-- =============================================================================
-- 406 — LE CATALOGUE DES CONTRÔLES BLANCS : 1re (allemand, anglais, arts-plastiques, biochimie-biologie, biologie-physiopathologie)
--
-- 363 sujets écrits d'avance et relus : pour chaque fiche, un sujet
-- Facile, un Moyen, un Difficile, chacun avec son barème sur 20 et son corrigé
-- type (`contenu.corrige`, jamais envoyé à l'élève avant sa copie). L'IA ne fait
-- plus que les corriger ; elle ne rédige que « Un autre sujet ».
--
-- ⚠️ FICHIER GÉNÉRÉ — ne pas éditer à la main. Source : contenu/controles/.
--    Regénérer : node node_modules/jiti/lib/jiti-cli.mjs scripts/controles-sql.ts --num 406 --niveau 1re --matieres allemand,anglais,arts-plastiques,biochimie-biologie,biologie-physiopathologie
--
--   allemand.jumelles           108 sujets · 36 fiches
--   allemand.n1                  36 sujets · 12 fiches
--   anglais.jumelles             72 sujets · 24 fiches
--   anglais.m1                   39 sujets · 13 fiches
--   arts-plastiques.jumelles      9 sujets · 3 fiches
--   biochimie-biologie.m1        24 sujets · 8 fiches
--   biochimie-biologie.n1a       27 sujets · 9 fiches
--   biologie-physiopathologie.n1a   24 sujets · 8 fiches
--   biologie-physiopathologie.n1b   24 sujets · 8 fiches
--
-- L'identifiant d'un sujet est dérivé de (fiche, niveau) : rejouer la migration
-- met le sujet à jour au lieu de le dupliquer. Une fiche absente est sautée.
--
-- PRÉREQUIS : 360 puis 364. Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

INSERT INTO public.chapter_exercices
  (id, chapter_id, style, contenu, difficulte, origine, created_by)
SELECT
  md5('exercice-catalogue:' || v.chapter_id::text || ':' || v.difficulte::text)::uuid,
  v.chapter_id,
  v.style,
  v.contenu,
  v.difficulte,
  'catalogue',
  NULL
FROM (VALUES
  ('32dc4dfc-0693-5ab3-951a-bb10799a7a49'::uuid, 1, 'traduction', $exo${"titre":"Conjuguer au présent","consigne":"Conjugue chaque verbe au présent, à la personne demandée, puis réponds à la question.","enonce":"**1. Conjugue** au présent :\n\na) *spielen* (du)\nb) *arbeiten* (er)\nc) *heißen* (du)\nd) *fahren* (er)\ne) *lesen* (du)\nf) *geben* (sie, elle)\ng) *sammeln* (ich)\nh) *finden* (ihr)\n\n**2.** Le changement de voyelle d’un verbe fort (*fahren → fährt*) touche-t-il aussi *wir* et *sie* (ils) ? Donne un exemple.","bareme":[{"critere":"Terminaisons régulières justes : spielst","points":2},{"critere":"Aménagements justes : arbeitet, heißt, sammle, findet","points":8},{"critere":"Verbes forts justes : fährt, liest, gibt","points":6},{"critere":"Réponse : changement aux 2e et 3e personnes du singulier seulement, avec exemple","points":4}],"dureeMin":7,"corrige":"**1.**\na) *du spielst*\nb) *er arbeitet* (radical en -t : on intercale un e)\nc) *du heißt* (radical en -ß : le -st perd son s)\nd) *er fährt* (verbe fort a → ä)\ne) *du liest* (e → ie ; radical en -s : -st perd son s)\nf) *sie gibt* (e → i)\ng) *ich sammle* (radical en -el : le e tombe à la 1re personne)\nh) *ihr findet* (radical en -d : on intercale un e)\n\n**2.** Non : le changement de voyelle ne touche que les **2e et 3e personnes du singulier**. Exemple : *du fährst, er fährt*, mais *wir fahren, sie fahren*."}$exo$::jsonb),
  ('32dc4dfc-0693-5ab3-951a-bb10799a7a49'::uuid, 2, 'traduction', $exo${"titre":"Lena se présente","consigne":"Complète la présentation de Lena au présent, puis traduis les deux phrases.","enonce":"**Situation.** Lena écrit à sa correspondante française.\n\n> Ich (1. heißen) Lena. Ich (2. lernen) seit drei Jahren Französisch. Mein Bruder Paul (3. lesen) jeden Abend und er (4. sprechen) gut Englisch. Meine Schwester (5. arbeiten) in Köln. Morgen (6. fahren) wir nach Berlin. Und du? (7. Schlafen) du am Wochenende lange?\n\n1. Écris les **sept verbes** conjugués.\n2. **Traduis** en allemand :\na) J’apprends l’allemand depuis deux ans.\nb) Demain, je vais à Munich (en train).\n3. Pourquoi n’utilise-t-on pas le futur dans la phrase b) ?","bareme":[{"critere":"Les sept formes justes : heiße, lerne, liest, spricht, arbeitet, fahren, Schläfst","points":10},{"critere":"Traduction a) au présent avec seit : Ich lerne seit zwei Jahren Deutsch","points":4},{"critere":"Traduction b) au présent, verbe en 2e position : Morgen fahre ich nach München","points":3},{"critere":"Explication : l’adverbe de temps suffit à dire l’avenir","points":3}],"dureeMin":10,"corrige":"**1.**\n1) *heiße*\n2) *lerne* (présent avec *seit*)\n3) *liest* (e → ie)\n4) *spricht* (e → i)\n5) *arbeitet* (e intercalé)\n6) *fahren* (pluriel : pas de changement de voyelle)\n7) *Schläfst* (a → ä)\n\n**2.**\na) *Ich lerne seit zwei Jahren Deutsch.* — avec *seit*, l’allemand emploie le **présent**, comme le français ; le parfait serait une faute.\nb) *Morgen fahre ich nach München.* — le verbe reste en **2e position**, le sujet passe derrière.\n\n**3.** Avec un adverbe de temps (*morgen*), le **présent suffit** à exprimer l’avenir et c’est la tournure la plus naturelle ; le futur en *werden* ne sert que sans repère temporel ou pour insister."}$exo$::jsonb),
  ('32dc4dfc-0693-5ab3-951a-bb10799a7a49'::uuid, 3, 'traduction', $exo${"titre":"Le courriel plein de fautes","consigne":"Corrige chaque faute en expliquant la règle, puis rédige un court message en allemand.","enonce":"**Document.** Courriel de Hugo, élève de 3e, à son correspondant.\n\n> Hallo Jonas! Ich habe seit zwei Jahren Deutsch gelernt. Mein Vater fahrt jeden Tag nach Paris. Du arbeitst viel, oder? Du heißst Jonas Müller, richtig? Meine Freunde und ich fähren oft ans Meer. Morgen ich spiele Fußball.\n\n1. Hugo a fait **six fautes**, une par phrase après *Hallo Jonas!*. Recopie chaque phrase **corrigée**.\n2. Pour chaque faute, **nomme la règle** en quelques mots.\n3. **Production** (5 lignes environ) : présente-toi à Jonas. Utilise au moins un verbe fort à la 2e ou 3e personne, une phrase avec *seit* et une phrase qui parle de demain au présent.","bareme":[{"critere":"Les six phrases corrigées : lerne seit, fährt, arbeitest, heißt, fahren, Morgen spiele ich","points":6},{"critere":"Règles nommées : seit + présent, verbe fort, e intercalé, s supprimé, pluriel sans inflexion, verbe en 2e position","points":6},{"critere":"Production : terminaisons et verbes forts justes","points":4},{"critere":"Production : seit + présent et avenir au présent avec adverbe, verbe en 2e position","points":4}],"dureeMin":17,"corrige":"**1 et 2.**\n- *Ich **lerne** seit zwei Jahren Deutsch.* — avec *seit*, on emploie le **présent**, pas le parfait.\n- *Mein Vater **fährt** jeden Tag nach Paris.* — *fahren* est un verbe fort : a → ä aux 2e et 3e personnes du singulier.\n- *Du **arbeitest** viel, oder?* — radical en -t : on intercale un **e**.\n- *Du **heißt** Jonas Müller, richtig?* — radical en -ß : le -st perd son **s**.\n- *Meine Freunde und ich **fahren** oft ans Meer.* — sujet *wir* : le changement de voyelle ne touche **pas** le pluriel.\n- ***Morgen spiele ich** Fußball.* — le verbe conjugué est en **2e position** ; l’adverbe de temps suffit à dire l’avenir.\n\n**3.** Exemple : *Hallo Jonas! Ich heiße Hugo und ich lerne seit vier Jahren Deutsch. Mein Bruder liest viel und er spricht Spanisch. Meine Mutter fährt jeden Tag zur Arbeit. Morgen spiele ich Tennis.* Le correcteur vérifie les terminaisons, un verbe fort bien conjugué, *seit* + présent et un avenir au présent avec le verbe en 2e position."}$exo$::jsonb),
  ('4d832393-b954-54b8-a4f0-aac5fec9be08'::uuid, 1, 'traduction', $exo${"titre":"Les formes du prétérit","consigne":"Donne la forme du prétérit, puis indique la famille de chaque verbe.","enonce":"**1. Mets au prétérit** :\n\na) *spielen* (ich)\nb) *gehen* (er)\nc) *kommen* (sie, elle)\nd) *sein* (ich)\ne) *haben* (er)\nf) *können* (wir)\ng) *bringen* (er)\nh) *nehmen* (ich)\n\n**2.** Pour *spielen*, *gehen* et *bringen*, indique la **famille** (faible, fort, mixte) et explique comment se forme leur prétérit.","bareme":[{"critere":"Les huit formes justes : spielte, ging, kam, war, hatte, konnten, brachte, nahm","points":12},{"critere":"Familles justes : spielen faible, gehen fort, bringen mixte","points":4},{"critere":"Formation expliquée : -te ; voyelle changée sans terminaison ; radical modifié + -te","points":4}],"dureeMin":7,"corrige":"**1.**\na) *ich spielte*\nb) *er ging*\nc) *sie kam*\nd) *ich war*\ne) *er hatte*\nf) *wir konnten* (modal : pas d’inflexion au prétérit)\ng) *er brachte*\nh) *ich nahm*\n\nAux 1re et 3e personnes du singulier, les formes sont identiques (*ich ging / er ging*).\n\n**2.**\n- *spielen* : verbe **faible** → radical + **-te** + terminaisons (*spielte*).\n- *gehen* : verbe **fort** → voyelle changée, **aucune terminaison** aux 1re et 3e personnes (*ging*).\n- *bringen* : verbe **mixte** → radical modifié + terminaisons faibles (*brachte*)."}$exo$::jsonb),
  ('4d832393-b954-54b8-a4f0-aac5fec9be08'::uuid, 2, 'traduction', $exo${"titre":"Le samedi de Max","consigne":"Réécris le récit au prétérit, complète la phrase au plus-que-parfait, puis explique ton choix.","enonce":"**Situation.** Pour le journal du collège, tu dois raconter le samedi de Max. Voici tes notes, au présent :\n\n> Am Samstag geht Max in die Stadt. Er sieht seinen Freund Tim. Sie trinken einen Kaffee und sprechen lange. Dann kauft Max ein Buch. Am Abend schreibt er seiner Oma. Er ist sehr zufrieden.\n\n1. **Réécris** le récit au **prétérit**.\n2. Complète au plus-que-parfait : *Nachdem Max das Buch gekauft (…), ging er nach Hause.*\n3. Pourquoi faut-il employer le prétérit, et non le parfait, dans un article de journal ?","bareme":[{"critere":"Formes fortes justes : ging, sah, tranken, sprachen, schrieb, war","points":9},{"critere":"Forme faible juste : kaufte ; terminaisons du pluriel justes","points":3},{"critere":"Plus-que-parfait juste : hatte","points":3},{"critere":"Explication : prétérit = temps du récit écrit ; parfait = oral et lettre","points":5}],"dureeMin":11,"corrige":"**1.** *Am Samstag **ging** Max in die Stadt. Er **sah** seinen Freund Tim. Sie **tranken** einen Kaffee und **sprachen** lange. Dann **kaufte** Max ein Buch. Am Abend **schrieb** er seiner Oma. Er **war** sehr zufrieden.*\n\n- *gehen → ging*, *sehen → sah*, *trinken → trank* (pluriel *tranken*), *sprechen → sprach* (*sprachen*), *schreiben → schrieb* : verbes forts.\n- *kaufen → kaufte* : verbe faible.\n- *sein → war*.\n\n**2.** *Nachdem Max das Buch gekauft **hatte**, ging er nach Hause.* — prétérit de *haben* + participe II : l’achat est **antérieur** au retour.\n\n**3.** Un article de journal est un **texte narratif écrit** : on y raconte au **prétérit**. Le parfait est le passé de l’oral et de la lettre ; mélanger les deux dans un même récit fait désordre."}$exo$::jsonb),
  ('4d832393-b954-54b8-a4f0-aac5fec9be08'::uuid, 3, 'traduction', $exo${"titre":"Une journée d’hiver","consigne":"Conjugue le récit, traduis, puis justifie les choix de temps avec les règles du cours.","enonce":"**Document.** Début d’une nouvelle, verbes à l’infinitif.\n\n> Es (1. sein) kalt. Anna (2. bleiben) zu Hause und (3. schreiben) einen Brief. Nachdem sie den Brief geschrieben (4. haben), (5. gehen) sie zur Post. Dort (6. finden) sie ihren Freund Paul. Er (7. wollen) einen Kaffee trinken. Sie (8. trinken) zusammen einen Kaffee und (9. denken) an die Ferien.\n\n1. Conjugue les **neuf verbes** : prétérit partout, plus-que-parfait pour (4).\n2. **Traduis** en allemand, pour la suite de la nouvelle : *Il faisait nuit et Anna était fatiguée. Elle ne pouvait pas dormir.*\n3. Pourquoi l’imparfait français devient-il ici un prétérit ? Aurait-on dit la même chose dans un dialogue ?\n4. À l’oral, Anna dit *Ich bin müde gewesen*. Est-ce faux ? Que dirait-on plutôt ?","bareme":[{"critere":"Formes justes : war, blieb, schrieb, ging, fand, wollte, tranken, dachten","points":6},{"critere":"Plus-que-parfait juste (hatte) et antériorité expliquée","points":3},{"critere":"Traduction juste : Es war dunkel (Nacht) und Anna war müde. Sie konnte nicht schlafen","points":5},{"critere":"Règle de registre : prétérit dans un récit écrit, parfait dans un dialogue","points":4},{"critere":"Ich war müde, ce que tout le monde dit (sein survit au prétérit à l’oral)","points":2}],"dureeMin":17,"corrige":"**1.** *Es **war** kalt. Anna **blieb** zu Hause und **schrieb** einen Brief. Nachdem sie den Brief geschrieben **hatte**, **ging** sie zur Post. Dort **fand** sie ihren Freund Paul. Er **wollte** einen Kaffee trinken. Sie **tranken** zusammen einen Kaffee und **dachten** an die Ferien.*\n\n(*denken → dachte* est un verbe mixte ; *wollen → wollte* un modal ; le plus-que-parfait *hatte geschrieben* marque ce qui s’est passé **avant** le départ pour la poste.)\n\n**2.** *Es war Nacht (Es war dunkel) und Anna war müde. Sie konnte nicht schlafen.* — *sein → war*, *können → konnte*.\n\n**3.** L’allemand oppose parfait et prétérit par le **registre**, pas par l’aspect : dans un **récit écrit**, tout passé se dit au prétérit, y compris ce que le français met à l’imparfait. Dans un **dialogue**, on aurait employé le **parfait** (sauf pour *sein, haben, werden* et les modaux).\n\n**4.** Ce n’est pas faux, mais tout le monde dit ***Ich war müde*** : *sein*, *haben*, *werden* et les modaux restent au prétérit même à l’oral."}$exo$::jsonb),
  ('282abce4-b26a-5ad2-a3cb-da690749272e'::uuid, 1, 'traduction', $exo${"titre":"Participes et auxiliaires","consigne":"Forme le participe II de chaque verbe, puis choisis l’auxiliaire.","enonce":"**1. Donne le participe II** :\n\na) *spielen* · b) *machen* · c) *sehen* · d) *fahren* · e) *studieren* · f) *besuchen* · g) *einkaufen* · h) *aufstehen*\n\n**2. Choisis l’auxiliaire** (*haben* ou *sein*) et complète :\n\na) Ich … nach Hause gegangen.\nb) Wir … Pizza gegessen.\nc) Er … sofort eingeschlafen.\nd) Sie … zu Hause geblieben.\ne) Ihr … Fußball gespielt.\nf) Was … passiert?","bareme":[{"critere":"Participes justes : gespielt, gemacht, gesehen, gefahren, studiert, besucht, eingekauft, aufgestanden","points":10},{"critere":"Auxiliaires justes : bin, haben, ist, ist, habt, ist","points":10}],"dureeMin":8,"corrige":"**1.**\na) *gespielt* · b) *gemacht* (faibles : ge- + radical + -t)\nc) *gesehen* · d) *gefahren* (forts : ge- + radical + -en)\ne) *studiert* (en -ieren : pas de ge-)\nf) *besucht* (préverbe inséparable : pas de ge-)\ng) *eingekauft* · h) *aufgestanden* (préverbe séparable : le ge- s’intercale)\n\n**2.**\na) Ich **bin** nach Hause gegangen. (déplacement)\nb) Wir **haben** Pizza gegessen.\nc) Er **ist** sofort eingeschlafen. (changement d’état)\nd) Sie **ist** (ou **sind**) zu Hause geblieben. (*bleiben* prend sein)\ne) Ihr **habt** Fußball gespielt.\nf) Was **ist** passiert? (*passieren* prend sein)"}$exo$::jsonb),
  ('282abce4-b26a-5ad2-a3cb-da690749272e'::uuid, 2, 'traduction', $exo${"titre":"Le week-end de Jonas","consigne":"Mets le message de Jonas au parfait, en respectant l’ordre des mots, puis complète la subordonnée.","enonce":"**Situation.** Jonas raconte son week-end à son ami Ben, dans un message. Ses notes sont au présent :\n\n> Am Samstag stehe ich um 9 Uhr auf. Dann fahre ich mit dem Zug nach Hamburg. Dort besuche ich meine Oma. Wir essen Kuchen und spielen Karten. Am Abend bleibe ich bei ihr.\n\n1. **Réécris** le message au **parfait**.\n2. Complète au parfait : *Ich bin müde, weil ich viel (lernen).*\n3. Pourquoi Jonas raconte-t-il au parfait et pas au prétérit ?","bareme":[{"critere":"Auxiliaires justes : bin aufgestanden, bin gefahren, bin geblieben ; habe besucht, haben gegessen/gespielt","points":8},{"critere":"Participes justes (aufgestanden, gefahren, besucht, gegessen, gespielt, geblieben)","points":5},{"critere":"Participe en fin de phrase, auxiliaire en 2e position ; subordonnée : gelernt habe","points":4},{"critere":"Explication : le parfait est le passé de la conversation et du message","points":3}],"dureeMin":11,"corrige":"**1.** *Am Samstag **bin** ich um 9 Uhr **aufgestanden**. Dann **bin** ich mit dem Zug nach Hamburg **gefahren**. Dort **habe** ich meine Oma **besucht**. Wir **haben** Kuchen **gegessen** und Karten **gespielt**. Am Abend **bin** ich bei ihr **geblieben**.*\n\n- *aufstehen* (changement d’état), *fahren* (déplacement), *bleiben* → **sein**.\n- *besuchen* : inséparable, pas de ge- ; *aufstehen* : séparable, ge- intercalé.\n- Auxiliaire en **2e position**, participe **à la fin**.\n\n**2.** *Ich bin müde, weil ich viel **gelernt habe**.* — en subordonnée, l’auxiliaire va **à la toute fin**, après le participe.\n\n**3.** Un message à un ami, c’est de la **conversation** écrite : on raconte au **parfait**. Le prétérit est le temps du récit écrit (roman, presse)."}$exo$::jsonb),
  ('282abce4-b26a-5ad2-a3cb-da690749272e'::uuid, 3, 'traduction', $exo${"titre":"La copie à corriger","consigne":"Repère les phrases fausses et corrige-les en citant la règle, puis traduis et explique.","enonce":"**Document.** Sept phrases tirées de la copie de Léo.\n\n> a) Ich habe nach Berlin gefahren.\n> b) Er hat mit seiner Oma getelefoniert.\n> c) Wir haben im Supermarkt geeinkauft.\n> d) Ich habe das Auto in die Garage gefahren.\n> e) Ich bin müde, weil ich habe den ganzen Tag gearbeitet.\n> f) Was ist gestern passiert?\n> g) Sie hat früh eingeschlafen.\n\n1. **Deux** phrases sont justes : lesquelles ? Justifie.\n2. **Corrige** les cinq autres en citant la règle.\n3. **Traduis**, pour un message à un ami : *Hier, je suis resté à la maison et j’ai lu un livre. Ma sœur s’est endormie tôt.*\n4. *Il pleuvait* se traduit-il de la même façon dans un dialogue et dans un roman ? Explique.","bareme":[{"critere":"Phrases justes identifiées (d et f) et justifiées : emploi transitif ; passieren prend sein","points":4},{"critere":"Corrections : bin gefahren, telefoniert, eingekauft, gearbeitet habe, ist eingeschlafen","points":6},{"critere":"Traduction juste : bin geblieben, habe gelesen, ist eingeschlafen, participes en fin","points":6},{"critere":"Registre expliqué : parfait dans un dialogue, prétérit dans un roman","points":4}],"dureeMin":17,"corrige":"**1.** **d)** est juste : *fahren* est employé **transitivement** (il a un complément, *das Auto*), il prend donc **haben**. **f)** est juste : *passieren* fait partie des six verbes à part qui prennent **sein**.\n\n**2.**\na) *Ich **bin** nach Berlin gefahren.* — déplacement d’un point à un autre : **sein**.\nb) *Er hat mit seiner Oma **telefoniert**.* — verbe en -ieren : **pas de ge-**.\nc) *Wir haben im Supermarkt **eingekauft**.* — préverbe séparable : le ge- **s’intercale**.\ne) *…, weil ich den ganzen Tag **gearbeitet habe**.* — en subordonnée, l’auxiliaire va **à la toute fin**.\ng) *Sie **ist** früh eingeschlafen.* — changement d’état : **sein**.\n\n**3.** *Gestern bin ich zu Hause geblieben und habe ein Buch gelesen. Meine Schwester ist früh eingeschlafen.* — *bleiben* et *einschlafen* prennent sein ; *lesen* (fort) donne *gelesen*.\n\n**4.** Non. L’allemand distingue parfait et prétérit par le **registre** : dans un **dialogue**, *Es hat geregnet* (parfait) ; dans un **roman**, *Es regnete* (prétérit). Le français, lui, oppose imparfait et passé composé par l’**aspect**."}$exo$::jsonb),
  ('b5820f20-5732-5ef4-a998-6b7efeb0a9b8'::uuid, 1, 'traduction', $exo${"titre":"Werden au futur","consigne":"Mets les phrases au Futur I, puis indique ce qu’exprime werden dans chaque phrase de la partie 2.","enonce":"**1. Mets au Futur I** :\n\na) Ich helfe dir.\nb) Du kommst nicht.\nc) Er schreibt einen Brief.\nd) Wir spielen Fußball.\ne) Ihr lernt viel.\nf) Sie (ils) fahren nach Wien.\n\n**2.** Que signifie *werden* dans chaque phrase : « devenir », futur ou passif ?\n\na) *Er wird Arzt.*\nb) *Das Haus wird gebaut.*\nc) *Er wird kommen.*","bareme":[{"critere":"Formes de werden justes : werde, wirst, wird, werden, werdet, werden","points":6},{"critere":"Infinitif placé en fin de phrase dans les six phrases","points":6},{"critere":"Les trois valeurs identifiées d’après ce qui suit werden","points":8}],"dureeMin":7,"corrige":"**1.**\na) *Ich **werde** dir **helfen**.*\nb) *Du **wirst** nicht **kommen**.*\nc) *Er **wird** einen Brief **schreiben**.*\nd) *Wir **werden** Fußball **spielen**.*\ne) *Ihr **werdet** viel **lernen**.*\nf) *Sie **werden** nach Wien **fahren**.*\n\n*werden* conjugué en 2e position, **infinitif à la fin**.\n\n**2.** C’est ce qui **suit** *werden* qui tranche :\na) un **nom** → « **devenir** » : il devient médecin.\nb) un **participe II** → **passif** : la maison est construite.\nc) un **infinitif** → **futur** : il viendra."}$exo$::jsonb),
  ('b5820f20-5732-5ef4-a998-6b7efeb0a9b8'::uuid, 2, 'traduction', $exo${"titre":"Les projets d’Emma","consigne":"Choisis entre présent et futur, justifie, puis traite la subordonnée et la supposition.","enonce":"**Situation.** Emma écrit à son amie Clara.\n\n> a) Morgen (fahren) ich nach Hamburg.\n> b) Keine Sorge, ich (helfen) dir! (une promesse, sans repère de temps)\n> c) Die Prüfung (sein) nicht einfach. (une prédiction)\n> d) Nächste Woche (schreiben) ich die Mathearbeit.\n\n1. Pour chaque phrase, choisis **présent** ou **Futur I**, conjugue et justifie.\n2. Complète au futur : *Ich hoffe, dass Tim (kommen).*\n3. Clara répond : *« Tim antwortet nicht. Er wird wohl krank sein. »* Traduis la seconde phrase et explique le piège.","bareme":[{"critere":"a) fahre et d) schreibe au présent, justifiés par l’adverbe de temps","points":5},{"critere":"b) werde helfen et c) wird sein au futur, justifiés (promesse, prédiction)","points":5},{"critere":"Subordonnée juste : dass Tim kommen wird (werden à la fin)","points":4},{"critere":"Supposition traduite : Il doit être malade ; ce n’est pas un futur","points":6}],"dureeMin":11,"corrige":"**1.**\na) *Morgen **fahre** ich nach Hamburg.* — **présent** : l’adverbe *morgen* suffit à dire l’avenir.\nb) *Ich **werde** dir **helfen**!* — **futur** : une promesse, sans repère de temps.\nc) *Die Prüfung **wird** nicht einfach **sein**.* — **futur** : une prédiction.\nd) *Nächste Woche **schreibe** ich die Mathearbeit.* — **présent** : *nächste Woche* précise l’avenir.\n(Le futur en a et d n’est pas faux, seulement plus lourd.)\n\n**2.** *Ich hoffe, dass Tim kommen **wird**.* — en subordonnée, les deux morceaux se rejoignent à la fin et c’est *werden* qui ferme.\n\n**3.** *« Il **doit** être malade. »* Ce futur renforcé par *wohl* exprime une **hypothèse sur le présent**, pas l’avenir ; traduire « il sera malade » est un contresens."}$exo$::jsonb),
  ('b5820f20-5732-5ef4-a998-6b7efeb0a9b8'::uuid, 3, 'traduction', $exo${"titre":"Les mille visages de werden","consigne":"Analyse et traduis chaque phrase, transforme la subordonnée, puis rédige tes projets.","enonce":"**1. Analyse et traduis** : pour chaque phrase, dis ce qu’exprime *werden* (devenir, futur, passif, supposition, insistance), puis traduis.\n\na) *Sie wird Lehrerin.*\nb) *Die Stadt wird renoviert.*\nc) *Er wird wohl zu Hause sein.*\nd) *Er wird es vergessen haben.*\ne) *Du wirst jetzt aufräumen!*\nf) *Das wird nicht einfach sein.*\n\n**2. Transforme** en subordonnée introduite par *dass* : *Ich glaube: Er wird morgen kommen.*\n\n**3. Production** (5 lignes environ) : écris tes projets pour les prochaines vacances. Emploie au moins **deux** fois le présent avec un adverbe de temps, et **deux** fois le Futur I (une promesse, une prédiction).","bareme":[{"critere":"Valeurs identifiées d’après ce qui suit werden (devenir, passif, supposition, Futur II, insistance, prédiction)","points":6},{"critere":"Traductions justes, sans contresens sur c) et d)","points":5},{"critere":"Subordonnée juste : dass er morgen kommen wird","points":3},{"critere":"Production : présent avec adverbe et Futur I bien formé (werden + infinitif final)","points":6}],"dureeMin":17,"corrige":"**1.**\na) Nom après *werden* → **devenir** : *Elle devient professeure.*\nb) Participe II → **passif** : *La ville est rénovée.*\nc) Futur + *wohl* → **supposition** sur le présent : *Il doit être à la maison.*\nd) Futur II → **supposition** sur le passé : *Il a dû l’oublier.*\ne) Futur → **insistance**, presque une menace : *Tu vas ranger, maintenant !*\nf) Futur → **prédiction** : *Ça ne sera pas facile.*\n\n**2.** *Ich glaube, dass er morgen kommen **wird**.* — *werden* conjugué ferme la subordonnée, après l’infinitif.\n\n**3.** Exemple : *Nächsten Sommer fahre ich nach Österreich. Am ersten Tag besuche ich Wien. Ich werde dir jeden Tag schreiben, versprochen! Das wird bestimmt toll sein.* Le correcteur vérifie le présent avec *nächsten Sommer, morgen…*, le verbe en 2e position, et deux Futur I justes (*werde… schreiben*, *wird… sein*), infinitif en fin de phrase."}$exo$::jsonb),
  ('0b9f5664-57dc-5b0f-8f78-194c6cbb76ab'::uuid, 1, 'traduction', $exo${"titre":"Donner un ordre à chacun","consigne":"Forme l’impératif demandé, sans oublier le pronom quand il le faut.","enonce":"**1. Forme l’impératif** de *kommen* pour **du**, **ihr** et **Sie**.\n\n**2. Forme l’impératif** pour **du** :\n\na) *geben* (mir das Buch)\nb) *fahren* (langsam)\nc) *arbeiten* (mehr)\nd) *lesen* (den Text)\ne) *nehmen* (den Bus)\n\n**3.** Donne l’impératif de *sein* (*ruhig sein*) pour **du**, **ihr** et **Sie**.","bareme":[{"critere":"kommen juste : Komm! Kommt! Kommen Sie!","points":5},{"critere":"Formes du juste : Gib! Fahr! Arbeite! Lies! Nimm!","points":10},{"critere":"sein juste : Sei ruhig! Seid ruhig! Seien Sie ruhig!","points":5}],"dureeMin":7,"corrige":"**1.** *Komm!* (du : radical, sans terminaison ni pronom) · *Kommt!* (ihr : forme du présent, sans pronom) · *Kommen Sie!* (Sie : infinitif + pronom).\n\n**2.**\na) *Gib mir das Buch!* — l’alternance e → i se **garde**.\nb) *Fahr langsam!* — l’alternance a → ä se **perd** (pas « Fähr »).\nc) *Arbeite mehr!* — le -e final est **obligatoire** après -t.\nd) *Lies den Text!* — e → ie gardé.\ne) *Nimm den Bus!* — e → i gardé.\n\n**3.** *Sei ruhig!* · *Seid ruhig!* · *Seien Sie ruhig!* — *sein* est à part."}$exo$::jsonb),
  ('0b9f5664-57dc-5b0f-8f78-194c6cbb76ab'::uuid, 2, 'traduction', $exo${"titre":"Le départ en classe verte","consigne":"Transforme chaque consigne en impératif, à la personne indiquée, en ajoutant bitte quand c’est demandé.","enonce":"**Situation.** Le jour du départ en classe verte, Frau Keller, la professeure, et les élèves se donnent des consignes.\n\n1. À ton camarade Paul (**du**) :\na) *aufstehen* (+ bitte)\nb) *mich heute Abend anrufen*\nc) *langsam fahren* (à vélo)\n\n2. À toute la classe (**ihr**) :\nd) *leise sein*\ne) *die Koffer nehmen*\n\n3. À Frau Keller (**Sie**) :\nf) *die Tür zumachen* (+ bitte)\n\n4. À tout le groupe, toi compris (**wir**) :\ng) *gehen*\n\n5. Où se place le préverbe séparable à l’impératif ? Appuie-toi sur a), b) et f).","bareme":[{"critere":"Formes du justes : Steh bitte auf! Ruf mich heute Abend an! Fahr langsam!","points":6},{"critere":"Formes ihr justes : Seid leise! Nehmt die Koffer!","points":4},{"critere":"Formes Sie et wir justes : Machen Sie bitte die Tür zu! Gehen wir!","points":4},{"critere":"Règle : verbe en 1re position, préverbe séparable rejeté à la fin","points":6}],"dureeMin":11,"corrige":"**1.**\na) *Steh bitte auf!*\nb) *Ruf mich heute Abend an!*\nc) *Fahr langsam!* (a → ä se perd)\n\n**2.**\nd) *Seid leise!* (*sein* est à part)\ne) *Nehmt die Koffer!* (forme du présent, sans pronom)\n\n**3.**\nf) *Machen Sie bitte die Tür zu!* (infinitif + *Sie*)\n\n**4.**\ng) *Gehen wir!* (« allons-y »)\n\n**5.** Le verbe **ouvre** la phrase, en première position, et le préverbe séparable (*auf*, *an*, *zu*) part **à la fin** de la phrase. *bitte* se place juste après le verbe (ou le pronom *Sie*)."}$exo$::jsonb),
  ('0b9f5664-57dc-5b0f-8f78-194c6cbb76ab'::uuid, 3, 'traduction', $exo${"titre":"Ordres secs, ordres polis","consigne":"Adoucis, corrige et analyse les ordres, en justifiant avec les règles du cours.","enonce":"**Document 1.** Mot laissé par Anna à son frère Tom :\n\n> Mach das Fenster zu! Räum dein Zimmer auf! Gib mir mein Buch!\n\n**Document 2.** Cinq ordres écrits par un élève :\n\n> a) Fähr langsam! · b) Gebe mir das! · c) Arbeit! · d) Kommst du! · e) Sei ruhig, Herr Braun!\n\n1. Tom trouve le mot d’Anna **hostile**. Explique pourquoi, puis **réécris-le** avec *bitte*, *mal* ou *doch* (une particule différente par phrase).\n2. **Corrige** les cinq ordres du document 2 en expliquant chaque faute.\n3. Anna veut demander à sa voisine, Frau Schulz, de l’aider, le plus poliment possible. Écris la phrase.\n4. Quel est le registre de *Nicht rauchen!* et de *Du wirst jetzt lernen!* ?","bareme":[{"critere":"Explication : sans particules un impératif paraît sec ; trois phrases adoucies justes","points":5},{"critere":"Corrections : Fahr! Gib mir das! Arbeite! Komm! Seien Sie ruhig, Herr Braun!","points":7},{"critere":"Demande très polie juste : Könnten Sie mir helfen?","points":4},{"critere":"Registres : infinitif = panneaux, consignes ; futur = menaçant","points":4}],"dureeMin":16,"corrige":"**1.** Sans les petits mots *bitte, mal, doch*, un impératif allemand paraît **sec**, parfois hostile. Réécriture possible : *Mach bitte das Fenster zu! Räum doch dein Zimmer auf! Gib mir mal mein Buch!* — *bitte* ajoute la politesse, *doch* l’insistance amicale, *mal* la légèreté.\n\n**2.**\na) ***Fahr** langsam!* — l’alternance a → ä se **perd** à l’impératif.\nb) ***Gib** mir das!* — l’alternance e → i se **garde**.\nc) ***Arbeite**!* — -e final **obligatoire** après -t.\nd) ***Komm**!* — pour *du* : radical sans terminaison, **sans pronom**.\ne) ***Seien Sie** ruhig, Herr Braun!* — on vouvoie un adulte : forme *Sie*, avec le pronom ; *sein* est à part.\n\n**3.** *Könnten Sie mir bitte helfen, Frau Schulz?* — la question au **subjonctif II** est le registre **très poli**.\n\n**4.** *Nicht rauchen!* : l’infinitif seul, registre des **panneaux et consignes**. *Du wirst jetzt lernen!* : le futur, registre **menaçant**."}$exo$::jsonb),
  ('72b1d366-a38c-5b17-b988-95c1126e18a3'::uuid, 1, 'traduction', $exo${"titre":"Wäre, hätte, würde","consigne":"Donne la forme de subjonctif II, puis mets les phrases au subjonctif II.","enonce":"**1. Donne le subjonctif II** (1re personne du singulier) de :\n\na) *sein* · b) *haben* · c) *können* · d) *müssen* · e) *wissen* · f) *mögen* · g) *werden*\n\n**2. Mets au subjonctif II** avec *würde* + infinitif :\n\na) Ich fahre gern nach Berlin.\nb) Wir spielen gern Tennis.\n\n**3.** À partir de quel temps se forment les formes simples ? Donne un exemple.","bareme":[{"critere":"Les sept formes justes : wäre, hätte, könnte, müsste, wüsste, möchte, würde","points":10},{"critere":"würde + infinitif final juste dans les deux phrases","points":6},{"critere":"Formation expliquée : prétérit + inflexion + -e, avec exemple","points":4}],"dureeMin":7,"corrige":"**1.**\na) *wäre* · b) *hätte* · c) *könnte* · d) *müsste* · e) *wüsste* · f) *möchte* · g) *würde*\n\n**2.**\na) *Ich **würde** gern nach Berlin **fahren**.*\nb) *Wir **würden** gern Tennis **spielen**.*\n*würde* est la construction **par défaut** pour la plupart des verbes ; l’infinitif va à la fin.\n\n**3.** Les formes simples se forment sur le **prétérit**, avec **inflexion** et un *-e* : *war → wäre*, *hatte → hätte*, *konnte → könnte*."}$exo$::jsonb),
  ('72b1d366-a38c-5b17-b988-95c1126e18a3'::uuid, 2, 'traduction', $exo${"titre":"Au café, et si…","consigne":"Rends les demandes polies, puis transforme les faits en hypothèses irréelles.","enonce":"**Situation.** Au café, à Munich, Jules parle trop sèchement au serveur.\n\n1. Rends chaque phrase **polie** avec le subjonctif II :\na) *Ich will einen Kaffee.*\nb) *Können Sie mir helfen?*\nc) *Ich will zahlen.*\n\n2. En sortant, Jules se plaint. **Transforme** chaque paire de phrases en une hypothèse irréelle avec *wenn* :\nd) *Ich habe keine Zeit. Ich komme nicht mit.*\ne) *Das Wetter ist schlecht. Wir gehen nicht schwimmen.*\nf) *Ich habe kein Geld. Ich kaufe das Fahrrad nicht.*\n\n3. Pourquoi *Ich will einen Kaffee* est-il maladroit ?","bareme":[{"critere":"Demandes polies : Ich hätte gern einen Kaffee ; Könnten Sie mir helfen? ; Ich möchte bitte zahlen","points":6},{"critere":"Subordonnées justes : wenn + subjonctif II, verbe à la fin (hätte, wäre)","points":5},{"critere":"Principales justes : würde + infinitif, verbe en tête après la subordonnée","points":5},{"critere":"Explication : le présent de wollen sonne comme un ordre","points":4}],"dureeMin":11,"corrige":"**1.**\na) *Ich **hätte** gern einen Kaffee.* (ou *Ich **möchte** einen Kaffee.*)\nb) ***Könnten** Sie mir helfen?*\nc) *Ich **möchte** bitte zahlen.*\nPour la politesse, on préfère la **forme simple**.\n\n**2.**\nd) *Wenn ich Zeit **hätte**, **würde** ich **mitkommen**.*\ne) *Wenn das Wetter schön **wäre**, **würden** wir schwimmen **gehen**.* (ou *nicht schlecht wäre*)\nf) *Wenn ich Geld **hätte**, **würde** ich das Fahrrad **kaufen**.*\nDans la subordonnée, le verbe conjugué est **à la fin** ; la principale commence par le verbe (*würde*).\n\n**3.** *Ich will einen Kaffee* sonne comme un **ordre** ; *Ich hätte gern einen Kaffee* comme une **demande**. Le subjonctif II est la forme quotidienne de la politesse."}$exo$::jsonb),
  ('72b1d366-a38c-5b17-b988-95c1126e18a3'::uuid, 3, 'traduction', $exo${"titre":"Si j’avais une année libre","consigne":"Transforme, complète, identifie les modes, puis rédige un paragraphe à l’irréel.","enonce":"**1. Supprime** *wenn* dans ces phrases, sans changer leur sens :\na) *Wenn ich Zeit hätte, würde ich kommen.*\nb) *Wenn das Wetter schön wäre, würden wir wandern.*\n\n**2. Complète** avec le subjonctif II :\nc) *Er tut so, als ob er alles (wissen).*\nd) *Sie spricht, als ob sie Deutsche (sein).*\ne) Ton ami est toujours fatigué. Donne-lui un **conseil** : *Du (sollen) mehr schlafen.*\n\n**3.** Dans un journal, tu lis : *Der Minister sagte, er sei krank.* Quel est le mode de *sei* ? À quoi sert-il ?\n\n**4. Production** (5 lignes environ) : *Wenn ich ein Jahr frei hätte…* Raconte ce que tu ferais. Emploie au moins **quatre** subjonctifs II (dont une forme simple et *würde*) et une phrase sans *wenn*.","bareme":[{"critere":"Phrases sans wenn justes : Hätte ich Zeit, würde ich kommen ; Wäre das Wetter schön, würden wir wandern","points":4},{"critere":"Formes justes : wüsste, wäre, solltest","points":4},{"critere":"Subjonctif I reconnu : discours indirect de la presse","points":3},{"critere":"Production : quatre subjonctifs II justes (forme simple et würde), verbe à la fin après wenn","points":6},{"critere":"Production : une phrase sans wenn, verbe en première place","points":3}],"dureeMin":17,"corrige":"**1.**\na) ***Hätte** ich Zeit, würde ich kommen.*\nb) ***Wäre** das Wetter schön, würden wir wandern.*\nQuand *wenn* disparaît, le verbe prend la **première place** : tournure élégante, valorisée à l’écrit.\n\n**2.**\nc) *…, als ob er alles **wüsste**.* — après *als ob*, le subjonctif II est de règle.\nd) *…, als ob sie Deutsche **wäre**.*\ne) *Du **solltest** mehr schlafen.* — *solltest* exprime le **conseil**.\n\n**3.** *sei* est un **subjonctif I** : il sert au **discours indirect de la presse** (on rapporte les paroles du ministre sans les prendre à son compte). Il suffit de le reconnaître.\n\n**4.** Exemple : *Wenn ich ein Jahr frei hätte, würde ich um die Welt reisen. Ich würde zuerst nach Kanada fliegen. Dort könnte ich Englisch lernen. Hätte ich genug Geld, würde ich auch Japan besuchen. Das wäre toll!* Le correcteur vérifie au moins une forme simple (*hätte, wäre, könnte…*), *würde* + infinitif final, le verbe à la fin après *wenn*, et une phrase sans *wenn* avec le verbe en tête."}$exo$::jsonb),
  ('36b32493-08a1-5bee-962e-a56d20b1e5ea'::uuid, 1, 'traduction', $exo${"titre":"Cinq phrases à ponctuer","consigne":"Recopie chaque phrase en plaçant les virgules là où l'allemand les exige, puis réponds à la question 2.","enonce":"**1. Recopie en ajoutant les virgules nécessaires.**\n\n1. Ich weiß dass du morgen kommst.\n2. Er ist müde aber glücklich.\n3. Ich kaufe Brot Milch und Käse.\n4. Sie lernt Deutsch um in Wien zu studieren.\n5. Das Buch das ich lese ist spannend.\n\n**2.** Dans la phrase 3, explique en une phrase pourquoi on ne met pas de virgule devant *und*.","bareme":[{"critere":"Virgules justes devant dass, aber et um… zu (phrases 1, 2, 4)","points":9},{"critere":"Relative enchâssée encadrée de deux virgules (phrase 5)","points":4},{"critere":"Énumération de la phrase 3 sans virgule devant und","points":3},{"critere":"Explication juste de l'absence de virgule devant und","points":4}],"dureeMin":6,"corrige":"**1. Phrases corrigées**\n\n1. *Ich weiß, dass du morgen kommst.* — virgule obligatoire devant une subordonnée.\n2. *Er ist müde, aber glücklich.* — virgule devant *aber*.\n3. *Ich kaufe Brot, Milch und Käse.* — virgule entre Brot et Milch, **pas** devant *und*.\n4. *Sie lernt Deutsch, um in Wien zu studieren.* — le groupe *um… zu* exige la virgule.\n5. *Das Buch, das ich lese, ist spannend.* — la relative enchâssée est encadrée des **deux** côtés.\n\n**2.** En allemand, la virgule marque une frontière grammaticale : *und* relie deux éléments de même rang dans une énumération, et en principe on ne met pas de virgule devant *und* (ni devant *oder*)."}$exo$::jsonb),
  ('36b32493-08a1-5bee-962e-a56d20b1e5ea'::uuid, 2, 'traduction', $exo${"titre":"Le message de Léa à corriger","consigne":"Léa a écrit ce message sans respecter l'orthographe allemande. Recopie-le en corrigeant les majuscules, la ponctuation, les guillemets et les s / ß, puis réponds à la question 2.","enonce":"**1. Recopie le texte corrigé.**\n\n> gestern habe ich im park meinen freund tom getroffen. er sagt „ich komme morgen mit.“ ich hoffe dass er pünktlich ist. wir wollen die strasse entlang bis zum fluß laufen.\n\n**2.** Explique en français pourquoi on écrit *Straße* avec ß, mais *Fluss* avec ss.","bareme":[{"critere":"Majuscules aux noms communs (Park, Freund, Straße, Fluss) et en début de phrase","points":6},{"critere":"Deux-points avant le discours direct et guillemets allemands conservés","points":4},{"critere":"Virgule devant la subordonnée en dass","points":3},{"critere":"Graphies Straße et Fluss corrigées","points":3},{"critere":"Explication juste : ß après voyelle longue, ss après voyelle brève","points":4}],"dureeMin":10,"corrige":"**1. Texte corrigé**\n\n> *Gestern habe ich im Park meinen Freund Tom getroffen. Er sagt: „Ich komme morgen mit.“ Ich hoffe, dass er pünktlich ist. Wir wollen die Straße entlang bis zum Fluss laufen.*\n\nPoints attendus :\n- Majuscule à **tous** les noms communs : *Park*, *Freund*, *Straße*, *Fluss* (et bien sûr au prénom *Tom* et en début de phrase : *Gestern*, *Er*, *Ich*, *Wir*).\n- Deux-points avant le discours direct (*Er sagt:*), guillemets ouverts en bas et fermés en haut, et majuscule au début de la parole rapportée (*Ich komme…*).\n- Virgule obligatoire devant *dass*.\n\n**2.** On écrit **ß** après une voyelle longue ou une diphtongue : le *a* de *Straße* est long. On écrit **ss** après une voyelle brève : le *u* de *Fluss* est bref. *Fluß* est donc une faute (ancienne orthographe)."}$exo$::jsonb),
  ('36b32493-08a1-5bee-962e-a56d20b1e5ea'::uuid, 3, 'traduction', $exo${"titre":"Thème : ponctuer et écrire juste","consigne":"Traduis les quatre phrases en allemand en respectant la ponctuation et les majuscules allemandes, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n1. Il dit : « Je sais qu'elle vient. »\n2. Madame Weber, je vous remercie.\n3. La ville que je visite est belle mais chère.\n4. J'apprends l'allemand pour lire des livres.\n\n*Aide : danken + datif ; besuchen = visiter ; schön = beau ; teuer = cher ; das Buch, die Bücher.*\n\n**2.** Quelle est la différence de sens entre *Können Sie mir helfen?* et *Können sie mir helfen?* Explique pourquoi.","bareme":[{"critere":"Virgules justes : dass, relative enchâssée, aber, um… zu","points":6},{"critere":"Deux-points et guillemets allemands au discours direct","points":3},{"critere":"Majuscules : noms communs, Ihnen de politesse","points":4},{"critere":"Ordre des mots et formes verbales corrects","points":3},{"critere":"Explication de la différence Sie / sie","points":4}],"dureeMin":15,"corrige":"**1. Traduction modèle**\n\n1. *Er sagt: „Ich weiß, dass sie kommt.“*\n2. *Frau Weber, ich danke Ihnen.*\n3. *Die Stadt, die ich besuche, ist schön, aber teuer.*\n4. *Ich lerne Deutsch, um Bücher zu lesen.*\n\nPoints attendus :\n- Phrase 1 : deux-points avant la parole, guillemets „…“, virgule devant *dass*, *sie* (elle) en minuscule.\n- Phrase 2 : *danken* régit le datif : *Ihnen*, avec **majuscule** car c'est le vouvoiement.\n- Phrase 3 : relative encadrée de deux virgules, verbe *besuche* à la fin de la relative, virgule devant *aber*.\n- Phrase 4 : virgule devant *um… zu*, infinitif avec *zu* en fin de phrase.\n\n**2.** *Können Sie mir helfen?* = « Pouvez-vous m'aider ? » (vouvoiement, une personne à qui l'on parle). *Können sie mir helfen?* = « Peuvent-ils (ou peuvent-elles) m'aider ? ». À l'écrit, seule la majuscule distingue le *Sie* de politesse du *sie* de la 3e personne : l'oublier change le destinataire de la phrase."}$exo$::jsonb),
  ('1aabfc2f-f9a8-5107-b019-906008c153f0'::uuid, 1, 'traduction', $exo${"titre":"Changer le début de la phrase","consigne":"Réécris chaque phrase en la commençant par l'élément en gras. Attention à la place du verbe conjugué.","enonce":"**Réécris en commençant par l'élément en gras.**\n\n1. Ich fahre **morgen** nach Berlin.\n2. Wir spielen **am Samstag** Fußball.\n3. Er hat **gestern** einen Film gesehen.\n4. Ich stehe **um sieben Uhr** auf.\n5. Meine Schwester muss **heute Abend** arbeiten.","bareme":[{"critere":"Verbe conjugué en deuxième position et sujet placé derrière (inversion)","points":12},{"critere":"Second morceau du verbe (participe, infinitif, préverbe) laissé en fin de phrase","points":8}],"dureeMin":6,"corrige":"**Phrases attendues**\n\n1. *Morgen fahre ich nach Berlin.*\n2. *Am Samstag spielen wir Fußball.*\n3. *Gestern hat er einen Film gesehen.*\n4. *Um sieben Uhr stehe ich auf.*\n5. *Heute Abend muss meine Schwester arbeiten.*\n\nPoints attendus :\n- Règle V2 : le verbe conjugué reste le **deuxième groupe**. Dès qu'un autre élément que le sujet ouvre la phrase, le sujet passe **derrière** le verbe (inversion). *Morgen ich fahre…* est faux.\n- Parenthèse verbale : *gesehen* (participe), *auf* (préverbe) et *arbeiten* (infinitif après le modal) restent à la toute fin."}$exo$::jsonb),
  ('1aabfc2f-f9a8-5107-b019-906008c153f0'::uuid, 2, 'traduction', $exo${"titre":"Cinq phrases à traduire dans le bon ordre","consigne":"Traduis en allemand. Soigne la place du verbe et l'ordre des compléments.","enonce":"**Traduis en allemand.**\n\n1. Demain, je dois travailler.\n2. Hier, Paul a acheté un vélo.\n3. Je donne le livre à l'enfant.\n4. Je le donne à l'enfant.\n5. Nous allons demain en train à Munich.\n\n*Aide : kaufen (gekauft) ; das Fahrrad ; das Buch ; das Kind ; fahren ; mit dem Zug ; München.*","bareme":[{"critere":"Verbe en deuxième position et inversion après Morgen / Gestern","points":6},{"critere":"Infinitif et participe rejetés en fin de phrase","points":5},{"critere":"Ordre datif puis accusatif, et pronom es placé devant le datif","points":5},{"critere":"Ordre temps, manière, lieu (TeKaMoLo) dans la phrase 5","points":4}],"dureeMin":10,"corrige":"**Traduction modèle**\n\n1. *Morgen muss ich arbeiten.*\n2. *Gestern hat Paul ein Fahrrad gekauft.*\n3. *Ich gebe dem Kind das Buch.*\n4. *Ich gebe es dem Kind.*\n5. *Wir fahren morgen mit dem Zug nach München.*\n\nPoints attendus :\n- 1 et 2 : l'adverbe de temps occupe la première place, le verbe conjugué suit, puis le sujet (inversion). L'infinitif *arbeiten* et le participe *gekauft* ferment la phrase.\n- 3 : deux groupes nominaux → **datif puis accusatif** (*dem Kind das Buch*).\n- 4 : l'accusatif est un **pronom** → il passe devant (*es dem Kind*). *Ich gebe dem Kind es* est faux.\n- 5 : TeKaMoLo : temps (*morgen*), manière (*mit dem Zug*), lieu (*nach München*)."}$exo$::jsonb),
  ('1aabfc2f-f9a8-5107-b019-906008c153f0'::uuid, 3, 'traduction', $exo${"titre":"Le week-end de Jonas","consigne":"À partir des notes, écris un petit texte de cinq phrases au présent, sauf une phrase au parfait. Au moins trois phrases doivent commencer par un autre élément que le sujet. Puis réponds à la question 2.","enonce":"**1. Rédige le texte à partir de ces notes.**\n\n- samedi : se lever à 8 heures (*aufstehen*)\n- ensuite : prendre le train pour Hambourg avec sa sœur\n- là-bas : devoir acheter un cadeau pour sa grand-mère (*müssen*)\n- dimanche : visiter le port — **au parfait** (*den Hafen besuchen*)\n- le soir : rentrer à la maison (*zurückkommen, nach Hause*)\n\n**2.** Choisis une de tes phrases qui commence par un complément de temps et explique en français la règle de la place du verbe qu'elle applique.","bareme":[{"critere":"Verbe conjugué en deuxième position dans chaque phrase, avec inversion","points":6},{"critere":"Parenthèse verbale : préverbe, infinitif du modal et participe en fin de phrase","points":6},{"critere":"Ordre des compléments (temps, manière, lieu) respecté","points":3},{"critere":"Explication juste de la règle V2 et de l'inversion","points":5}],"dureeMin":16,"corrige":"**1. Texte modèle**\n\n*Am Samstag steht Jonas um acht Uhr auf. Dann fährt er mit seiner Schwester mit dem Zug nach Hamburg. Dort muss er ein Geschenk für seine Großmutter kaufen. Am Sonntag hat er den Hafen besucht. Am Abend kommt er nach Hause zurück.*\n\nPoints attendus :\n- Chaque phrase ouverte par *Am Samstag*, *Dann*, *Dort*, *Am Sonntag*, *Am Abend* : verbe en 2e position, sujet **derrière**.\n- Préverbes *auf* et *zurück* en fin de phrase ; *kaufen* après le modal *muss* en fin de phrase ; participe *besucht* en fin de phrase après *hat*.\n- Compléments dans l'ordre temps → manière → lieu : *mit dem Zug nach Hamburg*.\n- Toute formulation équivalente correcte est acceptée (ex. *nimmt den Zug nach Hamburg*).\n\n**2.** Exemple : *Am Sonntag hat er den Hafen besucht.* Dans une déclarative, le verbe conjugué occupe toujours la deuxième place (le deuxième **groupe**, pas le deuxième mot). Comme le complément de temps *Am Sonntag* occupe la première place, le sujet *er* passe derrière le verbe : c'est l'inversion. Le participe *besucht* ferme la phrase."}$exo$::jsonb),
  ('91ebc13d-20dd-53ae-882e-9f0237bfc217'::uuid, 1, 'traduction', $exo${"titre":"Trouver la bonne question","consigne":"Écris la question qui correspond à chaque réponse. La partie en gras est ce que l'on demande ; pour la phrase 1, pose une question fermée.","enonce":"**Écris la question (tutoie la personne).**\n\n1. Ja, ich komme morgen.\n2. Ich wohne **in Köln**.\n3. Ich fahre **nach Wien**.\n4. **Mein Bruder** ruft an.\n5. Ich sehe **den Lehrer**.","bareme":[{"critere":"Mot interrogatif juste (wo, wohin, wer, wen)","points":10},{"critere":"Place du verbe : 1re position (question fermée), 2e après le mot en w-","points":6},{"critere":"Conjugaison à la 2e personne et point d'interrogation","points":4}],"dureeMin":7,"corrige":"**Questions attendues**\n\n1. *Kommst du morgen?* — question fermée : verbe en **première** position.\n2. *Wo wohnst du?* — *wo* : le lieu où l'on est, **sans** mouvement.\n3. *Wohin fährst du?* — *wohin* : la destination, **avec** mouvement.\n4. *Wer ruft an?* — *wer* : qui (sujet, nominatif).\n5. *Wen siehst du?* — *wen* : qui (COD, accusatif de *wer*).\n\nPoints attendus : dans les questions ouvertes, le verbe reste en deuxième position, juste après le mot interrogatif ; *wer* se décline (*wen* à l'accusatif) ; ne pas confondre *wo* et *wohin*."}$exo$::jsonb),
  ('91ebc13d-20dd-53ae-882e-9f0237bfc217'::uuid, 2, 'traduction', $exo${"titre":"Des questions indirectes","consigne":"Transforme chaque question directe en question indirecte avec l'amorce donnée, puis réponds à la question 2.","enonce":"**1. Transforme en question indirecte.**\n\n1. Kommt Lisa heute? → *Ich frage mich, …*\n2. Wann beginnt der Film? → *Weißt du, …*\n3. Warum lernst du Deutsch? → *Sag mir, …*\n4. Wo wohnt dein Onkel? → *Ich weiß nicht, …*\n\n**2.** Pourquoi serait-il faux d'écrire *Ich frage mich, wenn Lisa heute kommt* ?","bareme":[{"critere":"Choix de ob pour la question fermée, mot en w- conservé ailleurs","points":6},{"critere":"Verbe conjugué rejeté à la fin de la subordonnée","points":8},{"critere":"Virgules et ponctuation finale correctes","points":3},{"critere":"Explication de l'opposition ob / wenn","points":3}],"dureeMin":10,"corrige":"**1. Phrases attendues**\n\n1. *Ich frage mich, ob Lisa heute kommt.*\n2. *Weißt du, wann der Film beginnt?*\n3. *Sag mir, warum du Deutsch lernst.*\n4. *Ich weiß nicht, wo dein Onkel wohnt.*\n\nPoints attendus :\n- La question indirecte est une subordonnée : virgule devant, et verbe conjugué **à la fin** (*kommt*, *beginnt*, *lernst*, *wohnt*).\n- Sans mot interrogatif (question fermée), on emploie *ob*.\n- Le point d'interrogation disparaît, sauf quand la principale elle-même est une question (phrase 2 : *Weißt du…?*).\n\n**2.** Le « si » d'une question indirecte exprime une **alternative** (oui ou non) : il se traduit par *ob*. *Wenn* introduit une **condition** ou un **moment** ; l'employer ici serait une faute de sens."}$exo$::jsonb),
  ('91ebc13d-20dd-53ae-882e-9f0237bfc217'::uuid, 3, 'traduction', $exo${"titre":"Dialogue avant le concert","consigne":"Traduis ce dialogue en allemand (thème), puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n— Tu ne viens pas au concert ?\n— Si ! Mais je ne sais pas quand il commence.\n— À huit heures. À qui penses-tu ?\n— À Mia. Et toi, à quoi penses-tu ?\n— Aux vacances !\n\n*Aide : mitkommen ; zum Konzert ; beginnen ; denken an + accusatif ; die Ferien (pluriel).*\n\n**2.** Explique en français pourquoi on répond *Doch!* à la première question, et pourquoi on dit *an wen* pour Mia mais *woran* pour les vacances.","bareme":[{"critere":"Doch employé pour contredire la question négative","points":3},{"critere":"Question indirecte avec wann et verbe en fin de subordonnée","points":5},{"critere":"An wen pour une personne, woran pour une chose","points":5},{"critere":"Place du verbe dans les questions fermées et ouvertes","points":4},{"critere":"Explication juste de doch et de wo(r) + préposition","points":3}],"dureeMin":15,"corrige":"**1. Traduction modèle**\n\n— *Kommst du nicht zum Konzert mit?* (ou *Du kommst nicht mit zum Konzert?*)\n— *Doch! Aber ich weiß nicht, wann es beginnt.*\n— *Um acht Uhr. An wen denkst du?*\n— *An Mia. Und woran denkst du?*\n— *An die Ferien!*\n\nPoints attendus :\n- *Doch!* et non *Ja!* pour dire « si ».\n- *…, wann es beginnt* : virgule, verbe à la fin ; *es* reprend *das Konzert* (neutre).\n- *An wen denkst du?* (personne : préposition + *wen*) ; *Woran denkst du?* (chose : *wo(r)-* soudé à la préposition).\n- Question ouverte : verbe en 2e position après le mot interrogatif.\n\n**2.** Face à une question **négative**, *ja* est impossible : pour contredire la négation, l'allemand répond *doch* (comme « si » en français). Pour interroger sur une **chose**, l'allemand soude *wo(r)-* et la préposition (*woran*) ; pour une **personne**, il garde la préposition suivie de *wen* ou *wem* (*an wen*)."}$exo$::jsonb),
  ('43b9ea0d-3124-5c72-876c-7151c7e3b30d'::uuid, 1, 'traduction', $exo${"titre":"Nicht ou kein ?","consigne":"Mets chaque phrase à la forme négative en choisissant entre nicht et kein.","enonce":"**Mets à la forme négative.**\n\n1. Ich habe ein Fahrrad.\n2. Ich kenne den Mann.\n3. Er trinkt Kaffee.\n4. Das Buch ist interessant.\n5. Wir haben Freunde in Berlin.\n6. Ich gehe ins Kino.","bareme":[{"critere":"Choix juste entre nicht et kein pour chaque phrase","points":10},{"critere":"Déclinaison de kein (keinen, keine au pluriel)","points":4},{"critere":"Place de nicht (après le COD défini, devant l'attribut et le lieu)","points":6}],"dureeMin":7,"corrige":"**Phrases attendues**\n\n1. *Ich habe kein Fahrrad.* — nom précédé de *ein* → *kein*.\n2. *Ich kenne den Mann nicht.* — article défini → *nicht*, placé **après** le COD défini.\n3. *Er trinkt keinen Kaffee.* — nom sans article → *kein*, décliné à l'accusatif masculin : *keinen*.\n4. *Das Buch ist nicht interessant.* — on nie l'attribut : *nicht* **devant** lui.\n5. *Wir haben keine Freunde in Berlin.* — pluriel sans article → *keine* (kein a un pluriel).\n6. *Ich gehe nicht ins Kino.* — lieu directionnel : *nicht* **devant**.\n\nRègle : *kein* devant un nom précédé de *ein* ou sans article ; *nicht* devant un article défini, un possessif, un verbe, un adjectif."}$exo$::jsonb),
  ('43b9ea0d-3124-5c72-876c-7151c7e3b30d'::uuid, 2, 'traduction', $exo${"titre":"Cinq négations à traduire","consigne":"Traduis en allemand, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n1. Je ne l'ai pas vu hier. (*le* = un homme)\n2. Il ne travaille plus.\n3. Je ne pars pas demain, mais aujourd'hui.\n4. Personne ne vient.\n5. Je ne vois rien.\n\n*Aide : sehen (gesehen) ; arbeiten ; fahren ; kommen.*\n\n**2.** Un élève écrit *Ich sehe nicht nichts*. Explique en français pourquoi c'est faux.","bareme":[{"critere":"Mots négatifs justes : nicht mehr, niemand, nichts","points":6},{"critere":"Place de nicht : devant le participe, devant le mot nié","points":6},{"critere":"Rectification avec sondern","points":4},{"critere":"Explication : une seule négation suffit en allemand","points":4}],"dureeMin":10,"corrige":"**1. Traduction modèle**\n\n1. *Ich habe ihn gestern nicht gesehen.* — négation de toute la phrase : *nicht* le plus à droite possible, devant le participe.\n2. *Er arbeitet nicht mehr.* — « ne… plus » = *nicht mehr*.\n3. *Ich fahre nicht morgen, sondern heute.* — on nie un seul mot : *nicht* **devant** *morgen* ; après une négation, on rectifie avec *sondern* (pas *aber*).\n4. *Niemand kommt.*\n5. *Ich sehe nichts.*\n\n**2.** En allemand, deux négations ne s'additionnent pas pour renforcer : **une seule suffit**. *Nichts* porte déjà la négation (« rien »), il ne faut donc pas ajouter *nicht*. La phrase juste est *Ich sehe nichts*."}$exo$::jsonb),
  ('43b9ea0d-3124-5c72-876c-7151c7e3b30d'::uuid, 3, 'traduction', $exo${"titre":"Paul répond non à tout","consigne":"Paul est de mauvaise humeur : il répond non à toutes les questions de sa mère. Écris ses réponses en phrases complètes, puis réponds à la question 2.","enonce":"**1. Écris les réponses négatives de Paul.**\n\n1. Hast du einen Hund gesehen?\n2. Hast du deine Hausaufgaben gemacht?\n3. Ist dein Freund nett?\n4. Fährst du nach Berlin? — *Paul rectifie : il va à Hambourg.*\n5. Wohnst du noch in Köln?\n6. Kommt jemand mit?\n\n**2.** Justifie en français ton choix entre *nicht* et *kein* dans les réponses 1 et 2.","bareme":[{"critere":"Choix nicht / kein juste et kein décliné (keinen)","points":6},{"critere":"Place de nicht : après le COD défini, devant l'attribut et le lieu","points":5},{"critere":"Emploi de sondern, nicht mehr et niemand","points":5},{"critere":"Justification juste des réponses 1 et 2","points":4}],"dureeMin":15,"corrige":"**1. Réponses modèles**\n\n1. *Nein, ich habe keinen Hund gesehen.*\n2. *Nein, ich habe meine Hausaufgaben nicht gemacht.*\n3. *Nein, er ist nicht nett.*\n4. *Nein, ich fahre nicht nach Berlin, sondern nach Hamburg.*\n5. *Nein, ich wohne nicht mehr in Köln.*\n6. *Nein, niemand kommt mit.*\n\nPoints attendus :\n- 1 : *einen Hund* → *keinen Hund* (accusatif masculin).\n- 2 : COD avec possessif → *nicht*, placé après le COD et devant le participe *gemacht*.\n- 3 : *nicht* devant l'attribut.\n- 4 : *nicht* devant le lieu directionnel, rectification par *sondern*.\n- 5 : « ne… plus » = *nicht mehr*. 6 : *niemand*, sans autre négation.\n\n**2.** Réponse 1 : le nom est précédé de l'article indéfini *einen* → on nie avec *kein*, qui se décline comme *ein* (*keinen*). Réponse 2 : le nom est précédé d'un possessif (*meine*) → on nie avec *nicht*, jamais avec *kein*."}$exo$::jsonb),
  ('e63ceb4e-8685-53fb-80a2-8b7975b80c4d'::uuid, 1, 'traduction', $exo${"titre":"Relier deux phrases","consigne":"Relie les deux phrases avec la conjonction donnée. Attention à la place du verbe.","enonce":"**Relie avec la conjonction entre parenthèses.**\n\n1. Ich bleibe zu Hause. Ich bin krank. (*weil*)\n2. Ich weiß. Er kommt morgen. (*dass*)\n3. Sie geht spazieren. Es regnet. (*obwohl*)\n4. Er ruft an. Er hat Zeit. (*wenn*)","bareme":[{"critere":"Verbe conjugué rejeté à la fin de chaque subordonnée","points":12},{"critere":"Virgule devant la subordonnée","points":4},{"critere":"Reste de la phrase et sujet correctement placés","points":4}],"dureeMin":6,"corrige":"**Phrases attendues**\n\n1. *Ich bleibe zu Hause, weil ich krank bin.*\n2. *Ich weiß, dass er morgen kommt.*\n3. *Sie geht spazieren, obwohl es regnet.*\n4. *Er ruft an, wenn er Zeit hat.*\n\nPoints attendus : une subordonnée se reconnaît à la conjonction en tête et au **verbe conjugué à la toute fin** (*bin*, *kommt*, *regnet*, *hat*). La virgule devant la subordonnée est obligatoire. Le sujet suit directement la conjonction (*weil ich…*, *dass er…*). *Ich bleibe zu Hause, weil ich bin krank* est la faute à éviter."}$exo$::jsonb),
  ('e63ceb4e-8685-53fb-80a2-8b7975b80c4d'::uuid, 2, 'traduction', $exo${"titre":"Quand, parce que : quatre traductions","consigne":"Traduis en allemand. Soigne le choix de la conjonction et la place des verbes.","enonce":"**Traduis en allemand.**\n\n1. Quand j'étais petit, j'habitais à Munich.\n2. Je reste à la maison parce que je dois travailler.\n3. Il est fatigué parce qu'il a travaillé.\n4. Quand il pleut, je lis.\n\n*Aide : klein ; wohnen (prétérit wohnte) ; München ; zu Hause bleiben ; müde ; regnen ; lesen (er liest).*","bareme":[{"critere":"Choix de als pour un fait unique du passé, wenn pour la répétition","points":5},{"critere":"Verbe final en subordonnée, modal et auxiliaire en dernier","points":6},{"critere":"Subordonnée en tête : verbe de la principale juste après la virgule","points":6},{"critere":"Virgules correctes","points":3}],"dureeMin":10,"corrige":"**Traduction modèle**\n\n1. *Als ich klein war, wohnte ich in München.* (*habe ich in München gewohnt* accepté)\n2. *Ich bleibe zu Hause, weil ich arbeiten muss.*\n3. *Er ist müde, weil er gearbeitet hat.*\n4. *Wenn es regnet, lese ich.*\n\nPoints attendus :\n- 1 : « quand » pour une période **unique** du passé → *als*, jamais *wann* ni *wenn*.\n- 4 : « quand » au présent, à valeur répétée → *wenn*.\n- 2 : avec un modal, c'est le **modal conjugué** qui ferme la subordonnée, après l'infinitif (*arbeiten muss*).\n- 3 : au temps composé, l'**auxiliaire** ferme la subordonnée, après le participe (*gearbeitet hat*).\n- 1 et 4 : la subordonnée en tête occupe la première position ; le verbe de la principale suit **immédiatement** la virgule (*wohnte ich*, *lese ich*)."}$exo$::jsonb),
  ('e63ceb4e-8685-53fb-80a2-8b7975b80c4d'::uuid, 3, 'traduction', $exo${"titre":"Pourquoi j'apprends l'allemand","consigne":"Écris à ton correspondant un message de six phrases pour lui expliquer pourquoi tu apprends l'allemand. Emploie weil, denn, dass, obwohl et damit, et place au moins une subordonnée en tête de phrase. Puis réponds à la question 2.","enonce":"**1. Rédige ton message (six phrases).**\n\nIdées possibles : étudier plus tard en Allemagne, ce que disent tes parents de l'allemand, la grammaire difficile mais le cours agréable, lire des livres en allemand, un professeur qui parle lentement, une visite de ton correspondant l'été prochain.\n\n**2.** Choisis une de tes phrases avec *weil* et une avec *denn*. Explique en français la différence de construction entre les deux.","bareme":[{"critere":"Cinq conjonctions employées avec le bon sens","points":5},{"critere":"Verbe conjugué à la fin après weil, dass, obwohl, damit","points":6},{"critere":"Subordonnée en tête suivie du verbe de la principale","points":3},{"critere":"Ordre normal conservé après denn","points":3},{"critere":"Explication juste de la différence weil / denn","points":3}],"dureeMin":18,"corrige":"**1. Message modèle**\n\n*Ich lerne Deutsch, weil ich später in Berlin studieren möchte. Mein Vater sagt, dass Deutsch in Europa sehr wichtig ist. Obwohl die Grammatik schwer ist, macht mir der Unterricht Spaß. Ich lese auch deutsche Bücher, denn ich will meinen Wortschatz verbessern. Meine Lehrerin spricht langsam, damit wir alles verstehen. Wenn du mich im Sommer besuchst, können wir zusammen Deutsch sprechen.*\n\nPoints attendus :\n- Verbe (ou modal) conjugué à la fin après *weil*, *dass*, *obwohl*, *damit*, *wenn* : *möchte*, *ist*, *verstehen*, *besuchst*.\n- *Obwohl…* et *Wenn…* en tête : le verbe de la principale suit la virgule (*macht mir*, *können wir*).\n- *denn* : ordre normal, verbe en 2e position (*denn ich will…*).\n- *damit* (but avec un autre sujet), *obwohl* (concession) employés avec le bon sens. Toute production correcte et variée est acceptée.\n\n**2.** *weil* est une conjonction de **subordination** : elle envoie le verbe conjugué à la fin (*weil ich… studieren möchte*). *denn* est une conjonction de **coordination** : elle ne touche pas à l'ordre des mots, le verbe reste en deuxième position (*denn ich will…*). Le sens (la cause) est le même."}$exo$::jsonb),
  ('d45bd5ca-dc1d-5d93-99bc-8eee25574744'::uuid, 1, 'traduction', $exo${"titre":"Le bon pronom relatif","consigne":"Complète chaque phrase avec le pronom relatif qui convient, puis justifie les phrases 2 et 4.","enonce":"**1. Complète avec le pronom relatif.**\n\n1. Der Mann, ___ dort steht, ist mein Onkel.\n2. Die Frau, ___ ich helfe, ist alt.\n3. Das Buch, ___ ich lese, ist spannend.\n4. Die Kinder, mit ___ ich spiele, sind nett.\n5. Der Junge, ___ Vater Arzt ist, heißt Tim.\n6. Die Stadt, ___ ich besuche, ist schön.\n\n**2.** Justifie en une phrase chacun le pronom des phrases 2 et 4 (genre et cas).","bareme":[{"critere":"Genre et nombre repris de l'antécédent","points":6},{"critere":"Cas donné par la fonction dans la relative (dont der, denen, dessen)","points":10},{"critere":"Justification juste des phrases 2 et 4","points":4}],"dureeMin":7,"corrige":"**1. Réponses**\n\n1. *der* — masculin, sujet → nominatif.\n2. *der* — féminin, complément de *helfen* qui régit le **datif** → *der*.\n3. *das* — neutre, COD → accusatif *das*.\n4. *denen* — pluriel, après *mit* qui régit le datif → datif pluriel *denen*.\n5. *dessen* — masculin, complément du nom *Vater* → génitif *dessen*, sans article devant *Vater*.\n6. *die* — féminin, COD → accusatif *die*.\n\n**2.** Phrase 2 : *Frau* est féminin (genre venu d'avant), et dans la relative le pronom est complément de *helfen*, qui régit le datif (cas venu d'après) → *der*. Phrase 4 : *Kinder* est au pluriel, et la préposition *mit* impose le datif → *denen*, l'une des trois formes qui diffèrent de l'article."}$exo$::jsonb),
  ('d45bd5ca-dc1d-5d93-99bc-8eee25574744'::uuid, 2, 'traduction', $exo${"titre":"Deux phrases, une relative","consigne":"Relie chaque paire de phrases par une subordonnée relative.","enonce":"**Relie par une relative.**\n\n1. Das ist der Film. Ich habe den Film gestern gesehen.\n2. Ich kenne die Lehrerin. Sie wohnt in unserer Straße.\n3. Hier ist mein Freund. Ich fahre mit ihm nach Wien.\n4. Das ist die Frau. Ihr Auto ist kaputt.\n5. Du sagst alles. Das ist richtig. → commence par *Alles, …*","bareme":[{"critere":"Pronom relatif juste (den, die, dem, deren, was)","points":8},{"critere":"Préposition placée devant le relatif","points":3},{"critere":"Verbe conjugué à la fin de la relative","points":5},{"critere":"Virgules obligatoires autour de la relative","points":4}],"dureeMin":10,"corrige":"**Phrases attendues**\n\n1. *Das ist der Film, den ich gestern gesehen habe.* — masculin, COD → *den* ; l'auxiliaire *habe* ferme la relative.\n2. *Ich kenne die Lehrerin, die in unserer Straße wohnt.* — féminin, sujet → *die*.\n3. *Hier ist mein Freund, mit dem ich nach Wien fahre.* — la préposition reste **devant** le relatif et commande le datif.\n4. *Das ist die Frau, deren Auto kaputt ist.* — génitif féminin *deren*, sans article devant *Auto*.\n5. *Alles, was du sagst, ist richtig.* — après *alles*, le relatif est *was*, jamais *das*.\n\nDans toutes les phrases : virgules obligatoires, verbe conjugué **à la fin** de la relative."}$exo$::jsonb),
  ('d45bd5ca-dc1d-5d93-99bc-8eee25574744'::uuid, 3, 'traduction', $exo${"titre":"Lukas et son club de football","consigne":"Traduis le texte en allemand (thème), puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n> Lukas est un garçon qui habite à Hambourg. Le club dans lequel il joue au football est connu. Son entraîneur, à qui il fait confiance, est sévère. La fille dont le frère joue aussi s'appelle Emma. Lukas gagne souvent, ce qui plaît à ses parents.\n\n*Aide : der Verein ; der Trainer ; vertrauen + datif ; streng ; das Mädchen ; gewinnen ; gefallen + datif ; bekannt.*\n\n**2.** Explique en français pourquoi on écrit *dessen* (et non *deren*) devant *Bruder*, et *dem* devant *er vertraut*.","bareme":[{"critere":"Pronoms relatifs justes : der, in dem, dem, dessen","points":6},{"critere":"Relatif was après une phrase entière","points":3},{"critere":"Verbe à la fin de chaque relative et virgules","points":5},{"critere":"Vocabulaire et reste de la phrase corrects","points":2},{"critere":"Justification de dessen et de dem","points":4}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n> *Lukas ist ein Junge, der in Hamburg wohnt. Der Verein, in dem er Fußball spielt, ist bekannt. Sein Trainer, dem er vertraut, ist streng. Das Mädchen, dessen Bruder auch spielt, heißt Emma. Lukas gewinnt oft, was seinen Eltern gefällt.*\n\nPoints attendus :\n- *der* : masculin (Junge), sujet → nominatif.\n- *in dem* : la préposition reste devant le relatif ; *in* + datif (lieu où l'on est).\n- *dem* : masculin (Trainer), complément de *vertrauen* qui régit le datif.\n- *dessen* : génitif, sans article devant *Bruder*.\n- *was* : le relatif reprend toute la phrase précédente.\n- Chaque relative : virgules et verbe conjugué à la fin (*wohnt*, *spielt*, *vertraut*, *spielt*, *gefällt*). Relative enchâssée encadrée de deux virgules.\n\n**2.** Le pronom prend le **genre de l'antécédent** : *Mädchen* est **neutre** (diminutif en -chen), donc génitif neutre *dessen* ; *deren* serait féminin ou pluriel. Pour *dem* : l'antécédent *Trainer* est masculin, et dans la relative le pronom est complément de *vertrauen*, qui régit le datif → *dem*."}$exo$::jsonb),
  ('129d5284-86ed-5281-b99b-a30533e66829'::uuid, 1, 'traduction', $exo${"titre":"Passer au passif","consigne":"Mets chaque phrase au passif présent. Garde l'agent quand il est nommé.","enonce":"**Mets au passif présent.**\n\n1. Man baut ein Haus.\n2. Der Lehrer korrigiert die Hefte.\n3. Man repariert das Auto.\n4. Die Mutter kocht die Suppe.\n\n*Rappel : le COD de la phrase active devient le sujet de la phrase passive.*","bareme":[{"critere":"werden conjugué et accordé au nouveau sujet (wird, werden)","points":8},{"critere":"Participe II rejeté en fin de phrase","points":6},{"critere":"Agent introduit par von + datif (vom Lehrer, von der Mutter)","points":6}],"dureeMin":7,"corrige":"**Phrases attendues**\n\n1. *Ein Haus wird gebaut.*\n2. *Die Hefte werden vom Lehrer korrigiert.*\n3. *Das Auto wird repariert.*\n4. *Die Suppe wird von der Mutter gekocht.*\n\nPoints attendus :\n- Le passif d'action se construit avec **werden** (jamais *sein*) + participe II à la fin.\n- *werden* s'accorde avec le nouveau sujet : *die Hefte* est pluriel → *werden*.\n- *man* disparaît : pas d'agent. Une personne agent est introduite par *von* + datif : *vom Lehrer* (von dem), *von der Mutter*.\n- Participes : *gebaut*, *korrigiert*, *repariert* (verbes en -ieren, sans ge-), *gekocht*."}$exo$::jsonb),
  ('129d5284-86ed-5281-b99b-a30533e66829'::uuid, 2, 'traduction', $exo${"titre":"Le passif à tous les temps","consigne":"Réponds aux quatre questions.","enonce":"1. Mets *Das Haus wird gebaut* au **prétérit**, puis au **parfait**.\n2. Mets *Der Brief wird geschrieben* au **parfait**.\n3. Traduis : « Le travail doit être fait aujourd'hui. » (*die Arbeit, machen*)\n4. Explique en français la différence de sens entre *Die Tür wird geschlossen* et *Die Tür ist geschlossen*.","bareme":[{"critere":"Prétérit du passif avec wurde","points":4},{"critere":"Parfait du passif avec ist + participe + worden","points":6},{"critere":"Passif avec modal : muss + participe + werden","points":5},{"critere":"Distinction juste entre passif d'action et passif d'état","points":5}],"dureeMin":10,"corrige":"1. Prétérit : *Das Haus wurde gebaut.* Parfait : *Das Haus ist gebaut worden.*\n2. *Der Brief ist geschrieben worden.*\n3. *Die Arbeit muss heute gemacht werden.* — le modal se conjugue, le passif passe à l'infinitif (*gemacht werden*).\n4. *Die Tür wird geschlossen* = passif d'**action** : quelqu'un est en train de fermer la porte (le film). *Die Tür ist geschlossen* = passif d'**état** : la porte est fermée, c'est un résultat acquis (la photo).\n\nPoint essentiel : au parfait du passif, le participe de *werden* perd son ge- : **worden**. *geworden* est réservé au verbe *werden* au sens de « devenir » (*Er ist Arzt geworden*). L'auxiliaire du parfait passif est toujours *sein* (*ist… worden*)."}$exo$::jsonb),
  ('129d5284-86ed-5281-b99b-a30533e66829'::uuid, 3, 'traduction', $exo${"titre":"L'histoire d'un pont","consigne":"Traduis ce petit article en allemand en employant le passif, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n> Le pont de la ville a été construit en 1890. En 2020, il a été détruit par une tempête. Aujourd'hui, il est reconstruit par une entreprise allemande. Il doit être terminé en 2027. Ici, on travaille jour et nuit.\n\n*Aide : die Brücke (féminin) ; bauen ; zerstören ; der Sturm ; die Firma ; wieder aufbauen (wieder aufgebaut) ; fertigstellen (fertiggestellt) ; Tag und Nacht. Pour « on travaille », utilise le passif impersonnel.*\n\n**2.** Réécris la dernière phrase avec *man*, puis explique pourquoi tu as employé *durch* pour la tempête et *von* pour l'entreprise.","bareme":[{"critere":"Temps du passif justes : wurde / ist … worden, wird + participe","points":6},{"critere":"Passif avec modal : muss … fertiggestellt werden","points":3},{"critere":"Passif impersonnel : Hier wird … gearbeitet","points":3},{"critere":"Agent : durch + accusatif et von + datif","points":4},{"critere":"Phrase avec man et explication von / durch","points":4}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n> *Die Brücke der Stadt wurde 1890 gebaut. 2020 ist sie durch einen Sturm zerstört worden. Heute wird sie von einer deutschen Firma wieder aufgebaut. Sie muss 2027 fertiggestellt werden. Hier wird Tag und Nacht gearbeitet.*\n\nPoints attendus :\n- *wurde gebaut* (prétérit) ou *ist gebaut worden* (parfait) acceptés pour les deux premières phrases ; au parfait : **worden**, jamais *geworden*.\n- *sie* reprend *die Brücke* (féminin).\n- *wird… wieder aufgebaut* : présent du passif, participe en fin de phrase.\n- *muss… fertiggestellt werden* : modal + infinitif passif.\n- *Hier wird… gearbeitet* : passif impersonnel d'un verbe sans COD.\n- Une date seule s'emploie sans préposition (*1890*, *2020*) ; *im Jahr 1890* accepté.\n\n**2.** *Hier arbeitet man Tag und Nacht.* (ou *Man arbeitet hier Tag und Nacht.*)\n*von* + datif introduit une personne ou une force qui agit : l'entreprise fait le travail. *durch* + accusatif introduit un **moyen** ou un intermédiaire, comme un phénomène naturel (*durch ein Erdbeben*, *durch einen Sturm*)."}$exo$::jsonb),
  ('3eaabd78-cedc-5d4c-90ec-ad14fd014dee'::uuid, 1, 'traduction', $exo${"titre":"Avec ou sans zu ?","consigne":"Complète avec zu quand il le faut, ou écris l'infinitif entre parenthèses à la bonne forme.","enonce":"**Complète (mets un tiret si zu est impossible).**\n\n1. Ich versuche, pünktlich ___ sein.\n2. Ich kann gut ___ schwimmen.\n3. Er hat keine Lust, ins Kino ___ gehen.\n4. Wir gehen heute ___ schwimmen.\n5. Es ist wichtig, früh ___ (*aufstehen*).\n6. Vergiss nicht, Brot ___ (*einkaufen*).","bareme":[{"critere":"zu présent après versuchen, Lust haben, es ist wichtig, vergessen","points":8},{"critere":"Pas de zu après un modal et un verbe de mouvement","points":6},{"critere":"zu intercalé en un seul mot : aufzustehen, einzukaufen","points":6}],"dureeMin":6,"corrige":"**Réponses**\n\n1. *Ich versuche, pünktlich zu sein.* — *versuchen* appelle *zu*.\n2. *Ich kann gut schwimmen.* — **pas** de *zu* après un modal.\n3. *Er hat keine Lust, ins Kino zu gehen.* — *Lust haben* appelle *zu*.\n4. *Wir gehen heute schwimmen.* — **pas** de *zu* après un verbe de mouvement.\n5. *Es ist wichtig, früh aufzustehen.* — avec un préverbe séparable, *zu* s'intercale entre le préverbe et le radical, en **un seul mot**.\n6. *Vergiss nicht, Brot einzukaufen.* — même règle : *einzukaufen*.\n\nÀ retenir : *zu* se place juste devant l'infinitif, en fin de groupe ; les modaux, *sehen*, *hören*, *lassen* et les verbes de mouvement le refusent."}$exo$::jsonb),
  ('3eaabd78-cedc-5d4c-90ec-ad14fd014dee'::uuid, 2, 'traduction', $exo${"titre":"But, privation, substitution","consigne":"Relie chaque paire de phrases avec um… zu, damit, ohne… zu ou statt… zu, selon l'indication.","enonce":"**Relie les phrases.**\n\n1. Ich spare Geld. Ich will ein Fahrrad kaufen. (*but*)\n2. Ich erkläre es dir. Du verstehst es. (*but*)\n3. Er geht weg. Er sagt nichts. (*privation : « sans »*)\n4. Sie sieht fern. Sie sollte arbeiten. (*substitution : « au lieu de »*)\n5. Ich stehe früh auf. Ich rufe meine Oma an. (*but*)","bareme":[{"critere":"Choix du bon outil pour chaque phrase","points":6},{"critere":"damit quand le sujet change (phrase 2) avec verbe final","points":5},{"critere":"zu bien placé, dont anzurufen en un seul mot","points":5},{"critere":"Virgule obligatoire devant chaque groupe","points":4}],"dureeMin":11,"corrige":"**Phrases attendues**\n\n1. *Ich spare Geld, um ein Fahrrad zu kaufen.*\n2. *Ich erkläre es dir, damit du es verstehst.*\n3. *Er geht weg, ohne etwas zu sagen.*\n4. *Sie sieht fern, statt zu arbeiten.* (*anstatt* accepté)\n5. *Ich stehe früh auf, um meine Oma anzurufen.*\n\nPoints attendus :\n- *um… zu* exige que les deux propositions aient le **même sujet** (phrases 1 et 5).\n- Phrase 2 : le sujet change (*ich* / *du*) → *damit*, subordonnée avec le verbe à la fin (*verstehst*).\n- Phrase 3 : « ne rien dire » → *ohne etwas zu sagen* (« sans rien dire »).\n- Phrase 5 : *anrufen* est séparable → *anzurufen*.\n- Virgule obligatoire devant *um… zu*, *ohne… zu*, *statt… zu* et *damit*. Le groupe infinitif n'a jamais de sujet propre."}$exo$::jsonb),
  ('3eaabd78-cedc-5d4c-90ec-ad14fd014dee'::uuid, 3, 'traduction', $exo${"titre":"Thème : six groupes infinitifs","consigne":"Traduis les six phrases en allemand, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n1. J'ai beaucoup à faire.\n2. Ce travail doit être fait aujourd'hui. (*utilise sein + zu*)\n3. Il est parti sans fermer la porte.\n4. J'apprends l'allemand pour pouvoir parler avec ma correspondante.\n5. Mes parents travaillent pour que nous puissions partir en vacances.\n6. J'ai envie d'aller nager.\n\n*Aide : tun ; die Arbeit ; gehen (ist gegangen) ; die Tür schließen ; die Brieffreundin ; in Urlaub fahren ; Lust haben ; schwimmen gehen.*\n\n**2.** Explique en français pourquoi tu as employé *um… zu* dans la phrase 4 et *damit* dans la phrase 5.","bareme":[{"critere":"haben + zu et sein + zu justes (phrases 1 et 2)","points":4},{"critere":"ohne… zu et Lust haben… zu construits correctement","points":4},{"critere":"um… zu avec modal et damit avec verbe final","points":5},{"critere":"Virgules et place de zu","points":3},{"critere":"Explication juste um… zu / damit (même sujet ou non)","points":4}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n1. *Ich habe viel zu tun.* — *haben* + *zu* : valeur active (avoir à faire).\n2. *Diese Arbeit ist heute zu machen.* — *sein* + *zu* : valeur passive (doit être fait).\n3. *Er ist gegangen, ohne die Tür zu schließen.*\n4. *Ich lerne Deutsch, um mit meiner Brieffreundin sprechen zu können.*\n5. *Meine Eltern arbeiten, damit wir in Urlaub fahren können.*\n6. *Ich habe Lust, schwimmen zu gehen.*\n\nPoints attendus : virgule devant *ohne… zu*, *um… zu*, *damit* ; *zu* juste devant le dernier infinitif (*sprechen zu können*, *schwimmen zu gehen*) ; dans la phrase 5, le modal *können* ferme la subordonnée.\n\n**2.** Phrase 4 : le sujet est le même dans les deux propositions (*ich* apprend, *ich* veux parler) → groupe infinitif *um… zu*. Phrase 5 : le sujet change (*meine Eltern* travaillent, *wir* partons) → *um… zu* est impossible, il faut une subordonnée avec *damit* et un sujet exprimé."}$exo$::jsonb),
  ('4b7573a4-cf85-5ee5-8a79-649a721475f7'::uuid, 1, 'traduction', $exo${"titre":"Der, die ou das ?","consigne":"Donne l'article défini et l'article indéfini de chaque nom, puis justifie trois de tes réponses par un repère de genre.","enonce":"**1. Donne l'article défini et l'article indéfini (nominatif singulier).**\n\nMädchen · Zeitung · Montag · Freiheit · Lehrer · Essen · Frühling · Päckchen\n\n**2.** Pour *Mädchen*, *Zeitung* et *Montag*, donne en une phrase le repère qui permet de trouver le genre.","bareme":[{"critere":"Articles définis justes (der, die, das)","points":8},{"critere":"Articles indéfinis justes (ein, eine)","points":4},{"critere":"Repères de genre justes pour les trois noms","points":8}],"dureeMin":7,"corrige":"**1. Réponses**\n\n- *das Mädchen / ein Mädchen*\n- *die Zeitung / eine Zeitung*\n- *der Montag / ein Montag*\n- *die Freiheit / eine Freiheit*\n- *der Lehrer / ein Lehrer*\n- *das Essen / ein Essen*\n- *der Frühling / ein Frühling*\n- *das Päckchen / ein Päckchen*\n\n**2.** Repères :\n- *Mädchen* : tous les diminutifs en *-chen* et *-lein* sont **neutres** — la grammaire l'emporte sur le sens (même chose pour *Päckchen*).\n- *Zeitung* : les noms en *-ung* sont **féminins** (comme ceux en *-heit* : *Freiheit*).\n- *Montag* : les jours, mois et saisons sont **masculins** (comme *Frühling*, qui se termine aussi en *-ling*).\nAutres repères acceptés : *Lehrer* en *-er* masculin ; *Essen* infinitif substantivé neutre."}$exo$::jsonb),
  ('4b7573a4-cf85-5ee5-8a79-649a721475f7'::uuid, 2, 'traduction', $exo${"titre":"Article ou pas d'article ?","consigne":"Complète le texte avec l'article qui convient, ou avec Ø quand il n'en faut pas. Puis réponds à la question 2.","enonce":"**1. Complète le texte.**\n\n> Mein Vater ist ___ Lehrer. ___ Schule, in der er arbeitet, ist groß. Am Morgen trinkt er ___ Kaffee. ___ Mädchen neben ihm ist meine Schwester. Sie hat ___ Katze. ___ Katze heißt Mimi. Im Sommer fahren wir nach ___ Deutschland. Im Garten spielen ___ Kinder.\n\n*(Kinder : des enfants, sens indéfini.)*\n\n**2.** Dans *Das ist meine Schwester*, *das* est-il un article ? Explique.","bareme":[{"critere":"Genres justes des articles (Die Schule, Das Mädchen, eine / Die Katze)","points":6},{"critere":"Absence d'article : métier, matière, nom de pays","points":6},{"critere":"Pas d'article indéfini au pluriel","points":3},{"critere":"Explication de das démonstratif invariable","points":5}],"dureeMin":10,"corrige":"**1. Texte complété**\n\n> *Mein Vater ist Ø Lehrer. Die Schule, in der er arbeitet, ist groß. Am Morgen trinkt er Ø Kaffee. Das Mädchen neben ihm ist meine Schwester. Sie hat eine Katze. Die Katze heißt Mimi. Im Sommer fahren wir nach Ø Deutschland. Im Garten spielen Ø Kinder.*\n\nPoints attendus :\n- Métier après *sein* : pas d'article (*Er ist Lehrer*).\n- Nom de matière : pas d'article (*Kaffee*, « du café »).\n- La plupart des noms de pays : pas d'article (*nach Deutschland*).\n- *ein* n'a **pas de pluriel** : « des enfants » = *Kinder*.\n- *das Mädchen* est neutre (-chen) ; *die Schule*, *die Katze* féminins.\n\n**2.** Non : dans *Das ist meine Schwester*, *das* est un **démonstratif invariable** (« ça, c'est ma sœur »). Il ne s'accorde à rien, même si *Schwester* est féminin ; un article serait suivi d'un nom qu'il détermine."}$exo$::jsonb),
  ('4b7573a4-cf85-5ee5-8a79-649a721475f7'::uuid, 3, 'traduction', $exo${"titre":"Thème : genres et pièges","consigne":"Traduis les phrases en allemand, puis justifie trois de tes choix.","enonce":"**1. Traduis en allemand.**\n\n1. La jeune fille est ma cousine.\n2. Elle est étudiante.\n3. Le soleil brille, la lune est invisible.\n4. Une journée à Berlin coûte cher.\n5. Des enfants jouent dans la rue.\n6. Ça, c'est la solution !\n\n*Aide : Mädchen ; die Cousine ; die Studentin ; Sonne ; Mond ; scheinen ; unsichtbar ; Tag ; teuer sein ; auf der Straße ; Lösung.*\n\n**2.** Justifie en français : l'article de *Mädchen*, l'absence d'article devant *Studentin*, et l'article de *Lösung*.","bareme":[{"critere":"Genres justes : das Mädchen, die Sonne, der Mond, die Lösung","points":6},{"critere":"Absence d'article : métier après sein, indéfini pluriel","points":4},{"critere":"Das démonstratif invariable et ein Tag","points":3},{"critere":"Phrases correctes (verbe, accord, ordre)","points":2},{"critere":"Trois justifications justes","points":5}],"dureeMin":15,"corrige":"**1. Traduction modèle**\n\n1. *Das Mädchen ist meine Cousine.*\n2. *Sie ist Studentin.*\n3. *Die Sonne scheint, der Mond ist unsichtbar.*\n4. *Ein Tag in Berlin ist teuer.*\n5. *Kinder spielen auf der Straße.*\n6. *Das ist die Lösung!*\n\nPoints attendus :\n- *die Sonne* (le soleil) et *der Mond* (la lune) : genres inverses du français.\n- *Sie ist Studentin* : pas d'article devant un métier ou un statut après *sein*.\n- « Des enfants » : pas d'article indéfini au pluriel.\n- *Das ist…* : démonstratif invariable.\n- *Sie* reprend *das Mädchen* : accepté aussi, car il s'agit d'une personne ; *es* est grammaticalement possible.\n\n**2.** *das Mädchen* : tous les diminutifs en *-chen* sont neutres. *Studentin* : après *sein*, un métier ou un statut s'emploie sans article (« elle est **une** étudiante » ne se dit pas). *die Lösung* : les noms en *-ung* sont féminins."}$exo$::jsonb),
  ('8f2fa7ec-b5ae-5360-8e54-0a3e5bae0336'::uuid, 1, 'traduction', $exo${"titre":"Le bon cas, la bonne forme","consigne":"Complète avec la forme correcte du déterminant entre parenthèses.","enonce":"**Complète.**\n\n1. Ich sehe ___ (der) Mann.\n2. Ich helfe ___ (die) Frau.\n3. Ich gebe ___ (das) Kind ein Buch.\n4. Er kauft ___ (ein) Hund.\n5. Das ist das Auto ___ (der) Vater___.\n6. Wir spielen mit ___ (die, pluriel) Kinder___.","bareme":[{"critere":"Accusatifs justes (den, einen)","points":5},{"critere":"Datifs justes (der, dem, den)","points":8},{"critere":"Génitif des Vaters avec -s","points":4},{"critere":"-n du datif pluriel : Kindern","points":3}],"dureeMin":7,"corrige":"**Réponses**\n\n1. *Ich sehe den Mann.* — COD masculin → accusatif *den*.\n2. *Ich helfe der Frau.* — *helfen* : datif féminin *der*.\n3. *Ich gebe dem Kind ein Buch.* — COI neutre → datif *dem*.\n4. *Er kauft einen Hund.* — COD masculin → *einen*.\n5. *Das ist das Auto des Vaters.* — complément du nom → génitif *des*, et le nom masculin prend *-s*.\n6. *Wir spielen mit den Kindern.* — *mit* + datif ; au datif pluriel, l'article est *den* **et** le nom prend *-n*.\n\nRappel : le masculin est le seul genre qui change entre nominatif et accusatif (*der → den*, *ein → einen*)."}$exo$::jsonb),
  ('8f2fa7ec-b5ae-5360-8e54-0a3e5bae0336'::uuid, 2, 'traduction', $exo${"titre":"Possessifs et déterminants en der-","consigne":"Complète chaque phrase, puis indique le cas du groupe complété et sa fonction.","enonce":"**Complète, puis donne le cas et la fonction.**\n\n1. Ich besuche ___ (mein) Großvater.\n2. Ich schenke ___ (meine) Mutter Blumen.\n3. ___ (dieser) Film gefällt mir.\n4. Kennst du ___ (diese) Frau?\n5. ___ (jeder) Kind bekommt ein Geschenk.\n6. Ich spreche mit ___ (unsere, pluriel) Nachbarn.","bareme":[{"critere":"Formes justes des six déterminants","points":10},{"critere":"Cas et fonction correctement identifiés","points":6},{"critere":"Orthographe des terminaisons et des noms","points":4}],"dureeMin":11,"corrige":"**Réponses**\n\n1. *meinen Großvater* — accusatif, COD de *besuchen* ; le possessif se décline comme *ein* : *meinen*.\n2. *meiner Mutter* — datif, COI (on offre **à** sa mère).\n3. *Dieser Film* — nominatif, sujet de *gefällt*.\n4. *diese Frau* — accusatif, COD ; au féminin, accusatif = nominatif.\n5. *Jedes Kind* — nominatif, sujet ; *jeder* prend les terminaisons de l'article défini (*das* → *jedes*).\n6. *unseren Nachbarn* — datif pluriel après *mit* ; *unser* garde son e.\n\nRappel : *kein* et les possessifs se déclinent comme *ein* ; *dieser*, *jeder*, *welcher* comme l'article défini."}$exo$::jsonb),
  ('8f2fa7ec-b5ae-5360-8e54-0a3e5bae0336'::uuid, 3, 'traduction', $exo${"titre":"Thème : les quatre cas en action","consigne":"Traduis les cinq phrases en allemand, puis indique le cas de chaque groupe nominal souligné.","enonce":"**1. Traduis en allemand.**\n\n1. Le frère de **mon amie** offre un livre à **son père**.\n2. Je n'ai pas de **voiture**.\n3. Nous parlons avec **les voisins**.\n4. **Chaque élève** connaît **ce professeur**.\n5. La maison de **la famille** est grande.\n\n*Aide : die Freundin ; schenken ; sein Vater ; das Auto ; der Nachbar (pluriel die Nachbarn) ; der Schüler ; der Lehrer ; die Familie.*\n\n**2.** Donne le cas des sept groupes en gras et justifie-le par leur fonction.","bareme":[{"critere":"Nominatifs et accusatifs justes (kein Auto, diesen Lehrer)","points":4},{"critere":"Datifs justes (seinem Vater, den Nachbarn)","points":5},{"critere":"Génitifs justes (meiner Freundin, der Familie)","points":5},{"critere":"Déterminants en der- et kein bien déclinés","points":3},{"critere":"Cas identifiés et justifiés par la fonction","points":3}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n1. *Der Bruder meiner Freundin schenkt seinem Vater ein Buch.*\n2. *Ich habe kein Auto.*\n3. *Wir sprechen mit den Nachbarn.*\n4. *Jeder Schüler kennt diesen Lehrer.*\n5. *Das Haus der Familie ist groß.*\n\n**2. Cas des groupes en gras**\n- *meiner Freundin* : **génitif** féminin, complément du nom *Bruder*.\n- *seinem Vater* : **datif**, COI de *schenken*.\n- *kein Auto* : **accusatif** neutre, COD (même forme qu'au nominatif).\n- *den Nachbarn* : **datif pluriel** après *mit* (le nom a déjà son -n).\n- *Jeder Schüler* : **nominatif**, sujet.\n- *diesen Lehrer* : **accusatif** masculin, COD — *dieser* prend les terminaisons de l'article.\n- *der Familie* : **génitif** féminin, complément du nom *Haus* ; au féminin, pas de marque sur le nom."}$exo$::jsonb),
  ('a28694ba-8eae-53e7-b76c-3c83f827fc2f'::uuid, 1, 'traduction', $exo${"titre":"Remplacer par un pronom","consigne":"Remplace le groupe en gras par le pronom personnel qui convient.","enonce":"**Remplace le groupe en gras par un pronom.**\n\n1. **Der Tisch** ist alt.\n2. Ich sehe **den Lehrer**.\n3. Ich helfe **meiner Schwester**.\n4. **Die Lampe** ist neu.\n5. Wir danken **den Eltern**.\n6. Ich kaufe **das Buch**.","bareme":[{"critere":"Genre grammatical conservé (er pour der Tisch, sie pour die Lampe)","points":8},{"critere":"Cas juste : ihn, ihr, ihnen, es","points":8},{"critere":"Phrases correctement recopiées (majuscule, ordre)","points":4}],"dureeMin":6,"corrige":"**Réponses**\n\n1. *Er ist alt.* — *der Tisch* est masculin → *er*, même pour un objet.\n2. *Ich sehe ihn.* — masculin, COD → accusatif *ihn*.\n3. *Ich helfe ihr.* — féminin, *helfen* régit le datif → *ihr*.\n4. *Sie ist neu.* — *die Lampe* est féminin → *sie*.\n5. *Wir danken ihnen.* — pluriel, *danken* régit le datif → *ihnen*.\n6. *Ich kaufe es.* — neutre, COD → *es*.\n\nRègle : le pronom garde le **genre grammatical** du nom et prend le **cas** de sa fonction. Traduire mécaniquement une chose par *es* est une faute : en allemand, une table est « il »."}$exo$::jsonb),
  ('a28694ba-8eae-53e7-b76c-3c83f827fc2f'::uuid, 2, 'traduction', $exo${"titre":"Deux pronoms dans la phrase","consigne":"Remplace les deux compléments par des pronoms (phrases 1 à 3), puis traduis les phrases 4 et 5.","enonce":"**Remplace les deux compléments par des pronoms.**\n\n1. Ich gebe dem Kind das Buch.\n2. Er schenkt seiner Mutter die Blumen.\n3. Wir zeigen den Gästen das Haus.\n\n**Traduis.**\n\n4. Hier, mon père m'a appelé. (*commence par Gestern ; anrufen*)\n5. Je vous remercie, Monsieur Braun. (*vouvoiement ; danken + datif*)","bareme":[{"critere":"Formes des pronoms justes (es, ihm, sie, ihr, ihnen, mich)","points":6},{"critere":"Ordre des deux pronoms : accusatif puis datif","points":6},{"critere":"Pronom placé juste après le verbe, avant le sujet nominal","points":4},{"critere":"Ihnen de politesse avec majuscule","points":4}],"dureeMin":10,"corrige":"1. *Ich gebe es ihm.*\n2. *Er schenkt sie ihr.*\n3. *Wir zeigen es ihnen.*\n4. *Gestern hat mich mein Vater angerufen.*\n5. *Ich danke Ihnen, Herr Braun.*\n\nPoints attendus :\n- Avec deux groupes nominaux, l'ordre est datif puis accusatif ; avec deux **pronoms**, c'est **accusatif puis datif** : *es ihm*, *sie ihr*, *es ihnen*. *Ich gebe ihm es* est faux.\n- *das Buch* → *es* ; *die Blumen* (pluriel) → *sie* ; *seiner Mutter* → *ihr* ; *den Gästen* → *ihnen*.\n- Phrase 4 : les pronoms remontent juste après le verbe conjugué ; en cas d'inversion, le pronom *mich* peut précéder le sujet nominal *mein Vater*.\n- Phrase 5 : *Sie* de politesse → datif *Ihnen*, toujours avec majuscule."}$exo$::jsonb),
  ('a28694ba-8eae-53e7-b76c-3c83f827fc2f'::uuid, 3, 'traduction', $exo${"titre":"Une lettre à Anna","consigne":"Traduis la lettre en allemand, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n> Chère Anna, merci pour ta lettre ! Je l'ai lue hier. Mon frère te salue. Il a un nouveau vélo : il est rouge. Mes parents t'invitent : tu peux venir chez nous en été. Est-ce que tu veux leur écrire ?\n\n*Aide : Liebe Anna ; danke für + accusatif ; der Brief ; lesen (gelesen) ; grüßen ; ein neues Fahrrad ; einladen (séparable) ; zu uns ; im Sommer ; schreiben + datif.*\n\n**2.** Explique en français pourquoi « je **l'**ai lue » se traduit par *ihn* et « **il** est rouge » par *es*.","bareme":[{"critere":"Pronoms reprenant le genre du nom : ihn (Brief), es (Fahrrad)","points":5},{"critere":"Cas justes : dich, ihnen, uns","points":5},{"critere":"Place des pronoms et du préverbe ein en fin de phrase","points":3},{"critere":"Phrases correctes (verbes, possessifs, ponctuation)","points":3},{"critere":"Explication juste du choix ihn / es","points":4}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n> *Liebe Anna, danke für deinen Brief! Ich habe ihn gestern gelesen. Mein Bruder grüßt dich. Er hat ein neues Fahrrad: Es ist rot. Meine Eltern laden dich ein: Du kannst im Sommer zu uns kommen. Willst du ihnen schreiben?*\n\nPoints attendus :\n- *deinen Brief* : *für* + accusatif, masculin.\n- *ihn* : reprend *der Brief* (masculin), COD → accusatif.\n- *dich* : COD de *grüßen* et de *einladen* ; le préverbe *ein* ferme la phrase.\n- *es* : reprend *das Fahrrad* (neutre), sujet.\n- *ihnen* : datif pluriel (« à eux »), COI de *schreiben* ; minuscule, car ce n'est pas le vouvoiement.\n- Majuscule au début de la phrase après les deux-points (*Es ist rot*, *Du kannst*) acceptée ou minuscule tolérée.\n\n**2.** Le pronom allemand garde le **genre grammatical** du nom qu'il remplace, pas celui du français. *Der Brief* (la lettre) est masculin : on le reprend par *ihn* à l'accusatif. *Das Fahrrad* (le vélo) est neutre : on le reprend par *es*."}$exo$::jsonb),
  ('30f683c9-1587-515c-8fe8-f285b2c5bae1'::uuid, 1, 'traduction', $exo${"titre":"Dieser, et das ou dass","consigne":"Complète les phrases 1 à 5 avec la bonne forme de dieser, puis les phrases 6 et 7 avec das ou dass.","enonce":"**Complète avec dieser à la bonne forme.**\n\n1. ___ Mann ist mein Nachbar.\n2. Ich kenne ___ Frau nicht.\n3. Ich wohne in ___ Haus.\n4. Kaufst du ___ Rock? (*der Rock*)\n5. Das Auto ___ Mannes ist neu.\n\n**Complète avec das ou dass.**\n\n6. Ich glaube, ___ er kommt.\n7. ___ ist mein Bruder.","bareme":[{"critere":"Formes de dieser justes selon genre et cas","points":12},{"critere":"Choix juste entre das et dass","points":8}],"dureeMin":6,"corrige":"**Réponses**\n\n1. *Dieser Mann* — nominatif masculin.\n2. *diese Frau* — accusatif féminin.\n3. *in diesem Haus* — datif neutre (lieu où l'on est).\n4. *diesen Rock* — accusatif masculin.\n5. *dieses Mannes* — génitif masculin.\n6. *Ich glaube, dass er kommt.* — conjonction qui introduit une subordonnée.\n7. *Das ist mein Bruder.* — démonstratif invariable.\n\nPoints attendus : *dieser* se décline comme l'article défini (*der → dieser*, *den → diesen*, *dem → diesem*, *des → dieses*). Test pour *das* / *dass* : si l'on peut remplacer par *dieses*, c'est *das* avec un seul s ; sinon, c'est la conjonction *dass*."}$exo$::jsonb),
  ('30f683c9-1587-515c-8fe8-f285b2c5bae1'::uuid, 2, 'traduction', $exo${"titre":"Celui-là, le même","consigne":"Réponds aux cinq questions.","enonce":"**Complète la réponse avec le démonstratif accentué.**\n\n1. — Kennst du Peter? — Ja, ___ kenne ich gut!\n2. — Magst du die Lehrerin? — Ja, ___ mag ich.\n3. — Hilfst du den Nachbarn? — Ja, ___ helfe ich gern.\n\n4. Réécris pour dire clairement qu'il s'agit du frère **de Paul** : *Ich traf Paul und seinen Bruder.*\n5. Traduis : « Nous habitons dans la même maison. » et « Elle a la même robe que moi. » Explique en une phrase pourquoi tu n'emploies pas le même mot.","bareme":[{"critere":"Démonstratifs accentués justes (den, die, denen)","points":6},{"critere":"Emploi de dessen pour lever l'ambiguïté","points":4},{"critere":"derselbe décliné et der gleiche employés à bon escient","points":6},{"critere":"Explication juste : identique ou semblable","points":4}],"dureeMin":10,"corrige":"1. *Den kenne ich gut!* — masculin, COD → *den*.\n2. *Die mag ich.* — féminin, COD → *die*.\n3. *Denen helfe ich gern.* — pluriel, *helfen* + datif → *denen* (forme propre au démonstratif).\n4. *Ich traf Paul und dessen Bruder.* — *dessen* désigne sans équivoque le frère de Paul (*seinen* pouvait renvoyer au sujet).\n5. *Wir wohnen in demselben Haus.* / *Sie hat das gleiche Kleid wie ich.*\n\nExplication : *derselbe* désigne un objet **identique**, unique (une seule maison) ; *der gleiche* désigne un objet **semblable** (deux robes pareilles). Dans *derselbe*, les deux morceaux se déclinent : *dem-* comme l'article (datif après *in*), *-selben* comme un adjectif faible."}$exo$::jsonb),
  ('30f683c9-1587-515c-8fe8-f285b2c5bae1'::uuid, 3, 'traduction', $exo${"titre":"Dialogue dans la cour","consigne":"Traduis ce dialogue en allemand en employant les démonstratifs, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n— Tu vois ce garçon ?\n— Celui-là ? Je le connais : c'est le frère de Lisa.\n— Et la jeune fille à côté de lui ?\n— Celle-là, je ne la connais pas. Mais Lisa et sa sœur (la sœur de Lisa) habitent dans la même rue que moi.\n— Ce sont mes amies !\n\n*Aide : der Junge (accusatif den Jungen) ; das Mädchen ; neben + datif ; die Straße ; die Freundin.*\n\n**2.** Explique en français ton choix de *das* pour « celle-là » et de *deren* pour « sa sœur ».","bareme":[{"critere":"dieser et démonstratifs accentués justes (diesen, den, das)","points":5},{"critere":"deren pour lever l'ambiguïté sur la sœur","points":3},{"critere":"derselben Straße décliné au datif","points":3},{"critere":"Das sind … : verbe accordé avec ce qui suit","points":3},{"critere":"Justification de das et de deren","points":6}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n— *Siehst du diesen Jungen?*\n— *Den da? Den kenne ich: Das ist der Bruder von Lisa.* (*Lisas Bruder* accepté)\n— *Und das Mädchen neben ihm?*\n— *Das kenne ich nicht. Aber Lisa und deren Schwester wohnen in derselben Straße wie ich.*\n— *Das sind meine Freundinnen!*\n\nPoints attendus :\n- *diesen Jungen* : accusatif masculin ; *Den* : démonstratif accentué, masculin accusatif.\n- *Das ist…* et *Das sind…* : *das* invariable, le verbe s'accorde avec ce qui suit (*sind* devant un pluriel).\n- *in derselben Straße* : lieu où l'on est → datif, *der-* + *-selben*.\n- *neben ihm* : datif (localisation).\n\n**2.** *Das* : le démonstratif reprend le genre du nom ; *Mädchen* est **neutre**, donc *das* à l'accusatif, même s'il s'agit d'une fille. *deren* : génitif féminin du démonstratif, il renvoie sans équivoque à Lisa ; *ihre Schwester* serait possible mais moins précis dans une phrase à plusieurs personnes. C'est un usage soigné, apprécié à l'écrit."}$exo$::jsonb),
  ('33e8d4d0-5347-507f-b7a7-1cafa928b2c3'::uuid, 1, 'traduction', $exo${"titre":"Huit pluriels","consigne":"Donne le pluriel de chaque nom avec son article, puis indique pour trois d'entre eux le schéma de pluriel.","enonce":"**1. Donne le pluriel avec l'article.**\n\nder Tag · das Kind · die Frau · der Lehrer · das Auto · die Lehrerin · der Sohn · das Buch\n\n**2.** Pour *Frau*, *Lehrer* et *Auto*, nomme le schéma de pluriel (terminaison ajoutée ou absence de terminaison).","bareme":[{"critere":"Huit pluriels justes, Umlaut compris","points":14},{"critere":"Article die au pluriel pour tous les noms","points":2},{"critere":"Schémas justes pour les trois noms","points":4}],"dureeMin":6,"corrige":"**1. Pluriels**\n\n- *die Tage* (-e)\n- *die Kinder* (-er)\n- *die Frauen* (-en)\n- *die Lehrer* (aucune terminaison)\n- *die Autos* (-s)\n- *die Lehrerinnen* (-nen : le n est doublé)\n- *die Söhne* (-e avec Umlaut)\n- *die Bücher* (-er avec Umlaut)\n\nAu pluriel, l'article défini est **die** pour les trois genres.\n\n**2.** *Frau* : schéma en **-(e)n**, celui de presque tous les féminins, sans inflexion. *Lehrer* : **aucune terminaison** (masculin en -er). *Auto* : **-s**, schéma des emprunts et abréviations."}$exo$::jsonb),
  ('33e8d4d0-5347-507f-b7a7-1cafa928b2c3'::uuid, 2, 'traduction', $exo${"titre":"Tout au pluriel","consigne":"Mets chaque phrase entièrement au pluriel (sujet, verbe et complément).","enonce":"**Mets au pluriel.**\n\n1. Das Kind spielt mit dem Ball.\n2. Die Zeitung liegt auf dem Tisch.\n3. Der Lehrer spricht mit der Schülerin.\n4. Das Auto steht vor dem Haus.\n\n*Aide : der Ball → die Bälle ; der Tisch → die Tische ; das Haus → die Häuser ; die Schülerin → die Schülerinnen.*","bareme":[{"critere":"Pluriels des noms justes","points":8},{"critere":"-n du datif pluriel ajouté, sauf après -s (Autos)","points":6},{"critere":"Verbes accordés et articles die / den justes","points":6}],"dureeMin":11,"corrige":"**Phrases attendues**\n\n1. *Die Kinder spielen mit den Bällen.*\n2. *Die Zeitungen liegen auf den Tischen.*\n3. *Die Lehrer sprechen mit den Schülerinnen.*\n4. *Die Autos stehen vor den Häusern.*\n\nPoints attendus :\n- Sujets au pluriel avec *die* : *Kinder*, *Zeitungen*, *Lehrer* (sans terminaison), *Autos*.\n- Verbes à la 3e personne du pluriel : *spielen*, *liegen*, *sprechen*, *stehen*.\n- Datif pluriel : article *den*, et le nom prend **-n** s'il n'en a pas déjà un : *Bällen*, *Tischen*, *Häusern* ; *Schülerinnen* et *Zeitungen* finissent déjà par n.\n- Exception : pas de -n après un pluriel en -s (*mit den Autos*)."}$exo$::jsonb),
  ('33e8d4d0-5347-507f-b7a7-1cafa928b2c3'::uuid, 3, 'traduction', $exo${"titre":"Thème : singuliers et pluriels trompeurs","consigne":"Traduis les phrases en allemand, puis explique trois pièges.","enonce":"**1. Traduis en allemand.**\n\n1. Mon père porte des lunettes.\n2. Les enfants jouent avec les chats des voisins.\n3. La police arrive avec deux voitures.\n4. Les fruits sont frais.\n5. Les gens sont gentils.\n\n*Aide : tragen ; die Katze ; der Nachbar (pluriel die Nachbarn) ; kommen ; das Auto ; frisch ; nett.*\n\n**2.** Explique en français les trois pièges des phrases 1, 3 et 4.","bareme":[{"critere":"eine Brille et das Obst au singulier, verbe accordé","points":5},{"critere":"Pluriels justes : Kinder, Katzen, Nachbarn, Autos, Leute","points":5},{"critere":"Datif pluriel et génitif pluriel corrects","points":4},{"critere":"Explication des trois pièges","points":6}],"dureeMin":15,"corrige":"**1. Traduction modèle**\n\n1. *Mein Vater trägt eine Brille.*\n2. *Die Kinder spielen mit den Katzen der Nachbarn.*\n3. *Die Polizei kommt mit zwei Autos.*\n4. *Das Obst ist frisch.*\n5. *Die Leute sind nett.*\n\nPoints attendus :\n- *mit den Katzen* : datif pluriel (le nom finit déjà par n) ; *der Nachbarn* : génitif pluriel (article *der*).\n- *die Leute* n'existe qu'au pluriel : verbe *sind*.\n- *die Polizei* est un singulier : verbe *kommt*.\n\n**2. Les pièges**\n- Phrase 1 : l'allemand met au **singulier** ce que le français met au pluriel : « des lunettes » = *eine Brille*.\n- Phrase 3 : *Autos* est un pluriel en -s : au datif pluriel, il ne prend **pas** de -n (*mit zwei Autos*).\n- Phrase 4 : *das Obst* n'existe qu'au singulier : « les fruits sont » → *das Obst ist*."}$exo$::jsonb),
  ('8ac8fba3-6ef4-59d4-b1bf-8840c1cacf0c'::uuid, 1, 'traduction', $exo${"titre":"L'attribut ne bouge pas","consigne":"Corrige l'erreur de chaque phrase, puis réponds à la question 2.","enonce":"**1. Corrige chaque phrase.**\n\n1. Die Frau ist alte.\n2. Das Wetter ist schönes.\n3. Die Kinder sind müden.\n4. Das Haus wird großes.\n5. Er singt schöne.\n\n**2.** Dans *Ein alter Mann ist gekommen* et *Der Mann ist alt*, pourquoi l'adjectif n'a-t-il pas la même forme ?","bareme":[{"critere":"Cinq phrases corrigées avec l'adjectif à sa forme nue","points":12},{"critere":"Explication juste : épithète déclinée, attribut invariable","points":8}],"dureeMin":6,"corrige":"**1. Phrases corrigées**\n\n1. *Die Frau ist alt.*\n2. *Das Wetter ist schön.*\n3. *Die Kinder sind müde.* (*müde* se termine déjà par e : c'est sa forme nue)\n4. *Das Haus wird groß.*\n5. *Er singt schön.* — ici, *schön* est un **adverbe** : l'allemand n'a pas de terminaison d'adverbe, le mot reste invariable.\n\nAprès *sein*, *werden* et *bleiben*, l'adjectif attribut reste à sa forme nue : ni -e, ni -er, rien.\n\n**2.** Tout dépend de la **place** de l'adjectif. Dans *Ein alter Mann*, il est **épithète** (devant le nom) : il se décline toujours. Dans *Der Mann ist alt*, il est **attribut** (après le verbe *sein*) : il ne se décline jamais."}$exo$::jsonb),
  ('8ac8fba3-6ef4-59d4-b1bf-8840c1cacf0c'::uuid, 2, 'traduction', $exo${"titre":"Thème : attributs et adverbes","consigne":"Traduis les cinq phrases en allemand.","enonce":"**Traduis en allemand.**\n\n1. La maison est grande et belle.\n2. Ma sœur devient impatiente.\n3. Il chante bien.\n4. Je trouve ce film intéressant.\n5. Le train est plus rapide que la voiture.\n\n*Aide : das Haus ; ungeduldig ; singen ; schön ; der Film ; interessant ; der Zug ; schnell ; das Auto.*","bareme":[{"critere":"Adjectifs attributs invariables après sein et werden","points":8},{"critere":"Adverbe invariable (schön ou gut)","points":3},{"critere":"finden + COD + attribut invariable","points":4},{"critere":"Comparatif en -er suivi de als","points":5}],"dureeMin":10,"corrige":"**Traduction modèle**\n\n1. *Das Haus ist groß und schön.*\n2. *Meine Schwester wird ungeduldig.*\n3. *Er singt schön.* (*gut* accepté)\n4. *Ich finde diesen Film interessant.*\n5. *Der Zug ist schneller als das Auto.*\n\nPoints attendus :\n- Phrases 1 et 2 : l'attribut ne s'accorde pas, même au féminin (*ungeduldig*, pas *ungeduldige*).\n- Phrase 3 : l'allemand n'a pas de terminaison d'adverbe comme -ment : le même mot sert d'adjectif et d'adverbe.\n- Phrase 4 : *finden* + COD appelle un attribut, invariable ; *diesen Film* à l'accusatif.\n- Phrase 5 : la terminaison -er est la marque du **comparatif**, pas un accord ; « que » = *als*."}$exo$::jsonb),
  ('8ac8fba3-6ef4-59d4-b1bf-8840c1cacf0c'::uuid, 3, 'traduction', $exo${"titre":"Le portrait de Klara","consigne":"À partir de la fiche, écris le portrait de Klara en six phrases. Emploie les adjectifs comme attributs (après sein, werden, bleiben) et au moins un comparatif. Puis réponds à la question 2.","enonce":"**1. Écris le portrait (six phrases).**\n\n**Fiche de Klara**\n- ta meilleure amie, 15 ans\n- grande et sportive\n- parfois impatiente\n- reste calme pendant les examens\n- chante bien\n- plus rapide que son frère\n\n*Aide : groß ; sportlich ; ungeduldig ; ruhig ; die Prüfung ; singen ; schnell ; der Bruder.*\n\n**2.** Un camarade écrit *Klara ist große*. Explique-lui son erreur en français.","bareme":[{"critere":"Attributs invariables après sein et bleiben","points":7},{"critere":"Adverbe invariable pour chanter","points":2},{"critere":"Comparatif avec als correct","points":3},{"critere":"Phrases correctes : verbe en 2e position, inversion","points":4},{"critere":"Explication juste de l'erreur","points":4}],"dureeMin":15,"corrige":"**1. Portrait modèle**\n\n*Meine beste Freundin heißt Klara. Sie ist fünfzehn Jahre alt. Sie ist groß und sportlich. Manchmal ist sie ungeduldig, aber in den Prüfungen bleibt sie ruhig. Sie singt schön. Sie ist schneller als ihr Bruder.*\n\nPoints attendus :\n- *groß*, *sportlich*, *ungeduldig*, *ruhig* : attributs après *sein* ou *bleiben* → forme nue, sans terminaison.\n- *singt schön* (ou *gut*) : adverbe invariable.\n- *schneller als* : comparatif en -er + *als*.\n- Inversion après *Manchmal* et *in den Prüfungen* (verbe en 2e position).\n- *Meine beste Freundin* : épithète déclinée devant le nom, acceptée.\n\n**2.** Après *sein*, l'adjectif est **attribut** : il ne se décline jamais, même quand le sujet est féminin. Il faut écrire *Klara ist groß*. La terminaison n'apparaît que si l'adjectif est placé **devant** le nom (*eine große Freundin*)."}$exo$::jsonb),
  ('94371d4d-0c80-5235-a5b4-d9764ea8a9c0'::uuid, 1, 'traduction', $exo${"titre":"Les terminaisons de l'épithète","consigne":"Complète la terminaison de chaque adjectif.","enonce":"**Complète la terminaison (nominatif sauf indication).**\n\n1. der alt__ Mann\n2. ein alt__ Mann\n3. ein alt__ Haus\n4. mit dem neu__ Auto\n5. kalt__ Kaffee (sans déterminant)\n6. eine schön__ Blume\n\n*Rappel : der Mann, das Haus, das Auto, der Kaffee, die Blume.*","bareme":[{"critere":"Déclinaison faible après der / dem (-e, -en)","points":6},{"critere":"Déclinaison mixte après ein / eine (-er, -es, -e)","points":8},{"critere":"Déclinaison forte sans déterminant (-er)","points":6}],"dureeMin":7,"corrige":"**Réponses**\n\n1. *der alte Mann* — faible : *der* marque déjà le cas → -e.\n2. *ein alter Mann* — mixte : *ein* ne marque pas le masculin → l'adjectif prend -er.\n3. *ein altes Haus* — mixte : *ein* ne marque pas le neutre → -es.\n4. *mit dem neuen Auto* — faible au datif → -en.\n5. *kalter Kaffee* — forte : aucun déterminant, l'adjectif prend la marque de l'article (*der* → -er).\n6. *eine schöne Blume* — *eine* marque déjà le féminin → terminaison faible -e.\n\nPrincipe : la marque du cas apparaît **une fois** dans le groupe ; si le déterminant la porte, l'adjectif se contente de -e ou -en."}$exo$::jsonb),
  ('94371d4d-0c80-5235-a5b4-d9764ea8a9c0'::uuid, 2, 'traduction', $exo${"titre":"Le nouvel ami","consigne":"Complète les terminaisons du texte, puis justifie deux de tes choix.","enonce":"**1. Complète les terminaisons.**\n\n> Ich habe einen neu__ Freund. Er wohnt in einem groß__ Haus mit einem schön__ Garten. Sein klein__ Bruder spielt mit einem rot__ Ball. Er hat ein teu__ Fahrrad (*teuer*). Morgen fahren wir mit dem neu__ Zug nach Berlin.\n\n*Rappel : der Freund, das Haus, der Garten, der Bruder, der Ball, das Fahrrad, der Zug.*\n\n**2.** Justifie en français la terminaison de *klein__ Bruder* et celle de *teu__ Fahrrad*.","bareme":[{"critere":"Terminaisons -en justes à l'accusatif et au datif","points":8},{"critere":"Nominatif masculin après sein : kleiner","points":3},{"critere":"Forme teures, sans le e de teuer","points":3},{"critere":"Faible après dem : neuen","points":3},{"critere":"Deux justifications justes","points":3}],"dureeMin":11,"corrige":"**1. Texte complété**\n\n> *Ich habe einen neuen Freund. Er wohnt in einem großen Haus mit einem schönen Garten. Sein kleiner Bruder spielt mit einem roten Ball. Er hat ein teures Fahrrad. Morgen fahren wir mit dem neuen Zug nach Berlin.*\n\nPoints attendus :\n- *einen neuen* (accusatif masculin), *einem großen*, *einem schönen*, *einem roten* (datif) : le déterminant marque le cas → -en.\n- *dem neuen Zug* : déclinaison faible au datif → -en.\n\n**2.** *kleiner Bruder* : *Bruder* est masculin et sujet (nominatif) ; le possessif *sein* se décline comme *ein* et ne marque rien au nominatif masculin → l'adjectif prend la marque -er. *teures Fahrrad* : *Fahrrad* est neutre, COD (accusatif) ; *ein* ne marque pas le neutre → -es ; et *teuer* perd son e devant la terminaison : *teures*, jamais *teueres*."}$exo$::jsonb),
  ('94371d4d-0c80-5235-a5b4-d9764ea8a9c0'::uuid, 3, 'traduction', $exo${"titre":"Thème : le vieil homme de la montagne","consigne":"Traduis le texte en allemand, puis explique ta méthode pour deux groupes nominaux.","enonce":"**1. Traduis en allemand.**\n\n> Un vieil homme habite dans une petite maison au pied d'une haute montagne. Il boit du café froid et mange du bon pain. Sa fille porte une robe rose. Le vieil homme aime les longues promenades.\n\n*Aide : alt ; klein ; am Fuß + génitif ; hoch ; der Berg ; kalt ; gut ; das Brot ; die Tochter ; tragen ; rosa ; das Kleid ; lang ; der Spaziergang (pluriel die Spaziergänge) ; lieben.*\n\n**2.** Explique en français comment tu as trouvé la terminaison de *kalt…* devant *Kaffee* et la forme de *hoch* devant *Berg*.","bareme":[{"critere":"Déclinaisons mixte et faible justes (alter, kleinen, alte)","points":5},{"critere":"Déclinaison forte sans déterminant (kalten, gutes, lange)","points":5},{"critere":"Irréguliers et invariables : hohen, rosa","points":4},{"critere":"Méthode expliquée : cas et genre, puis déterminant","points":6}],"dureeMin":18,"corrige":"**1. Traduction modèle**\n\n> *Ein alter Mann wohnt in einem kleinen Haus am Fuß eines hohen Berges. Er trinkt kalten Kaffee und isst gutes Brot. Seine Tochter trägt ein rosa Kleid. Der alte Mann liebt lange Spaziergänge.*\n\nPoints attendus :\n- *ein alter Mann* (nominatif, mixte) ; *einem kleinen Haus* (datif) ; *eines hohen Berges* (génitif) ; *der alte Mann* (faible).\n- *kalten Kaffee*, *gutes Brot*, *lange Spaziergänge* : aucun déterminant → déclinaison forte, terminaisons de l'article défini (*den*, *das*, *die*).\n- *hoch* perd son c : *hohen*.\n- *rosa* est invariable : *ein rosa Kleid*.\n- *an einem hohen Berg* accepté pour « au pied de ».\n\n**2.** Méthode : repérer d'abord le **cas et le genre**, puis regarder le déterminant. *Kaffee* est masculin, COD → accusatif ; il n'y a aucun déterminant, donc l'adjectif porte la marque de l'article *den* → *kalten*. *Berg* est masculin, au génitif après *eines*, qui marque déjà le cas → terminaison -en ; et *hoch* perd son c devant une terminaison → *hohen*."}$exo$::jsonb),
  ('9bdc55ab-472a-5b40-a9a7-57493a655b50'::uuid, 1, 'traduction', $exo${"titre":"Sein ou ihr ?","consigne":"Complète chaque phrase avec le possessif qui convient, bien décliné, puis réponds à la question 2 en français.","enonce":"**1. Complète avec le possessif.**\n\n1. Anna besucht ___ Großmutter. *(sa grand-mère, à elle)*\n2. Peter ruft ___ Vater an. *(son père, à lui — accusatif)*\n3. Das Kind spielt mit ___ Hund. *(son chien — datif)*\n4. Wir fahren mit ___ Auto. *(notre voiture — datif, das Auto)*\n5. Die Kinder und ___ Eltern kommen heute. *(leurs parents)*\n6. Herr Klein, ist das ___ Buch? *(votre livre, politesse)*\n\n**2.** Explique en une ou deux phrases pourquoi on écrit *ihre* dans la phrase 1 et *seinen* dans la phrase 2.","bareme":[{"critere":"Radical juste selon le possesseur : ihr- (1, 5), sein- (2, 3), unser- (4), Ihr- avec majuscule (6)","points":8},{"critere":"Terminaisons justes selon l'objet possédé : ihre, seinen, seinem, unserem, ihre, Ihr","points":8},{"critere":"Explication : radical commandé par le possesseur, terminaison par le genre et le cas du nom","points":4}],"dureeMin":6,"corrige":"**1.**\n1. Anna besucht **ihre** Großmutter. — possesseur féminin (Anna) → *ihr-* ; *Großmutter* féminin → *-e*.\n2. Peter ruft **seinen** Vater an. — possesseur masculin → *sein-* ; *Vater* masculin à l'accusatif → *-en*.\n3. Das Kind spielt mit **seinem** Hund. — *Kind* est neutre → *sein-* ; *mit* + datif masculin → *-em*.\n4. Wir fahren mit **unserem** Auto. — *unser* garde son e ; datif neutre → *-em*.\n5. Die Kinder und **ihre** Eltern kommen heute. — *ihr* = leur ; pluriel nominatif → *-e*.\n6. Herr Klein, ist das **Ihr** Buch? — vouvoiement → *Ihr* avec majuscule ; *Buch* neutre nominatif → pas de terminaison.\n\n**2.** Le **radical** dépend du **possesseur** : Anna est une femme → *ihr-*, Peter est un homme → *sein-*. La **terminaison** dépend du **nom possédé** : *Großmutter* est féminin → *ihre* ; *Vater* est masculin et COD (accusatif) → *seinen*. Le possessif se décline comme *ein* / *kein*."}$exo$::jsonb),
  ('9bdc55ab-472a-5b40-a9a7-57493a655b50'::uuid, 2, 'traduction', $exo${"titre":"Léna présente sa famille","consigne":"Léna prépare une présentation de sa famille pour son correspondant allemand. Traduis ses phrases en allemand, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n1. Mon frère et sa copine habitent à Berlin.\n2. Ma sœur aime son chat.\n3. Nos voisins et leur fils viennent ce soir.\n4. Les enfants, où est votre professeur ?\n5. Les enfants, j'ai vu votre mère.\n6. Le matin, je me lave les mains.\n\n*Aide : die Freundin = la copine ; die Katze = le chat ; der Nachbar, die Nachbarn = le voisin ; der Sohn = le fils ; der Lehrer = le professeur ; ich habe … gesehen = j'ai vu ; heute Abend = ce soir ; morgens = le matin ; waschen = laver.*\n\n**2.** Dans les phrases 4 et 5, le possessif change de forme. Explique pourquoi.","bareme":[{"critere":"Radical sein- / ihr- choisi selon le possesseur (phrases 1, 2, 3)","points":6},{"critere":"Terminaisons justes selon le genre et le cas : seine, ihre, ihr Sohn, euer, eure","points":6},{"critere":"Phrase 6 construite avec le datif et l'article : mir die Hände","points":4},{"critere":"Explication : euer devient eur- devant une terminaison","points":4}],"dureeMin":10,"corrige":"**1. Traduction modèle**\n\n1. *Mein Bruder und **seine** Freundin wohnen in Berlin.* — possesseur masculin → *sein-* ; *Freundin* féminin → *-e*.\n2. *Meine Schwester liebt **ihre** Katze.* — possesseur féminin → *ihr-* ; *Katze* féminin accusatif → *-e*.\n3. *Unsere Nachbarn und **ihr** Sohn kommen heute Abend.* — *ihr* = leur ; *Sohn* masculin nominatif → pas de terminaison.\n4. *Kinder, wo ist **euer** Lehrer?* — *euer* sans terminaison (masculin nominatif).\n5. *Kinder, ich habe **eure** Mutter gesehen.* — *Mutter* féminin → terminaison *-e* → *eure*.\n6. *Morgens wasche ich **mir die** Hände.* (ou *Ich wasche mir morgens die Hände.*) — avec les parties du corps, l'allemand emploie l'article + un datif, pas le possessif.\n\n**2.** *euer* perd son second e dès qu'il reçoit une terminaison : *euer Lehrer* (pas de terminaison) mais *eure Mutter*, *euren Vater*. À l'inverse, *unser* garde son e : *unsere Nachbarn*."}$exo$::jsonb),
  ('9bdc55ab-472a-5b40-a9a7-57493a655b50'::uuid, 3, 'traduction', $exo${"titre":"Le texte de Sophie à corriger","consigne":"Lis le texte de Sophie, corrige ses fautes en justifiant, puis traduis les phrases de la question 3.","enonce":"**Document — Sophie parle de son frère Paul**\n\n> Mein Bruder Paul hat einen Hund. Ihr Hund heißt Rex. Paul spielt jeden Tag mit sein Hund. Nach dem Spiel wasche ich meine Hände. Meine Eltern und ihre Freunde kommen am Samstag. „Ist das dein Ball?“ – „Nein, das ist nicht mein, das ist Pauls Ball.“\n\n1. Le texte contient **quatre** fautes sur le possessif. Relève-les, corrige-les et justifie chaque correction.\n2. Un camarade pense que *ihre Freunde* est aussi une faute. A-t-il raison ? Explique.\n3. Traduis en allemand :\n   - a. Julia et son frère aiment leur chien.\n   - b. — À qui est ce livre ? — C'est le mien.\n\n*Aide : der Ball ; das Buch ; lieben = aimer.*","bareme":[{"critere":"Les quatre fautes relevées et corrigées : Sein Hund, seinem Hund, mir die Hände, meiner","points":8},{"critere":"Justifications : possesseur, datif après mit, tournure article + datif, possessif employé seul","points":4},{"critere":"ihre Freunde reconnu correct : ihr = leur, pluriel","points":3},{"critere":"Traductions justes : ihr Bruder, ihren Hund, Wessen, meins","points":5}],"dureeMin":16,"corrige":"**1. Les quatre fautes**\n- *Ihr Hund* → **Sein Hund** : le possesseur est Paul, un homme → radical *sein-*.\n- *mit sein Hund* → **mit seinem Hund** : *mit* impose le datif ; *Hund* masculin → *-em*.\n- *wasche ich meine Hände* → **wasche ich mir die Hände** : avec les parties du corps, l'allemand n'emploie pas le possessif mais l'article + un pronom au datif.\n- *das ist nicht mein* → **das ist nicht meiner** : employé seul, le possessif prend les terminaisons de l'article défini ; *Ball* est masculin (*der*) → *meiner*.\n\n**2.** Non. *ihre Freunde* est correct : *ihr* signifie ici **leur** (les amis de mes parents), et *Freunde* est un pluriel → terminaison *-e*.\n\n**3.**\n- a. *Julia und **ihr** Bruder lieben **ihren** Hund.* — Julia est une femme → *ihr Bruder* ; « leur chien » → *ihr-*, *Hund* masculin accusatif → *ihren*.\n- b. *— **Wessen** Buch ist das? — Das ist **meins** (meines).* — *Buch* neutre (*das*) → possessif seul *mein(e)s*."}$exo$::jsonb),
  ('8c3bf0b0-bf2d-5cbb-ac85-dd6466cb04f1'::uuid, 1, 'traduction', $exo${"titre":"À qui est-ce ?","consigne":"Transforme chaque groupe avec von en génitif, puis réponds à la question 2 par une phrase complète.","enonce":"**1. Transforme au génitif.** Utilise le génitif saxon pour les noms propres, le génitif ordinaire pour les autres.\n\n1. das Auto von Peter\n2. das Fahrrad von Anna\n3. das Haus von dem Vater\n4. die Tasche von der Lehrerin\n5. das Zimmer von dem Kind\n6. die Spielsachen von den Kindern\n\n**2.** Pose la question qui correspond à « à qui est ce cahier ? » en allemand, puis réponds que c'est le cahier de Maria. *(das Heft = le cahier)*","bareme":[{"critere":"Génitif saxon sans article ni apostrophe : Peters Auto, Annas Fahrrad","points":5},{"critere":"Masculin et neutre : des + nom en -(e)s (des Vaters, des Kindes)","points":6},{"critere":"Féminin et pluriel : der sans marque sur le nom (der Lehrerin, der Kinder)","points":5},{"critere":"Question avec Wessen et réponse Marias Heft","points":4}],"dureeMin":6,"corrige":"**1.**\n1. **Peters Auto** — nom propre placé devant, -s sans apostrophe, aucun article.\n2. **Annas Fahrrad**\n3. **das Haus des Vaters** — masculin : article *des*, le nom prend *-s*.\n4. **die Tasche der Lehrerin** — féminin : article *der*, aucune marque sur le nom.\n5. **das Zimmer des Kindes** — neutre : *des*, le nom prend *-es* (ou *des Kinds*, plus rare).\n6. **die Spielsachen der Kinder** — pluriel : *der*, aucune marque.\n\n**2.** *Wessen Heft ist das?* — *Das ist **Marias** Heft.* (*Wessen?* = de qui ?, la question du génitif.)"}$exo$::jsonb),
  ('8c3bf0b0-bf2d-5cbb-ac85-dd6466cb04f1'::uuid, 2, 'traduction', $exo${"titre":"Les vacances de Tom","consigne":"Complète le récit de Tom avec la préposition qui convient et l'article au génitif, puis traduis les groupes de la question 2.","enonce":"**1. Complète avec *wegen, trotz, während* ou *statt*, et l'article au génitif.**\n\n1. ___ d__ Ferien fahre ich nach Hamburg. *(pendant)*\n2. ___ d__ Regens spielen wir Fußball. *(malgré)*\n3. ___ d__ Sturms bleibt das Museum geschlossen. *(à cause de — der Sturm)*\n4. ___ ein__ Kaffees trinke ich einen Tee. *(au lieu de)*\n5. Das Haus mein__ Großmutter liegt außerhalb d__ Stadt.\n\n**2.** Traduis chaque groupe de deux façons : **a.** le vélo de Lisa ; **b.** la voiture de mon père. Pour chaque groupe, indique laquelle des deux formes est la plus soignée, à l'écrit.","bareme":[{"critere":"Prépositions justes : Während, Trotz, Wegen, Statt","points":6},{"critere":"Articles et noms au génitif justes : der Ferien, des Regens, des Sturms, eines Kaffees, meiner, der Stadt","points":6},{"critere":"Deux traductions justes de chaque groupe (génitif et von + datif)","points":5},{"critere":"Registre identifié : le génitif est plus soigné que von + datif","points":3}],"dureeMin":10,"corrige":"**1.**\n1. **Während der** Ferien fahre ich nach Hamburg. — *Ferien* est un pluriel → *der*.\n2. **Trotz des** Regens spielen wir Fußball. — masculin → *des Regens*.\n3. **Wegen des** Sturms bleibt das Museum geschlossen.\n4. **Statt eines** Kaffees trinke ich einen Tee. — masculin → *eines*, nom en *-s*.\n5. Das Haus **meiner** Großmutter liegt außerhalb **der** Stadt. — féminin → *meiner*, *der*.\n\n**2.**\n- a. *Lisas Fahrrad* (génitif saxon, courant pour un nom propre) / *das Fahrrad von Lisa* (oral, plus relâché). La forme la plus soignée : **Lisas Fahrrad**.\n- b. *das Auto meines Vaters* (génitif ordinaire) / *das Auto von meinem Vater* (von + datif). La forme la plus soignée : **das Auto meines Vaters**.\n\nLe génitif recule à l'oral mais reste la marque d'un écrit soigné ; *von* + datif est la tournure parlée."}$exo$::jsonb),
  ('8c3bf0b0-bf2d-5cbb-ac85-dd6466cb04f1'::uuid, 3, 'traduction', $exo${"titre":"Réécrire en allemand soigné","consigne":"Réécris le texte de Lena dans un allemand écrit soigné, explique tes choix, puis écris trois phrases à ton sujet.","enonce":"**Document — Le message de Lena, écrit comme on parle**\n\n> Wegen dem Regen feiern wir im Haus von meiner Tante. Das Geschenk von meinem Bruder ist toll. Trotz dem Wetter kommen alle Freunde von Lena. Das Auto von Paul steht vor der Tür.\n\n1. Réécris les quatre phrases en remplaçant chaque tournure orale par le **génitif** (génitif ordinaire ou génitif saxon selon le cas).\n2. Explique pourquoi un correcteur remarque ces transformations.\n3. Écris **trois phrases** sur ta vie (école, loisirs, famille) : une avec *während*, une avec *wegen*, une avec un génitif saxon.\n\n*Aide : das Wetter = le temps ; das Geschenk = le cadeau.*","bareme":[{"critere":"Prépositions wegen et trotz suivies du génitif : des Regens, des Wetters","points":6},{"critere":"Compléments du nom au génitif : meiner Tante, meines Bruders, Lenas Freunde, Pauls Auto","points":6},{"critere":"Explication : le génitif marque un niveau de langue écrit et soigné","points":3},{"critere":"Trois phrases correctes avec während, wegen et un génitif saxon","points":5}],"dureeMin":15,"corrige":"**1. Texte réécrit**\n\n> *Wegen **des Regens** feiern wir im Haus **meiner Tante**. Das Geschenk **meines Bruders** ist toll. Trotz **des Wetters** kommen alle **Freunde Lenas** (ou : **Lenas Freunde**). **Pauls Auto** steht vor der Tür.*\n\n- *wegen* et *trotz* régissent le génitif à l'écrit : *des Regens*, *des Wetters* (masculin / neutre → *des* + *-s*).\n- *meiner Tante* : féminin → *meiner*, sans marque sur le nom.\n- *meines Bruders* : masculin → *meines*, nom en *-s*.\n- Noms propres : génitif saxon devant le nom, sans article ni apostrophe (*Pauls Auto*, *Lenas Freunde*).\n\n**2.** Le génitif recule dans l'allemand parlé (on dit *wegen dem*, *von meinem*), mais il reste un **marqueur de niveau de langue** : à l'écrit, il montre qu'on maîtrise la langue soignée.\n\n**3. Exemple de réponse**\n- *Während der Woche habe ich viel Arbeit.*\n- *Wegen des Tests lerne ich heute Abend.*\n- *Am Samstag spiele ich mit Maxims Ball.*\n\nToute phrase correcte avec *während* + génitif, *wegen* + génitif et un nom propre + *-s* devant le nom est acceptée."}$exo$::jsonb),
  ('e9d46a34-f937-5cdd-b468-66f1b302908f'::uuid, 1, 'traduction', $exo${"titre":"Plus grand, plus vieux, meilleur","consigne":"Complète chaque phrase avec le comparatif de l'adjectif entre parenthèses, puis corrige la phrase de la question 2.","enonce":"**1. Complète.**\n\n1. Berlin ist ___ als München. *(groß)*\n2. Mein Bruder ist ___ als ich. *(alt)*\n3. Das Buch ist ___ als der Film. *(interessant)*\n4. Heute ist es ___ als gestern. *(warm)*\n5. Mein Deutsch ist ___ als mein Englisch. *(gut)*\n6. Ich trinke ___ Tee als Kaffee. *(gern)*\n7. Anna ist so ___ wie Lisa. *(groß)*\n\n**2.** Corrige la phrase suivante et explique ta correction : *Tom ist größer wie Paul.*","bareme":[{"critere":"Comparatifs réguliers en -er avec Umlaut : größer, älter, interessanter, wärmer","points":8},{"critere":"Irréguliers justes : besser, lieber","points":4},{"critere":"als après un comparatif, so… wie pour l'égalité, faute de la question 2 corrigée et expliquée","points":8}],"dureeMin":6,"corrige":"**1.**\n1. Berlin ist **größer** als München.\n2. Mein Bruder ist **älter** als ich.\n3. Das Buch ist **interessanter** als der Film. — adjectif long, mais toujours *-er*, jamais « mehr interessant ».\n4. Heute ist es **wärmer** als gestern.\n5. Mein Deutsch ist **besser** als mein Englisch. — *gut → besser*.\n6. Ich trinke **lieber** Tee als Kaffee. — *gern → lieber* : je préfère le thé au café.\n7. Anna ist so **groß** wie Lisa. — égalité : l'adjectif ne change pas.\n\n**2.** *Tom ist größer **als** Paul.* Après un comparatif, le second terme est introduit par **als** ; *wie* ne s'emploie qu'après *so* (égalité)."}$exo$::jsonb),
  ('e9d46a34-f937-5cdd-b468-66f1b302908f'::uuid, 2, 'traduction', $exo${"titre":"Deux vélos à comparer","consigne":"Noah hésite entre deux vélos. À partir du tableau, écris les phrases demandées en allemand.","enonce":"**Document — Les deux vélos**\n\n| | Rad X | Rad Y |\n| Prix | 400 € | 400 € |\n| Poids | 14 kg | 10 kg |\n| Âge | 3 ans | 1 an |\n| Vitesse | 25 km/h | 30 km/h |\n\n1. Écris **quatre phrases** de comparaison : une sur le prix, une sur le poids, une sur l'âge, une sur la vitesse.\n2. Noah préfère le Rad Y : écris-le avec *lieber*.\n3. Les vélos coûtent de plus en plus cher : dis-le en allemand.\n\n*Aide : teuer → teurer (cher) ; schwer (lourd) ; leicht (léger) ; alt (vieux) ; schnell (rapide) ; fahren = rouler ; kosten = coûter.*","bareme":[{"critere":"Comparatifs de supériorité justes avec als (poids, âge, vitesse)","points":6},{"critere":"Égalité exprimée par so… wie pour le prix","points":4},{"critere":"Préférence exprimée avec lieber","points":4},{"critere":"immer + comparatif : immer teurer","points":3},{"critere":"Formes justes : Umlaut d'älter, orthographe de teurer","points":3}],"dureeMin":10,"corrige":"**1. Exemples de réponses**\n- Prix : *Rad X ist **so teuer wie** Rad Y.* — même prix → égalité.\n- Poids : *Rad X ist **schwerer als** Rad Y.* (ou *Rad Y ist leichter als Rad X.*)\n- Âge : *Rad X ist **älter als** Rad Y.* — Umlaut : *alt → älter*.\n- Vitesse : *Rad Y ist **schneller als** Rad X.*\n\n**2.** *Noah fährt **lieber** mit Rad Y.* (ou *Noah mag Rad Y lieber.*) — *gern → lieber* = préférer.\n\n**3.** *Die Fahrräder werden **immer teurer**.* — *immer* + comparatif = de plus en plus.\n\nToute formulation correcte est acceptée ; *als* après le comparatif et *wie* après *so* sont exigés."}$exo$::jsonb),
  ('e9d46a34-f937-5cdd-b468-66f1b302908f'::uuid, 3, 'traduction', $exo${"titre":"Comparer sans se tromper","consigne":"Corrige le texte de Hugo en justifiant, traduis les trois phrases, puis compare deux saisons en trois phrases.","enonce":"**Document — Le texte de Hugo**\n\n> Mein Bruder ist mehr groß als ich. Er hat ein größer Zimmer. Er ist so alt als mein Cousin. Je mehr er trainiert, desto er wird stärker.\n\n1. Le texte contient **quatre fautes**. Corrige chaque phrase et justifie.\n2. Traduis en allemand :\n   - a. Plus je lis, mieux je comprends.\n   - b. Mon frère aîné a un plus grand vélo.\n   - c. Il fait de plus en plus froid.\n3. Compare l'été et l'hiver en **trois phrases** : une avec *als*, une avec *so… wie* ou *nicht so… wie*, une avec *lieber*.\n\n*Aide : lesen, verstehen ; das Fahrrad ; kalt ; der Sommer, der Winter ; lang (long) ; die Tage.*","bareme":[{"critere":"Les quatre fautes corrigées : größer, größeres, so alt wie, desto stärker wird er","points":8},{"critere":"Traductions justes : je… desto, älterer / größeres déclinés, immer kälter","points":6},{"critere":"Trois phrases de comparaison correctes (als, so… wie, lieber)","points":6}],"dureeMin":16,"corrige":"**1. Corrections**\n- *mehr groß* → **größer** : *mehr* traduit une quantité, jamais le comparatif d'un adjectif.\n- *ein größer Zimmer* → **ein größeres Zimmer** : le comparatif épithète se décline ; neutre après *ein* → *-es*.\n- *so alt als* → **so alt wie** : égalité = *so… wie*.\n- *desto er wird stärker* → **desto stärker wird er** : après *desto*, le comparatif vient d'abord, puis le verbe, puis le sujet (*Je mehr er trainiert, desto stärker wird er.*).\n\n**2.**\n- a. *Je mehr ich lese, desto (umso) besser verstehe ich.*\n- b. *Mein **älterer** Bruder hat ein **größeres** Fahrrad.* — deux terminaisons : celle du comparatif, puis celle de la déclinaison.\n- c. *Es wird **immer kälter**.*\n\n**3. Exemple de réponse**\n- *Im Sommer sind die Tage länger als im Winter.*\n- *Der Winter ist nicht so warm wie der Sommer.*\n- *Ich mag den Sommer lieber als den Winter.*"}$exo$::jsonb),
  ('684c4b6a-69bd-59d1-94bb-05411f5d5427'::uuid, 1, 'traduction', $exo${"titre":"Les superlatifs à connaître","consigne":"Donne le superlatif en am … -sten de chaque adjectif, puis choisis la bonne forme dans les deux phrases de la question 2.","enonce":"**1. Donne la forme en *am … -sten*.**\n\nschnell · alt · kurz · groß · gut · viel · gern · hoch\n\n**2. Choisis la bonne forme et justifie en une phrase.**\n\n1. Der ICE ist *am schnellsten / der schnellste*.\n2. Das ist *am schnellsten / der schnellste* Zug.","bareme":[{"critere":"Superlatifs réguliers justes, avec le e de liaison et l'exception groß : schnellsten, ältesten, kürzesten, größten","points":8},{"critere":"Irréguliers justes : besten, meisten, liebsten, höchsten","points":8},{"critere":"Choix justifié : am -sten en attribut, der -ste devant un nom","points":4}],"dureeMin":6,"corrige":"**1.**\n- schnell → **am schnellsten**\n- alt → **am ältesten** (e de liaison après *t*, et Umlaut)\n- kurz → **am kürzesten** (e de liaison après *z*)\n- groß → **am größten** (exception : pas de e)\n- gut → **am besten**\n- viel → **am meisten**\n- gern → **am liebsten**\n- hoch → **am höchsten**\n\n**2.**\n1. *Der ICE ist **am schnellsten**.* — l'adjectif est attribut (après *sein*) : forme figée *am … -sten*.\n2. *Das ist **der schnellste** Zug.* — l'adjectif est épithète, devant le nom : *der … -ste*, qui se décline."}$exo$::jsonb),
  ('684c4b6a-69bd-59d1-94bb-05411f5d5427'::uuid, 2, 'traduction', $exo${"titre":"Le sondage de la classe","consigne":"Lis le tableau du cours de sport, puis réponds en allemand par des phrases complètes.","enonce":"**Document — 100 mètres, classe 3eB**\n\n| Élève | Temps | Âge |\n| Tim | 12,4 s | 15 ans |\n| Mia | 13,1 s | 14 ans |\n| Jonas | 14,0 s | 16 ans |\n\n1. *Wer läuft am schnellsten?*\n2. *Wer ist am ältesten? Wer ist am jüngsten?*\n3. Écris une phrase qui dit que Tim est **le coureur le plus rapide de tous**, avec l'adjectif devant le nom. *(der Läufer = le coureur)*\n4. Écris deux phrases qui disent ce que tu préfères faire par-dessus tout, en sport et le week-end.\n\n*Aide : jung = jeune.*","bareme":[{"critere":"Forme am … -sten juste en attribut et en adverbe (schnellsten, ältesten, jüngsten)","points":6},{"critere":"Superlatif épithète décliné : der schnellste Läufer","points":6},{"critere":"Complément du superlatif juste : von allen + datif","points":4},{"critere":"Deux phrases correctes avec am liebsten et l'inversion","points":4}],"dureeMin":10,"corrige":"**1.** *Tim läuft **am schnellsten**.* — adverbe : forme figée.\n\n**2.** *Jonas ist **am ältesten**.* (e de liaison après *t*, Umlaut) — *Mia ist **am jüngsten**.*\n\n**3.** *Tim ist **der schnellste Läufer von allen**.* — épithète devant le nom → *der schnellste* ; complément introduit par *von* + datif. (*Tim ist der Schnellste von allen* est aussi accepté.)\n\n**4. Exemple de réponse**\n- *Am liebsten spiele ich Basketball.*\n- *Am Wochenende schlafe ich am liebsten lange.*\n\n*am liebsten* = ce que je préfère par-dessus tout ; placé en tête, il entraîne l'inversion verbe-sujet."}$exo$::jsonb),
  ('684c4b6a-69bd-59d1-94bb-05411f5d5427'::uuid, 3, 'traduction', $exo${"titre":"Le meilleur et le plus haut","consigne":"Traduis les phrases, corrige les deux erreurs du document, puis explique la règle des deux formes du superlatif.","enonce":"**1. Traduis en allemand.**\n\n1. Berlin est la plus grande ville d'Allemagne. *(deux façons)*\n2. Ce que je préfère par-dessus tout, c'est lire des romans policiers.\n3. Je joue avec mon meilleur ami.\n4. La Zugspitze est la montagne la plus haute d'Allemagne.\n5. C'est lui qui a le plus d'argent.\n\n**Document — deux phrases d'un élève**\n\n> a. Das ist der Zug am schnellsten.\n> b. Paula ist am altsten.\n\n**2.** Corrige les deux phrases du document.\n**3.** Explique en quelques lignes, en français, comment on choisit entre les deux formes du superlatif.\n\n*Aide : die Stadt ; der Krimi, die Krimis ; der Freund ; der Berg ; das Geld.*","bareme":[{"critere":"Phrases 1 et 4 : superlatif épithète décliné et complément de lieu (in + datif ou génitif)","points":5},{"critere":"Phrases 2, 3 et 5 : am liebsten avec inversion, meinem besten Freund, am meisten","points":5},{"critere":"Les deux phrases du document corrigées : der schnellste Zug, am ältesten","points":5},{"critere":"Explication : attribut ou adverbe → am -sten figé ; épithète → der -ste décliné","points":5}],"dureeMin":16,"corrige":"**1.**\n1. *Berlin ist **die größte Stadt in Deutschland**.* / *Berlin ist **Deutschlands größte Stadt**.* — épithète féminine ; complément avec *in* + datif ou génitif.\n2. ***Am liebsten** lese ich Krimis.* — *am liebsten* n'est pas « le plus aimé » mais « ce que je préfère » ; inversion après l'adverbe.\n3. *Ich spiele mit **meinem besten** Freund.* — *mit* + datif, superlatif épithète décliné.\n4. *Die Zugspitze ist **der höchste Berg** Deutschlands* (ou *in Deutschland*). — *hoch → höchste*, *Berg* masculin.\n5. *Er hat **am meisten** Geld.* — *viel → am meisten*.\n\n**2.**\n- a. *Das ist **der schnellste Zug**.* — devant un nom, on emploie la forme déclinée.\n- b. *Paula ist **am ältesten**.* — après *t*, on intercale un *e* ; *alt* prend aussi l'Umlaut.\n\n**3.** Le superlatif a deux formes selon la **place** de l'adjectif. Quand il est **attribut** (après *sein*) ou **adverbe** (*er läuft…*), on emploie *am* + *-sten*, forme figée qui ne se décline pas. Quand il est **épithète**, devant un nom, on emploie *der / die / das* + *-ste*, qui se décline comme un adjectif (*mit dem besten Freund*). Dans les deux cas, on ajoute un *e* de liaison après *d, t, s, ß, z, sch* (sauf *groß → größten*)."}$exo$::jsonb),
  ('2580e2ea-b1a7-5f67-97d9-75feff3c59ff'::uuid, 1, 'traduction', $exo${"titre":"Durch, für, gegen, ohne, um","consigne":"Complète chaque phrase avec la préposition qui convient et, s'il le faut, la terminaison de l'article ou du possessif.","enonce":"**1. Complète avec *durch, für, gegen, ohne* ou *um*.**\n\n1. Wir gehen ___ d__ Park. *(à travers — der Park)*\n2. Das Geschenk ist ___ mein__ Schwester. *(pour)*\n3. Ich trinke den Kaffee ___ Zucker. *(sans)*\n4. Wir sitzen ___ d__ Tisch. *(autour de — der Tisch)*\n5. Ich bin ___ dies__ Idee. *(contre — die Idee)*\n6. Der Film beginnt ___ acht Uhr. *(à huit heures pile)*\n\n**2.** Quel cas suit ces cinq prépositions ? Explique pourquoi on écrit *den Park* et non *der Park* dans la phrase 1.","bareme":[{"critere":"Prépositions justes : durch, für, ohne, um, gegen, um","points":8},{"critere":"Terminaisons de l'accusatif justes : den Park, meine Schwester, den Tisch, diese Idee","points":8},{"critere":"Explication : ces prépositions imposent toujours l'accusatif, masculin der → den","points":4}],"dureeMin":6,"corrige":"**1.**\n1. Wir gehen **durch den** Park.\n2. Das Geschenk ist **für meine** Schwester.\n3. Ich trinke den Kaffee **ohne** Zucker. — *ohne* se passe souvent d'article.\n4. Wir sitzen **um den** Tisch.\n5. Ich bin **gegen diese** Idee.\n6. Der Film beginnt **um** acht Uhr. — heure précise → *um* (*gegen acht Uhr* = vers huit heures).\n\n**2.** *durch, für, gegen, ohne, um* imposent **toujours l'accusatif**, quel que soit le sens. Au masculin, l'article *der* devient *den* à l'accusatif : *durch den Park*. Au féminin et au neutre, la forme ne change pas (*meine Schwester*, *diese Idee*)."}$exo$::jsonb),
  ('2580e2ea-b1a7-5f67-97d9-75feff3c59ff'::uuid, 2, 'traduction', $exo${"titre":"Le message d'Emma","consigne":"Emma répond à une invitation. Traduis son message en allemand, puis réponds à la question 2.","enonce":"**Le message d'Emma, en français**\n\n1. J'arrive vers huit heures.\n2. Le cadeau est pour ton frère.\n3. Nous marchons le long de la rivière.\n4. Je vais jusqu'à la gare en bus.\n5. Je viens sans mon vélo.\n\n*Aide : kommen ; das Geschenk ; der Bruder ; laufen ; der Fluss ; fahren ; der Bahnhof ; mit dem Bus ; das Fahrrad.*\n\n**2.** Emma hésite entre *gegen acht Uhr* et *um acht Uhr*. Explique la différence.","bareme":[{"critere":"Prépositions justes : gegen, für, entlang, bis zum, ohne","points":7},{"critere":"Accusatif juste après les prépositions : deinen Bruder, den Fluss, mein Fahrrad","points":6},{"critere":"Place d'entlang après le nom et bis suivi de zum","points":3},{"critere":"Différence gegen (vers) / um (heure précise) expliquée","points":4}],"dureeMin":10,"corrige":"**Traduction modèle**\n1. *Ich komme **gegen** acht Uhr.* — heure approximative.\n2. *Das Geschenk ist **für deinen** Bruder.* — *für* + accusatif ; masculin → *deinen*.\n3. *Wir laufen **den Fluss entlang**.* — *entlang* se place **après** le nom, qui est à l'accusatif.\n4. *Ich fahre mit dem Bus **bis zum** Bahnhof.* — *bis* est souvent suivi d'une seconde préposition (*zum* = *zu dem*).\n5. *Ich komme **ohne mein** Fahrrad.* — *Fahrrad* neutre : *mein* à l'accusatif.\n\n**2.** *gegen acht Uhr* = **vers** huit heures (approximatif) ; *um acht Uhr* = **à** huit heures pile. Une seule préposition d'écart change l'heure du rendez-vous."}$exo$::jsonb),
  ('2580e2ea-b1a7-5f67-97d9-75feff3c59ff'::uuid, 3, 'traduction', $exo${"titre":"Pour apprendre, pas für lernen","consigne":"Corrige le texte de Jules en justifiant chaque correction, puis rédige une invitation de quatre phrases.","enonce":"**Document — Le texte de Jules**\n\n> Ich lerne Deutsch für in Berlin studieren. Jeden Morgen gehe ich durch dem Wald. Das Buch ist für mein Vater. Am Sonntag laufen wir entlang die Straße.\n\n1. Chaque phrase contient **une faute**. Recopie les phrases corrigées.\n2. Justifie chaque correction en une phrase.\n3. Rédige en allemand une **invitation de quatre phrases** à une fête d'anniversaire, avec **quatre prépositions différentes** parmi *durch, für, gegen, ohne, um, bis, entlang*.\n\n*Aide : die Party ; der Geburtstag ; der Garten ; der Kuchen.*","bareme":[{"critere":"Quatre corrections justes : um… zu studieren, durch den Wald, für meinen Vater, die Straße entlang","points":8},{"critere":"Justifications : für devant un nom seulement, accusatif obligatoire, place d'entlang","points":4},{"critere":"Invitation : quatre prépositions différentes suivies de l'accusatif correct","points":6},{"critere":"Invitation compréhensible, verbes conjugués et ordre des mots corrects","points":2}],"dureeMin":16,"corrige":"**1. Texte corrigé**\n\n> *Ich lerne Deutsch, **um in Berlin zu studieren**. Jeden Morgen gehe ich **durch den** Wald. Das Buch ist **für meinen** Vater. Am Sonntag laufen wir **die Straße entlang**.*\n\n**2. Justifications**\n- « Pour + verbe » ne se dit pas *für* : *für* introduit un groupe nominal, jamais un verbe. Le but se dit **um… zu** + infinitif.\n- *durch* impose l'**accusatif** : *der Wald* → *den Wald* (et non le datif *dem*).\n- *für* impose l'accusatif : *Vater* masculin → *meinen Vater*.\n- *entlang* se place **après** le nom : *die Straße entlang*.\n\n**3. Exemple de réponse**\n\n> *Hallo Tim! Ich mache am Samstag eine Party für meinen Geburtstag. Die Party beginnt um drei Uhr. Wir essen Kuchen und spielen im Garten bis zum Abend. Komm nicht ohne deinen Bruder!*\n\nToute invitation correcte employant quatre prépositions différentes avec l'accusatif juste est acceptée."}$exo$::jsonb),
  ('ae0a3bfb-73a9-554f-95a1-d5ea673e88af'::uuid, 1, 'traduction', $exo${"titre":"Aus, bei, mit, nach, seit, von, zu","consigne":"Complète chaque phrase avec la préposition entre parenthèses et la terminaison du datif, en contractant quand c'est l'usage.","enonce":"**1. Complète.**\n\n1. Ich fahre ___ d__ Bus in die Stadt. *(avec)*\n2. Er kommt ___ d__ Schweiz. *(de — die Schweiz)*\n3. Ich wohne ___ mein__ Eltern. *(chez)*\n4. Ich gehe heute ___ Arzt. *(chez — contracté)*\n5. ___ d__ Film essen wir Pizza. *(après — der Film)*\n6. Ich lerne ___ ein__ Jahr Deutsch. *(depuis — das Jahr)*\n\n**2.** Dans la phrase 6, pourquoi le verbe est-il au présent alors que le français pourrait hésiter ? Explique en une phrase.","bareme":[{"critere":"Prépositions justes : mit, aus, bei, zum, nach, seit","points":6},{"critere":"Terminaisons du datif justes : dem Bus, der Schweiz, meinen Eltern, dem Film, einem Jahr","points":8},{"critere":"Contraction zum employée","points":2},{"critere":"Explication : seit + présent","points":4}],"dureeMin":6,"corrige":"**1.**\n1. Ich fahre **mit dem** Bus in die Stadt.\n2. Er kommt **aus der** Schweiz. — féminin au datif → *der*.\n3. Ich wohne **bei meinen** Eltern. — datif pluriel → *-en*.\n4. Ich gehe heute **zum** Arzt. — *zu dem* → *zum*, contraction obligatoire dans l'usage.\n5. **Nach dem** Film essen wir Pizza. — masculin datif → *dem* ; inversion après le complément.\n6. Ich lerne **seit einem** Jahr Deutsch. — neutre datif → *einem*.\n\n**2.** Avec *seit*, l'action a commencé dans le passé et **dure encore** : l'allemand emploie le **présent**, comme le français (« j'apprends l'allemand depuis un an »)."}$exo$::jsonb),
  ('ae0a3bfb-73a9-554f-95a1-d5ea673e88af'::uuid, 2, 'traduction', $exo${"titre":"Le voyage de Noah","consigne":"Noah raconte ses projets de voyage. Traduis ses phrases en allemand, puis explique tes choix de préposition.","enonce":"**1. Traduis en allemand.**\n\n1. Cet été, je vais en Autriche.\n2. Ensuite, je vais en Suisse.\n3. Je vais chez ma tante.\n4. Le soir, je rentre à la maison.\n5. Le dimanche, je suis à la maison.\n6. J'habite à Munich depuis deux ans.\n\n*Aide : Österreich (sans article) ; die Schweiz ; die Tante ; fahren, gehen ; wohnen ; München ; das Jahr, die Jahre ; im Sommer ; dann ; abends ; sonntags.*\n\n**2.** Explique quand on emploie *nach*, *in* + accusatif et *zu* pour dire où l'on va.","bareme":[{"critere":"Choix juste de nach, in die et zu selon le lieu (phrases 1 à 3)","points":7},{"critere":"Datif et contractions justes : zu meiner Tante, seit zwei Jahren","points":5},{"critere":"Expressions figées nach Hause / zu Hause bien employées","points":4},{"critere":"seit + présent, et règle nach / in / zu expliquée","points":4}],"dureeMin":10,"corrige":"**1. Traduction modèle**\n1. *Im Sommer fahre ich **nach Österreich**.* — pays sans article → *nach*.\n2. *Dann fahre ich **in die Schweiz**.* — pays avec article → *in* + accusatif.\n3. *Ich fahre **zu meiner** Tante.* — personne → *zu* + datif.\n4. *Abends gehe ich **nach Hause**.* — avec mouvement.\n5. *Sonntags bin ich **zu Hause**.* — sans mouvement.\n6. *Ich wohne **seit zwei Jahren** in München.* — *seit* + datif pluriel (*Jahren*) et verbe au **présent**.\n\n**2.** Pour dire où l'on va : **nach** devant un pays ou une ville **sans article** (*nach Wien*) ; **in** + accusatif devant un pays **avec article** (*in die Schweiz, in die Türkei*) ; **zu** + datif devant une **personne** ou un bâtiment vu comme un but (*zum Arzt, zur Post*). *nach Hause* / *zu Hause* sont des expressions figées."}$exo$::jsonb),
  ('ae0a3bfb-73a9-554f-95a1-d5ea673e88af'::uuid, 3, 'traduction', $exo${"titre":"Une journée à Hambourg","consigne":"Corrige le texte d'Hugo en justifiant, puis décris ta propre journée en quatre phrases.","enonce":"**Document — Le texte d'Hugo**\n\n> Seit drei Jahren habe ich in Hamburg gewohnt. Jeden Tag fahre ich mit meinem Fahrrad zu die Schule. Nach der Schule gehe ich bei meinem Freund Max. Im Juli fahren wir nach die Türkei. Meine Mutter kommt aus Frankreich.\n\n1. Le texte contient **quatre fautes**. Recopie les phrases fautives corrigées.\n2. Justifie chaque correction.\n3. Une phrase du texte est entièrement correcte : laquelle ? Explique pourquoi.\n4. Décris ta journée en **quatre phrases** en employant au moins quatre prépositions différentes parmi *aus, bei, mit, nach, seit, von, zu*.","bareme":[{"critere":"Quatre corrections : Seit… wohne ich, zur Schule, zu meinem Freund, in die Türkei","points":8},{"critere":"Justifications : seit + présent, contraction, zu pour une destination, pays avec article","points":4},{"critere":"Phrase correcte identifiée : aus Frankreich, pays sans article, aus + origine","points":2},{"critere":"Quatre phrases personnelles avec quatre prépositions à datif bien construites","points":6}],"dureeMin":16,"corrige":"**1. Corrections**\n- *Seit drei Jahren **wohne ich** in Hamburg.*\n- *Jeden Tag fahre ich mit meinem Fahrrad **zur** Schule.*\n- *Nach der Schule gehe ich **zu meinem** Freund Max.*\n- *Im Juli fahren wir **in die** Türkei.*\n\n**2. Justifications**\n- Avec *seit*, l'action dure encore : **présent**, pas parfait.\n- *zu* impose le datif : *zu der* → contraction **zur** (obligatoire dans l'usage).\n- On **va** chez quelqu'un : *zu* + datif ; *bei* indique qu'on **est** chez lui (sans mouvement).\n- *die Türkei* a un article : on emploie **in** + accusatif, pas *nach*.\n\n**3.** *Meine Mutter kommt aus Frankreich* est correct : *aus* + datif marque l'origine, et *Frankreich* s'emploie sans article.\n\n**4. Exemple de réponse**\n- *Ich fahre mit dem Bus zur Schule.*\n- *Nach dem Unterricht esse ich bei meiner Oma.*\n- *Ich lerne seit vier Jahren Deutsch.*\n- *Am Abend bekomme ich eine Nachricht von meinem Freund.*"}$exo$::jsonb),
  ('8479055b-1fb7-55b1-a35f-5009eb9f76bd'::uuid, 1, 'traduction', $exo${"titre":"Wo ou wohin ?","consigne":"Complète chaque phrase avec l'article au bon cas, puis explique ton choix pour les phrases 1 et 2.","enonce":"**1. Complète avec l'article.**\n\n1. Ich gehe in ___ Schule. *(die Schule)*\n2. Ich bin in ___ Schule.\n3. Das Bild hängt an ___ Wand. *(die Wand)*\n4. Die Katze liegt unter ___ Tisch. *(der Tisch)*\n5. Die Katze läuft unter ___ Tisch. *(elle s'y glisse)*\n6. Das Heft liegt neben ___ Buch. *(das Buch)*\n\n**2.** Explique pourquoi l'article n'est pas le même dans les phrases 1 et 2.","bareme":[{"critere":"Accusatif juste en cas de déplacement (wohin) : die Schule, den Tisch","points":8},{"critere":"Datif juste en cas de localisation (wo) : der Schule, der Wand, dem Tisch, dem Buch","points":8},{"critere":"Explication avec les questions wo ? / wohin ?","points":4}],"dureeMin":6,"corrige":"**1.**\n1. Ich gehe in **die** Schule. — *wohin?* déplacement → accusatif.\n2. Ich bin in **der** Schule. — *wo?* localisation → datif.\n3. Das Bild hängt an **der** Wand. — état → datif.\n4. Die Katze liegt unter **dem** Tisch. — *wo?* → datif.\n5. Die Katze läuft unter **den** Tisch. — elle change de lieu (*wohin?*) → accusatif.\n6. Das Heft liegt neben **dem** Buch. — *wo?* → datif.\n\n**2.** Les neuf prépositions mixtes changent de cas selon le sens. Dans la phrase 1, il y a un **changement de lieu** (question *wohin?*) → **accusatif** ; dans la phrase 2, une **localisation** (question *wo?*) → **datif**."}$exo$::jsonb),
  ('8479055b-1fb7-55b1-a35f-5009eb9f76bd'::uuid, 2, 'traduction', $exo${"titre":"Clara range sa chambre","consigne":"Complète chaque paire de phrases avec le verbe conjugué et l'article au bon cas, puis réponds à la question 2.","enonce":"**1. Complète.** Dans chaque paire, la phrase **a** décrit l'action, la phrase **b** le résultat.\n\n1. a. Clara ___ die Lampe auf ___ Schreibtisch. *(stellen / stehen)* — b. Die Lampe ___ auf ___ Schreibtisch.\n2. a. Sie ___ das Buch auf ___ Bett. *(legen / liegen)* — b. Das Buch ___ auf ___ Bett.\n3. a. Sie ___ das Poster an ___ Wand. *(hängen)* — b. Das Poster ___ an ___ Wand.\n\n*der Schreibtisch, das Bett, die Wand*\n\n**2.** Contracte : *in das Zimmer* ; *an dem Fenster* ; *auf das Bett*.","bareme":[{"critere":"Couples de verbes justes et conjugués : stellt / steht, legt / liegt, hängt / hängt","points":8},{"critere":"Accusatif pour l'action, datif pour l'état : den / dem Schreibtisch, das / dem Bett, die / der Wand","points":8},{"critere":"Contractions justes : ins, am, aufs","points":4}],"dureeMin":10,"corrige":"**1.**\n1. a. Clara **stellt** die Lampe auf **den** Schreibtisch. — action → accusatif. b. Die Lampe **steht** auf **dem** Schreibtisch. — état → datif.\n2. a. Sie **legt** das Buch auf **das** (*aufs*) Bett. b. Das Buch **liegt** auf **dem** Bett.\n3. a. Sie **hängt** das Poster an **die** Wand. — *hängen* faible = accrocher. b. Das Poster **hängt** an **der** Wand. — *hängen* fort = être accroché.\n\nLes verbes d'action (*stellen, legen, setzen, hängen* faible) appellent l'accusatif ; les verbes d'état (*stehen, liegen, sitzen, hängen* fort) le datif.\n\n**2.** *in das Zimmer* → **ins Zimmer** ; *an dem Fenster* → **am Fenster** ; *auf das Bett* → **aufs Bett**."}$exo$::jsonb),
  ('8479055b-1fb7-55b1-a35f-5009eb9f76bd'::uuid, 3, 'traduction', $exo${"titre":"Même verbe, deux cas","consigne":"Traduis les phrases en allemand, puis explique en français la méthode qui permet de choisir le cas.","enonce":"**1. Traduis en allemand.**\n\n1. Je cours dans le parc (à l'intérieur du parc).\n2. J'entre en courant dans le parc.\n3. Je pose la bouteille sur la table.\n4. La bouteille est sur la table.\n5. Je me réjouis des vacances.\n6. En janvier, nous allons au cinéma.\n\n*Aide : laufen ; der Park ; die Flasche ; der Tisch ; sich freuen auf ; die Ferien (pluriel) ; der Januar ; das Kino.*\n\n**2.** En quelques lignes, explique pourquoi les phrases 1 et 2 n'ont pas le même cas alors que le verbe est le même, et donne la méthode à suivre pour choisir l'article.","bareme":[{"critere":"Phrases 1 et 2 : im Park (datif) / in den Park (accusatif)","points":5},{"critere":"Phrases 3 et 4 : stellen + accusatif, stehen + datif","points":4},{"critere":"Emplois figés justes : auf die Ferien (accusatif), im Januar, ins Kino avec inversion","points":5},{"critere":"Explication : c'est le changement de lieu, pas le verbe, qui décide ; méthode wo ? / wohin ?","points":6}],"dureeMin":15,"corrige":"**1. Traduction modèle**\n1. *Ich laufe **im Park**.* — je cours à l'intérieur : pas de changement de lieu → datif (*in dem* → *im*).\n2. *Ich laufe **in den Park**.* — j'y entre : changement de lieu → accusatif.\n3. *Ich **stelle** die Flasche auf **den** Tisch.* — action → accusatif.\n4. *Die Flasche **steht** auf **dem** Tisch.* — état → datif.\n5. *Ich freue mich **auf die** Ferien.* — emploi figé : *sich freuen auf* + accusatif.\n6. ***Im** Januar gehen wir **ins** Kino.* — *im Januar* figé ; *ins Kino* = déplacement ; inversion après le complément de temps.\n\n**2.** Ce n'est pas le verbe de mouvement qui décide, mais le **changement de lieu** : dans la phrase 1, on court en restant dans le parc (*wo?* → datif) ; dans la phrase 2, on passe de l'extérieur à l'intérieur (*wohin?* → accusatif). Méthode : trouver le **verbe**, se demander **wo?** ou **wohin?**, et n'écrire l'article qu'**ensuite**. Certaines expressions ne relèvent plus du lieu et s'apprennent telles quelles (*im Januar, sich freuen auf* + accusatif)."}$exo$::jsonb),
  ('75ddbcd9-92d4-5a7e-88ac-86a06295ad38'::uuid, 1, 'traduction', $exo${"titre":"Relier deux phrases","consigne":"Relie chaque paire de phrases avec la conjonction indiquée, en respectant la virgule et l'ordre des mots.","enonce":"**1. Relie les deux phrases.**\n\n1. Ich bleibe zu Hause. Ich bin krank. *(denn)*\n2. Er ist arm. Er ist glücklich. *(aber)*\n3. Das ist nicht mein Buch. Es ist deins. *(sondern)*\n4. Trinkst du Tee? Trinkst du Kaffee? *(oder)*\n5. Ich spiele Fußball. Mein Bruder spielt Tennis. *(und)*\n\n**2.** Dans la phrase 3, pourquoi faut-il *sondern* et non *aber* ?","bareme":[{"critere":"Phrases reliées sans changer l'ordre des mots après la conjonction (verbe en 2e position)","points":10},{"critere":"Virgule devant denn, aber et sondern, pas devant und ni oder","points":5},{"critere":"Explication : sondern après une négation","points":5}],"dureeMin":6,"corrige":"**1.**\n1. *Ich bleibe zu Hause, **denn** ich bin krank.* — après *denn*, rien ne bouge : sujet puis verbe.\n2. *Er ist arm, **aber** glücklich.* (ou *…, aber er ist glücklich.*)\n3. *Das ist nicht mein Buch, **sondern** deins.*\n4. *Trinkst du Tee **oder** Kaffee?*\n5. *Ich spiele Fußball **und** mein Bruder spielt Tennis.*\n\nLes conjonctions de coordination occupent la **position zéro** : elles ne comptent pas dans l'ordre des mots.\n\n**2.** *sondern* (« mais au contraire ») s'emploie après une **négation** pour rectifier : *nicht mein Buch, sondern deins*. *aber* s'emploie sans négation, pour une opposition simple."}$exo$::jsonb),
  ('75ddbcd9-92d4-5a7e-88ac-86a06295ad38'::uuid, 2, 'traduction', $exo${"titre":"Trois syntaxes pour une même idée","consigne":"Réécris chaque idée avec les mots de liaison demandés, puis explique où se place le verbe dans chaque cas.","enonce":"**1. Idée : nous restons à la maison parce qu'il pleut.**\n\nÉcris la phrase de trois façons :\na. avec *denn* ;\nb. avec *weil* ;\nc. avec *deshalb*.\n\n*(Wir bleiben zu Hause. — Es regnet.)*\n\n**2. Idée : je suis fatigué, pourtant je continue à travailler.**\n\nÉcris la phrase de deux façons :\na. avec *aber* ;\nb. avec *trotzdem*.\n\n*(Ich bin müde. — Ich lerne weiter.)*\n\n**3.** Explique en français, pour *denn*, *weil* et *deshalb*, où se place le verbe conjugué.","bareme":[{"critere":"Phrase avec denn : ordre normal, virgule","points":4},{"critere":"Phrase avec weil : verbe conjugué à la fin","points":4},{"critere":"Phrases avec deshalb et trotzdem : inversion verbe-sujet","points":6},{"critere":"Explication des trois places du verbe (coordination, subordination, adverbe)","points":6}],"dureeMin":10,"corrige":"**1.**\na. *Wir bleiben zu Hause, **denn** es regnet.*\nb. *Wir bleiben zu Hause, **weil** es **regnet**.*\nc. *Es regnet, **deshalb bleiben wir** zu Hause.*\n\n**2.**\na. *Ich bin müde, **aber** ich lerne weiter.*\nb. *Ich bin müde, **trotzdem lerne ich** weiter.*\n\n**3.**\n- Après **denn** (coordination) : la conjonction est en position zéro, rien ne bouge — sujet puis verbe en **2e position**.\n- Après **weil** (subordination) : le verbe conjugué part **à la fin** de la subordonnée.\n- Après **deshalb** (adverbe de liaison, comme *trotzdem*) : l'adverbe occupe la **1re position**, le verbe reste en 2e position, donc le sujet passe derrière : **inversion**.\n\nTrois syntaxes pour un même lien logique : les confondre est l'erreur la plus fréquente en expression écrite."}$exo$::jsonb),
  ('75ddbcd9-92d4-5a7e-88ac-86a06295ad38'::uuid, 3, 'traduction', $exo${"titre":"Donner son avis en nuances","consigne":"Traduis les phrases, corrige les deux erreurs du document, puis donne ton avis en quatre phrases.","enonce":"**1. Traduis en allemand.**\n\n1. Ni mon frère ni ma sœur ne parlent allemand.\n2. Il joue non seulement au football, mais aussi au tennis.\n3. Ou bien nous allons au cinéma, ou bien nous restons à la maison.\n4. Certes, le voyage est cher, mais il est intéressant.\n\n**Document — deux phrases d'élève**\n\n> a. Ich spiele nicht Tennis, aber Fußball.\n> b. Weder Tom noch Lisa kommt nicht.\n\n**2.** Corrige les deux phrases et justifie.\n\n**3.** Donne ton avis sur le téléphone portable au collège en **quatre phrases**, en utilisant *zwar… aber*, *denn* et *deshalb*.\n\n*Aide : die Reise ; teuer ; das Handy ; nützlich (utile) ; stören (déranger) ; im Unterricht.*","bareme":[{"critere":"Traductions justes des corrélatifs : weder… noch, nicht nur… sondern auch, entweder… oder, zwar… aber","points":8},{"critere":"Corrections justifiées : sondern après négation, pas de nicht après weder… noch","points":4},{"critere":"Avis : zwar… aber, denn (sans inversion) et deshalb (avec inversion) bien construits","points":6},{"critere":"Avis cohérent et compréhensible","points":2}],"dureeMin":18,"corrige":"**1. Traduction modèle**\n1. *Weder mein Bruder noch meine Schwester spricht Deutsch.* (*sprechen* au pluriel est aussi accepté) — la phrase est déjà négative : pas de *nicht*.\n2. *Er spielt nicht nur Fußball, sondern auch Tennis.*\n3. *Entweder gehen wir ins Kino, oder wir bleiben zu Hause.* (*Entweder wir gehen…* est aussi accepté.)\n4. *Die Reise ist zwar teuer, aber (sie ist) interessant.*\n\n**2.**\n- a. *Ich spiele nicht Tennis, **sondern** Fußball.* — après une négation, on rectifie avec *sondern*.\n- b. *Weder Tom noch Lisa **kommt**.* — *weder… noch* porte déjà la négation : ajouter *nicht* est une faute.\n\n**3. Exemple de réponse**\n\n> *Das Handy ist zwar nützlich, aber es stört im Unterricht. Viele Schüler spielen im Unterricht, denn sie sind nicht konzentriert. Deshalb bin ich für ein Handyverbot in der Klasse. Nach der Schule ist das Handy aber okay.*\n\nSont vérifiés : *zwar* après le verbe et *aber* en tête de la seconde partie, *denn* sans changement d'ordre, *deshalb* suivi de l'inversion."}$exo$::jsonb),
  ('79a29c76-4a2d-54ce-85bd-9d2ed2be58e6'::uuid, 1, 'traduction', $exo${"titre":"Wo, wohin, woher ?","consigne":"Complète chaque phrase avec la préposition (et l'article contracté si besoin), puis indique la question à laquelle elle répond.","enonce":"**1. Complète, puis écris à côté *wo?*, *wohin?* ou *woher?*.**\n\n1. Ich fahre ___ Deutschland.\n2. Ich komme ___ Frankreich.\n3. Im Sommer fahren wir ___ Meer. *(das Meer)*\n4. Heute Abend gehe ich ___ Kino. *(das Kino)*\n5. Ich bin gerade ___ Arzt. *(der Arzt)*\n6. Mama kommt um sechs Uhr ___ der Arbeit.","bareme":[{"critere":"Prépositions justes : nach, aus, ans, ins, beim, von","points":12},{"critere":"Contractions correctes : ans, ins, beim","points":4},{"critere":"Question juste pour chaque phrase","points":4}],"dureeMin":6,"corrige":"1. Ich fahre **nach** Deutschland. — *wohin?* pays sans article.\n2. Ich komme **aus** Frankreich. — *woher?* venir d'un pays.\n3. Im Sommer fahren wir **ans** Meer. — *wohin?* un bord : *an* + accusatif (*an das* → *ans*).\n4. Heute Abend gehe ich **ins** Kino. — *wohin?* nom avec article : *in* + accusatif (*in das* → *ins*).\n5. Ich bin gerade **beim** Arzt. — *wo?* chez une personne sans mouvement : *bei dem* → *beim*.\n6. Mama kommt um sechs Uhr **von** der Arbeit. — *woher?* point de départ : *von* + datif."}$exo$::jsonb),
  ('79a29c76-4a2d-54ce-85bd-9d2ed2be58e6'::uuid, 2, 'traduction', $exo${"titre":"Dialogue avant les vacances","consigne":"Complète le dialogue entre Ben et Aylin, puis traduis les deux paires de phrases de la question 2.","enonce":"**1. Complète le dialogue.**\n\n> Ben: Wohin fährst du in den Ferien?\n> Aylin: Ich fahre ___ Land zu meiner Oma. *(à la campagne)*\n> Ben: Wo wohnt sie genau?\n> Aylin: Sie wohnt ___ Land, in einem kleinen Dorf.\n> Ben: Und dein Vater? Woher kommt er?\n> Aylin: Er kommt ___ Türkei. Im August fahren wir alle ___ Türkei.\n\n**2. Traduis en allemand.**\na. Je vais chez le médecin. / Je suis chez le médecin.\nb. Il part à l'étranger. / Il vit à l'étranger.\n\n*Aide : das Ausland = l'étranger ; der Arzt.*","bareme":[{"critere":"Paire aufs Land / auf dem Land juste","points":4},{"critere":"aus der Türkei (origine) et in die Türkei (destination) justes","points":4},{"critere":"zum Arzt / beim Arzt justes","points":6},{"critere":"ins Ausland / im Ausland justes","points":6}],"dureeMin":10,"corrige":"**1.**\n- Ich fahre **aufs** Land zu meiner Oma. — mouvement : *auf* + accusatif (*auf das* → *aufs*).\n- Sie wohnt **auf dem** Land. — sans mouvement : datif.\n- Er kommt **aus der** Türkei. — origine : *aus* + datif ; pays avec article féminin → *der*.\n- Im August fahren wir alle **in die** Türkei. — destination, pays avec article → *in* + accusatif (jamais *nach*).\n\n**2.**\na. *Ich gehe **zum** Arzt.* (mouvement vers une personne) / *Ich bin **beim** Arzt.* (sans mouvement). Le français dit « chez » dans les deux cas ; l'allemand oblige à choisir.\nb. *Er geht (fährt) **ins** Ausland.* / *Er lebt **im** Ausland.* — expressions figées par paires : une avec mouvement (accusatif), une sans (datif)."}$exo$::jsonb),
  ('79a29c76-4a2d-54ce-85bd-9d2ed2be58e6'::uuid, 3, 'traduction', $exo${"titre":"Hin, her et le récit d'un voyage","consigne":"Traduis les phrases de la question 1, rédige le récit demandé, puis réponds à la question 3 en français.","enonce":"**1. Traduis en allemand.**\na. Viens ici !\nb. Vas-y !\nc. Où vas-tu ? *(deux façons)*\nd. D'où viens-tu ? *(deux façons)*\n\n**2.** Raconte en **six phrases** un voyage imaginaire : d'où tu pars, où tu vas, chez qui, où tu dors, ce que tu visites. Emploie au moins **cinq** constructions différentes parmi : *nach, in* + accusatif, *zu, an* + accusatif, *aus, von, bei*.\n\n**3.** Explique la différence entre *hineingehen* et *herauskommen* en t'appuyant sur le sens de *hin* et *her*.","bareme":[{"critere":"Impératifs justes : Komm her!, Geh hin!","points":3},{"critere":"Questions justes : Wohin / Wo… hin, Woher / Wo… her","points":4},{"critere":"Récit : cinq constructions de lieu différentes avec le bon cas","points":7},{"critere":"Récit compréhensible, verbes conjugués correctement","points":2},{"critere":"Explication : hin = éloignement du locuteur, her = rapprochement","points":4}],"dureeMin":18,"corrige":"**1.**\na. *Komm **her**!* — rapprochement vers celui qui parle.\nb. *Geh **hin**!* — éloignement.\nc. *Wohin gehst du?* / *Wo gehst du **hin**?*\nd. *Woher kommst du?* / *Wo kommst du **her**?* — la particule peut se détacher et partir en fin de phrase.\n\n**2. Exemple de réponse**\n\n> *Ich komme aus Lyon. Im Juli fahre ich mit dem Zug nach Berlin. Dort gehe ich zu meinem Brieffreund Jonas. Ich schlafe bei seiner Familie. Am Montag gehen wir ins Museum. Am Wochenende fahren wir ans Meer.*\n\nConstructions attendues : *aus* (origine), *nach* (ville sans article), *zu* + datif (personne), *bei* + datif (sans mouvement), *in* + accusatif (*ins Museum*), *an* + accusatif (*ans Meer*).\n\n**3.** *hin* marque l'**éloignement** du locuteur, *her* le **rapprochement**. *hineingehen* = entrer, vu de **dehors** (on s'éloigne de celui qui parle) ; *herauskommen* = sortir, vu de **dedans** (on vient vers celui qui parle). Ces particules se soudent aux prépositions pour former des préverbes."}$exo$::jsonb),
  ('9712f7b8-159d-5a85-b792-992b0ea096f4'::uuid, 1, 'traduction', $exo${"titre":"Am, im ou um ?","consigne":"Complète chaque complément de temps, puis traduis les trois expressions de la question 2.","enonce":"**1. Complète avec *am*, *im*, *um* ou *in der*.**\n\n1. ___ Montag\n2. ___ Sommer\n3. ___ acht Uhr\n4. ___ Januar\n5. ___ Abend\n6. ___ Jahr 2026\n7. ___ Nacht\n8. ___ Mitternacht\n\n**2.** Traduis et explique la différence : *morgen* ; *morgens* ; *am Morgen*.","bareme":[{"critere":"am devant les jours et parties de la journée : am Montag, am Abend","points":4},{"critere":"im devant mois, saisons, années : im Sommer, im Januar, im Jahr 2026","points":4},{"critere":"um devant l'heure précise et exception in der Nacht","points":4},{"critere":"Sens juste de morgen, morgens, am Morgen","points":8}],"dureeMin":6,"corrige":"**1.**\n1. **am** Montag — jour\n2. **im** Sommer — saison\n3. **um** acht Uhr — heure précise\n4. **im** Januar — mois\n5. **am** Abend — partie de la journée\n6. **im** Jahr 2026 — année\n7. **in der** Nacht — exception (et non *am*)\n8. **um** Mitternacht — heure précise\n\n**2.**\n- *morgen* = **demain**.\n- *morgens* = **le matin, en général**, habituellement (adverbe).\n- *am Morgen* = **ce matin-là**, un matin précis.\n\nUn seul *s* d'écart suffit à changer le sens."}$exo$::jsonb),
  ('9712f7b8-159d-5a85-b792-992b0ea096f4'::uuid, 2, 'traduction', $exo${"titre":"L'agenda de Lina","consigne":"Traduis les phrases de l'agenda de Lina en commençant chaque phrase par le complément de temps.","enonce":"**L'agenda de Lina, en français**\n\n1. Chaque jour, je vais au collège.\n2. Il y a deux semaines, j'étais à Vienne.\n3. Dans une heure, le film commence.\n4. J'apprends l'allemand depuis trois ans. *(commence par « Seit… »)*\n5. Pendant les vacances, je lis beaucoup.\n6. Du lundi au vendredi, je me lève tôt.\n\n*Aide : in die Schule gehen ; die Woche ; Wien ; die Stunde ; beginnen ; die Ferien (pluriel) ; lesen ; früh aufstehen (ich stehe … auf).*","bareme":[{"critere":"Prépositions et cas justes : vor zwei Wochen, in einer Stunde, seit drei Jahren, während der Ferien, von… bis","points":8},{"critere":"Accusatif sans préposition : jeden Tag","points":3},{"critere":"Inversion verbe-sujet après le complément de temps en tête","points":5},{"critere":"seit + présent","points":4}],"dureeMin":10,"corrige":"**Traduction modèle**\n1. ***Jeden Tag** gehe ich in die Schule.* — durée ou date entière : accusatif sans préposition.\n2. ***Vor zwei Wochen** war ich in Wien.* — *vor* + datif = il y a.\n3. ***In einer Stunde** beginnt der Film.* — *in* + datif = dans (futur).\n4. ***Seit drei Jahren** lerne ich Deutsch.* — *seit* + datif pluriel, verbe au **présent**.\n5. ***Während der Ferien** lese ich viel.* — *während* + génitif ; *Ferien* pluriel → *der*.\n6. ***Von Montag bis Freitag** stehe ich früh auf.*\n\nDans chaque phrase, le complément de temps ouvre la phrase : le verbe reste en 2e position et le sujet passe **derrière** (inversion)."}$exo$::jsonb),
  ('9712f7b8-159d-5a85-b792-992b0ea096f4'::uuid, 3, 'traduction', $exo${"titre":"Des vacances en Italie","consigne":"Corrige le texte d'Inès en justifiant, puis raconte ta journée type en cinq phrases.","enonce":"**Document — La carte postale d'Inès**\n\n> Am Sommer fahre ich nach Italien. Ich bin dort seit zwei Wochen gewesen. Um Abend esse ich Pizza. Morgens stehe ich um neun Uhr auf. Nächsten Woche ich fahre nach Hause.\n\n1. Le texte contient **quatre phrases fautives** (une phrase est correcte). Corrige-les.\n2. Justifie chaque correction.\n3. Raconte ta journée type en **cinq phrases**, avec **cinq compléments de temps différents** ; au moins deux phrases commencent par le complément de temps.","bareme":[{"critere":"Corrections : Im Sommer, Ich bin seit zwei Wochen dort, Am Abend, Nächste Woche fahre ich","points":8},{"critere":"Justifications : im / am, seit + présent, accusatif sans préposition, inversion","points":4},{"critere":"Journée type : cinq compléments de temps différents et justes","points":5},{"critere":"Inversion correcte quand le complément ouvre la phrase","points":3}],"dureeMin":16,"corrige":"**1. Texte corrigé**\n\n> ***Im** Sommer fahre ich nach Italien. Ich **bin** seit zwei Wochen dort. **Am** Abend esse ich Pizza. Morgens stehe ich um neun Uhr auf. **Nächste Woche fahre ich** nach Hause.*\n\n**2. Justifications**\n- Saisons → **im** (*im Sommer*), pas *am*.\n- Avec *seit*, l'action dure encore : **présent** (*ich bin*), pas parfait.\n- Parties de la journée → **am** (*am Abend*) ; *um* est réservé à l'heure précise.\n- *nächste Woche* : accusatif sans préposition, **féminin** → *nächste* ; en tête de phrase, le verbe reste en 2e position → **inversion** (*fahre ich*).\n- La phrase *Morgens stehe ich um neun Uhr auf* est correcte (*morgens* = le matin, habituellement).\n\n**3. Exemple de réponse**\n\n> *Morgens stehe ich um sieben Uhr auf. Um acht Uhr beginnt der Unterricht. Am Mittag esse ich in der Kantine. Nach der Schule spiele ich Fußball. Am Abend lese ich ein Buch.*"}$exo$::jsonb),
  ('7abdd284-4e9f-5adc-88d9-4cbc451e7ab0'::uuid, 1, 'traduction', $exo${"titre":"Sein, haben, werden","consigne":"Complète avec la bonne forme de sein, haben ou werden au temps indiqué, puis donne les trois participes.","enonce":"**1. Complète.**\n\n1. Ihr ___ müde. *(sein, présent)*\n2. Du ___ einen Hund. *(haben, présent)*\n3. Mein Bruder ___ Arzt. *(werden, présent : il devient)*\n4. Gestern ___ ich krank. *(sein, prétérit)*\n5. Wir ___ keine Zeit. *(haben, prétérit)*\n6. Es ___ kalt. *(werden, prétérit)*\n\n**2.** Donne le participe passé de *sein*, *haben* et *werden* (verbe plein).","bareme":[{"critere":"Présents justes : seid, hast, wird","points":8},{"critere":"Prétérits justes : war, hatten, wurde","points":6},{"critere":"Participes justes : gewesen, gehabt, geworden","points":6}],"dureeMin":6,"corrige":"**1.**\n1. Ihr **seid** müde. (attention : *seid* avec d, le verbe ; *seit* avec t est la préposition « depuis »)\n2. Du **hast** einen Hund.\n3. Mein Bruder **wird** Arzt. — *werden* verbe plein = devenir.\n4. Gestern **war** ich krank.\n5. Wir **hatten** keine Zeit.\n6. Es **wurde** kalt.\n\n**2.** *sein → **gewesen*** ; *haben → **gehabt*** ; *werden → **geworden*** (et *worden* seulement quand *werden* est auxiliaire du passif)."}$exo$::jsonb),
  ('7abdd284-4e9f-5adc-88d9-4cbc451e7ab0'::uuid, 2, 'traduction', $exo${"titre":"Haben ou sein au parfait ?","consigne":"Complète chaque phrase au parfait avec haben ou sein conjugué, puis explique la différence entre les phrases 1 et 2.","enonce":"**1. Complète avec *haben* ou *sein*.**\n\n1. Ich ___ nach Berlin gefahren.\n2. Ich ___ das Auto meines Vaters gefahren.\n3. Er ___ um sieben Uhr aufgestanden.\n4. Wir ___ den ganzen Tag zu Hause geblieben.\n5. Sie ___ ein Buch gelesen.\n6. Was ___ passiert?\n7. Das Kind ___ schnell eingeschlafen.\n8. Ich ___ eine Pizza gegessen.\n\n**2.** Les phrases 1 et 2 ont le même verbe, mais pas le même auxiliaire. Explique pourquoi.","bareme":[{"critere":"sein pour les verbes de mouvement et de changement d'état : bin, ist aufgestanden, ist eingeschlafen","points":6},{"critere":"sein pour bleiben et passieren : sind geblieben, ist passiert","points":4},{"critere":"haben pour les autres verbes : habe gefahren (avec COD), hat gelesen, habe gegessen","points":4},{"critere":"Explication : fahren avec un COD prend haben, c'est le sens qui tranche","points":6}],"dureeMin":10,"corrige":"**1.**\n1. Ich **bin** nach Berlin gefahren. — déplacement.\n2. Ich **habe** das Auto meines Vaters gefahren. — *fahren* avec un COD (*das Auto*).\n3. Er **ist** um sieben Uhr aufgestanden. — changement d'état.\n4. Wir **sind** den ganzen Tag zu Hause geblieben. — *bleiben* prend toujours *sein*.\n5. Sie **hat** ein Buch gelesen.\n6. Was **ist** passiert? — *passieren* prend *sein*.\n7. Das Kind **ist** schnell eingeschlafen. — changement d'état.\n8. Ich **habe** eine Pizza gegessen.\n\n**2.** Dans la phrase 1, *fahren* exprime un **déplacement** d'un point à un autre : auxiliaire **sein** (je me suis déplacé). Dans la phrase 2, *fahren* a un **COD** (*das Auto*) : il signifie « conduire » et prend **haben**. C'est le sens de la phrase qui tranche, pas le verbe lui-même."}$exo$::jsonb),
  ('7abdd284-4e9f-5adc-88d9-4cbc451e7ab0'::uuid, 3, 'traduction', $exo${"titre":"Les trois vies de werden","consigne":"Traduis les phrases, corrige la phrase du document, puis explique les emplois de werden.","enonce":"**1. Traduis en allemand.**\n\n1. Je deviens nerveux.\n2. Je reçois une lettre.\n3. Demain, il fera beau.\n4. La maison est en train d'être construite.\n5. Il est devenu médecin.\n6. La maison a été construite en 1990.\n\n*Aide : nervös ; der Brief ; das Wetter ; schön ; bauen (construire) ; der Arzt.*\n\n**Document — phrase d'un élève**\n\n> Ich habe gestern nach Paris gegangen.\n\n**2.** Corrige cette phrase et justifie.\n**3.** Explique en français les trois emplois de *werden* et pourquoi *bekommen* est un piège.","bareme":[{"critere":"werden verbe plein, futur et passif justes (phrases 1, 3, 4)","points":6},{"critere":"bekommen = recevoir (phrase 2)","points":2},{"critere":"Participes justes : ist… geworden, ist… gebaut worden","points":5},{"critere":"Phrase du document corrigée : bin gegangen, verbe de mouvement","points":3},{"critere":"Explication des trois emplois de werden et du faux ami bekommen","points":4}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n1. *Ich **werde** nervös.* — verbe plein : devenir.\n2. *Ich **bekomme** einen Brief.* — *bekommen* = recevoir.\n3. *Morgen **wird** das Wetter schön (**sein**).* — auxiliaire du futur.\n4. *Das Haus **wird gebaut**.* — passif d'action : *werden* + participe.\n5. *Er **ist** Arzt **geworden**.* — parfait de *werden* verbe plein : *sein* + *geworden*.\n6. *Das Haus **ist** 1990 **gebaut worden**.* — parfait du passif : participe *worden*.\n\n**2.** *Ich **bin** gestern nach Paris **gegangen**.* — *gehen* est un verbe de mouvement d'un point à un autre : il forme son parfait avec **sein**.\n\n**3.** *werden* a trois emplois : **verbe plein** « devenir » (*Er wird Arzt*) ; **auxiliaire du futur** (*Es wird regnen*) ; **auxiliaire du passif** d'action (*Das Haus wird gebaut*). Au participe, il fait *geworden* comme verbe plein, *worden* dans un passif. *bekommen* ressemble à « become » ou « devenir », mais il signifie **recevoir** : « je deviens » se dit *ich werde*. La confusion produit un contresens complet."}$exo$::jsonb),
  ('291d895a-d0af-5a20-86e8-86cec57e7728'::uuid, 1, 'traduction', $exo${"titre":"Les temps primitifs","consigne":"Donne les trois temps primitifs (infinitif, prétérit, participe II) de chaque verbe et classe-le.","enonce":"**1. Recopie et complète le tableau.**\n\n| Infinitif | Prétérit (er) | Participe II | Famille |\n| machen | | | |\n| spielen | | | |\n| fahren | | | |\n| schreiben | | | |\n| nehmen | | | |\n| gehen | | | |\n| studieren | | | |\n| bringen | | | |\n\n*Familles : faible, fort, mixte, verbe en -ieren.*\n\n**2.** Quelle différence vois-tu entre le participe d'un verbe faible et celui d'un verbe fort ?","bareme":[{"critere":"Verbes faibles justes : machte / gemacht, spielte / gespielt","points":4},{"critere":"Verbes forts justes : fuhr / gefahren, schrieb / geschrieben, nahm / genommen, ging / gegangen","points":8},{"critere":"Cas particuliers : studierte / studiert sans ge-, brachte / gebracht (mixte)","points":4},{"critere":"Différence ge-…-t / ge-…-en expliquée","points":4}],"dureeMin":8,"corrige":"**1.**\n| Infinitif | Prétérit | Participe II | Famille |\n| machen | machte | gemacht | faible |\n| spielen | spielte | gespielt | faible |\n| fahren | fuhr | gefahren | fort |\n| schreiben | schrieb | geschrieben | fort |\n| nehmen | nahm | genommen | fort |\n| gehen | ging | gegangen | fort |\n| studieren | studierte | studiert | en -ieren (faible, sans ge-) |\n| bringen | brachte | gebracht | mixte |\n\n**2.** Le participe d'un verbe **faible** se forme en *ge-… **-t*** et garde son radical (*gemacht*). Celui d'un verbe **fort** se forme en *ge-… **-en*** et change souvent de voyelle (*gesprochen, genommen*). Le mixte a un radical modifié mais des terminaisons faibles (*gebracht*)."}$exo$::jsonb),
  ('291d895a-d0af-5a20-86e8-86cec57e7728'::uuid, 2, 'traduction', $exo${"titre":"Le samedi de Max","consigne":"Complète les phrases au présent, puis mets le récit de Max au prétérit.","enonce":"**1. Conjugue au présent.**\n\n1. Du ___ gut Deutsch. *(sprechen)*\n2. Er ___ mir das Buch. *(geben)*\n3. ___ du den Film heute Abend? *(sehen)*\n4. Sie ___ einen Roman. *(lesen)*\n5. Du ___ zu schnell! *(fahren)*\n6. Wir ___ ihm ein Geschenk. *(geben)*\n\n**2. Réécris le récit au prétérit.**\n\n> Am Samstag fahre ich nach Köln. Ich nehme den Zug. Im Zug schreibe ich eine Karte. In Köln kaufe ich ein T-Shirt und spiele mit meinem Cousin Fußball.","bareme":[{"critere":"Changement de voyelle aux 2e et 3e personnes du singulier : sprichst, gibt, siehst, liest, fährst","points":8},{"critere":"Pas de changement au pluriel : wir geben","points":2},{"critere":"Prétérits forts justes : fuhr, nahm, schrieb","points":6},{"critere":"Prétérits faibles justes : kaufte, spielte","points":4}],"dureeMin":10,"corrige":"**1.**\n1. Du **sprichst** gut Deutsch. — *e → i*.\n2. Er **gibt** mir das Buch. — *e → i*.\n3. **Siehst** du den Film heute Abend? — *e → ie*.\n4. Sie **liest** einen Roman. — *e → ie*.\n5. Du **fährst** zu schnell! — *a → ä*.\n6. Wir **geben** ihm ein Geschenk. — au pluriel, pas de changement.\n\n**2. Récit au prétérit**\n\n> *Am Samstag **fuhr** ich nach Köln. Ich **nahm** den Zug. Im Zug **schrieb** ich eine Karte. In Köln **kaufte** ich ein T-Shirt und **spielte** mit meinem Cousin Fußball.*\n\n- Verbes forts : la voyelle change et il n'y a pas de terminaison à la 1re personne (*fuhr, nahm, schrieb*).\n- Verbes faibles : radical inchangé + *-te* (*kaufte, spielte*)."}$exo$::jsonb),
  ('291d895a-d0af-5a20-86e8-86cec57e7728'::uuid, 3, 'traduction', $exo${"titre":"Lire un récit au prétérit","consigne":"Analyse les verbes du récit, réécris-en une partie au parfait, puis traduis la dernière phrase.","enonce":"**Document — Le voyage de Paul**\n\n> Letzten Sommer **fuhr** Paul nach Hamburg. Er **nahm** den Zug und **schrieb** seiner Mutter eine Karte. Er **kaufte** ein Souvenir und **telefonierte** mit seinem Freund. Am Abend **dachte** er an seine Familie.\n\n1. Pour chaque verbe en gras, donne l'**infinitif** et la **famille** (fort, faible, mixte, en -ieren).\n2. Réécris les deux premières phrases du récit au **parfait**. *(Aide : fahren se conjugue avec sein au parfait, les autres avec haben.)*\n3. Traduis en allemand : **Il parle allemand et elle lit un livre.**","bareme":[{"critere":"Infinitifs justes : fahren, nehmen, schreiben, kaufen, telefonieren, denken","points":5},{"critere":"Familles justes : trois forts, un faible, un en -ieren, un mixte","points":4},{"critere":"Parfait juste : ist gefahren, hat genommen, geschrieben, gekauft, telefoniert (sans ge-)","points":7},{"critere":"Traduction avec les changements de voyelle : spricht, liest","points":4}],"dureeMin":16,"corrige":"**1.**\n| Forme | Infinitif | Famille |\n| fuhr | fahren | fort |\n| nahm | nehmen | fort |\n| schrieb | schreiben | fort |\n| kaufte | kaufen | faible (-te) |\n| telefonierte | telefonieren | en -ieren (faible) |\n| dachte | denken | mixte (radical modifié, terminaison faible) |\n\n**2. Au parfait**\n\n> *Letzten Sommer **ist** Paul nach Hamburg **gefahren**. Er **hat** den Zug **genommen** und seiner Mutter eine Karte **geschrieben**.*\n\n(La suite, si l'élève la réécrit : *Er hat ein Souvenir **gekauft** und mit seinem Freund **telefoniert**.* — pas de *ge-* pour les verbes en *-ieren* ; *Am Abend hat er an seine Familie **gedacht**.*)\n\n**3.** *Er **spricht** Deutsch und sie **liest** ein Buch.* — verbes forts : *e → i* (*sprechen*) et *e → ie* (*lesen*) à la 3e personne du singulier."}$exo$::jsonb),
  ('11217a44-31bc-57c7-8fca-38a3cad9cc05'::uuid, 1, 'traduction', $exo${"titre":"Le bon modal","consigne":"Complète chaque phrase avec le verbe de modalité qui convient, conjugué au présent, puis réponds à la question 2.","enonce":"**1. Complète.**\n\n1. Ich ___ gut schwimmen. *(capacité)*\n2. ___ ich reinkommen? *(autorisation)*\n3. Du ___ heute lernen, morgen ist der Test. *(nécessité)*\n4. Wir ___ im Sommer nach Berlin fahren. *(volonté)*\n5. Ich ___ einen Kaffee, bitte. *(demande polie)*\n6. Der Arzt sagt, er ___ im Bett bleiben. *(consigne venue d'autrui)*\n\n**2.** Dans la phrase 3, où se place l'infinitif *lernen* ? Énonce la règle.","bareme":[{"critere":"Modal juste selon le sens : kann, darf, musst, wollen, möchte, soll","points":8},{"critere":"Conjugaison juste, sans terminaison aux 1re et 3e personnes du singulier","points":8},{"critere":"Règle : modal en 2e position, infinitif à la fin","points":4}],"dureeMin":6,"corrige":"**1.**\n1. Ich **kann** gut schwimmen. — *können* : capacité.\n2. **Darf** ich reinkommen? — *dürfen* : permission.\n3. Du **musst** heute lernen, morgen ist der Test. — *müssen* : nécessité.\n4. Wir **wollen** im Sommer nach Berlin fahren. — *wollen* : volonté.\n5. Ich **möchte** einen Kaffee, bitte. — forme polie de *mögen*.\n6. Der Arzt sagt, er **soll** im Bett bleiben. — *sollen* : consigne venue d'autrui.\n\n**2.** Dans une principale, le modal conjugué est en **2e position** et l'infinitif part **à la fin** de la phrase : *Du musst heute **lernen**.*"}$exo$::jsonb),
  ('11217a44-31bc-57c7-8fca-38a3cad9cc05'::uuid, 2, 'traduction', $exo${"titre":"Le règlement de l'auberge","consigne":"Lis le règlement de l'auberge de jeunesse, puis réponds aux questions en allemand.","enonce":"**Document — Jugendherberge Bremen**\n\n> Rauchen verboten! — Frühstück von 7 bis 9 Uhr. — Die Zimmer sind um 10 Uhr frei. — Fahrräder: 8 Euro pro Tag. — Die Küche ist für alle offen.\n\n1. Écris **quatre phrases** avec *man* + un modal pour résumer le règlement : une interdiction, une obligation, une possibilité, une autorisation.\n2. Traduis et explique la différence : *Du musst nicht kommen.* / *Du darfst nicht rauchen.*\n3. Relie les deux phrases avec *weil* : *Ich kann heute nicht kommen. Ich muss lernen.*\n\n*Aide : rauchen ; frühstücken ; das Zimmer verlassen (quitter la chambre) ; mieten (louer) ; kochen.*","bareme":[{"critere":"Quatre phrases avec man + modal adapté au sens (darf nicht, muss, kann, darf)","points":8},{"critere":"Négation : muss nicht = pas obligé, darf nicht = interdiction","points":6},{"critere":"Subordonnée avec weil : infinitif puis modal à la fin","points":6}],"dureeMin":10,"corrige":"**1. Exemples de réponses**\n- Interdiction : *Man **darf** hier nicht **rauchen**.*\n- Obligation : *Man **muss** das Zimmer um 10 Uhr **verlassen**.*\n- Possibilité : *Man **kann** Fahrräder **mieten**.* (ou *Man kann von 7 bis 9 Uhr frühstücken.*)\n- Autorisation : *Man **darf** in der Küche **kochen**.*\n\n**2.**\n- *Du musst nicht kommen* = **tu n'es pas obligé** de venir.\n- *Du darfst nicht rauchen* = **tu n'as pas le droit** de fumer (interdiction).\n*müssen* + négation supprime l'obligation ; l'interdiction se dit avec *nicht dürfen*.\n\n**3.** *Ich kann heute nicht kommen, **weil** ich **lernen muss**.* — en subordonnée, tout part à la fin : l'infinitif, puis le modal conjugué."}$exo$::jsonb),
  ('11217a44-31bc-57c7-8fca-38a3cad9cc05'::uuid, 3, 'traduction', $exo${"titre":"Ce qu'on a dû faire","consigne":"Transforme les phrases au passé, traduis la phrase rapportée, puis écris un court texte sur tes projets.","enonce":"**1. Mets au parfait.**\na. Ich muss arbeiten.\nb. Er kann nicht kommen.\nc. Ich will es. *(sans infinitif)*\n\n**2. Mets au prétérit.**\na. Wir können nicht schwimmen.\nb. Sie muss lernen.\n\n**3.** Traduis en allemand, avec *sollen* : « Le médecin m'a dit de rester au lit. » (Commence par *Ich…*)\n\n**4.** Écris **quatre phrases** sur tes projets pour l'été, avec **quatre modaux différents**.\n\n*Aide : im Bett bleiben ; im Sommer ; arbeiten, reisen, schlafen.*","bareme":[{"critere":"Parfait avec double infinitif : habe arbeiten müssen, hat nicht kommen können ; participe gewollt sans infinitif","points":6},{"critere":"Prétérits justes sans Umlaut : konnten, musste","points":4},{"critere":"sollen employé pour rapporter une consigne : Ich soll im Bett bleiben","points":3},{"critere":"Quatre phrases avec quatre modaux différents, bien conjugués, infinitif à la fin","points":7}],"dureeMin":16,"corrige":"**1.**\na. *Ich **habe arbeiten müssen**.* — avec un infinitif dépendant : **double infinitif**, pas de participe.\nb. *Er **hat nicht kommen können**.*\nc. *Ich **habe es gewollt**.* — sans infinitif, le participe existe.\n\n**2.**\na. *Wir **konnten** nicht schwimmen.*\nb. *Sie **musste** lernen.* — prétérit régulier, **sans inflexion**.\n\n**3.** *Ich **soll** im Bett bleiben.* — *sollen* rapporte une consigne extérieure (on m'a dit de…).\n\n**4. Exemple de réponse**\n\n> *Im Sommer will ich nach Österreich reisen. Dort kann ich wandern. Ich darf zum ersten Mal allein fahren. Aber ich muss vorher etwas Geld verdienen.*\n\nSont vérifiés : un modal différent par phrase, conjugué, et l'infinitif en fin de phrase."}$exo$::jsonb),
  ('96113ee5-5d37-5c00-992b-b587c7e3b674'::uuid, 1, 'traduction', $exo${"titre":"Le préverbe à sa place","consigne":"Construis chaque phrase au présent, puis donne le participe passé de chaque verbe.","enonce":"**1. Construis la phrase au présent.**\n\n1. aufstehen — ich — um sieben Uhr\n2. einkaufen — wir — am Samstag\n3. anrufen — er — seine Mutter\n4. besuchen — ich — meine Tante\n5. verstehen — du — den Text\n\n**2.** Donne le participe passé de : *aufstehen, einkaufen, anrufen, besuchen, verstehen*.","bareme":[{"critere":"Préverbe séparable en fin de phrase : stehe… auf, kaufen… ein, ruft… an","points":8},{"critere":"Verbes inséparables non coupés : besuche, verstehst","points":4},{"critere":"Participes justes : aufgestanden, eingekauft, angerufen (ge- intercalé), besucht, verstanden (sans ge-)","points":8}],"dureeMin":6,"corrige":"**1.**\n1. *Ich **stehe** um sieben Uhr **auf**.* — le préverbe ferme la phrase.\n2. *Wir **kaufen** am Samstag **ein**.*\n3. *Er **ruft** seine Mutter **an**.*\n4. *Ich **besuche** meine Tante.* — *be-* est inséparable : rien ne bouge.\n5. *Du **verstehst** den Text.* — *ver-* inséparable.\n\n**2.**\n- *aufstehen → **aufgestanden*** ; *einkaufen → **eingekauft*** ; *anrufen → **angerufen*** — le *ge-* s'intercale entre le préverbe et le radical.\n- *besuchen → **besucht*** ; *verstehen → **verstanden*** — inséparables : **pas de ge-**."}$exo$::jsonb),
  ('96113ee5-5d37-5c00-992b-b587c7e3b674'::uuid, 2, 'traduction', $exo${"titre":"La journée de Lukas","consigne":"À partir des notes de Lukas, rédige sa journée en allemand, puis transforme deux phrases comme demandé.","enonce":"**Document — Les notes de Lukas**\n\n| Heure | Action |\n| 7 h | aufstehen |\n| 8 h | mit dem Bus abfahren |\n| 17 h | im Supermarkt einkaufen |\n| 19 h | fernsehen |\n| 22 h | einschlafen |\n\n1. Écris **cinq phrases** au présent sur la journée de Lukas (3e personne). Commence au moins deux phrases par l'heure.\n2. Relie avec *weil* : *Lukas ist müde. Er steht um sieben Uhr auf.*\n3. Complète avec *zu* : *Lukas hat keine Lust, ___ (einkaufen).*","bareme":[{"critere":"Préverbe en fin de phrase dans les principales : steht… auf, fährt… ab, kauft… ein, sieht… fern, schläft… ein","points":8},{"critere":"Inversion quand l'heure ouvre la phrase et verbes forts bien conjugués (fährt, sieht, schläft)","points":4},{"critere":"Subordonnée : préverbe recollé en fin (aufsteht)","points":4},{"critere":"zu intercalé : einzukaufen","points":4}],"dureeMin":10,"corrige":"**1. Exemple de réponse**\n- *Um sieben Uhr **steht** Lukas **auf**.*\n- *Um acht Uhr **fährt** er mit dem Bus **ab**.*\n- *Um siebzehn Uhr **kauft** er im Supermarkt **ein**.*\n- *Um neunzehn Uhr **sieht** er **fern**.*\n- *Um zweiundzwanzig Uhr **schläft** er **ein**.*\n\nLe préverbe séparable ferme la phrase ; l'heure en tête entraîne l'inversion ; *fahren, sehen, schlafen* changent de voyelle à la 3e personne.\n\n**2.** *Lukas ist müde, **weil** er um sieben Uhr **aufsteht**.* — en subordonnée, le préverbe se **recolle** au verbe, à la fin.\n\n**3.** *Lukas hat keine Lust, **einzukaufen**.* — le *zu* s'intercale entre le préverbe et le radical."}$exo$::jsonb),
  ('96113ee5-5d37-5c00-992b-b587c7e3b674'::uuid, 3, 'traduction', $exo${"titre":"Kommen et sa famille","consigne":"Donne le sens des verbes, traduis les phrases, puis explique comment reconnaître un préverbe séparable.","enonce":"**1.** Donne le sens de : *kommen, ankommen, bekommen, mitkommen, umkommen*.\n\n**2. Traduis en allemand.**\na. Le train arrive à huit heures.\nb. Je reçois un cadeau.\nc. Tu viens avec nous ?\nd. Elle traduit le texte.\ne. Le train est arrivé. *(parfait avec sein)*\nf. J'ai reçu un cadeau. *(parfait avec haben)*\n\n*Aide : der Zug ; das Geschenk ; übersetzen ; der Text.*\n\n**3.** Explique en français le test qui permet de savoir si un préverbe est séparable, et pourquoi *übersetzen* peut être les deux.","bareme":[{"critere":"Sens justes des cinq verbes","points":4},{"critere":"Phrases au présent : kommt… an, bekomme, Kommst du mit?, übersetzt (non coupé)","points":6},{"critere":"Participes : ist angekommen (ge- intercalé), habe bekommen (sans ge-)","points":4},{"critere":"Explication : test de l'accent et double statut selon le sens concret ou figuré","points":6}],"dureeMin":16,"corrige":"**1.** *kommen* = venir ; *ankommen* = arriver ; *bekommen* = recevoir ; *mitkommen* = accompagner, venir avec ; *umkommen* = périr. Le sens dépend entièrement du préverbe.\n\n**2.**\na. *Der Zug **kommt** um acht Uhr **an**.*\nb. *Ich **bekomme** ein Geschenk.* — *be-* inséparable.\nc. ***Kommst** du **mit**?*\nd. *Sie **übersetzt** den Text.* — sens figuré (traduire) → inséparable.\ne. *Der Zug **ist angekommen**.* — *ge-* intercalé.\nf. *Ich **habe** ein Geschenk **bekommen**.* — inséparable : pas de *ge-*.\n\n**3.** Le seul critère fiable est l'**accent** : un préverbe **séparable** est accentué (*ÁN-kommen*), un préverbe **inséparable** ne l'est pas, l'accent tombe sur le radical (*be-KÓMMEN*). *über-* fait partie des préverbes à double statut : au sens **concret**, il est séparable (*Ich setze über* = je traverse en bateau) ; au sens **figuré**, il est inséparable (*Ich übersetze den Text* = je traduis)."}$exo$::jsonb),
  ('4989d2df-694b-5ebb-a359-bc891a3e6873'::uuid, 1, 'traduction', $exo${"titre":"Mich ou mir ?","consigne":"Complète chaque phrase avec le pronom réfléchi qui convient, puis explique la différence entre les phrases 1 et 2.","enonce":"**1. Complète avec le pronom réfléchi.**\n\n1. Ich wasche ___.\n2. Ich wasche ___ die Hände.\n3. Du kaufst ___ ein Buch.\n4. Er freut ___ auf die Ferien.\n5. Wir interessieren ___ für Musik.\n6. Setzen Sie ___ bitte!\n\n**2.** Pourquoi écrit-on *mich* dans la phrase 1 et *mir* dans la phrase 2 ?","bareme":[{"critere":"Réfléchis à l'accusatif sans COD : mich, sich, uns","points":6},{"critere":"Réfléchis au datif en présence d'un COD : mir, dir","points":6},{"critere":"sich en minuscule dans le vouvoiement","points":3},{"critere":"Explication : un COD dans la phrase fait passer le réfléchi au datif","points":5}],"dureeMin":6,"corrige":"**1.**\n1. Ich wasche **mich**. — pas de COD → accusatif.\n2. Ich wasche **mir** die Hände. — *die Hände* est COD → datif.\n3. Du kaufst **dir** ein Buch. — COD *ein Buch* → datif.\n4. Er freut **sich** auf die Ferien.\n5. Wir interessieren **uns** für Musik.\n6. Setzen Sie **sich** bitte! — *sich* ne prend **jamais** de majuscule, même dans le vouvoiement.\n\n**2.** Dans la phrase 1, il n'y a pas d'autre complément : le réfléchi est le COD → **accusatif** (*mich*). Dans la phrase 2, il y a déjà un COD (*die Hände*) : le réfléchi passe au **datif** (*mir*). Les deux séries ne diffèrent qu'aux deux premières personnes du singulier."}$exo$::jsonb),
  ('4989d2df-694b-5ebb-a359-bc891a3e6873'::uuid, 2, 'traduction', $exo${"titre":"Le message d'Ambre","consigne":"Ambre écrit à sa correspondante. Traduis ses phrases en allemand, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n1. Je me souviens de mes vacances.\n2. Je m'intéresse au sport.\n3. Je me réjouis de ton cadeau (je l'ai reçu).\n4. Je me réjouis du week-end (il n'est pas encore là).\n5. Je me lève à sept heures.\n6. Je suis souvent en retard.\n\n*Aide : sich erinnern ; der Sport ; das Geschenk ; das Wochenende ; aufstehen ; sich verspäten ; oft.*\n\n**2.** Explique pourquoi la phrase 5 n'a pas de pronom réfléchi en allemand et pourquoi la phrase 6 en a un.","bareme":[{"critere":"Prépositions justes suivies de l'accusatif : an meine Ferien, für Sport","points":6},{"critere":"auf (à venir) et über (déjà arrivé) bien distingués","points":6},{"critere":"Faux pronominaux : stehe… auf sans réfléchi, verspäte mich","points":4},{"critere":"Explication juste des faux pronominaux","points":4}],"dureeMin":10,"corrige":"**1. Traduction modèle**\n1. *Ich erinnere mich **an** meine Ferien.* — *sich erinnern an* + accusatif.\n2. *Ich interessiere mich **für** Sport.* — *sich interessieren für* + accusatif.\n3. *Ich freue mich **über** dein Geschenk.* — ce qui est déjà arrivé → *über*.\n4. *Ich freue mich **auf** das Wochenende.* — ce qui vient → *auf*.\n5. *Ich **stehe** um sieben Uhr **auf**.* — pas de pronom.\n6. *Ich **verspäte mich** oft.*\n\n**2.** Certains verbes pronominaux en français ne le sont pas en allemand : *aufstehen* (se lever) n'a pas de réfléchi. À l'inverse, *sich verspäten* (être en retard) est pronominal en allemand mais pas en français. Il faut apprendre chaque verbe avec sa construction."}$exo$::jsonb),
  ('4989d2df-694b-5ebb-a359-bc891a3e6873'::uuid, 3, 'traduction', $exo${"titre":"Le pronom au bon endroit","consigne":"Place les pronoms, corrige le texte de Malo en justifiant, puis écris quatre phrases sur toi.","enonce":"**1. Place le pronom réfléchi au bon endroit.**\na. Gestern hat mein Bruder verletzt. *(sich)*\nb. Ich bin glücklich, weil ich freue. *(mich)*\nc. Heute Abend sehe ich den Film an. *(mir)*\n\n**Document — Le texte de Malo**\n\n> Jeden Morgen wasche ich mich die Haare. Mein Freund interessiert sich an Fußball. Nächste Woche beginnen die Ferien: wir freuen uns schon über die Ferien. Am Sonntag spaziere ich mich im Park.\n\n**2.** Chaque phrase contient une faute. Corrige-les et justifie.\n\n**3.** Écris **quatre phrases** sur toi avec quatre verbes pronominaux différents du cours (dont un au datif avec COD).","bareme":[{"critere":"Place juste du pronom : hat sich mein Bruder, weil ich mich freue, sehe mir… an","points":5},{"critere":"Corrections : mir die Haare, für Fußball, auf die Ferien, gehe… spazieren","points":6},{"critere":"Justifications : datif avec COD, bonne préposition, auf / über, faux pronominal","points":3},{"critere":"Quatre phrases personnelles correctes, dont un réfléchi au datif avec COD","points":6}],"dureeMin":16,"corrige":"**1.**\na. *Gestern hat **sich** mein Bruder verletzt.* — inversion : le pronom vient après le verbe, **avant** un sujet nominal.\nb. *Ich bin glücklich, weil ich **mich** freue.* — subordonnée : après le sujet.\nc. *Heute Abend sehe ich **mir** den Film an.* — COD *den Film* → datif, juste après le verbe et le sujet inversé.\n\n**2. Texte corrigé**\n- *Jeden Morgen wasche ich **mir** die Haare.* — il y a un COD (*die Haare*) → réfléchi au datif.\n- *Mein Freund interessiert sich **für** Fußball.* — *sich interessieren für* + accusatif.\n- *Wir freuen uns schon **auf** die Ferien.* — les vacances sont à venir → *auf* ; *über* pour ce qui est déjà arrivé.\n- *Am Sonntag **gehe** ich im Park **spazieren**.* — « se promener » n'est pas pronominal en allemand.\n\n**3. Exemple de réponse**\n- *Ich interessiere mich für Geschichte.*\n- *Ich erinnere mich gern an meine Kindheit.*\n- *Ich freue mich auf die Sommerferien.*\n- *Am Wochenende kaufe ich mir ein neues Buch.* — réfléchi au datif avec le COD *ein neues Buch*."}$exo$::jsonb),
  ('4113f286-ddf7-57a8-9154-2816837bdad1'::uuid, 1, 'traduction', $exo${"titre":"Le Rhin et le Danube, des frontières devenues des liens","consigne":"Lis le texte, puis réponds aux questions en français, sauf indication contraire.","enonce":"**Texte**\n\n> Der Rhein fließt von den Schweizer Alpen bis zur Nordsee. Er ist der meistbefahrene Fluss Europas. Die Donau ist viel länger: Sie fließt vom Schwarzwald bis zum Schwarzen Meer, durch zehn Länder und vier Hauptstädte. Früher waren diese Flüsse oft Grenzen und Schlachtfelder. Heute verbindet die Europabrücke Straßburg und Kehl, und ein Radweg führt an der Donau entlang.\n\n*Aide : meistbefahren = le plus fréquenté ; das Schlachtfeld = le champ de bataille ; der Radweg = la piste cyclable.*\n\n1. Relève dans le texte : a) où le Rhin prend sa source ; b) où il se jette ; c) où se jette le Danube ; d) combien de pays il traverse.\n2. Traduis en français la dernière phrase du texte (*Heute verbindet…*).\n3. En une ou deux phrases, explique ce que le texte oppose entre *früher* et *heute*.","bareme":[{"critere":"Les quatre informations relevées exactement (Alpes suisses, mer du Nord, mer Noire, dix pays)","points":8},{"critere":"Traduction juste de la dernière phrase (verbindet, Europabrücke, Radweg, entlang)","points":8},{"critere":"Opposition expliquée : hier frontières et guerres, aujourd'hui liens et coopération","points":4}],"dureeMin":7,"corrige":"1. a) Le Rhin prend sa source dans les **Alpes suisses** (*von den Schweizer Alpen*). b) Il se jette dans la **mer du Nord** (*bis zur Nordsee*). c) Le Danube se jette dans la **mer Noire** (*bis zum Schwarzen Meer*). d) Il traverse **dix pays** (*durch zehn Länder*).\n\n2. Traduction modèle : « Aujourd'hui, le pont de l'Europe relie Strasbourg et Kehl, et une piste cyclable longe le Danube. » (« relie Strasbourg à Kehl » accepté ; *führt an der Donau entlang* = « longe le Danube » ou « suit le Danube ».)\n\n3. **Autrefois** (*früher*), les fleuves séparaient : c'étaient des frontières et des champs de bataille. **Aujourd'hui** (*heute*), ils relient : un pont unit la France et l'Allemagne, une piste cyclable suit le Danube. Les fleuves sont passés de la séparation à l'échange et à la coopération."}$exo$::jsonb),
  ('4113f286-ddf7-57a8-9154-2816837bdad1'::uuid, 2, 'traduction', $exo${"titre":"Ce que raconte une Currywurst","consigne":"Lis le texte, réponds aux questions 1 et 2 en français, puis rédige la question 3 en allemand.","enonce":"**Texte (inventé pour le sujet)**\n\n> Mein Opa sagt immer: „Was wir essen, erzählt unsere Geschichte.“ Die Currywurst wurde 1949 in Berlin erfunden, mit Ketchup und Curry von den alliierten Soldaten. Den Döner haben türkische Einwanderer bekannt gemacht, Pizza und Pasta kamen mit den italienischen Gastarbeitern. Heute isst meine Klasse mittags Döner, Pizza oder Currywurst, und niemand denkt darüber nach, woher diese Gerichte kommen.\n\n*Aide : erfinden = inventer ; der Einwanderer = l'immigré ; das Gericht = le plat.*\n\n1. D'après le texte, d'où vient chacun de ces plats : la Currywurst, le Döner, la pizza et les pâtes ?\n2. Traduis en français : *Den Döner haben türkische Einwanderer bekannt gemacht.*\n3. **En allemand (3 à 4 phrases)** : explique pourquoi le grand-père a raison. Emploie au moins deux de ces mots : *der Austausch, prägen, die Vielfalt*.","bareme":[{"critere":"Origine des trois plats donnée d'après le texte (soldats alliés, immigrés turcs, travailleurs italiens)","points":5},{"critere":"Traduction juste de la phrase (ordre des mots, sujet = Einwanderer)","points":5},{"critere":"Production : l'idée que la cuisine garde la trace des échanges, avec des exemples du texte","points":6},{"critere":"Correction de l'allemand (verbe en 2e position, verbe à la fin des subordonnées, mots imposés)","points":4}],"dureeMin":11,"corrige":"1. - **Currywurst** : inventée à Berlin en 1949, avec le ketchup et le curry des **soldats alliés**.\n- **Döner** : rendu célèbre par des **immigrés turcs**.\n- **Pizza et pâtes** : arrivées avec les **travailleurs immigrés italiens** (*Gastarbeiter*).\n\n2. « Ce sont des immigrés turcs qui ont rendu le Döner célèbre. » (ou « Des immigrés turcs ont fait connaître le Döner. ») Piège : *den Döner* est à l'accusatif (COD), placé en tête ; le sujet est *türkische Einwanderer*. Traduire « Le Döner a rendu célèbres des immigrés turcs » est un contresens.\n\n3. Production modèle :\n*Der Opa hat recht, denn das Essen erzählt vom Austausch mit anderen Ländern. Die Currywurst erinnert an die alliierten Soldaten, der Döner an die türkischen Einwanderer. Die Pizza zeigt, dass die italienischen Gastarbeiter Deutschland geprägt haben. So spiegelt das Essen die Vielfalt des Landes.*\n\nÉléments attendus : au moins deux exemples tirés du texte, l'idée que les migrations ont transformé les habitudes allemandes, deux mots imposés employés correctement (*prägen* au parfait : *haben … geprägt*). Vérifier : verbe conjugué en 2e position, verbe à la fin après *dass* et *denn* suivi de l'ordre normal."}$exo$::jsonb),
  ('4113f286-ddf7-57a8-9154-2816837bdad1'::uuid, 3, 'traduction', $exo${"titre":"Un échange change-t-il aussi celui qui accueille ?","consigne":"À partir du dossier, rédige en allemand un texte argumenté de 100 à 120 mots. Appuie-toi sur au moins trois exemples du dossier et nuance ta réponse.","enonce":"**Sujet :** *„Ein Austausch verändert auch den, der aufnimmt.“ Stimmst du zu?*\n\n**Dossier**\n\n| Thème | Repère |\n|---|---|\n| Fleuves | Le Rhin et l'Oder ont longtemps été des frontières ; aujourd'hui, le pont de l'Europe relie Strasbourg et Kehl. |\n| Accueil | En 2015, plus d'un million de réfugiés arrivent ; des bénévoles les accueillent dans les gares (*Willkommenskultur*). Angela Merkel déclare « *Wir schaffen das* ». Le pays connaît aussi la méfiance et la montée d'un parti hostile à l'immigration. |\n| Cuisine | Currywurst (Berlin, 1949, ketchup et curry des soldats alliés), Döner des immigrés turcs, pizza des *Gastarbeiter* italiens. |\n| Argent | Deutsche Mark (1948), symbole du miracle économique ; euro (2002), BCE à Francfort. |\n\n**Mots utiles** : *der Austausch, die Aufnahme, die Integration, die Vielfalt, prägen, der Flüchtling (le réfugié), der Freiwillige (le bénévole)*.","bareme":[{"critere":"Au moins trois exemples du dossier exploités avec exactitude","points":6},{"critere":"Prise de position claire, nuancée (limites, méfiance) et conclusion","points":5},{"critere":"Lexique du chapitre employé à bon escient","points":4},{"critere":"Correction grammaticale : place du verbe, cas, temps du passé","points":5}],"dureeMin":18,"corrige":"**Texte modèle (≈ 110 mots)**\n\n*Ich stimme dieser Aussage zu. Erstens hat die Ankunft von über einer Million Flüchtlingen im Jahr 2015 Deutschland verändert: Viele Freiwillige haben in den Bahnhöfen geholfen, und die Integration ist heute eine tägliche Aufgabe. Zweitens prägt der Austausch auch das Essen: Die Currywurst, der Döner oder die Pizza erzählen die Geschichte der Soldaten und der Gastarbeiter. Drittens waren der Rhein und die Oder früher Grenzen, heute verbinden sie die Menschen. Allerdings gab es auch Misstrauen, und eine Partei gegen Einwanderung ist stärker geworden. Trotzdem glaube ich, dass die Vielfalt Deutschland reicher gemacht hat. Ein Austausch lässt niemanden unverändert.*\n\n**Éléments attendus**\n- Une thèse annoncée (*Ich stimme zu* / *Ich bin der Meinung, dass…*).\n- Trois exemples exacts : l'accueil de 2015, la cuisine, les fleuves (ou la monnaie : le Deutsche Mark devenu symbole de l'identité économique, puis l'euro).\n- Une nuance : la méfiance, le parti hostile à l'immigration, l'intégration qui reste un défi (langue, école, travail).\n- Une conclusion.\n\n**Langue** : verbe en 2e position après *Erstens, Zweitens, Trotzdem* (inversion) ; verbe à la fin après *dass* ; parfait correct (*haben geholfen, ist geworden*) ; *von* + datif (*von über einer Million Flüchtlingen*). Toute production entre 100 et 120 mots qui remplit ces critères obtient la totalité des points."}$exo$::jsonb),
  ('3ac783e3-7a43-5c51-b685-18bfe2989ee5'::uuid, 1, 'traduction', $exo${"titre":"Lena et son club de sport","consigne":"Lis le texte, puis réponds aux questions en français.","enonce":"**Texte (inventé pour le sujet)**\n\n> Lena ist 17 und Mitglied in einem Sportverein. Jeden Samstag trainiert sie die Kinder des Vereins. Einmal im Jahr wählen die Mitglieder einen Vorstand, und sie stimmen über wichtige Fragen ab. „Hier lerne ich, mich für andere zu engagieren“, sagt Lena. In Deutschland gibt es mehr als 600 000 Vereine.\n\n*Aide : das Mitglied = le membre ; der Vorstand = le bureau ; abstimmen = voter.*\n\n1. Vrai ou faux ? Justifie chaque réponse en citant le texte.\n   a) Lena entraîne des adultes.\n   b) Les membres de l'association votent.\n   c) L'Allemagne compte moins de 100 000 associations.\n2. Traduis : *„Hier lerne ich, mich für andere zu engagieren.“*\n3. D'après le texte, pourquoi peut-on dire que le *Verein* est une « école de démocratie » ?","bareme":[{"critere":"Trois réponses vrai/faux justes, chacune justifiée par une citation","points":9},{"critere":"Traduction juste (sich engagieren für = s'engager pour)","points":6},{"critere":"Explication : élire, voter, s'engager pour les autres","points":5}],"dureeMin":7,"corrige":"1. a) **Faux** : *Jeden Samstag trainiert sie die Kinder des Vereins* — elle entraîne des enfants.\nb) **Vrai** : *sie stimmen über wichtige Fragen ab* (et *die Mitglieder wählen einen Vorstand*).\nc) **Faux** : *In Deutschland gibt es mehr als 600 000 Vereine.*\n\n2. « Ici, j'apprends à m'engager pour les autres. »\n\n3. Dans le *Verein*, on pratique la démocratie : les membres **élisent un bureau** (*wählen einen Vorstand*), **votent** sur les questions importantes (*stimmen ab*) et **s'engagent pour les autres**, comme Lena qui entraîne les enfants. On y apprend donc, concrètement, à décider ensemble et à se rendre utile."}$exo$::jsonb),
  ('3ac783e3-7a43-5c51-b685-18bfe2989ee5'::uuid, 2, 'traduction', $exo${"titre":"L'inclusion à l'école allemande","consigne":"Traduis le texte en français (question 1), puis réponds à la question 2 en allemand.","enonce":"**Texte**\n\n> Seit 1994 steht im Grundgesetz: „Niemand darf wegen seiner Behinderung benachteiligt werden.“ Seit 2009 sollen Schüler mit Behinderung möglichst in normalen Klassen lernen, nicht in speziellen Schulen. Das nennt man Inklusion. Der Weg ist noch lang, aber der Sport für alle hat die Blicke verändert.\n\n*Aide : das Grundgesetz = la Loi fondamentale ; möglichst = autant que possible ; der Blick = le regard.*\n\n1. Traduis le texte en français.\n2. **En allemand (2 à 3 phrases)** : explique ce qu'est l'inclusion et pourquoi, selon le texte, le chemin est « encore long ».","bareme":[{"critere":"Traduction de la phrase de la Loi fondamentale (niemand, wegen, benachteiligen)","points":5},{"critere":"Traduction juste du reste du texte, sans contresens","points":5},{"critere":"Production : définition exacte de l'Inklusion et idée d'un progrès inachevé","points":6},{"critere":"Correction de l'allemand (place du verbe, accords)","points":4}],"dureeMin":11,"corrige":"1. Traduction modèle :\n« Depuis 1994, on peut lire dans la Loi fondamentale : “Nul ne doit être défavorisé en raison de son handicap.” Depuis 2009, les élèves handicapés doivent, autant que possible, apprendre dans des classes ordinaires, et non dans des écoles spécialisées. C'est ce qu'on appelle l'inclusion. Le chemin est encore long, mais le sport pour tous a changé les regards. »\n\nPoints vérifiés : *niemand* = nul, personne ; *wegen* + génitif = en raison de ; *benachteiligt werden* = être défavorisé (passif) ; *sollen* = doivent (c'est un objectif) ; *nicht in speziellen Schulen* = et non dans des écoles spécialisées.\n\n2. Production modèle :\n*Inklusion bedeutet, dass Schüler mit Behinderung in normalen Klassen lernen. Der Weg ist noch lang, weil sie nicht immer in normalen Klassen lernen können. Aber der Sport hat gezeigt, dass alle zusammen leben können.*\n\nÉléments attendus : la définition (classes ordinaires plutôt qu'écoles spécialisées) ; l'idée que l'objectif n'est pas encore atteint (*möglichst*, *noch lang*). Verbe à la fin après *dass* et *weil*."}$exo$::jsonb),
  ('3ac783e3-7a43-5c51-b685-18bfe2989ee5'::uuid, 3, 'traduction', $exo${"titre":"La parabole des anneaux, une leçon pour aujourd'hui ?","consigne":"Lis le document, puis rédige en allemand un texte argumenté de 100 à 120 mots. Relie la parabole à au moins deux repères du vivre-ensemble allemand d'aujourd'hui.","enonce":"**Document 1 — La parabole des trois anneaux (résumé écrit pour le sujet, d'après *Nathan le Sage* de Lessing, 1779)**\n\n> Ein Vater hat drei Söhne. Er liebt alle drei gleich und gibt jedem einen Ring. Die drei Ringe sehen gleich aus, und niemand kann sagen, welcher der echte ist. Die Botschaft: Jeder soll durch sein Verhalten zeigen, dass sein Ring wertvoll ist. Die Ringe stehen für drei Religionen: das Judentum, das Christentum und den Islam.\n\n**Document 2 — Repères**\n- 1949 : la Loi fondamentale interdit toute discrimination (article 3).\n- 1994 : suppression du paragraphe 175, qui punissait l'homosexualité.\n- 2017 : mariage pour tous (*Ehe für alle*).\n- Plus de 600 000 associations (*Vereine*).\n\n**Sujet :** *Was kann uns die Ringparabel heute über das Zusammenleben lehren?*","bareme":[{"critere":"Sens de la parabole bien restitué : impossible de savoir quelle religion est la vraie, on juge la conduite","points":5},{"critere":"Lien argumenté avec au moins deux repères actuels du document 2","points":5},{"critere":"Lexique du chapitre (Toleranz, Zusammenleben, Gleichberechtigung, benachteiligen)","points":4},{"critere":"Correction grammaticale et connecteurs (verbe en 2e position, subordonnées)","points":6}],"dureeMin":18,"corrige":"**Texte modèle (≈ 115 mots)**\n\n*Die Ringparabel zeigt, dass niemand sagen kann, welche Religion die einzig wahre ist. Deshalb soll jeder durch sein Verhalten zeigen, was sein Glaube wert ist. Das ist eine Lehre der Toleranz. Diese Idee ist heute noch wichtig: Seit 1949 verbietet das Grundgesetz jede Diskriminierung. Außerdem hat Deutschland 1994 den Paragrafen 175 abgeschafft, und seit 2017 gibt es die Ehe für alle. Niemand soll also wegen seiner Religion oder seiner Liebe benachteiligt werden. Aber Toleranz steht nicht nur im Gesetz: In den Vereinen lernen die Menschen, sich für andere zu engagieren. Für mich lehrt uns die Parabel, dass das Zusammenleben vom Verhalten jedes Einzelnen abhängt.*\n\n**Éléments attendus**\n- La parabole : trois anneaux identiques, trois religions, la valeur se prouve par la **conduite**, pas par une preuve d'origine → la tolérance.\n- Au moins deux liens avec le document 2 : l'interdiction des discriminations, l'égalité des droits (1994, 2017), l'engagement associatif.\n- Une conclusion personnelle.\n\n**Langue** : inversion après *Deshalb, Außerdem, Seit 2017* ; verbe à la fin après *dass, welche* ; *wegen* + génitif ; *sich engagieren für*. Accepter toute argumentation juste de 100 à 120 mots."}$exo$::jsonb),
  ('3a3d7cda-bd71-5e16-9be7-5037c20715a9'::uuid, 1, 'traduction', $exo${"titre":"1933 : quand le pouvoir contrôle l'art","consigne":"Lis le texte, puis réponds aux questions en français.","enonce":"**Texte**\n\n> Ab 1933 kontrolliert Joseph Goebbels die Kultur. Wer nicht Mitglied der Reichskulturkammer ist, darf nicht mehr arbeiten. Am 10. Mai 1933 verbrennen Studenten die Bücher von jüdischen, pazifistischen und kommunistischen Autoren. 1937 zeigt die Ausstellung „Entartete Kunst“ in München moderne Kunst, um sie lächerlich zu machen.\n\n*Aide : verbrennen = brûler ; lächerlich machen = ridiculiser.*\n\n1. a) Que se passe-t-il le 10 mai 1933 ? b) Quelle condition faut-il remplir pour avoir le droit de travailler comme artiste ? c) Quel est le but de l'exposition de 1937 ?\n2. Un siècle plus tôt, Heinrich Heine avait écrit : *„Dort, wo man Bücher verbrennt, verbrennt man auch am Ende Menschen.“* Traduis cette phrase.\n3. Donne le mot allemand pour : le pouvoir, la censure, interdire.","bareme":[{"critere":"Trois réponses exactes tirées du texte","points":9},{"critere":"Traduction juste de la phrase de Heine","points":6},{"critere":"Trois mots de vocabulaire justes, avec l'article pour les noms","points":5}],"dureeMin":8,"corrige":"1. a) Le 10 mai 1933, des **étudiants brûlent les livres** d'auteurs juifs, pacifistes et communistes : ce sont les autodafés.\nb) Il faut être **membre de la Chambre de la culture du Reich** (*Reichskulturkammer*) ; sinon, on n'a plus le droit de travailler.\nc) L'exposition « Art dégénéré » montre l'art moderne **pour le ridiculiser** (*um sie lächerlich zu machen*).\n\n2. « Là où l'on brûle des livres, on finit par brûler des hommes. » (« Là où on brûle des livres, on brûle aussi, à la fin, des hommes » accepté.)\n\n3. **die Macht** (le pouvoir) ; **die Zensur** (la censure) ; **verbieten** (interdire)."}$exo$::jsonb),
  ('3a3d7cda-bd71-5e16-9be7-5037c20715a9'::uuid, 2, 'traduction', $exo${"titre":"Partir pour témoigner : les artistes en exil","consigne":"Lis le texte, réponds aux questions 1 et 2 en français, puis à la question 3 en allemand.","enonce":"**Texte**\n\n> Nach 1933 verlassen Hunderte von Künstlern Deutschland. Thomas Mann emigriert in die USA und spricht im Radio der BBC zu den Deutschen. Bertolt Brecht lebt zuerst in Dänemark, dann in den USA. Die Schauspielerin Marlene Dietrich will nicht mehr für die Nazis Filme drehen. Das Exil bedeutet oft Armut und Einsamkeit, aber es erlaubt, Zeugnis abzulegen.\n\n*Aide : die Armut = la pauvreté ; die Einsamkeit = la solitude ; Zeugnis ablegen = témoigner.*\n\n1. Recopie et complète le tableau en français :\n\n| Artiste | Pays d'exil | Ce qu'il ou elle fait contre le régime |\n|---|---|---|\n| Thomas Mann | … | … |\n| Bertolt Brecht | … | — |\n| Marlene Dietrich | — | … |\n\n2. Traduis la dernière phrase du texte.\n3. **En allemand (3 à 4 phrases)** : pourquoi l'exil est-il une forme de résistance ? Emploie *sich widersetzen* + datif.","bareme":[{"critere":"Tableau complété exactement d'après le texte","points":6},{"critere":"Traduction juste de la dernière phrase","points":4},{"critere":"Production : l'exil comme refus et comme témoignage, avec un exemple du texte","points":6},{"critere":"Correction de l'allemand, dont sich widersetzen + datif","points":4}],"dureeMin":12,"corrige":"1. | Artiste | Pays d'exil | Action |\n|---|---|---|\n| Thomas Mann | les États-Unis | il parle aux Allemands à la radio de la BBC |\n| Bertolt Brecht | le Danemark, puis les États-Unis | — |\n| Marlene Dietrich | — | elle refuse de tourner des films pour les nazis |\n\n2. « L'exil signifie souvent la pauvreté et la solitude, mais il permet de témoigner. »\n\n3. Production modèle :\n*Das Exil ist eine Form von Widerstand, weil die Künstler sich der Macht widersetzen. Sie bleiben nicht in Deutschland und arbeiten nicht für die Nazis. Thomas Mann spricht zum Beispiel im Radio zu den Deutschen. So können die Künstler im Ausland die Wahrheit sagen.*\n\nÉléments attendus : refuser de servir le régime ; témoigner de l'étranger (exemple de Thomas Mann ou de Marlene Dietrich). Langue : *sich der Macht / dem Regime widersetzen* (datif), verbe à la fin après *weil*."}$exo$::jsonb),
  ('3a3d7cda-bd71-5e16-9be7-5037c20715a9'::uuid, 3, 'traduction', $exo${"titre":"Servir, fuir ou contester : l'art face à deux dictatures","consigne":"Rédige en allemand un texte argumenté de 100 à 120 mots en t'appuyant sur au moins trois exemples du dossier, dont un de la RDA.","enonce":"**Sujet :** *Kann Kunst die Macht herausfordern?*\n\n**Dossier**\n- **1935** : *Le Triomphe de la volonté*, film de Leni Riefenstahl à la gloire du parti nazi.\n- **1933** : les autodafés ; des centaines d'artistes partent en exil (Thomas Mann, Bertolt Brecht).\n- **Janvier 1933** : Erika Mann ouvre à Munich le cabaret *Die Pfeffermühle*, qui se moque des nazis ; elle doit ensuite poursuivre en Suisse.\n- **1976** : en RDA, le chansonnier Wolf Biermann, auteur de *Ermutigung*, est déchu de sa nationalité pendant un concert à l'Ouest ; de nombreux artistes protestent.\n- **Après 1945** : Heinrich Böll et Günter Grass, prix Nobel, interrogent le passé allemand.\n\n**Mots utiles** : *herausfordern (défier), die Propaganda, die Zensur, das Kabarett, sich lustig machen über + acc. (se moquer de), ausbürgern (déchoir de la nationalité)*.","bareme":[{"critere":"Trois exemples exacts du dossier, dont un de la RDA","points":5},{"critere":"Argumentation structurée : l'art peut servir, fuir ou contester le pouvoir","points":5},{"critere":"Lexique du chapitre et connecteurs","points":4},{"critere":"Correction grammaticale (verbe en 2e position, subordonnées, prétérit ou parfait)","points":6}],"dureeMin":18,"corrige":"**Texte modèle (≈ 115 mots)**\n\n*Kunst kann der Macht dienen, aber sie kann sie auch herausfordern. Einerseits hat Leni Riefenstahl 1935 mit ihrem Film die Partei der Nazis verherrlicht: Das war Propaganda. Andererseits haben viele Künstler Widerstand geleistet. Erika Mann hat sich 1933 in ihrem Kabarett „Die Pfeffermühle“ über die Nazis lustig gemacht, und Thomas Mann ist ins Exil gegangen. Auch in der DDR war Kunst gefährlich für die Macht: Wolf Biermann wurde 1976 ausgebürgert, und viele Künstler haben protestiert. Das zeigt, dass die Diktatur Angst vor Liedern und vor dem Lachen hatte. Deshalb glaube ich, dass Kunst die Macht herausfordern kann, auch wenn der Preis hoch ist.*\n\n**Éléments attendus**\n- Les trois attitudes : **servir** (Riefenstahl), **fuir** (exil), **contester** (cabaret, Biermann ; après 1945, Böll et Grass).\n- Un exemple de la RDA (Biermann, 1976) obligatoire.\n- Une conclusion nuancée (le prix payé : exil, déchéance de nationalité).\n\n**Langue** : *Einerseits / Andererseits / Deshalb* + inversion ; *dass* + verbe à la fin ; passif *wurde ausgebürgert* accepté, ou *Die DDR hat Biermann ausgebürgert*. Toute production juste de 100 à 120 mots obtient les points."}$exo$::jsonb),
  ('df3653fa-11c0-5d35-8dbc-8b016a39d690'::uuid, 1, 'traduction', $exo${"titre":"Inventer ou découvrir ?","consigne":"Lis le texte, puis réponds aux questions en français.","enonce":"**Texte**\n\n> Um 1450 erfindet Johannes Gutenberg in Mainz den Buchdruck mit beweglichen Lettern. 1895 entdeckt Wilhelm Conrad Röntgen die Röntgenstrahlen, und 1901 bekommt er den ersten Nobelpreis für Physik. 1882 entdeckt Robert Koch den Bazillus der Tuberkulose.\n\n*Aide : der Buchdruck mit beweglichen Lettern = l'imprimerie à caractères mobiles ; die Strahlen = les rayons.*\n\n1. Pour chacun des trois savants, indique ce qu'il a fait et en quelle année.\n2. Le texte emploie *erfinden* pour Gutenberg, mais *entdecken* pour Röntgen et Koch. Explique la différence de sens entre ces deux verbes et pourquoi ce choix est logique.\n3. Traduis la deuxième phrase du texte (*1895 entdeckt…*).","bareme":[{"critere":"Les trois savants, leur apport et leur date justes","points":8},{"critere":"Différence erfinden / entdecken expliquée et appliquée aux exemples","points":6},{"critere":"Traduction juste de la deuxième phrase","points":6}],"dureeMin":7,"corrige":"1. - **Gutenberg**, vers **1450**, à Mayence : il invente l'imprimerie à caractères mobiles.\n- **Röntgen**, en **1895** : il découvre les rayons X ; il reçoit en 1901 le premier prix Nobel de physique.\n- **Koch**, en **1882** : il découvre le bacille de la tuberculose.\n\n2. *erfinden* = **inventer** : créer quelque chose qui n'existait pas (une machine, une technique). *entdecken* = **découvrir** : mettre au jour quelque chose qui existait déjà dans la nature. L'imprimerie est une création humaine, donc *erfinden* ; les rayons X et le bacille existaient avant d'être trouvés, donc *entdecken*.\n\n3. « En 1895, Wilhelm Conrad Röntgen découvre les rayons X, et en 1901 il reçoit le premier prix Nobel de physique. » (Le passé composé « a découvert… a reçu » est accepté.)"}$exo$::jsonb),
  ('df3653fa-11c0-5d35-8dbc-8b016a39d690'::uuid, 2, 'traduction', $exo${"titre":"Fritz Haber : nourrir ou tuer","consigne":"Traduis le texte en français (question 1), puis rédige la question 2 en allemand.","enonce":"**Texte**\n\n> Fritz Haber bekommt den Nobelpreis für die Synthese von Ammoniak. Mit Ammoniak kann man Dünger herstellen und Milliarden Menschen ernähren. Aber 1915 leitet Haber auch den ersten Angriff mit Giftgas bei Ypern. Dasselbe Wissen kann also ernähren oder töten.\n\n*Aide : der Dünger = l'engrais ; herstellen = fabriquer ; ernähren = nourrir ; leiten = diriger ; das Giftgas = le gaz de combat ; Ypern = Ypres.*\n\n1. Traduis le texte en français.\n2. **En allemand (3 à 4 phrases)** : *Ist ein Forscher für seine Entdeckung verantwortlich?* Donne ton avis et appuie-toi sur l'exemple de Haber.","bareme":[{"critere":"Traduction juste et complète du texte, sans contresens","points":9},{"critere":"Production : avis clair, argument tiré de l'exemple de Haber","points":7},{"critere":"Correction de l'allemand (verantwortlich für + acc., place du verbe)","points":4}],"dureeMin":12,"corrige":"1. Traduction modèle :\n« Fritz Haber reçoit le prix Nobel pour la synthèse de l'ammoniac. Avec l'ammoniac, on peut fabriquer des engrais et nourrir des milliards d'êtres humains. Mais en 1915, Haber dirige aussi la première attaque au gaz de combat, à Ypres. Le même savoir peut donc nourrir ou tuer. »\n\nPoints vérifiés : *man kann* = on peut ; *Milliarden Menschen* = des milliards d'hommes ; *auch* = aussi ; *also* = donc (et non « aussi »).\n\n2. Production modèle :\n*Ich denke, dass ein Forscher für seine Entdeckung verantwortlich ist. Fritz Haber hat mit dem Ammoniak Milliarden Menschen geholfen. Aber er hat sein Wissen auch für den Krieg benutzt. Deshalb muss jeder Forscher fragen, wozu seine Entdeckung dienen wird.*\n\nÉléments attendus : une position nette (oui, non, ou en partie) ; l'argument du double usage (engrais / gaz de combat) ; l'idée de la responsabilité (*die Verantwortung*). Une position « la découverte est neutre, c'est l'usage qui compte » est acceptée si elle est justifiée par l'exemple. Langue : *verantwortlich für* + accusatif, verbe à la fin après *dass*, inversion après *Deshalb*."}$exo$::jsonb),
  ('df3653fa-11c0-5d35-8dbc-8b016a39d690'::uuid, 3, 'traduction', $exo${"titre":"Le progrès, mais à quel prix ?","consigne":"Rédige en allemand un texte argumenté de 100 à 120 mots, en t'appuyant sur au moins trois exemples du dossier.","enonce":"**Sujet :** *Fortschritt ja, aber um jeden Preis?*\n\n**Dossier**\n- **Fritz Haber** : prix Nobel pour la synthèse de l'ammoniac (engrais) ; en 1915, il dirige la première attaque au gaz de combat à Ypres.\n- **Lise Meitner** : physicienne, elle explique en 1939 la fission nucléaire ; juive, elle avait dû fuir l'Allemagne en 1938 ; le Nobel de chimie est attribué à Otto Hahn seul.\n- **Özlem Türeci et Uğur Şahin** (BioNTech, Mayence) : un vaccin à ARN messager contre le Covid-19 en 2020.\n- **Dieselgate** (2015) : des moteurs diesel truqués ternissent l'image de l'automobile allemande.\n\n**Mots utiles** : *der Fortschritt, die Verantwortung, die Forschung, die Entdeckung, missbrauchen (détourner), um jeden Preis (à tout prix)*.","bareme":[{"critere":"Trois exemples exacts du dossier, utilisés comme arguments","points":5},{"critere":"Argumentation nuancée (bienfaits et dérives) et conclusion","points":5},{"critere":"Lexique du chapitre employé correctement","points":4},{"critere":"Correction grammaticale et connecteurs","points":6}],"dureeMin":18,"corrige":"**Texte modèle (≈ 115 mots)**\n\n*Der Fortschritt hat das Leben der Menschen verbessert. Zum Beispiel haben Özlem Türeci und Uğur Şahin 2020 einen Impfstoff gegen Covid-19 entwickelt. Auch Fritz Haber hat mit dem Ammoniak Dünger möglich gemacht. Aber derselbe Haber hat 1915 den ersten Gasangriff geleitet: Man kann eine Entdeckung also missbrauchen. Außerdem ist der Fortschritt nicht immer gerecht. Lise Meitner hat die Kernspaltung erklärt, aber den Nobelpreis hat nur Otto Hahn bekommen. Und beim Dieselgate haben Firmen gelogen, um mehr Autos zu verkaufen. Deshalb meine ich: Fortschritt ja, aber nicht um jeden Preis. Forscher, Firmen und Bürger tragen zusammen die Verantwortung.*\n\n*Aide acceptée : der Impfstoff = le vaccin ; die Kernspaltung = la fission nucléaire.*\n\n**Éléments attendus**\n- Un bienfait (vaccin, engrais) et au moins deux dérives ou limites (gaz de combat, injustice envers Meitner, tricherie du Dieselgate).\n- La distinction entre la découverte et son usage.\n- Une conclusion qui répond à la question.\n\n**Langue** : inversion après *Zum Beispiel, Außerdem, Deshalb* ; *um … zu* + infinitif ; parfait correct (*haben entwickelt, hat bekommen*)."}$exo$::jsonb),
  ('021ade94-a51a-5a19-837e-ce13c1cb72fb'::uuid, 1, 'traduction', $exo${"titre":"Du tableau romantique au Wandervogel","consigne":"Lis le texte, puis réponds aux questions en français.","enonce":"**Texte**\n\n> Um 1818 malt Caspar David Friedrich den „Wanderer über dem Nebelmeer“: Ein Mann steht mit dem Rücken zu uns vor einer riesigen Landschaft. Für die Romantiker ist die Natur ein Ort des Gefühls und des Geheimnisses. Um 1900 wachsen die Städte. Junge Leute gründen 1901 den „Wandervogel“: Sie wandern, singen und schlafen draußen.\n\n*Aide : das Nebelmeer = la mer de nuages ; der Rücken = le dos ; das Geheimnis = le mystère.*\n\n1. Décris en français ce que montre le tableau de Friedrich, d'après le texte.\n2. Que représente la nature pour les romantiques ?\n3. Pourquoi, d'après le texte, les jeunes fondent-ils le *Wandervogel* ? Que font-ils ?\n4. Donne le mot allemand pour : le paysage, randonner.","bareme":[{"critere":"Description du tableau fidèle au texte","points":5},{"critere":"Ce que la nature représente pour les romantiques (sentiment, mystère)","points":5},{"critere":"Wandervogel : lien avec la croissance des villes et activités citées","points":6},{"critere":"Deux mots de vocabulaire justes","points":4}],"dureeMin":8,"corrige":"1. Le tableau montre un **homme vu de dos**, debout face à un **immense paysage** (une mer de nuages).\n\n2. Pour les romantiques, la nature est le lieu du **sentiment** et du **mystère** (*ein Ort des Gefühls und des Geheimnisses*).\n\n3. Le texte relie la fondation du *Wandervogel* (1901) à la **croissance des villes** vers 1900 : les jeunes veulent sortir de la ville. Ils **randonnent, chantent et dorment dehors** (*wandern, singen, schlafen draußen*).\n\n4. **die Landschaft** (le paysage) ; **wandern** (randonner)."}$exo$::jsonb),
  ('021ade94-a51a-5a19-837e-ce13c1cb72fb'::uuid, 2, 'traduction', $exo${"titre":"Le jardin de la famille de Jonas","consigne":"Lis le texte, réponds aux questions 1 et 2 en français, puis à la question 3 en allemand.","enonce":"**Texte (inventé pour le sujet)**\n\n> Jonas wohnt mit seinen Eltern in einer kleinen Wohnung in Leipzig. Am Wochenende fährt die Familie in ihren Schrebergarten am Stadtrand. Dort pflanzen sie Tomaten, und Jonas liest unter einem Apfelbaum. „Der Garten gehört uns nicht, wir mieten ihn“, erklärt sein Vater. „Aber hier sind wir in der Natur, mitten in der Stadt.“ Seine Oma aus Dresden erzählt oft von ihrer Datsche aus der DDR-Zeit.\n\n*Aide : mieten = louer ; der Stadtrand = la périphérie.*\n\n1. Qu'est-ce qu'un *Schrebergarten* ? Réponds à l'aide du texte et donne l'origine de son nom (Moritz Schreber, médecin ; premier jardin à Leipzig en 1864).\n2. Traduis la phrase du père : *„Aber hier sind wir in der Natur, mitten in der Stadt.“*\n3. **En allemand (3 à 4 phrases)** : explique pourquoi les jardins et les *Datschen* sont importants pour beaucoup d'Allemands qui vivent en ville.","bareme":[{"critere":"Définition du Schrebergarten (jardin loué, en ville) et origine du nom","points":5},{"critere":"Traduction juste de la phrase du père (mitten in)","points":4},{"critere":"Production : besoin de nature en ville, avec des éléments du texte","points":7},{"critere":"Correction de l'allemand (verbe en 2e position, verbe à la fin des subordonnées)","points":4}],"dureeMin":11,"corrige":"1. Un *Schrebergarten* est un **jardin ouvrier en location**, à la périphérie de la ville : la famille de Jonas ne le possède pas, elle le loue (*wir mieten ihn*). On y cultive des légumes (des tomates) et on s'y repose. Il doit son nom au médecin **Moritz Schreber** ; le premier a été créé à **Leipzig en 1864**.\n\n2. « Mais ici, nous sommes dans la nature, en pleine ville. » (« au milieu de la ville » accepté.)\n\n3. Production modèle :\n*Viele Deutsche wohnen in kleinen Wohnungen ohne Garten. Deshalb brauchen sie einen Ort in der Natur. Im Schrebergarten können sie Gemüse pflanzen und sich ausruhen. In der DDR war die Datsche ein kleines Haus auf dem Land, wo die Familien das Wochenende verbrachten.*\n\nÉléments attendus : la ville et les petits logements, le besoin de nature et de repos, le jardin comme lieu de culture (tomates) ; la *Datsche*, petite maison de campagne très répandue en RDA. Langue : inversion après *Deshalb* ; verbe à la fin après *wo*."}$exo$::jsonb),
  ('021ade94-a51a-5a19-837e-ce13c1cb72fb'::uuid, 3, 'traduction', $exo${"titre":"Du tableau au bulletin de vote","consigne":"Rédige en allemand un texte de 100 à 120 mots qui montre comment la nature est devenue, en Allemagne, un enjeu politique. Utilise au moins quatre repères de la frise, dans l'ordre chronologique.","enonce":"**Sujet :** *Wie ist die Natur in Deutschland ein politisches Thema geworden?*\n\n**Frise**\n- **1713** : le forestier Hans Carl von Carlowitz invente l'idée de *Nachhaltigkeit* : ne pas couper plus de bois qu'il n'en repousse.\n- **Vers 1818** : Caspar David Friedrich peint *Le Voyageur contemplant une mer de nuages*.\n- **1901** : fondation du *Wandervogel*.\n- **1970** : premier parc national allemand, la forêt bavaroise.\n- **Années 1980** : peur du *Waldsterben* (mort des forêts, due aux pluies acides) et mouvement antinucléaire.\n- **1980** : fondation du parti *die Grünen* ; il entre au Bundestag en 1983.\n\n**Mots utiles** : *der Umweltschutz, nachhaltig, die Partei, gründen, der saure Regen (les pluies acides), der Bundestag*.","bareme":[{"critere":"Au moins quatre repères exacts, présentés dans l'ordre chronologique","points":5},{"critere":"Idée directrice : du sentiment romantique à l'action politique","points":5},{"critere":"Lexique du chapitre et marqueurs de temps (zuerst, später, dann, heute)","points":4},{"critere":"Correction grammaticale (temps du passé, inversion, subordonnées)","points":6}],"dureeMin":18,"corrige":"**Texte modèle (≈ 115 mots)**\n\n*Schon 1713 hat der Förster Hans Carl von Carlowitz die Idee der Nachhaltigkeit erfunden: Man soll nicht mehr Holz schlagen, als nachwächst. Um 1818 hat Caspar David Friedrich die Natur als Ort des Gefühls gemalt. Später, 1901, haben junge Leute den Wandervogel gegründet, weil sie die Städte verlassen wollten. 1970 ist der erste Nationalpark entstanden, der Bayerische Wald. In den achtziger Jahren hatten viele Deutsche Angst vor dem Waldsterben, das der saure Regen verursachte. Deshalb wurde 1980 die Partei der Grünen gegründet, die 1983 in den Bundestag kam. So ist die Natur vom Bild zum Wahlzettel gekommen: Heute ist der Umweltschutz ein politisches Thema.*\n\n*(Aide acceptée : nachwachsen = repousser ; der Wahlzettel = le bulletin de vote.)*\n\n**Éléments attendus**\n- Quatre repères au moins, justes et dans l'ordre.\n- Le fil : l'idée ancienne de durabilité, le sentiment romantique, la fuite hors des villes, puis la protection (parc national) et enfin la politique (les Verts).\n- Une conclusion.\n\n**Langue** : inversion après les dates et *Deshalb* ; verbe à la fin après *weil*, et dans les relatives *das …verursachte, die … kam* ; passif *wurde … gegründet* accepté. Toute production juste de 100 à 120 mots obtient les points."}$exo$::jsonb),
  ('61d7abb4-9780-51e0-9e71-37925864d94e'::uuid, 1, 'traduction', $exo${"titre":"Germantown : quand les Allemands émigraient","consigne":"Lis le texte, puis réponds aux questions en français.","enonce":"**Texte**\n\n> 1683 gründen Deutsche in Pennsylvanien die Stadt Germantown. Im 19. Jahrhundert wandern mehr als fünf Millionen Deutsche in die USA aus. Heute ist die deutsche Herkunft eine der häufigsten in den USA. In Brasilien, in Chile oder in Namibia sprechen manche Gemeinschaften noch Deutsch.\n\n*Aide : die Herkunft = l'origine ; häufig = fréquent ; die Gemeinschaft = la communauté.*\n\n1. Relève : a) la date de fondation de Germantown et la région où elle se trouve ; b) le nombre d'Allemands partis aux États-Unis au XIXe siècle ; c) trois pays où l'on parle encore allemand dans certaines communautés.\n2. Traduis la troisième phrase (*Heute ist…*).\n3. Donne le mot allemand pour « l'émigration » et le verbe « émigrer ».","bareme":[{"critere":"Informations relevées exactement (1683, Pennsylvanie, plus de cinq millions, trois pays)","points":9},{"critere":"Traduction juste de la troisième phrase","points":6},{"critere":"Die Auswanderung et auswandern justes","points":5}],"dureeMin":7,"corrige":"1. a) Germantown est fondée en **1683**, en **Pennsylvanie**.\nb) **Plus de cinq millions** d'Allemands émigrent aux États-Unis au XIXe siècle.\nc) **Le Brésil, le Chili, la Namibie.**\n\n2. « Aujourd'hui, l'origine allemande est l'une des plus fréquentes aux États-Unis. »\n\n3. **die Auswanderung** (l'émigration) ; **auswandern** (émigrer), verbe à préverbe séparable : *sie wandern aus*."}$exo$::jsonb),
  ('61d7abb4-9780-51e0-9e71-37925864d94e'::uuid, 2, 'traduction', $exo${"titre":"« Une place au soleil » : le passé colonial allemand","consigne":"Lis le texte, réponds aux questions 1 et 2 en français, puis à la question 3 en allemand.","enonce":"**Texte**\n\n> 1884 und 1885 teilen die europäischen Mächte auf der Berliner Konferenz Afrika unter sich auf. 1897 fordert der Minister von Bülow für Deutschland „einen Platz an der Sonne“. In Deutsch-Südwestafrika, dem heutigen Namibia, töten deutsche Soldaten zwischen 1904 und 1908 Zehntausende Herero und Nama. 1919 verliert Deutschland alle Kolonien. Erst 2021 erkennt Deutschland dieses Massaker als Völkermord an.\n\n*Aide : aufteilen = partager ; fordern = réclamer ; der Völkermord = le génocide ; anerkennen = reconnaître.*\n\n1. Classe dans l'ordre chronologique, avec leur date, les événements évoqués.\n2. Que veut dire l'expression de von Bülow, *„einen Platz an der Sonne“* ? Explique son sens.\n3. **En allemand (3 phrases)** : aujourd'hui, en Allemagne, on rebaptise des rues et on rend des objets pris en Afrique. Explique pourquoi.","bareme":[{"critere":"Les cinq événements, datés et dans l'ordre","points":6},{"critere":"Traduction et sens de l'expression (réclamer des colonies, une place parmi les puissances)","points":4},{"critere":"Production : mémoire, réparation, reconnaissance d'une histoire longtemps oubliée","points":6},{"critere":"Correction de l'allemand","points":4}],"dureeMin":12,"corrige":"1. - **1884-1885** : conférence de Berlin, les puissances européennes se partagent l'Afrique.\n- **1897** : von Bülow réclame « une place au soleil » pour l'Allemagne.\n- **1904-1908** : massacre des Herero et des Nama en Namibie (*Deutsch-Südwestafrika*).\n- **1919** : l'Allemagne perd toutes ses colonies.\n- **2021** : l'Allemagne reconnaît ce massacre comme un génocide.\n\n2. « Une place au soleil » : l'Allemagne veut, comme les autres puissances européennes, avoir **des colonies** et une place parmi les grandes puissances mondiales. C'est une revendication de puissance coloniale.\n\n3. Production modèle :\n*Die Kolonialgeschichte war lange vergessen. Heute will Deutschland an die Opfer erinnern, deshalb bekommen manche Straßen neue Namen. Außerdem gibt Deutschland Objekte zurück, weil sie in Afrika genommen wurden.*\n\nÉléments attendus : l'oubli, puis la mémoire des victimes ; la réparation (*die Wiedergutmachung*) ; la reconnaissance du génocide en 2021. Langue : inversion après *deshalb* et *Außerdem* ; *weil* + verbe à la fin ; *zurückgeben* séparable (*gibt … zurück*)."}$exo$::jsonb),
  ('61d7abb4-9780-51e0-9e71-37925864d94e'::uuid, 3, 'traduction', $exo${"titre":"Géant économique, puissance discrète","consigne":"Rédige en allemand un texte argumenté de 100 à 120 mots. Appuie-toi sur au moins trois repères du dossier et emploie correctement *der Einfluss auf* + accusatif.","enonce":"**Sujet :** *„Wirtschaftlich ein Riese, politisch lange diskret.“ Welchen Einfluss hat Deutschland heute auf die Welt?*\n\n**Dossier**\n- **Goethe-Institut** (1951) : fait connaître la langue et la culture allemandes, plus de 150 instituts dans le monde.\n- **Deutsche Welle** : radio et télévision internationales en une trentaine de langues.\n- **« Made in Germany »** : voitures et machines, une qualité reconnue.\n- **Après 1945** : ancrage à l'Ouest (OTAN, Europe) ; puis, avec Willy Brandt, détente avec l'Est (*Ostpolitik*).\n- **Années 1990** : premières interventions de la *Bundeswehr* à l'étranger.\n- **Février 2022** : après l'invasion de l'Ukraine, Olaf Scholz parle de *Zeitenwende* ; l'Allemagne réarme.\n\n**Mots utiles** : *der Riese (le géant), die Außenpolitik, der Export, die Kultur, die Verantwortung, übernehmen (assumer)*.","bareme":[{"critere":"Trois repères exacts, dont au moins un économique ou culturel et un politique","points":5},{"critere":"Réponse argumentée à la citation : poids économique et culturel, prudence puis changement","points":5},{"critere":"Lexique du chapitre, dont der Einfluss auf + accusatif","points":4},{"critere":"Correction grammaticale et connecteurs","points":6}],"dureeMin":18,"corrige":"**Texte modèle (≈ 115 mots)**\n\n*Deutschland hat einen großen Einfluss auf die Welt, aber vor allem durch die Wirtschaft und die Kultur. Die Produkte „Made in Germany“, zum Beispiel Autos und Maschinen, werden überall gekauft. Außerdem macht das Goethe-Institut die deutsche Sprache in mehr als 150 Instituten bekannt, und die Deutsche Welle sendet in etwa dreißig Sprachen. Politisch war Deutschland nach 1945 lange vorsichtig: Es hat sich an den Westen gebunden, und Willy Brandt hat die Entspannung mit dem Osten gesucht. Erst seit den neunziger Jahren ist die Bundeswehr im Ausland. Seit 2022 und der „Zeitenwende“ rüstet Deutschland wieder auf. Das Land will also mehr Verantwortung übernehmen.*\n\n*(Aide acceptée : senden = émettre ; die Entspannung = la détente ; aufrüsten = réarmer.)*\n\n**Éléments attendus**\n- Le soft power (Goethe-Institut, Deutsche Welle, *Made in Germany*).\n- La prudence politique après 1945 (Ouest, *Ostpolitik*), puis l'évolution (années 1990, *Zeitenwende*).\n- Une conclusion qui répond à la question.\n\n**Langue** : *Einfluss auf die Welt* (accusatif) ; inversion après *Außerdem, Politisch, Erst seit…, Seit 2022* ; passif *werden gekauft* accepté ; verbes séparables (*macht … bekannt, rüstet … auf*)."}$exo$::jsonb),
  ('01dddb98-7603-54fe-b7ea-f3f66e908200'::uuid, 1, 'traduction', $exo${"titre":"Former le plus-que-parfait","consigne":"Réponds à chaque exercice. Écris les formes verbales complètes.","enonce":"**1. Mets au plus-que-parfait** (même auxiliaire qu'au parfait).\n\na) ich esse\nb) er geht\nc) wir warten\nd) du kommst an\ne) sie machen die Hausaufgaben\n\n**2. Complète avec *hatte* ou *war*.**\n\na) Als ich ankam, ___ der Zug schon abgefahren.\nb) Nachdem sie gegessen ___, ging sie schlafen.\n\n**3.** Traduis la phrase 2 a) en français.","bareme":[{"critere":"Cinq formes au plus-que-parfait justes (auxiliaire au prétérit, participe II)","points":10},{"critere":"Choix juste de hatte / war dans les deux phrases","points":5},{"critere":"Traduction juste exprimant l'antériorité","points":5}],"dureeMin":7,"corrige":"**1.**\na) ich **hatte gegessen**\nb) er **war gegangen**\nc) wir **hatten gewartet**\nd) du **warst angekommen**\ne) sie **hatten** die Hausaufgaben **gemacht**\n\nRègle : prétérit de *haben* ou *sein* + participe II, avec le même auxiliaire qu'au parfait (*er ist gegangen* → *er war gegangen* ; *du bist angekommen* → *du warst angekommen*). Participe placé à la fin.\n\n**2.**\na) Als ich ankam, **war** der Zug schon abgefahren. (*abfahren*, verbe de déplacement → *sein*)\nb) Nachdem sie gegessen **hatte**, ging sie schlafen. (*essen* → *haben* ; subordonnée en *nachdem* au plus-que-parfait, principale au prétérit)\n\n**3.** « Quand je suis arrivé, le train était déjà parti. » Le plus-que-parfait marque que le départ du train a eu lieu **avant** l'arrivée."}$exo$::jsonb),
  ('01dddb98-7603-54fe-b7ea-f3f66e908200'::uuid, 2, 'traduction', $exo${"titre":"Nachdem, bevor : mettre les actions en ordre","consigne":"Relie chaque paire de phrases comme indiqué, en respectant la concordance des temps. Justifie ensuite en une phrase la règle appliquée à la question 1.","enonce":"**1. Relie les deux phrases avec *nachdem*** (la première action a lieu d'abord ; commence par *Nachdem*).\n\na) Er macht die Hausaufgaben. Dann geht er ins Kino.\nb) Wir besuchten das Museum. Dann gingen wir ins Café.\nc) Sie kam nach Hause. Dann rief sie ihre Mutter an.\nd) Ich lese das Buch. Dann schreibe ich eine Zusammenfassung.\n\n**2. Relie avec *bevor*** (commence par *Bevor*) :\n\nIch gehe. Vorher rufe ich dich an.\n\n**3.** Explique en une phrase quelle règle de temps tu as suivie avec *nachdem*, et pourquoi elle ne s'applique pas avec *bevor*.","bareme":[{"critere":"Décalage des temps juste dans les quatre phrases avec nachdem","points":8},{"critere":"Ordre des mots : verbe à la fin de la subordonnée, inversion dans la principale","points":5},{"critere":"Phrase avec bevor juste, sans décalage de temps","points":3},{"critere":"Règle expliquée clairement","points":4}],"dureeMin":10,"corrige":"**1.**\na) *Nachdem er die Hausaufgaben **gemacht hat**, **geht** er ins Kino.* (principale au présent → subordonnée au parfait)\nb) *Nachdem wir das Museum **besucht hatten**, **gingen** wir ins Café.* (principale au prétérit → subordonnée au plus-que-parfait)\nc) *Nachdem sie nach Hause **gekommen war**, **rief** sie ihre Mutter **an**.* (*kommen* → *sein*)\nd) *Nachdem ich das Buch **gelesen habe**, **schreibe** ich eine Zusammenfassung.*\n\nOrdre des mots : dans la subordonnée, le verbe conjugué est à la fin (*gemacht hat*) ; la subordonnée occupe la 1re place, donc le verbe de la principale vient juste après la virgule (*geht er*).\n\n**2.** *Bevor ich **gehe**, **rufe** ich dich **an**.* Même temps (présent) des deux côtés ; jamais *vor … zu*.\n\n**3.** Avec *nachdem*, la subordonnée est **un cran plus loin dans le passé** que la principale (parfait si la principale est au présent, plus-que-parfait si elle est au prétérit), car l'action qu'elle exprime est terminée avant l'autre. Avec *bevor*, l'action de la subordonnée vient **après** : il n'y a pas d'antériorité à marquer, on garde le même temps."}$exo$::jsonb),
  ('01dddb98-7603-54fe-b7ea-f3f66e908200'::uuid, 3, 'traduction', $exo${"titre":"La mauvaise journée de Paul : un récit à traduire","consigne":"Traduis le récit en allemand (thème), en employant le prétérit pour le récit. Puis justifie deux de tes choix.","enonce":"**1. Traduis en allemand.**\n\n> Quand Paul est arrivé à la gare, le train était déjà parti. Il s'était réveillé trop tard. Après avoir attendu une heure, il a pris le train suivant. Avant de monter, il a appelé sa sœur. Après le voyage, il était très fatigué.\n\n*Aide : der Bahnhof = la gare ; aufwachen (ist aufgewacht) = se réveiller ; einsteigen (ist eingestiegen) = monter (dans un train) ; nächst- = suivant ; die Reise = le voyage.*\n\n**2. Justifie :**\na) comment tu as traduit « après avoir attendu » et pourquoi l'allemand ne peut pas garder l'infinitif ;\nb) pourquoi « après le voyage » ne se traduit pas avec *nachdem*.","bareme":[{"critere":"Plus-que-parfait juste (war abgefahren, war aufgewacht, gewartet hatte)","points":6},{"critere":"Subordonnées en als, nachdem, bevor bien construites (verbe à la fin, inversion)","points":5},{"critere":"Nach + datif et prétérit du récit justes","points":3},{"critere":"Justifications exactes des deux choix","points":6}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n*Als Paul am Bahnhof ankam, war der Zug schon abgefahren. Er war zu spät aufgewacht. Nachdem er eine Stunde gewartet hatte, nahm er den nächsten Zug. Bevor er einstieg, rief er seine Schwester an. Nach der Reise war er sehr müde.*\n\nPoints vérifiés :\n- *war abgefahren*, *war aufgewacht* : plus-que-parfait avec *sein* (déplacement, changement d'état), actions antérieures au récit.\n- *Nachdem er … gewartet hatte, nahm er* : plus-que-parfait dans la subordonnée, prétérit dans la principale, inversion *nahm er*.\n- *Bevor er einstieg, rief er … an* : même temps des deux côtés ; *einstieg* réuni en fin de subordonnée.\n- *Nach der Reise* : préposition + datif (*die Reise* → *der Reise*), puis inversion *war er*.\n- « Il a pris », « il a appelé » : dans un récit écrit, le prétérit (*nahm, rief an*) ; le parfait est toléré s'il est correct.\n\n**2. Justifications**\na) « Après avoir attendu » → *Nachdem er eine Stunde gewartet hatte*. L'allemand n'a pas de construction « *nach* + infinitif passé » : *nachdem* exige une **subordonnée conjuguée**, avec un sujet, et le décalage des temps impose le plus-que-parfait puisque la principale est au prétérit.\nb) « Après le voyage » est un **groupe nominal** sans verbe : on emploie la **préposition** *nach* + datif. *nachdem* est un subordonnant, il introduit une proposition avec un verbe conjugué ; *nachher* est un adverbe (« après, ensuite ») sans complément."}$exo$::jsonb),
  ('942a29d1-ac6a-58ba-87c7-998d96d44a00'::uuid, 1, 'traduction', $exo${"titre":"Le cas que le verbe impose","consigne":"Complète chaque phrase avec la forme correcte du mot entre parenthèses, puis indique le cas employé.","enonce":"**Complète et indique le cas (datif ou accusatif).**\n\n1. Ich helfe ___ . (mein Bruder)\n2. Der Film gefällt ___ . (ich)\n3. Ich frage ___ . (der Lehrer)\n4. Das Buch gehört ___ . (meine Schwester)\n5. Wir danken ___ für die Einladung. (Sie, forme de politesse)\n6. Ruf ___ morgen an! (ich)","bareme":[{"critere":"Six formes justes (déclinaison du déterminant ou du pronom)","points":12},{"critere":"Cas correctement identifié pour chaque phrase","points":6},{"critere":"Orthographe (Ihnen avec majuscule)","points":2}],"dureeMin":7,"corrige":"1. Ich helfe **meinem Bruder**. — **datif** (*helfen* + datif, même si le français dit « aider quelqu'un »).\n2. Der Film gefällt **mir**. — **datif** (*gefallen* : la personne à qui ça plaît est au datif).\n3. Ich frage **den Lehrer**. — **accusatif** (*jn fragen*, même si le français dit « demander à »).\n4. Das Buch gehört **meiner Schwester**. — **datif** (*gehören*).\n5. Wir danken **Ihnen** für die Einladung. — **datif** (*danken* ; *Ihnen* avec majuscule, forme de politesse).\n6. Ruf **mich** morgen an! — **accusatif** (*jn anrufen*, « téléphoner à quelqu'un »)."}$exo$::jsonb),
  ('942a29d1-ac6a-58ba-87c7-998d96d44a00'::uuid, 2, 'traduction', $exo${"titre":"Aider, remercier, demander : six phrases à traduire","consigne":"Traduis les phrases en allemand (thème), puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\na) J'aide mon amie.\nb) Il contredit son père.\nc) Je demande de l'aide au professeur.\nd) Nous félicitons le vainqueur.\ne) J'explique la règle à l'élève.\nf) Je me lave les mains.\n\n*Aide : der Sieger = le vainqueur ; die Regel = la règle ; die Hilfe = l'aide.*\n\n**2.** Récris la phrase e) en remplaçant *la règle* et *l'élève* par deux pronoms, et explique l'ordre des pronoms.","bareme":[{"critere":"Cas justes après helfen, widersprechen, gratulieren (datif) et bitten (accusatif + um)","points":8},{"critere":"Verbe à deux compléments : personne au datif, chose à l'accusatif","points":4},{"critere":"Réfléchi au datif avec un COD (mir die Hände)","points":3},{"critere":"Phrase avec deux pronoms juste et ordre expliqué","points":5}],"dureeMin":10,"corrige":"**1.**\na) *Ich helfe **meiner Freundin**.* (*helfen* + datif)\nb) *Er widerspricht **seinem Vater**.* (*widersprechen* + datif)\nc) *Ich bitte **den Lehrer um Hilfe**.* (*jn um etwas bitten* : accusatif de la personne + *um*)\nd) *Wir gratulieren **dem Sieger**.* (*gratulieren* + datif)\ne) *Ich erkläre **dem Schüler die Regel**.* (personne au datif, chose à l'accusatif)\nf) *Ich wasche **mir** die Hände.* (le verbe a déjà un COD, *die Hände* : le réfléchi passe au datif)\n\n**2.** *Ich erkläre **sie ihm**.* Quand les deux compléments sont des pronoms, l'**accusatif** (*sie* = die Regel) se place **avant** le datif (*ihm* = dem Schüler). Avec deux noms, c'est l'inverse (datif puis accusatif)."}$exo$::jsonb),
  ('942a29d1-ac6a-58ba-87c7-998d96d44a00'::uuid, 3, 'traduction', $exo${"titre":"La copie de Tim : cinq fautes de cas","consigne":"Relève et corrige les fautes de cas du texte en justifiant chaque correction, puis traduis les deux phrases de la question 2.","enonce":"**1. Ce texte contient cinq fautes de cas.** Relève-les, corrige-les et justifie chaque correction.\n\n> Gestern habe ich meinen Opa geholfen. Er hat mir eine alte Uhr gezeigt, die meinem Urgroßvater gehört hat. Dann habe ich ihm gefragt, woher sie kommt. Er hat mich die Geschichte der Uhr erklärt. Ich habe mich die Hände gewaschen und ihm für den Nachmittag gedankt. Am Abend habe ich meiner Tante angerufen.\n\n*Aide : der Urgroßvater = l'arrière-grand-père.*\n\n**2. Traduis en allemand.**\na) Je fais confiance à mon professeur et je le remercie pour son aide.\nb) Elle est consciente du danger.","bareme":[{"critere":"Cinq fautes repérées sans signaler de fausse faute","points":5},{"critere":"Cinq corrections justes","points":5},{"critere":"Justifications exactes (rection du verbe, réfléchi au datif)","points":5},{"critere":"Deux traductions justes (vertrauen + datif, danken + datif, génitif après bewusst sein)","points":5}],"dureeMin":15,"corrige":"**1. Les cinq fautes**\n1. *meinen Opa geholfen* → **meinem Opa geholfen** : *helfen* se construit avec le **datif**.\n2. *ihm gefragt* → **ihn gefragt** : *jn fragen* prend l'**accusatif** de la personne.\n3. *Er hat mich die Geschichte erklärt* → **Er hat mir die Geschichte erklärt** : *jm etwas erklären*, personne au **datif**, chose à l'accusatif.\n4. *Ich habe mich die Hände gewaschen* → **Ich habe mir die Hände gewaschen** : le verbe a déjà un COD (*die Hände*), le réfléchi passe au **datif**.\n5. *meiner Tante angerufen* → **meine Tante angerufen** : *jn anrufen* prend l'**accusatif**.\n\nPhrases correctes à ne pas corriger : *Er hat mir eine alte Uhr gezeigt* (datif de la personne), *die meinem Urgroßvater gehört hat* (*gehören* + datif), *ihm … gedankt* (*danken* + datif). Signaler l'une d'elles comme fautive fait perdre des points au premier critère.\n\n**2.**\na) *Ich vertraue **meinem Lehrer** und danke **ihm** für seine Hilfe.* (*vertrauen* et *danken* + datif)\nb) *Sie ist sich **der Gefahr** bewusst.* (*sich einer Sache bewusst sein* : génitif ; *die Gefahr* → *der Gefahr*)"}$exo$::jsonb),
  ('fa17180e-43d2-5982-b445-9009ece3f398'::uuid, 1, 'traduction', $exo${"titre":"Un radical, plusieurs sens","consigne":"Réponds à chaque exercice en français, sauf pour les participes.","enonce":"**1. Donne le sens de chaque verbe**, et indique si le préverbe est séparable ou inséparable.\n\na) auswandern  b) einwandern  c) umziehen  d) zurückkommen  e) zerstören  f) missverstehen\n\n**2. Donne le participe II** de : *verändern, erreichen, aufstehen*.\n\n**3.** À partir de l'adjectif *neu* (nouveau), explique le sens de *erneuern*.","bareme":[{"critere":"Six sens justes","points":9},{"critere":"Séparable / inséparable juste pour les six verbes","points":3},{"critere":"Trois participes II justes (pas de ge- avec un préverbe inséparable)","points":5},{"critere":"Sens de erneuern expliqué par er- + adjectif","points":3}],"dureeMin":7,"corrige":"**1.**\na) *auswandern* = **émigrer** (aus- : vers l'extérieur) — séparable.\nb) *einwandern* = **immigrer** (ein- : vers l'intérieur) — séparable.\nc) *umziehen* = **déménager** (um- : changement) — séparable.\nd) *zurückkommen* = **revenir** (zurück- : retour) — séparable.\ne) *zerstören* = **détruire** (zer- : destruction en morceaux) — inséparable.\nf) *missverstehen* = **mal comprendre** (miss- : de travers) — inséparable.\n\n**2.** *verändern* → **verändert** ; *erreichen* → **erreicht** ; *aufstehen* → **aufgestanden** (séparable : *ge-* entre le préverbe et le radical). Un préverbe inséparable ne prend jamais *ge-*.\n\n**3.** *er-* sert souvent à « rendre » ce que dit un adjectif : *erneuern* = rendre neuf, donc **renouveler** (comme *erleichtern*, de *leicht*, faciliter)."}$exo$::jsonb),
  ('fa17180e-43d2-5982-b445-9009ece3f398'::uuid, 2, 'traduction', $exo${"titre":"Partir en Amérique : traduire les préverbes","consigne":"Traduis le texte en français, puis applique la méthode du cours à deux verbes.","enonce":"**1. Traduis en français.**\n\n> Im 19. Jahrhundert wanderten viele Deutsche nach Amerika aus. In New York stiegen sie aus dem Schiff aus. Manche kamen nie zurück. Sie mussten umdenken und ihr Leben verändern. Oft erleichterte die Familie den Neuanfang.\n\n*Aide : das Schiff = le navire ; der Neuanfang = le nouveau départ.*\n\n**2.** Pour *umdenken* et *erleichtern*, applique les quatre étapes de la méthode : isole le préverbe, donne le sens du radical, ajoute l'idée du préverbe, vérifie dans le contexte.","bareme":[{"critere":"Traduction juste des cinq verbes à préverbe","points":7},{"critere":"Traduction juste et fluide du reste du texte","points":5},{"critere":"Méthode appliquée complètement à umdenken","points":4},{"critere":"Méthode appliquée complètement à erleichtern","points":4}],"dureeMin":11,"corrige":"**1. Traduction modèle**\n« Au XIXe siècle, beaucoup d'Allemands émigrèrent en Amérique (ont émigré). À New York, ils descendirent du navire. Certains ne revinrent jamais. Ils durent changer leur façon de penser et transformer leur vie. Souvent, la famille facilitait le nouveau départ. »\n\nPoints vérifiés : *wanderten … aus* = émigrèrent (préverbe séparé, rejeté en fin de phrase) ; *stiegen … aus* = descendirent ; *kamen … zurück* = revinrent ; *umdenken* = changer sa façon de penser ; *verändern* = transformer, changer ; *erleichterte* = facilitait.\n\n**2. Méthode**\n- *umdenken* : 1. *um / denken* ; 2. *denken* = penser ; 3. *um-* = changement ; 4. → **changer sa façon de penser** : dans le texte, les émigrés doivent s'adapter à une vie nouvelle.\n- *erleichtern* : 1. *er / leicht (+ -ern)* ; 2. *leicht* = facile, léger ; 3. *er-* = rendre ; 4. → rendre facile, **faciliter** : la famille rend le nouveau départ plus facile."}$exo$::jsonb),
  ('fa17180e-43d2-5982-b445-9009ece3f398'::uuid, 3, 'traduction', $exo${"titre":"Deviner six verbes, puis raconter","consigne":"Déduis le sens des verbes en justifiant par le préverbe, puis rédige un court récit en allemand au parfait.","enonce":"**1. Déduis le sens** de chaque verbe souligné, en expliquant le rôle du préverbe.\n\na) Im Wald hat sich Mia **verlaufen**.\nb) Das Glas ist **zerbrochen**.\nc) Der Dieb ist der Polizei **entkommen**.\nd) Bitte **beantworte** meine Frage!\ne) Heute Morgen habe ich **verschlafen**.\nf) Wir **verbrauchen** zu viel Wasser.\n\n*Aide : das Glas = le verre ; der Dieb = le voleur.*\n\n**2. Récit (6 à 8 phrases, au parfait)** : raconte une journée qui a mal commencé. Emploie au moins **quatre** verbes à préverbe, dont au moins **deux séparables** et **deux inséparables**, et souligne-les.","bareme":[{"critere":"Six sens justes","points":6},{"critere":"Rôle du préverbe expliqué pour chaque verbe","points":4},{"critere":"Récit : quatre verbes à préverbe employés dans un sens juste (2 séparables, 2 inséparables)","points":4},{"critere":"Participes II corrects (ge- seulement pour les séparables) et auxiliaires justes","points":6}],"dureeMin":16,"corrige":"**1.**\na) *sich verlaufen* = **se perdre** : *ver-* exprime l'erreur (marcher dans la mauvaise direction).\nb) *zerbrechen* = **se briser** : *zer-* = destruction en morceaux (*brechen* = casser).\nc) *entkommen* = **s'échapper** : *ent-* = éloignement (*kommen* = venir) ; *jm entkommen*, échapper à quelqu'un.\nd) *beantworten* = **répondre à** (une question) : *be-* rend le verbe transitif (*antworten auf* → *etwas beantworten*).\ne) *verschlafen* = **ne pas se réveiller à temps, dormir trop longtemps** : *ver-* = erreur.\nf) *verbrauchen* = **consommer** : *ver-* = consommation complète (*brauchen* = avoir besoin de).\n\n**2. Récit modèle**\n*Heute Morgen habe ich **verschlafen**. Ich bin um acht Uhr **aufgestanden** und schnell aus dem Haus gegangen. Im Bus bin ich zu spät **umgestiegen**, und dann habe ich mich in der Stadt **verlaufen**. In der Schule hat der Lehrer mir eine Frage gestellt, aber ich habe sie nicht **beantwortet**. Am Abend bin ich endlich nach Hause **zurückgekommen**.*\n\nÀ vérifier : séparables avec *ge-* entre préverbe et radical (*aufgestanden, umgestiegen, zurückgekommen*) ; inséparables sans *ge-* (*verschlafen, verlaufen, beantwortet*) ; *sein* pour les déplacements (*bin aufgestanden, bin umgestiegen*). Tout récit cohérent qui respecte ces contraintes obtient les points."}$exo$::jsonb),
  ('22a70af2-3b16-57ba-9179-a8946666b8e3'::uuid, 1, 'traduction', $exo${"titre":"Deux actions en même temps","consigne":"Complète chaque phrase avec le mot qui convient, choisi dans la liste. Chaque mot sert une fois.","enonce":"**Liste :** *während · beim · als · wenn · solange · gleichzeitig*\n\n1. ___ Essen hören wir Radio.\n2. ___ ich arbeite, schläft er.\n3. ___ es regnet, bleiben wir hier.\n4. ___ ich klein war, wohnte ich in Berlin.\n5. Immer ___ ich ihn sehe, lacht er.\n6. Sie kocht. ___ telefoniert sie.\n\n**Question :** Pourquoi *Essen* prend-il une majuscule dans la phrase 1 ?","bareme":[{"critere":"Six mots correctement placés","points":12},{"critere":"Distinction als / wenn respectée (phrases 4 et 5)","points":4},{"critere":"Majuscule expliquée : infinitif devenu nom neutre après beim","points":4}],"dureeMin":7,"corrige":"1. **Beim** Essen hören wir Radio. (*beim* + infinitif substantivé = « en mangeant »)\n2. **Während** ich arbeite, schläft er. (subordonnant, verbe à la fin)\n3. **Solange** es regnet, bleiben wir hier. (« tant que »)\n4. **Als** ich klein war, wohnte ich in Berlin. (une période unique du passé → *als*)\n5. Immer **wenn** ich ihn sehe, lacht er. (« chaque fois » → *wenn*)\n6. Sie kocht. **Gleichzeitig** telefoniert sie. (adverbe → inversion : verbe puis sujet)\n\n**Majuscule** : *beim* = *bei dem* ; l'infinitif *essen* devient un **nom neutre** (*das Essen*), et en allemand tous les noms prennent une majuscule."}$exo$::jsonb),
  ('22a70af2-3b16-57ba-9179-a8946666b8e3'::uuid, 2, 'traduction', $exo${"titre":"En mangeant, pendant que, tant que : six phrases à traduire","consigne":"Traduis les phrases en allemand en choisissant l'outil qui convient, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\na) En conduisant, il écoute de la musique.\nb) Pendant que je travaille, il dort.\nc) Tant qu'il pleut, nous restons à la maison.\nd) Quand j'étais petit, j'habitais à Munich.\ne) Chaque fois que je la vois, elle rit.\nf) Pendant le cours, il ne parle pas.\n\n*Aide : Auto fahren = conduire ; der Unterricht = le cours.*\n\n**2.** Pour la phrase f), donne une autre traduction avec *während* suivi d'une subordonnée. Quel changement de construction cela entraîne-t-il ?","bareme":[{"critere":"Outil juste dans chaque phrase (beim, während, solange, als, wenn)","points":7},{"critere":"Ordre des mots : verbe à la fin des subordonnées, inversion dans la principale","points":6},{"critere":"während + génitif juste (während des Unterrichts)","points":3},{"critere":"Deuxième traduction de f) et changement de construction expliqué","points":4}],"dureeMin":10,"corrige":"**1.**\na) *Beim Autofahren hört er Musik.* (*beim* + infinitif substantivé, majuscule ; inversion *hört er*)\nb) *Während ich arbeite, schläft er.*\nc) *Solange es regnet, bleiben wir zu Hause.*\nd) *Als ich klein war, wohnte ich in München.* (une seule période du passé → *als*)\ne) *Immer wenn ich sie sehe, lacht sie.* (« chaque fois » → *wenn*)\nf) *Während des Unterrichts spricht er nicht.* (préposition *während* + **génitif**)\n\n**2.** *Während der Unterricht läuft, spricht er nicht.* (ou *Während wir Unterricht haben, …*). Avec la **préposition**, *während* est suivi d'un groupe nominal au génitif, sans verbe ; avec le **subordonnant**, il introduit une proposition avec un sujet et un verbe conjugué **à la fin**. Dans les deux cas, le verbe de la principale suit immédiatement (*spricht er*)."}$exo$::jsonb),
  ('22a70af2-3b16-57ba-9179-a8946666b8e3'::uuid, 3, 'traduction', $exo${"titre":"Pendant que ou tandis que ? Les deux visages de während","consigne":"Réponds aux trois parties. Justifie tes choix.","enonce":"**1. Sens de *während*.** Pour chaque phrase, dis si *während* est temporel (pendant que) ou adversatif (tandis que), justifie, puis traduis.\n\na) Während er kocht, deckt sie den Tisch.\nb) Während Paul Sport liebt, liest seine Schwester lieber.\nc) Während meine Eltern gern fernsehen, lese ich lieber Bücher.\n\n*Aide : den Tisch decken = mettre la table.*\n\n**2. Thème.** Traduis :\n\n> En faisant ses devoirs, Mia écoute de la musique ; pendant ce temps, son frère joue au football. Quand elle a fini, elle l'appelle.\n\n**3. Reformulation.** Récris *Während des Frühstücks liest er die Zeitung* de deux façons : avec *beim*, puis avec *während* subordonnant.","bareme":[{"critere":"Sens de während juste et justifié dans les trois phrases","points":5},{"critere":"Traduction française juste des trois phrases","points":3},{"critere":"Thème : beim ou bei den Hausaufgaben, währenddessen + inversion, wenn pour le présent","points":7},{"critere":"Deux reformulations justes","points":5}],"dureeMin":16,"corrige":"**1.**\na) **Temporel** : les deux actions se font en même temps et se complètent. → « Pendant qu'il fait la cuisine, elle met la table. »\nb) **Adversatif** : les goûts de Paul et de sa sœur s'opposent. → « Tandis que Paul aime le sport, sa sœur préfère lire. »\nc) **Adversatif** : deux préférences opposées. → « Alors que mes parents aiment regarder la télévision, moi, je préfère lire des livres. »\nCritère : si les deux actions s'**opposent**, c'est l'adversatif ; si elles se déroulent simplement en même temps, c'est le temporel.\n\n**2. Traduction modèle**\n*Bei den Hausaufgaben hört Mia Musik; währenddessen spielt ihr Bruder Fußball. Wenn sie fertig ist, ruft sie ihn an.*\n- « En faisant ses devoirs » → *Bei den Hausaufgaben* (ou *Beim Hausaufgabenmachen*), puis inversion *hört Mia*. *beim* est possible car c'est Mia qui fait les deux actions.\n- « pendant ce temps » → *währenddessen*, adverbe → inversion *spielt ihr Bruder*.\n- « Quand elle a fini » : au présent, et pas pour une seule fois dans le passé → *wenn* (et non *als*) ; *anrufen* séparable (*ruft … an*).\n\n**3.**\n- *Beim Frühstück liest er die Zeitung.*\n- *Während er frühstückt, liest er die Zeitung.* (verbe à la fin de la subordonnée, inversion dans la principale)"}$exo$::jsonb),
  ('b008759b-3def-5f0d-b9e6-903018fc285f'::uuid, 1, 'traduction', $exo${"titre":"Une idée, trois constructions","consigne":"Récris et complète les phrases comme demandé, en respectant la place du verbe.","enonce":"**1.** Relie les deux phrases *Es regnet. Wir gehen spazieren.* de trois façons :\na) avec *obwohl* (commence par *Obwohl*) ;\nb) avec *trotzdem* ;\nc) avec *trotz* (commence par *Trotz*).\n\n*Aide : der Regen = la pluie.*\n\n**2.** Complète avec *aber* ou *sondern*.\na) Das ist nicht teuer, ___ billig.\nb) Das ist teuer, ___ praktisch.\n\n**3.** Donne le sens de : *außerdem, dagegen, d. h.*","bareme":[{"critere":"Trois constructions de la concession justes, avec la bonne place du verbe","points":9},{"critere":"aber et sondern bien choisis","points":5},{"critere":"Trois sens justes","points":6}],"dureeMin":7,"corrige":"**1.**\na) *Obwohl es regnet, gehen wir spazieren.* (subordonnant → verbe à la fin ; la subordonnée compte comme 1re place → *gehen wir*)\nb) *Es regnet, trotzdem gehen wir spazieren.* (adverbe → inversion : verbe puis sujet)\nc) *Trotz des Regens gehen wir spazieren.* (préposition + génitif, pas de verbe dans le groupe)\n\n**2.**\na) *Das ist nicht teuer, **sondern** billig.* (après une négation, « mais au contraire »)\nb) *Das ist teuer, **aber** praktisch.* (simple opposition, pas de négation ; *zwar … aber* possible)\n\n**3.** *außerdem* = **de plus, en outre** ; *dagegen* = **en revanche** ; *d. h.* (*das heißt*) = **c'est-à-dire**."}$exo$::jsonb),
  ('b008759b-3def-5f0d-b9e6-903018fc285f'::uuid, 2, 'traduction', $exo${"titre":"Grande ville, petit village : articuler un paragraphe","consigne":"Complète le paragraphe avec les connecteurs de la liste (chacun une fois), puis justifie la place du verbe dans trois phrases.","enonce":"**Liste :** *zwar · außerdem · dagegen · obwohl · trotzdem · d. h.*\n\n> Das Leben in der Stadt ist (1) ___ teuer, aber es bietet viele Möglichkeiten. (2) ___ gibt es dort Kinos, Museen und gute Schulen. Auf dem Land ist das Leben (3) ___ ruhiger und billiger. (4) ___ das Dorf schön ist, ziehen viele junge Leute weg. Die Dörfer werden kleiner, (5) ___ es gibt dort weniger Geschäfte und Ärzte. Viele Familien bleiben (6) ___ auf dem Land, weil sie die Natur lieben.\n\n*Aide : die Möglichkeit = la possibilité ; wegziehen = partir, déménager.*\n\n**Question :** explique la place du verbe après les connecteurs (2), (4) et (6).","bareme":[{"critere":"Six connecteurs justes, cohérents avec le sens","points":10},{"critere":"Place du verbe expliquée pour (2), (4) et (6) selon la nature du connecteur","points":6},{"critere":"Nature de chaque connecteur identifiée (adverbe, subordonnant)","points":4}],"dureeMin":10,"corrige":"**Paragraphe complété**\n> Das Leben in der Stadt ist (1) **zwar** teuer, aber es bietet viele Möglichkeiten. (2) **Außerdem** gibt es dort Kinos, Museen und gute Schulen. Auf dem Land ist das Leben (3) **dagegen** ruhiger und billiger. (4) **Obwohl** das Dorf schön ist, ziehen viele junge Leute weg. Die Dörfer werden kleiner, (5) **d. h.** es gibt dort weniger Geschäfte und Ärzte. Viele Familien bleiben (6) **trotzdem** auf dem Land, weil sie die Natur lieben.\n\nSens : *zwar … aber* (certes… mais) ; *außerdem* (un argument de plus) ; *dagegen* (en revanche, opposition ville/campagne) ; *obwohl* (bien que) ; *d. h.* (reformulation : ce que veut dire « les villages rétrécissent ») ; *trotzdem* (quand même : malgré le départ des jeunes).\n\n**Place du verbe**\n- (2) *Außerdem gibt es* : *außerdem* est un **adverbe** qui occupe la 1re place → **inversion**, le verbe *gibt* en 2e position, le sujet *es* après.\n- (4) *Obwohl das Dorf schön ist, ziehen …* : *obwohl* est un **subordonnant** → verbe conjugué *ist* **à la fin** ; la subordonnée occupe la 1re place, donc la principale commence par le verbe *ziehen*.\n- (6) *Viele Familien bleiben trotzdem* : *trotzdem* est un adverbe, placé ici après le verbe ; l'ordre reste normal (sujet, verbe). En tête de phrase, il aurait imposé l'inversion : *Trotzdem bleiben viele Familien…*"}$exo$::jsonb),
  ('b008759b-3def-5f0d-b9e6-903018fc285f'::uuid, 3, 'traduction', $exo${"titre":"Faut-il interdire le portable au lycée ?","consigne":"Rédige en allemand un paragraphe argumenté de 100 à 120 mots. Emploie au moins six connecteurs du cours, dont au moins un coordonnant, deux adverbes et deux subordonnants, et souligne-les.","enonce":"**Sujet :** *Sollte man das Handy in der Schule verbieten?*\n\n**Structure imposée**\n1. *Einerseits* … (un argument pour l'interdiction)\n2. *Andererseits* … (un argument contre)\n3. *Außerdem* … (un argument de plus, dans le sens de ton choix)\n4. *Zusammenfassend kann man sagen, dass* … (conclusion)\n\n**Idées possibles** : *sich konzentrieren* (se concentrer), *ablenken* (distraire), *im Notfall* (en cas d'urgence), *recherchieren* (faire des recherches), *die Pause* (la récréation), *miteinander sprechen* (se parler).\n\nPense aussi à une concession : *zwar … aber*, *obwohl*, *trotzdem* ou *auch wenn*.","bareme":[{"critere":"Structure imposée respectée et prise de position claire","points":4},{"critere":"Arguments pertinents et développés (pour, contre, conclusion)","points":4},{"critere":"Six connecteurs variés des trois natures, employés dans le bon sens","points":6},{"critere":"Place du verbe juste après chaque connecteur (ordre normal, inversion, verbe à la fin)","points":6}],"dureeMin":18,"corrige":"**Texte modèle (≈ 110 mots)**\n\n*Einerseits lenkt das Handy die Schüler im Unterricht ab, **denn** viele schauen ständig auf ihre Nachrichten. **Außerdem** sprechen die Jugendlichen in der Pause weniger miteinander. Andererseits ist das Handy **zwar** manchmal störend, **aber** es kann auch nützlich sein: Man kann damit recherchieren, **d. h.** schnell Informationen finden. **Obwohl** es Probleme gibt, braucht man das Handy im Notfall. **Trotzdem** bin ich für ein Verbot im Unterricht, **während** es in der Pause erlaubt bleiben sollte. Zusammenfassend kann man sagen, dass das Handy nicht verboten, **sondern** besser kontrolliert werden sollte.*\n\n**Connecteurs employés et construction**\n- Coordonnants (ordre normal) : *denn* (… *viele schauen*), *aber*, *sondern*.\n- Adverbes (inversion) : *Außerdem sprechen die Jugendlichen*, *Trotzdem bin ich*.\n- Subordonnants (verbe à la fin) : *Obwohl es Probleme gibt*, *während es … erlaubt bleiben sollte*, *dass … werden sollte*.\n- *zwar … aber* (concession), *d. h.* (reformulation).\n\nToute prise de position est acceptée (pour ou contre l'interdiction). Les points de langue portent sur la place du verbe : chaque connecteur doit être suivi de l'ordre des mots qui correspond à sa nature. *Sondern* n'est juste qu'après une négation."}$exo$::jsonb),
  ('b1db55e3-10c0-5572-8850-c6668b37cc1f'::uuid, 1, 'traduction', $exo${"titre":"Obligation ou supposition ?","consigne":"Pour chaque phrase, dis si le modal a un emploi objectif ou subjectif, puis traduis-la en français.","enonce":"1. Er muss heute arbeiten.\n2. Er muss krank sein.\n3. Das dürfte ein Fehler sein.\n4. Das kann nicht sein!\n5. Er muss nicht kommen.\n6. Er darf nicht kommen.\n\n**Question :** quelle différence de sens y a-t-il entre les phrases 5 et 6 ?","bareme":[{"critere":"Emploi objectif ou subjectif juste pour les six phrases","points":6},{"critere":"Six traductions justes, rendant le degré de certitude","points":9},{"critere":"Différence entre muss nicht et darf nicht expliquée","points":5}],"dureeMin":7,"corrige":"1. **Objectif** (obligation) : « Il doit travailler aujourd'hui. » / « Il est obligé de travailler aujourd'hui. »\n2. **Subjectif** (presque certain) : « Il doit être malade. » / « Il est sûrement malade. »\n3. **Subjectif** (très probable) : « Ça doit être une erreur. » / « C'est sans doute une erreur. »\n4. **Subjectif** (impossible) : « Ce n'est pas possible ! »\n5. **Objectif** (absence d'obligation) : « Il n'est pas obligé de venir. »\n6. **Objectif** (interdiction) : « Il n'a pas le droit de venir. » / « Il ne doit pas venir. »\n\n**Différence 5 / 6** : *muss nicht* = il n'y a **pas d'obligation** (il peut venir s'il veut) ; *darf nicht* = c'est **interdit**. Traduire *Er muss nicht kommen* par « il ne doit pas venir » est le contresens classique."}$exo$::jsonb),
  ('b1db55e3-10c0-5572-8850-c6668b37cc1f'::uuid, 2, 'traduction', $exo${"titre":"Du sûrement au peut-être : l'échelle de certitude","consigne":"Transforme chaque phrase en remplaçant l'adverbe par un verbe de modalité de même degré, puis réponds à la question.","enonce":"**1. Présent.** Remplace l'adverbe par un modal.\na) Er ist sicher krank.\nb) Sie ist vielleicht zu Hause.\nc) Das ist wahrscheinlich ein Fehler.\n\n**2. Passé.** Même travail, en employant le modal + infinitif passé.\nd) Er war sicher müde.\ne) Sie hat vielleicht den Bus verpasst.\nf) Das war wahrscheinlich schwierig.\n\n**3.** Traduis les phrases d), e) et f) transformées.\n\n**Question :** à quel temps reste le modal quand on juge un fait passé ?","bareme":[{"critere":"Trois modaux justes au présent (muss, kann/könnte, dürfte)","points":6},{"critere":"Trois phrases justes au passé (modal + participe II + haben/sein)","points":6},{"critere":"Trois traductions justes (a dû, a pu, a sans doute)","points":5},{"critere":"Règle du modal au présent énoncée","points":3}],"dureeMin":10,"corrige":"**1.**\na) *Er **muss** krank sein.* (sicher = presque certain → *muss*)\nb) *Sie **kann** (ou **könnte**) zu Hause sein.* (vielleicht = possible)\nc) *Das **dürfte** ein Fehler sein.* (wahrscheinlich = très probable)\n\n**2.**\nd) *Er **muss** müde **gewesen sein**.*\ne) *Sie **kann** den Bus **verpasst haben**.* (*könnte … verpasst haben* accepté)\nf) *Das **dürfte** schwierig **gewesen sein**.*\n\n**3.**\nd) « Il a dû être fatigué. » (« Il était sûrement fatigué. »)\ne) « Elle a pu rater le bus. » (« Elle a peut-être raté le bus. »)\nf) « Ça a dû être difficile. » (« Ça a sans doute été difficile. »)\n\n**Règle** : le modal reste **au présent** (le jugement se fait maintenant) ; c'est l'**infinitif** qui passe au passé : participe II + *haben* ou *sein* (*gewesen sein*, *verpasst haben*). *Er musste krank sein* serait faux : ce serait une obligation dans le passé."}$exo$::jsonb),
  ('b1db55e3-10c0-5572-8850-c6668b37cc1f'::uuid, 3, 'traduction', $exo${"titre":"Pourquoi Max s'est-il tu ? Faire des hypothèses","consigne":"Lis le texte, puis rédige en allemand 6 à 8 phrases d'hypothèses sur le comportement du personnage. Nuance tes suppositions avec l'échelle de certitude du cours.","enonce":"**Texte (inventé pour le sujet)**\n\n> Beim Abendessen erzählt die Mutter, dass jemand im Supermarkt eine Scheibe eingeschlagen hat. Max wird rot, sieht auf seinen Teller und sagt kein Wort. Nach dem Essen geht er sofort in sein Zimmer. Später hört seine Schwester, dass er leise telefoniert. Am nächsten Morgen ist er schon um sieben Uhr weg.\n\n*Aide : eine Scheibe einschlagen = casser une vitre ; rot werden = rougir ; der Teller = l'assiette.*\n\n**Consignes**\n1. Emploie au moins **quatre degrés** différents : *muss*, *dürfte*, *kann / könnte*, *kann nicht*.\n2. Au moins **deux** hypothèses portent sur un fait passé (modal + infinitif passé).\n3. Termine par une concession avec *Das mag sein, aber…*\n4. Emploie au moins un adverbe (*bestimmt, wahrscheinlich, vielleicht, kaum*).","bareme":[{"critere":"Hypothèses fondées sur des indices du texte","points":4},{"critere":"Quatre degrés de certitude employés correctement","points":6},{"critere":"Deux hypothèses au passé justes (modal au présent + infinitif passé)","points":5},{"critere":"Concession avec Das mag sein, aber… et un adverbe, correction de l'ensemble","points":5}],"dureeMin":16,"corrige":"**Production modèle**\n\n*Max muss etwas wissen, denn er wird rot und sagt kein Wort. Er dürfte die Scheibe selbst eingeschlagen haben, oder er muss den Täter gesehen haben. Vielleicht hat er Angst vor seinen Eltern. Er könnte am Abend einen Freund angerufen haben, um ihn zu warnen. Er kann aber nicht einfach müde gewesen sein, denn er ist am nächsten Morgen schon um sieben Uhr weg. Das mag sein, aber vielleicht schämt er sich nur, weil er einen Freund schützen will.*\n\n*(Aide acceptée : der Täter = le coupable ; warnen = prévenir ; sich schämen = avoir honte.)*\n\n**À vérifier**\n- Indices exploités : il rougit, il se tait, il part dans sa chambre, il téléphone en cachette, il part tôt.\n- Quatre degrés : *muss* (presque certain), *dürfte* (très probable), *könnte / kann* (possible), *kann nicht* (impossible).\n- Au passé : *dürfte … eingeschlagen haben*, *muss … gesehen haben*, *könnte … angerufen haben*, *kann nicht … gewesen sein* : modal au présent, participe II + *haben* ou *sein* à la fin.\n- *Das mag sein, aber…* pour concéder, puis un adverbe (*vielleicht*).\n\nToute hypothèse cohérente avec le texte est acceptée ; on ne récompense pas une affirmation présentée comme certaine sans modal ni adverbe."}$exo$::jsonb),
  ('6c812d1e-3b57-5c8f-8d6c-edc60516985a'::uuid, 1, 'traduction', $exo${"titre":"A, an, the ou rien ?","consigne":"Complète chaque phrase avec a, an, the ou Ø (article zéro), puis traduis les deux dernières phrases en anglais.","enonce":"**1. Complète avec a, an, the ou Ø.**\n\n1. She is ___ engineer.\n2. I bought ___ umbrella yesterday. ___ umbrella is blue.\n3. ___ sun rises in the east.\n4. It takes ___ hour to get there.\n5. ___ water is essential to life.\n6. We go swimming twice ___ week.\n\n**2. Traduis en anglais.**\n\n7. J'aime la musique.\n8. Les chats sont indépendants.","bareme":[{"critere":"Articles justes dans les six phrases à compléter (a / an / the / Ø)","points":12},{"critere":"Article zéro dans les deux traductions (music, cats au sens général)","points":8}],"dureeMin":7,"corrige":"**1.**\n1. *She is **an** engineer.* — métier → a/an ; *engineer* commence par un son voyelle → **an**.\n2. *I bought **an** umbrella yesterday. **The** umbrella is blue.* — première mention → *an* (son voyelle) ; déjà mentionné → *the*.\n3. ***The** sun rises in the east.* — objet unique → *the*.\n4. *It takes **an** hour…* — h muet, son voyelle → *an*.\n5. ***Ø** Water is essential to life.* — indénombrable au sens général → article zéro.\n6. *twice **a** week* — fréquence → *a*.\n\n**2.**\n7. *I like music.* (ou *I love music.*) — pas *the music* : sens général.\n8. *Cats are independent.* — pluriel au sens général → article zéro ; *The cats are independent* parlerait de chats précis.\n\nOn accepte *I love music*. Toute forme avec *the* devant *music* ou *cats* perd les points du critère 2."}$exo$::jsonb),
  ('6c812d1e-3b57-5c8f-8d6c-edc60516985a'::uuid, 2, 'traduction', $exo${"titre":"La chambre de Maya et Ethan","consigne":"Traduis le texte en anglais (thème). Soigne les articles, les possessifs et le génitif.","enonce":"**Thème : traduis en anglais.**\n\n> Maya et son frère Ethan partagent une chambre. Le lit de Maya est près de la fenêtre. Ethan est un musicien : sa guitare est sur le lit. Maya aime les livres et elle lit une heure par jour. Les jouets des enfants sont dans une boîte. La boîte est sous le bureau de leur père.\n\n*Aide : partager = to share ; jouet = toy ; bureau (meuble) = desk.*","bareme":[{"critere":"Articles justes : a musician, an hour, a day, a box / the box, Ø books","points":7},{"critere":"Possessifs accordés au possesseur (her brother, his guitar, their father)","points":5},{"critere":"Génitifs corrects (Maya's bed, the children's toys, their father's desk)","points":5},{"critere":"Sens général, ordre des mots et orthographe","points":3}],"dureeMin":11,"corrige":"**Traduction modèle**\n\n> *Maya and her brother Ethan share a room. Maya's bed is near the window. Ethan is a musician: his guitar is on the bed. Maya likes books and she reads an hour a day. The children's toys are in a box. The box is under their father's desk.*\n\n**Points attendus**\n- *her brother* : le possesseur est Maya → *her* ; *his guitar* : le possesseur est Ethan → *his* ; *their father* : deux possesseurs → *their*.\n- *Maya's bed* : génitif, le possesseur passe devant. *The children's toys* : pluriel irrégulier → *'s* (pas *childrens'*). *Their father's desk* : génitif singulier.\n- *a room*, *a box* : première mention d'un singulier dénombrable ; *the box* ensuite : déjà mentionné. *the window*, *the bed* : identifiés par le contexte.\n- *Ethan is a musician* : métier → *a*.\n- *likes books* : pluriel au sens général → article zéro (pas *the books*).\n- *an hour a day* : *an* devant h muet ; *a day* : fréquence.\n\nAccepté : *a bedroom*, *loves books*, *by the window*."}$exo$::jsonb),
  ('6c812d1e-3b57-5c8f-8d6c-edc60516985a'::uuid, 3, 'traduction', $exo${"titre":"Corriger la copie de Hugo","consigne":"Hugo a rendu un petit texte plein de fautes de déterminants. Repère les erreurs, corrige-les et justifie chaque correction par la règle du cours.","enonce":"**Voici le texte de Hugo :**\n\n> *The life in the Netherlands is pleasant. My cousin Lisa lives there with his husband. She is teacher and she works in an university. Its a big school. Lisa likes the nature and she goes cycling three times the week. Last summer, I visited Lisa's parents house. This days were the best days of my life.*\n\n1. Relève et corrige les **neuf** erreurs du texte.\n2. Pour chacune, donne en une phrase la règle qui justifie la correction.\n3. Réécris la dernière phrase en parlant d'une époque lointaine et révolue, puis explique le déterminant choisi.","bareme":[{"critere":"Les neuf erreurs repérées et corrigées","points":8},{"critere":"Une règle juste et précise pour chaque correction","points":7},{"critere":"Réécriture de la dernière phrase avec those et justification (distance)","points":3},{"critere":"Texte final correct et orthographe","points":2}],"dureeMin":17,"corrige":"**1 et 2. Les neuf erreurs**\n1. *The life* → ***Life*** : indénombrable au sens général → article zéro (« la vie en général »). *The Netherlands* est juste : pays au pluriel.\n2. *his husband* → ***her husband*** : le possessif s'accorde avec le possesseur, Lisa (féminin).\n3. *She is teacher* → *She is **a** teacher* : un métier prend *a/an*.\n4. *an university* → ***a** university* : on regarde le son (« you- »), un son de consonne → *a*.\n5. *Its a big school* → ***It's** a big school* : *it's* = *it is* ; *its* sans apostrophe est le possessif.\n6. *the nature* → ***nature*** : indénombrable au sens général → article zéro.\n7. *three times the week* → *three times **a** week* : la fréquence se dit avec *a*.\n8. *Lisa's parents house* → *Lisa's **parents'** house* : possesseur au pluriel en -s → apostrophe seule.\n9. *This days* → ***These** days* (ou *Those days*) : *this* est singulier, son pluriel est *these* (proche) ou *those* (éloigné).\n\n**3.** *Those days were the best days of my life.* *Those* : pluriel de *that*, il situe le nom **loin** dans le temps, une époque révolue ; *these* désignerait ce qui est proche, maintenant. *The best* reste : le superlatif prend toujours *the*.\n\n**Texte corrigé** : *Life in the Netherlands is pleasant. My cousin Lisa lives there with her husband. She is a teacher and she works in a university. It's a big school. Lisa likes nature and she goes cycling three times a week. Last summer, I visited Lisa's parents' house. Those days were the best days of my life.*"}$exo$::jsonb),
  ('69c80eb6-39df-527b-8e5a-e9f09fbb699b'::uuid, 1, 'traduction', $exo${"titre":"Choisir le bon modal","consigne":"Complète chaque phrase avec le modal qui convient et indique entre parenthèses ce qu'il exprime (capacité, obligation, conseil, possibilité, interdiction, déduction).","enonce":"**Complète avec : can, must, mustn't, should, might, must.**\n\n1. You look tired. You ___ go to bed earlier.\n2. Take an umbrella: it ___ rain this afternoon.\n3. My little sister is only five but she ___ read.\n4. You ___ smoke in the hospital: it is forbidden.\n5. He has worked all night. He ___ be exhausted.\n6. The rules are clear: you ___ wear a helmet on a motorbike.\n\n**7.** Trouve et corrige l'erreur : *She cans to swim.*","bareme":[{"critere":"Modal juste dans chacune des six phrases","points":12},{"critere":"Valeur du modal correctement nommée","points":5},{"critere":"Correction de She cans to swim (pas de -s, pas de to)","points":3}],"dureeMin":7,"corrige":"1. *You **should** go to bed earlier.* (conseil)\n2. *It **might** rain this afternoon.* (possibilité incertaine)\n3. *She **can** read.* (capacité)\n4. *You **mustn't** smoke in the hospital.* (interdiction)\n5. *He **must** be exhausted.* (déduction quasi certaine, valeur épistémique)\n6. *You **must** wear a helmet.* (obligation) — on accepte *have to* si l'élève l'écrit, puisque la règle vient des circonstances.\n\n7. *She **can swim**.* Deux fautes : un modal ne prend **jamais de -s** à la 3e personne, et il est suivi de la **base verbale sans to**."}$exo$::jsonb),
  ('69c80eb6-39df-527b-8e5a-e9f09fbb699b'::uuid, 2, 'traduction', $exo${"titre":"Le règlement du stage de voile","consigne":"Traduis le règlement en anglais, puis réponds à la question 2 en français.","enonce":"**1. Thème : traduis en anglais.**\n\n> Règlement du club de voile\n> - Vous devez porter un gilet de sauvetage.\n> - Vous ne devez pas nager seul après 18 h.\n> - Vous n'êtes pas obligés d'apporter votre matériel : le club le prête.\n> - Vous devriez boire de l'eau régulièrement.\n> - Il se peut que la sortie soit annulée s'il y a du vent.\n\n*Aide : gilet de sauvetage = life jacket ; prêter = to lend ; annuler = to cancel ; vent = wind.*\n\n**2.** Explique la différence de sens entre la phrase 2 et la phrase 3.","bareme":[{"critere":"Modaux justes : must, mustn't, don't have to, should, might/may","points":10},{"critere":"Forme correcte : base verbale sans to, pas de -s","points":4},{"critere":"Explication juste de mustn't (interdiction) et don't have to (absence d'obligation)","points":4},{"critere":"Vocabulaire et orthographe","points":2}],"dureeMin":11,"corrige":"**1. Traduction modèle**\n\n> *Sailing club rules*\n> - *You must wear a life jacket.*\n> - *You mustn't swim alone after 6 pm.*\n> - *You don't have to bring your equipment: the club lends it.*\n> - *You should drink water regularly.*\n> - *The trip might be cancelled if it is windy.* (ou *if there is wind* ; *may* accepté)\n\n**Points attendus** : *must* (obligation) ; *mustn't* (interdiction) ; *don't have to* (absence d'obligation) ; *should* (conseil) ; *might/may* (possibilité incertaine). Toujours la base verbale sans *to* après le modal. *If it is windy* : présent après *if*.\n\n**2.** *Mustn't* exprime une **interdiction** : « il ne faut pas » nager seul après 18 h. *Don't have to* exprime une **absence d'obligation** : ce n'est pas la peine d'apporter son matériel, mais on peut le faire. Les confondre changerait complètement le sens du règlement."}$exo$::jsonb),
  ('69c80eb6-39df-527b-8e5a-e9f09fbb699b'::uuid, 3, 'traduction', $exo${"titre":"Le mystère du vélo disparu","consigne":"Lis la situation, puis réponds en anglais aux questions 1 et 2, en français à la question 3.","enonce":"**Situation.** Ce matin, le vélo de Noah n'était plus devant le lycée. Voici ce qu'on sait :\n\n> Noah left his bike unlocked. The school gate was open all night. Noah's friend Jake says he saw the bike at 8 pm. Jake is very honest. The caretaker was on holiday.\n\n1. Écris **quatre phrases** au passé qui font des hypothèses ou des déductions, avec *must have*, *might have*, *can't have* et *should have* + participe passé. (Ex. : quelqu'un a pu le prendre la nuit ; Jake n'a pas pu mentir ; Noah aurait dû l'attacher…)\n2. Traduis : « Il se pourrait qu'il le retrouve. Il pourra prendre le bus en attendant. »\n3. Explique pourquoi on ne peut pas écrire *he will can take the bus*, et pourquoi *He must be sad* ne signifie pas une obligation.","bareme":[{"critere":"Quatre phrases modal + have + participe passé correctes et adaptées à la situation","points":8},{"critere":"Valeur juste de chaque structure (déduction, hypothèse, déduction négative, reproche)","points":4},{"critere":"Traduction : might find it / will be able to take","points":4},{"critere":"Explications justes (deux modaux impossibles ; must épistémique)","points":4}],"dureeMin":16,"corrige":"**1. Exemples de réponses attendues**\n- *Someone must have taken it during the night.* — déduction quasi certaine sur le passé (le portail était ouvert).\n- *A thief might have seen that it was unlocked.* — hypothèse.\n- *Jake can't have lied: he is very honest.* — déduction négative.\n- *Noah should have locked his bike.* — reproche sur le passé.\nToute phrase juste et cohérente avec la situation est acceptée. Structure obligatoire : modal + *have* + **participe passé** (*taken, seen, lied, locked*).\n\n**2.** *He might find it. He will be able to take the bus in the meantime.* (*may find it* accepté ; *meanwhile* accepté.)\n\n**3.** Deux modaux ne se suivent jamais : *will* est déjà un modal, on ne peut donc pas lui ajouter *can*. Pour dire « il pourra », on remplace *can* par *be able to* : *he will be able to*.\n*Must* a deux valeurs : **radicale** (un ordre : *you must go*) et **épistémique** (une déduction : *he must be sad*). C'est le contexte qui tranche : ici on ne donne pas d'ordre à Noah, on déduit son état d'après la situation — « il doit être triste », c'est-à-dire « il est sûrement triste »."}$exo$::jsonb),
  ('7eadba78-d023-5894-a7f1-d4153546dd32'::uuid, 1, 'traduction', $exo${"titre":"Le samedi de Chloé","consigne":"Mets les verbes entre parenthèses au prétérit simple, puis transforme les deux dernières phrases comme demandé.","enonce":"**1. Mets au prétérit.**\n\n> Last Saturday, Chloé (get) ___ up at 9. She (play) ___ tennis with her brother, then they (go) ___ to the cinema. They (see) ___ a comedy. After that, she (study) ___ for two hours and she (take) ___ the bus home.\n\n**2.**\n- Mets à la forme négative : *She saw a comedy.*\n- Pose la question portant sur le mot souligné : *They went **to the cinema**.* (commence par *Where*)","bareme":[{"critere":"Six verbes au prétérit justes (réguliers et irréguliers)","points":12},{"critere":"Négative et interrogative avec did + base verbale","points":8}],"dureeMin":7,"corrige":"**1.** *Last Saturday, Chloé **got** up at 9. She **played** tennis with her brother, then they **went** to the cinema. They **saw** a comedy. After that, she **studied** for two hours and she **took** the bus home.*\n- *play → played* (régulier, base + -ed) ; *study → studied* (y après consonne → -ied).\n- Irréguliers : *get → got*, *go → went*, *see → saw*, *take → took*.\n- Marqueur *last Saturday* : passé révolu → prétérit.\n\n**2.**\n- *She didn't see a comedy.* — *did* porte le passé, le verbe revient à la base (pas *didn't saw*).\n- *Where did they go?* — auxiliaire *did* + sujet + base verbale (pas *Where did they went?*)."}$exo$::jsonb),
  ('7eadba78-d023-5894-a7f1-d4153546dd32'::uuid, 2, 'traduction', $exo${"titre":"La panne d'électricité","consigne":"Complète le récit avec le prétérit simple ou le prétérit en BE + -ING, puis justifie deux de tes choix.","enonce":"**1. Complète le récit.**\n\n> It (rain) ___ and the wind (blow) ___. My parents (watch) ___ the news and I (do) ___ my homework when suddenly the lights (go) ___ out. My father (find) ___ a candle and we (play) ___ cards until midnight.\n\n**2.** Justifie le temps choisi pour *(watch)* et pour *(go)*.\n\n**3.** Traduis : « Il y a deux ans, nous vivions à Lyon. »","bareme":[{"critere":"Décor au prétérit BE + -ING (was raining, was blowing, were watching, was doing)","points":8},{"critere":"Événements au prétérit simple (went, found, played)","points":6},{"critere":"Justification décor / événement","points":3},{"critere":"Traduction avec ago et le prétérit","points":3}],"dureeMin":11,"corrige":"**1.** *It **was raining** and the wind **was blowing**. My parents **were watching** the news and I **was doing** my homework when suddenly the lights **went** out. My father **found** a candle and we **played** cards until midnight.*\n\n**2.** *Were watching* : c'est le **décor**, une action en cours au moment du récit (équivalent de l'imparfait « regardaient »). *Went* : c'est l'**événement** qui survient et interrompt le décor (passé simple ou composé « s'est éteinte »), donc prétérit simple.\n\n**3.** *Two years ago, we lived in Lyon.* (*we were living in Lyon* accepté). Fait situé dans un passé révolu avec *ago* → prétérit ; jamais *we have lived*."}$exo$::jsonb),
  ('7eadba78-d023-5894-a7f1-d4153546dd32'::uuid, 3, 'traduction', $exo${"titre":"Un souvenir de vacances","consigne":"Rédige en anglais un court récit (80 à 100 mots), puis réponds aux questions de grammaire en français.","enonce":"**1. Production.** Raconte en anglais un souvenir de vacances (réel ou inventé) en 80 à 100 mots. Tu dois utiliser :\n- au moins **deux** verbes réguliers et **quatre** verbes irréguliers au prétérit ;\n- au moins **deux** verbes au prétérit en BE + -ING pour planter le décor ;\n- une phrase **négative** et une phrase **interrogative** au prétérit ;\n- un **marqueur** de temps passé (*last summer*, *two years ago*…).\n\n**2.** Souligne (ou recopie) une phrase où le décor est interrompu par un événement, et explique la répartition des deux temps.\n\n**3.** Un camarade a écrit *I have visited Rome last year*. Corrige et explique.","bareme":[{"critere":"Prétérit simple juste : 2 réguliers et 4 irréguliers corrects","points":6},{"critere":"Deux prétérits BE + -ING employés pour le décor","points":4},{"critere":"Négative et interrogative avec did + base verbale, marqueur de temps","points":4},{"critere":"Explication de la phrase décor / événement","points":3},{"critere":"Correction de I have visited Rome last year et justification","points":3}],"dureeMin":18,"corrige":"**1. Exemple de récit attendu**\n\n> *Last summer, I went to Spain with my cousins. On the first day, the sun was shining and people were swimming everywhere. We walked along the beach and we ate paella. One evening, we were walking in the old town when a man stopped us. He spoke English and he told us the history of the city. We didn't understand everything, but it was fantastic. Did I want to go home? Not at all!*\n\nÀ vérifier : réguliers (*walked, stopped*), irréguliers (*went, ate, spoke, told, was*), décor (*was shining, were swimming, were walking*), négative *didn't understand* (base verbale), interrogative *Did I want…?* (base verbale), marqueur *last summer*. Longueur 80 à 100 mots.\n\n**2.** *We were walking in the old town when a man stopped us* : *were walking* est le décor, l'action en cours (imparfait) ; *stopped* est l'événement bref qui survient et l'interrompt (passé simple / composé).\n\n**3.** *I visited Rome last year.* *Last year* date le fait dans un passé terminé : dès qu'un repère de temps passé est présent, c'est le **prétérit**, jamais le present perfect."}$exo$::jsonb),
  ('46d5879d-235f-5639-91b0-04bd08c2f70f'::uuid, 1, 'traduction', $exo${"titre":"Since ou for ?","consigne":"Complète avec since ou for, puis mets le verbe au present perfect.","enonce":"**1. Complète avec since ou for et mets le verbe au present perfect.**\n\n1. I (know) ___ Amir ___ 2020.\n2. She (live) ___ in London ___ ten years.\n3. We (not see) ___ our grandparents ___ Christmas.\n4. They (be) ___ friends ___ a long time.\n\n**2.** Complète avec *already, yet, ever, just*.\n\n5. Have you ___ been to Canada?\n6. I haven't finished my homework ___.\n7. The bus has ___ left: you can see it at the end of the street!","bareme":[{"critere":"Present perfect bien formé (have/has + participe passé)","points":8},{"critere":"Since (point de départ) et for (durée) justes","points":6},{"critere":"Marqueurs ever, yet, just/already bien placés","points":6}],"dureeMin":8,"corrige":"**1.**\n1. *I **have known** Amir **since** 2020.* (point de départ)\n2. *She **has lived** in London **for** ten years.* (durée)\n3. *We **haven't seen** our grandparents **since** Christmas.* (point de départ)\n4. *They **have been** friends **for** a long time.* (durée)\n\n**2.**\n5. *Have you **ever** been to Canada?* — expérience de vie.\n6. *I haven't finished my homework **yet**.* — *yet* en fin de phrase négative.\n7. *The bus has **just** left* — vient juste de partir (*already* accepté).\n\nRappel : situation commencée dans le passé et qui dure encore → present perfect, jamais le présent (*I know Amir since 2020* est faux)."}$exo$::jsonb),
  ('46d5879d-235f-5639-91b0-04bd08c2f70f'::uuid, 2, 'traduction', $exo${"titre":"Le message de Léna","consigne":"Traduis le message en anglais, puis réponds à la question 2 en français.","enonce":"**1. Thème : traduis en anglais.**\n\n> Salut Emma ! J'apprends l'anglais depuis six ans et je n'ai jamais visité l'Angleterre. Mon frère a déjà vu Londres trois fois. J'ai perdu mon passeport : je ne peux pas partir cet été ! Ma mère le cherche depuis ce matin.\n\n*Aide : passeport = passport ; chercher = to look for.*\n\n**2.** Explique pourquoi « J'ai perdu mon passeport » se met au present perfect ici, et pourquoi « Ma mère le cherche depuis ce matin » se met au present perfect en BE + -ING.","bareme":[{"critere":"Depuis traduit par present perfect + for/since (have been learning ou have learnt ; has been looking for)","points":7},{"critere":"Present perfect avec never, already, et have lost","points":6},{"critere":"Explications : résultat présent / durée qui continue","points":5},{"critere":"Vocabulaire et orthographe","points":2}],"dureeMin":12,"corrige":"**1. Traduction modèle**\n\n> *Hi Emma! I have been learning English for six years and I have never visited England. My brother has already seen London three times. I have lost my passport: I can't leave this summer! My mother has been looking for it since this morning.*\n\nAcceptés : *I have learnt/learned English for six years* ; *I've never been to England*.\n\n**Points attendus** : « depuis six ans » au présent en français → present perfect + **for** (durée) ; « depuis ce matin » → **since** (point de départ). *Never*, *already* : marqueurs du present perfect. Jamais *I learn English since…*.\n\n**2.** *I have lost my passport* : le present perfect fait le **bilan au présent** ; ce qui compte est le **résultat actuel** (je ne l'ai plus, donc je ne peux pas partir), pas le moment de la perte. *Has been looking for it* : la forme BE + -ING insiste sur la **durée** d'une action commencée ce matin et qui **continue encore**."}$exo$::jsonb),
  ('46d5879d-235f-5639-91b0-04bd08c2f70f'::uuid, 3, 'traduction', $exo${"titre":"Prétérit ou present perfect : l'entretien de Sofia","consigne":"Complète le dialogue avec le temps qui convient (prétérit, present perfect simple ou BE + -ING), puis justifie tes choix.","enonce":"**Sofia passe un entretien pour un job d'été.**\n\n> **Manager:** How long (you / work) ___ as a babysitter?\n> **Sofia:** I (work) ___ as a babysitter for two years. I (start) ___ in 2024.\n> **Manager:** (you / ever / work) ___ in a shop?\n> **Sofia:** Yes, last summer I (work) ___ in a bakery for a month.\n> **Manager:** Why are your hands so red?\n> **Sofia:** Oh, I (paint) ___ my bedroom all morning!\n> **Manager:** (you / finish) ___ it yet?\n> **Sofia:** No, I (not finish) ___ it yet.\n\n1. Complète les huit blancs.\n2. Justifie en une phrase chacun des temps choisis pour les blancs 2, 3, 5 et 6.\n3. Traduis : « Elle a écrit trois lettres ce matin (la matinée est finie). » puis « Elle a écrit trois lettres (elles sont prêtes). » et explique la différence.","bareme":[{"critere":"Huit formes verbales justes et bien construites","points":8},{"critere":"Justifications des blancs 2, 3, 5 et 6","points":6},{"critere":"Deux traductions justes (wrote / has written)","points":3},{"critere":"Explication récit daté / bilan au présent","points":3}],"dureeMin":18,"corrige":"**1.**\n1. *How long **have you been working** (ou **have you worked**) as a babysitter?*\n2. *I **have been working** (ou **have worked**) as a babysitter for two years.*\n3. *I **started** in 2024.*\n4. ***Have you ever worked** in a shop?*\n5. *Last summer I **worked** in a bakery for a month.*\n6. *I **have been painting** my bedroom all morning!*\n7. ***Have you finished** it yet?*\n8. *No, I **haven't finished** it yet.*\n\n**2.**\n- Blanc 2 : situation commencée dans le passé qui **dure encore**, avec *for* → present perfect (BE + -ING souligne la durée).\n- Blanc 3 : fait **daté** (*in 2024*) → prétérit ; un fait daté ne va jamais au present perfect.\n- Blanc 5 : *last summer* situe le fait dans un passé terminé → prétérit, même avec *for a month* (l'action est finie).\n- Blanc 6 : BE + -ING insiste sur la **durée** et ses **traces** visibles (les mains rouges).\n\n**3.** *She wrote three letters this morning.* (récit d'un moment passé et terminé → prétérit) / *She has written three letters.* (bilan : le **résultat** compte maintenant, les lettres sont écrites → present perfect). Le prétérit raconte un fait situé ; le present perfect fait le bilan au présent, sans repère daté."}$exo$::jsonb),
  ('edf767d9-8938-515b-b743-791df5954739'::uuid, 1, 'traduction', $exo${"titre":"Qu'est-ce qui s'est passé avant ?","consigne":"Mets un des deux verbes au past perfect et l'autre au prétérit, selon l'ordre réel des faits.","enonce":"**Conjugue les verbes : l'un au past perfect, l'autre au prétérit.**\n\n1. When we (arrive) ___ at the station, the train (already / leave) ___.\n2. She (be) ___ tired because she (not sleep) ___ well.\n3. After he (finish) ___ his homework, he (go) ___ out.\n4. I (recognise) ___ the town: I (visit) ___ it as a child.\n\n**5.** Dans *He'd gone* et *He'd go*, que remplace *'d* ? Explique comment tu le sais.","bareme":[{"critere":"Past perfect (had + participe passé) pour le fait le plus ancien","points":10},{"critere":"Prétérit juste pour le fait le plus récent","points":6},{"critere":"Distinction had / would après 'd expliquée","points":4}],"dureeMin":8,"corrige":"1. *When we **arrived** at the station, the train **had already left**.* — le départ du train est antérieur.\n2. *She **was** tired because she **hadn't slept** well.* — le mauvais sommeil est antérieur.\n3. *After he **had finished** his homework, he **went** out.* — *after* appelle le past perfect pour la première action.\n4. *I **recognised** the town: I **had visited** it as a child.* — la visite est antérieure.\n\n5. *He'd gone* : *'d* = **had**, car il est suivi d'un **participe passé** (*gone*). *He'd go* : *'d* = **would**, car il est suivi d'une **base verbale** (*go*)."}$exo$::jsonb),
  ('edf767d9-8938-515b-b743-791df5954739'::uuid, 2, 'traduction', $exo${"titre":"Ce que Tom a raconté","consigne":"Rapporte au discours indirect ce que Tom a dit, puis traduis la phrase de la question 2.","enonce":"**1. Tom a dit hier :**\n\n> « I have lost my phone. »\n> « I left it on the bus. »\n> « Nobody has called me since this morning. »\n\nRapporte ses paroles en commençant chaque phrase par *Tom said (that)…*\n\n**2. Traduis :** « Quand le médecin est arrivé, Paul était épuisé : il conduisait depuis dix heures. »\n\n**3.** Justifie le temps employé pour « il conduisait depuis dix heures ».","bareme":[{"critere":"Discours indirect : present perfect et prétérit transformés en past perfect","points":8},{"critere":"Pronoms et repères adaptés (he, his, it, that morning)","points":3},{"critere":"Traduction avec had been driving for ten hours","points":6},{"critere":"Justification : durée de l'action antérieure","points":3}],"dureeMin":11,"corrige":"**1.**\n- *Tom said (that) he **had lost** his phone.* (present perfect → past perfect)\n- *Tom said (that) he **had left** it on the bus.* (prétérit → past perfect)\n- *Tom said (that) nobody **had called** him since **that** morning.* (present perfect → past perfect ; *this morning* devient *that morning*, accepté aussi *since the morning*)\nPronoms : *I → he*, *my → his*, *me → him*.\n\n**2.** *When the doctor arrived, Paul was exhausted: he had been driving for ten hours.*\n\n**3.** *Had been driving* : past perfect en BE + -ING. Il marque une action **antérieure** à l'arrivée du médecin (déjà au passé) et insiste sur sa **durée** (*for ten hours*), qui explique l'épuisement."}$exo$::jsonb),
  ('edf767d9-8938-515b-b743-791df5954739'::uuid, 3, 'traduction', $exo${"titre":"Le soir du concert","consigne":"Traduis le récit en anglais, puis réponds aux questions en français.","enonce":"**1. Thème : traduis en anglais.**\n\n> Quand Inès est arrivée au stade, le concert avait déjà commencé. Elle avait attendu le bus pendant une heure et elle avait oublié son billet à la maison. Heureusement, son amie Zoé avait gardé une copie sur son téléphone. Si Inès avait su, elle serait partie plus tôt.\n\n*Aide : billet = ticket ; garder = to keep (kept, kept).*\n\n**2.** Classe dans l'ordre chronologique réel les cinq faits du récit (arrivée, début du concert, attente du bus, oubli du billet, copie gardée par Zoé — l'ordre des trois derniers entre eux importe peu, dis seulement qu'ils sont antérieurs à l'arrivée).\n\n**3.** Quelle structure emploie la dernière phrase ? Qu'exprime-t-elle ?","bareme":[{"critere":"Past perfect juste pour les faits antérieurs (had started, had forgotten, had kept)","points":6},{"critere":"Had been waiting ou had waited for an hour ; prétérit arrived","points":4},{"critere":"Irréel du passé : If Inès had known, she would have left earlier","points":4},{"critere":"Ordre chronologique expliqué","points":3},{"critere":"Structure et valeur de la dernière phrase","points":3}],"dureeMin":18,"corrige":"**1. Traduction modèle**\n\n> *When Inès arrived at the stadium, the concert had already started. She had been waiting for the bus for an hour and she had forgotten her ticket at home. Luckily, her friend Zoé had kept a copy on her phone. If Inès had known, she would have left earlier.*\n\nAcceptés : *had waited for the bus for an hour* ; *Fortunately* ; *had begun*.\n\n**2.** L'attente du bus, l'oubli du billet et la copie gardée par Zoé sont **antérieurs** à l'arrivée ; le concert a commencé avant l'arrivée ; l'arrivée d'Inès est le dernier fait, au **prétérit**, qui sert de repère. Tous les faits antérieurs sont au **past perfect** : il correspond au plus-que-parfait français (« avait commencé », « avait oublié »).\n\n**3.** *If* + **past perfect**, *would have* + **participe passé** : c'est l'**irréel du passé**. Inès n'a pas su, elle n'est pas partie plus tôt : on imagine ce qui aurait pu se passer et qui ne s'est pas produit."}$exo$::jsonb),
  ('fb3d717b-259a-5201-ac3a-3771771dc1b6'::uuid, 1, 'traduction', $exo${"titre":"Will ou be going to ?","consigne":"Complète chaque phrase avec la forme de futur qui convient, puis corrige l'erreur de la question 2.","enonce":"**1. Complète avec will, be going to, le présent en -ING ou le présent simple.**\n\n1. The phone is ringing! — Don't move, I ___ (answer) it.\n2. Look at those black clouds: it ___ (rain).\n3. We ___ (fly) to Dublin on Monday: the tickets are booked.\n4. Hurry up! The train ___ (leave) at 6:15.\n\n**2. Corrige :** *I'll call you when I will get home.*","bareme":[{"critere":"Forme de futur juste dans les quatre phrases","points":14},{"critere":"Correction : présent après when (when I get home)","points":6}],"dureeMin":6,"corrige":"**1.**\n1. *I**'ll answer** it.* — décision prise au moment où l'on parle → *will*.\n2. *It**'s going to rain**.* — prédiction fondée sur un indice visible → *be going to*.\n3. *We**'re flying** to Dublin on Monday.* — programme fixé, avec une date → présent en -ING.\n4. *The train **leaves** at 6:15.* — horaire officiel → présent simple.\n\n**2.** *I'll call you when I **get** home.* Après *when* (et *as soon as, until, before, after, if*), on emploie le **présent**, jamais *will*."}$exo$::jsonb),
  ('fb3d717b-259a-5201-ac3a-3771771dc1b6'::uuid, 2, 'traduction', $exo${"titre":"Et si… ? Trois hypothèses","consigne":"Termine chaque phrase en respectant le type d'hypothèse, puis traduis les deux phrases de la question 2.","enonce":"**1. Complète en conjuguant le verbe entre parenthèses.**\n\n1. If it (rain) ___ tomorrow, we will stay at home.\n2. If I (have) ___ more money, I would travel around the world.\n3. If you had told me, I (help) ___ you.\n4. If I (be) ___ you, I would talk to her.\n\n**2. Traduis en anglais.**\n\n5. Si tu te dépêches, tu auras le bus.\n6. Si j'avais su, je serais venu.\n\n**3.** Pour les phrases 1, 2 et 3, indique le type (1, 2 ou 3) et ce qu'il exprime.","bareme":[{"critere":"Formes verbales justes dans les quatre phrases (rains, had, would have helped, were)","points":8},{"critere":"Deux traductions justes (type 1 et type 3)","points":6},{"critere":"Types identifiés avec leur valeur (possible, irréel du présent, irréel du passé)","points":6}],"dureeMin":11,"corrige":"**1.**\n1. *If it **rains** tomorrow…* — présent après *if* (jamais *will rain*).\n2. *If I **had** more money…* — prétérit dans la subordonnée.\n3. *…I **would have helped** you.* — *would have* + participe passé.\n4. *If I **were** you…* — *were* est la forme soignée à toutes les personnes (*was* toléré à l'oral, mais on attend *were*).\n\n**2.**\n5. *If you hurry, you will catch the bus.* (*you'll get the bus* accepté)\n6. *If I had known, I would have come.*\n\n**3.**\n- Phrase 1 : **type 1**, *if* + présent / *will* : le **possible**.\n- Phrase 2 : **type 2**, *if* + prétérit / *would* : l'**irréel du présent** (je n'ai pas assez d'argent).\n- Phrase 3 : **type 3**, *if* + past perfect / *would have* : l'**irréel du passé** (tu ne me l'as pas dit).\n\nJamais *would* dans la subordonnée en *if*."}$exo$::jsonb),
  ('fb3d717b-259a-5201-ac3a-3771771dc1b6'::uuid, 3, 'traduction', $exo${"titre":"Les projets de Karim","consigne":"Rédige en anglais le texte demandé (70 à 90 mots), puis justifie tes choix en français.","enonce":"**Situation.** Karim, 16 ans, écrit à son correspondant anglais pour lui parler de ses projets d'été. Voici ses notes :\n\n> - Il a déjà décidé de chercher un petit boulot (intention ancienne).\n> - Son avion pour Londres part le 12 juillet à 10 h (horaire officiel), et il a réservé le vol avec son oncle pour ce jour-là (programme fixé).\n> - Il promet d'envoyer des photos.\n> - Il prévoit que la météo sera mauvaise, comme d'habitude.\n> - S'il gagnait au loto, il achèterait un scooter (il n'a aucune chance).\n> - Il lui téléphonera dès qu'il arrivera.\n\n1. Rédige la lettre de Karim en anglais (70 à 90 mots) en employant **toutes** les formes de l'avenir du cours et **une** hypothèse de type 2.\n2. Pour quatre phrases de ta lettre, explique en français pourquoi tu as choisi cette forme.","bareme":[{"critere":"Be going to pour l'intention, présent -ING pour le programme, présent simple pour l'horaire","points":6},{"critere":"Will pour la promesse et la prédiction","points":3},{"critere":"Hypothèse de type 2 correcte (If I won…, I would buy…)","points":3},{"critere":"Présent après as soon as (as soon as I arrive)","points":3},{"critere":"Justification de quatre choix, lettre cohérente et correcte","points":5}],"dureeMin":18,"corrige":"**1. Exemple de lettre attendue**\n\n> *Hi Jack,*\n> *This summer I'm going to look for a job. I'm flying to London with my uncle on 12th July: the plane leaves at 10 am. I'll send you lots of photos, I promise! I think the weather will be bad, as usual. If I won the lottery, I would buy a scooter, but I have no chance! I'll call you as soon as I arrive.*\n> *See you soon,*\n> *Karim*\n\n**Formes attendues** : *I'm going to look for* (intention déjà formée) ; *I'm flying… on 12th July* (programme fixé, daté) ; *the plane leaves at 10 am* (horaire officiel) ; *I'll send* (promesse) ; *the weather will be bad* (prédiction) ; *If I won…, I would buy* (type 2, irréel du présent : *if* + prétérit, *would* dans la principale) ; *as soon as I arrive* (présent après *as soon as*, jamais *will arrive*).\n\n**2.** L'élève justifie quatre choix en reprenant ces valeurs. Exemple : « *I'm going to* : Karim a déjà décidé, c'est une intention formée avant de parler. » / « *as soon as I arrive* : dans une subordonnée de temps, l'anglais met le présent pour parler de l'avenir. »"}$exo$::jsonb),
  ('0e320025-46ae-5153-bdac-f6192c2701f8'::uuid, 1, 'traduction', $exo${"titre":"Poser les bonnes questions","consigne":"Pose la question qui porte sur le mot en gras, puis ajoute le question tag qui convient.","enonce":"**1. Pose la question portant sur le passage en gras.**\n\n1. She lives **in Manchester**.\n2. They arrived **yesterday**.\n3. He goes to the gym **twice a week**.\n4. The film lasts **two hours**.\n\n**2. Ajoute le question tag.**\n\n5. You're French, ___?\n6. She likes pizza, ___?\n7. He can't swim, ___?","bareme":[{"critere":"Questions justes : mot interrogatif + auxiliaire + sujet + base verbale","points":12},{"critere":"Question tags justes (polarité inversée, bon auxiliaire)","points":8}],"dureeMin":7,"corrige":"**1.**\n1. *Where does she live?* (pas *Where does she lives?*)\n2. *When did they arrive?*\n3. *How often does he go to the gym?*\n4. *How long does the film last?*\nL'auxiliaire *do/does/did* porte le temps et la personne, le verbe reste à la base.\n\n**2.**\n5. *You're French, **aren't you**?*\n6. *She likes pizza, **doesn't she**?* — pas d'auxiliaire dans la phrase → *do*.\n7. *He can't swim, **can he**?* — phrase négative → tag positif."}$exo$::jsonb),
  ('0e320025-46ae-5153-bdac-f6192c2701f8'::uuid, 2, 'traduction', $exo${"titre":"L'interview d'une sportive","consigne":"Retrouve les questions du journaliste à partir des réponses de la championne, puis réponds à la question 2.","enonce":"**1. Voici les réponses de Maria, championne de natation. Écris les questions du journaliste.**\n\n1. — ___? — I started swimming **when I was six**.\n2. — ___? — I train **four hours a day**.\n3. — ___? — **My coach** taught me everything.\n4. — ___? — I admire **Laure Manaudou**.\n5. — ___? — She is **kind and very determined**.\n6. — ___? — The pool is **about two kilometres** from my house.\n\n**2.** Explique en français pourquoi les questions 3 et 4 ne se construisent pas de la même façon.","bareme":[{"critere":"Mots interrogatifs adaptés (when, how long, who, what... like, how far)","points":6},{"critere":"Ordre auxiliaire + sujet + base verbale dans les questions sur le complément","points":6},{"critere":"Question sur le sujet sans auxiliaire (Who taught you…?) et What is she like?","points":4},{"critere":"Explication question sur le sujet / sur le complément","points":4}],"dureeMin":12,"corrige":"**1.**\n1. *When did you start swimming?*\n2. *How long do you train (every day)?* (*How many hours a day do you train?* accepté)\n3. *Who taught you everything?* — pas de *did*.\n4. *Who do you admire?* (*Whom* accepté)\n5. *What is she like?* — on demande une description, son caractère (pas *How is she?*, qui demande comment elle va).\n6. *How far is the pool from your house?*\n\n**2.** Dans la question 3, *who* est le **sujet** du verbe (c'est l'entraîneur qui a appris) : on n'ajoute pas d'auxiliaire et le verbe garde le prétérit (*taught*). Dans la question 4, *who* est **complément** (Maria admire quelqu'un, le sujet est *you*) : il faut l'auxiliaire *do* devant le sujet, suivi de la base verbale."}$exo$::jsonb),
  ('0e320025-46ae-5153-bdac-f6192c2701f8'::uuid, 3, 'traduction', $exo${"titre":"Enquête au CDI","consigne":"Corrige les questions fautives, puis rédige toi-même un questionnaire en anglais selon les consignes.","enonce":"**1. Un élève a préparé ces questions pour un sondage. Corrige chacune et explique la faute.**\n\n1. *Where you do study?*\n2. *Who did write this book?*\n3. *How often you read?*\n4. *Which book do you prefers?*\n5. *How is your best friend? — He's funny and generous.*\n\n**2. Rédige un questionnaire de six questions** sur les habitudes de lecture, en anglais. Il doit contenir :\n- une question avec *how much* ou *how many* ;\n- une question avec *which* (choix limité proposé) ;\n- une question avec *how long* ;\n- une question oui/non avec un modal ;\n- une question sur le **sujet** avec *who* ;\n- une affirmation suivie d'un **question tag**.","bareme":[{"critere":"Cinq questions fautives corrigées","points":5},{"critere":"Explication juste de chaque faute","points":5},{"critere":"Six questions produites conformes aux contraintes","points":7},{"critere":"Correction de la langue (ordre, base verbale, tag)","points":3}],"dureeMin":17,"corrige":"**1.**\n1. *Where **do you** study?* — l'auxiliaire se place **devant** le sujet.\n2. *Who **wrote** this book?* — *who* est sujet : pas d'auxiliaire *did*.\n3. *How often **do you** read?* — pas d'auxiliaire dans la phrase affirmative → on fabrique *do* devant le sujet.\n4. *Which book do you **prefer**?* — le verbe lexical reste à la base ; *do* porte la personne.\n5. *What is your best friend **like**?* — la réponse décrit un caractère : *What… like?* ; *How is he?* demande comment il va.\n\n**2. Exemple de questionnaire**\n1. *How many books do you read a month?*\n2. *Which do you prefer: novels, comics or magazines?*\n3. *How long do you read every day?*\n4. *Can you read in English?* (ou *Should the library open on Saturdays?*)\n5. *Who recommends books to you?* — question sur le sujet, sans *do*.\n6. *You like reading, don't you?* — tag de polarité inversée avec *do*.\n\nToute question juste qui respecte les contraintes est acceptée."}$exo$::jsonb),
  ('db6121af-43c2-524d-90e0-90284e31d707'::uuid, 1, 'traduction', $exo${"titre":"Plus grand, plus cher, le meilleur","consigne":"Mets l'adjectif au comparatif ou au superlatif selon la consigne entre crochets.","enonce":"**Complète.**\n\n1. My brother is ___ than me. (tall) [comparatif]\n2. This phone is ___ than that one. (expensive) [comparatif]\n3. Today is ___ than yesterday. (hot) [comparatif]\n4. It's ___ film of the year. (good) [superlatif]\n5. This is ___ exercise in the book. (difficult) [superlatif]\n6. My marks are ___ than last term. (bad) [comparatif]\n7. Emma is ___ her sister. (tall) [égalité]","bareme":[{"critere":"Adjectifs courts et longs bien traités (-er / more, -est / the most)","points":8},{"critere":"Irréguliers justes (the best, worse) et doublement de consonne (hotter)","points":8},{"critere":"Égalité avec as … as","points":4}],"dureeMin":6,"corrige":"1. *taller than* — adjectif court → -er + *than*.\n2. *more expensive than* — adjectif long → *more … than*.\n3. *hotter than* — doublement de la consonne finale.\n4. *the best film* — *good* est irrégulier ; le superlatif prend toujours *the*.\n5. *the most difficult exercise* — adjectif long.\n6. *worse than* — *bad* est irrégulier.\n7. *as tall as* — égalité."}$exo$::jsonb),
  ('db6121af-43c2-524d-90e0-90284e31d707'::uuid, 2, 'traduction', $exo${"titre":"Comparer deux villes","consigne":"Compare les deux villes en anglais à partir du tableau, en six phrases.","enonce":"**Données.**\n\n| | Brighton | York |\n| Habitants | environ 280 000 | environ 200 000 |\n| Prix moyen d'un repas | 18 £ | 15 £ |\n| Jours de pluie par an | 110 | 110 |\n| Distance de Londres | 85 km | 330 km |\n| Note des touristes | 4,5 / 5 | 4,7 / 5 |\n\nÉcris **six** phrases en anglais :\n1. une comparaison de supériorité avec un adjectif **court** ;\n2. une comparaison avec un adjectif **long** ;\n3. une comparaison d'**égalité** ;\n4. une comparaison avec *far* ;\n5. une phrase avec un **superlatif** (tu peux ajouter une ville de ton choix) ;\n6. une comparaison d'**infériorité** (*not as … as* ou *less … than*).","bareme":[{"critere":"Supériorité courte et longue justes et conformes au tableau","points":6},{"critere":"Égalité et infériorité justes","points":5},{"critere":"Farther/further et superlatif avec the","points":5},{"critere":"Phrases correctes et cohérentes avec les données","points":4}],"dureeMin":11,"corrige":"**Exemples de phrases attendues**\n1. *Brighton is bigger than York.* (*bigger* : doublement du g)\n2. *A meal is more expensive in Brighton than in York.*\n3. *Brighton is as rainy as York.* (110 jours dans les deux villes)\n4. *York is farther (further) from London than Brighton.*\n5. *York is the most popular of the two… / London is the biggest city in England.* On accepte un superlatif juste avec *the*.\n6. *York is not as big as Brighton.* ou *A meal in York is less expensive than in Brighton.*\n\nFautes pénalisées : *more bigger*, *the most big*, *very bigger*, superlatif sans *the*, comparaison contraire aux données."}$exo$::jsonb),
  ('db6121af-43c2-524d-90e0-90284e31d707'::uuid, 3, 'traduction', $exo${"titre":"La publicité du nouveau téléphone","consigne":"Traduis la publicité en anglais, repère les fautes de la version d'un camarade, puis explique la structure des proportions.","enonce":"**1. Thème : traduis en anglais.**\n\n> Le nouveau Zéphyr est plus léger et beaucoup plus rapide que l'ancien modèle. Son écran est le plus lumineux du marché. Les téléphones sont de plus en plus chers, mais le Zéphyr coûte moins cher que ses rivaux. Plus vous l'utiliserez, plus vous l'aimerez !\n\n*Aide : léger = light ; lumineux = bright ; rival = rival.*\n\n**2.** Un camarade a écrit : *The new Zéphyr is more lighter and very faster than the old model. Its screen is brightest on the market.* Relève les trois fautes et corrige-les en citant la règle.\n\n**3.** Explique la construction de la dernière phrase de la publicité.","bareme":[{"critere":"Comparatifs justes : lighter, much faster, less expensive (cheaper accepté)","points":5},{"critere":"Superlatif the brightest et progression more and more expensive","points":4},{"critere":"Proportion the more … the more","points":3},{"critere":"Trois fautes du camarade corrigées et justifiées","points":6},{"critere":"Explication de la structure de proportion","points":2}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n> *The new Zéphyr is lighter and much faster than the old model. Its screen is the brightest on the market. Phones are more and more expensive, but the Zéphyr is less expensive than its rivals. The more you use it, the more you will love it!*\n\nAcceptés : *cheaper than its rivals* ; *costs less than its rivals* ; *the more you'll like it*. *Phones* : pluriel au sens général, sans article.\n\n**2.**\n- *more lighter* → *lighter* : jamais de **double marque** ; *light* est court → -er.\n- *very faster* → *much faster* : *very* ne se combine jamais avec un comparatif.\n- *is brightest* → *is **the** brightest* : le superlatif prend toujours *the*.\n\n**3.** *The more…, the more…* exprime la **proportion** : deux quantités augmentent ensemble. Chaque moitié commence par *the* + comparatif ; le verbe suit le sujet sans inversion (*the more you use it*)."}$exo$::jsonb),
  ('c9242ed0-5beb-566e-9a76-65cf0fe989e0'::uuid, 1, 'traduction', $exo${"titre":"Who, which ou whose ?","consigne":"Complète avec le pronom relatif qui convient, puis corrige l'erreur de la question 2.","enonce":"**1. Complète avec who, which, whose ou where.**\n\n1. The girl ___ won the race is my cousin.\n2. This is the book ___ I told you about.\n3. I have a friend ___ father is a pilot.\n4. That's the café ___ we met.\n5. My uncle, ___ lives in York, is a doctor.\n\n**2. Corrige :** *He said me that he was tired.*","bareme":[{"critere":"Relatifs justes dans les cinq phrases","points":14},{"critere":"Correction said / told me et règle","points":6}],"dureeMin":7,"corrige":"**1.**\n1. *who* — une personne (*that* accepté : relative déterminative).\n2. *which* — une chose (*that* ou pronom effacé acceptés : il est complément).\n3. *whose* — la possession, « dont le père ».\n4. *where* — un lieu.\n5. *who* — une personne, relative **appositive** entre virgules : *that* impossible.\n\n**2.** *He **told** me that he was tired.* ou *He **said** that he was tired.* *Tell* exige un complément de personne, *say* l'interdit : *He said me* est une faute lourde."}$exo$::jsonb),
  ('c9242ed0-5beb-566e-9a76-65cf0fe989e0'::uuid, 2, 'traduction', $exo${"titre":"Relier les idées","consigne":"Relie chaque paire de phrases en une seule, avec le mot demandé.","enonce":"**Relie les phrases avec le mot indiqué.**\n\n1. I met a woman. She speaks six languages. (*who*)\n2. Paris is a beautiful city. It attracts millions of tourists. (*which*, relative appositive)\n3. This is the student. Her project won a prize. (*whose*)\n4. He was tired. He went on working. (*although*)\n5. She spoke slowly. Everyone could understand. (*so that*)\n6. I'll wait here. You come back. (*until*)\n\n**7.** Dans quelle phrase la virgule est-elle obligatoire, et pourquoi ne peut-on pas y employer *that* ?","bareme":[{"critere":"Trois relatives justes (who, which avec virgules, whose)","points":8},{"critere":"Trois circonstancielles justes (although, so that, until + présent)","points":8},{"critere":"Explication relative appositive / that impossible","points":4}],"dureeMin":12,"corrige":"1. *I met a woman who speaks six languages.*\n2. *Paris, which attracts millions of tourists, is a beautiful city.*\n3. *This is the student whose project won a prize.*\n4. *Although he was tired, he went on working.* (ou *He went on working although he was tired.*)\n5. *She spoke slowly so that everyone could understand.* — but, avec un modal.\n6. *I'll wait here until you come back.* — présent après *until*, jamais *will come*.\n\n**7.** Phrase 2 : la relative est **appositive**, elle **ajoute** une information sur un nom déjà identifié (Paris). Elle est encadrée de virgules et *that* y est **impossible** ; il ne s'emploie que dans une relative déterminative, qui identifie le nom."}$exo$::jsonb),
  ('c9242ed0-5beb-566e-9a76-65cf0fe989e0'::uuid, 3, 'traduction', $exo${"titre":"La biographie d'une inventrice","consigne":"Traduis le texte en anglais, puis réponds aux questions d'analyse en français.","enonce":"**1. Thème : traduis en anglais.**\n\n> Hedy Lamarr, qui était une actrice célèbre, a aussi inventé un système de communication. Le système qu'elle a imaginé est utilisé aujourd'hui dans le wifi. Bien qu'elle fût connue pour ses films, peu de gens savaient qu'elle était inventrice. Elle a dit à un journaliste qu'elle trouvait les idées faciles.\n\n*Aide : inventer = to invent ; imaginer (concevoir) = to design ; peu de gens = few people.*\n\n**2.** Dans ta traduction, relève :\n- une relative appositive et une relative déterminative, en justifiant leur différence ;\n- une relative où le pronom peut s'effacer, et explique pourquoi ;\n- une complétive et une circonstancielle de concession.\n\n**3.** Pourquoi as-tu employé *told* et non *said* dans la dernière phrase ?","bareme":[{"critere":"Traduction juste des deux relatives (who… ; the system (that) she designed)","points":5},{"critere":"Concession avec although / even though et complétive avec that (ou that effacé)","points":4},{"critere":"Told a journalist (that)… correct","points":2},{"critere":"Analyse juste : appositive / déterminative, effacement du relatif complément","points":6},{"critere":"Explication say / tell","points":3}],"dureeMin":18,"corrige":"**1. Traduction modèle**\n\n> *Hedy Lamarr, who was a famous actress, also invented a communication system. The system (that) she designed is used in wifi today. Although she was known for her films, few people knew (that) she was an inventor. She told a journalist (that) she found ideas easy.*\n\n**2.**\n- ***who was a famous actress*** : relative **appositive**, entre virgules, elle **ajoute** une information sur une personne déjà identifiée ; *that* impossible. ***(that) she designed*** : relative **déterminative**, sans virgule, elle **identifie** de quel système on parle.\n- Dans *the system (that) she designed*, le pronom est **complément** (le sujet est *she*) : il peut s'effacer. Un pronom **sujet** (*who was a famous actress*) ne s'efface jamais.\n- Complétive : *(that) she was an inventor* (ou *(that) she found ideas easy*), introduite par *that*, souvent omis. Concession : *Although she was known for her films* (*even though* accepté).\n\n**3.** « Dire à quelqu'un » : il y a un complément de personne (*a journalist*). *Tell* l'exige, *say* l'interdit (*she said to a journalist* serait possible, mais *she said a journalist* est faux)."}$exo$::jsonb),
  ('d075982a-2640-5168-85bb-9f7b9e98cf49'::uuid, 1, 'traduction', $exo${"titre":"For, since, ago, during, while","consigne":"Complète chaque phrase avec for, since, ago, during ou while.","enonce":"**Complète.**\n\n1. I have lived in Nantes ___ 2021.\n2. She has been a nurse ___ fifteen years.\n3. We moved here three years ___.\n4. My phone rang ___ the film.\n5. He fell asleep ___ he was reading.\n6. Nobody spoke ___ the meeting.\n7. They have known each other ___ they were children.","bareme":[{"critere":"For / since justes (durée / point de départ)","points":9},{"critere":"Ago placé après la durée avec le prétérit","points":3},{"critere":"During devant un nom, while devant une proposition","points":8}],"dureeMin":6,"corrige":"1. *since 2021* — point de départ.\n2. *for fifteen years* — durée.\n3. *three years ago* — point du passé compté à rebours, avec le prétérit (*moved*).\n4. *during the film* — *during* + nom.\n5. *while he was reading* — *while* + sujet et verbe.\n6. *during the meeting* — nom.\n7. *since they were children* — point de départ exprimé par une proposition."}$exo$::jsonb),
  ('d075982a-2640-5168-85bb-9f7b9e98cf49'::uuid, 2, 'traduction', $exo${"titre":"La carte postale de Jade","consigne":"Traduis la carte postale en anglais en choisissant bien les mots de la temporalité et les temps.","enonce":"**Thème : traduis en anglais.**\n\n> Coucou Nathan ! Je suis en Écosse depuis dix jours. Je suis arrivée il y a dix jours et j'ai déjà visité trois châteaux. Pendant la visite d'hier, il a plu. Pendant que nous marchions, un guide nous a raconté des légendes. Je dois rendre ma voiture de location d'ici vendredi. Je rentre dans deux semaines !\n\n*Aide : château = castle ; voiture de location = rental car ; rendre = to return ; raconter = to tell.*","bareme":[{"critere":"Depuis dix jours : present perfect + for ; il y a dix jours : prétérit + ago","points":6},{"critere":"During + nom et while + proposition","points":5},{"critere":"By Friday et in two weeks","points":5},{"critere":"Autres temps et vocabulaire corrects","points":4}],"dureeMin":11,"corrige":"**Traduction modèle**\n\n> *Hi Nathan! I have been in Scotland for ten days. I arrived ten days ago and I have already visited three castles. During yesterday's visit, it rained. While we were walking, a guide told us legends. I have to return my rental car by Friday. I'm coming back in two weeks!*\n\n**Points attendus**\n- « depuis dix jours » (situation qui dure) → *have been … for ten days* ; jamais *I am in Scotland since*.\n- « il y a dix jours » → *ten days ago*, avec le **prétérit** *arrived* (jamais *I have arrived ten days ago*).\n- « pendant la visite » → *during* + nom ; « pendant que nous marchions » → *while* + proposition.\n- « d'ici vendredi » → *by Friday* (au plus tard), pas *until*.\n- « dans deux semaines » → *in two weeks*.\n\nAcceptés : *during the visit yesterday* ; *I must return* ; *I'll be back in two weeks*."}$exo$::jsonb),
  ('d075982a-2640-5168-85bb-9f7b9e98cf49'::uuid, 3, 'traduction', $exo${"titre":"La chronologie d'une association","consigne":"Lis la fiche, rédige un court paragraphe en anglais, puis corrige et explique les fautes d'un camarade.","enonce":"**Fiche : l'association « Green Street » (nous sommes en 2026)**\n\n> - Créée en 2018 par Aya et Léo.\n> - Nettoie les parcs de la ville chaque dimanche depuis sa création.\n> - A planté 500 arbres pendant l'hiver 2023.\n> - Prépare un grand festival : il doit être prêt au plus tard le 1er juin, et il durera jusqu'au 3 juin.\n\n1. Rédige un paragraphe de 60 à 80 mots en anglais sur l'association. Tu dois employer : *for*, *since*, *ago*, *during*, *while*, *by*, *until*.\n\n2. Corrige ces phrases d'un camarade et explique chaque faute :\n- *The association exists since eight years.*\n- *It was created ago eight years.*\n- *They planted trees while the winter.*","bareme":[{"critere":"For et since avec le present perfect","points":4},{"critere":"Ago après la durée avec le prétérit","points":3},{"critere":"During + nom et while + proposition justes","points":3},{"critere":"By et until employés dans leur sens (au plus tard / jusqu'à)","points":4},{"critere":"Trois phrases corrigées et fautes expliquées","points":6}],"dureeMin":17,"corrige":"**1. Exemple de paragraphe attendu**\n\n> *Green Street was created eight years ago by Aya and Léo. It has existed for eight years, and its members have cleaned the city parks every Sunday since 2018. During the winter of 2023, they planted 500 trees. While they were planting, many neighbours came to help. Now they are preparing a big festival: it must be ready by 1st June, and it will last until 3rd June.*\n\nÀ vérifier : *eight years ago* + prétérit (*was created*) ; *for eight years* et *since 2018* avec le present perfect (situation qui dure) ; *during* + nom ; *while* + proposition ; *by 1st June* = au plus tard ; *until 3rd June* = jusqu'à.\n\n**2.**\n- *The association **has existed for** eight years.* — situation qui dure encore → present perfect ; une **durée** → *for* (*since* introduit un point de départ).\n- *It was created **eight years ago**.* — *ago* se place **après** la durée.\n- *They planted trees **during** the winter.* — *winter* est un nom : il faut la préposition *during* ; *while* exige un sujet et un verbe."}$exo$::jsonb),
  ('dce5a324-c54f-52d2-b03d-21bfd1f1509b'::uuid, 1, 'traduction', $exo${"titre":"Because ou because of ?","consigne":"Complète chaque phrase avec l'expression qui convient.","enonce":"**Complète avec : because, because of, thanks to, to, for, so as not to.**\n\n1. The match was cancelled ___ the storm.\n2. I stayed at home ___ I was ill.\n3. I passed my exam ___ your help.\n4. I bought these flowers ___ my grandmother.\n5. She went to the library ___ borrow a book.\n6. He left early ___ be late.","bareme":[{"critere":"Cause : because / because of / thanks to selon ce qui suit","points":10},{"critere":"But et « pour » : for + nom, to + verbe, so as not to","points":10}],"dureeMin":6,"corrige":"1. *because of the storm* — suivi d'un **nom**.\n2. *because I was ill* — suivi d'une **proposition**.\n3. *thanks to your help* — cause positive + nom.\n4. *for my grandmother* — « pour » + nom → *for*.\n5. *to borrow a book* — « pour » + verbe → *to* (jamais *for to*).\n6. *so as not to be late* — but négatif (pas *to not be late*)."}$exo$::jsonb),
  ('dce5a324-c54f-52d2-b03d-21bfd1f1509b'::uuid, 2, 'traduction', $exo${"titre":"Pourquoi Lucas fait du bénévolat","consigne":"Traduis le texte en anglais, puis réponds à la question 2.","enonce":"**1. Thème : traduis en anglais.**\n\n> Lucas est bénévole dans une association pour aider les personnes âgées. Comme il habite près du centre, il y va à pied. Il a commencé à cause de sa grand-mère, qui vivait seule. Il parle fort pour que tout le monde puisse l'entendre. Il a reçu un prix pour son engagement.\n\n*Aide : bénévole = volunteer ; personnes âgées = elderly people ; engagement = commitment ; prix = award.*\n\n**2.** Pour chaque mot anglais qui traduit « pour » dans ta traduction, explique pourquoi tu l'as choisi.","bareme":[{"critere":"But : to help ; so that everyone can/could hear him","points":5},{"critere":"Cause : as/since he lives ; because of his grandmother","points":5},{"critere":"For + -ING ou for + nom pour la justification du prix","points":3},{"critere":"Explication des choix de « pour »","points":4},{"critere":"Vocabulaire et orthographe","points":3}],"dureeMin":12,"corrige":"**1. Traduction modèle**\n\n> *Lucas is a volunteer in an association to help elderly people. As he lives near the centre, he walks there. He started because of his grandmother, who lived alone. He speaks loudly so that everyone can hear him. He received an award for his commitment.*\n\nAcceptés : *Since he lives…* ; *in order to help* ; *so that everyone could hear him* ; *He got an award*.\n\n**2.**\n- *to help* : « pour » suivi d'un **verbe** → *to* + base verbale (but).\n- *so that everyone can hear him* : but avec un **sujet différent** (*everyone*) → *so that* + proposition, avec un modal.\n- *for his commitment* : « pour » suivi d'un **nom** → *for* ; il justifie le prix.\n- *because of his grandmother* : cause suivie d'un nom → *because of* (pas *because*).\n- *As he lives* : cause déjà connue, suivie d'une proposition."}$exo$::jsonb),
  ('dce5a324-c54f-52d2-b03d-21bfd1f1509b'::uuid, 3, 'traduction', $exo${"titre":"Défendre un projet de piste cyclable","consigne":"Rédige un court texte argumentatif en anglais, puis corrige les fautes d'un camarade en expliquant la règle.","enonce":"**1. Production (70 à 90 mots).** Le conseil municipal hésite à construire une piste cyclable devant ton lycée. Écris un message au maire pour défendre le projet. Tu dois employer :\n- deux expressions de **cause** suivies d'une proposition (*because*, *since* ou *as*) ;\n- deux expressions de **cause** suivies d'un nom (*because of*, *due to*, *thanks to*) ;\n- *to* + base verbale, *in order to* et *so that* ;\n- un but **négatif** avec *so as not to*.\n\n**2.** Corrige et explique :\n- *Many students are late because of the traffic is heavy.*\n- *We need a bike lane for to be safe.*\n- *We ride carefully to not have accidents.*","bareme":[{"critere":"Cause : proposition après because/since/as ; nom après because of/due to/thanks to","points":6},{"critere":"But : to, in order to, so that + modal, so as not to","points":6},{"critere":"Message argumenté cohérent et correct","points":2},{"critere":"Trois phrases corrigées avec la règle","points":6}],"dureeMin":18,"corrige":"**1. Exemple de message attendu**\n\n> *Dear Mayor,*\n> *We need a bike lane in front of our school because the road is dangerous. Since many students live nearby, they could cycle every day. At the moment, they take the car because of the rain or due to the lack of safe routes. A bike lane would help us to be more independent. The city could build it in order to reduce pollution, so that everyone could breathe better. Students would leave home earlier so as not to be late. Thanks to this project, our town would be greener.*\n\nÀ vérifier : *because / since* + proposition ; *because of / due to / thanks to* + nom ; *to be*, *in order to reduce*, *so that everyone could…* (modal après *so that*), *so as not to be late*.\n\n**2.**\n- *because of the traffic is heavy* → *because **the traffic is heavy*** (ou *because of the heavy traffic*) : après *because of*, un **nom**, jamais sujet + verbe.\n- *for to be safe* → ***to** be safe* : « pour » + verbe → *to* ; *for to* n'existe pas.\n- *to not have accidents* → ***so as not to** have accidents* : c'est la forme du but négatif."}$exo$::jsonb),
  ('4904efdb-38a9-5981-8637-44f8d8f00976'::uuid, 1, 'traduction', $exo${"titre":"Although ou despite ?","consigne":"Complète chaque phrase avec l'expression qui convient.","enonce":"**Complète avec : although, despite, unless, whereas, in case.**\n\n1. ___ the rain, we went for a walk.\n2. ___ it was raining, we went for a walk.\n3. You will miss the bus ___ you hurry.\n4. He likes tea, ___ his sister prefers coffee.\n5. Take a coat ___ it gets cold.\n\n**6. Corrige :** *Unless you don't study, you will fail.*","bareme":[{"critere":"Concession : despite + nom, although + proposition","points":8},{"critere":"Unless, whereas et in case bien employés","points":8},{"critere":"Correction de unless you don't (double négation)","points":4}],"dureeMin":7,"corrige":"1. ***Despite** the rain* — préposition + nom (*In spite of* accepté).\n2. ***Although** it was raining* — conjonction + proposition (*Even though* accepté).\n3. *…**unless** you hurry* — « sauf si tu te dépêches ».\n4. *…**whereas** his sister prefers coffee* — opposition entre deux faits (*while* accepté).\n5. *…**in case** it gets cold* — au cas où, suivi du présent.\n\n6. *Unless you study, you will fail.* (ou *If you don't study, you will fail.*) *Unless* contient déjà la négation : *unless you don't* ferait une double négation et dirait le contraire."}$exo$::jsonb),
  ('4904efdb-38a9-5981-8637-44f8d8f00976'::uuid, 2, 'traduction', $exo${"titre":"Le débat sur l'uniforme","consigne":"Traduis les arguments en anglais, puis nomme la relation exprimée dans chaque phrase.","enonce":"**1. Thème : traduis en anglais.**\n\n1. Bien que l'uniforme soit cher, il évite les inégalités.\n2. Malgré les critiques, le lycée l'a adopté.\n3. Les élèves de 2de l'aiment, alors que ceux de Terminale le détestent.\n4. Tu ne pourras pas entrer à moins que tu portes ta veste.\n5. Si je dirigeais le lycée, je supprimerais l'uniforme.\n\n*Aide : uniforme = uniform ; éviter = to prevent ; supprimer = to get rid of ; veste = jacket.*\n\n**2.** Pour chaque phrase, dis s'il s'agit d'une condition, d'une concession ou d'une opposition.","bareme":[{"critere":"Concession : although + proposition, despite + nom","points":6},{"critere":"Opposition avec whereas / while","points":3},{"critere":"Condition : unless sans négation ; type 2 (If I ran…, I would…)","points":6},{"critere":"Relations correctement identifiées","points":5}],"dureeMin":12,"corrige":"**1. Traduction modèle**\n1. *Although the uniform is expensive, it prevents inequalities.* (*Even though* accepté)\n2. *Despite the criticism, the school adopted it.* (*In spite of* accepté)\n3. *Students in 2de like it, whereas those in Terminale hate it.* (*while* accepté ; *Year 11 / Year 13* acceptés)\n4. *You won't be able to come in unless you wear your jacket.* (*You can't come in unless…* accepté)\n5. *If I ran the school, I would get rid of the uniform.* — type 2, *if* + prétérit, *would* dans la principale.\n\n**2.**\n1. Concession (obstacle reconnu sans changer d'avis).\n2. Concession.\n3. Opposition (deux faits mis en regard, sans obstacle).\n4. Condition (*unless* = sauf si).\n5. Condition, irréel du présent."}$exo$::jsonb),
  ('4904efdb-38a9-5981-8637-44f8d8f00976'::uuid, 3, 'traduction', $exo${"titre":"Pour ou contre les écrans au collège ?","consigne":"Rédige un paragraphe argumenté en anglais, puis corrige les fautes d'un camarade en expliquant la règle.","enonce":"**1. Production (80 à 100 mots).** Donne ton avis sur l'usage des tablettes en classe. Tu dois employer :\n- une **concession** avec une conjonction et une autre avec une préposition suivie d'un -ING ;\n- une **opposition** avec *whereas* et un connecteur entre deux phrases (*however* ou *on the other hand*) ;\n- une **condition** avec *unless* et une autre avec *provided that* ou *as long as* ;\n- une hypothèse **irréelle** (type 2 ou type 3).\n\n**2.** Corrige et explique :\n- *Despite tablets are useful, they distract students.*\n- *Although the cost, schools buy them.*\n- *If teachers would allow phones, students would be happier.*","bareme":[{"critere":"Deux concessions justes (conjonction + proposition ; préposition + -ING)","points":4},{"critere":"Opposition : whereas et however / on the other hand bien employés","points":4},{"critere":"Conditions : unless sans négation, provided that / as long as, irréel correct","points":5},{"critere":"Trois fautes corrigées et règle expliquée","points":6},{"critere":"Paragraphe cohérent","points":1}],"dureeMin":20,"corrige":"**1. Exemple de paragraphe attendu**\n\n> *Although tablets are expensive, I think they are useful in class. In spite of being distracting sometimes, they help students find information quickly. Some students love them, whereas others prefer paper. However, screens can hurt our eyes. Students won't learn well unless teachers control their use. Tablets are a good tool as long as we use them for short periods. If our school had more tablets, we would work in groups more easily.*\n\nÀ vérifier : *although* + proposition ; *in spite of being* (préposition + -ING) ; *whereas* entre deux faits ; *however* en début de phrase ; *unless* sans négation ; *as long as / provided that* + présent ; type 2 (*if* + prétérit, *would*) ou type 3 (*if* + past perfect, *would have* + participe).\n\n**2.**\n- *Despite tablets are useful* → ***Although** tablets are useful* (ou *Despite **being** useful*, *Despite their usefulness*) : *despite* est une **préposition**, suivie d'un nom ou d'un -ING, jamais d'une proposition.\n- *Although the cost* → ***Despite** the cost* (ou *Although it is expensive*) : *although* est une **conjonction**, il lui faut une proposition complète.\n- *If teachers would allow* → *If teachers **allowed** phones, students would be happier* : la subordonnée en *if* ne prend jamais *would* ; au type 2, elle est au **prétérit**."}$exo$::jsonb),
  ('c59a6cdd-4f82-5f4e-9647-55e5c333c8f9'::uuid, 1, 'traduction', $exo${"titre":"What ou how ?","consigne":"Complète chaque exclamation avec what, what a / an ou how.","enonce":"**Complète avec what, what a, what an ou how.**\n\n1. … beautiful day!\n2. … terrible weather!\n3. … strange!\n4. … fast he runs!\n5. … interesting idea!\n6. … nice people!\n7. … pity!\n\n**8.** Rappelle en français la règle qui permet de choisir entre *what* et *how*.","bareme":[{"critere":"Les sept exclamations justes (dont article a / an et absence d'article)","points":14},{"critere":"Règle : what + nom, how + adjectif ou adverbe","points":6}],"dureeMin":6,"corrige":"1. ***What a** beautiful day!* (nom singulier dénombrable : *a*)\n2. ***What** terrible weather!* (indénombrable : sans article)\n3. ***How** strange!* (adjectif)\n4. ***How** fast he runs!* (adverbe)\n5. ***What an** interesting idea!* (*an* devant une voyelle)\n6. ***What** nice people!* (pluriel : sans article)\n7. ***What a** pity!*\n\n8. ***What*** est suivi d'un **nom** (groupe nominal) ; ***how*** est suivi d'un **adjectif** ou d'un **adverbe**."}$exo$::jsonb),
  ('c59a6cdd-4f82-5f4e-9647-55e5c333c8f9'::uuid, 2, 'traduction', $exo${"titre":"So, such et l'ordre des mots","consigne":"Transforme les phrases selon les consignes, puis traduis les exclamations en anglais.","enonce":"**A. Transforme avec so, such ou such a.**\n\n1. She is very kind. → She is …\n2. It was a very good film. → It was …\n3. They are very nice people. → They are …\n\n**B. Corrige l'ordre des mots.**\n\n4. How beautiful is this place!\n5. How is it expensive!\n\n**C. Traduis en anglais.**\n\n6. Quel dommage !\n7. Comme ta sœur chante bien !\n8. Quelle belle maison !","bareme":[{"critere":"Transformations justes avec so, such a, such","points":6},{"critere":"Deux phrases corrigées sans inversion","points":6},{"critere":"Trois traductions justes","points":8}],"dureeMin":10,"corrige":"**A.**\n1. *She is **so** kind!* (*so* + adjectif)\n2. *It was **such a** good film!* (*such a* + adjectif + nom singulier)\n3. *They are **such** nice people!* (*such* + adjectif + nom pluriel)\n\n**B.** L'anglais ne fait **pas d'inversion** dans l'exclamation : le sujet reste devant le verbe.\n4. *How beautiful **this place is**!*\n5. *How expensive **it is**!*\n\n**C.**\n6. ***What a pity!*** (ou *What a shame!*)\n7. ***How well** your sister sings!* (adverbe → *how*, sans inversion)\n8. ***What a beautiful house!***"}$exo$::jsonb),
  ('c59a6cdd-4f82-5f4e-9647-55e5c333c8f9'::uuid, 3, 'traduction', $exo${"titre":"Carte postale d'Édimbourg","consigne":"Corrige le texte, puis rédige ta propre carte postale en anglais selon les contraintes.","enonce":"**A.** Ce message contient **cinq** erreurs sur l'exclamation. Recopie les phrases fautives corrigées et explique chaque correction en français.\n\n> Dear Grandma,\n> We are in Edinburgh! How a beautiful city! What old the castle is! Yesterday it rained all day: what a terrible weather! The people are so nice people. How is delicious the food here!\n> Love, Zoé\n\n**B. Production.** Écris une carte postale de 6 à 8 phrases racontant un voyage. Tu dois employer : *what a* + nom singulier, *what* + nom pluriel ou indénombrable, *how* + adjectif + sujet + verbe, *such a*, *so*, et une exclamation toute faite (*No way!*, *Well done!*, *How come?*…).","bareme":[{"critere":"Les cinq erreurs corrigées","points":7},{"critere":"Règle expliquée pour chaque correction","points":3},{"critere":"Les six structures imposées présentes et correctes","points":7},{"critere":"Carte postale cohérente et correcte","points":3}],"dureeMin":17,"corrige":"**A.**\n1. ***What a** beautiful city!* — devant un nom (*city*), c'est *what (a)*, pas *how*.\n2. ***How old** the castle is!* — devant un adjectif seul, c'est *how*.\n3. *What terrible weather!* — *weather* est **indénombrable** : **pas d'article**.\n4. *The people are **so nice**!* ou *They are **such nice people**!* — *so* + adjectif, *such* + adjectif + nom.\n5. *How delicious **the food is** here!* — **pas d'inversion** : sujet puis verbe.\n\n**B. Exemple attendu :**\n*Dear Tom,*\n*We're in Cornwall. **What a** lovely place! **What** beautiful beaches! **How** blue the sea is! We had **such a** good time at the surf school. I was **so** tired after the lesson. I stood up on the board: **Well done!** said the teacher.*\n\nLe correcteur vérifie : article *a* devant un singulier, pas d'article devant un pluriel ou un indénombrable, pas d'inversion après *how*, *such a* devant un nom singulier, *so* devant un adjectif seul."}$exo$::jsonb),
  ('e87d7228-c129-5637-8fb0-61e8eddebe0f'::uuid, 1, 'traduction', $exo${"titre":"Former le passif","consigne":"Mets chaque phrase à la voix passive en gardant le même temps.","enonce":"**Mets à la voix passive.** Garde le complément d'agent (*by…*) seulement quand il est utile.\n\n1. They build houses. *(présent)*\n2. Shakespeare wrote Hamlet. *(prétérit)*\n3. They have repaired the car. *(present perfect)*\n4. They will open the new pool next year. *(futur)*\n5. You can recycle this bottle. *(modal)*\n\n**6.** Rappelle en français comment se forme la voix passive.","bareme":[{"critere":"Les cinq phrases passives justes, au bon temps","points":15},{"critere":"Formation : be au temps voulu + participe passé, complément devenu sujet, by","points":5}],"dureeMin":7,"corrige":"1. *Houses **are built**.*\n2. *Hamlet **was written by** Shakespeare.* (l'auteur est intéressant : on garde *by*)\n3. *The car **has been repaired**.*\n4. *The new pool **will be opened** next year.*\n5. *This bottle **can be recycled**.*\n\n6. Voix passive : **be** conjugué au **temps** de la phrase active + **participe passé**. Le **complément d'objet** de l'actif devient **sujet** ; l'ancien sujet, si on le garde, est introduit par ***by***."}$exo$::jsonb),
  ('e87d7228-c129-5637-8fb0-61e8eddebe0f'::uuid, 2, 'traduction', $exo${"titre":"Un article de journal","consigne":"Transforme les phrases de l'article à la voix passive, puis justifie l'emploi du passif.","enonce":"**Article.**\n\n> Last night, someone stole a famous painting from the city museum. The police have arrested two men. Experts are examining the frame. The museum will reopen the gallery on Monday.\n\n1. Réécris les **quatre** phrases à la voix passive, sans complément d'agent quand l'auteur est inconnu ou évident.\n2. Pourquoi le passif est-il fréquent dans les articles de journaux ? Donne deux raisons en français.\n3. Traduis : « On m'a donné un prix. » Donne les deux passifs possibles et indique le plus courant.","bareme":[{"critere":"Quatre phrases passives justes, au bon temps","points":10},{"critere":"Complément d'agent omis quand il est inconnu ou évident","points":3},{"critere":"Deux raisons de l'emploi du passif","points":3},{"critere":"Double passif : I was given a prize (le plus courant) et A prize was given to me","points":4}],"dureeMin":11,"corrige":"1.\n- *Last night, a famous painting **was stolen** from the city museum.* (auteur inconnu : pas de *by someone*)\n- *Two men **have been arrested**.* (*by the police* est évident, on peut l'omettre)\n- *The frame **is being examined** by experts.* (présent en BE + -ING → *is being* + participe passé ; *by experts* accepté ou omis)\n- *The gallery **will be reopened** on Monday.*\n\n2. Le passif permet de **mettre en avant ce qui a été fait** plutôt que qui l'a fait ; l'auteur est souvent **inconnu** (le voleur) ou **évident** (la police). C'est pourquoi le complément d'agent est omis dans la grande majorité des phrases passives.\n\n3. ***I was given a prize.*** (le plus courant) ou ***A prize was given to me.***"}$exo$::jsonb),
  ('e87d7228-c129-5637-8fb0-61e8eddebe0f'::uuid, 3, 'traduction', $exo${"titre":"La construction du pont","consigne":"Corrige les erreurs, puis rédige un court texte informatif en anglais en employant le passif selon les contraintes.","enonce":"**A.** Chaque phrase contient une erreur sur le passif. Corrige-la et explique en français.\n\n1. The window broken by the storm.\n2. The bridge was build in 1894.\n3. English is speak in many countries.\n4. The letter has sent yesterday.\n\n**B. Production.** Rédige un texte informatif de 6 à 8 phrases sur un monument (réel ou inventé). Tu dois employer le passif à **quatre temps différents** (présent, prétérit, present perfect, futur ou modal), au moins un complément d'agent avec *by* justifié, et au moins un passif **sans** complément d'agent.\n\n**C.** Explique en français pourquoi tu as gardé *by* dans une phrase et pas dans une autre.","bareme":[{"critere":"Les quatre erreurs corrigées et expliquées","points":6},{"critere":"Passif à quatre temps différents, correctement formé","points":7},{"critere":"Usage justifié du complément d'agent (C)","points":4},{"critere":"Texte cohérent et correct","points":3}],"dureeMin":18,"corrige":"**A.**\n1. *The window **was** broken by the storm.* — il manque **be** : sans lui, pas de verbe conjugué.\n2. *The bridge was **built** in 1894.* — il faut le **participe passé** (*built*), pas la base verbale.\n3. *English is **spoken** in many countries.* — participe passé de *speak* : *spoken*.\n4. *The letter **was sent** yesterday.* — avec *yesterday* (moment passé précis), le **prétérit** : *was sent* ; et le passif demande *be* (*has been sent* serait incompatible avec *yesterday*).\n\n**B. Exemple attendu :**\n*Tower Bridge **was built** between 1886 and 1894. It **was designed by** Horace Jones. Today, it **is crossed** by thousands of cars every day. The bridge **has been painted** blue and white. It **can be visited** all year round. A new exhibition **will be opened** next spring.*\n\n**C.** On garde *by* quand l'auteur est **intéressant** ou nouveau (l'architecte) ; on l'omet quand il est **inconnu, évident ou sans intérêt** (ceux qui ont peint le pont) : s'il était important, on aurait gardé l'actif."}$exo$::jsonb),
  ('bbe3d420-29e9-59c1-bac8-7036d3acec5c'::uuid, 1, 'traduction', $exo${"titre":"Used to ou be used to ?","consigne":"Complète chaque phrase avec la bonne forme, puis traduis-la en français.","enonce":"**Complète avec used to, am / is used to ou is getting used to, et mets le verbe à la bonne forme.**\n\n1. When I was a child, I … (play) with dolls. *(ce n'est plus le cas)*\n2. I … (get up) early: I do it every day, it's easy for me.\n3. She has just moved to Canada. She … (live) in the cold.\n4. My grandfather … (smoke), but he stopped ten years ago.\n\n**5.** Explique en français la différence de forme du verbe après *used to* et après *be used to*.","bareme":[{"critere":"Les quatre formes justes","points":10},{"critere":"Traductions françaises justes","points":4},{"critere":"Règle : used to + base verbale, be used to + -ING","points":6}],"dureeMin":7,"corrige":"1. *I **used to play** with dolls.* — « Je jouais à la poupée (autrefois). »\n2. *I **am used to getting up** early.* — « J'ai l'habitude de me lever tôt. »\n3. *She **is getting used to living** in the cold.* — « Elle s'habitue à vivre dans le froid. »\n4. *My grandfather **used to smoke**.* — « Mon grand-père fumait (autrefois). »\n\n5. Après ***used to*** (habitude passée révolue) : **base verbale**. Après ***be / get used to*** (être habitué, s'habituer) : verbe en **-ING** ou nom."}$exo$::jsonb),
  ('bbe3d420-29e9-59c1-bac8-7036d3acec5c'::uuid, 2, 'traduction', $exo${"titre":"La vie d'avant de Grandpa Joe","consigne":"Exploite le document pour écrire des phrases avec used to, would et le présent simple.","enonce":"**Document – Grandpa Joe, 80 ans, raconte**\n\n| Autrefois | Aujourd'hui |\n|---|---|\n| went to school on foot | takes the bus to town |\n| was very shy | is very talkative |\n| every Sunday, went fishing with his father | watches football on TV |\n| didn't have a phone | calls his grandchildren every day |\n\n1. Écris **quatre** phrases sur la vie d'autrefois de Joe avec *used to* (dont une à la forme **négative**).\n2. Réécris la phrase sur la pêche avec *would*. Peut-on faire de même pour « was very shy » ? Justifie.\n3. Écris deux phrases sur sa vie d'aujourd'hui avec un adverbe de fréquence bien placé.\n4. Pose une question à Joe avec *used to*.","bareme":[{"critere":"Quatre phrases avec used to justes, dont la négative didn't use to","points":8},{"critere":"Would pour l'action répétée, impossible pour un état, justifié","points":5},{"critere":"Deux phrases au présent simple avec adverbe bien placé","points":4},{"critere":"Question Did you use to… ?","points":3}],"dureeMin":11,"corrige":"1. Exemples attendus :\n- *Joe **used to go** to school on foot.*\n- *He **used to be** very shy.*\n- *He **used to go** fishing with his father every Sunday.*\n- *He **didn't use to have** a phone.* (sans *-d* après *did*)\n\n2. *Every Sunday, he **would go** fishing with his father.* — *would* convient pour une **action répétée**. Pour « was very shy », **non** : c'est un **état** ; seul *used to* convient (*He used to be shy*, jamais *he would be shy*).\n\n3. Exemples : *He **usually takes** the bus to town.* / *He **always calls** his grandchildren.* / *He **is often** very talkative.* — l'adverbe se place **avant** le verbe lexical, **après** *be*.\n\n4. ***Did** you **use to** play football, Grandpa?*"}$exo$::jsonb),
  ('bbe3d420-29e9-59c1-bac8-7036d3acec5c'::uuid, 3, 'traduction', $exo${"titre":"Une nouvelle vie à Toronto","consigne":"Corrige les erreurs, puis rédige un texte en anglais qui oppose passé, présent et adaptation.","enonce":"**A.** Corrige chaque phrase et explique la règle en français.\n\n1. I am used to swim every morning.\n2. I didn't used to like vegetables.\n3. When I was young, I would be very shy.\n4. She is getting used to speak English.\n\n**B. Production.** Nadia vient de quitter Lyon pour Toronto. Rédige son journal intime (8 à 10 phrases) : ce qu'elle faisait autrefois, ce qu'elle fait maintenant, ce à quoi elle est déjà habituée et ce à quoi elle s'habitue peu à peu. Tu dois employer : *used to* (affirmatif et négatif), *would*, *be used to*, *get used to*, et le présent simple avec deux adverbes de fréquence.","bareme":[{"critere":"Les quatre erreurs corrigées et expliquées","points":6},{"critere":"Used to affirmatif et négatif, would pour une action répétée","points":5},{"critere":"Be used to et get used to suivis de -ING ou d'un nom","points":5},{"critere":"Présent simple et adverbes bien placés, texte cohérent","points":4}],"dureeMin":18,"corrige":"**A.**\n1. *I am used to **swimming** every morning.* — après *be used to* : **-ING**.\n2. *I didn't **use** to like vegetables.* — après *did*, pas de *-d* : *didn't use to*.\n3. *When I was young, I **used to be** very shy.* — *shy* est un **état** : *would* est impossible.\n4. *She is getting used to **speaking** English.* — après *get used to* : **-ING**.\n\n**B. Exemple attendu :**\n*In Lyon, I **used to walk** to school with my friends. Every Friday, we **would eat** crêpes together. I **didn't use to wear** a hat! Now I **always wear** one, because it's minus ten. I **usually take** the subway. I **am** already **used to speaking** English at school. But I **am** still **getting used to** the snow and to having dinner at six.*\n\nLe correcteur vérifie : base verbale après *used to*, *didn't use to*, *would* seulement pour une action, **-ING** ou nom après *be / get used to*, adverbes avant le verbe lexical."}$exo$::jsonb),
  ('77faf9c0-1cad-58eb-9a66-20e3382b35fa'::uuid, 1, 'traduction', $exo${"titre":"Rapporter des paroles","consigne":"Mets chaque phrase au discours indirect après « He said » ou « She said ».","enonce":"**Mets au discours indirect.**\n\n1. « I am tired. » → He said …\n2. « I saw her. » → He said …\n3. « I will call you. » → She said …\n4. « I can swim. » → He said …\n5. « I have finished. » → She said …\n\n**6.** Explique en français ce qu'est le **recul des temps** et quand il ne s'applique pas.","bareme":[{"critere":"Les cinq phrases justes (temps reculé, pronoms adaptés)","points":15},{"critere":"Recul des temps défini, avec ses exceptions (verbe introducteur au présent, vérité générale)","points":5}],"dureeMin":7,"corrige":"1. *He said (that) he **was** tired.* (présent → prétérit)\n2. *He said (that) he **had seen** her.* (prétérit → past perfect)\n3. *She said (that) she **would** call me.* (*will* → *would* ; *you* → *me*)\n4. *He said (that) he **could** swim.* (*can* → *could*)\n5. *She said (that) she **had finished**.* (present perfect → past perfect)\n\n6. Quand le verbe introducteur est au **passé** (*said, told*), chaque temps **recule d'un cran**. Le recul ne s'applique **pas** quand le verbe introducteur est au **présent** (*He says he is tired*), ni quand le fait rapporté est **toujours vrai**."}$exo$::jsonb),
  ('77faf9c0-1cad-58eb-9a66-20e3382b35fa'::uuid, 2, 'traduction', $exo${"titre":"Ce que le prof a dit","consigne":"Rapporte les paroles au discours indirect en adaptant temps, pronoms et repères.","enonce":"**Situation.** Hier, Mrs Cole a parlé à la classe. Aujourd'hui, Lucas raconte ce qu'elle a dit à Jade, qui était absente.\n\n1. « The test is tomorrow. »\n2. « I corrected your essays yesterday. »\n3. « Are you ready? »\n4. « Where do you usually revise? »\n5. « Close your books. »\n6. « Don't be late. »\n\nCommence chaque phrase par *She said*, *She told us* ou *She asked us*. Choisis bien entre *say* et *tell*.","bareme":[{"critere":"Phrases 1 et 2 : temps reculés et repères adaptés (the next day, the day before)","points":6},{"critere":"Questions 3 et 4 : if, ordre de l'affirmative","points":6},{"critere":"Ordres 5 et 6 : told us to / not to + base verbale","points":5},{"critere":"say et tell bien employés, pronoms adaptés","points":3}],"dureeMin":11,"corrige":"1. *She said (that) the test **was the next day**.* (*is* → *was* ; *tomorrow* → *the next day*)\n2. *She told us (that) she **had corrected our** essays **the day before**.* (prétérit → past perfect ; *your* → *our* ; *yesterday* → *the day before*)\n3. *She asked us **if / whether we were** ready.* (question fermée : *if / whether*, ordre de l'affirmative)\n4. *She asked us **where we usually revised**.* (question ouverte : pas de *do*, ordre de l'affirmative)\n5. *She told us **to close** our books.*\n6. *She told us **not to be** late.*\n\n***Say*** ne prend pas de complément de personne (*She said…*) ; ***tell*** en exige un (*She told **us**…*)."}$exo$::jsonb),
  ('77faf9c0-1cad-58eb-9a66-20e3382b35fa'::uuid, 3, 'traduction', $exo${"titre":"Le témoin de l'accident","consigne":"Corrige les erreurs, puis réécris un dialogue entier au discours indirect.","enonce":"**A.** Corrige chaque phrase et explique la règle en français.\n\n1. He said me that he was tired.\n2. She asked me where did I live.\n3. He told that he would come.\n4. She asked me are you ready.\n\n**B. Dialogue.** Un policier interroge Ryan, témoin d'un accident.\n\n> **Policeman**: Where were you at 5 pm?\n> **Ryan**: I was waiting for the bus here.\n> **Policeman**: Did you see the car?\n> **Ryan**: Yes, it was going very fast. I have never seen that car before.\n> **Policeman**: Can you describe the driver?\n> **Ryan**: He was wearing a red cap. I will help you if I can.\n> **Policeman**: Don't leave the town.\n\nRéécris tout le dialogue au **discours indirect** dans un récit au passé (*The policeman asked Ryan…*, *Ryan said…*).","bareme":[{"critere":"Les quatre erreurs corrigées et expliquées","points":6},{"critere":"Recul des temps juste dans tout le dialogue","points":6},{"critere":"Questions rapportées (if, mot interrogatif, ordre affirmatif) et ordre rapporté","points":5},{"critere":"Pronoms, repères (here → there) et say / tell corrects","points":3}],"dureeMin":18,"corrige":"**A.**\n1. *He **told me** / He **said** that he was tired.* — *say* ne prend pas de complément de personne.\n2. *She asked me where **I lived**.* — la question rapportée reprend l'**ordre de l'affirmative**, sans *did*.\n3. *He **said** that he would come.* — *tell* exige un complément de personne (*He told me…*).\n4. *She asked me **if I was** ready.* — question fermée : *if / whether*, ordre affirmatif, temps reculé.\n\n**B. Réponse attendue :**\n*The policeman asked Ryan **where he had been** at 5 pm. Ryan said (that) **he had been waiting** for the bus **there**. The policeman asked him **if / whether he had seen** the car. Ryan said that **it had been going** very fast and that **he had never seen** that car before. The policeman asked him **if he could** describe the driver. Ryan said that the driver **had been wearing** a red cap and that **he would help** him if **he could**. Finally, the policeman **told him not to leave** the town.*\n\nLe correcteur vérifie : prétérit → past perfect (*were* → *had been*, *saw* → *had seen*), present perfect → past perfect, *will* → *would*, *can* → *could* ; *here* → *there* ; questions sans inversion ; ordre avec *told him not to*. Tolérer *he was waiting* / *it was going* (prétérit en BE + -ING non reculé), fréquent à l'oral, mais valoriser le past perfect."}$exo$::jsonb),
  ('706e2b7f-a77a-5f4a-a2d6-dd94a189c7ff'::uuid, 1, 'traduction', $exo${"titre":"Some, any, much, many","consigne":"Complète chaque phrase avec le quantifieur qui convient, puis réponds à la question 2.","enonce":"**1. Complète avec some, any, much ou many.**\n\n1. I have ___ money in my pocket.\n2. We don't have ___ bread.\n3. How ___ books have you got?\n4. How ___ water do you drink a day?\n5. Would you like ___ tea?\n6. Is there ___ milk in the fridge?\n\n**2.** Explique la différence de sens entre *I have a few friends* et *I have few friends*.","bareme":[{"critere":"Six quantifieurs justes","points":12},{"critere":"Différence a few (assez, rassurant) / few (trop peu) expliquée","points":8}],"dureeMin":7,"corrige":"**1. Réponses**\n1. **some** money — affirmative.\n2. **any** bread — négative.\n3. How **many** books — dénombrable pluriel.\n4. How **much** water — indénombrable.\n5. Would you like **some** tea? — offre polie : *some* même dans une question.\n6. Is there **any** milk — interrogative.\n\n**2. A few / few**\n*I have a few friends* : j'ai quelques amis, un nombre **suffisant** — le sens est positif, il rassure.\n*I have few friends* : j'ai **peu** d'amis, trop peu — le sens est négatif, il inquiète. L'article *a* change le sens."}$exo$::jsonb),
  ('706e2b7f-a77a-5f4a-a2d6-dd94a189c7ff'::uuid, 2, 'traduction', $exo${"titre":"La fête de Yanis","consigne":"Complète le dialogue, puis justifie trois de tes choix.","enonce":"> **Yanis**: I'm organising a party. Have we got (1) ___ crisps?\n> **Mum**: No, we haven't got (2) ___ crisps, but we've got (3) ___ lemonade.\n> **Yanis**: How (4) ___ bottles?\n> **Mum**: Only two. That's not (5) ___ for twenty people!\n> **Yanis**: And how (6) ___ cake is left?\n> **Mum**: Just (7) ___ cake, but we've got (8) ___ biscuits.\n\n*Mots possibles : any, some, many, much, enough, a little, a lot of.*\n\n1. Complète les huit blancs.\n2. Justifie tes choix pour les blancs 2, 4 et 6.","bareme":[{"critere":"Huit blancs corrects","points":10},{"critere":"Justifications : forme de la phrase (négative / interrogative)","points":4},{"critere":"Justifications : dénombrable / indénombrable (many / much)","points":4},{"critere":"Clarté des explications","points":2}],"dureeMin":10,"corrige":"**1. Réponses**\n(1) **any** — question.\n(2) **any** — négative.\n(3) **some** — affirmative.\n(4) How **many** bottles — dénombrable pluriel.\n(5) not **enough** — pas assez.\n(6) How **much** cake — *cake* est ici indénombrable (de la matière).\n(7) **a little** cake — un peu de, indénombrable.\n(8) **a lot of** biscuits (ou *some*) — affirmative, dénombrable.\n\n**2. Justifications**\n- Blanc 2 : la phrase est **négative** (*haven't got*) → *any*.\n- Blanc 4 : *bottles* est **dénombrable** pluriel → *how many*.\n- Blanc 6 : *cake* au singulier, sans article, désigne une quantité de gâteau : **indénombrable** → *how much*.\n\nAccepter (8) *some* ; refuser *much biscuits* ou *many cake*."}$exo$::jsonb),
  ('706e2b7f-a77a-5f4a-a2d6-dd94a189c7ff'::uuid, 3, 'traduction', $exo${"titre":"Le camp de vacances","consigne":"Traduis les six phrases en anglais, puis réponds à la question 2 en justifiant.","enonce":"**1. Thème : traduis en anglais.**\n\n1. Il n'y a pas de lait dans le frigo.\n2. Tu veux du jus d'orange ?\n3. Prends n'importe quel livre.\n4. Nous avons trop de devoirs et pas assez de temps.\n5. Peu d'élèves sont venus : c'était triste.\n6. J'ai quelques amis au camp, alors je suis content.\n\n*Aide : came = sont venus ; at the camp = au camp.*\n\n**2.** Les phrases 5 et 6 parlent toutes deux d'une petite quantité. Explique en quoi leur sens diffère, et comment l'anglais le marque.","bareme":[{"critere":"No / any, some pour l'offre, any au sens de n'importe quel","points":6},{"critere":"Too much / enough avec les bons noms (homework indénombrable)","points":4},{"critere":"Few / a few correctement choisis","points":4},{"critere":"Explication de la nuance few / a few","points":4},{"critere":"Correction de la langue","points":2}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n1. *There is no milk in the fridge.* (ou *There isn't any milk…*)\n2. *Would you like some orange juice?* — offre polie : *some*.\n3. *Take any book (you like).* — *any* en affirmative = n'importe quel.\n4. *We have too much homework and not enough time.* — *homework* est indénombrable → *too much* (pas *too many homeworks*) ; *enough* devant le nom.\n5. *Few students came: it was sad.* (*pupils* accepté)\n6. *I have a few friends at the camp, so I'm happy.*\n\n**2. La nuance**\nLes deux phrases parlent d'un petit nombre (*students*, *friends* sont dénombrables), mais :\n- *few* (sans article) = **trop peu**, sens négatif : on le regrette (« c'était triste ») ;\n- *a few* = **quelques-uns, assez**, sens positif : on s'en contente (« je suis content »).\nL'anglais marque cette différence par la seule présence de l'article *a*. Pour un indénombrable, on aurait *little* / *a little*."}$exo$::jsonb),
  ('b97527d9-a761-5713-9314-ac7f02dab68f'::uuid, 1, 'traduction', $exo${"titre":"Bored ou boring ?","consigne":"Choisis la bonne forme de l'adjectif, puis traduis les deux groupes.","enonce":"**1. Entoure la bonne forme et recopie la phrase.**\n\n1. The film was very (bored / boring).\n2. I am (interested / interesting) in history.\n3. After the match, the players were (tired / tiring).\n4. The news was (surprised / surprising).\n5. The children were (frightened / frightening) by the storm.\n6. This book is really (interested / interesting).\n\n**2. Traduis :** une voiture rouge — deux voitures rouges.","bareme":[{"critere":"Six choix -ed / -ing justes","points":14},{"critere":"Traduction avec adjectif invariable placé avant le nom","points":6}],"dureeMin":6,"corrige":"**1. Réponses**\n1. The film was very **boring**. — le film provoque l'ennui.\n2. I am **interested** in history. — ce que je ressens.\n3. The players were **tired**. — ce qu'ils ressentent.\n4. The news was **surprising**. — la nouvelle provoque la surprise.\n5. The children were **frightened**. — ce qu'ils ressentent.\n6. This book is really **interesting**. — le livre provoque l'intérêt.\n\nRègle : **-ed** = ce que ressent la personne ; **-ing** = ce qui provoque le sentiment.\n\n**2. Traduction**\n*a red car* — *two red cars*. L'adjectif se place **avant** le nom et reste **invariable** : jamais *reds*."}$exo$::jsonb),
  ('b97527d9-a761-5713-9314-ac7f02dab68f'::uuid, 2, 'traduction', $exo${"titre":"La brocante de Léon","consigne":"Remets les adjectifs dans l'ordre, puis traduis les groupes avec un adjectif composé.","enonce":"Léon vend des objets à une brocante. Aide-le à écrire ses étiquettes.\n\n**1. Remets les adjectifs dans le bon ordre.**\n\na. a (wooden / small / old) box\nb. a (French / beautiful / blue) vase\nc. (leather / black / big) boots\n\n**2. Traduis en anglais.**\n\na. une fille de dix ans\nb. un film de deux heures\nc. un trajet de trois kilomètres\n\n**3.** Complète : *Léon seems ___ (happy / happily).* Explique ton choix.","bareme":[{"critere":"Ordre des adjectifs juste dans les trois groupes","points":9},{"critere":"Adjectifs composés avec trait d'union et nom au singulier","points":7},{"critere":"Adjectif après le verbe d'état seem, choix expliqué","points":4}],"dureeMin":10,"corrige":"**1. Ordre** (opinion → taille → âge → forme → couleur → origine → matière)\na. *a small old wooden box* — taille, âge, matière.\nb. *a beautiful blue French vase* — opinion, couleur, origine.\nc. *big black leather boots* — taille, couleur, matière.\n\n**2. Adjectifs composés**\na. *a ten-year-old girl*\nb. *a two-hour film*\nc. *a three-kilometre journey* (ou *trip* ; *kilometer* accepté)\nTrait d'union, et le nom reste au **singulier** : jamais *ten-years-old* ni *two-hours*.\n\n**3.** *Léon seems **happy**.* — *seem* est un verbe d'état (comme be, look, feel) : il est suivi d'un **adjectif**, pas d'un adverbe."}$exo$::jsonb),
  ('b97527d9-a761-5713-9314-ac7f02dab68f'::uuid, 3, 'traduction', $exo${"titre":"Une journée au musée","consigne":"Traduis le texte en anglais, puis justifie trois choix grammaticaux.","enonce":"**1. Thème : traduis en anglais.**\n\n> Hier, notre classe a visité un grand musée moderne. Le guide était intéressant, mais la visite de trois heures était fatigante. À la fin, nous étions fatigués. Dans une salle, il y avait une jolie petite table ronde en bois. Le musée aide les pauvres : l'entrée est gratuite pour eux.\n\n*Aide : visited = a visité ; room = salle ; free = gratuit ; entry = l'entrée ; to help = aider.*\n\n**2.** Justifie en une phrase chacun :\na) *interesting* / *tiring* / *tired* ;\nb) l'ordre des adjectifs devant *table* ;\nc) le verbe employé avec *the poor*.","bareme":[{"critere":"Adjectifs placés avant le nom, invariables, bon ordre","points":5},{"critere":"Choix -ed / -ing justes","points":4},{"critere":"Adjectif composé three-hour et adjectif substantivé the poor avec verbe au pluriel","points":4},{"critere":"Trois justifications exactes","points":5},{"critere":"Correction générale de la langue","points":2}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n> *Yesterday, our class visited a big modern museum. The guide was interesting, but the three-hour visit was tiring. At the end, we were tired. In one room, there was a lovely little round wooden table. The museum helps the poor: entry is free for them.*\n(*nice* ou *pretty little round wooden table* acceptés ; *large* accepté.)\n\n**2. Justifications**\na) *interesting* et *tiring* décrivent ce qui **provoque** le sentiment (le guide, la visite) → **-ing** ; *tired* décrit ce que **ressentent** les élèves → **-ed**. *We were tiring* voudrait dire « nous étions fatigants ».\nb) Ordre : opinion (*lovely*) → taille (*little*) → forme (*round*) → matière (*wooden*).\nc) *the poor* désigne un **groupe entier** de personnes : l'adjectif substantivé prend **the** et un sens pluriel (on le reprend par *them*, et un verbe dont il serait sujet serait au pluriel : *the poor are…*).\n\nAutres points : *three-hour* avec trait d'union et sans -s ; adjectifs jamais au pluriel."}$exo$::jsonb),
  ('ff5a2987-5f45-5742-8a87-cc4f1bda2944'::uuid, 1, 'traduction', $exo${"titre":"Repérer l'auxiliaire","consigne":"Pour chaque phrase, relève l'auxiliaire et le verbe lexical, puis donne une réponse courte.","enonce":"**1. Relève l'auxiliaire et le verbe lexical.**\n\na. She is working.\nb. I have finished.\nc. They don't know.\nd. You can go.\n\n**2. Réponds par une réponse courte (reprise).**\n\na. Do you like tea? — Yes, …\nb. Is she ready? — No, …\nc. Have you finished? — Yes, …\nd. Can he swim? — No, …","bareme":[{"critere":"Auxiliaire et verbe lexical correctement relevés dans les quatre phrases","points":10},{"critere":"Quatre réponses courtes avec le bon auxiliaire repris","points":10}],"dureeMin":7,"corrige":"**1. Repérage**\na. auxiliaire **is** (be, forme en -ING) — verbe lexical **working** (work).\nb. auxiliaire **have** (temps composé) — verbe lexical **finished** (finish).\nc. auxiliaire **do** (dans *don't*, négation) — verbe lexical **know**.\nd. auxiliaire **can** (modal) — verbe lexical **go**.\n\n**2. Réponses courtes**\na. Yes, **I do**.\nb. No, **she isn't**.\nc. Yes, **I have**.\nd. No, **he can't**.\n\nLa reprise courte répète l'**auxiliaire** de la question, jamais le verbe lexical (*Yes, I like* est faux)."}$exo$::jsonb),
  ('ff5a2987-5f45-5742-8a87-cc4f1bda2944'::uuid, 2, 'traduction', $exo${"titre":"Questions et négations","consigne":"Mets chaque phrase à la forme interrogative, puis à la forme négative.","enonce":"Mets chaque phrase **à la forme interrogative**, puis **à la forme négative**.\n\n1. You are ready.\n2. She has finished her homework.\n3. He works in London.\n4. They can speak Spanish.\n5. You have a car.\n\n**Question finale :** pourquoi les phrases 3 et 5 ne se construisent-elles pas comme les autres ?","bareme":[{"critere":"Questions avec l'auxiliaire placé devant le sujet","points":7},{"critere":"Négations avec not juste après l'auxiliaire","points":7},{"critere":"Do employé pour work et pour have lexical","points":4},{"critere":"Explication : verbe lexical seul, il faut un auxiliaire","points":2}],"dureeMin":10,"corrige":"**Réponses**\n1. *Are you ready?* — *You aren't ready.* (*You are not ready.*)\n2. *Has she finished her homework?* — *She hasn't finished her homework.*\n3. *Does he work in London?* — *He doesn't work in London.*\n4. *Can they speak Spanish?* — *They can't speak Spanish.* (*cannot*)\n5. *Do you have a car?* — *You don't have a car.*\n\n**Explication**\nDans les phrases 1, 2 et 4, il y a déjà un auxiliaire (*are*, *has*, *can*) : il passe devant le sujet pour la question et reçoit *not* pour la négation. Dans les phrases 3 et 5, il n'y a qu'un **verbe lexical** (*works*, *have* au sens de posséder) : seul, il ne sait former ni question ni négation, il faut donc l'auxiliaire **do** (*does* à la 3e personne, et le verbe revient à la base verbale : *does he work*)."}$exo$::jsonb),
  ('ff5a2987-5f45-5742-8a87-cc4f1bda2944'::uuid, 3, 'traduction', $exo${"titre":"L'interview d'une chanteuse","consigne":"Retrouve les questions de la journaliste, puis réponds aux questions 2 et 3.","enonce":"Une journaliste interroge la chanteuse Maya. Voici les réponses de Maya.\n\n1. (…?) — *Yes, I am. I'm very tired tonight.*\n2. (…?) — *Yes, I do. I love my fans.*\n3. (…?) — *No, I haven't. I haven't finished my new album yet.*\n4. (…?) — *Yes, I can. I can play the piano.*\n5. (…?) — *No, I don't. I don't have a dog.*\n\n**1.** Écris les cinq questions de la journaliste.\n**2.** Dans la réponse 1, *be* est-il auxiliaire ou verbe lexical ? Et *have* dans la réponse 5 ? Justifie.\n**3.** Explique pourquoi l'auxiliaire est « la clé de toute la grammaire anglaise ».","bareme":[{"critere":"Cinq questions correctes, auxiliaire devant le sujet","points":8},{"critere":"Auxiliaire de la question cohérent avec la reprise courte","points":4},{"critere":"Statut de be et de have justifié","points":5},{"critere":"Explication du rôle de l'auxiliaire (question, négation, reprise)","points":3}],"dureeMin":15,"corrige":"**1. Questions attendues**\n1. *Are you tired (tonight)?*\n2. *Do you love your fans?* (*Do you like your fans?* accepté)\n3. *Have you finished your new album (yet)?*\n4. *Can you play the piano?* (*Can you play an instrument?* accepté)\n5. *Do you have a dog?*\nLa reprise courte donne l'auxiliaire : *I am* → *Are you…?* ; *I do* → *Do you…?*, etc.\n\n**2. Statut**\n- Réponse 1 : *be* est **lexical** (verbe d'état, *I'm tired*), mais il **garde ses pouvoirs** d'auxiliaire : il passe lui-même devant le sujet (*Are you tired?*), sans *do*.\n- Réponse 5 : *have* est **lexical** (posséder) : il n'a pas ces pouvoirs, il faut **do** (*Do you have a dog?* / *I don't have a dog*).\n\n**3. La clé**\nL'auxiliaire construit la phrase : il passe **devant le sujet** pour la question, reçoit **not** pour la négation et sert à la **reprise courte**. Une fois l'auxiliaire repéré, question, négation et réponse courte se construisent toutes seules."}$exo$::jsonb),
  ('be859065-313a-5acd-9b99-fff696e04575'::uuid, 1, 'traduction', $exo${"titre":"Make ou let ?","consigne":"Complète avec make, made, let ou lets, puis corrige la phrase fautive.","enonce":"**1. Complète.**\n\n1. My parents ___ me do my homework every evening. (ils m'obligent)\n2. My sister ___ me borrow her bike yesterday. (elle m'a autorisé)\n3. The film ___ me cry. (il m'a fait pleurer)\n4. Our teacher ___ us use a calculator. (il nous autorise)\n\n**2. Corrige :** *My mum made me to tidy my room.*","bareme":[{"critere":"Quatre formes justes (sens et temps)","points":12},{"critere":"Correction : make + complément + base verbale, sans to","points":8}],"dureeMin":6,"corrige":"**1. Réponses**\n1. My parents **make** me do — obliger, présent.\n2. My sister **let** me borrow — autoriser ; *let* a la même forme au prétérit.\n3. The film **made** me cry — make = faire (provoquer), prétérit.\n4. Our teacher **lets** us use — autoriser, 3e personne du présent.\n\n**2. Correction**\n*My mum made me tidy my room.* — *make* + complément + **base verbale**, sans *to*. Le *to* ne réapparaît qu'au passif : *I was made to tidy my room*."}$exo$::jsonb),
  ('be859065-313a-5acd-9b99-fff696e04575'::uuid, 2, 'traduction', $exo${"titre":"Les courses de Mme Leroy","consigne":"Réécris chaque phrase avec la structure causative have (ou get), puis traduis les deux phrases de la question 2.","enonce":"Mme Leroy ne fait rien elle-même : elle fait tout faire par des professionnels.\n\n**1. Réécris avec have + complément + participe passé.**\n\na. A hairdresser cut her hair.\nb. A mechanic repaired her car.\nc. A painter painted her kitchen.\nd. Someone fixed her phone. (avec *get*)\n\n**2. Traduis en anglais.**\n\na. J'ai convaincu mon frère de m'aider.\nb. Je me suis fait couper les cheveux samedi.\n\n**3.** Pourquoi *I cut my hair* ne traduit-il pas « je me suis fait couper les cheveux » ?","bareme":[{"critere":"Quatre phrases causatives correctes (have / get + complément + participe passé)","points":8},{"critere":"Get + to pour convaincre, had my hair cut","points":6},{"critere":"Explication du piège I cut my hair","points":4},{"critere":"Correction de la langue","points":2}],"dureeMin":10,"corrige":"**1. Réponses**\na. *She had her hair cut.*\nb. *She had her car repaired.*\nc. *She had her kitchen painted.*\nd. *She got her phone fixed.*\nConstruction : *have / get* + complément + **participe passé**. Le sujet ne fait pas l'action : il la **commande**.\n\n**2. Traduction**\na. *I got my brother to help me.* — *get* + complément + **to** + verbe = convaincre.\nb. *I had my hair cut on Saturday.* (*I got my hair cut* accepté)\n\n**3. Le piège**\n*I cut my hair* signifie que je les ai coupés **moi-même**. « Se faire couper les cheveux » par un coiffeur se dit avec la structure causative : *I had my hair cut*."}$exo$::jsonb),
  ('be859065-313a-5acd-9b99-fff696e04575'::uuid, 3, 'traduction', $exo${"titre":"Le stage de voile","consigne":"Traduis le texte en anglais, puis réponds aux questions 2 et 3 en justifiant.","enonce":"**1. Thème : traduis en anglais.**\n\n> Au stage de voile, le moniteur nous faisait nager tous les matins, mais il nous laissait choisir notre bateau. Un jour, j'ai convaincu mon ami d'essayer le kayak. Ma planche était cassée, alors je l'ai fait réparer.\n\n*Aide : sailing camp = stage de voile ; instructor = moniteur ; board = planche ; to try = essayer.*\n\n**2.** Mets ces deux phrases au passif et explique ce qui change :\na. *The instructor made us swim.*\nb. *The instructor let us choose our boat.*\n\n**3.** Classe *make*, *let*, *have*, *get* selon leur sens (obliger, autoriser, faire faire, convaincre) et indique ce qui suit le complément pour chacun.","bareme":[{"critere":"Make et let + complément + base verbale au prétérit","points":5},{"critere":"Get + to (convaincre) et have + participe passé (faire réparer)","points":5},{"critere":"Passif de make avec to ; let remplacé par be allowed to","points":5},{"critere":"Tableau des quatre verbes juste","points":3},{"critere":"Correction de la langue","points":2}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n> *At the sailing camp, the instructor made us swim every morning, but he let us choose our boat. One day, I got my friend to try the kayak. My board was broken, so I had it repaired.* (*got it repaired* accepté)\n\n**2. Passif**\na. *We were made to swim.* — au passif, **to** réapparaît après *make*.\nb. *We were allowed to choose our boat.* — *let* n'a **pas de passif** : on emploie *be allowed to*.\n\n**3. Tableau**\n- **make** = obliger → complément + **base verbale** ;\n- **let** = autoriser → complément + **base verbale** ;\n- **have** = faire faire par un professionnel → complément + **participe passé** ;\n- **get** = convaincre → complément + **to** + verbe ; ou faire faire (familier) → complément + **participe passé**."}$exo$::jsonb),
  ('0b878ce4-7620-5929-a68d-110b1af4e92d'::uuid, 1, 'traduction', $exo${"titre":"Les verbes à particule du brevet","consigne":"Complète chaque phrase avec le verbe qui convient, à la bonne forme.","enonce":"**Complète avec : give up, look after, look for, put on, find out, get up, run out of, grow up.**\n\n1. I ___ at 7 every morning.\n2. It's cold: ___ your coat!\n3. My grandma ___ my little sister on Wednesdays.\n4. I'm ___ my keys. Have you seen them?\n5. Don't ___! You can do it!\n6. We have ___ milk: can you buy some?\n7. I want to ___ the truth.\n8. She wants to be a vet when she ___.\n\n**Question :** pourquoi *look after* ne se traduit-il pas par « regarder après » ?","bareme":[{"critere":"Huit verbes justes et bien conjugués","points":16},{"critere":"Explication : le sens n'est pas la somme des deux mots","points":4}],"dureeMin":7,"corrige":"**Réponses**\n1. I **get up** at 7.\n2. **Put on** your coat! (*Put your coat on!*)\n3. My grandma **looks after** my little sister — 3e personne : -s.\n4. I'm **looking for** my keys.\n5. Don't **give up**!\n6. We have **run out of** milk.\n7. I want to **find out** the truth.\n8. when she **grows up**.\n\n**Explication**\nLe sens d'un verbe à particule ou prépositionnel n'est presque jamais la somme de ses deux mots : *look after* signifie « s'occuper de ». Ces verbes s'apprennent comme des **mots de vocabulaire entiers**."}$exo$::jsonb),
  ('0b878ce4-7620-5929-a68d-110b1af4e92d'::uuid, 2, 'traduction', $exo${"titre":"La place du pronom","consigne":"Remplace le nom souligné par un pronom et réécris la phrase, puis réponds à la question 2.","enonce":"**1. Remplace le complément en gras par un pronom (it, them, her…).**\n\n1. Turn on **the light**.\n2. Take off **your shoes**.\n3. Look after **your sister**.\n4. Put on **your jacket**.\n5. Listen to **the teacher**. (*him*)\n6. Look up **these words** in the dictionary.\n\n**2.** Pour les phrases 1 et 3, dis s'il s'agit d'un verbe **à particule** ou d'un verbe **prépositionnel**, et explique le test qui permet de le savoir.","bareme":[{"critere":"Pronom placé avant la particule pour les verbes à particule","points":8},{"critere":"Pronom placé après la préposition pour les verbes prépositionnels","points":5},{"critere":"Nature des verbes 1 et 3 identifiée","points":3},{"critere":"Test de séparation expliqué","points":4}],"dureeMin":10,"corrige":"**1. Réponses**\n1. *Turn **it** on.* — jamais *turn on it*.\n2. *Take **them** off.*\n3. *Look after **her**.* — préposition : le pronom reste après.\n4. *Put **it** on.*\n5. *Listen to **him**.*\n6. *Look **them** up in the dictionary.*\n\nAvec un verbe **à particule**, un pronom se place **obligatoirement avant** la particule. Avec un verbe **prépositionnel**, le complément (nom ou pronom) est **toujours après** la préposition.\n\n**2. Le test**\n- *Turn on* : verbe **à particule** — on peut dire *turn the light on*.\n- *Look after* : verbe **prépositionnel** — on ne peut pas dire *look your sister after*.\nSi le complément peut se glisser entre le verbe et le petit mot, c'est une particule ; sinon, c'est une préposition."}$exo$::jsonb),
  ('0b878ce4-7620-5929-a68d-110b1af4e92d'::uuid, 3, 'traduction', $exo${"titre":"Le premier voyage de Jules","consigne":"Lis le texte, traduis-le, puis réponds aux questions 2 et 3.","enonce":"> Jules got up at 5 a.m. He put on his jacket and looked for his passport. At the airport, he waited for his friends. The plane took off at 8. Jules was looking forward to seeing London. When he arrived, his phone had run out of battery, so he couldn't find out where his hotel was. But he didn't give up!\n\n1. Traduis le texte en français.\n2. Relève **deux verbes à particule** et **deux verbes prépositionnels**, et justifie ton classement avec le test du cours.\n3. Réécris deux phrases du texte en remplaçant le complément du verbe à particule par un pronom. Explique la règle de position.","bareme":[{"critere":"Traduction juste du sens de chaque verbe composé","points":7},{"critere":"Deux verbes à particule et deux prépositionnels bien classés","points":4},{"critere":"Classement justifié par le test de séparation","points":3},{"critere":"Deux réécritures avec pronom avant la particule, règle expliquée","points":4},{"critere":"Qualité du français","points":2}],"dureeMin":17,"corrige":"**1. Traduction modèle**\n> Jules s'est levé à 5 h. Il a mis sa veste et a cherché son passeport. À l'aéroport, il a attendu ses amis. L'avion a décollé à 8 h. Jules avait hâte de voir Londres. Quand il est arrivé, son téléphone n'avait plus de batterie, alors il n'a pas pu découvrir où était son hôtel. Mais il n'a pas abandonné !\n\nPoints de sens : *got up* = s'est levé ; *put on* = a mis (vêtement) ; *looked for* = a cherché ; *waited for* = a attendu ; *took off* = a décollé ; *looking forward to* = avait hâte de (suivi de -ING) ; *run out of* = être à court de ; *find out* = découvrir ; *give up* = abandonner.\n\n**2. Classement**\n- À particule : *put on*, *find out* (aussi *get up*, *take off*, *give up*) — on peut dire *put his jacket on*.\n- Prépositionnels : *look for*, *wait for* — impossible de dire *waited his friends for*.\n\n**3. Réécritures**\n- *He put it on.* — jamais *put on it*.\n- *He couldn't find it out.* (phrase possible, même si l'on garde plutôt le nom ici).\nRègle : avec un verbe à particule, un **pronom** se place **obligatoirement avant** la particule ; un nom peut se placer avant ou après."}$exo$::jsonb),
  ('135a010e-30ae-545f-902e-26e987d3287c'::uuid, 1, 'traduction', $exo${"titre":"To + verbe ou -ING ?","consigne":"Mets le verbe entre parenthèses à la bonne forme (to + verbe, -ING ou base verbale).","enonce":"**Mets le verbe à la bonne forme.**\n\n1. I enjoy (read) comics.\n2. She decided (leave) early.\n3. You must (go) now.\n4. He left without (say) goodbye.\n5. I hope (see) you soon.\n6. We finished (work) at six.\n7. I avoid (eat) sugar.\n8. I'm looking forward to (meet) you.\n\n**Question :** pourquoi *look forward to* est-il suivi de -ING malgré son « to » ?","bareme":[{"critere":"Huit verbes à la bonne forme","points":16},{"critere":"Explication : to est ici une préposition","points":4}],"dureeMin":7,"corrige":"**Réponses**\n1. I enjoy **reading** — *enjoy* + -ING.\n2. She decided **to leave** — *decide* + to.\n3. You must **go** — après un modal : base verbale.\n4. without **saying** — après une préposition : -ING.\n5. I hope **to see** — *hope* + to.\n6. We finished **working** — *finish* + -ING.\n7. I avoid **eating** — *avoid* + -ING.\n8. looking forward to **meeting** — -ING.\n\n**Explication**\nDans *look forward to*, *to* n'est pas la marque de l'infinitif mais une **préposition** (comme dans *I look forward to the holidays*). Or, après une préposition, le verbe se met toujours en **-ING**."}$exo$::jsonb),
  ('135a010e-30ae-545f-902e-26e987d3287c'::uuid, 2, 'traduction', $exo${"titre":"Stop, remember, try","consigne":"Traduis chaque paire de phrases en français, puis complète les phrases de la question 2.","enonce":"**1. Traduis en français et explique la différence de sens.**\n\na. *He stopped to smoke.* / *He stopped smoking.*\nb. *Remember to lock the door.* / *I remember locking the door.*\nc. *Try to open the window.* / *Try opening the window.*\n\n**2. Complète avec la bonne forme.**\n\n1. Grandpa is healthier since he stopped (drink) coffee.\n2. Did you remember (buy) bread?\n3. I went to the library (study).\n4. It's too hot. Try (open) the window, it might help.","bareme":[{"critere":"Trois paires traduites avec la bonne nuance","points":9},{"critere":"Quatre blancs justes","points":8},{"critere":"Infinitif de but avec to (et non for)","points":3}],"dureeMin":10,"corrige":"**1. Traductions**\na. « Il s'est arrêté **pour** fumer. » / « Il a **arrêté de** fumer. »\nb. « **Pense à** fermer la porte à clé. » (action à faire) / « Je **me souviens d'avoir** fermé la porte à clé. » (action déjà faite)\nc. « **Essaie d'**ouvrir la fenêtre. » (effort, peut-être difficile) / « Essaie **en** ouvrant la fenêtre, pour voir. » (tester une solution)\n\n**2. Réponses**\n1. since he stopped **drinking** coffee — il a arrêté d'en boire.\n2. Did you remember **to buy** bread? — penser à faire.\n3. I went to the library **to study** — infinitif de but ; jamais *for studying*.\n4. Try **opening** the window — essayer pour voir si ça aide."}$exo$::jsonb),
  ('135a010e-30ae-545f-902e-26e987d3287c'::uuid, 3, 'traduction', $exo${"titre":"Le projet de Nina","consigne":"Traduis le texte en anglais, puis justifie quatre de tes choix.","enonce":"**1. Thème : traduis en anglais.**\n\n> Nina veut devenir pilote. Elle adore voyager et elle a appris à piloter l'an dernier. Elle est douée pour parler aux gens, mais elle déteste attendre. La semaine dernière, elle est allée à l'aéroport pour rencontrer un vrai pilote. Il lui a promis de l'aider. Elle a hâte de voler seule !\n\n*Aide : to fly = piloter / voler ; to become = devenir ; alone = seule ; she is good at = elle est douée pour.*\n\n**2.** Justifie la forme du verbe après : *want*, *good at*, *to meet* (pour rencontrer), *look forward to*.","bareme":[{"critere":"Verbes + to justes (want, learn, promise)","points":5},{"critere":"Verbes + -ING justes (love, hate, look forward to)","points":5},{"critere":"-ING après préposition et infinitif de but","points":3},{"critere":"Quatre justifications exactes","points":5},{"critere":"Correction générale de la langue","points":2}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n> *Nina wants to become a pilot. She loves travelling and she learnt to fly last year. She is good at talking to people, but she hates waiting. Last week, she went to the airport to meet a real pilot. He promised to help her. She is looking forward to flying alone!*\n(*learned* et *traveling* acceptés ; *loves to travel* accepté car *love* admet les deux, mais -ING est la forme du cours.)\n\n**2. Justifications**\n- *want* + **to** + verbe : *want* fait partie des verbes suivis de l'infinitif (comme decide, hope, promise, learn).\n- *good at* + **-ING** : *at* est une **préposition** ; après une préposition, toujours -ING.\n- *to meet* : **infinitif de but** (« pour rencontrer ») → *to* ou *in order to* ; jamais *for meeting*.\n- *look forward to* + **-ING** : *to* y est une préposition, pas la marque de l'infinitif."}$exo$::jsonb),
  ('11e79187-bd85-5697-9eaf-fbd4a6a77ead'::uuid, 1, 'traduction', $exo${"titre":"Former les adverbes","consigne":"Donne l'adverbe correspondant à chaque adjectif, puis corrige la phrase fautive.","enonce":"**1. Donne l'adverbe.**\n\nslow · careful · happy · simple · good · fast · hard · late\n\n**2. Corrige :** *She speaks very good English and she sings good.*\n\n**3.** Que signifient *hardly* et *lately* ?","bareme":[{"critere":"Huit adverbes justes, irréguliers compris","points":12},{"critere":"Phrase corrigée (sings well)","points":4},{"critere":"Sens de hardly et lately","points":4}],"dureeMin":6,"corrige":"**1. Adverbes**\n- slow → **slowly**\n- careful → **carefully**\n- happy → **happily** (-y → -ily)\n- simple → **simply** (-le → -ly)\n- good → **well** (irrégulier)\n- fast → **fast** (identique)\n- hard → **hard** (identique)\n- late → **late** (identique)\n\n**2. Correction**\n*She speaks very good English and she sings **well**.* — *good English* est juste (adjectif devant un nom) ; mais pour modifier le verbe *sings*, il faut l'adverbe **well**.\n\n**3. Pièges**\n- *hardly* = **à peine** (pas « durement ») ;\n- *lately* = **récemment** (pas « tardivement »)."}$exo$::jsonb),
  ('11e79187-bd85-5697-9eaf-fbd4a6a77ead'::uuid, 2, 'traduction', $exo${"titre":"Les habitudes de Farah","consigne":"Place l'adverbe entre parenthèses au bon endroit, puis réponds à la question 2.","enonce":"**1. Réécris chaque phrase avec l'adverbe à sa place.**\n\n1. Farah gets up early. (always)\n2. She is late. (never)\n3. She has been to Spain. (never)\n4. She plays tennis on Saturdays. (usually)\n5. She doesn't run fast. (enough → après l'adjectif / adverbe)\n6. She is tired after school. (very)\n\n**2.** Remets les compléments dans l'ordre habituel : *She sang (last night / at the concert / beautifully).* Donne la règle.","bareme":[{"critere":"Adverbes de fréquence placés avant le verbe lexical, après be ou l'auxiliaire","points":10},{"critere":"Enough après, very devant l'adjectif","points":4},{"critere":"Ordre manière, lieu, temps rétabli et règle donnée","points":6}],"dureeMin":10,"corrige":"**1. Réponses**\n1. *Farah always gets up early.* — avant le verbe lexical.\n2. *She is never late.* — après *be*.\n3. *She has never been to Spain.* — après l'auxiliaire.\n4. *She usually plays tennis on Saturdays.* — avant le verbe lexical.\n5. *She doesn't run fast enough.* — *enough* après l'adverbe / l'adjectif.\n6. *She is very tired after school.* — adverbe de degré devant l'adjectif.\n\n**2. Ordre**\n*She sang beautifully at the concert last night.* — ordre habituel en fin de phrase : **manière → lieu → temps**."}$exo$::jsonb),
  ('11e79187-bd85-5697-9eaf-fbd4a6a77ead'::uuid, 3, 'traduction', $exo${"titre":"La critique de concert","consigne":"Lis le texte, corrige les fautes en justifiant, puis traduis les deux phrases de la question 3.","enonce":"> Last night, the band played very good. The singer sang loud the songs and the guitarist always was smiling. I could hard hear the drums, because I was at the back. The concert finished lately, at midnight. I have been to concerts often, but this one was really amazing!\n\n1. Le texte contient **six fautes** sur les adverbes. Relève-les et corrige-les.\n2. Justifie chaque correction par la règle du cours.\n3. Traduis : a) *I have hardly slept lately.* b) *She works hard and she is never late.*","bareme":[{"critere":"Six fautes relevées et corrigées","points":7},{"critere":"Justifications (irréguliers, place, sens de hardly / lately)","points":6},{"critere":"Traductions justes de hardly, lately, hard, late","points":5},{"critere":"Qualité de la rédaction","points":2}],"dureeMin":16,"corrige":"**1 et 2. Les six fautes**\n- *played very good* → **played very well** : l'adverbe de *good* est *well*.\n- *sang loud the songs* → **sang the songs loudly** (ou *loud*) : on n'intercale jamais un adverbe entre le verbe et son complément d'objet.\n- *always was smiling* → **was always smiling** : l'adverbe de fréquence se place **après** *be* / l'auxiliaire.\n- *could hard hear* → **could hardly hear** : « à peine » = *hardly* ; *hard* = dur.\n- *finished lately* → **finished late** : *late* reste identique ; *lately* signifie « récemment ».\n- *I have been to concerts often* → **I have often been to concerts** : fréquence entre l'auxiliaire et le participe passé.\n\n**3. Traductions**\na) « J'ai **à peine** dormi **ces derniers temps**. » (récemment)\nb) « Elle travaille **dur** et elle n'est **jamais en retard**. » — *hard* et *late* adverbes identiques à l'adjectif."}$exo$::jsonb),
  ('463efa64-25c6-560f-829c-2e2591d6de80'::uuid, 1, 'traduction', $exo${"titre":"Habituel ou en cours ?","consigne":"Mets le verbe au présent simple ou au présent en BE + -ING.","enonce":"**Mets le verbe à la bonne forme.**\n\n1. Look! It (rain).\n2. My brother (study) English every day.\n3. Water (boil) at 100 °C.\n4. Be quiet, I (do) my homework.\n5. She (not / like) fish.\n6. I (know) the answer.\n7. We (meet) Tom tonight at 8. (c'est organisé)\n8. He (watch) TV every evening.\n\n**Question :** pourquoi ne peut-on pas dire *I am knowing* ?","bareme":[{"critere":"Huit formes justes (temps, 3e personne, orthographe)","points":16},{"critere":"Explication des verbes d'état","points":4}],"dureeMin":7,"corrige":"**Réponses**\n1. It **is raining** — action en cours (*Look!*).\n2. My brother **studies** — habitude ; consonne + y → -ies.\n3. Water **boils** — vérité générale.\n4. I **am doing** — en cours.\n5. She **doesn't like** — présent simple, négation avec *doesn't*.\n6. I **know** — verbe d'état.\n7. We **are meeting** — projet organisé.\n8. He **watches** — habitude ; -ch → -es.\n\n**Explication**\n*Know* est un **verbe d'état** (comme like, love, want, need, understand, believe) : il n'accepte pas la forme en -ING. On dit *I know*, jamais *I am knowing*."}$exo$::jsonb),
  ('463efa64-25c6-560f-829c-2e2591d6de80'::uuid, 2, 'traduction', $exo${"titre":"La carte postale d'Ilan","consigne":"Conjugue les verbes entre parenthèses, puis justifie trois choix.","enonce":"> Dear Grandma,\n> I (1. write) to you from Edinburgh! I (2. stay) with my aunt this week. Every morning, she (3. go) to work by bike and I (4. visit) the city. Right now, it (5. rain) and my cousin (6. play) the piano. He (7. play) every day! Tonight we (8. have) dinner at a restaurant: my aunt booked a table. I (9. love) this city!\n> Ilan\n\n1. Conjugue les neuf verbes.\n2. Justifie les formes 2, 3 et 9.","bareme":[{"critere":"Formes en BE + -ING justes (en cours, temporaire, projet)","points":7},{"critere":"Présents simples justes, orthographe de la 3e personne","points":6},{"critere":"Verbe d'état love au présent simple","points":2},{"critere":"Trois justifications exactes","points":5}],"dureeMin":10,"corrige":"**1. Réponses**\n(1) **am writing** — en cours.\n(2) **am staying** — situation temporaire.\n(3) **goes** — habitude ; -o → -es.\n(4) **visit** — habitude.\n(5) **is raining** — en cours (*right now*).\n(6) **is playing** — en cours.\n(7) **plays** — habitude (*every day*).\n(8) **are having** — projet organisé.\n(9) **love** — verbe d'état.\n\n**2. Justifications**\n- (2) *this week* : une situation **temporaire** → BE + -ING.\n- (3) *every morning* : une **habitude** → présent simple, -es à la 3e personne.\n- (9) *love* est un **verbe d'état** : jamais à la forme en -ING."}$exo$::jsonb),
  ('463efa64-25c6-560f-829c-2e2591d6de80'::uuid, 3, 'traduction', $exo${"titre":"Le colocataire agaçant","consigne":"Traduis le texte en anglais, puis réponds à la question 2.","enonce":"**1. Thème : traduis en anglais.**\n\n> Mon frère aîné vit à Manchester. Il travaille dans une banque, mais ce mois-ci il travaille à Londres. D'habitude, il se lève à 7 h. En ce moment, il cherche un appartement. Son colocataire perd toujours ses clés, c'est énervant ! Samedi, nous prenons le train pour aller le voir : les billets sont achetés. Le train part à 9 h 15.\n\n*Aide : flatmate = colocataire ; flat = appartement ; to look for = chercher.*\n\n**2.** Pour cinq verbes de ta traduction, nomme le temps choisi et l'emploi du cours qui le justifie (habitude, état permanent, temporaire, en cours, projet organisé, programme fixe, agacement).","bareme":[{"critere":"Présent simple pour l'état permanent, l'habitude et l'horaire","points":5},{"critere":"BE + -ING pour le temporaire, l'action en cours et le projet organisé","points":5},{"critere":"Always + BE + -ING pour l'agacement","points":3},{"critere":"Cinq justifications exactes","points":5},{"critere":"Correction de la langue","points":2}],"dureeMin":17,"corrige":"**1. Traduction modèle**\n> *My older brother lives in Manchester. He works in a bank, but this month he is working in London. He usually gets up at 7. At the moment, he is looking for a flat. His flatmate is always losing his keys, it's annoying! On Saturday, we are taking the train to see him: the tickets are bought. The train leaves at 9.15.*\n\n**2. Justifications attendues**\n- *lives*, *works in a bank* : **état permanent** → présent simple.\n- *is working in London* (*this month*) : situation **temporaire** → BE + -ING.\n- *usually gets up* : **habitude** → présent simple.\n- *is looking for* (*at the moment*) : action **en cours** → BE + -ING.\n- *is always losing* : *always* + BE + -ING → **agacement**.\n- *are taking the train* : **projet organisé** (billets achetés) → BE + -ING.\n- *leaves at 9.15* : **programme fixe**, horaire → présent simple.\nCinq justifications suffisent."}$exo$::jsonb),
  ('983ed423-3e2d-5c11-afb9-ad2721af7663'::uuid, 1, 'traduction', $exo${"titre":"Arriving at Tilbury","consigne":"Lis le texte (fictif), puis réponds en anglais aux questions 1 et 2 et en français à la question 3.","enonce":"**Text (fictional).**\n\n> *My grandfather Winston was one of the passengers on the Empire Windrush. The ship docked at Tilbury on 22 June 1948. He came from Jamaica with a small suitcase and a big dream: to help rebuild Britain after the war. He found a job on the London buses and settled in Brixton. At first, it was hard to fit in. Today, our family goes to the Notting Hill Carnival every summer.*\n\n1. **Right or wrong?** Justify each answer with a quotation from the text.\n   a. Winston arrived in Britain before the Second World War.\n   b. Winston went to Britain to work.\n   c. Winston's family still celebrates Caribbean culture.\n2. Find in the text the words or phrases that mean: *s'installer* ; *s'intégrer* ; *reconstruire*.\n3. Explique en une ou deux phrases en français ce que représente la génération Windrush pour le Royaume-Uni.","bareme":[{"critere":"Trois réponses right/wrong justes, chacune justifiée par une citation exacte du texte","points":9},{"critere":"Les trois équivalents trouvés : settled, to fit in, to rebuild","points":6},{"critere":"Explication juste du rôle de la génération Windrush (Caribéens venus reconstruire le pays après la guerre)","points":5}],"dureeMin":8,"corrige":"1.\na. **Wrong** : *The ship docked at Tilbury on 22 June 1948* / *to help rebuild Britain after the war.* Il arrive après la guerre.\nb. **Right** : *He found a job on the London buses* ou *to help rebuild Britain after the war.*\nc. **Right** : *Today, our family goes to the Notting Hill Carnival every summer.* (Le carnaval célèbre la culture caribéenne.)\n\n2. *s'installer* → **settled** (*to settle*) ; *s'intégrer* → **to fit in** ; *reconstruire* → **rebuild** (*to rebuild*).\n\n3. La génération Windrush désigne les Caribéens arrivés à partir de 1948 (l'*Empire Windrush* accoste à Tilbury le 22 juin 1948) pour aider à **reconstruire** le Royaume-Uni après la guerre : ils ont travaillé dans les transports ou les hôpitaux et ont apporté leur culture (carnaval de Notting Hill, depuis 1966)."}$exo$::jsonb),
  ('983ed423-3e2d-5c11-afb9-ad2721af7663'::uuid, 2, 'traduction', $exo${"titre":"A newcomer in Toronto","consigne":"Lis le texte (fictif), réponds en anglais aux questions 1 à 3, puis traduis en français le passage souligné en gras (question 4).","enonce":"**Text (fictional).**\n\n> *Priya is a nurse from India. Three years ago, she applied to emigrate to Canada. The immigration officers looked at her level of English, her diploma and her job. She got enough points and settled in Toronto. \"Here, nobody asked me to forget where I come from,\" she says. \"On Sundays, I still cook my mother's recipes, and I cheer for the Toronto Raptors with my colleagues.\" **Canada does not want its newcomers to melt into one model: it sees itself as a mosaic, where each community keeps its colours.***\n\n1. Why was Priya allowed to settle in Canada? Explain the system in your own words.\n2. Quote two elements showing that Priya keeps her culture and one showing that she fits in.\n3. What official policy, adopted in 1971, does the text illustrate? Explain it in one sentence.\n4. Traduis en français la dernière phrase (en gras).","bareme":[{"critere":"Système à points expliqué (langue, diplôme, métier) en anglais correct","points":5},{"critere":"Trois citations pertinentes : deux sur la culture gardée, une sur l'intégration","points":5},{"critere":"Multiculturalisme canadien identifié et expliqué (mosaïque et non assimilation)","points":4},{"critere":"Traduction fidèle et correcte en français de la phrase en gras","points":6}],"dureeMin":12,"corrige":"1. *Canada chooses its immigrants with a **points system**: officers look at the candidate's language, diploma and job. Priya had enough points because she speaks English, has a diploma and is a nurse.*\n\n2. Culture gardée : *nobody asked me to forget where I come from* ; *I still cook my mother's recipes.* Intégration : *I cheer for the Toronto Raptors with my colleagues.*\n\n3. *The text illustrates **Canadian multiculturalism** (policy of 1971, law of 1988): Canada recognises diversity instead of asking newcomers to assimilate.*\n\n4. Traduction proposée : « Le Canada ne veut pas que ses nouveaux arrivants se fondent dans un modèle unique : il se voit comme une mosaïque, où chaque communauté garde ses couleurs. »\nPoints attendus : *does not want its newcomers to melt* → « ne veut pas que ses nouveaux arrivants se fondent » (subjonctif en français) ; *newcomers* → « nouveaux arrivants » ; *sees itself as* → « se voit comme / se considère comme » ; *keeps its colours* → « garde ses couleurs ». On accepte « un seul modèle »."}$exo$::jsonb),
  ('983ed423-3e2d-5c11-afb9-ad2721af7663'::uuid, 3, 'traduction', $exo${"titre":"Belonging is not only a matter of papers","consigne":"Expression écrite en anglais : rédige un texte argumenté d'environ 150 mots en t'appuyant sur le document et sur tes connaissances.","enonce":"**Document (fictional testimony, 2018).**\n\n> *I came to London from Barbados in 1962, when I was seven. I went to school here, I worked as a nurse for thirty-five years, I paid my taxes. Last month, a letter told me I had no right to stay in this country because I could not prove when I had arrived. I was born British, in a British colony. Now I am treated like an illegal immigrant.* — Gloria, 63\n\n**Subject.** *Has immigration been a win-win situation for Britain and the Windrush generation?*\n\nIn about 150 words, show what both sides gained, then explain what the 2018 scandal revealed. Use at least three words from the lesson (e.g. *host country, newcomer, to settle, to fit in*).","bareme":[{"critere":"Bénéfices pour le Royaume-Uni (reconstruction, hôpitaux, transports, culture) et pour les migrants, développés","points":5},{"critere":"Scandale Windrush 2018 expliqué à partir du document (arrivés enfants, menacés d'expulsion faute de papiers)","points":5},{"critere":"Argumentation nuancée et structurée, avec une conclusion qui répond à la question","points":4},{"critere":"Correction de la langue, trois mots du cours bien employés, longueur respectée","points":6}],"dureeMin":20,"corrige":"**Éléments attendus**\n- **Ce que le Royaume-Uni a gagné** : après 1948 (*Empire Windrush*, Tilbury, 22 juin 1948), des Caribéens ont aidé à **reconstruire** le pays : hôpitaux (Gloria, infirmière pendant 35 ans), bus, transports ; une culture qui enrichit le pays (carnaval de Notting Hill depuis 1966, roman *Small Island* d'Andrea Levy, 2004).\n- **Ce que les migrants ont gagné** : du travail, une vie nouvelle, une place dans le pays d'accueil.\n- **Le revers : le scandale de 2018** : des Britanniques arrivés **enfants** (Gloria, à sept ans) ont été menacés d'expulsion car ils ne pouvaient pas **prouver** leur date d'arrivée. Ils se sentaient chez eux mais étaient traités comme des immigrés illégaux.\n- **Conclusion** : un échange gagnant-gagnant, mais trahi : l'appartenance ne se réduit pas aux papiers.\n\n**Exemple de copie (≈ 150 mots)**\n*The Windrush generation first seems to prove that immigration can be a win-win situation. When the Empire Windrush docked at Tilbury in 1948, hundreds of Caribbean newcomers came to help rebuild post-war Britain. They worked in hospitals, like Gloria, who was a nurse for thirty-five years, and on buses. In return, they found jobs and settled in their host country. They also brought their culture: the Notting Hill Carnival has celebrated it since 1966.*\n*However, the 2018 scandal revealed another side of the story. People who had arrived as children, like Gloria, were told they had no right to stay because they could not prove when they had arrived. After a whole life of work, they were treated as illegal immigrants.*\n*Both sides benefited from immigration, but Britain did not always keep its promise. Gloria's story shows that belonging is not only a matter of papers.*"}$exo$::jsonb),
  ('4d2675eb-0fb0-554a-a3c5-332a3ad98a1b'::uuid, 1, 'traduction', $exo${"titre":"Five rulings of the Supreme Court","consigne":"Réponds en anglais, par des phrases complètes.","enonce":"**Five rulings of the US Supreme Court**\n\n*Brown v. Board of Education* — *Obergefell v. Hodges* — *Plessy v. Ferguson* — *Students for Fair Admissions v. Harvard* — *Loving v. Virginia*\n\n1. Put the five rulings in chronological order and give the year of each one.\n2. For each ruling, write one sentence in English to explain what the Court decided.\n3. Explain in one sentence what *to overturn a ruling* means, and give an example taken from this list.","bareme":[{"critere":"Ordre chronologique et dates justes (1896, 1954, 1967, 2015, 2023)","points":6},{"critere":"Une phrase juste en anglais pour chacun des cinq arrêts","points":10},{"critere":"To overturn expliqué, avec Brown qui renverse Plessy","points":4}],"dureeMin":8,"corrige":"1. *Plessy v. Ferguson* (**1896**) → *Brown v. Board of Education* (**1954**) → *Loving v. Virginia* (**1967**) → *Obergefell v. Hodges* (**2015**) → *Students for Fair Admissions v. Harvard* (**2023**).\n\n2. Phrases attendues (formulations proches acceptées) :\n- *In Plessy v. Ferguson, the Court declared segregation legal: \"separate but equal\".*\n- *In Brown v. Board of Education, it ruled that segregation in public schools was unconstitutional.*\n- *In Loving v. Virginia, it struck down the laws banning interracial marriages.*\n- *In Obergefell v. Hodges, same-sex marriage became a right in the whole country.*\n- *In Students for Fair Admissions v. Harvard, the Court ended the use of ethnic origin in university admissions.*\n\n3. *To overturn a ruling means to cancel it, to reverse it.* Exemple : *Brown v. Board of Education (1954) overturned the principle of \"separate but equal\" set by Plessy v. Ferguson (1896) in schools.*"}$exo$::jsonb),
  ('4d2675eb-0fb0-554a-a3c5-332a3ad98a1b'::uuid, 2, 'traduction', $exo${"titre":"The red lines on the map","consigne":"Lis le texte (fictif), réponds en anglais aux questions 1 à 3, puis traduis la question 4 en français.","enonce":"**Text (fictional).**\n\n> *In 1937, my grandparents wanted to buy a house in their neighbourhood of Chicago. The bank refused. On its map, their street was surrounded by a red line: no loans for Black families. For years, their area received no investment. In 1968, a new federal law finally banned discrimination in housing. My father bought a house in 1975. But equality on paper does not mean equality in practice: the houses in our street are still worth less than those a few miles away.* — Marcus\n\n1. What was *redlining*? Explain it with elements from the text.\n2. Which law is the text referring to in 1968? What did it change?\n3. Why does Marcus say that *equality on paper does not mean equality in practice*?\n4. Traduis en français : *For years, their area received no investment. In 1968, a new federal law finally banned discrimination in housing.*","bareme":[{"critere":"Redlining expliqué avec des éléments du texte (banques, prêts refusés, quartiers noirs cerclés de rouge)","points":5},{"critere":"Fair Housing Act (1968) identifié et son effet expliqué","points":4},{"critere":"Explication de l'écart entre égalité juridique et égalité réelle, appuyée sur le texte","points":5},{"critere":"Traduction fidèle et correcte (for years, area, banned, housing)","points":6}],"dureeMin":12,"corrige":"1. *Redlining was a practice of the 1930s: banks refused to lend money to people living in Black neighbourhoods, which were surrounded by a red line on their maps. In the text, the bank refused a loan to Marcus's grandparents because their street was inside the red line.*\n\n2. *It is the **Fair Housing Act** (1968), which banned discrimination in housing. After it, Black families like Marcus's father could buy a house (in 1975).*\n\n3. *Because the law changed, but the consequences of redlining are still visible: the area received no investment for years, so the houses in Marcus's street are still worth less than those a few miles away. The law gives equal rights, but not equal situations.*\n\n4. Traduction proposée : « Pendant des années, leur quartier n'a reçu aucun investissement. En 1968, une nouvelle loi fédérale a enfin interdit la discrimination dans le logement. »\nPoints attendus : *for years* → « pendant des années » ; *area* → « quartier / zone » ; *received no* → « n'a reçu aucun » ; *finally* → « enfin / finalement » ; *banned* → « a interdit » ; *housing* → « le logement »."}$exo$::jsonb),
  ('4d2675eb-0fb0-554a-a3c5-332a3ad98a1b'::uuid, 3, 'traduction', $exo${"titre":"Can the law include minorities?","consigne":"Expression écrite en anglais : rédige un texte argumenté d'environ 180 mots en t'appuyant sur les documents et sur tes connaissances.","enonce":"**Document A.** *1896: the Supreme Court declares segregation legal. 1954: the same Court declares segregation in public schools unconstitutional.*\n\n**Document B (fictional).** *After the Grenfell Tower fire (London, 14 June 2017, 72 dead), a resident of a nearby council estate said: \"We had complained about safety for years. Nobody listened to us, because nobody listens to people like us.\"*\n\n**Document C.** *October 2023: Australian voters reject the \"Voice\", a consultative body for Indigenous peoples. In New Zealand, Maori seats have existed in Parliament since 1867.*\n\n**Subject.** *\"The law can be a tool for change, but it is not enough.\" Discuss, using at least two of the documents and at least four words from the lesson.*","bareme":[{"critere":"Le droit comme outil d'inclusion et d'exclusion, illustré par la Cour suprême (Plessy puis Brown)","points":5},{"critere":"Limites du droit : logement (Grenfell, council estates) et/ou représentation des peuples premiers (Voice, sièges maoris)","points":5},{"critere":"Argumentation structurée et nuancée, conclusion personnelle","points":4},{"critere":"Correction de la langue, quatre mots du cours employés à bon escient, longueur respectée","points":6}],"dureeMin":20,"corrige":"**Éléments attendus**\n- **Le droit peut exclure puis inclure** : la même Cour suprême légalise la ségrégation en 1896 (*Plessy v. Ferguson*, « separate but equal ») puis l'interdit dans les écoles en 1954 (*Brown*). La Constitution n'a pas changé : la société et les juges, si. On peut ajouter *Loving v. Virginia* (1967), *Obergefell* (2015), le *Fair Housing Act* (1968).\n- **Mais le droit ne suffit pas** : l'incendie de Grenfell (2017, 72 morts) montre la négligence envers les habitants des *council estates* : leurs plaintes n'étaient pas écoutées ; ils sont sous-représentés (*under-represented*).\n- **La représentation** : les sièges maoris en Nouvelle-Zélande (depuis 1867) donnent une voix aux peuples premiers ; en Australie, la *Voice* a été rejetée en 2023 : l'inclusion dépend aussi des électeurs.\n- **Conclusion** : l'égalité sur le papier n'est pas l'égalité en pratique.\n\n**Exemple de copie (≈ 180 mots)**\n*The history of the US Supreme Court shows that the law can be a tool for change. In 1896, the Court declared segregation legal; in 1954, the same Court declared segregation in public schools unconstitutional. The Constitution had not changed, but society and the judges had. This ruling paved the way for civil rights.*\n*However, the law is not enough. In London, the residents of council estates near Grenfell Tower had complained about safety for years, but nobody listened. The fire killed 72 people in 2017. Equality on paper does not mean equality in practice: poor minorities are often under-represented and ignored.*\n*Representation matters too. In New Zealand, Maori seats have existed in Parliament since 1867, but in 2023 Australian voters rejected the Voice for Indigenous peoples.*\n*In conclusion, laws and rulings can open doors, but minorities will only be included when their voices are really heard.*"}$exo$::jsonb),
  ('cf2ca757-1306-5f91-b69b-878220dc8e8d'::uuid, 1, 'traduction', $exo${"titre":"Serve or challenge power?","consigne":"Réponds en anglais, par des phrases complètes.","enonce":"**Six works of art**\n\na. Hans Holbein's portraits of Henry VIII (1530s)\nb. *Strange Fruit*, sung by Billie Holiday (1939)\nc. The *Armada Portrait* of Elizabeth I (around 1588)\nd. *Migrant Mother*, a photo by Dorothea Lange (1936)\ne. Shepard Fairey's *Hope* poster (2008)\nf. *Spitting Image*, a puppet show (1984)\n\n1. Sort the six works into two groups: those which **reinforce** power and those which **challenge** it or denounce injustice.\n2. Choose one work in each group and explain in two sentences what it shows or denounces.\n3. Give the English words for: *la censure* ; *se moquer de* ; *une chanson engagée*.","bareme":[{"critere":"Classement juste des six œuvres en deux groupes","points":6},{"critere":"Deux œuvres expliquées avec précision et en anglais correct","points":10},{"critere":"Trois mots de vocabulaire justes : censorship, to mock, a protest song","points":4}],"dureeMin":8,"corrige":"1. **Reinforce power** : a (Holbein's Henry VIII), c (*Armada Portrait*), e (*Hope*).\n**Challenge power / denounce injustice** : b (*Strange Fruit*), d (*Migrant Mother*), f (*Spitting Image*).\n\n2. Exemples attendus :\n- *In Holbein's portraits, Henry VIII looks massive: he stands with his legs apart and fills the whole space. The painting glorifies the king.*\n- *In the Armada Portrait, Elizabeth I has her hand on a globe: it shows that England is the master of the seas.*\n- *Hope turned Barack Obama's face into an icon of his 2008 campaign.*\n- *Strange Fruit, sung by Billie Holiday in 1939, denounces the lynchings in the South of the United States.*\n- *Migrant Mother, by Dorothea Lange, shows the poverty of the Great Depression.*\n- *Spitting Image mocked Margaret Thatcher and the royal family with puppets.*\n\n3. *la censure* → **censorship** ; *se moquer de* → **to mock** ; *une chanson engagée* → **a protest song**."}$exo$::jsonb),
  ('cf2ca757-1306-5f91-b69b-878220dc8e8d'::uuid, 2, 'traduction', $exo${"titre":"A mural on the town hall","consigne":"Lis le texte (fictif), réponds en anglais aux questions 1 à 3, puis traduis en français la phrase de la question 4.","enonce":"**Text (fictional).**\n\n> *One morning, the inhabitants of a small English town discovered a mural on the wall of their town hall. It showed the mayor as a giant, sitting on a pile of coins, while tiny workers carried him on their backs. Nobody knew who the artist was. The mayor ordered the council to cover the wall with white paint, but a student had already taken a picture of it, and the image spread online. \"Far from glorifying our leaders, it exposes how they treat us,\" a shopkeeper said.*\n\n1. Describe the mural and explain its message.\n2. Why did the mayor want to paint over it? Which word from the lesson describes this reaction?\n3. Which famous anonymous artist, known for his stencils, does this story remind you of? Explain the comparison.\n4. Traduis : *Far from glorifying our leaders, it exposes how they treat us.*","bareme":[{"critere":"Description du mural et message dégagé (le pouvoir porté et ridiculisé, les travailleurs écrasés)","points":5},{"critere":"Réaction du maire analysée et identifiée comme censure (censorship)","points":4},{"critere":"Comparaison pertinente avec Banksy (anonyme, pochoirs, contestation)","points":5},{"critere":"Traduction fidèle (loin de glorifier, révèle / dénonce la façon dont)","points":6}],"dureeMin":12,"corrige":"1. *The mural shows the mayor as a giant sitting on a pile of coins, carried by tiny workers. It mocks the mayor: it suggests that he is rich and powerful thanks to the work of ordinary people, who carry the weight of power. The artist uses exaggeration (a giant, tiny workers) to denounce injustice.*\n\n2. *The mayor wanted to hide a work that challenged his power and made fun of him. This is **censorship**. But it failed: the image spread online.*\n\n3. *It reminds us of **Banksy**, an anonymous street artist who has painted stencils since the 1990s to denounce war, surveillance and consumer society. Like him, the artist of the mural is anonymous and uses a public wall to challenge power.*\n\n4. Traduction proposée : « Loin de glorifier nos dirigeants, il révèle la façon dont ils nous traitent. »\nPoints attendus : *far from* + -ing → « loin de » + infinitif ; *leaders* → « dirigeants » ; *exposes* → « révèle / dénonce / met à nu » ; *how they treat us* → « la façon dont / comment ils nous traitent »."}$exo$::jsonb),
  ('cf2ca757-1306-5f91-b69b-878220dc8e8d'::uuid, 3, 'traduction', $exo${"titre":"The Problem We All Live With","consigne":"Expression écrite en anglais : rédige un texte argumenté d'environ 180 mots en t'appuyant sur le document et sur au moins deux autres œuvres du cours.","enonce":"**Document.** Norman Rockwell, *The Problem We All Live With* (1964).\n\n> *Description: Ruby Bridges, a six-year-old Black girl in a white dress, walks to school. She is escorted by four federal marshals; we only see their bodies, not their heads. On the wall behind her, an insult has been written and a tomato has been thrown.*\n\n**Subject.** *\"Art can reinforce power or challenge it.\" Using the document and at least two other works from the lesson, explain how artists represent power.*\n\nFor each work, ask yourself: who produced it? for which audience? to serve or to challenge power?","bareme":[{"critere":"Analyse du tableau de Rockwell : choix de cadrage (marshals sans tête), sens moral et dénonciation","points":6},{"critere":"Au moins une œuvre au service du pouvoir analysée (Holbein, Armada Portrait, Hope)","points":4},{"critere":"Argumentation structurée qui répond au sujet, appuyée sur les trois questions du cours","points":4},{"critere":"Correction de la langue, vocabulaire du cours (to glorify, to denounce, committed…), longueur respectée","points":6}],"dureeMin":20,"corrige":"**Éléments attendus**\n- **Rockwell** : Ruby Bridges, six ans, escortée par des policiers fédéraux pour aller à l'école. Les *marshals* n'ont pas de tête : le regard se porte sur la petite fille et sur l'insulte écrite au mur. Le tableau transforme un fait d'actualité en **question morale** : il dénonce le racisme ; le titre (*le problème avec lequel nous vivons tous*) implique le spectateur.\n- **Art au service du pouvoir** : Holbein peint Henri VIII massif, jambes écartées, qui occupe tout l'espace ; l'*Armada Portrait* montre Élisabeth Ire la main sur le globe (maîtresse des mers) ; *Hope* fait d'Obama une icône de campagne (2008).\n- **Art qui conteste** : *Strange Fruit* (Billie Holiday, 1939, les lynchages), *Mississippi Goddam* (Nina Simone, 1964), *Migrant Mother* (Lange, 1936), Banksy, Gillray, *Spitting Image*.\n- **Méthode** : qui a commandé ou produit l'œuvre, pour quel public, pour servir ou contester.\n\n**Exemple de copie (≈ 180 mots)**\n*For centuries, art has been used to glorify power. In the 1530s, Holbein painted Henry VIII as a massive king, standing with his legs apart and filling the whole space: the portrait was made to impress his subjects. Around 1588, the Armada Portrait showed Elizabeth I with her hand on a globe, as if England ruled the seas.*\n*But artists can also denounce injustice. In The Problem We All Live With (1964), Norman Rockwell paints Ruby Bridges, a six-year-old girl escorted by federal marshals. The marshals have no heads, so the viewer only sees a little girl and the insult written on the wall. Far from glorifying anyone, the painting exposes racism and turns a news event into a moral question. In the same way, Billie Holiday's Strange Fruit denounced lynchings in 1939.*\n*In conclusion, the same art can serve or challenge power: it depends on who produces it, and for whom.*"}$exo$::jsonb),
  ('456fd206-da1b-5204-adfb-25d15b53b929'::uuid, 1, 'traduction', $exo${"titre":"Milestones of science","consigne":"Réponds en anglais, par des phrases complètes, sauf à la question 3.","enonce":"1. **Match each date with an event and write a full sentence for each one.**\n\nDates : 1818 — 1969 — 1978 — 1996\nEvents : Louise Brown, the first baby conceived by IVF, is born in Oldham ; Mary Shelley publishes *Frankenstein* ; Dolly the sheep is cloned at the Roslin Institute ; Apollo 11 lands on the Moon.\n\n2. Who were the Luddites, and what did they fear?\n\n3. Donne l'équivalent français de : *a breakthrough* ; *a wind farm* ; *to tamper with nature* ; *The benefits outweigh the risks.*","bareme":[{"critere":"Quatre associations date-événement justes, en phrases correctes","points":8},{"critere":"Les luddites présentés (ouvriers qui brisent les machines, 1811-1816) et leur crainte (perdre leur emploi)","points":5},{"critere":"Quatre traductions justes","points":7}],"dureeMin":8,"corrige":"1.\n- *In **1818**, Mary Shelley published Frankenstein.*\n- *In **1969**, Apollo 11 landed on the Moon (on 20 July).*\n- *In **1978**, Louise Brown, the first baby conceived by IVF, was born in Oldham.*\n- *In **1996**, Dolly the sheep was cloned at the Roslin Institute, in Scotland.*\n(Le prétérit est attendu pour des faits datés du passé.)\n\n2. *The Luddites were British textile workers who broke machines between 1811 and 1816. They were afraid of losing their jobs because of the new machines: they refused a technology that threatened employment.*\n\n3. *a breakthrough* → une percée, une avancée décisive ; *a wind farm* → un parc éolien ; *to tamper with nature* → trafiquer la nature ; *The benefits outweigh the risks* → les bénéfices l'emportent sur les risques."}$exo$::jsonb),
  ('456fd206-da1b-5204-adfb-25d15b53b929'::uuid, 2, 'traduction', $exo${"titre":"The lab on the hill","consigne":"Lis le texte (fictif), réponds en anglais aux questions 1 à 3, puis traduis en français la phrase de la question 4.","enonce":"**Text (fictional).**\n\n> *Dr Ellen Moore runs a small laboratory in Scotland. Her team has just made a breakthrough: they can modify the genes of a plant so that it grows without water for weeks. Journalists call it a miracle for farmers in dry countries. But at the village meeting, an old farmer stands up: \"You scientists always say you can do it. Nobody asks if you should.\" Dr Moore answers: \"Science is neither good nor bad in itself. It depends on how we use it.\"*\n\n1. What discovery has Dr Moore's team made? Why do journalists call it a miracle?\n2. Explain the farmer's objection in your own words.\n3. Which famous novel of 1818 also asks whether a scientist is responsible for his creation? Explain the link with the text.\n4. Traduis : *Science is neither good nor bad in itself. It depends on how we use it.*","bareme":[{"critere":"Découverte et intérêt expliqués (génie génétique, plante sans eau, agriculteurs des pays secs)","points":5},{"critere":"Objection du fermier reformulée : possible ne veut pas dire souhaitable","points":4},{"critere":"Frankenstein de Mary Shelley identifié et lien avec la responsabilité du savant","points":5},{"critere":"Traduction fidèle (ni… ni…, en soi, cela dépend de la façon dont)","points":6}],"dureeMin":12,"corrige":"1. *Her team has made a breakthrough in genetic engineering: they can modify the genes of a plant so that it grows without water for weeks. Journalists call it a miracle because it could help farmers in dry countries, where droughts destroy crops.*\n\n2. *The farmer thinks that scientists only ask whether something is possible, never whether it is acceptable. For him, what is possible is not always desirable: there may be limits that should not be crossed when we tamper with nature.*\n\n3. *It is **Frankenstein**, by Mary Shelley (1818). Victor Frankenstein creates a creature and then has to face the consequences. Like the farmer, the novel asks whether the scientist is responsible for what he creates.*\n\n4. Traduction proposée : « La science n'est ni bonne ni mauvaise en soi. Cela dépend de l'usage que nous en faisons / de la façon dont nous l'utilisons. »\nPoints attendus : *neither… nor…* → « ni… ni… » avec la négation « n'est » ; *in itself* → « en soi » ; *how we use it* → « la façon dont nous l'utilisons » (pas « comment nous l'utilisons » au sens interrogatif lourd, accepté cependant)."}$exo$::jsonb),
  ('456fd206-da1b-5204-adfb-25d15b53b929'::uuid, 3, 'traduction', $exo${"titre":"Is everything possible desirable?","consigne":"Expression écrite en anglais : rédige un texte argumenté d'environ 180 mots en t'appuyant sur les documents et sur tes connaissances.","enonce":"**Document A.** *July 1969: Apollo 11 lands on the Moon. Two years earlier, the Outer Space Treaty (1967) stated that space belongs to no State.*\n\n**Document B.** *1996: Dolly the sheep, the first mammal cloned from an adult cell, is born at the Roslin Institute, in Scotland. Many people fear that human cloning will follow.*\n\n**Document C.** *In Brave New World (1932), Aldous Huxley imagines humans who are manufactured and sorted from birth.*\n\n**Subject.** *\"Science is a force for progress, but there are limits that should not be crossed.\" Discuss, using at least two documents and at least four words from the lesson.*\n\nDistinguish between the **discovery** and its **use**.","bareme":[{"critere":"Le progrès scientifique mis en valeur avec des exemples précis (Apollo 11, FIV, énergies renouvelables…)","points":5},{"critere":"Les limites éthiques développées (clonage, transhumanisme, Brave New World)","points":5},{"critere":"Distinction entre la découverte et son usage ; conclusion argumentée","points":4},{"critere":"Correction de la langue, quatre mots du cours bien employés, longueur respectée","points":6}],"dureeMin":20,"corrige":"**Éléments attendus**\n- **Progrès** : Apollo 11 (20 juillet 1969), premier homme sur la Lune ; le traité de l'espace (1967) fait de l'espace un bien qui n'appartient à aucun État ; Louise Brown (1978), premier bébé FIV ; l'Écosse passe du pétrole de la mer du Nord à l'éolien en mer (*wind farms*).\n- **Limites** : Dolly (1996) fait craindre le clonage humain — la plupart des pays l'ont ensuite interdit : certaines choses sont possibles mais pas acceptables. *Brave New World* (1932) imagine des humains fabriqués et triés : le rêve transhumaniste de l'homme parfait peut devenir un cauchemar.\n- **Clé** : la découverte est neutre ; c'est son usage qui se juge.\n\n**Exemple de copie (≈ 180 mots)**\n*Science has brought extraordinary breakthroughs. On 20 July 1969, Apollo 11 landed on the Moon, and the Outer Space Treaty of 1967 had already stated that space belongs to no State. In 1978, Louise Brown was the first baby conceived by IVF: science helped couples who could not have children. Today, Scotland produces renewable energy with offshore wind farms.*\n*However, some discoveries raise ethical questions. When Dolly the sheep was cloned in 1996, many people feared that human cloning would follow, and most countries banned it. As early as 1932, Aldous Huxley imagined in Brave New World humans manufactured and sorted from birth. Genetic engineering could lead us to tamper with nature in the same way.*\n*In my opinion, science is neither good nor bad in itself: a discovery is neutral, but its use must be judged. Society has to decide which limits should not be crossed.*"}$exo$::jsonb),
  ('8efd6d83-8333-50f4-9710-70cf535ff35d'::uuid, 1, 'traduction', $exo${"titre":"Protect, admire, suffer","consigne":"Réponds en anglais, par des phrases complètes, sauf à la question 3.","enonce":"1. **Match each person with what he or she did, and write a sentence for each one.**\n\nPeople : John Muir — Rachel Carson — Henry David Thoreau — John Steinbeck — William Wordsworth\nActions : wrote about the daffodils of the Lake District ; spent two years in a cabin near a lake and wrote *Walden* ; founded the Sierra Club in 1892 ; denounced pesticides in *Silent Spring* ; told the story of the Dust Bowl in *The Grapes of Wrath*.\n\n2. What was created at Yellowstone in 1872?\n\n3. Donne l'équivalent français de : *a drought* ; *wildlife* ; *endangered species* ; *a wildfire*.","bareme":[{"critere":"Cinq associations justes, en phrases correctes au prétérit","points":10},{"critere":"Yellowstone : le premier parc national du monde","points":3},{"critere":"Quatre traductions justes","points":7}],"dureeMin":8,"corrige":"1.\n- *John Muir founded the Sierra Club in 1892.*\n- *Rachel Carson denounced pesticides in Silent Spring (1962).*\n- *Henry David Thoreau spent two years in a cabin near a lake and wrote Walden (1854).*\n- *John Steinbeck told the story of the Dust Bowl in The Grapes of Wrath (1939).*\n- *William Wordsworth wrote about the daffodils of the Lake District (I Wandered Lonely as a Cloud, 1807).*\n(Les dates ne sont pas exigées.)\n\n2. *In 1872, Yellowstone became the first national park in the world.*\n\n3. *a drought* → une sécheresse ; *wildlife* → la faune sauvage ; *endangered species* → les espèces menacées ; *a wildfire* → un feu de forêt."}$exo$::jsonb),
  ('8efd6d83-8333-50f4-9710-70cf535ff35d'::uuid, 2, 'traduction', $exo${"titre":"After the storm","consigne":"Lis le texte (fictif), réponds en anglais aux questions 1 à 3, puis traduis en français la phrase de la question 4.","enonce":"**Text (fictional).**\n\n> *August 2005. When Hurricane Katrina hit New Orleans, Denise, a cleaner, had no car. The authorities had told people to leave the city, but how could she leave? She stayed in her house in a poor neighbourhood near the levees. The water rose up to the roof. Twelve miles away, in a richer area built on higher ground, her employer's house was only slightly damaged. \"The storm was the same for everybody,\" Denise says today. \"The disaster was not.\"*\n\n1. Why couldn't Denise leave New Orleans?\n2. Compare the situations of Denise and her employer. What does the comparison show?\n3. Explain the last sentence: *The storm was the same for everybody. The disaster was not.*\n4. Traduis : *Natural disasters are not only natural: they hit the poorest hardest.*","bareme":[{"critere":"Raison du maintien de Denise identifiée (pas de voiture, pauvreté)","points":3},{"critere":"Comparaison des deux situations et idée d'inégalité face à la catastrophe","points":6},{"critere":"Dernière phrase expliquée : phénomène naturel, catastrophe aussi sociale","points":5},{"critere":"Traduction fidèle (ne sont pas seulement, frappent le plus durement les plus pauvres)","points":6}],"dureeMin":12,"corrige":"1. *She couldn't leave because she had no car: she was poor and had no means of transport, even though the authorities had told people to leave the city.*\n\n2. *Denise lived in a poor neighbourhood near the levees, and the water rose up to her roof. Her employer lived in a richer area built on higher ground, and her house was only slightly damaged. The comparison shows that the poorest were the worst hit: Katrina was a natural disaster aggravated by inequalities.*\n\n3. *The hurricane itself was a natural event that hit the whole city. But its consequences depended on people's wealth: the poor could not escape and lived in the most exposed areas. The storm was natural; the disaster was also social.*\n\n4. Traduction proposée : « Les catastrophes naturelles ne sont pas seulement naturelles : elles frappent plus durement les plus pauvres. »\nPoints attendus : *not only* → « pas seulement / pas uniquement » ; *hit* (présent) → « frappent » ; *the poorest* → « les plus pauvres » ; *hardest* → « le plus durement / plus durement »."}$exo$::jsonb),
  ('8efd6d83-8333-50f4-9710-70cf535ff35d'::uuid, 3, 'traduction', $exo${"titre":"Keeping people out to protect nature?","consigne":"Expression écrite en anglais : rédige un texte argumenté d'environ 180 mots en t'appuyant sur les documents et sur tes connaissances.","enonce":"**Document A.** *1872: Yellowstone becomes the first national park in the world. 1892: John Muir founds the Sierra Club to protect the wilderness for itself.*\n\n**Document B.** *1951: Britain creates its first national parks, the Peak District and then the Lake District. They protect landscapes where people live and farm.*\n\n**Document C (fictional).** *A park ranger in the United States: \"Every summer, thousands of cars queue at the entrance. Sometimes I think the only way to protect this place would be to close it.\"*\n\n**Subject.** *\"Protecting nature sometimes means keeping people out.\" Do you agree? Use at least two documents and the difference between **preserving** and **conserving**.*","bareme":[{"critere":"Modèle américain de la wilderness préservée (Yellowstone, Muir) expliqué","points":5},{"critere":"Modèle britannique des paysages habités et distinction préserver / conserver expliquée","points":5},{"critere":"Prise de position argumentée et nuancée, appuyée sur le document C","points":4},{"critere":"Correction de la langue, vocabulaire du cours, longueur respectée","points":6}],"dureeMin":20,"corrige":"**Éléments attendus**\n- **Préserver** : garder intact. Yellowstone (1872), premier parc national ; John Muir et le Sierra Club (1892) protègent la *wilderness* pour elle-même ; Theodore Roosevelt multiplie les espaces protégés. Le document C montre la limite : trop de visiteurs menacent le lieu.\n- **Conserver** : utiliser sans épuiser. Les parcs britanniques (1951, Peak District puis Lake District) protègent des paysages **habités et cultivés** : l'homme en fait partie.\n- **Position** : on peut défendre l'idée qu'il faut parfois tenir l'homme à distance, ou qu'il faut plutôt apprendre à vivre avec la nature (*Man is part of nature, not its master*). Une réponse nuancée est valorisée.\n\n**Exemple de copie (≈ 180 mots)**\n*Americans invented the national park. In 1872, Yellowstone became the first national park in the world, and in 1892 John Muir founded the Sierra Club to protect the wilderness for itself. For Muir, nature had to be preserved, which means kept intact. Today, the ranger in document C seems to agree: thousands of cars queue at the entrance every summer, and he thinks closing the park would protect it.*\n*However, the British model is different. In 1951, Britain created its first national parks, the Peak District and the Lake District, to protect landscapes where people live and farm. Here, the aim is to conserve nature: to use it without depleting its resources.*\n*In my opinion, keeping people out may be necessary in some fragile places, to protect wildlife and endangered species. But in most cases, we should learn to live in harmony with nature, because man is part of nature, not its master.*"}$exo$::jsonb),
  ('3b94e0cd-764f-5a8e-a21b-7bfdbb517f99'::uuid, 1, 'traduction', $exo${"titre":"English across the Americas","consigne":"Réponds en anglais, par des phrases complètes, sauf à la question 3.","enonce":"1. **Right or wrong? Correct the wrong sentences.**\n   a. Canada has two official languages: English and Spanish.\n   b. Jamaica became independent in 1962.\n   c. Barbados became a republic on 30 November 2021.\n   d. The head of State of Canada is the Canadian Prime Minister.\n   e. The Monroe Doctrine (1823) stated that Europeans should no longer intervene in America.\n\n2. What is the USMCA, and which agreement did it replace?\n\n3. Donne l'équivalent français de : *brain drain* ; *soft power* ; *a trade agreement*.","bareme":[{"critere":"Cinq réponses right/wrong justes, phrases fausses corrigées (anglais et français ; le roi Charles III)","points":10},{"critere":"USMCA présenté (accord commercial États-Unis, Canada, Mexique, 2020) et ALENA / NAFTA cité","points":5},{"critere":"Trois traductions justes","points":5}],"dureeMin":8,"corrige":"1.\na. **Wrong**: *Canada has two official languages: English and **French**.*\nb. **Right**.\nc. **Right**.\nd. **Wrong**: *The head of State of Canada is **King Charles III**.*\ne. **Right**: *the American continent became the zone of influence of the United States.*\n\n2. *The USMCA (ACEUM in French) is a trade agreement between the United States, Canada and Mexico. It replaced NAFTA (ALENA, 1994) in 2020.*\n\n3. *brain drain* → la fuite des cerveaux ; *soft power* → l'influence culturelle (l'attrait d'un pays) ; *a trade agreement* → un accord commercial."}$exo$::jsonb),
  ('3b94e0cd-764f-5a8e-a21b-7bfdbb517f99'::uuid, 2, 'traduction', $exo${"titre":"A Canadian in Los Angeles","consigne":"Lis le texte (fictif), réponds en anglais aux questions 1 à 3, puis traduis en français la phrase de la question 4.","enonce":"**Text (fictional).**\n\n> *Noah grew up in Winnipeg. After his studies, he wanted to become a sound engineer, but the best studios were in Los Angeles. He moved there at twenty-three, like many young Canadian artists before him. \"At home, everybody watches American series and listens to American music,\" he says. \"But here, in LA, I work with a producer who grew up in Jamaica, and we mix reggae with pop. Americans think they export their culture to the world. They don't realise how much they import.\"*\n\n1. Why did Noah leave Canada? What phenomenon does his story illustrate?\n2. Quote the sentence showing American *soft power* in Canada.\n3. How does Noah's job show that *the influence goes both ways*? Give one more example from the lesson.\n4. Traduis : *Americans think they export their culture to the world. They don't realise how much they import.*","bareme":[{"critere":"Départ expliqué et fuite des cerveaux (brain drain) identifiée","points":5},{"critere":"Citation juste illustrant le soft power américain","points":3},{"critere":"Influence réciproque expliquée avec le texte et un exemple du cours (reggae, Rihanna, hip-hop, Drake…)","points":6},{"critere":"Traduction fidèle (se rendent compte, à quel point)","points":6}],"dureeMin":12,"corrige":"1. *Noah left Canada because the best studios were in Los Angeles: he wanted better opportunities for his career. His story illustrates the **brain drain**: researchers and artists from Canada or the Caribbean leave for the United States.*\n\n2. *\"At home, everybody watches American series and listens to American music.\"*\n\n3. *Noah works with a producer who grew up in Jamaica and they mix reggae with pop: Caribbean culture enters American music. The influence does not only go from the US to its neighbours. Other examples: Bob Marley's reggae spread from Jamaica to the world; Rihanna, from Barbados, became a global star; hip-hop was born in the Bronx in the 1970s thanks partly to DJ Kool Herc, who had grown up in Jamaica; Canadian singers like Drake or Justin Bieber are stars in the US.* (Un exemple suffit.)\n\n4. Traduction proposée : « Les Américains pensent qu'ils exportent leur culture dans le monde entier. Ils ne se rendent pas compte de tout ce qu'ils importent / à quel point ils importent. »\nPoints attendus : *don't realise* → « ne se rendent pas compte » (pas « ne réalisent pas », anglicisme toléré mais pénalisé légèrement) ; *how much* → « à quel point / combien »."}$exo$::jsonb),
  ('3b94e0cd-764f-5a8e-a21b-7bfdbb517f99'::uuid, 3, 'traduction', $exo${"titre":"A one-way influence?","consigne":"Expression écrite en anglais : rédige un texte argumenté d'environ 180 mots en t'appuyant sur les documents et sur tes connaissances.","enonce":"**Document A.** *1823: the Monroe Doctrine declares that Europeans must no longer intervene in America. 1994: NAFTA links the United States, Canada and Mexico; it is replaced in 2020 by the USMCA.*\n\n**Document B.** *\"Canada defines itself partly against the United States.\" (common saying)*\n\n**Document C.** *Hip-hop was born in the Bronx in the 1970s, partly thanks to DJ Kool Herc, who had grown up in Jamaica.*\n\n**Subject.** *\"American culture is everywhere, yet the influence goes both ways.\" To what extent is the cultural permeability around the American continent unequal? Use at least two documents and four words from the lesson.*","bareme":[{"critere":"Domination des États-Unis montrée (doctrine Monroe, commerce, soft power, fuite des cerveaux)","points":5},{"critere":"Influences qui remontent montrées (reggae, hip-hop, Rihanna, artistes canadiens, Windrush) et identité canadienne","points":5},{"critere":"Réponse nuancée au « to what extent » : perméabilité réelle mais inégale","points":4},{"critere":"Correction de la langue, quatre mots du cours, longueur respectée","points":6}],"dureeMin":20,"corrige":"**Éléments attendus**\n- **Un pôle dominant** : la doctrine Monroe (1823) fait du continent la zone d'influence des États-Unis ; le commerce (ALENA 1994, ACEUM/USMCA 2020) ; le *soft power* (cinéma, musique, réseaux sociaux) ; la fuite des cerveaux vers les États-Unis.\n- **Des influences en retour** : reggae de Bob Marley, Rihanna (Barbade), le hip-hop né dans le Bronx grâce à DJ Kool Herc qui avait grandi en Jamaïque ; artistes canadiens (Drake, Justin Bieber) ; Caraïbes → Royaume-Uni (Windrush, carnaval).\n- **Résistances** : le Canada se définit en partie contre les États-Unis (deux langues officielles, roi Charles III chef d'État).\n- **Conclusion** : la circulation n'est jamais à sens unique, mais elle est **inégale** : les États-Unis exportent bien plus qu'ils n'importent.\n\n**Exemple de copie (≈ 180 mots)**\n*Since the Monroe Doctrine of 1823, the American continent has been the zone of influence of the United States. Today, trade agreements like NAFTA and then the USMCA link the US to Canada and Mexico, and American soft power is everywhere: films, music and social networks spread across the continent. Many Canadian and Caribbean artists and researchers also leave for the US: this is the brain drain.*\n*Yet the influence goes both ways. Hip-hop was born in the Bronx in the 1970s, partly thanks to DJ Kool Herc, who had grown up in Jamaica. Bob Marley's reggae conquered the world, and Rihanna, from Barbados, is a global star. Canada also resists: it defines itself partly against its powerful neighbour, with two official languages and a king as head of State.*\n*To conclude, cultural permeability is real, but it is unequal: the United States export much more than they import, even if local cultures keep their voice.*"}$exo$::jsonb),
  ('ea540e90-afbd-5ab7-8dde-9f6f8fba3d80'::uuid, 1, 'traduction', $exo${"titre":"Puerto Rico in five dates","consigne":"Réponds en anglais, par des phrases complètes, sauf à la question 3.","enonce":"1. **Match each date with an event, and write a full sentence for each one.**\n\nDates : 1898 — 1917 — 1952 — 2017\nEvents : Hurricane Maria devastates the island ; the Jones Act makes Puerto Ricans American citizens ; Spain cedes Puerto Rico to the United States ; Puerto Rico becomes a Commonwealth (free associated State).\n\n2. **Right or wrong?** Justify.\n   a. Puerto Ricans living on the island can vote in the US presidential election.\n   b. Puerto Rico is the 51st State of the United States.\n\n3. Donne l'équivalent français de : *statehood* ; *citizenship* ; *to be entitled to*.","bareme":[{"critere":"Quatre associations date-événement justes, en phrases correctes","points":8},{"critere":"Deux réponses fausses repérées et justifiées (pas de vote présidentiel depuis l'île, pas un État)","points":6},{"critere":"Trois traductions justes","points":6}],"dureeMin":8,"corrige":"1.\n- *In **1898**, Spain ceded Puerto Rico to the United States after the Spanish-American War.*\n- *In **1917**, the Jones Act made Puerto Ricans American citizens.*\n- *In **1952**, Puerto Rico became a Commonwealth (a free associated State).*\n- *In **2017**, Hurricane Maria devastated the island, and relief was slow.*\n\n2.\na. **Wrong**: *Puerto Ricans are American citizens, but they cannot vote in the presidential election from the island. They only have a resident commissioner in Congress, who cannot vote in plenary sessions.*\nb. **Wrong**: *Puerto Rico is not a State; its status is debated, and several non-binding referendums have been held (2012-2024).*\n\n3. *statehood* → le statut d'État ; *citizenship* → la citoyenneté ; *to be entitled to* → avoir droit à."}$exo$::jsonb),
  ('ea540e90-afbd-5ab7-8dde-9f6f8fba3d80'::uuid, 2, 'traduction', $exo${"titre":"Twin cities of the Pacific Northwest","consigne":"Lis le document, puis réponds en anglais aux questions 1 à 3 et traduis en français la phrase de la question 4.","enonce":"**Document.**\n\n| | Vancouver (Canada) | Seattle (United States) |\n| Economy | Port, film industry (\"Hollywood North\"), technology | Boeing, Microsoft (in Redmond), Amazon (headquarters, founded in 1994), Starbucks (1971) |\n| Big events | 2010 Winter Olympics | 1962 World's Fair (Space Needle) |\n| Common challenges | Housing prices, homelessness | Housing prices, homelessness |\n\n1. Where are the two cities? Why can we call them *twin cities*?\n2. Compare their economies: give one difference and one similarity.\n3. Which international sporting event did both cities host in 2026, and which three countries organised it?\n4. Traduis : *Although they are on different sides of the border, the two cities share the same housing crisis.*","bareme":[{"critere":"Situation (Pacific Northwest, de part et d'autre de la frontière) et idée de villes jumelles","points":4},{"critere":"Une différence et une ressemblance économiques justes, tirées du document","points":5},{"critere":"Coupe du monde de football 2026, Canada, États-Unis et Mexique","points":4},{"critere":"Traduction fidèle (bien que + subjonctif, de part et d'autre, crise du logement)","points":7}],"dureeMin":12,"corrige":"1. *Both cities are in the Pacific Northwest, a few hours' drive apart, on either side of the border between Canada and the United States. We can call them twin cities because they look alike: they are big port cities with similar economies and the same problems.*\n\n2. Différence (une suffit) : *Vancouver is known for its film industry (\"Hollywood North\"), whereas Seattle is home to big companies like Boeing, Microsoft (in Redmond), Amazon or Starbucks.* Ressemblance : *both have a technology sector*, ou *both face high housing prices and homelessness.*\n\n3. *Both cities hosted matches of the **2026 FIFA World Cup**, organised by **Canada, the United States and Mexico**.*\n\n4. Traduction proposée : « Bien qu'elles soient de part et d'autre de la frontière / de chaque côté de la frontière, les deux villes connaissent la même crise du logement. »\nPoints attendus : *although* → « bien que » + **subjonctif** (« soient ») ; *on different sides of the border* → « de part et d'autre de la frontière » ; *share* → « partagent / connaissent » ; *housing crisis* → « crise du logement »."}$exo$::jsonb),
  ('ea540e90-afbd-5ab7-8dde-9f6f8fba3d80'::uuid, 3, 'traduction', $exo${"titre":"Second-class citizens?","consigne":"Expression écrite en anglais : rédige un texte argumenté d'environ 180 mots en t'appuyant sur le document et sur tes connaissances.","enonce":"**Document (fictional testimony).**\n\n> *\"My cousin lives in Florida. She votes for the president. I live in San Juan, I have the same passport, I pay the same price for gas, and I cannot vote. After Hurricane Maria, we waited weeks for electricity. On TV, I heard people ask if we were even Americans. We are. But are we treated like it?\"* — Marisol, 34\n\n**Subject.** *\"Puerto Rico shows that you can belong to a country without being fully part of it.\" Explain this statement, then say whether Puerto Rico should become the 51st State. Use the document, your knowledge and at least four words from the lesson (e.g. statehood, citizenship, to be entitled to, relief).*","bareme":[{"critere":"Statut expliqué : citoyens depuis 1917, État libre associé depuis 1952, pas de vote présidentiel, commissaire résident sans vote","points":5},{"critere":"Document exploité : Maria (2017), secours tardifs, sentiment d'être des citoyens de seconde zone","points":4},{"critere":"Position argumentée sur le statut d'État, en mentionnant les référendums et l'identité culturelle","points":5},{"critere":"Correction de la langue, quatre mots du cours, longueur respectée","points":6}],"dureeMin":20,"corrige":"**Éléments attendus**\n- **Appartenance** : île cédée par l'Espagne en 1898 ; le *Jones Act* (1917) fait des Portoricains des **citoyens américains** ; État libre associé (*Commonwealth*) depuis 1952.\n- **Sans tous les droits** : l'île n'est pas un État ; ses habitants **ne votent pas** à la présidentielle depuis l'île (sauf s'ils s'installent dans l'un des cinquante États, comme la cousine de Marisol en Floride) ; un seul **commissaire résident** au Congrès, sans droit de vote en séance plénière.\n- **Maria (2017)** : les secours tardent ; beaucoup se sentent citoyens de seconde zone.\n- **Le débat** : plusieurs référendums non contraignants (2012-2024) ; une identité propre (l'espagnol domine, l'anglais est aussi officiel ; Lin-Manuel Miranda, Bad Bunny). Toute position argumentée est acceptée.\n\n**Exemple de copie (≈ 180 mots)**\n*Puerto Ricans have been American citizens since the Jones Act of 1917. They have the same passport as Americans in Florida or Texas. However, the island is not a State but a Commonwealth, since 1952. As a consequence, Puerto Ricans living on the island are not entitled to vote in the presidential election, and they only have a resident commissioner in Congress, who cannot vote in plenary sessions. Marisol's cousin can vote only because she moved to Florida.*\n*After Hurricane Maria in 2017, relief was slow and many people felt treated like second-class citizens. It shows that citizenship without all the rights is fragile.*\n*Should Puerto Rico become the 51st State? Statehood would give its people full political rights. But the island has its own identity: Spanish is dominant, and artists like Bad Bunny are proud of this culture. The several referendums held since 2012 were not binding. In my opinion, the choice must belong to Puerto Ricans themselves.*"}$exo$::jsonb),
  ('d76ec20f-5f2d-5124-851d-1418372353d7'::uuid, 1, 'traduction', $exo${"titre":"Wish, hope, it's time : huit phrases à compléter","consigne":"Complète chaque phrase avec la forme correcte du verbe entre parenthèses (ou le bon verbe), puis réponds à la question 2.","enonce":"**1. Complète.**\n\n1. I wish I ___ (know) the answer. *(je ne la connais pas)*\n2. I wish I ___ (study) harder last year.\n3. I wish you ___ (stop) shouting! *(agacement)*\n4. I ___ (hope / wish) you pass your exam tomorrow.\n5. It's high time we ___ (leave).\n6. I'd rather you ___ (not tell) anyone.\n7. I'd rather ___ (stay) at home tonight. *(pour moi-même)*\n8. If only I ___ (listen) to her! *(regret sur le passé)*\n\n**2.** Dans la phrase 1, le verbe est au prétérit alors qu'on parle du présent. Explique pourquoi en une ou deux phrases.","bareme":[{"critere":"Phrases 1, 2, 3 et 8 justes : knew, had studied, would stop, had listened","points":8},{"critere":"Phrase 4 : hope (souhait possible)","points":2},{"critere":"Phrases 5, 6 et 7 justes : left, didn't tell, stay","points":6},{"critere":"Explication du prétérit modal (irréel du présent)","points":4}],"dureeMin":7,"corrige":"**1.**\n1. *I wish I **knew** the answer.* — regret sur le présent : *wish* + prétérit.\n2. *I wish I **had studied** harder last year.* — regret sur le passé : *wish* + past perfect.\n3. *I wish you **would stop** shouting!* — comportement de quelqu'un d'autre qui agace : *wish* + sujet + *would*.\n4. *I **hope** you pass your exam tomorrow.* — c'est possible : *hope*, pas *wish*.\n5. *It's high time we **left**.* — *it's (high) time* + sujet + prétérit.\n6. *I'd rather you **didn't tell** anyone.* — *I'd rather* + autre sujet + prétérit.\n7. *I'd rather **stay** at home tonight.* — pour soi-même : *I'd rather* + base verbale (pas *to stay*).\n8. *If only I **had listened** to her!* — regret sur le passé : past perfect.\n\n**2.** Après *wish*, le prétérit ne parle pas du passé : c'est un **prétérit modal**, qui exprime l'**irréel**. On recule le temps d'un cran pour dire que la situation n'est pas vraie (je ne connais pas la réponse). C'est le même mécanisme que dans *If I were rich…*"}$exo$::jsonb),
  ('d76ec20f-5f2d-5124-851d-1418372353d7'::uuid, 2, 'traduction', $exo${"titre":"Le contrôle raté de Yanis","consigne":"Traduis le texte en anglais (thème). Choisis avec soin la structure qui exprime chaque souhait ou regret.","enonce":"**Thème : traduis en anglais.**\n\n> Yanis a raté son contrôle de maths. « Je regrette de ne pas avoir révisé ! Si seulement j'avais écouté mon professeur ! J'aimerais être plus organisé. Il est grand temps que je change mes habitudes. Je préférerais que mes parents ne l'apprennent pas. J'espère que je réussirai le prochain. »\n\n*Aide : rater = to fail ; réviser = to revise ; changer ses habitudes = to change one's habits ; apprendre (une nouvelle) = to find out.*","bareme":[{"critere":"Regrets sur le passé : wish + past perfect et if only + past perfect (had revised, had listened)","points":6},{"critere":"Regret présent : I wish I were (was) more organised","points":3},{"critere":"It's high time I changed et I'd rather my parents didn't find out","points":6},{"critere":"Hope + présent ou futur pour le souhait possible ; sens général, orthographe","points":5}],"dureeMin":11,"corrige":"**Traduction modèle**\n\n*Yanis failed his maths test. \"I wish I had revised! If only I had listened to my teacher! I wish I were more organised. It's high time I changed my habits. I'd rather my parents didn't find out. I hope I pass the next one.\"*\n\n**Points attendus**\n- « Je regrette de ne pas avoir révisé » → *I wish I **had revised*** (regret sur le passé, past perfect). On accepte *I should have revised* (même regret, vu comme un reproche fait à soi-même).\n- « Si seulement j'avais écouté » → *If only I **had listened***.\n- « J'aimerais être plus organisé » (mais je ne le suis pas) → *I wish I **were** more organised* ; *was* accepté (oral).\n- « Il est grand temps que je change » → *It's high time I **changed*** : sujet + prétérit (pas *It's time to change*, puisqu'il y a un sujet exprimé ; *It's high time for me to change* toléré).\n- « Je préférerais que mes parents ne l'apprennent pas » → *I'd rather my parents **didn't find out*** : autre sujet + prétérit.\n- « J'espère que je réussirai » → *I **hope** I pass / I will pass* : c'est possible, donc *hope* et non *wish*.\n- *failed* au prétérit (action datée) ; *maths test*."}$exo$::jsonb),
  ('d76ec20f-5f2d-5124-851d-1418372353d7'::uuid, 3, 'traduction', $exo${"titre":"Regrets d'un été","consigne":"Corrige et justifie, puis rédige un court paragraphe en anglais en employant les structures demandées.","enonce":"**1. Chaque phrase contient une erreur. Corrige-la et justifie en une phrase.**\n\na. I wish I will know how to swim.\nb. I hope I had gone to the concert last week.\nc. It's time we go home.\nd. I'd rather to walk.\ne. I wish I spoke to her yesterday.\n\n**2. Expression.** Tu n'es pas parti(e) en vacances avec tes amis l'été dernier, et tu le regrettes. En 6 à 8 phrases en anglais, exprime tes regrets et tes souhaits. Emploie **obligatoirement** :\n- *wish* + prétérit ;\n- *wish* + past perfect ;\n- *if only* ;\n- *it's high time* + sujet ;\n- *I'd rather* + sujet ;\n- *should have*.\nSouligne chaque structure.","bareme":[{"critere":"Cinq erreurs corrigées","points":5},{"critere":"Cinq justifications grammaticales exactes (irréel, possible, sujet + prétérit, base verbale, past perfect)","points":5},{"critere":"Les six structures employées correctement dans le paragraphe","points":6},{"critere":"Paragraphe cohérent, sens clair, langue correcte","points":4}],"dureeMin":18,"corrige":"**1.**\na. *I wish I **knew** how to swim.* — regret sur le présent : *wish* + prétérit, jamais *will*.\nb. *I **wish** I had gone to the concert last week.* — c'est trop tard, donc irréel : *wish*, pas *hope* (réservé au possible).\nc. *It's time we **went** home.* — *it's time* + sujet + **prétérit** (ou *It's time to go home* sans sujet).\nd. *I'd rather **walk**.* — pour soi-même : *I'd rather* + base verbale, sans *to*.\ne. *I wish I **had spoken** to her yesterday.* — regret sur le passé (*yesterday*) : past perfect.\n\n**2. Exemple de paragraphe**\n*Last summer, my friends went to Scotland without me. I **wish I had gone** with them! **If only I had saved** more money! I **should have** worked in June instead of doing nothing. Now I **wish I had** photos and memories like them. My parents keep talking about it, but **I'd rather they didn't** mention it. **It's high time I organised** my own trip: next summer, I will go.*\n\nOn vérifie : *wish* + prétérit (*I wish I had photos* : regret présent), *wish* + past perfect (*I wish I had gone*), *if only* (+ past perfect ici), *it's high time* + sujet + prétérit (*I organised*), *I'd rather* + sujet + prétérit (*they didn't*), *should have* + participe passé (*should have worked*). Toute production correcte qui emploie les six structures est acceptée."}$exo$::jsonb),
  ('899fc82c-176a-51e2-92ea-e5f2c8b9eb4f'::uuid, 1, 'traduction', $exo${"titre":"Le bon remplaçant du modal","consigne":"Complète chaque phrase avec be able to, have to, be allowed to (au bon temps), could, managed to, mustn't ou don't have to.","enonce":"**Complète.**\n\n1. She ___ drive next year. *(elle pourra)*\n2. I ___ sleep for three nights. *(je n'ai pas pu, depuis trois nuits)*\n3. At ten, he ___ swim. *(il savait nager)*\n4. The sea was rough, but she ___ swim to the shore. *(elle a réussi, cette fois-là)*\n5. You ___ come: the meeting is optional. *(ce n'est pas la peine)*\n6. You ___ smoke here: it's forbidden.\n7. Last year, we ___ wear a uniform. *(on devait, c'était le règlement)*\n8. We ___ use our phones in class. *(on n'avait pas le droit)*","bareme":[{"critere":"Phrases 1 et 2 justes : will be able to, haven't been able to","points":5},{"critere":"Phrases 3 et 4 justes : could / was able to (ou managed to)","points":5},{"critere":"Phrases 5 et 6 justes : don't have to / mustn't","points":5},{"critere":"Phrases 7 et 8 justes : had to / weren't allowed to","points":5}],"dureeMin":7,"corrige":"1. *She **will be able to** drive next year.* — *can* n'a pas de futur (*will can* est impossible).\n2. *I **haven't been able to** sleep for three nights.* — present perfect : il faut *be able to*.\n3. *At ten, he **could** swim.* — capacité générale dans le passé.\n4. *The sea was rough, but she **was able to** (ou **managed to**) swim to the shore.* — réussite ponctuelle : pas *could* à l'affirmatif.\n5. *You **don't have to** come.* — absence d'obligation.\n6. *You **mustn't** smoke here.* — interdiction.\n7. *Last year, we **had to** wear a uniform.* — *must* n'a pas de passé ; obligation extérieure (règlement).\n8. *We **weren't allowed to** use our phones in class.* — permission refusée, au passé.\n\nChaque phrase vaut 2,5 points ; une forme juste au mauvais temps perd la moitié des points."}$exo$::jsonb),
  ('899fc82c-176a-51e2-92ea-e5f2c8b9eb4f'::uuid, 2, 'traduction', $exo${"titre":"La nouvelle école d'Inès","consigne":"Traduis le texte en anglais (thème). Choisis pour chaque verbe modal le bon équivalent et le bon temps.","enonce":"**Thème : traduis en anglais.**\n\n> Quand elle était petite, ma sœur Inès savait déjà lire. L'an dernier, elle a dû changer d'école. Au début, elle n'avait pas le droit de sortir seule, mais elle a réussi à se faire des amis. Bientôt, elle pourra aller au lycée à vélo. Ce n'est pas la peine de t'inquiéter pour elle !\n\n*Aide : se faire des amis = to make friends ; à vélo = by bike ; s'inquiéter = to worry.*","bareme":[{"critere":"Capacité générale passée (could read) et réussite ponctuelle (managed to / was able to)","points":6},{"critere":"Obligation passée (had to) et permission refusée (wasn't allowed to)","points":6},{"critere":"Futur de la capacité (will be able to) et absence d'obligation (don't have to)","points":5},{"critere":"Sens général, temps du récit, orthographe","points":3}],"dureeMin":11,"corrige":"**Traduction modèle**\n\n*When she was little, my sister Inès **could** already read. Last year, she **had to** change schools. At first, she **wasn't allowed to** go out alone, but she **managed to** make friends. Soon, she **will be able to** go to high school by bike. You **don't have to** worry about her!*\n\n**Points attendus**\n- « savait déjà lire » : capacité **générale** dans le passé → *could* (ou *was able to*).\n- « a dû changer » : *must* n'a pas de passé → *had to* (*changer d'école* → *change schools*).\n- « n'avait pas le droit » → *wasn't allowed to*.\n- « a réussi à se faire des amis » : réussite **ponctuelle** → *managed to* ou *was able to* ; *could make friends* est fautif à l'affirmatif.\n- « pourra » : *will can* impossible → *will be able to*.\n- « Ce n'est pas la peine de » : absence d'obligation → *don't have to* (et surtout pas *mustn't*, qui interdirait).\n- *go to school* : on accepte *secondary school* ou *high school* pour « lycée »."}$exo$::jsonb),
  ('899fc82c-176a-51e2-92ea-e5f2c8b9eb4f'::uuid, 3, 'traduction', $exo${"titre":"Le règlement de la sortie scolaire","consigne":"Explique les différences de sens, corrige les erreurs, puis rédige un court règlement en anglais.","enonce":"**1. Explique en français la différence de sens entre les deux phrases de chaque paire.**\n\na. *You mustn't tell him.* / *You don't have to tell him.*\nb. *I must call my mum.* / *I have to wear a helmet at the skatepark.*\nc. *At ten, she could ski.* / *That day, she managed to ski down the black run.*\n\n**2. Corrige chaque phrase et justifie.**\n\na. She will can come on Saturday.\nb. I musted leave early yesterday.\nc. Last night, the fire was huge, but he could escape.\n\n**3. Expression.** Rédige en anglais le règlement d'une sortie scolaire à Londres (5 phrases), en employant *have to*, *don't have to*, *mustn't*, *be allowed to* et *ought to*.","bareme":[{"critere":"Paire a : interdiction contre absence d'obligation","points":3},{"critere":"Paires b et c : origine de l'obligation, capacité générale contre réussite ponctuelle","points":5},{"critere":"Trois corrections justes et justifiées (will be able to, had to, managed to / was able to)","points":6},{"critere":"Règlement : les cinq structures employées avec le bon sens, langue correcte","points":6}],"dureeMin":18,"corrige":"**1.**\na. *You mustn't tell him* : **interdiction** (tu ne dois pas le lui dire). *You don't have to tell him* : **absence d'obligation** (ce n'est pas la peine de le lui dire, mais tu peux).\nb. *must* : l'obligation vient de **celui qui parle** (je me l'impose : je dois appeler ma mère). *have to* : l'obligation vient de **l'extérieur**, d'une règle (le règlement du skatepark impose le casque).\nc. *could* : **capacité générale** dans le passé (à dix ans, elle savait skier). *managed to* : **réussite ponctuelle**, une fois (ce jour-là, elle a réussi à descendre la piste noire).\n\n**2.**\na. *She **will be able to** come on Saturday.* — deux modaux ne se suivent jamais, *can* n'a pas de futur.\nb. *I **had to** leave early yesterday.* — *must* n'a pas de passé : on emploie *had to*.\nc. *…, but he **managed to** (ou **was able to**) escape.* — réussite ponctuelle : pas de *could* à l'affirmatif. (*He couldn't escape* serait correct à la négation.)\n\n**3. Exemple de règlement**\n1. *All students **have to** bring their identity card.*\n2. *You **don't have to** bring lunch: sandwiches will be provided.*\n3. *You **mustn't** leave the group without a teacher.*\n4. *You **are allowed to** buy souvenirs during the free time.*\n5. *You **ought to** wear comfortable shoes, because we will walk a lot.*\nOn vérifie le sens : obligation extérieure, absence d'obligation, interdiction, permission, conseil. Toute production correcte est acceptée."}$exo$::jsonb),
  ('21ec2fe9-9589-5820-ba90-7fd856cf3817'::uuid, 1, 'traduction', $exo${"titre":"Sans that ni subjonctif","consigne":"Traduis chaque phrase en anglais en employant la structure verbe + complément + (to) + base verbale, ou la structure qui convient.","enonce":"**Thème : traduis en anglais.**\n\n1. Mon père veut que je range ma chambre.\n2. Elle m'a dit de fermer la porte.\n3. Ils attendent de nous que nous soyons à l'heure.\n4. Je lui ai demandé de ne pas crier. *(lui = un garçon)*\n5. Le professeur nous a fait relire le texte.\n6. Il est important que les élèves dorment assez.\n\n*Aide : ranger = to tidy ; relire = to read again ; à l'heure = on time.*","bareme":[{"critere":"Phrases 1 à 3 : complément + to + base verbale, pronom complément (me, us)","points":9},{"critere":"Phrase 4 : not placé devant to","points":3},{"critere":"Phrase 5 : make sans to","points":4},{"critere":"Phrase 6 : for + nom + to","points":4}],"dureeMin":7,"corrige":"1. *My father wants **me to tidy** my room.* — jamais *wants that I tidy* ; pronom complément *me*.\n2. *She told **me to close** the door.* — *tell* + complément + *to* (pas *said me*).\n3. *They expect **us to be** on time.*\n4. *I asked him **not to shout**.* — la négation porte sur l'action demandée : *not* devant *to*.\n5. *The teacher made **us read** the text again.* — *make* se construit **sans to**.\n6. *It is important **for students to sleep** enough.* — après un adjectif, quand l'action a un sujet propre : *for* + nom + *to*.\n\nToute tournure qui garde *that* + verbe conjugué après *want*, *expect*, *tell* ou *ask* perd les points de la phrase."}$exo$::jsonb),
  ('21ec2fe9-9589-5820-ba90-7fd856cf3817'::uuid, 2, 'traduction', $exo${"titre":"Sept phrases à réparer","consigne":"Corrige chaque phrase en justifiant, puis réécris les consignes rapportées avec le verbe entre parenthèses.","enonce":"**1. Chaque phrase contient une erreur. Corrige-la et justifie en quelques mots.**\n\na. I want that you help me.\nb. She suggested me to go.\nc. They let us to leave early.\nd. I'd like he stays.\ne. He asked me to not say anything.\n\n**2. Réécris chaque phrase avec le verbe entre parenthèses, sans that.**\n\na. The coach to the players: \"Don't be late!\" (tell)\nb. My mother to my brother: \"Please, apply for that job!\" (encourage)\nc. The doctor to Mr Hill: \"Walk every day.\" (advise)","bareme":[{"critere":"Cinq phrases corrigées","points":8},{"critere":"Justifications justes (pas de that, suggest, let sans to, pronom complément, place de not)","points":5},{"critere":"Trois réécritures justes avec complément + to (+ not to pour la négation)","points":7}],"dureeMin":11,"corrige":"**1.**\na. *I want **you to help** me.* — *want* + complément + *to*, jamais *that*.\nb. *She suggested **that I (should) go** / She suggested **going**.* — *suggest* ne se construit jamais avec complément + *to*.\nc. *They let us **leave** early.* — *let* se construit **sans to**.\nd. *I'd like **him to stay**.* — pronom **complément** (*him*) + *to* ; pas de verbe conjugué.\ne. *He asked me **not to say** anything.* — *not* se place **devant** *to*.\n\n**2.**\na. *The coach told the players **not to be** late.*\nb. *My mother encouraged my brother **to apply** for that job.*\nc. *The doctor advised Mr Hill **to walk** every day.*\n\nOn accepte les pronoms (*told them not to be late*, *encouraged him to apply*, *advised him to walk*). Garder *that* ou mettre *not* après *to* fait perdre les points de la phrase."}$exo$::jsonb),
  ('21ec2fe9-9589-5820-ba90-7fd856cf3817'::uuid, 3, 'traduction', $exo${"titre":"Le choix de Clara","consigne":"Traduis le texte en anglais (thème), puis justifie trois de tes choix de traduction.","enonce":"**1. Thème : traduis en anglais.**\n\n> Les parents de Clara aimeraient qu'elle fasse des études de droit, mais sa professeure d'anglais l'encourage à partir un an à l'étranger. Elle lui a conseillé de postuler dans une université canadienne et l'a aidée à écrire sa lettre. Son père ne la laissera peut-être pas partir. Sa mère a suggéré qu'ils en parlent tous ensemble. Il est essentiel que chacun comprenne son choix.\n\n*Aide : faire des études de droit = to study law ; postuler = to apply ; à l'étranger = abroad.*\n\n**2. Justifie en français** la construction que tu as choisie pour : « aimeraient qu'elle fasse » ; « a suggéré qu'ils en parlent » ; « ne la laissera pas partir ».","bareme":[{"critere":"Would like, encourage, advise + complément + to + base verbale","points":6},{"critere":"Help (to facultatif) et let sans to","points":3},{"critere":"Suggest construit sans complément + to ; for + nom + to après essential","points":5},{"critere":"Trois justifications exactes","points":6}],"dureeMin":18,"corrige":"**1. Traduction modèle**\n\n*Clara's parents **would like her to study** law, but her English teacher **encourages her to go** abroad for a year. She **advised her to apply** to a Canadian university and **helped her (to) write** her letter. Her father may not **let her go**. Her mother **suggested that they (should) talk** about it all together. It is essential **for everyone to understand** her choice.*\n\n**Points attendus**\n- « aimeraient qu'elle fasse » → *would like her to study* (pas *would like that she studies*).\n- « l'encourage à partir » → *encourages her to go* ; « lui a conseillé de postuler » → *advised her to apply*.\n- « l'a aidée à écrire » → *helped her (to) write* : *to* facultatif.\n- « ne la laissera peut-être pas partir » → *may not let her go* : *let* sans *to*. On accepte *might not* ou *will perhaps not let her go*.\n- « a suggéré qu'ils en parlent » → *suggested that they (should) talk* ou *suggested talking*.\n- « Il est essentiel que chacun comprenne » → *It is essential for everyone to understand*.\n\n**2. Justifications**\n- « aimeraient qu'elle fasse » : après *would like*, l'anglais n'emploie ni *that* ni subjonctif ; il met le sujet de l'action en **complément** (*her*) puis *to* + base verbale.\n- « a suggéré qu'ils en parlent » : *suggest* est l'exception, il n'accepte **jamais** complément + *to* ; on emploie *that* + sujet + verbe, ou -ing.\n- « ne la laissera pas partir » : *let* (comme *make*) se construit **sans to** : *let her go*."}$exo$::jsonb),
  ('2e0cbfd5-f75c-5834-a830-cc5a054860c6'::uuid, 1, 'traduction', $exo${"titre":"Both, either, neither, each, every","consigne":"Complète chaque phrase avec both, either, neither (… nor), each ou every.","enonce":"**Complète.**\n\n1. ___ answers are correct. *(les deux réponses)*\n2. You can take ___ bus: they both go to the station.\n3. ___ Tom ___ Anna came to the party.\n4. The bus comes ___ ten minutes.\n5. These T-shirts cost ten pounds ___.\n6. I don't like horror films, and my brother doesn't like them ___.\n7. In our class of thirty, ___ of us has a locker.\n8. She speaks ___ English and Spanish.","bareme":[{"critere":"Phrases 1, 2, 3 et 8 justes (distributifs pour deux éléments)","points":10},{"critere":"Phrases 4, 5 et 7 justes (each / every)","points":7},{"critere":"Phrase 6 juste : either en fin de phrase négative","points":3}],"dureeMin":7,"corrige":"1. ***Both** answers are correct.* — les deux ensemble, suivi d'un pluriel.\n2. *You can take **either** bus.* — l'un ou l'autre, suivi d'un singulier.\n3. ***Neither** Tom **nor** Anna came to the party.* — ni l'un ni l'autre ; pas d'autre négation.\n4. *The bus comes **every** ten minutes.* — fréquence : *every* + nombre (toutes les dix minutes).\n5. *These T-shirts cost ten pounds **each**.* — *each* peut s'employer seul (pièce) ; *every* jamais.\n6. *…my brother doesn't like them **either**.* — en fin de phrase négative, *either* = « non plus ».\n7. *…**each** of us has a locker.* — *each of* + pronom ; *every of us* est impossible ; *neither* et *either* ne concernent que deux éléments.\n8. *She speaks **both** English **and** Spanish.* — *both… and…*"}$exo$::jsonb),
  ('2e0cbfd5-f75c-5834-a830-cc5a054860c6'::uuid, 2, 'traduction', $exo${"titre":"Six fautes de distributifs","consigne":"Corrige chaque phrase en justifiant, puis traduis les trois phrases de la partie 2.","enonce":"**1. Chaque phrase contient une erreur. Corrige-la et justifie.**\n\na. Neither of them didn't come.\nb. Every of us wants to win.\nc. Both answer is correct.\nd. Every students has a book.\ne. You can come on either days.\nf. They are tired both.\n\n**2. Thème : traduis en anglais.**\n\n7. Je vais à la piscine un jour sur deux.\n8. Aucune des deux solutions n'est parfaite.\n9. Chaque candidat a trois minutes.","bareme":[{"critere":"Six phrases corrigées","points":8},{"critere":"Justifications justes (négation, every of, pluriel, singulier, place de both)","points":6},{"critere":"Trois traductions justes (every other day, neither + singulier, each / every + singulier)","points":6}],"dureeMin":11,"corrige":"**1.**\na. *Neither of them **came**.* — *neither* contient déjà la négation : pas de *didn't*.\nb. ***Every one** of us wants to win* (ou ***Each** of us wants to win*). — *every of* n'existe pas.\nc. *Both **answers are** correct.* — *both* est suivi d'un **pluriel** et d'un verbe au pluriel.\nd. *Every **student** has a book.* — *every* est suivi d'un **singulier**.\ne. *You can come on either **day**.* — *either* est suivi d'un **singulier**.\nf. *They are **both** tired.* — *both* se place après *be* (ou devant le verbe lexical).\n\n**2.**\n7. *I go to the swimming pool **every other day**.*\n8. ***Neither** solution is perfect.* (ou *Neither of the (two) solutions is perfect.*) — singulier, pas de *not*.\n9. ***Each** candidate has three minutes.* — *each* insiste sur l'individu, un par un ; *Every candidate has* est accepté s'il y a au moins trois candidats. Verbe au singulier dans les deux cas."}$exo$::jsonb),
  ('2e0cbfd5-f75c-5834-a830-cc5a054860c6'::uuid, 3, 'traduction', $exo${"titre":"Deux amies en route pour l'Écosse","consigne":"Traduis le texte en anglais (thème), puis justifie trois de tes choix.","enonce":"**1. Thème : traduis en anglais.**\n\n> Deux amies, Lina et Maëlle, préparent un voyage. Toutes les deux veulent aller en Écosse, mais aucune des deux n'a le permis. Elles peuvent prendre l'un ou l'autre train pour Édimbourg. Les billets coûtent quarante livres chacun, et un train part toutes les deux heures. Chaque voyageur doit montrer son passeport. Lina n'aime pas l'avion, et Maëlle non plus.\n\n*Aide : préparer un voyage = to plan a trip ; le permis = a driving licence ; Édimbourg = Edinburgh.*\n\n**2. Justifie en français** ton choix pour : « Toutes les deux » ; « aucune des deux n'a » ; « Maëlle non plus ».","bareme":[{"critere":"Both (bien placé) et neither + verbe affirmatif au singulier","points":6},{"critere":"Either + singulier, each en fin de groupe, every two hours","points":5},{"critere":"Each / every + singulier pour chaque voyageur ; either pour non plus","points":3},{"critere":"Trois justifications exactes","points":6}],"dureeMin":18,"corrige":"**1. Traduction modèle**\n\n*Two friends, Lina and Maëlle, are planning a trip. They **both** want to go to Scotland (ou **Both of them** want…), but **neither** of them has a driving licence. They can take **either** train to Edinburgh. The tickets cost forty pounds **each**, and a train leaves **every** two hours. **Every** passenger (ou **Each** passenger) must show their passport. Lina doesn't like planes, and Maëlle doesn't like them **either**.*\n\n**Points attendus**\n- *They both want* : *both* devant le verbe lexical ; *both of them* accepté.\n- *neither of them has* : verbe **affirmatif** et au **singulier** (*has*).\n- *either train* : singulier.\n- *forty pounds each* : *each* employé seul, en fin de groupe.\n- *every two hours* : fréquence.\n- *Every / Each passenger must* : les deux sont acceptés (un groupe de plus de trois voyageurs) ; nom au singulier.\n- *doesn't like them either* : « non plus » en fin de phrase négative.\n\n**2. Justifications**\n- « Toutes les deux » : il y a **deux** personnes, prises **ensemble** → *both*, placé devant le verbe (*They both want*).\n- « aucune des deux n'a » : **deux** éléments, **aucun** → *neither*, qui contient déjà la négation ; on n'ajoute pas *doesn't*, et le verbe est au singulier.\n- « Maëlle non plus » : dans une phrase **négative**, « non plus » se dit *either* en fin de phrase (*doesn't… either*)."}$exo$::jsonb),
  ('adf10a8e-53f8-540e-9f30-d2fec7a89948'::uuid, 1, 'traduction', $exo${"titre":"La manière dans le verbe","consigne":"Traduis chaque phrase en anglais en appliquant le chassé-croisé, puis réponds à la question 2.","enonce":"**1. Thème : traduis en anglais.**\n\n1. Il a traversé le lac à la nage.\n2. Elle est sortie de la maison en courant.\n3. Ils sont rentrés à pied.\n4. L'oiseau s'est envolé.\n5. Le chien est entré dans la cuisine en courant.\n6. Elle a peint la porte en bleu.\n\n**2.** Dans ta traduction de la phrase 1, indique quel mot dit la **manière** et quel mot dit le **déplacement**. Compare avec la phrase française.","bareme":[{"critere":"Phrases 1 à 5 : verbe de manière + particule de déplacement justes","points":12},{"critere":"Phrase 6 : adjectif de résultat placé après le complément","points":3},{"critere":"Analyse juste du chassé-croisé sur la phrase 1","points":5}],"dureeMin":8,"corrige":"**1.**\n1. *He **swam across** the lake.*\n2. *She **ran out of** the house.*\n3. *They **walked back** (home).*\n4. *The bird **flew away**.*\n5. *The dog **ran into** the kitchen.*\n6. *She painted the door **blue**.* — résultat : l'adjectif se place **après** le complément.\n\nLes calques (*He crossed the lake swimming*, *She went out running*) perdent les points de la phrase.\n\n**2.** Dans *He swam across the lake*, le **verbe** *swam* dit la **manière** (nager) et la **particule** *across* dit le **déplacement** (d'un côté à l'autre). En français, c'est l'inverse : le verbe *traverser* dit le déplacement et le complément *à la nage* dit la manière. C'est le **chassé-croisé**."}$exo$::jsonb),
  ('adf10a8e-53f8-540e-9f30-d2fec7a89948'::uuid, 2, 'traduction', $exo${"titre":"Une nuit agitée","consigne":"Traduis le texte en français (version). Remets le déplacement dans le verbe français et la manière dans un complément.","enonce":"**Version : traduis en français.**\n\n> *Late at night, Sam tiptoed out of his bedroom and crept down the stairs. Suddenly, the wind blew the kitchen door open. Frightened, the cat dashed across the room and jumped out of the window. Sam slammed the door shut and ran back upstairs.*\n\n*Aide : to creep (crept) = avancer sans bruit ; to dash = se précipiter, filer ; frightened = effrayé ; upstairs = en haut, à l'étage.*","bareme":[{"critere":"Chassé-croisé rendu : tiptoed out, crept down, dashed across, ran back (verbe de déplacement + complément de manière)","points":8},{"critere":"Résultatives rendues : blew the door open, slammed the door shut","points":5},{"critere":"Sens général et temps du récit cohérents","points":4},{"critere":"Correction du français (orthographe, syntaxe)","points":3}],"dureeMin":12,"corrige":"**Traduction modèle**\n\n« Tard dans la nuit, Sam sortit de sa chambre sur la pointe des pieds et descendit l'escalier sans bruit. Soudain, le vent ouvrit brusquement la porte de la cuisine. Effrayé, le chat traversa la pièce à toute vitesse et sauta par la fenêtre. Sam claqua la porte et remonta l'escalier en courant. »\n(Passé composé accepté : « est sorti », « a descendu »…)\n\n**Points attendus**\n- *tiptoed out of his bedroom* → « sortit de sa chambre **sur la pointe des pieds** » : le déplacement (*out*) devient le verbe *sortir*, la manière (*tiptoe*) devient un complément.\n- *crept down the stairs* → « descendit l'escalier **sans bruit / à pas de loup** ».\n- *the wind blew the door open* → « le vent ouvrit **brusquement / d'un coup** la porte » : le résultat (*open*) devient le verbe *ouvrir*.\n- *dashed across the room* → « traversa la pièce **à toute vitesse / en courant** ».\n- *jumped out of the window* → « sauta par la fenêtre ».\n- *slammed the door shut* → « claqua la porte » (le résultat *shut* est contenu dans le verbe français).\n- *ran back upstairs* → « remonta l'escalier **en courant** » (ou « remonta en courant »).\nLes calques du type « il marcha sur la pointe des pieds hors de sa chambre » perdent les points du critère 1."}$exo$::jsonb),
  ('adf10a8e-53f8-540e-9f30-d2fec7a89948'::uuid, 3, 'traduction', $exo${"titre":"La fuite du voleur","consigne":"Traduis le récit en anglais (thème), puis réponds aux questions 2 et 3.","enonce":"**1. Thème : traduis en anglais.**\n\n> Le voleur est entré dans la banque sur la pointe des pieds. Quand l'alarme a sonné, il est ressorti en courant et a traversé la rue en courant. Un policier l'a suivi, mais le voleur a traversé la rivière à la nage. Épuisé, il est sorti de l'eau en rampant. Le policier l'attendait sur la rive : ils sont rentrés au commissariat à pied.\n\n*Aide : sonner = to ring ; épuisé = exhausted ; la rive = the bank ; le commissariat = the police station.*\n\n**2.** Explique en français, sur deux verbes de ta traduction, la méthode qui t'a permis de les construire.\n\n**3.** Traduis *The wind blew the door open* et explique ce que dit l'adjectif *open*.","bareme":[{"critere":"Cinq déplacements traduits par verbe de manière + particule (tiptoed into, ran out, ran across, swam across, crawled out of)","points":8},{"critere":"Walked back to the police station ; temps du récit et sens général","points":3},{"critere":"Méthode expliquée sur deux verbes (comment on bouge, puis où on va)","points":5},{"critere":"Résultative traduite et expliquée","points":4}],"dureeMin":18,"corrige":"**1. Traduction modèle**\n\n*The thief **tiptoed into** the bank. When the alarm rang, he **ran out** and **ran across** the street. A policeman followed him, but the thief **swam across** the river. Exhausted, he **crawled out of** the water. The policeman was waiting for him on the bank: they **walked back to** the police station.*\n\nOn accepte *dashed out*, *rushed across* pour « en courant ». On refuse *entered the bank on tiptoe*, *crossed the river swimming* (calques).\n\n**2. Méthode** (deux exemples attendus)\n- « a traversé la rivière à la nage » : 1. **comment** il bouge ? il nage → le verbe *swim* (prétérit *swam*) ; 2. **où** il va ? d'un côté à l'autre → la particule *across*. D'où *swam across the river*.\n- « est sorti de l'eau en rampant » : comment ? il rampe → *crawl* ; où ? vers l'extérieur → *out of*. D'où *crawled out of the water*.\n- (ou « est entré sur la pointe des pieds » → *tiptoe* + *into*.)\n\n**3.** « Le vent a ouvert la porte d'un coup. » L'adjectif *open*, placé **après le complément**, dit le **résultat** de l'action du vent (*blow*, souffler) : la porte se retrouve ouverte. Le verbe anglais dit la manière (souffler), l'adjectif le résultat ; en français, le résultat devient le verbe (*ouvrir*)."}$exo$::jsonb),
  ('ad349bdb-e7c9-5b20-afbc-3cdf75b6e9a5'::uuid, 1, 'traduction', $exo${"titre":"La bonne préposition","consigne":"Complète chaque phrase avec la préposition qui convient.","enonce":"**Complète avec at, in, of, about, with, for, to, from ou on.**\n\n1. Emma is good ___ drawing.\n2. My brother is interested ___ history.\n3. I'm proud ___ you!\n4. Don't be worried ___ the exam.\n5. She was angry ___ her little brother.\n6. Liverpool is famous ___ the Beatles.\n7. He is married ___ a doctor.\n8. Your phone is different ___ mine.\n9. What is the reason ___ his departure?\n10. The impact ___ young people is huge.","bareme":[{"critere":"Adjectifs 1 à 4 justes : at, in, of, about","points":8},{"critere":"Adjectifs 5 à 8 justes : with, for, to, from","points":8},{"critere":"Noms 9 et 10 justes : for, on","points":4}],"dureeMin":6,"corrige":"1. *good **at** drawing* — une compétence → *at* (et -ING après la préposition).\n2. *interested **in** history* — un domaine → *in* (jamais *interested by*).\n3. *proud **of** you* — un sentiment → *of*.\n4. *worried **about** the exam* — un sujet d'émotion → *about*.\n5. *angry **with** her little brother* — une **personne** → *with* (*angry about* une chose).\n6. *famous **for** the Beatles* — une cause → *for*.\n7. *married **to** a doctor* — jamais *married with*.\n8. *different **from** mine* — une différence → *from*.\n9. *the reason **for** his departure* — jamais *the reason of*.\n10. *The impact **on** young people* — *impact / effect* → *on*.\n\nChaque réponse vaut 2 points."}$exo$::jsonb),
  ('ad349bdb-e7c9-5b20-afbc-3cdf75b6e9a5'::uuid, 2, 'traduction', $exo${"titre":"Sept calques à chasser","consigne":"Corrige chaque phrase et justifie en quelques mots.","enonce":"**Chaque phrase contient une erreur. Corrige-la et justifie.**\n\n1. She's interested by politics.\n2. It depends of the weather.\n3. He is responsible of the team.\n4. I'm tired to wait for the bus.\n5. My aunt is married with a lawyer.\n6. Nobody has found the solution of the problem.\n7. There has been an increase of prices this year.\n\n**Puis traduis en anglais :** « Elle est douée pour chanter et fière de ses dessins. »","bareme":[{"critere":"Phrases 1, 2, 3 et 5 corrigées (interested in, depend on, responsible for, married to)","points":7},{"critere":"Phrase 4 : tired of + -ING","points":3},{"critere":"Phrases 6 et 7 corrigées (solution to, increase in)","points":4},{"critere":"Traduction juste : good at singing, proud of her drawings","points":6}],"dureeMin":10,"corrige":"1. *She's interested **in** politics.* — *interested in* (un domaine) ; *by* est un calque du français.\n2. *It depends **on** the weather.* — *depend on*, jamais *depend of*.\n3. *He is responsible **for** the team.* — *responsible for* (une fonction).\n4. *I'm tired **of waiting** for the bus.* — *tired of*, et après une préposition le verbe prend **-ING**.\n5. *My aunt is married **to** a lawyer.* — on est marié **à** quelqu'un : *married to*.\n6. *…the solution **to** the problem.* — *solution / key / answer* + *to*.\n7. *…an increase **in** prices…* — *increase / decrease* + *in*.\n\n**Traduction** : *She is good **at singing** and proud **of** her drawings.*\n- « douée pour » → *good at* (une compétence), suivi de -ING (*singing*) ;\n- « fière de » → *proud of* (un sentiment)."}$exo$::jsonb),
  ('ad349bdb-e7c9-5b20-afbc-3cdf75b6e9a5'::uuid, 3, 'traduction', $exo${"titre":"Une jeunesse inquiète","consigne":"Traduis le texte en anglais (thème), puis justifie trois de tes choix de préposition.","enonce":"**1. Thème : traduis en anglais.**\n\n> Beaucoup de jeunes sont inquiets pour l'avenir de la planète. Ils sont conscients des risques et fiers de leurs actions. Pourtant, certains sont fatigués d'attendre des décisions. La raison de leur colère est simple : ils ont besoin de changement. La hausse des températures a un impact sur leur vie, et ils sont en colère contre les dirigeants qui ne font rien.\n\n*Aide : une décision = a decision ; la colère = anger ; les dirigeants = leaders.*\n\n**2. Justifie en français** ta préposition pour : « fatigués d'attendre » ; « en colère contre les dirigeants » ; « la hausse des températures ».","bareme":[{"critere":"Adjectifs + préposition justes : worried about, aware of, proud of, tired of + -ING, angry with","points":7},{"critere":"Noms + préposition justes : reason for, need for, increase in, impact on","points":5},{"critere":"Trois justifications exactes","points":6},{"critere":"Sens général et orthographe","points":2}],"dureeMin":18,"corrige":"**1. Traduction modèle**\n\n*Many young people are **worried about** the future of the planet. They are **aware of** the risks and **proud of** their actions. Yet some of them are **tired of waiting** for decisions. The reason **for** their anger is simple: they **need** change (ou *there is a need **for** change*). The increase **in** temperatures has an impact **on** their lives, and they are **angry with** the leaders who do nothing.*\n\n**Points attendus**\n- *worried about* (sujet d'émotion) ; *aware of*, *proud of* (sentiment) ; *tired of waiting* (-ING après la préposition).\n- *the reason for*, jamais *of* ; *a need for change* ; *the increase in temperatures* ; *an impact on their lives*.\n- *angry with* + personnes. *young people* (pluriel), *their lives*.\n- « ils ont besoin de changement » : *they need change* est aussi correct ; *a need for change* montre la construction nom + *for*.\n\n**2. Justifications**\n- « fatigués d'attendre » : *tired* se construit avec **of** (un sentiment) ; après une préposition, le verbe prend **-ING** : *tired of waiting* (pas *tired to wait*).\n- « en colère contre les dirigeants » : on est *angry **with** someone* (une **personne**) et *angry **about** something* (une chose). Les dirigeants sont des personnes → *with*.\n- « la hausse des températures » : *increase* et *decrease* se construisent avec **in** : *an increase in temperatures* (pas *of*, qui est un calque du français « des »)."}$exo$::jsonb),
  ('d8e64893-bc5a-57eb-b93c-9d8a347f5245'::uuid, 1, 'redaction', $exo${"titre":"Les quatre temps d'un projet","consigne":"Réponds à chaque question en quelques lignes, avec le vocabulaire du cours.","enonce":"**Questions de cours**\n\n1. Cite dans l'ordre les quatre temps d'un projet plastique et dis en une phrase ce qui se passe à chacun.\n2. Quelle différence y a-t-il entre une intention et un thème ? Donne un exemple d'intention.\n3. Pourquoi une production sans question posée reste-t-elle « illustrative » ?","bareme":[{"critere":"Quatre temps dans l'ordre (formuler, chercher, réaliser, présenter) avec leur contenu","points":10},{"critere":"Intention = une phrase qui vise un effet, pas un thème, avec un exemple","points":5},{"critere":"Production illustrative : montre un sujet au lieu de le travailler","points":5}],"dureeMin":7,"corrige":"1. - **Formuler une intention** : une phrase qui dit ce que je veux produire comme effet.\n- **Chercher** : essais, matériaux, échelles, références ; on a **le droit de rater**.\n- **Réaliser** : les choix plastiques **répondent à l'intention** ou la **déplacent** (et le déplacement se note).\n- **Présenter** : l'**accrochage** et le **texte d'intention** font partie de l'œuvre.\n2. Un **thème** est un sujet (« la mémoire ») ; une **intention** est une **phrase** qui vise un effet : « je veux rendre visible la disparition », « je veux que le spectateur hésite ».\n3. Sans question posée, la production **montre un sujet au lieu de le travailler** : elle illustre. Une vraie problématique **admet plusieurs réponses plastiques** ; si une seule est possible, c'est une **consigne**, pas une question."}$exo$::jsonb),
  ('d8e64893-bc5a-57eb-b93c-9d8a347f5245'::uuid, 2, 'redaction', $exo${"titre":"Le carnet de Maëlys","consigne":"Analyse la situation et conseille Maëlys en t'appuyant sur le cours.","enonce":"**Situation (inventée).** Maëlys prépare la présentation de son projet sur le thème de l'absence. Elle veut retirer de son carnet de recherche trois essais ratés et ne garder que la version finale, « pour faire propre ». Elle a aussi repris une silhouette peinte par un artiste célèbre, mais n'ose pas le dire de peur qu'on l'accuse de copier.\n\n1. Explique à Maëlys pourquoi elle ne doit pas retirer ses essais ratés. Que prouve chaque type de contenu du carnet au jury ?\n2. Reprendre la silhouette d'un artiste, est-ce copier ? Présente les trois relations légitimes à une référence et dis laquelle correspond à son geste.\n3. Son thème, « l'absence », est-il une intention ? Propose-lui une formulation d'intention.","bareme":[{"critere":"Garder les essais : c'est le cheminement qui est noté ; un échec documenté vaut mieux qu'une réussite inexpliquée","points":4},{"critere":"Ce que prouvent croquis, essais datés, références annotées, notes d'intention","points":5},{"critere":"Citer, prolonger, contredire expliqués ; son geste relève de la citation, à assumer comme emprunt","points":7},{"critere":"Thème ≠ intention, formulation d'intention pertinente","points":4}],"dureeMin":12,"corrige":"1. Au lycée, c'est la **démarche** qui est évaluée : **un échec documenté vaut mieux qu'une réussite inexpliquée**. Le carnet prouve : **croquis et variantes** → que des **choix ont été écartés** ; **essais ratés, datés** → que la **recherche a eu lieu** ; **références annotées** → que le travail **se situe** ; **notes d'intention** → que la démarche est **consciente**.\n2. Non, situer son travail par rapport à un artiste n'est pas copier, c'est **se positionner**, à condition que la relation soit **consciente** :\n- **Citer** : reprendre un motif et l'**assumer comme emprunt** ;\n- **Prolonger** : poursuivre une recherche là où l'artiste l'a laissée ;\n- **Contredire** : reprendre le dispositif pour en **renverser le sens**.\nMaëlys **cite** : elle doit le dire et l'assumer.\n3. « L'absence » est un **thème**. Une intention est une phrase : par exemple « je veux que le spectateur ressente un manque devant une place vide » ou « je veux rendre visible la disparition »."}$exo$::jsonb),
  ('d8e64893-bc5a-57eb-b93c-9d8a347f5245'::uuid, 3, 'redaction', $exo${"titre":"Défendre son projet devant un jury","consigne":"Rédige un texte organisé d'une vingtaine de lignes, comme si tu préparais l'oral de présentation d'un projet.","enonce":"**Sujet.** Tu as réalisé une installation à partir de l'intention : « je veux que le spectateur hésite entre entrer et rester dehors ». Au départ, tu pensais faire une peinture ; tes essais t'ont amené à construire un seuil avec des voilages.\n\n1. Explique en quoi ton intention pose une vraie problématique (et non une consigne).\n2. Montre comment ton carnet de recherche rend visible le passage de la peinture à l'installation, et pourquoi ce déplacement est valorisé.\n3. Choisis une référence (réelle ou décrite de façon générale) et précise ta relation à elle : citer, prolonger ou contredire.\n4. Explique pourquoi l'accrochage et le texte d'intention sont le « dernier acte plastique », et ce que signifie « défendre son travail ».","bareme":[{"critere":"Problématique justifiée : elle admet plusieurs réponses plastiques","points":4},{"critere":"Carnet : essais datés, variantes, choix écartés montrant le déplacement de l'intention","points":5},{"critere":"Relation à une référence nommée et justifiée","points":4},{"critere":"Présentation (accrochage, éclairage, ordre de lecture, texte) comme acte plastique","points":4},{"critere":"Défendre = expliciter les choix, pas justifier les manques","points":3}],"dureeMin":18,"corrige":"Éléments attendus :\n1. L'intention est une **phrase** qui vise un effet sur le spectateur. Elle pose une vraie **problématique** car elle **admet plusieurs réponses plastiques** (une peinture en trompe-l'œil, un passage étroit, un voilage, un jeu de lumière…). Si une seule réponse était possible, ce serait une **consigne**. Sans cette question, le travail serait **illustratif**.\n2. Le carnet montre la **phase de recherche** : croquis de la peinture, **essais ratés datés**, variantes d'échelle et de matériaux, photos du seuil. Ils prouvent que des **choix ont été écartés** et que la recherche a eu lieu. Pendant la réalisation, les choix plastiques **répondent à l'intention ou la déplacent** : ici, passer de la peinture à l'installation est un **déplacement**, et **le déplacement se note** — c'est le **cheminement** qui est évalué, pas la seule habileté.\n3. Toute référence pertinente est acceptée si la relation est **consciente** et justifiée : **citer** (reprendre un motif en l'assumant), **prolonger** (poursuivre la recherche d'un artiste) ou **contredire** (reprendre son dispositif pour en renverser le sens). Se situer n'est pas copier.\n4. **Accrochage, éclairage, ordre de lecture, texte d'intention** : la présentation est le **dernier acte plastique**, pas une formalité ; elle fait partie de l'œuvre (ici, placer le seuil pour que le spectateur doive choisir). **Défendre** son travail, c'est **expliciter ses choix** — jamais **justifier ses manques**."}$exo$::jsonb),
  ('eeee663c-e2fc-56fc-a26b-2ed6151ee14e'::uuid, 1, 'redaction', $exo${"titre":"Les quatre déplacements de l'art contemporain","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"**Questions de cours**\n\n1. Quelle question l'art contemporain a-t-il remplacée, et par laquelle ?\n2. Complète : l'œuvre passe de l'objet à l'…, de l'atelier au …, de l'objet au …, de l'unique au … . Donne pour chacun le mouvement ou la pratique qui correspond.\n3. Que signifie la phrase de Duchamp : « C'est le regardeur qui fait le tableau » ?","bareme":[{"critere":"De « est-ce beau ? » à « qu'est-ce que cela fait ? »","points":4},{"critere":"Quatre déplacements justes avec la pratique associée (art conceptuel, in situ/land art, performance, Pop art)","points":12},{"critere":"L'œuvre existe activée par l'interprétation ou la participation","points":4}],"dureeMin":7,"corrige":"1. On ne demande plus « **est-ce beau ?** » mais « **qu'est-ce que cela fait ?** ».\n2. - De l'objet à l'**idée** : l'**art conceptuel**, où le protocole vaut l'œuvre.\n- De l'atelier au **lieu** : l'**in situ** et le **land art**, où l'œuvre tient à son site.\n- De l'objet au **corps** : la **performance**, où l'œuvre est un temps vécu.\n- De l'unique au **reproductible** : le **Pop art** et la **sérigraphie**, où la copie n'est plus un défaut.\n3. Pour **Duchamp**, l'œuvre n'est pas complète sans celui qui la regarde : beaucoup d'œuvres contemporaines **n'existent qu'activées** — par une **interprétation**, une **participation** ou un **récit**."}$exo$::jsonb),
  ('eeee663c-e2fc-56fc-a26b-2ed6151ee14e'::uuid, 2, 'redaction', $exo${"titre":"Quatre artistes, quatre gestes","consigne":"Associe et explique, en t'appuyant sur le cours.","enonce":"**Document – Quatre descriptions (sans nom)**\n\n- **A.** Un artiste reproduit en série, par sérigraphie, la même image d'une célébrité.\n- **B.** Un couple d'artistes enveloppe un monument entier de toile pendant quelques jours.\n- **C.** Une artiste suit un inconnu dans la rue et raconte son enquête par des textes et des photos.\n- **D.** Un artiste réalise des œuvres qui dénoncent la censure dans son pays.\n\n1. Retrouve l'artiste (ou les artistes) correspondant à chaque description, selon le cours.\n2. Pour chacun, dis ce que son geste « déplace ».\n3. Le street art, né dans l'illégalité, est-il resté en dehors du marché ? Explique.","bareme":[{"critere":"Quatre attributions justes : Warhol, Christo et Jeanne-Claude, Sophie Calle, Ai Weiwei","points":8},{"critere":"Ce que chaque geste déplace (unicité, éphémère et public, artiste narratrice, prise de position)","points":8},{"critere":"Street art : passé de la rue au marché, l'illégalité devenue valeur","points":4}],"dureeMin":11,"corrige":"1. **A** : **Andy Warhol** ; **B** : **Christo et Jeanne-Claude** ; **C** : **Sophie Calle** ; **D** : **Ai Weiwei**.\n2. - **Warhol**, reproduction sérielle : il déplace l'**unicité de l'œuvre**.\n- **Christo et Jeanne-Claude**, emballage monumental : l'œuvre devient **éphémère et publique**.\n- **Sophie Calle**, récit et enquête : l'**artiste devient narratrice**.\n- **Ai Weiwei**, art politique : l'œuvre comme **prise de position**.\n3. **Non** : le street art est passé de **la rue au marché** ; **l'illégalité est devenue valeur**. Galeries, foires et musées construisent aussi socialement la valeur d'une œuvre."}$exo$::jsonb),
  ('eeee663c-e2fc-56fc-a26b-2ed6151ee14e'::uuid, 3, 'redaction', $exo${"titre":"« Mon petit frère pourrait le faire »","consigne":"Rédige une réponse argumentée et organisée d'une vingtaine de lignes, en t'appuyant sur des exemples précis du cours.","enonce":"**Situation (inventée).** Au musée, devant une œuvre faite d'objets du quotidien disposés au sol selon un protocole écrit, ton ami Nolan s'exclame : « Ce n'est même pas beau, mon petit frère pourrait le faire, et en plus ça coûte une fortune ! »\n\nRéponds à Nolan en montrant :\n1. que l'art contemporain a déplacé la question qu'on pose à une œuvre ;\n2. à quel déplacement appartient cette œuvre, et en quoi l'idée compte plus que l'habileté ;\n3. comment se construit la valeur d'une œuvre contemporaine ;\n4. quelle méthode adopter devant une œuvre qui déroute, et quel rôle y joue le regardeur.","bareme":[{"critere":"Question déplacée : de la beauté à ce que fait l'œuvre","points":4},{"critere":"Art conceptuel : l'idée prime sur l'objet, le protocole vaut l'œuvre, avec au moins un autre déplacement cité","points":5},{"critere":"Valeur construite aussi socialement : galeries, foires, biennales, musées","points":4},{"critere":"Méthode : demander ce que l'œuvre demande de faire ; Duchamp et le regardeur","points":5},{"critere":"Argumentation organisée qui répond à Nolan","points":2}],"dureeMin":18,"corrige":"Éléments attendus :\n1. Nolan juge avec la question « **est-ce beau ?** ». L'art contemporain l'a **déplacée** vers « **qu'est-ce que cela fait ?** » : l'œuvre ne cherche pas forcément la beauté ni l'habileté technique.\n2. Cette œuvre relève du passage **de l'objet à l'idée** : c'est l'**art conceptuel**, où **le protocole vaut l'œuvre**. Ce qui compte est l'idée et la décision de l'artiste, pas la difficulté de fabrication : « pouvoir le faire » n'est pas « l'avoir pensé ». On peut citer d'autres déplacements : vers le **lieu** (in situ, land art), le **corps** (performance), le **reproductible** (Warhol et le Pop art, où la copie n'est plus un défaut).\n3. Le prix n'est pas absurde si l'on comprend le circuit : **galeries, foires, biennales, musées** — la valeur d'une œuvre contemporaine se construit **aussi socialement**. Ignorer ce circuit condamne à trouver les prix absurdes ; le comprendre fait partie de la compréhension de l'œuvre (exemple du **street art**, passé de la rue au marché).\n4. Méthode : ne pas demander **ce que l'œuvre représente**, mais **ce qu'elle demande de faire**. Pour **Duchamp**, « **c'est le regardeur qui fait le tableau** » : beaucoup d'œuvres n'existent qu'**activées** par une interprétation, une participation ou un récit. Nolan, en réagissant, participe déjà à l'œuvre."}$exo$::jsonb),
  ('12819aec-e2d2-5c97-bc51-2931e4be5ef6'::uuid, 1, 'redaction', $exo${"titre":"Pixel ou vecteur ?","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"**Questions de cours**\n\n1. Comment une image matricielle est-elle décrite ? Et une image vectorielle ? Que se passe-t-il quand on les agrandit ?\n2. Donne un usage typique de chacune.\n3. Quels sont les deux sens du mot « résolution » ? En quelle unité mesure-t-on la finesse d'impression ?","bareme":[{"critere":"Grille de pixels / formules géométriques ; pixellisation / netteté conservée","points":8},{"critere":"Usages : photographie ou peinture numérique / logo, typographie, pictogramme","points":5},{"critere":"Résolution en pixels (dimensions) et en ppp/dpi (impression)","points":7}],"dureeMin":6,"corrige":"1. Une image **matricielle** (bitmap) est une **grille de pixels colorés** : agrandie, elle **se dégrade, se pixellise**. Une image **vectorielle** est décrite par des **formules géométriques** : agrandie, elle **reste nette, sans perte**.\n2. Matricielle : **photographie**, peinture numérique. Vectorielle : **logo**, typographie, pictogramme.\n3. La résolution se lit deux fois : en **pixels** (les dimensions de l'image) et en **ppp / dpi** (points par pouce, sa **finesse à l'impression**)."}$exo$::jsonb),
  ('12819aec-e2d2-5c97-bc51-2931e4be5ef6'::uuid, 2, 'redaction', $exo${"titre":"Le bon format pour chaque usage","consigne":"Aide Ilyes à choisir ses formats en justifiant chaque choix avec le cours.","enonce":"**Situation (inventée).** Ilyes prépare l'affiche d'un festival de son lycée. Il doit produire :\n- **A.** le logo du festival, qui sera imprimé en petit sur les billets et en très grand sur une banderole ;\n- **B.** une photo du groupe de musique pour le site web ;\n- **C.** une image du chanteur détourée, à poser sur un fond coloré ;\n- **D.** un fichier de l'affiche finale en qualité maximale, à archiver et à envoyer à l'imprimeur.\n\n1. Pour chaque cas, choisis un format parmi JPEG, PNG, TIFF, SVG et justifie.\n2. Pour la photo du site, quel inconvénient présente le format choisi ?\n3. Pour poser le chanteur sur le fond, quels outils de montage Ilyes peut-il utiliser ?","bareme":[{"critere":"A SVG (vectoriel, net à toutes les tailles) justifié","points":4},{"critere":"B JPEG, C PNG (transparence), D TIFF justifiés","points":8},{"critere":"JPEG : compression avec perte d'information","points":4},{"critere":"Outils : calques, masques, détourage, fondus","points":4}],"dureeMin":10,"corrige":"1. - **A** : **SVG**, format **vectoriel** : le logo reste **net sans perte** du billet à la banderole (une image matricielle se pixelliserait).\n- **B** : **JPEG**, adapté à une **photo destinée au web** (fichier léger).\n- **C** : **PNG**, qui compresse **sans perte** et **garde la transparence** : idéal pour une **image détourée**.\n- **D** : **TIFF**, qui **conserve la qualité maximale** : **archivage** et **impression**.\n2. Le JPEG **compresse en perdant de l'information** : la qualité se dégrade, surtout si on l'enregistre plusieurs fois.\n3. Les **calques** (superposer et modifier les éléments indépendamment), les **masques**, le **détourage** et les **fondus**."}$exo$::jsonb),
  ('12819aec-e2d2-5c97-bc51-2931e4be5ef6'::uuid, 3, 'redaction', $exo${"titre":"Une photo qui n'a jamais eu lieu","consigne":"Rédige une réponse argumentée et organisée d'une vingtaine de lignes, en t'appuyant sur le cours.","enonce":"**Situation (inventée).** Une image circule sur les réseaux sociaux : on y voit une baleine nageant dans une rue inondée de Paris. Elle est parfaite, sans aucune trace visible de retouche. Des milliers de personnes la partagent, et personne ne sait qui l'a faite.\n\n1. Explique comment le montage numérique permet de produire une telle image (outils, notion d'image « sans référent réel »).\n2. Que devient la valeur de preuve de la photographie ? Une photographie numérique est-elle toujours une preuve fiable ?\n3. Explique la notion d'« aura » selon Walter Benjamin et montre comment le numérique pousse cette logique à l'extrême, à partir de l'exemple.\n4. Conclus : en quoi le numérique n'est-il « pas un pinceau de plus » ?","bareme":[{"critere":"Montage : calques, masques, détourage, fondus ; image sans référent réel, photographiquement parfaite","points":5},{"critere":"Valeur de preuve remise en question quand la retouche ne laisse plus de trace","points":4},{"critere":"Aura selon Benjamin (1935) : l'ici-et-maintenant perdu par la reproduction","points":4},{"critere":"Numérique extrême : copie parfaite, diffusion instantanée, auteur indéterminé, relié à l'exemple","points":4},{"critere":"Conclusion : le numérique change le statut de l'image (matière, copie, preuve)","points":3}],"dureeMin":18,"corrige":"Éléments attendus :\n1. Avec les **calques**, les **masques**, le **détourage** et les **fondus**, on combine plusieurs images (une baleine, une rue, de l'eau) en une seule. On obtient une image **sans référent réel** : une scène **qui n'a jamais eu lieu**, pourtant **photographiquement parfaite**.\n2. La photographie passait pour une **preuve** (« ça a eu lieu »). Quand **la retouche ne laisse plus de trace**, cette **valeur de preuve** est remise en question : une photographie numérique **n'est pas toujours une preuve fiable** ; il faut s'interroger sur sa source.\n3. **Walter Benjamin** l'anticipait dès **1935** : la **reproduction** fait perdre à l'œuvre son **« aura »**, son **ici-et-maintenant**. Le numérique pousse cette logique à l'extrême : **copie parfaite** (chaque partage est identique à l'original), **diffusion instantanée** (des milliers de partages), **auteur parfois indéterminé** (personne ne sait qui l'a faite).\n4. Le numérique n'est **pas un pinceau de plus** : il change le **statut** de l'image — sa **matière** (pixels ou vecteurs), sa **copie** (sans perte ni original) et sa **preuve** (plus garantie)."}$exo$::jsonb),
  ('cae06da0-6377-52bd-9c6c-06ae700b9a91'::uuid, 1, 'application', $exo${"titre":"Classer les oses","consigne":"Réponds à chaque question en justifiant avec le vocabulaire du cours.","enonce":"On étudie quatre oses : le **D-glucose**, le **D-fructose**, le **D-ribose** et le **D-désoxyribose**.\n\n1. Rappelle la définition d'un ose.\n2. Classe chacun des quatre oses : aldose ou cétose ? hexose ou pentose ? Justifie à partir du nombre de carbones et de la fonction portée.\n3. Cite les deux fonctions présentes dans la forme ouverte du D-glucose et écris leur groupe caractéristique.\n4. Que signifie la lettre **D** dans une projection de Fischer ?\n5. Qu'est-ce qui distingue le désoxyribose du ribose ?","bareme":[{"critere":"Définition d'un ose juste (plusieurs fonctions alcool, une seule fonction aldéhyde ou cétone)","points":4},{"critere":"Les quatre oses classés et justifiés (aldohexose, cétohexose, deux aldopentoses)","points":8},{"critere":"Fonctions alcool (–OH) et aldéhyde (–CHO) du glucose","points":4},{"critere":"Sens de D (–OH de l'avant-dernier carbone à droite) et différence ribose / désoxyribose (–OH en moins sur le carbone 2)","points":4}],"dureeMin":8,"corrige":"1. Un **ose** (sucre simple) porte **plusieurs fonctions alcool** et **une seule** fonction aldéhyde ou cétone.\n\n2.\n- **D-glucose** : 6 C, fonction aldéhyde → **aldohexose**.\n- **D-fructose** : 6 C, fonction cétone → **cétohexose**.\n- **D-ribose** : 5 C, fonction aldéhyde → **aldopentose**.\n- **D-désoxyribose** : 5 C, fonction aldéhyde → **aldopentose**.\n\n3. Fonctions **alcool** (–OH) et fonction **aldéhyde** (–CHO).\n\n4. En projection de Fischer (chaîne verticale, carbone 1 en haut), **D** signifie que le –OH porté par l'**avant-dernier carbone** est à **droite**.\n\n5. Le désoxyribose possède **un –OH en moins sur le carbone 2** (d'où « désoxy »). Le ribose entre dans l'ARN, le désoxyribose dans l'ADN."}$exo$::jsonb),
  ('cae06da0-6377-52bd-9c6c-06ae700b9a91'::uuid, 2, 'application', $exo${"titre":"Trois osides à identifier","consigne":"Exploite les résultats expérimentaux et réponds en justifiant. Détaille tes calculs.","enonce":"**Expérience.** Trois osides X, Y et Z, tous des diholosides, sont hydrolysés. L'hydrolysat de chacun est analysé par chromatographie, à côté de témoins (glucose, fructose, galactose).\n\n| Oside | Taches observées dans l'hydrolysat |\n| X | une seule tache, au niveau du glucose |\n| Y | deux taches : glucose et fructose |\n| Z | deux taches : glucose et galactose |\n\n1. Identifie X, Y et Z et indique où on les trouve.\n2. Quelle liaison relie les deux oses d'un oside ? Comment se forme-t-elle, et comment la digestion la rompt-elle ?\n3. **Calcul.** La formule brute du glucose est C₆H₁₂O₆. Calcule la masse molaire du glucose, puis celle de l'oside X. *Données : M(C) = 12 g/mol ; M(H) = 1 g/mol ; M(O) = 16 g/mol.*\n4. Le glucose et le galactose ont la même formule brute. En quoi diffèrent-ils ?","bareme":[{"critere":"X = maltose, Y = saccharose, Z = lactose, avec leur origine (hydrolyse de l'amidon, sucre de table, lait)","points":6},{"critere":"Liaison osidique : condensation avec élimination d'une molécule d'eau, rupture par hydrolyse","points":5},{"critere":"M(glucose) = 180 g/mol et M(X) = 2 × 180 − 18 = 342 g/mol, calcul posé","points":6},{"critere":"Différence glucose / galactose : position d'un –OH sur le carbone 4","points":3}],"dureeMin":12,"corrige":"1.\n- **X = maltose** (glucose + glucose) : produit de l'hydrolyse de l'amidon.\n- **Y = saccharose** (glucose + fructose) : le sucre de table.\n- **Z = lactose** (galactose + glucose) : le sucre du lait.\n\n2. Les oses sont reliés par une **liaison osidique**, formée par **condensation** : une molécule d'**eau est éliminée**. La digestion la coupe par **hydrolyse** (ajout d'une molécule d'eau), grâce à des enzymes.\n\n3. M(C₆H₁₂O₆) = 6 × 12 + 12 × 1 + 6 × 16 = 72 + 12 + 96 = **180 g/mol**.\nM(H₂O) = 2 × 1 + 16 = 18 g/mol.\nLe maltose se forme à partir de deux glucoses avec élimination d'une molécule d'eau :\nM(maltose) = 2 × 180 − 18 = **342 g/mol** (formule C₁₂H₂₂O₁₁).\n\n4. Le galactose ne diffère du glucose que par la **position d'un –OH sur le carbone 4**. Même formule brute, mais propriétés biologiques différentes."}$exo$::jsonb),
  ('cae06da0-6377-52bd-9c6c-06ae700b9a91'::uuid, 3, 'application', $exo${"titre":"Amidon, glycogène, cellulose : même brique, destins différents","consigne":"Réponds en justifiant chaque réponse et en posant tous les calculs.","enonce":"**Document.** L'amidon, le glycogène et la cellulose sont trois polymères de glucose.\n\n| Polymère | Particularité | Rôle |\n| Amidon | des milliers de glucoses | réserve végétale |\n| Glycogène | des milliers de glucoses, très ramifié | réserve animale (foie, muscles) |\n| Cellulose | liaisons osidiques d'une autre orientation | paroi des cellules végétales |\n\n1. Pourquoi l'amidon et le maltose sont-ils tous deux des **holosides** ? Lequel est un dimère, lequel un polymère ?\n2. On considère une chaîne linéaire formée de **1 000 glucoses**.\n   a. Combien de liaisons osidiques contient-elle ?\n   b. Combien de molécules d'eau ont été éliminées lors de sa synthèse ?\n   c. Calcule sa masse molaire. *Données : M(glucose) = 180 g/mol ; M(H₂O) = 18 g/mol.*\n3. Un élève affirme : « Puisque la cellulose est faite de glucose, nous pouvons la digérer comme l'amidon. » Critique cette affirmation.\n4. On hydrolyse complètement un échantillon inconnu, puis on analyse l'hydrolysat par chromatographie : une seule tache, au niveau du glucose. Peut-on en conclure qu'il s'agit d'amidon ? Justifie.","bareme":[{"critere":"Holoside défini (uniquement des oses), maltose dimère et amidon polymère","points":3},{"critere":"999 liaisons, 999 molécules d'eau, M = 180 000 − 17 982 = 162 018 g/mol, calculs posés","points":7},{"critere":"Critique argumentée : orientation des liaisons, enzymes qui ne reconnaissent pas la cellulose","points":5},{"critere":"Conclusion nuancée : maltose, amidon, glycogène ou cellulose donnent tous du glucose seul","points":5}],"dureeMin":20,"corrige":"1. Un **holoside** est un oside fait **uniquement d'oses**. Le maltose (glucose + glucose) est un **dimère** ; l'amidon (des milliers de glucoses) est un **polymère**.\n\n2.\na. Dans une chaîne linéaire de n glucoses, chaque liaison relie deux glucoses voisins : il y a n − 1 liaisons, soit **999 liaisons osidiques**.\nb. Chaque liaison se forme par condensation en éliminant une molécule d'eau : **999 molécules d'eau**.\nc. M = 1 000 × 180 − 999 × 18 = 180 000 − 17 982 = **162 018 g/mol** (environ 1,6 × 10⁵ g/mol).\n\n3. L'affirmation est fausse. La cellulose est bien un polymère de glucose, mais ses **liaisons osidiques ont une autre orientation** que celles de l'amidon. Nos enzymes digestives, qui coupent les liaisons de l'amidon, **ne reconnaissent pas** celles de la cellulose : nous ne pouvons pas l'hydrolyser. Même monomère, liaison différente, destin différent.\n\n4. Non. Une seule tache de glucose montre seulement que l'échantillon est un holoside **fait uniquement de glucose**. Ce peut être du **maltose**, de l'**amidon**, du **glycogène** ou de la **cellulose** : l'hydrolyse complète de chacun ne donne que du glucose. Pour conclure, il faudrait d'autres informations (origine végétale ou animale, ramification, action des enzymes digestives…)."}$exo$::jsonb),
  ('a6412e61-bbb9-516e-9b29-5567e71a56a7'::uuid, 1, 'application', $exo${"titre":"L'acide α-aminé","consigne":"Réponds à chaque question avec le vocabulaire du cours.","enonce":"1. Cite les quatre groupes portés par le **carbone α** d'un acide aminé.\n2. Pourquoi ce carbone est-il dit **asymétrique** ? Quel acide aminé fait exception, et pourquoi ?\n3. À quelle série appartiennent les acides aminés des protéines humaines ? Comment la reconnaît-on en projection de Fischer ?\n4. Complète le tableau en indiquant la propriété de chaque acide aminé.\n\n| Acide aminé | Propriété du radical |\n| Valine | ? |\n| Sérine | ? |\n| Cystéine | ? |\n| Lysine | ? (à pH 7) |\n| Acide glutamique | ? (à pH 7) |","bareme":[{"critere":"Les quatre groupes du carbone α : –NH₂, –COOH, H, radical R","points":4},{"critere":"Carbone asymétrique expliqué (quatre groupes différents) et exception de la glycine (R = H)","points":5},{"critere":"Série L, –NH₂ à gauche en projection de Fischer","points":3},{"critere":"Les cinq propriétés justes : hydrophobe, polaire, ponts disulfure, chargée +, chargé −","points":8}],"dureeMin":7,"corrige":"1. Le carbone α porte une fonction **amine –NH₂**, une fonction **acide carboxylique –COOH**, un atome d'**hydrogène** et un **radical R**, différent pour chacun des 20 acides aminés.\n\n2. Il porte **quatre groupes différents** : il est asymétrique, et il existe deux formes, images l'une de l'autre dans un miroir. Exception : la **glycine**, dont le radical est **R = H** : le carbone α porte alors deux hydrogènes, il n'est pas asymétrique.\n\n3. Les protéines n'utilisent que des acides aminés de la **série L** : en projection de Fischer, le **–NH₂ est à gauche**.\n\n4.\n- Valine : chaîne carbonée ramifiée, **hydrophobe**.\n- Sérine : –CH₂–OH, **polaire, hydrophile**.\n- Cystéine : –CH₂–SH, forme des **ponts disulfure**.\n- Lysine : chaîne terminée par –NH₂, **chargée +** à pH 7.\n- Acide glutamique : chaîne terminée par –COOH, **chargé −** à pH 7."}$exo$::jsonb),
  ('a6412e61-bbb9-516e-9b29-5567e71a56a7'::uuid, 2, 'application', $exo${"titre":"Le tripeptide Ser-Cys-Lys","consigne":"Réponds en justifiant et en posant les calculs.","enonce":"On étudie le tripeptide **Ser-Cys-Lys**, écrit dans le sens conventionnel.\n\n1. Quel acide aminé porte l'extrémité **N-terminale** ? Et l'extrémité **C-terminale** ? Justifie à partir du sens d'écriture.\n2. Combien de liaisons peptidiques contient ce tripeptide ? Entre quels groupes s'établit chacune d'elles ? Quel groupe caractéristique forme-t-elle ?\n3. **Calcul.** Calcule la masse molaire du tripeptide. *Données : M(Ser) = 105 g/mol ; M(Cys) = 121 g/mol ; M(Lys) = 146 g/mol ; M(H₂O) = 18 g/mol.*\n4. Le peptide Lys-Cys-Ser contient les mêmes acides aminés. Est-ce la même molécule ? Justifie avec la notion de structure primaire.\n5. Lequel des trois radicaux porte une charge à pH 7 ? Avec quel radical d'une autre chaîne pourrait-il former une liaison ionique ?","bareme":[{"critere":"Ser en N-terminal (–NH₂ libre), Lys en C-terminal (–COOH libre)","points":3},{"critere":"Deux liaisons peptidiques entre –COOH et –NH₂ suivant, fonction amide –CO–NH–, élimination d'eau","points":5},{"critere":"M = 105 + 121 + 146 − 2 × 18 = 336 g/mol, calcul posé","points":5},{"critere":"Structure primaire : ordre différent, molécule différente","points":4},{"critere":"Lysine chargée +, liaison ionique avec un acide glutamique (chargé −)","points":3}],"dureeMin":12,"corrige":"1. Une chaîne s'écrit de l'extrémité **N-terminale** (–NH₂ libre) vers l'extrémité **C-terminale** (–COOH libre). La **sérine** porte l'extrémité N-terminale, la **lysine** l'extrémité C-terminale.\n\n2. Trois acides aminés sont reliés par **deux liaisons peptidiques** : Ser–Cys et Cys–Lys. Chacune s'établit entre le **–COOH** d'un acide aminé et le **–NH₂** du suivant, avec **élimination d'une molécule d'eau**. Elle forme une fonction **amide –CO–NH–**.\n\n3. Deux liaisons, donc deux molécules d'eau éliminées :\nM = 105 + 121 + 146 − 2 × 18 = 372 − 36 = **336 g/mol**.\n\n4. Non. La **structure primaire** d'une protéine ou d'un peptide est l'**ordre** de ses acides aminés. Lys-Cys-Ser n'a pas le même ordre (la lysine est cette fois en N-terminal) : c'est une molécule différente, même si sa composition et sa masse molaire sont les mêmes.\n\n5. Le radical de la **lysine** est **chargé +** à pH 7 (la sérine est polaire mais non chargée, la cystéine forme des ponts disulfure). Il peut former une **liaison ionique** avec un radical de charge opposée, celui d'un **acide glutamique** (chargé −)."}$exo$::jsonb),
  ('a6412e61-bbb9-516e-9b29-5567e71a56a7'::uuid, 3, 'application', $exo${"titre":"Une forme qui tient à peu de chose","consigne":"Exploite les documents et tes connaissances pour répondre de façon argumentée.","enonce":"**Document 1 – Une enzyme chauffée.** Une solution d'enzyme est placée 10 minutes à différentes températures, puis ramenée à 37 °C avant de mesurer son activité.\n\n| Température du traitement | 37 °C | 50 °C | 70 °C | 90 °C |\n| Activité mesurée ensuite (en % de l'activité initiale) | 100 | 85 | 10 | 0 |\n\nUne analyse montre que la séquence de l'enzyme est **identique** avant et après le chauffage à 90 °C.\n\n**Document 2 – L'hémoglobine S.** Dans la drépanocytose, à un endroit de la surface de l'hémoglobine, un **acide glutamique** est remplacé par une **valine**. Les molécules d'hémoglobine S s'associent alors en longues fibres.\n\n1. Nomme les quatre types de liaisons qui maintiennent la forme tridimensionnelle d'une protéine et précise, pour chacune, entre quels éléments elle s'établit.\n2. Décris les résultats du document 1, puis explique-les. Pourquoi la séquence est-elle intacte ?\n3. À l'aide des propriétés des radicaux, explique pourquoi le remplacement décrit dans le document 2 fait s'associer les molécules d'hémoglobine.\n4. Rédige une conclusion reliant séquence, forme et fonction d'une protéine.","bareme":[{"critere":"Quatre liaisons nommées avec les éléments reliés (pont disulfure, ionique, hydrogène, hydrophobes)","points":5},{"critere":"Document 1 : description chiffrée et explication par la rupture des liaisons faibles (dénaturation), séquence intacte","points":6},{"critere":"Document 2 : Glu chargé et hydrophile remplacé par Val hydrophobe en surface, valines « collantes »","points":5},{"critere":"Conclusion séquence → forme → fonction","points":4}],"dureeMin":20,"corrige":"1.\n- **Pont disulfure** : entre deux **cystéines** ; liaison covalente, solide.\n- **Liaison ionique** : entre radicaux de **charges opposées** (Lys⁺ / Glu⁻) ; faible.\n- **Liaison hydrogène** : entre **groupes polaires** ; faible.\n- **Interactions hydrophobes** : entre **radicaux apolaires** regroupés au cœur de la protéine ; faibles.\n\n2. L'activité reste de 100 % après 37 °C, baisse à 85 % après 50 °C, chute à 10 % après 70 °C et devient nulle après 90 °C, même une fois l'enzyme ramenée à 37 °C : la perte est **définitive**.\nLa forme d'une protéine tient surtout à des **liaisons faibles**. La hausse de température les rompt : la protéine perd sa forme tridimensionnelle, elle est **dénaturée** et perd sa fonction. La séquence reste intacte car les **liaisons peptidiques** (covalentes) ne sont pas rompues : seule la forme est perdue.\n\n3. L'acide glutamique est **chargé** et **hydrophile** : à la surface de la protéine, il est au contact de l'eau. La valine qui le remplace est **hydrophobe**. Ces valines exposées en surface cherchent à fuir l'eau et établissent des **interactions hydrophobes** avec d'autres molécules d'hémoglobine : elles sont « collantes », et les molécules s'associent en longues fibres. Un seul acide aminé change, et toute la fonction s'effondre.\n\n4. La **séquence** (structure primaire) détermine les liaisons entre radicaux, donc la **forme** tridimensionnelle ; la forme détermine la **fonction**. On peut perdre la fonction en changeant la séquence (hémoglobine S) ou, sans toucher à la séquence, en détruisant la forme (dénaturation par la chaleur)."}$exo$::jsonb),
  ('ee1628d3-10b7-5f76-bcf4-0a23441168ed'::uuid, 1, 'application', $exo${"titre":"Lire le nom d'un acide gras","consigne":"Réponds à chaque question en justifiant.","enonce":"On donne trois acides gras :\n- l'acide palmitique **C16:0** ;\n- l'acide oléique **C18:1 (9)** ;\n- l'acide linoléique **C18:2 (9,12)**.\n\n1. Traduis en phrase chacune des trois notations.\n2. Classe chaque acide gras : saturé, mono-insaturé ou poly-insaturé.\n3. Lequel est majoritaire dans une matière grasse solide à 20 °C comme le beurre ? Explique pourquoi les huiles, riches en acides gras insaturés, sont liquides.\n4. Pourquoi une chaîne carbonée C–H est-elle **hydrophobe**, alors qu'un groupe –OH est **hydrophile** ?","bareme":[{"critere":"Trois notations traduites correctement (nombre de C, nombre et position des doubles liaisons, numérotation depuis la fonction acide)","points":6},{"critere":"Classement juste des trois acides gras","points":3},{"critere":"État physique expliqué : coude de la double liaison qui gêne l'empilement","points":5},{"critere":"Polarité expliquée par l'électronégativité et les liaisons hydrogène avec l'eau","points":6}],"dureeMin":8,"corrige":"1.\n- **C16:0** : 16 carbones, **aucune** double liaison C=C.\n- **C18:1 (9)** : 18 carbones, **1** double liaison, qui part du **carbone 9**.\n- **C18:2 (9,12)** : 18 carbones, **2** doubles liaisons, partant des carbones **9 et 12**.\nLes carbones sont numérotés depuis le carbone de la fonction acide (carbone 1).\n\n2. Acide palmitique : **saturé** ; acide oléique : **mono-insaturé** ; acide linoléique : **poly-insaturé**.\n\n3. Le beurre, solide à 20 °C, est riche en acides gras **saturés** comme l'acide palmitique. Dans un acide gras insaturé, la **double liaison crée un coude** dans la chaîne, qui **gêne l'empilement** des molécules : elles restent dispersées, d'où l'état liquide des huiles.\n\n4. Dans la liaison O–H, l'oxygène est plus **électronégatif** que l'hydrogène : il attire les électrons, la liaison est **polaire**. Les groupes polaires forment des **liaisons hydrogène** avec l'eau : ils sont hydrophiles. Les liaisons C–H sont **apolaires** : elles ne forment pas de liaisons hydrogène avec l'eau, la chaîne est hydrophobe."}$exo$::jsonb),
  ('ee1628d3-10b7-5f76-bcf4-0a23441168ed'::uuid, 2, 'application', $exo${"titre":"La tripalmitine, un triglycéride de réserve","consigne":"Réponds en justifiant et en posant les calculs.","enonce":"La **tripalmitine** est un triglycéride formé à partir de glycérol et de trois molécules d'acide palmitique (C16:0).\n\n*Données : glycérol C₃H₈O₃ ; acide palmitique C₁₆H₃₂O₂ ; M(C) = 12 g/mol ; M(H) = 1 g/mol ; M(O) = 16 g/mol. La formation d'une fonction ester entre une fonction alcool et une fonction acide carboxylique élimine une molécule d'eau.*\n\n1. Combien de fonctions alcool porte le glycérol ? Combien de fonctions ester contient la tripalmitine ?\n2. Calcule la masse molaire du glycérol, de l'acide palmitique, puis de la tripalmitine.\n3. Pourquoi un triglycéride est-il **totalement hydrophobe** ? Où l'organisme le stocke-t-il ?\n4. Un phospholipide ne porte que deux acides gras. Qu'est-ce qui remplace le troisième, et quelle propriété nouvelle en résulte ?","bareme":[{"critere":"Trois fonctions alcool, trois fonctions ester","points":3},{"critere":"M(glycérol) = 92, M(acide palmitique) = 256, M(tripalmitine) = 92 + 768 − 54 = 806 g/mol, calculs posés","points":8},{"critere":"Triglycéride hydrophobe expliqué (fonctions alcool engagées, longues chaînes apolaires), stockage dans le tissu adipeux","points":4},{"critere":"Phospholipide : groupement phosphate, tête hydrophile, molécule amphiphile","points":5}],"dureeMin":12,"corrige":"1. Le glycérol porte **trois fonctions alcool** ; chacune est estérifiée par un acide gras : la tripalmitine contient **trois fonctions ester** (–COO–).\n\n2.\n- M(glycérol) = 3 × 12 + 8 × 1 + 3 × 16 = 36 + 8 + 48 = **92 g/mol**.\n- M(acide palmitique) = 16 × 12 + 32 × 1 + 2 × 16 = 192 + 32 + 32 = **256 g/mol**.\n- M(H₂O) = 18 g/mol ; trois liaisons ester, donc trois molécules d'eau éliminées :\nM(tripalmitine) = 92 + 3 × 256 − 3 × 18 = 92 + 768 − 54 = **806 g/mol**.\n\n3. Les trois fonctions alcool du glycérol sont engagées dans des liaisons ester : il ne reste pas de groupe –OH libre capable de former des liaisons hydrogène avec l'eau, et la molécule est dominée par trois **longues chaînes carbonées apolaires**. Elle est totalement hydrophobe. C'est la **forme de réserve** des lipides, stockée dans le **tissu adipeux**.\n\n4. Le troisième acide gras est remplacé par un **groupement phosphate**, qui forme une **tête hydrophile**, tandis que les deux acides gras forment des **queues hydrophobes**. Le phospholipide est **amphiphile** : dans l'eau, il s'organise spontanément en bicouche (les micelles se forment surtout avec des amphiphiles à une seule chaîne, comme les savons)."}$exo$::jsonb),
  ('ee1628d3-10b7-5f76-bcf4-0a23441168ed'::uuid, 3, 'application', $exo${"titre":"Ce qui traverse la membrane","consigne":"Exploite le document et tes connaissances pour répondre de façon argumentée.","enonce":"**Document – Des vésicules artificielles.** Un laboratoire fabrique des vésicules dont la paroi est une **bicouche de phospholipides pure**, sans protéine. On mesure si différentes molécules, placées à l'extérieur, entrent dans les vésicules.\n\n| Molécule | Bicouche pure | Bicouche + protéine A | Bicouche + protéine B |\n| Dioxygène O₂ | entre | entre | entre |\n| Ion Na⁺ | n'entre pas | n'entre pas | n'entre pas |\n| Glucose | n'entre pas | entre | n'entre pas |\n| Eau | entre très lentement | entre très lentement | entre rapidement |\n\n1. Explique comment des phospholipides placés dans l'eau forment spontanément une bicouche. Fais un schéma légendé.\n2. Explique les résultats obtenus avec la bicouche pure pour O₂, Na⁺ et le glucose.\n3. Identifie la nature et le rôle des protéines A et B, en donnant pour chacune un exemple du cours.\n4. Une autre protéine membranaire, le récepteur de l'insuline, fixe l'insuline. D'après le cours, l'insuline entre-t-elle dans la cellule ? Distingue récepteur et transporteur.\n5. Le cholestérol est aussi présent dans les membranes animales. Par quel motif structural le reconnaît-on, et dans quelles autres molécules retrouve-t-on ce motif ?","bareme":[{"critere":"Bicouche expliquée par le caractère amphiphile (têtes vers l'eau, queues face à face), schéma légendé","points":5},{"critere":"Résultats de la bicouche pure expliqués : O₂ apolaire traverse, ions et grosses molécules polaires bloqués","points":4},{"critere":"A = transporteur du glucose, B = aquaporine, rôle de transport justifié par le tableau","points":5},{"critere":"Récepteur : fixe le messager sans le faire entrer et déclenche une réponse ; différence avec le transporteur","points":3},{"critere":"Noyau stérane (quatre cycles) et hormones stéroïdes (testostérone, œstrogènes, progestérone)","points":3}],"dureeMin":20,"corrige":"1. Un phospholipide est **amphiphile** : une tête hydrophile (groupement phosphate) et deux queues hydrophobes (acides gras). Dans l'eau, les têtes se tournent vers l'eau et les queues la fuient : les phospholipides s'organisent en **deux couches**, têtes vers l'eau de chaque côté, **queues face à face** au centre.\nSchéma attendu : deux rangées de phospholipides, têtes (ronds) vers le milieu aqueux extérieur et intérieur, queues au centre ; légendes « tête hydrophile », « queues hydrophobes », « eau ».\n\n2. Le centre de la bicouche est **hydrophobe**. Le **dioxygène**, petite molécule **apolaire**, s'y dissout et la traverse. L'ion **Na⁺** (chargé) et le **glucose** (grosse molécule polaire) ne peuvent pas traverser cette zone hydrophobe : ils ont besoin de protéines.\n\n3.\n- **Protéine A** : elle fait entrer le glucose, qui ne passait pas seul → c'est un **transporteur** du glucose.\n- **Protéine B** : elle accélère fortement l'entrée d'eau → c'est une **aquaporine**, un transporteur d'eau.\nUn transporteur fait **passer** une molécule d'un côté à l'autre de la membrane. Aucune des deux ne fait entrer Na⁺ : chaque transporteur est spécifique.\n\n4. Non : un **récepteur fixe** son messager **sans le faire entrer** et déclenche une réponse dans la cellule. Le **transporteur**, lui, fait passer la molécule d'un côté à l'autre.\n\n5. Le cholestérol porte un **noyau à quatre cycles**, le **noyau stérane**. On le retrouve dans les **hormones stéroïdes** : testostérone, œstrogènes, progestérone."}$exo$::jsonb),
  ('35960909-47a6-58a2-937a-6405263073fd'::uuid, 1, 'application', $exo${"titre":"Le nucléotide et le brin complémentaire","consigne":"Réponds à chaque question en justifiant.","enonce":"1. Cite les trois constituants d'un nucléotide d'ADN.\n2. Quelle liaison relie les nucléotides d'un même brin ? Pourquoi un brin a-t-il une extrémité 5' et une extrémité 3' ?\n3. Écris le brin complémentaire de **5'-ATGCCA-3'**, d'abord de 3' vers 5', puis dans le sens conventionnel.\n4. Complète le tableau comparatif.\n\n| | ADN | ARN |\n| Ose | ? | ? |\n| Bases | ? | ? |\n| Nombre de brins | ? | ? |\n| Rôle | ? | ? |","bareme":[{"critere":"Phosphate, désoxyribose, base azotée","points":3},{"critere":"Liaison phosphodiester et extrémités 5' (phosphate libre) et 3' (–OH libre)","points":4},{"critere":"Brin complémentaire juste : 3'-TACGGT-5' puis 5'-TGGCAT-3'","points":6},{"critere":"Tableau complet et juste","points":7}],"dureeMin":8,"corrige":"1. Un **groupement phosphate**, un ose à cinq carbones, le **désoxyribose**, et une **base azotée** (A, T, G ou C).\n\n2. Les nucléotides sont reliés par des **liaisons phosphodiester**, entre le phosphate de l'un et l'ose du suivant. Le premier nucléotide garde un **phosphate libre** (extrémité **5'**), le dernier un **–OH libre** (extrémité **3'**) : les deux extrémités sont différentes, le brin est orienté.\n\n3. Appariement A–T et G–C, brins antiparallèles :\n5'-A T G C C A-3'\n3'-T A C G G T-5'\nÉcrit dans le sens conventionnel (5' vers 3') : **5'-TGGCAT-3'**.\n\n4.\n| | ADN | ARN |\n| Ose | désoxyribose | ribose |\n| Bases | A, T, G, C | A, U, G, C |\n| Nombre de brins | deux | un seul |\n| Rôle | stocker l'information | la transmettre (ARN messager) |"}$exo$::jsonb),
  ('35960909-47a6-58a2-937a-6405263073fd'::uuid, 2, 'application', $exo${"titre":"Compter les bases et les liaisons hydrogène","consigne":"Pose tous les calculs et justifie avec les règles d'appariement.","enonce":"Un fragment d'ADN double brin **F1** compte **200 paires de bases** et contient **22 % de guanine**.\n\n1. Calcule le pourcentage de chacune des trois autres bases. Justifie.\n2. Calcule le nombre total de nucléotides de F1, puis le nombre de nucléotides de chaque base.\n3. Combien F1 compte-t-il de paires G–C et de paires A–T ? Calcule le nombre total de liaisons hydrogène entre ses deux brins.\n4. Un second fragment **F2**, lui aussi de 200 paires de bases, contient 30 % de guanine. Calcule son nombre de liaisons hydrogène. Lequel des deux fragments se dénature à la plus haute température ? Justifie.","bareme":[{"critere":"Pourcentages justes et justifiés : C = 22 %, A = T = 28 %","points":5},{"critere":"400 nucléotides ; G = C = 88, A = T = 112","points":4},{"critere":"88 paires G–C, 112 paires A–T, 112 × 2 + 88 × 3 = 488 liaisons hydrogène","points":5},{"critere":"F2 : 520 liaisons hydrogène, se dénature à plus haute température, justification par les paires G–C","points":6}],"dureeMin":12,"corrige":"1. Dans l'ADN double brin, G s'apparie avec C et A avec T : %C = %G = **22 %**. Il reste 100 − 44 = 56 % pour A et T, avec %A = %T : **A = 28 %** et **T = 28 %**.\n\n2. 200 paires de bases = 2 × 200 = **400 nucléotides**.\nG = C = 22 % × 400 = **88** ; A = T = 28 % × 400 = **112**. Vérification : 88 + 88 + 112 + 112 = 400.\n\n3. Chaque G est apparié à un C : **88 paires G–C** ; il reste 200 − 88 = **112 paires A–T**.\nUne paire A–T compte **2** liaisons hydrogène, une paire G–C en compte **3** :\n112 × 2 + 88 × 3 = 224 + 264 = **488 liaisons hydrogène**.\n\n4. F2 : G = 30 % de 400 = 120, donc 120 paires G–C et 200 − 120 = 80 paires A–T.\n80 × 2 + 120 × 3 = 160 + 360 = **520 liaisons hydrogène**.\nLa dénaturation sépare les deux brins en rompant les liaisons hydrogène, qui sont faibles. F2, plus riche en G–C, compte plus de liaisons hydrogène (520 contre 488) : il **résiste mieux à la chaleur** et se dénature à plus haute température."}$exo$::jsonb),
  ('35960909-47a6-58a2-937a-6405263073fd'::uuid, 3, 'application', $exo${"titre":"Choisir la bonne sonde","consigne":"Justifie chaque réponse avec les propriétés des acides nucléiques. Écris toutes les séquences de 5' vers 3'.","enonce":"**Situation.** Un laboratoire veut repérer, dans un échantillon, un fragment d'ADN dont l'un des brins a pour séquence :\n\n**5'-GGATCCATGAAC-3'**\n\nIl dispose de trois sondes marquées, simple brin :\n- P1 : 5'-GTTCATGG-3'\n- P2 : 5'-CCATGAAC-3'\n- P3 : 5'-GGTACTTG-3'\n\n1. Explique le principe de l'hybridation moléculaire. Pourquoi faut-il d'abord chauffer l'échantillon vers 90 °C ?\n2. Écris le brin complémentaire du brin donné, de 5' vers 3'.\n3. Laquelle des trois sondes peut s'hybrider au brin donné ? Sur quelle partie ? Justifie en écrivant l'appariement.\n4. Explique l'erreur commise par le technicien qui a conçu P3.\n5. La sonde P2 peut-elle servir à quelque chose ? Justifie.","bareme":[{"critere":"Principe de l'hybridation : complémentarité, liaisons hydrogène faibles, dénaturation puis réassociation avec la sonde","points":5},{"critere":"Brin complémentaire juste : 5'-GTTCATGGATCC-3'","points":4},{"critere":"P1 identifiée, région 5'-CCATGAAC-3', appariement antiparallèle écrit","points":5},{"critere":"Erreur de P3 expliquée (complément écrit sans inverser le sens)","points":3},{"critere":"P2 : identique à une partie du brin donné, s'hybride au brin complémentaire","points":3}],"dureeMin":20,"corrige":"1. Deux brins complémentaires et antiparallèles s'apparient par des **liaisons hydrogène** (A–T, G–C). Ces liaisons sont **faibles** : en chauffant vers 90 °C, les deux brins de l'ADN se séparent (**dénaturation**) ; en refroidissant, un brin peut s'apparier à une **sonde** complémentaire, même d'une autre origine : c'est l'**hybridation moléculaire**. Il faut chauffer d'abord pour rendre le brin cible **accessible** à la sonde.\n\n2. Brin donné : 5'-GGATCCATGAAC-3'\nComplémentaire : 3'-CCTAGGTACTTG-5', soit **5'-GTTCATGGATCC-3'**.\n\n3. **P1** s'hybride au brin donné, sur la région **5'-CCATGAAC-3'** (nucléotides 5 à 12) :\n5'-…C C A T G A A C-3' (brin donné)\n3'-G G T A C T T G-5' (P1 lue de 3' vers 5')\nToutes les paires sont complémentaires (C–G, A–T) et les brins antiparallèles.\n\n4. P3 = 5'-GGTACTTG-3' est la suite complémentaire de la région cible **lue de 3' vers 5'**, recopiée **sans inverser le sens**. Écrite ainsi, elle n'est pas antiparallèle à la cible : elle ne s'y hybride pas. Il fallait l'écrire 5'-GTTCATGG-3' (c'est P1).\n\n5. P2 = 5'-CCATGAAC-3' est **identique** à une partie du brin donné : elle ne s'y hybride pas, mais elle est complémentaire de l'**autre brin** du fragment (5'-GTTCATGGATCC-3', région GTTCATGG). Après dénaturation du double brin, P2 peut donc repérer le même fragment en s'hybridant au brin complémentaire."}$exo$::jsonb),
  ('0f384b6d-1bab-5863-bef6-173203dd8097'::uuid, 1, 'application', $exo${"titre":"Échelles et outils d'observation","consigne":"Réponds à chaque question en posant les conversions et les calculs.","enonce":"*Rappels : 1 mm = 1 000 µm ; 1 µm = 1 000 nm.*\n\n1. Convertis : 0,2 µm en nm ; 25 µm en mm ; 7 nm en µm.\n2. Sur une photographie prise au microscope optique et agrandie **500 fois**, une cellule mesure **15 mm**. Calcule sa taille réelle en µm.\n3. Pour chaque objet, donne un ordre de grandeur de sa taille et l'outil qui permet de l'observer :\n   a. un rein ;\n   b. une cellule animale ;\n   c. un virus ;\n   d. la membrane plasmique.\n4. Remets dans l'ordre, du plus grand au plus petit : tissu, organite, organe, cellule, molécule, appareil.","bareme":[{"critere":"Trois conversions justes : 200 nm ; 0,025 mm ; 0,007 µm","points":5},{"critere":"Taille réelle : 15 mm / 500 = 0,03 mm = 30 µm, calcul posé","points":5},{"critere":"Quatre tailles et outils justes","points":6},{"critere":"Ordre des niveaux d'organisation juste","points":4}],"dureeMin":8,"corrige":"1.\n- 0,2 µm = 0,2 × 1 000 = **200 nm**.\n- 25 µm = 25 / 1 000 = **0,025 mm**.\n- 7 nm = 7 / 1 000 = **0,007 µm**.\n\n2. Taille réelle = taille sur la photo / grossissement = 15 mm / 500 = **0,03 mm** = 0,03 × 1 000 = **30 µm**. C'est bien dans l'ordre de grandeur d'une cellule animale (10 à 100 µm).\n\n3.\na. Rein : ≈ **10 cm** ; œil, imagerie médicale.\nb. Cellule animale : **10 à 100 µm** ; microscope optique.\nc. Virus : **20 à 300 nm** ; microscope électronique.\nd. Membrane plasmique : ≈ **7 nm** ; microscope électronique.\n\n4. **Appareil → organe → tissu → cellule → organite → molécule.**"}$exo$::jsonb),
  ('0f384b6d-1bab-5863-bef6-173203dd8097'::uuid, 2, 'application', $exo${"titre":"Une cellule qui sécrète","consigne":"Exploite le document et justifie chaque réponse ; pose les calculs.","enonce":"**Document – Description d'une électronographie** (cliché au microscope électronique, grossissement **× 20 000**) d'une cellule d'une glande qui sécrète une enzyme digestive :\n\n> Un gros noyau entouré d'une enveloppe double, percée de pores. Un réseau très développé de membranes couvertes de petits grains (des ribosomes). Des empilements de saccules aplatis, entourés de nombreuses vésicules. Des vésicules qui fusionnent avec la membrane plasmique du côté de la face apicale. Plusieurs organites allongés, dont l'un mesure **20 mm** sur le cliché.\n\n1. Nomme les organites décrits et donne le rôle de chacun.\n2. Calcule la taille réelle de l'organite allongé, en µm. De quel organite s'agit-il probablement ? Justifie.\n3. Retrace, dans l'ordre, le trajet de l'enzyme depuis sa synthèse jusqu'à sa libération. Nomme le phénomène final.\n4. Aurait-on pu observer ces détails au microscope optique ? Justifie avec la limite de résolution.\n5. Cite deux différences entre cette cellule et une bactérie.","bareme":[{"critere":"Organites identifiés et rôles justes : noyau, réticulum rugueux, Golgi, vésicules, mitochondries","points":5},{"critere":"Calcul : 20 mm / 20 000 = 0,001 mm = 1 µm, organite identifié (mitochondrie)","points":4},{"critere":"Voie de sécrétion dans l'ordre et exocytose décrite","points":5},{"critere":"Limite du microscope optique (0,2 µm) appliquée","points":3},{"critere":"Deux différences avec une bactérie (pas de noyau, pas d'organites membranaires, ADN libre)","points":3}],"dureeMin":12,"corrige":"1.\n- **Noyau** : protège l'ADN ; enveloppe nucléaire double percée de **pores nucléaires**.\n- Réseau de membranes couvertes de ribosomes : **réticulum endoplasmique rugueux**, synthèse des protéines destinées à la sécrétion.\n- Empilements de saccules : **appareil de Golgi**, modifie et emballe les protéines dans des **vésicules**.\n- Organites allongés : **mitochondries**, respiration cellulaire et production d'ATP.\n- **Membrane plasmique** : limite et échanges.\n\n2. Taille réelle = 20 mm / 20 000 = **0,001 mm = 1 µm**. Une taille d'environ 1 µm, une forme allongée : c'est probablement une **mitochondrie** (≈ 1 µm).\n\n3. Ribosome → **réticulum endoplasmique rugueux** → **appareil de Golgi** → **vésicule** → **exocytose** : la vésicule fusionne avec la membrane plasmique et libère son contenu hors de la cellule (ici du côté apical).\n\n4. Non. Le microscope optique ne distingue pas deux points séparés de moins de **0,2 µm** environ : les détails des membranes (7 nm), des ribosomes ou de l'intérieur des mitochondries sont bien plus petits. Il faut le **microscope électronique**, qui descend au nanomètre.\n\n5. Une bactérie (cellule **procaryote**) n'a **pas de noyau** : son ADN est libre dans le cytoplasme ; elle n'a **pas d'organites membranaires** (ni réticulum, ni Golgi, ni mitochondries) ; elle est aussi plus petite (1 à 5 µm)."}$exo$::jsonb),
  ('0f384b6d-1bab-5863-bef6-173203dd8097'::uuid, 3, 'application', $exo${"titre":"Du service de radiologie au microscope","consigne":"Justifie chaque choix et chaque calcul avec les notions du cours.","enonce":"**Partie A – Choisir l'imagerie.** Pour chaque patient, choisis la technique la plus adaptée (radiographie, radiographie avec produit de contraste, échographie) et justifie par son principe et par le tissu observé.\n1. Hugo, 16 ans, est tombé au ski ; on suspecte une fracture du poignet.\n2. Nora est enceinte de 12 semaines ; on veut contrôler le développement du fœtus.\n3. On veut observer le trajet du tube digestif de M. Lambert.\n4. On veut observer les reins d'un enfant de 6 ans.\n\n**Partie B – Changer d'échelle.** Sur une électronographie agrandie **100 000 fois**, un virus mesure **12 mm**.\n5. Calcule sa taille réelle en nm. Aurait-on pu l'observer au microscope optique ?\n6. Sur le même cliché, quelle longueur mesurerait une membrane plasmique de 7 nm d'épaisseur ?\n\n**Partie C – Un tissu adapté.**\n7. Décris l'organisation d'un épithélium intestinal et explique en quoi sa structure est adaptée à l'absorption.","bareme":[{"critere":"Quatre choix d'imagerie justes et justifiés par le principe et le tissu (os, tissus mous, absence de rayonnement ionisant, contraste)","points":8},{"critere":"Virus : 12 mm / 100 000 = 120 nm, invisible au microscope optique (< 0,2 µm)","points":4},{"critere":"Membrane : 7 nm × 100 000 = 0,7 mm","points":3},{"critere":"Épithélium : cellules jointives polarisées, membrane basale, jonctions serrées, lien avec l'absorption","points":5}],"dureeMin":20,"corrige":"**Partie A**\n1. **Radiographie** : les rayons X sont absorbés par les tissus denses ; l'os apparaît blanc, une fracture se voit bien.\n2. **Échographie** : les ultrasons se réfléchissent aux interfaces et montrent bien les **tissus mous** (fœtus) ; ils ne sont **pas ionisants**, donc sans danger pendant la grossesse.\n3. **Radiographie avec produit de contraste** : le tube digestif est un tissu mou, peu contrasté aux rayons X ; une substance opaque aux rayons X, avalée, le rend visible.\n4. **Échographie** : les reins sont des organes mous, et on évite le rayonnement ionisant chez un enfant.\n\n**Partie B**\n5. Taille réelle = 12 mm / 100 000 = 0,00012 mm = 0,12 µm = **120 nm**. Elle est inférieure à **0,2 µm**, limite du microscope optique : le virus n'y est pas observable. Il faut le **microscope électronique**.\n6. Longueur sur le cliché = 7 nm × 100 000 = 700 000 nm = 700 µm = **0,7 mm**.\n\n**Partie C**\n7. Un épithélium est un tissu de **cellules jointives** posé sur une **membrane basale**. Dans l'intestin, les cellules sont **polarisées** : une face apicale tournée vers la cavité intestinale, une face basale tournée vers la membrane basale. Elles sont reliées par des **jonctions serrées**, qui empêchent le passage entre les cellules : les molécules absorbées doivent traverser les cellules, de la face apicale à la face basale. Cette organisation permet une absorption contrôlée, dans un seul sens."}$exo$::jsonb),
  ('38889374-0809-5bef-86d2-aa529291761c'::uuid, 1, 'application', $exo${"titre":"Les compartiments liquidiens","consigne":"Réponds en posant les calculs et en justifiant.","enonce":"Léo pèse **70 kg**. L'eau représente environ **60 %** de la masse d'un adulte. On admet qu'1 kg d'eau occupe 1 L.\n\n1. Calcule le volume d'eau total de Léo.\n2. Calcule le volume de chaque compartiment : liquide intracellulaire (≈ 2/3 de l'eau totale), liquide interstitiel (≈ 1/4), plasma (≈ 1/12).\n3. Quels compartiments forment le **milieu intérieur** ?\n4. Quel ion est le plus concentré dans le liquide intracellulaire ? et dans le liquide interstitiel ?\n5. Pourquoi le liquide interstitiel est-il pauvre en grosses protéines alors que le plasma en est riche ?","bareme":[{"critere":"Eau totale : 60 % × 70 = 42 L","points":3},{"critere":"Trois volumes justes : 28 L, 10,5 L, 3,5 L, calculs posés","points":7},{"critere":"Milieu intérieur = liquide extracellulaire (interstitiel, plasma, lymphe)","points":4},{"critere":"K⁺ dans la cellule, Na⁺ à l'extérieur ; protéines retenues par la paroi des capillaires","points":6}],"dureeMin":8,"corrige":"1. Eau totale = 60 % × 70 kg = 0,60 × 70 = **42 kg**, soit **42 L**.\n\n2.\n- Liquide intracellulaire : 2/3 × 42 = **28 L**.\n- Liquide interstitiel : 1/4 × 42 = **10,5 L**.\n- Plasma : 1/12 × 42 = **3,5 L**.\nVérification : 28 + 10,5 + 3,5 = 42 L (la lymphe canalisée représente un faible volume).\n\n3. Le milieu intérieur est le **liquide extracellulaire** : **liquide interstitiel**, **plasma** et **lymphe**. Le liquide intracellulaire n'en fait pas partie.\n\n4. Dans le liquide intracellulaire, l'ion le plus concentré est **K⁺** ; dans le liquide interstitiel (comme dans le plasma), c'est **Na⁺**.\n\n5. Au niveau des capillaires, le plasma filtre vers le liquide interstitiel, mais les **grosses protéines ne traversent pas la paroi des capillaires** : elles restent dans le plasma. Le liquide interstitiel ressemble donc au plasma sans ses grosses protéines."}$exo$::jsonb),
  ('38889374-0809-5bef-86d2-aa529291761c'::uuid, 2, 'application', $exo${"titre":"Un bilan sanguin et trois tubes","consigne":"Exploite les documents et justifie chaque réponse.","enonce":"**Document 1 – Extrait du bilan sanguin de Mme Duval.**\n\n| Paramètre (plasma) | Résultat | Intervalle physiologique du laboratoire |\n| Na⁺ | 128 mmol·L⁻¹ | 135 – 145 mmol·L⁻¹ |\n| K⁺ | 4,2 mmol·L⁻¹ | 3,5 – 5,0 mmol·L⁻¹ |\n| Glucose (à jeun) | 0,95 g·L⁻¹ | 0,70 – 1,10 g·L⁻¹ |\n\n**Document 2 – Expérience.** On place des globules rouges dans trois tubes :\n- tube 1 : eau pure ;\n- tube 2 : solution de même concentration en solutés que le plasma ;\n- tube 3 : solution très salée.\n\n1. Qu'est-ce qu'un intervalle physiologique ? Analyse le bilan de Mme Duval paramètre par paramètre.\n2. Définis l'osmose.\n3. Prévois et explique ce qui arrive aux globules rouges dans chaque tube.\n4. Entre le liquide interstitiel et une cellule, par quel mode passent le dioxygène, le glucose et l'eau ?","bareme":[{"critere":"Intervalle physiologique défini, Na⁺ hors intervalle (trop bas), K⁺ et glucose normaux","points":5},{"critere":"Osmose définie : passage de l'eau vers le compartiment le plus concentré en solutés","points":4},{"critere":"Trois tubes expliqués : gonfle et éclate, pas de changement, se ratatine","points":7},{"critere":"Modes de passage : diffusion (O₂), transporteur (glucose), osmose (eau)","points":4}],"dureeMin":12,"corrige":"1. Un **intervalle physiologique** est la fourchette de valeurs normales d'un constituant autour de sa valeur de référence ; un bilan compare chaque résultat à cet intervalle.\n- **Na⁺ = 128 mmol·L⁻¹** : **inférieur** à 135, hors de l'intervalle : écart à la normale, à signaler au médecin.\n- **K⁺ = 4,2 mmol·L⁻¹** : compris entre 3,5 et 5,0, **normal**.\n- **Glucose = 0,95 g·L⁻¹** : compris entre 0,70 et 1,10, **normal**.\n\n2. L'**osmose** est le passage de l'**eau** à travers une membrane vers le compartiment **le plus concentré en solutés**.\n\n3.\n- **Tube 1 (eau pure)** : l'intérieur du globule rouge est plus concentré que l'eau pure ; l'eau entre dans la cellule, qui **gonfle et peut éclater**.\n- **Tube 2** : les concentrations sont égales de part et d'autre ; il n'y a pas d'entrée nette d'eau, le globule rouge **garde sa forme**.\n- **Tube 3 (très salé)** : l'extérieur est plus concentré ; l'eau sort de la cellule, qui **se ratatine**.\n\n4. Le **dioxygène** passe par **diffusion** ; le **glucose** par un **transporteur** ; l'**eau** par **osmose**."}$exo$::jsonb),
  ('38889374-0809-5bef-86d2-aa529291761c'::uuid, 3, 'application', $exo${"titre":"L'hyperglycémie provoquée","consigne":"Exploite le document et utilise le vocabulaire de la boucle de régulation.","enonce":"**Document – Test d'hyperglycémie provoquée.** À jeun, deux personnes boivent une solution contenant 75 g de glucose. On mesure leur glycémie (en g·L⁻¹) et leur insulinémie.\n\n| Temps (min) | 0 | 30 | 60 | 120 |\n| Glycémie de Camille | 0,90 | 1,50 | 1,20 | 0,95 |\n| Glycémie de Paul | 1,20 | 2,30 | 2,50 | 2,10 |\n\nL'insulinémie de Camille augmente fortement après l'ingestion ; celle de Paul reste presque nulle pendant tout le test.\n*Intervalle physiologique de la glycémie à jeun : 0,70 – 1,10 g·L⁻¹.*\n\n1. Décris l'évolution de la glycémie de Camille et identifie la perturbation, la réponse et la correction.\n2. Complète la boucle de régulation de la glycémie : grandeur régulée, capteurs, messagers, effecteurs. Quel type de rétroaction met-elle en jeu ?\n3. Compare les résultats de Paul à ceux de Camille. Quel maillon de la boucle est défaillant chez lui ? Justifie.\n4. Sur le même modèle, donne les éléments de la boucle de régulation du volume d'eau du plasma.","bareme":[{"critere":"Description chiffrée pour Camille et identification perturbation / réponse / correction","points":5},{"critere":"Boucle de la glycémie complète (pancréas, insuline et glucagon, foie, muscles, tissu adipeux) et rétroaction négative","points":5},{"critere":"Paul : glycémie à jeun hors intervalle, pas de retour, absence d'insuline, pathologie","points":6},{"critere":"Boucle de la volémie : hypothalamus, ADH, rein (tube collecteur)","points":4}],"dureeMin":20,"corrige":"1. À jeun, la glycémie de Camille est de 0,90 g·L⁻¹, dans l'intervalle physiologique. Après l'ingestion de glucose (**perturbation**), elle monte à 1,50 g·L⁻¹ à 30 min ; l'insuline est libérée (**réponse**) ; la glycémie redescend à 1,20 puis 0,95 g·L⁻¹ à 120 min, près de sa valeur de départ (**correction**).\n\n2.\n- **Grandeur régulée** : la glycémie, comparée à une **valeur de consigne**.\n- **Capteurs** : les cellules du **pancréas**.\n- **Messagers** : l'**insuline** (et le glucagon).\n- **Effecteurs** : le **foie**, les **muscles**, le **tissu adipeux**.\nLa réponse s'oppose à l'écart et ramène la grandeur vers la consigne : c'est une **rétroaction négative**.\n\n3. Chez Paul, la glycémie à jeun (1,20 g·L⁻¹) est déjà **au-dessus** de l'intervalle (1,10). Après l'ingestion, elle monte jusqu'à 2,50 g·L⁻¹ et reste à 2,10 g·L⁻¹ à 120 min : la perturbation **n'est pas corrigée**. Son insulinémie reste presque nulle : le maillon défaillant est le **messager**, l'**insuline**, qui n'est pas libérée. Sans elle, les effecteurs ne reçoivent pas l'ordre de faire baisser la glycémie. Un maillon manquant rend la boucle inopérante : c'est une **pathologie** (on accepte le mot « diabète »).\n\n4. Volume d'eau du plasma :\n- grandeur régulée : volume et concentration du plasma ;\n- capteurs : capteurs de l'**hypothalamus** ;\n- messager : l'**ADH** ;\n- effecteur : le **rein** (tube collecteur)."}$exo$::jsonb),
  ('827909f0-e2f6-57cd-94eb-f5c3af3ca978'::uuid, 1, 'application', $exo${"titre":"Du brin transcrit au peptide","consigne":"Applique la méthode du cours et justifie chaque étape.","enonce":"Voici le **brin transcrit** d'un court gène :\n\n**3'-TAC GGA AAA ACC ATT-5'**\n\n*Extrait du code génétique : AUG = Met (initiation) ; CCU = Pro ; UUU = Phe ; UGG = Trp ; UAA, UAG, UGA = stop.*\n\n1. Où a lieu la transcription chez les eucaryotes ? Quelle enzyme la réalise ?\n2. Écris la séquence de l'ARN messager, de 5' vers 3'.\n3. Écris la séquence du brin non transcrit (brin codant) de l'ADN, de 5' vers 3'. Que remarques-tu ?\n4. Traduis l'ARNm et écris le peptide obtenu. Où a lieu la traduction ?","bareme":[{"critere":"Transcription dans le noyau par l'ARN polymérase","points":3},{"critere":"ARNm juste : 5'-AUG CCU UUU UGG UAA-3'","points":6},{"critere":"Brin non transcrit juste et remarque (même séquence que l'ARNm avec T au lieu de U)","points":5},{"critere":"Peptide Met-Pro-Phe-Trp, codon stop non traduit, traduction sur les ribosomes du cytoplasme","points":6}],"dureeMin":8,"corrige":"1. La transcription a lieu dans le **noyau** ; elle est réalisée par l'**ARN polymérase**.\n\n2. L'ARNm est complémentaire du brin transcrit, avec **U à la place de T** (A → U, T → A, G → C, C → G) :\nbrin transcrit : 3'-TAC GGA AAA ACC ATT-5'\n**ARNm : 5'-AUG CCU UUU UGG UAA-3'**\n\n3. Brin non transcrit : **5'-ATG CCT TTT TGG TAA-3'**. C'est la **même séquence que l'ARNm**, avec T à la place de U.\n\n4. AUG → **Met** (initiation, fixe le cadre de lecture) ; CCU → **Pro** ; UUU → **Phe** ; UGG → **Trp** ; UAA → **stop** (aucun acide aminé).\nPeptide : **Met-Pro-Phe-Trp**.\nLa traduction a lieu dans le **cytoplasme**, sur les **ribosomes** ; l'ARNm est sorti du noyau par les pores nucléaires."}$exo$::jsonb),
  ('827909f0-e2f6-57cd-94eb-f5c3af3ca978'::uuid, 2, 'application', $exo${"titre":"Trois allèles mutés","consigne":"Compare les séquences codon par codon et nomme chaque mutation en justifiant.","enonce":"On donne le **brin non transcrit** de l'allèle sauvage d'un gène (début de la séquence codante) et de trois allèles mutés :\n\n| Allèle | Brin non transcrit (5' → 3') |\n| Sauvage | ATG GAG AAG CCT TGG TAA |\n| Muté 1 | ATG GAG AAG CCC TGG TAA |\n| Muté 2 | ATG GTG AAG CCT TGG TAA |\n| Muté 3 | ATG GAG TAG CCT TGG TAA |\n\n*Extrait du code génétique : AUG = Met ; GAG = Glu ; GUG = Val ; AAG = Lys ; CCU = Pro ; CCC = Pro ; UGG = Trp ; UAA, UAG, UGA = stop.*\n\n1. Écris l'ARNm de l'allèle sauvage et le peptide qu'il code.\n2. Pour chaque allèle muté, écris l'ARNm, le peptide obtenu, puis nomme la mutation.\n3. Quelle mutation n'a aucun effet sur la protéine ? Quelle propriété du code génétique l'explique ?\n4. Une mutation modifie-t-elle toujours le phénotype ? Justifie.","bareme":[{"critere":"ARNm et peptide sauvages justes : Met-Glu-Lys-Pro-Trp","points":4},{"critere":"Trois ARNm et peptides mutés justes","points":6},{"critere":"Mutations nommées : silencieuse, faux-sens, non-sens (protéine tronquée)","points":5},{"critere":"Redondance du code et lien génotype / phénotype expliqués","points":5}],"dureeMin":12,"corrige":"1. L'ARNm a la séquence du brin non transcrit avec U à la place de T :\nARNm sauvage : 5'-AUG GAG AAG CCU UGG UAA-3'\nPeptide : **Met-Glu-Lys-Pro-Trp** (UAA = stop).\n\n2.\n- **Muté 1** : ARNm AUG GAG AAG **CCC** UGG UAA → Met-Glu-Lys-**Pro**-Trp. Le codon CCU devient CCC, qui code toujours Pro : mutation **silencieuse**.\n- **Muté 2** : ARNm AUG **GUG** AAG CCU UGG UAA → Met-**Val**-Lys-Pro-Trp. GAG (Glu) devient GUG (Val) : un acide aminé est remplacé par un autre, mutation **faux-sens** (c'est la mutation de la drépanocytose).\n- **Muté 3** : ARNm AUG GAG **UAG** CCU UGG UAA → Met-Glu, puis **stop**. AAG (Lys) devient UAG, un codon stop prématuré : mutation **non-sens**, la protéine est **tronquée**.\n\n3. La mutation du muté 1 n'a aucun effet sur la protéine. Le code génétique est **redondant** : 64 codons pour 20 acides aminés, plusieurs codons codent le même acide aminé (CCU et CCC codent Pro).\n\n4. Non. Une mutation modifie toujours le **génotype**, mais elle ne modifie le **phénotype** que si elle **change la protéine**, et seulement si ce changement **touche sa fonction**. Une mutation silencieuse ne change pas le phénotype ; un faux-sens peut le changer ou non selon l'acide aminé touché ; un non-sens précoce le change le plus souvent."}$exo$::jsonb),
  ('827909f0-e2f6-57cd-94eb-f5c3af3ca978'::uuid, 3, 'application', $exo${"titre":"Un nucléotide en moins","consigne":"Suis la méthode du cours, écris toutes les séquences et justifie chaque conclusion.","enonce":"On donne le **brin non transcrit** (5' → 3') du début de la séquence codante d'un gène, nucléotides numérotés de 1 à 21 :\n\n**5'-ATG GCT GTA AAG CCT TGG TAA-3'**\n\n*Extrait du code génétique : AUG = Met ; GCU = Ala ; GUA = Val ; AAG = Lys ; AAA = Lys ; CCU = Pro ; UGG = Trp ; AGC = Ser ; UAA, UAG, UGA = stop.*\n\n1. Écris le brin transcrit (de 3' vers 5'), puis l'ARNm, puis le peptide codé par l'allèle sauvage.\n2. **Allèle a1** : le nucléotide n° 7 (un G) est **supprimé**. Écris le nouvel ARNm découpé en codons à partir de l'AUG, puis le peptide obtenu. Nomme la mutation et explique pourquoi un seul nucléotide a un effet aussi important.\n3. **Allèle a2** : le nucléotide n° 12 (un G) est **remplacé par un A**. Quel est l'effet sur le peptide ? Nomme la mutation.\n4. Des expériences historiques ont montré que de l'ARN radioactif fabriqué dans le noyau migre ensuite vers le cytoplasme. Explique ce que ces expériences ont établi.\n5. Lequel des deux allèles mutés risque le plus de modifier le phénotype ? Argumente.","bareme":[{"critere":"Brin transcrit, ARNm et peptide sauvage justes (Met-Ala-Val-Lys-Pro-Trp)","points":5},{"critere":"a1 : ARNm AUG GCU UAA…, peptide Met-Ala, décalage du cadre de lecture expliqué","points":6},{"critere":"a2 : AAG → AAA, toujours Lys, mutation silencieuse","points":3},{"critere":"Rôle de l'ARN messager, lien entre noyau et cytoplasme","points":3},{"critere":"Comparaison argumentée : a1 donne une protéine tronquée, non fonctionnelle","points":3}],"dureeMin":20,"corrige":"1. Brin transcrit (complémentaire, antiparallèle) : **3'-TAC CGA CAT TTC GGA ACC ATT-5'**.\nARNm (séquence du brin non transcrit, U à la place de T) : **5'-AUG GCU GUA AAG CCU UGG UAA-3'**.\nPeptide : **Met-Ala-Val-Lys-Pro-Trp** (UAA = stop).\n\n2. Suppression du nucléotide 7 (le G du codon GTA) :\nnouveau brin non transcrit : ATG GCT **TAA** AGC CTT GGT AA\nARNm : 5'-AUG GCU **UAA** AGC CUU GGU AA-3'\nPeptide : **Met-Ala**, puis stop.\nC'est une **délétion** qui provoque un **décalage du cadre de lecture** : le ribosome lit toujours par groupes de trois à partir de l'AUG, donc **tous les codons suivants changent**. Ici, le décalage fait apparaître immédiatement un codon stop : la protéine est réduite à deux acides aminés, **non fonctionnelle**.\n\n3. Le nucléotide 12 est le dernier du codon AAG (nucléotides 10 à 12). AAG devient **AAA**, qui code toujours la **lysine** : le peptide est inchangé (Met-Ala-Val-Lys-Pro-Trp). Mutation **silencieuse**, grâce à la redondance du code.\n\n4. L'ARN fabriqué dans le noyau passe dans le **cytoplasme**, là où se fabriquent les protéines. Ces expériences ont établi qu'un intermédiaire, l'**ARN messager**, fait le lien entre l'ADN (dans le noyau) et la synthèse des protéines (dans le cytoplasme).\n\n5. **a1**. La délétion modifie le génotype **et** la protéine, qui est tronquée et perd sa fonction : le phénotype a toutes les chances d'être modifié. La mutation a2 modifie le génotype mais pas la protéine : elle ne change pas le phénotype."}$exo$::jsonb),
  ('9f25b26b-4689-50bb-b4c2-362fe95c80a9'::uuid, 1, 'application', $exo${"titre":"Le cycle cellulaire","consigne":"Réponds à chaque question avec le vocabulaire du cours.","enonce":"1. Cite les quatre phases du cycle cellulaire. Lesquelles forment l'interphase ?\n2. Pendant quelle phase l'ADN est-il répliqué ? Combien de chromatides compte un chromosome avant et après cette phase ?\n3. Pourquoi dit-on que la réplication est **semi-conservative** ?\n4. Remets dans l'ordre les étapes de la mitose et décris chacune en une phrase : anaphase, prophase, télophase, métaphase.\n5. On note q la quantité d'ADN d'une cellule en G1. Quelle quantité contient-elle en G2 ? et chacune des deux cellules filles à la fin de la mitose ?","bareme":[{"critere":"G1, S, G2, M ; interphase = G1 + S + G2","points":3},{"critere":"Réplication en phase S, passage de 1 à 2 chromatides","points":3},{"critere":"Semi-conservative : un brin ancien et un brin neuf dans chaque molécule fille","points":4},{"critere":"Ordre et description des quatre étapes de la mitose","points":6},{"critere":"Quantités d'ADN : 2q en G2, q par cellule fille","points":4}],"dureeMin":8,"corrige":"1. **G1**, **S**, **G2** et **M** (mitose). G1, S et G2 forment l'**interphase**.\n\n2. L'ADN est répliqué pendant la **phase S**. Avant, chaque chromosome compte **une chromatide** ; après, **deux chromatides**.\n\n3. Face à chacun des deux brins de l'ADN, un brin complémentaire neuf est fabriqué. Chaque molécule fille contient donc **un brin ancien et un brin neuf** : la moitié de la molécule mère est conservée dans chaque molécule fille.\n\n4.\n- **Prophase** : les chromosomes se condensent, l'enveloppe nucléaire se fragmente, le fuseau mitotique (microtubules) se forme.\n- **Métaphase** : les chromosomes s'alignent au centre de la cellule (plaque équatoriale).\n- **Anaphase** : les deux chromatides de chaque chromosome se séparent et migrent vers les pôles opposés.\n- **Télophase** : deux noyaux se reforment, la cellule se divise en deux.\n\n5. En G2 : **2q** (l'ADN a été répliqué). À la fin de la mitose, chaque cellule fille contient **q**."}$exo$::jsonb),
  ('9f25b26b-4689-50bb-b4c2-362fe95c80a9'::uuid, 2, 'application', $exo${"titre":"Suivre l'ADN d'une cellule humaine","consigne":"Pose les calculs et justifie chaque réponse.","enonce":"Une cellule humaine en G1 contient **q = 6,6 pg** d'ADN (1 pg = 10⁻¹² g) et **46 chromosomes**.\n\n1. Complète le tableau (quantité d'ADN par cellule).\n\n| Moment | Mitose | Méiose |\n| G1 | 6,6 pg | 6,6 pg |\n| Après la phase S | ? | ? |\n| Après la 1re division | ? | ? |\n| Après la 2e division | — | ? |\n\n2. Décris l'allure de la courbe de la quantité d'ADN au cours d'un cycle avec mitose. Comment se distingue la courbe d'une méiose ?\n3. Lors d'une réplication, une cellule humaine copie environ **6 milliards** de paires de nucléotides. La réplication fait environ **une erreur pour un milliard** de nucléotides après correction. Combien d'erreurs non corrigées attend-on par réplication ? Comment appelle-t-on ces erreurs ?\n4. Identifie chaque situation :\n   a. 46 chromosomes à deux chromatides, alignés au centre de la cellule ;\n   b. 23 chromosomes à deux chromatides, alignés au centre ;\n   c. des chromosomes homologues appariés.","bareme":[{"critere":"Tableau juste : 13,2 pg ; 6,6 pg ; 6,6 pg ; 3,3 pg","points":6},{"critere":"Courbe décrite : montée progressive en S, chute brutale ; deux marches en méiose","points":4},{"critere":"Environ 6 erreurs par réplication, appelées mutations","points":4},{"critere":"Trois situations identifiées : métaphase de mitose, métaphase II, méiose I","points":6}],"dureeMin":12,"corrige":"1.\n| Moment | Mitose | Méiose |\n| G1 | 6,6 pg | 6,6 pg |\n| Après la phase S | **13,2 pg** (2q) | **13,2 pg** (2q) |\n| Après la 1re division | **6,6 pg** (q, deux cellules identiques) | **6,6 pg** (q) |\n| Après la 2e division | — | **3,3 pg** (q/2, gamètes) |\n\n2. En mitose, la quantité d'ADN **monte progressivement** de q à 2q pendant la phase S (la réplication prend quelques heures), reste à 2q en G2, puis **redescend brutalement** à q à la fin de la division. En méiose, après la même montée, elle redescend en **deux marches** : 2q → q → q/2.\n\n3. Nombre d'erreurs ≈ 6 × 10⁹ / 10⁹ = **6 erreurs** par réplication. Ces rares erreurs non corrigées sont des **mutations**. La réplication reste très **fidèle**, ce qui garantit la transmission de l'information.\n\n4.\na. **Métaphase de mitose** (46 chromosomes doubles alignés).\nb. **Métaphase II de méiose** (23 chromosomes doubles alignés : le nombre a déjà été divisé par deux).\nc. **Méiose I** (seule division où les homologues s'apparient)."}$exo$::jsonb),
  ('9f25b26b-4689-50bb-b4c2-362fe95c80a9'::uuid, 3, 'application', $exo${"titre":"Chromosomes, chromatides et fuseau","consigne":"Justifie chaque réponse ; pose les dénombrements.","enonce":"On étudie des cellules de drosophile, dont les cellules somatiques contiennent **8 chromosomes**. On note q la quantité d'ADN d'une cellule en G1.\n\n1. Complète le tableau pour une cellule qui se divise par **mitose**.\n\n| Moment | Nombre de chromosomes dans la cellule | Chromatides par chromosome | Quantité d'ADN |\n| G1 | ? | ? | q |\n| G2 | ? | ? | ? |\n| Métaphase | ? | ? | ? |\n| Fin d'anaphase (cellule entière, avant la séparation) | ? | ? | ? |\n| Chaque cellule fille | ? | ? | ? |\n\n2. Explique comment la réplication puis la mitose garantissent que les deux cellules filles portent **la même information génétique** que la cellule mère.\n3. Une substance détruit les **microtubules**. Quelle structure ne peut plus se former ? À quelle étape la mitose sera-t-elle bloquée ? Justifie.\n4. Explique la phrase : « En mitose se séparent les chromatides sœurs ; en méiose I se séparent les chromosomes homologues. » Pourquoi parle-t-on de division équationnelle d'un côté et réductionnelle de l'autre ?","bareme":[{"critere":"Tableau juste (8/1/q ; 8/2/2q ; 8/2/2q ; 16/1/2q ; 8/1/q)","points":6},{"critere":"Réplication fidèle et semi-conservative puis répartition des chromatides sœurs identiques","points":5},{"critere":"Fuseau mitotique non formé, blocage avant la séparation des chromatides, justifié","points":4},{"critere":"Distinction chromatides sœurs / homologues, équationnelle / réductionnelle","points":5}],"dureeMin":20,"corrige":"1.\n| Moment | Chromosomes | Chromatides par chromosome | ADN |\n| G1 | 8 | 1 | q |\n| G2 | 8 | 2 | 2q |\n| Métaphase | 8 | 2 | 2q |\n| Fin d'anaphase (cellule entière) | 16 (8 à chaque pôle) | 1 | 2q |\n| Chaque cellule fille | 8 | 1 | q |\nÀ l'anaphase, les deux chromatides de chaque chromosome se séparent : chacune devient un chromosome à une chromatide ; il y en a 16 dans la cellule, 8 migrant vers chaque pôle.\n\n2. En phase S, l'ADN est **répliqué** de façon semi-conservative et très fidèle : les deux **chromatides sœurs** d'un chromosome portent la **même** séquence. En anaphase, les chromatides sœurs se séparent et chaque cellule fille en reçoit **une** de chaque chromosome : elle reçoit donc les 8 chromosomes, avec la même information que la cellule mère.\n\n3. Le **fuseau mitotique**, fait de **microtubules**, ne peut plus se former. C'est lui qui assure l'alignement des chromosomes et la migration des chromatides vers les pôles : la mitose sera bloquée **avant l'anaphase** — les chromosomes condensés ne peuvent ni s'aligner en métaphase ni se séparer.\n\n4. En **mitose**, ce sont les deux **chromatides sœurs**, copies identiques, qui se séparent : chaque cellule fille garde le même nombre de chromosomes que la cellule mère (division **équationnelle**). En **méiose I**, ce sont les **chromosomes homologues** (un d'origine paternelle, un d'origine maternelle) qui se séparent : chaque cellule reçoit un seul chromosome de chaque paire, le nombre de chromosomes est divisé par deux (division **réductionnelle**, n chromosomes doubles)."}$exo$::jsonb),
  ('a59eada7-900e-5ce1-9e48-610535959f4e'::uuid, 1, 'application', $exo${"titre":"Ce que contient ton assiette","consigne":"Réponds à chaque question en quelques phrases précises, avec le vocabulaire du cours.","enonce":"1. Cite les **six familles de constituants alimentaires**. Pour chacune, donne un exemple et son rôle principal dans l'organisme.\n2. Explique la différence entre un **macronutriment** et un **micronutriment**. Classe les constituants suivants dans l'une ou l'autre catégorie : amidon, vitamine C, triglycérides, protéines, vitamine B12.\n3. Qu'est-ce qu'un **nutriment essentiel** ? Donne deux exemples précis cités dans le cours.","bareme":[{"critere":"Les six familles (glucides, lipides, protides, eau et sels minéraux, vitamines, fibres) avec un exemple et un rôle justes","points":8},{"critere":"Macronutriment et micronutriment définis par les quantités ingérées, classement des cinq constituants juste","points":6},{"critere":"Nutriment essentiel défini (non synthétisé, apporté par l'alimentation) et deux exemples justes","points":6}],"dureeMin":7,"corrige":"1. **Glucides** (amidon, saccharose, lactose) : énergie rapide. **Lipides** (triglycérides, cholestérol) : énergie de réserve, constituants des membranes. **Protides** (protéines de la viande, des légumineuses) : construction des cellules, enzymes. **Eau et sels minéraux** (Na⁺, Ca²⁺, Fe²⁺) : milieu intérieur, os, transport du dioxygène (fer). **Vitamines** (A, C, D, B12) : cofacteurs, actives à très faible dose. **Fibres** (cellulose) : non digestibles, elles facilitent le transit.\n2. Les **macronutriments** sont consommés en grande quantité (des dizaines de grammes par jour) ; les **micronutriments** en très petite quantité (milligrammes, voire microgrammes). Macronutriments : amidon, triglycérides, protéines. Micronutriments : vitamine C, vitamine B12.\n3. Un **nutriment essentiel** est un nutriment que l'organisme **ne sait pas synthétiser** : il doit obligatoirement être apporté par l'alimentation (besoin qualitatif). Exemples : les **acides aminés essentiels** (lysine, tryptophane, valine…) et les **acides gras essentiels** (acide linoléique, oméga-6, et acide alpha-linolénique, oméga-3)."}$exo$::jsonb),
  ('a59eada7-900e-5ce1-9e48-610535959f4e'::uuid, 2, 'application', $exo${"titre":"Le goûter de Maël","consigne":"Lis l'étiquette, puis réponds aux questions en posant chaque calcul.","enonce":"**Situation.** Maël, 16 ans, mange chaque après-midi 40 g de biscuits. Le paquet indique :\n\n| Pour 100 g | Valeur |\n| Glucides | 68 g |\n| Lipides | 18 g |\n| Protéines | 7 g |\n| Fibres | 3 g |\n\nSur l'emballage est écrit en gros : « Source de fibres ».\n\n**Données** : 1 g de glucide ou de protide apporte environ 4 kcal, 1 g de lipide environ 9 kcal. On néglige l'énergie apportée par les fibres.\n\n1. Calcule l'énergie apportée par **100 g** de biscuits.\n2. Calcule l'énergie apportée par la **portion de 40 g** que mange Maël.\n3. Quelle part (en %) de l'énergie des biscuits vient des **lipides** ? Explique pourquoi elle est si importante alors que les biscuits contiennent beaucoup moins de lipides que de glucides.\n4. La mention « Source de fibres » est-elle une **recommandation** ou une **allégation** ? Justifie.","bareme":[{"critere":"Énergie pour 100 g : 68 × 4 + 7 × 4 + 18 × 9 = 462 kcal, calcul posé","points":6},{"critere":"Énergie de la portion : 0,4 × 462 ≈ 185 kcal","points":4},{"critere":"Part des lipides ≈ 35 % (162/462) et explication par les 9 kcal par gramme","points":5},{"critere":"Allégation identifiée et justifiée (affirmation commerciale sur l'emballage, encadrée par la réglementation, pas une consigne des autorités de santé)","points":5}],"dureeMin":11,"corrige":"1. Glucides : 68 × 4 = 272 kcal. Protéines : 7 × 4 = 28 kcal. Lipides : 18 × 9 = 162 kcal. Total pour 100 g : 272 + 28 + 162 = **462 kcal**.\n2. La portion fait 40 g, soit 0,4 fois 100 g : 0,4 × 462 = 184,8 ≈ **185 kcal**.\n3. Part des lipides : 162 / 462 ≈ 0,35, soit environ **35 %** de l'énergie. Les lipides ne représentent que 18 g contre 68 g de glucides, mais **1 g de lipide apporte environ 9 kcal**, plus du double d'un gramme de glucide (4 kcal) : leur poids énergétique est donc bien supérieur à leur poids en grammes.\n4. C'est une **allégation** : une affirmation portée sur l'emballage par le fabricant, encadrée par la réglementation européenne, mais qui reste un **argument commercial**. Une **recommandation** vient des autorités de santé (par exemple les repères du Programme national nutrition santé) et ne figure pas comme argument de vente sur un produit."}$exo$::jsonb),
  ('a59eada7-900e-5ce1-9e48-610535959f4e'::uuid, 3, 'application', $exo${"titre":"Deux journées d'Inès","consigne":"Exploite les deux documents, pose tes calculs et rédige des réponses argumentées.","enonce":"**Situation.** Inès, 15 ans, peu sportive, a besoin d'environ 2 200 kcal par jour. On compare deux de ses journées.\n\n**Document 1 – Deux rations journalières**\n\n| | Journée A | Journée B |\n| Glucides | 380 g | 300 g |\n| Lipides | 70 g | 80 g |\n| Protides | 60 g | 90 g |\n| Aliments principaux | pâtes, pain blanc, beurre, charcuterie, soda, bonbons | pain complet, lentilles, poisson gras, œufs, huile de colza, légumes crus, fruits |\n\n**Document 2 – Où trouver quelques nutriments**\n\n| Nutriment | Aliments qui en apportent |\n| Vitamine C | fruits, légumes crus |\n| Fer | viande rouge, lentilles |\n| Acide alpha-linolénique (oméga-3) | huile de colza, noix, poissons gras |\n\n**Données** : glucide et protide ≈ 4 kcal/g, lipide ≈ 9 kcal/g.\n\n1. Calcule l'apport énergétique de chaque journée.\n2. Les deux journées couvrent-elles les **besoins quantitatifs** d'Inès ? Justifie.\n3. À l'aide du document 2, montre que la journée A ne couvre pas les **besoins qualitatifs** d'Inès. Précise quelles conséquences pourrait avoir, à long terme, une alimentation toujours bâtie sur ce modèle.\n4. Rédige une conclusion : pourquoi dit-on qu'une ration peut apporter « assez » sans apporter « ce qu'il faut » ? Cite un autre déséquilibre que favorise la journée A.","bareme":[{"critere":"Énergie juste : A = 1 520 + 630 + 240 = 2 390 kcal ; B = 1 200 + 720 + 360 = 2 280 kcal","points":5},{"critere":"Les deux journées couvrent le besoin de 2 200 kcal : besoins quantitatifs couverts","points":3},{"critere":"Manques de la journée A tirés du document 2 (vitamine C, oméga-3 essentiel), leurs conséquences (scorbut, nutriment essentiel), fer faible et anémie","points":8},{"critere":"Conclusion distinguant besoins quantitatifs et qualitatifs, et excès de sucres rapides et de lipides relié à l'obésité et au diabète de type 2","points":4}],"dureeMin":16,"corrige":"1. **Journée A** : glucides 380 × 4 = 1 520 kcal ; lipides 70 × 9 = 630 kcal ; protides 60 × 4 = 240 kcal ; total **2 390 kcal**. **Journée B** : 300 × 4 = 1 200 kcal ; 80 × 9 = 720 kcal ; 90 × 4 = 360 kcal ; total **2 280 kcal**.\n2. Les deux journées apportent un peu plus que les 2 200 kcal nécessaires : les **besoins quantitatifs** (l'énergie à couvrir chaque jour) sont couverts dans les deux cas.\n3. La journée A ne contient **ni fruits ni légumes crus** : elle n'apporte pas de **vitamine C**. Elle ne contient ni huile de colza, ni noix, ni poisson gras : elle n'apporte pas d'**acide alpha-linolénique**, un **acide gras essentiel** que l'organisme ne sait pas fabriquer. Elle ne contient ni viande rouge ni lentilles : l'apport en **fer** est faible. À long terme, une carence en vitamine C provoque le **scorbut**, une ration pauvre en fer provoque une **anémie**, et le manque d'un acide gras essentiel ne peut pas être compensé par l'organisme. La journée B, variée, apporte tous ces nutriments.\n4. Une ration peut couvrir les **besoins quantitatifs** (assez d'énergie) sans couvrir les **besoins qualitatifs** (certaines molécules indispensables que l'organisme ne sait pas synthétiser). Seule une alimentation **variée** couvre les deux. La journée A, riche en **sucres rapides** (soda, bonbons) et en lipides (beurre, charcuterie), favorise aussi l'**obésité** et le **diabète de type 2**."}$exo$::jsonb),
  ('4cf1f66d-ee98-52a7-97a4-1cce0eaeeab4'::uuid, 1, 'application', $exo${"titre":"Trois façons de digérer","consigne":"Réponds à chaque question en quelques phrases, avec le vocabulaire du cours.","enonce":"1. Qu'est-ce qu'une **hydrolyse** ? Pourquoi dit-on que la digestion est une **simplification moléculaire** ?\n2. Présente les **trois mécanismes** de la digestion (mécanique, chimique, enzymatique) en donnant pour chacun un exemple précis.\n3. Les sels biliaires sont-ils des enzymes ? Explique leur rôle dans la digestion des lipides.\n4. On dit que la lumière du tube digestif appartient au **milieu extérieur**. Explique cette phrase.","bareme":[{"critere":"Hydrolyse définie (coupure d'une liaison grâce à une molécule d'eau) et simplification moléculaire expliquée (grosses molécules → nutriments absorbables)","points":6},{"critere":"Les trois mécanismes décrits avec un exemple juste chacun","points":6},{"critere":"Sels biliaires : pas des enzymes, émulsion des lipides qui augmente la surface d'action de la lipase","points":5},{"critere":"Lumière = milieu extérieur : ce qui y circule n'est pas encore entré dans l'organisme","points":3}],"dureeMin":8,"corrige":"1. Une **hydrolyse** est une réaction qui **coupe une liaison grâce à une molécule d'eau**. La digestion transforme de **grosses molécules** (amidon, protéines, triglycérides), incapables de traverser la paroi intestinale, en **petites molécules absorbables**, les nutriments : c'est une simplification moléculaire.\n2. **Mécanique** : fragmentation et brassage des aliments, par la **mastication** et le **péristaltisme** (contractions des muscles lisses de la paroi). **Chimique** : action d'un agent non enzymatique, comme l'**acidité gastrique** (HCl) ou l'émulsion des lipides par la **bile**. **Enzymatique** : hydrolyse catalysée par une enzyme, comme l'**amylase** (amidon → maltose), la **pepsine** ou la **lipase**.\n3. **Non** : les sels biliaires ne sont pas des enzymes, ils ne coupent aucune liaison. Ils **émulsionnent** les lipides en fines gouttelettes, ce qui **multiplie la surface** sur laquelle la lipase pancréatique peut agir.\n4. Le tube digestif est un tuyau ouvert aux deux bouts (bouche, anus). Ce qui circule dans sa **lumière** n'a encore traversé aucune paroi : il n'est **pas encore dans l'organisme**. Il n'y entrera qu'après l'absorption."}$exo$::jsonb),
  ('4cf1f66d-ee98-52a7-97a4-1cce0eaeeab4'::uuid, 2, 'application', $exo${"titre":"Les quatre tubes de Jade","consigne":"Analyse les résultats de l'expérience, puis réponds en justifiant chaque interprétation.","enonce":"**Situation.** En TP, Jade prépare quatre tubes contenant chacun 5 mL d'empois d'amidon.\n\n| Tube | Ajout | Température |\n| T1 | 1 mL de salive | 37 °C |\n| T2 | 1 mL d'eau | 37 °C |\n| T3 | 1 mL de salive portée à ébullition puis refroidie | 37 °C |\n| T4 | 1 mL de salive | 0 °C |\n\nAprès 15 minutes, elle teste une goutte de chaque tube à l'eau iodée : T1 reste jaune-orangé, T2, T3 et T4 donnent une coloration **bleu-noir**. Chauffé avec la liqueur de Fehling, T1 donne un **précipité rouge brique**.\n\n1. Quel est le rôle du tube T2 ?\n2. Interprète les résultats du tube T1. Nomme l'enzyme en cause et le produit formé.\n3. Interprète les résultats des tubes T3 et T4.\n4. D'après le cours, dans quel organe l'amidon non digéré dans la bouche peut-il encore être hydrolysé, par quelle enzyme et à quel pH optimal ?","bareme":[{"critere":"T2 identifié comme tube témoin (sans enzyme, l'amidon reste)","points":4},{"critere":"T1 : amidon disparu (plus de bleu-noir) et sucre réducteur formé (Fehling), amylase salivaire, maltose","points":6},{"critere":"T3 : enzyme dénaturée par l'ébullition ; T4 : enzyme inactive à 0 °C ; température optimale 37 °C","points":6},{"critere":"Intestin grêle, amylase pancréatique, pH ≈ 8","points":4}],"dureeMin":11,"corrige":"1. **T2** est le **tube témoin** : il contient de l'amidon sans salive. Il montre que, sans enzyme, l'amidon reste présent (bleu-noir) : ce n'est donc ni l'eau ni la température qui font disparaître l'amidon.\n2. Dans **T1**, l'eau iodée ne donne plus de bleu-noir : l'**amidon a disparu**. La liqueur de Fehling donne un précipité rouge brique : un **sucre réducteur** est apparu. La salive contient l'**amylase salivaire**, qui a hydrolysé l'amidon en **maltose**.\n3. Dans **T3**, la salive a été bouillie : l'amylase a été **dénaturée** et n'agit plus, l'amidon reste. Dans **T4**, à 0 °C, l'enzyme est **inactive** : l'amidon reste aussi. Une enzyme n'agit bien qu'à sa **température optimale**, 37 °C chez l'être humain.\n4. Dans l'**intestin grêle**, l'**amylase pancréatique** (du suc pancréatique) hydrolyse l'amidon en maltose, à un **pH optimal voisin de 8**."}$exo$::jsonb),
  ('4cf1f66d-ee98-52a7-97a4-1cce0eaeeab4'::uuid, 3, 'application', $exo${"titre":"Le voyage d'un sandwich","consigne":"Suis le devenir de chaque aliment en t'appuyant sur le document et sur le cours. Rédige des réponses structurées.","enonce":"**Situation.** Karim mange un sandwich : pain complet (amidon et fibres), jambon (protéines), beurre (triglycérides).\n\n**Document – pH le long du tube digestif**\n\n| Lieu | pH |\n| Bouche | ≈ 7 |\n| Estomac | ≈ 2 |\n| Intestin grêle | ≈ 8 |\n\n1. Pour l'**amidon**, les **protéines** et les **triglycérides**, indique où a lieu la digestion enzymatique, les enzymes en cause et les produits obtenus.\n2. En t'appuyant sur le document, explique pourquoi la **pepsine** agit dans l'estomac, et pourquoi l'**amylase salivaire** ne peut pas y poursuivre efficacement son action.\n3. Montre que la digestion des triglycérides du beurre associe un mécanisme **chimique** et un mécanisme **enzymatique**. Précise le rôle de chaque glande annexe concernée.\n4. Les fibres du pain complet ne sont pas digérées par nos enzymes. Que deviennent-elles dans le gros intestin, et quel intérêt en tirons-nous ?","bareme":[{"critere":"Amidon (bouche puis grêle, amylases), protéines (estomac puis grêle, pepsine, trypsine), triglycérides (grêle, lipase) et leurs produits","points":6},{"critere":"Pepsine au pH optimal ≈ 2 dans l'estomac, amylase salivaire (pH optimal ≈ 7) loin de son optimum à pH 2","points":5},{"critere":"Émulsion par la bile (foie, glande annexe, agent non enzymatique) puis hydrolyse par la lipase du pancréas exocrine","points":5},{"critere":"Fibres fermentées par le microbiote en symbiose, production de vitamines K et B12, protection contre les pathogènes","points":4}],"dureeMin":16,"corrige":"1. **Amidon** : dans la bouche, l'**amylase salivaire** commence son hydrolyse ; dans l'intestin grêle, l'**amylase pancréatique** la poursuit. Produit : le **maltose**. **Protéines** : dans l'estomac, la **pepsine** les coupe en **peptides** ; dans l'intestin grêle, la **trypsine** coupe les peptides en **petits peptides**. **Triglycérides** : dans l'intestin grêle, la **lipase pancréatique** les hydrolyse en **acides gras et monoglycérides**.\n2. Chaque enzyme a un **pH optimal**. La pepsine a un pH optimal voisin de **2** : l'estomac (pH ≈ 2) lui offre les conditions où elle agit le mieux. L'amylase salivaire a un pH optimal voisin de **7** : dans l'estomac, à pH 2, elle est très loin de son optimum et ne peut plus hydrolyser efficacement l'amidon. Son action reprend avec l'amylase pancréatique dans l'intestin, à pH ≈ 8.\n3. Mécanisme **chimique** : la **bile**, produite par le **foie** (stockée dans la vésicule biliaire) et déversée dans l'intestin, contient des **sels biliaires** qui **émulsionnent** les lipides en fines gouttelettes, sans couper de liaison. Mécanisme **enzymatique** : le **pancréas exocrine** déverse le suc pancréatique contenant la **lipase**, qui **hydrolyse** les triglycérides. L'émulsion multiplie la surface d'action de la lipase : les deux mécanismes se complètent. Foie et pancréas sont des glandes **exocrines** : ils déversent leurs sécrétions dans la lumière du tube.\n4. Les fibres arrivent intactes dans le gros intestin, où le **microbiote** (des milliards de bactéries vivant en **symbiose** avec nous) les **fermente**. Ce microbiote produit des **vitamines** (K, B12) et **protège contre les pathogènes**. Les fibres facilitent aussi le transit."}$exo$::jsonb),
  ('02f2dc13-0617-5697-80ed-7a67fee5d5fb'::uuid, 1, 'application', $exo${"titre":"Du chyle au foie","consigne":"Réponds à chaque question en quelques phrases, avec le vocabulaire du cours.","enonce":"1. Où a lieu l'essentiel de l'**absorption** des nutriments ? Cite les trois niveaux auxquels la paroi multiplie sa surface, et la surface totale obtenue.\n2. Pourquoi dit-on que l'**entérocyte** est une cellule **polarisée** ? Quel est le rôle des **jonctions serrées** ?\n3. Présente les **deux voies** empruntées par les nutriments absorbés : quels nutriments empruntent chacune, et où vont-ils d'abord ?","bareme":[{"critere":"Intestin grêle ; replis circulaires, villosités, microvillosités ; environ 200 m²","points":7},{"critere":"Membranes apicale et basale portant des transporteurs différents ; jonctions serrées obligeant à traverser les cellules","points":6},{"critere":"Hydrosolubles → sang → veine porte hépatique → foie ; lipides → chylomicrons → lymphe, rejoignant le sang sans passer d'abord par le foie","points":7}],"dureeMin":7,"corrige":"1. L'absorption a lieu surtout dans l'**intestin grêle**. Sa surface est multipliée à trois niveaux : les **replis circulaires** (échelle de l'organe, × 3), les **villosités** (échelle du tissu, × 10) et les **microvillosités** des entérocytes (échelle de la cellule, × 20). On obtient environ **200 m²**, la surface d'un court de tennis.\n2. L'entérocyte est **polarisé** : sa **membrane apicale**, côté lumière (bordure en brosse), et sa **membrane basale**, côté milieu intérieur, ne portent **pas les mêmes transporteurs**. Les **jonctions serrées** soudent les cellules entre elles : les molécules ne peuvent pas passer entre les cellules et doivent **traverser** les entérocytes.\n3. Les nutriments **hydrosolubles** (glucose, acides aminés, vitamines B et C) passent dans le **sang** des capillaires, puis la **veine porte hépatique** les conduit au **foie** (système porte). Les **lipides**, réassemblés en triglycérides et emballés en **chylomicrons**, passent dans la **lymphe** (le chyle) par les chylifères ; elle rejoint le sang près du cœur **sans passer d'abord par le foie**."}$exo$::jsonb),
  ('02f2dc13-0617-5697-80ed-7a67fee5d5fb'::uuid, 2, 'application', $exo${"titre":"Un court de tennis dans le ventre","consigne":"Pose chaque calcul, puis explique le résultat avec le vocabulaire du cours.","enonce":"**Situation.** Lucie veut vérifier le chiffre de 200 m² annoncé par son manuel. Elle modélise l'intestin grêle par un **tube lisse** de 4 m de long et de 2,5 cm de diamètre.\n\n**Donnée** : la surface intérieure d'un cylindre vaut π × diamètre × longueur (prendre π ≈ 3,14).\n\n1. Calcule la surface intérieure du tube lisse, en m².\n2. Les replis multiplient la surface par 3, les villosités par 10, les microvillosités par 20. Calcule le **facteur d'amplification total**.\n3. Calcule la surface réelle d'échange. Le résultat est-il cohérent avec le manuel ?\n4. Donne **deux caractéristiques** de la villosité, autres que sa surface, qui facilitent le passage des nutriments vers le milieu intérieur.","bareme":[{"critere":"Surface lisse : 3,14 × 0,025 × 4 ≈ 0,314 m², unités converties","points":5},{"critere":"Facteur total : 3 × 10 × 20 = 600 (produit, pas somme)","points":4},{"critere":"Surface réelle ≈ 188 m², cohérente avec environ 200 m²","points":5},{"critere":"Capillaire sanguin et chylifère dans chaque villosité, à moins d'un dixième de millimètre de la lumière","points":6}],"dureeMin":10,"corrige":"1. Diamètre : 2,5 cm = 0,025 m. Surface = 3,14 × 0,025 × 4 = **0,314 m²** : à peine un tiers de mètre carré.\n2. Les facteurs se **multiplient** : 3 × 10 × 20 = **600**.\n3. Surface réelle : 0,314 × 600 ≈ **188 m²**. C'est bien de l'ordre de **200 m²**, la surface d'un court de tennis : le chiffre du manuel est cohérent.\n4. Chaque villosité contient un **capillaire sanguin** (qui reçoit les nutriments hydrosolubles) et un **chylifère**, vaisseau lymphatique (qui reçoit les lipides). Ces vaisseaux sont à **moins d'un dixième de millimètre** de la lumière : la distance à traverser est très courte. Une grande surface, une paroi fine et des vaisseaux tout proches font de l'intestin grêle une surface d'échange très efficace."}$exo$::jsonb),
  ('02f2dc13-0617-5697-80ed-7a67fee5d5fb'::uuid, 3, 'application', $exo${"titre":"Le glucose à travers l'entérocyte","consigne":"Exploite le document en comparant les concentrations de part et d'autre de chaque membrane. Justifie chaque mode de transport.","enonce":"**Document – Concentrations mesurées pendant l'absorption (mmol·L⁻¹)**\n\n| | Lumière intestinale | Entérocyte | Sang |\n| Glucose | 5 | 20 | 5 |\n| Na⁺ | 140 | 15 | 140 |\n\n1. Le glucose entre dans l'entérocyte par la **membrane apicale**. Se déplace-t-il dans le sens de son gradient ou contre lui ? Quel mode de transport cela impose-t-il ? Explique comment le sodium intervient.\n2. Le glucose sort de l'entérocyte par la **membrane basale**. Nomme ce mode de transport et justifie.\n3. Quel est le rôle de la **pompe Na⁺/K⁺** ? Prévois ce qui arriverait à l'absorption du glucose si un poison bloquait la production d'ATP de la cellule.\n4. Une fois dans le sang, par quel vaisseau le glucose est-il conduit, et vers quel organe ? Explique ce que devient le glucose en excès dans cet organe, et pourquoi le glycogène du muscle ne joue pas le même rôle.","bareme":[{"critere":"Entrée apicale contre le gradient (5 → 20) : transport actif, co-transport avec Na⁺ qui entre selon son gradient (140 → 15)","points":5},{"critere":"Sortie basale selon le gradient (20 → 5) : transport passif facilité par un transporteur, sans énergie","points":4},{"critere":"Pompe Na⁺/K⁺ consommant de l'ATP entretient le gradient de Na⁺ ; sans ATP le gradient disparaît et l'entrée du glucose s'arrête","points":5},{"critere":"Veine porte hépatique vers le foie ; glycogénogenèse ; glycogénolyse possible dans le foie, glycogène musculaire gardé pour le muscle","points":6}],"dureeMin":17,"corrige":"1. Le glucose passe de la lumière (5 mmol·L⁻¹) à l'entérocyte (20 mmol·L⁻¹) : il va **contre son gradient** de concentration. Cela impose un **transport actif**. C'est un **co-transport Na⁺/glucose** : le sodium entre selon **son** gradient (140 mmol·L⁻¹ dans la lumière, 15 dans la cellule) et « porte » le glucose avec lui. L'énergie vient du **gradient électrochimique du sodium**.\n2. À la membrane basale, le glucose passe de l'entérocyte (20) au sang (5) : il va **dans le sens de son gradient**. C'est un **transport passif facilité** : il emprunte un transporteur mais ne consomme pas d'énergie.\n3. La **pompe Na⁺/K⁺** consomme de l'**ATP** pour rejeter le sodium hors de la cellule : elle **entretient le gradient de Na⁺** (peu de Na⁺ dans l'entérocyte). Si un poison bloquait la production d'ATP, la pompe s'arrêterait, le sodium s'accumulerait dans la cellule, le gradient disparaîtrait et le **co-transport ne pourrait plus faire entrer le glucose** contre son gradient : l'absorption du glucose chuterait.\n4. Le glucose, hydrosoluble, rejoint le **sang** puis la **veine porte hépatique**, qui le conduit au **foie** (système porte : capillaires de l'intestin puis capillaires du foie). Dans l'hépatocyte, le glucose en excès est stocké sous forme de **glycogène** : c'est la **glycogénogenèse** (le foie en stocke environ 100 g). Plus tard, la **glycogénolyse** libère du glucose dans le sang. Le muscle stocke aussi du glycogène, mais il le **garde pour lui** : il ne libère pas de glucose dans le sang."}$exo$::jsonb),
  ('ab9e8e28-7b9b-58cd-b635-6af53da956d8'::uuid, 1, 'application', $exo${"titre":"Un taux tenu à un gramme près","consigne":"Réponds à chaque question en quelques phrases précises, avec le vocabulaire du cours.","enonce":"1. Définis la **glycémie** et donne sa valeur chez une personne à jeun. Pourquoi son maintien est-il un exemple d'**homéostasie** ?\n2. Complète la boucle de régulation de la glycémie : grandeur régulée, valeur de consigne, capteurs, messagers, effecteurs.\n3. Compare l'**insuline** et le **glucagon** : cellules productrices, situation qui déclenche leur sécrétion, effets sur la glycémie.","bareme":[{"critere":"Glycémie = concentration de glucose dans le plasma, ≈ 1 g·L⁻¹ à jeun (0,7 à 1,1), maintenue malgré les repas et la consommation continue","points":6},{"critere":"Les cinq éléments de la boucle justes (glycémie, 1 g·L⁻¹, îlots de Langerhans, insuline et glucagon, foie-muscles-tissu adipeux)","points":6},{"critere":"Insuline (cellules β, hyperglycémie, glycémie baisse) et glucagon (cellules α, hypoglycémie, glycogénolyse, glycémie monte)","points":8}],"dureeMin":7,"corrige":"1. La **glycémie** est la **concentration de glucose dans le plasma**. À jeun, elle reste proche de **1 g·L⁻¹** (entre 0,7 et 1,1 g·L⁻¹ environ). Nous mangeons par à-coups alors que nos cellules consomment du glucose en continu : maintenir ce taux stable malgré ces perturbations est un exemple d'**homéostasie**.\n2. **Grandeur régulée** : la glycémie. **Valeur de consigne** : environ 1 g·L⁻¹. **Capteurs** : les cellules des **îlots de Langerhans** du pancréas. **Messagers** : les **hormones insuline et glucagon**, transportées par le sang. **Effecteurs** : le **foie**, les **muscles** et le **tissu adipeux**.\n3. **Insuline** : sécrétée par les **cellules β** des îlots en cas d'**hyperglycémie** ; elle fait entrer le glucose dans les cellules et stimule la glycogénogenèse et la lipogenèse : la glycémie **baisse**. C'est la seule hormone hypoglycémiante. **Glucagon** : sécrété par les **cellules α** en cas d'**hypoglycémie** ; il stimule la **glycogénolyse** dans le foie : la glycémie **monte**. Les deux hormones sont **antagonistes**."}$exo$::jsonb),
  ('ab9e8e28-7b9b-58cd-b635-6af53da956d8'::uuid, 2, 'application', $exo${"titre":"Le test de Sofia et de Paul","consigne":"Exploite les résultats du test, puis réponds en citant les valeurs utiles.","enonce":"**Situation.** Sofia et Paul passent un test d'**hyperglycémie provoquée** : à jeun, ils boivent 75 g de glucose, puis on mesure leur glycémie toutes les 30 minutes.\n\n| Temps (min) | 0 | 30 | 60 | 90 | 120 |\n| Glycémie de Sofia (g·L⁻¹) | 0,90 | 1,35 | 1,25 | 1,10 | 0,95 |\n| Glycémie de Paul (g·L⁻¹) | 1,25 | 1,90 | 2,30 | 2,40 | 2,20 |\n\nChez Paul, l'insulinémie mesurée est **élevée** pendant tout le test.\n\n1. Décris l'évolution de la glycémie de Sofia. Sa réponse est-elle normale ? Justifie avec le critère du cours.\n2. Explique, en nommant l'hormone et ses effets, pourquoi la glycémie de Sofia redescend.\n3. Paul est-il diabétique ? Justifie avec deux valeurs du tableau.\n4. Quel type de diabète l'insulinémie de Paul permet-elle de suspecter ? Justifie.","bareme":[{"critere":"Sofia : hausse jusqu'à 1,35 g·L⁻¹ à 30 min puis retour vers 0,95 g·L⁻¹, sous 1,4 à 2 h : réponse normale","points":5},{"critere":"Insuline sécrétée par les cellules β : entrée du glucose dans les cellules, glycogénogenèse, lipogenèse ; rétroaction négative","points":5},{"critere":"Paul diabétique : 2,20 g·L⁻¹ à 2 h (> 2) et glycémie à jeun 1,25 g·L⁻¹ au-dessus de l'intervalle normal","points":5},{"critere":"Diabète de type 2 : insuline présente mais peu efficace (résistance des cellules)","points":5}],"dureeMin":11,"corrige":"1. La glycémie de Sofia passe de 0,90 g·L⁻¹ à jeun à un maximum de **1,35 g·L⁻¹ à 30 min**, puis redescend à **0,95 g·L⁻¹ à 120 min**. Elle revient **sous 1,4 g·L⁻¹ à 2 h** : c'est une **réponse normale**.\n2. L'hyperglycémie est détectée par les cellules des îlots de Langerhans : les **cellules β** sécrètent de l'**insuline**. Elle fait **entrer le glucose dans les cellules** et stimule la **glycogénogenèse** (foie, muscles) et la **lipogenèse** (tissu adipeux) : la glycémie baisse et revient vers la consigne. C'est une **rétroaction négative**.\n3. Oui : sa glycémie à 2 h vaut **2,20 g·L⁻¹**, supérieure à **2 g·L⁻¹**, ce qui caractérise un diabète. De plus, sa glycémie à jeun (**1,25 g·L⁻¹**) dépasse déjà l'intervalle normal (0,7 à 1,1 g·L⁻¹).\n4. Chez Paul, l'insuline est **présente, et même élevée**, mais la glycémie ne baisse pas : l'insuline **agit mal**. C'est le signe d'une **résistance des cellules à l'insuline** : on suspecte un **diabète de type 2**. Dans un diabète de type 1, l'insuline serait absente."}$exo$::jsonb),
  ('ab9e8e28-7b9b-58cd-b635-6af53da956d8'::uuid, 3, 'application', $exo${"titre":"Deux diabètes, deux histoires","consigne":"Compare les deux situations en t'appuyant sur le cours. Rédige une réponse argumentée pour chaque question.","enonce":"**Document – Deux patients**\n\n| | Léo, 13 ans | M. Garnier, 58 ans |\n| Signes | amaigrissement rapide, soif intense | aucun signe marqué, découvert lors d'un bilan |\n| Mode de vie | sportif, poids normal | surpoids, sédentaire |\n| Glycémie à jeun | 2,1 g·L⁻¹ | 1,4 g·L⁻¹ |\n| Insulinémie | quasi nulle | normale à élevée |\n| Autre résultat | anticorps dirigés contre les cellules β | — |\n\n1. Identifie le type de diabète de chaque patient. Justifie avec au moins deux éléments du document.\n2. Dans chaque cas, indique **quel maillon** de la boucle de régulation de la glycémie est défaillant.\n3. Explique pourquoi Léo doit recevoir des injections d'insuline, et pourquoi aucune autre hormone de son organisme ne peut compenser ce manque.\n4. Quel traitement propose-t-on en premier à M. Garnier ? Justifie en lien avec la cause de sa maladie.","bareme":[{"critere":"Léo : type 1 (insuline quasi nulle, anticorps contre les cellules β, jeune) ; M. Garnier : type 2 (insuline présente, surpoids, sédentarité, âge)","points":6},{"critere":"Maillon défaillant : sécrétion du messager (cellules β détruites) chez Léo ; réponse des cellules cibles à l'insuline chez M. Garnier","points":5},{"critere":"Injections : insuline absente à remplacer ; seule hormone hypoglycémiante, le glucagon est hyperglycémiant","points":5},{"critere":"Hygiène de vie (alimentation, activité physique) puis médicaments, parfois insuline, reliés à la résistance liée au surpoids et à la sédentarité","points":4}],"dureeMin":17,"corrige":"1. **Léo** a un **diabète de type 1** : son insulinémie est **quasi nulle** et il possède des **anticorps dirigés contre les cellules β**, ce qui traduit leur **destruction auto-immune** ; il est jeune, comme souvent dans ce type. **M. Garnier** a un **diabète de type 2** : son insuline est **présente** (normale à élevée), mais sa glycémie reste élevée ; il est adulte, en **surpoids** et **sédentaire**, facteurs associés au type 2.\n2. Chez Léo, c'est le **messager** qui manque : les cellules β, détruites, ne sécrètent plus d'insuline en réponse à l'hyperglycémie. Chez M. Garnier, le messager est là mais les **cellules cibles** (foie, muscles, tissu adipeux) **répondent mal** à l'insuline : c'est la réponse des effecteurs qui est défaillante. Dans les deux cas, la rétroaction négative ne corrige plus l'écart à la consigne.\n3. Léo ne produit plus d'insuline : il faut l'**apporter de l'extérieur**, par **injections**. Aucune autre hormone ne peut la remplacer, car l'insuline est la **seule hormone hypoglycémiante** de l'organisme ; le glucagon, l'autre hormone de la régulation, a l'effet **inverse** (il fait monter la glycémie).\n4. On propose d'abord une **hygiène de vie** : alimentation équilibrée, perte de poids, activité physique. En effet, le diabète de type 2 est lié au **surpoids et à la sédentarité**, qui rendent les cellules résistantes à l'insuline. Si cela ne suffit pas, on ajoute des **médicaments**, et **parfois de l'insuline**."}$exo$::jsonb),
  ('7ebcf0eb-1261-5872-85b2-fe691a02bb5f'::uuid, 1, 'application', $exo${"titre":"Filtrer, reprendre, rejeter","consigne":"Réponds à chaque question en quelques phrases, avec le vocabulaire du cours.","enonce":"1. Décris le trajet de l'urine, du rein jusqu'à l'extérieur du corps, en nommant chaque organe. Quelle confusion d'orthographe faut-il éviter ?\n2. Quelle est l'**unité fonctionnelle** du rein ? Nomme ses parties dans l'ordre.\n3. Présente les **trois étapes** de la formation de l'urine : lieu et ce qui s'y passe. Quelle différence fais-tu entre urine primitive et urine définitive ?","bareme":[{"critere":"Rein → uretère → vessie → urètre ; uretère (du rein à la vessie) distingué de l'urètre (sortie de la vessie)","points":6},{"critere":"Néphron : glomérule dans la capsule de Bowman, tube contourné proximal, anse de Henlé, tube contourné distal, tube collecteur","points":6},{"critere":"Filtration (glomérule), réabsorption et sécrétion (tubes) décrites ; urine primitive = filtrat, urine définitive = au bout du tube collecteur","points":8}],"dureeMin":7,"corrige":"1. Les deux **reins** produisent l'urine ; deux **uretères** la conduisent à la **vessie**, qui la stocke ; l'**urètre** l'évacue à l'extérieur. Attention : l'**uretère** (avec è) part du rein, l'**urètre** sort de la vessie.\n2. L'unité fonctionnelle est le **néphron** (environ un million par rein). Dans l'ordre : le **corpuscule rénal** (un **glomérule**, pelote de capillaires, dans la **capsule de Bowman**), le **tube contourné proximal**, l'**anse de Henlé**, le **tube contourné distal**, puis le **tube collecteur**, commun à plusieurs néphrons.\n3. **Filtration**, dans le **glomérule** : le plasma passe dans la capsule, sauf les cellules et les grosses protéines. **Réabsorption**, dans les **tubes** : l'eau, le glucose et les ions utiles retournent dans le sang. **Sécrétion**, dans les **tubes** : certaines molécules (H⁺, médicaments) passent du sang vers le tube. L'**urine primitive** est le liquide filtré dans la capsule ; l'**urine définitive** est ce qui reste au bout du tube collecteur, après réabsorption et sécrétion."}$exo$::jsonb),
  ('7ebcf0eb-1261-5872-85b2-fe691a02bb5f'::uuid, 2, 'application', $exo${"titre":"Les comptes du rein","consigne":"Pose chaque calcul à partir des données, puis interprète le résultat.","enonce":"**Données** : chaque jour, les reins filtrent environ 180 L de plasma et produisent environ 1,5 L d'urine définitive.\n\n| Molécule (g·L⁻¹) | Plasma | Urine primitive | Urine définitive |\n| Protéines | 70 | ≈ 0 | 0 |\n| Glucose | 1 | 1 | 0 |\n| Urée | 0,3 | 0,3 | ≈ 20 |\n\n1. Calcule le pourcentage de l'eau filtrée qui est réabsorbée chaque jour.\n2. Calcule la masse de glucose filtrée en un jour. Quelle masse est rejetée dans l'urine ? Conclus.\n3. Calcule la masse d'urée filtrée et la masse d'urée rejetée en un jour. Par combien sa concentration est-elle multipliée entre le plasma et l'urine définitive ?\n4. Explique l'absence de protéines dans l'urine primitive.","bareme":[{"critere":"Eau réabsorbée : (180 − 1,5) / 180 ≈ 99,2 %","points":5},{"critere":"Glucose : 180 g filtrés, 0 g rejeté, glucose totalement réabsorbé","points":5},{"critere":"Urée : 54 g filtrés, 30 g rejetés, concentration multipliée par environ 67","points":6},{"critere":"Barrière de filtration (endothélium, membrane basale, podocytes) retenant les molécules de plus de 60 000 Da comme l'albumine","points":4}],"dureeMin":12,"corrige":"1. Eau réabsorbée : 180 − 1,5 = 178,5 L. Pourcentage : 178,5 / 180 ≈ 0,992, soit environ **99,2 %** de l'eau filtrée retourne dans le sang.\n2. Glucose filtré : 180 L × 1 g·L⁻¹ = **180 g** par jour. Glucose rejeté : 1,5 L × 0 g·L⁻¹ = **0 g**. Tout le glucose filtré est donc **réabsorbé** (dans le tube proximal, par co-transport avec Na⁺).\n3. Urée filtrée : 180 × 0,3 = **54 g**. Urée rejetée : 1,5 × 20 = **30 g**. Sa concentration passe de 0,3 à 20 g·L⁻¹ : elle est multipliée par 20 / 0,3 ≈ **67**. L'urée, déchet, est très concentrée dans l'urine parce que l'eau est presque entièrement réabsorbée ; les calculs montrent aussi qu'une partie seulement de l'urée filtrée est rejetée.\n4. La **barrière de filtration** du glomérule est faite de l'endothélium percé des capillaires, d'une membrane basale et des **podocytes**, dont les pédicelles laissent des fentes étroites. Seules les molécules de masse inférieure à **60 000 Da environ** passent ; les grosses protéines comme l'**albumine** restent dans le sang. L'urine primitive n'en contient donc presque pas."}$exo$::jsonb),
  ('7ebcf0eb-1261-5872-85b2-fe691a02bb5f'::uuid, 3, 'application', $exo${"titre":"Trois analyses d'urine","consigne":"Interprète chaque analyse en expliquant le mécanisme rénal en cause. Rédige des réponses argumentées.","enonce":"**Document – Résultats de trois patients**\n\n| | Patient A | Patient B | Patient C |\n| Glycémie à jeun | 2,5 g·L⁻¹ | 0,9 g·L⁻¹ | 0,9 g·L⁻¹ |\n| Glucose dans l'urine | 8 g·L⁻¹ | 0 | 0 |\n| Protéines dans l'urine | 0 | 3 g·L⁻¹, avec des globules rouges | 0 |\n| Diurèse | 2,5 L/jour | 1,5 L/jour | 12 L/jour, urine très diluée |\n\n1. Explique pourquoi le patient A a du glucose dans ses urines, alors qu'une personne saine n'en a pas. Quel est le seuil à retenir ?\n2. Quelle anomalie présente le patient B ? Quelle structure du rein est touchée ?\n3. Le patient C a une glycémie normale mais urine 12 L par jour. Propose une explication en nommant l'hormone en cause, la glande qui la libère, son mode d'action et le nom de cette maladie.\n4. Une personne en bonne santé a beaucoup transpiré lors d'une randonnée. Prévois l'évolution de sa sécrétion d'ADH, de sa diurèse et de la concentration de son urine. Justifie.","bareme":[{"critere":"Patient A : glycémie > 1,8 g·L⁻¹, transporteurs de réabsorption (co-transport Na⁺/glucose, tube proximal) saturés, glycosurie, signe de diabète","points":5},{"critere":"Patient B : protéines et globules rouges dans l'urine = lésion de la barrière de filtration glomérulaire","points":4},{"critere":"Patient C : manque d'ADH (neurohypophyse), pas d'insertion d'aquaporines dans le tube collecteur, eau non réabsorbée, diabète insipide","points":6},{"critere":"Randonneur : manque d'eau → ADH augmente → plus d'aquaporines, plus d'eau réabsorbée → diurèse baisse, urine plus concentrée","points":5}],"dureeMin":18,"corrige":"1. Le glucose est filtré dans le glomérule puis **réabsorbé** dans le tube proximal par **co-transport avec Na⁺**. Les transporteurs sont **en nombre limité** : au-delà d'une glycémie d'environ **1,8 g·L⁻¹**, ils sont **saturés**. Avec 2,5 g·L⁻¹, le patient A filtre plus de glucose que ses tubes ne peuvent en reprendre : l'excès passe dans l'urine. C'est une **glycosurie**, signe classique d'un **diabète**. Chez une personne saine (glycémie ≈ 1 g·L⁻¹), tout le glucose est réabsorbé.\n2. Le patient B a des **protéines** et des **globules rouges** dans l'urine. Normalement, ils ne traversent pas la **barrière de filtration** du glomérule (endothélium, membrane basale, podocytes). Leur présence signale une **lésion de cette barrière**.\n3. Sa glycémie est normale : ce n'est pas un diabète sucré. La réabsorption de l'eau dans le **tube collecteur** est réglée par l'**ADH** (hormone antidiurétique), libérée par la **neurohypophyse**. L'ADH fait insérer des **aquaporines** (canaux à eau) dans la membrane des cellules, ce qui permet à l'eau de retourner au sang. **Sans ADH**, l'eau n'est pas réabsorbée : l'urine est très diluée et la diurèse énorme (plus de 10 L par jour). C'est le **diabète insipide**.\n4. Le randonneur **manque d'eau** : la neurohypophyse libère **plus d'ADH**. Davantage d'aquaporines sont insérées dans le tube collecteur, **plus d'eau retourne au sang** : la **diurèse diminue** et l'urine devient **plus concentrée**. C'est une rétroaction négative qui limite la perte d'eau."}$exo$::jsonb),
  ('18b2360a-0b76-5c42-b0ea-2a22f97b6d29'::uuid, 1, 'application', $exo${"titre":"Des gonades sous contrôle","consigne":"Réponds à chaque question en quelques phrases, avec le vocabulaire du cours.","enonce":"1. Pour l'appareil génital masculin, nomme les **gonades**, les **gamètes**, les **voies génitales** et les **glandes annexes**.\n2. Une coupe de testicule montre deux structures. Nomme-les et indique la fonction de chacune.\n3. Distingue les **caractères sexuels primaires** et **secondaires**, avec deux exemples de caractères secondaires masculins.\n4. De quelle famille chimique est la testostérone, et de quelle molécule dérive-t-elle ?","bareme":[{"critere":"Testicules ; spermatozoïdes ; épididyme, canal déférent, urètre ; vésicules séminales, prostate","points":6},{"critere":"Tubes séminifères (spermatogenèse, cellules de Sertoli) et cellules de Leydig (testostérone sécrétée dans le sang)","points":6},{"critere":"Primaires = organes génitaux ; secondaires = apparus à la puberté, deux exemples justes","points":5},{"critere":"Hormone stéroïde dérivée du cholestérol","points":3}],"dureeMin":7,"corrige":"1. **Gonades** : les testicules. **Gamètes** : les spermatozoïdes, produits en continu dès la puberté. **Voies génitales** : épididyme, canal déférent, urètre. **Glandes annexes** : vésicules séminales et prostate.\n2. Les **tubes séminifères**, où se déroule la **spermatogenèse** (production des spermatozoïdes), avec les **cellules de Sertoli** qui nourrissent les cellules germinales. Entre les tubes, les **cellules de Leydig**, qui sécrètent la **testostérone** dans le sang.\n3. Les **caractères sexuels primaires** sont les organes génitaux eux-mêmes. Les **caractères sexuels secondaires** apparaissent à la puberté : chez l'homme, la **pilosité**, la **voix grave**, le **développement musculaire**.\n4. La testostérone est une **hormone stéroïde**, dérivée du **cholestérol**."}$exo$::jsonb),
  ('18b2360a-0b76-5c42-b0ea-2a22f97b6d29'::uuid, 2, 'application', $exo${"titre":"Quatre expériences chez le rat","consigne":"Interprète chaque expérience, puis construis une conclusion d'ensemble.","enonce":"**Document – Expériences sur des rats mâles adultes**\n\n| Expérience | Résultat |\n| 1. Ablation des testicules (castration) | la testostérone disparaît du sang ; les vésicules séminales et la prostate régressent |\n| 2. Castration puis injections de testostérone | vésicules séminales et prostate retrouvent un aspect normal |\n| 3. Ablation de l'hypophyse | les testicules s'atrophient, la testostérone chute, la spermatogenèse s'arrête |\n| 4. Ablation de l'hypophyse puis injections de LH | la testostérone est de nouveau sécrétée |\n\n1. Que montrent les expériences 1 et 2 sur l'origine et le rôle de la testostérone ?\n2. Que montre l'expérience 3 ?\n3. Que montre l'expérience 4 ? Quelles cellules du testicule la LH stimule-t-elle ?\n4. Construis la **cascade de régulation** complète de l'hypothalamus jusqu'aux organes cibles, en nommant chaque hormone.","bareme":[{"critere":"Exp. 1 et 2 : testostérone produite par les testicules, nécessaire au maintien des organes génitaux annexes, rôle hormonal prouvé par la restauration","points":5},{"critere":"Exp. 3 : l'hypophyse est nécessaire au fonctionnement du testicule (hormones et gamètes)","points":4},{"critere":"Exp. 4 : la LH hypophysaire stimule la sécrétion de testostérone par les cellules de Leydig","points":5},{"critere":"Cascade : hypothalamus (GnRH) → hypophyse (LH, FSH) → testicule (testostérone ; FSH sur Sertoli pour la spermatogenèse) → organes cibles","points":6}],"dureeMin":12,"corrige":"1. Expérience 1 : sans testicules, la testostérone disparaît et les organes annexes régressent : la testostérone est **produite par les testicules** et elle est **nécessaire** au maintien de ces organes. Expérience 2 : l'injection de testostérone seule suffit à restaurer ces organes : c'est bien cette **hormone**, transportée par le sang, qui agit sur ses organes cibles.\n2. Sans hypophyse, les testicules s'atrophient, ne sécrètent plus de testostérone et ne produisent plus de spermatozoïdes : le **testicule dépend de l'hypophyse** pour ses deux fonctions.\n3. L'injection de **LH** suffit à relancer la sécrétion de testostérone : l'hypophyse agit sur le testicule par la LH, qui stimule les **cellules de Leydig**.\n4. **Hypothalamus** → sécrète la **GnRH** → agit sur l'**hypophyse antérieure** → sécrète **LH** et **FSH** → agissent sur le **testicule** : la LH stimule les cellules de Leydig (**testostérone**), la FSH agit sur les cellules de Sertoli (**spermatogenèse**) → la testostérone agit sur ses **organes cibles** (organes génitaux, caractères sexuels secondaires). Chaque glande stimule la suivante : c'est une **cascade de régulation**."}$exo$::jsonb),
  ('18b2360a-0b76-5c42-b0ea-2a22f97b6d29'::uuid, 3, 'application', $exo${"titre":"Le bilan du culturiste","consigne":"Exploite le document et explique chaque résultat par le fonctionnement de l'axe hypothalamo-hypophysaire.","enonce":"**Situation.** Théo, 27 ans, culturiste, prend depuis un an des **stéroïdes anabolisants** (une testostérone de synthèse). Il consulte pour infertilité.\n\n**Document – Résultats de Théo comparés aux valeurs habituelles**\n\n| Mesure | Théo | Valeurs habituelles |\n| Hormones de type testostérone dans le sang | très élevées | normales |\n| LH | très basse | normale |\n| FSH | très basse | normale |\n| Volume des testicules | diminué | normal |\n| Spermatozoïdes | très peu nombreux | nombreux |\n\n1. Explique comment, chez un homme sans traitement, la concentration de testostérone reste à peu près constante.\n2. Explique pourquoi la LH et la FSH de Théo sont effondrées.\n3. Déduis-en pourquoi ses testicules ont diminué de volume et pourquoi il produit très peu de spermatozoïdes, en précisant le rôle de chacune des deux hormones hypophysaires.\n4. Théo arrête son traitement. Quelle évolution peut-on attendre de ses sécrétions de LH et de FSH ? Justifie par le mécanisme.","bareme":[{"critere":"Rétrocontrôle négatif : testostérone élevée freine GnRH, LH et FSH, ce qui la fait baisser ; concentration stabilisée","points":5},{"critere":"Stéroïdes = excès d'hormone qui exerce un rétrocontrôle négatif fort sur l'hypothalamus et l'hypophyse","points":5},{"critere":"Sans LH, cellules de Leydig non stimulées ; sans FSH, cellules de Sertoli non stimulées, spermatogenèse effondrée, testicules atrophiés","points":6},{"critere":"Arrêt : rétrocontrôle levé, GnRH puis LH et FSH peuvent de nouveau être sécrétées et relancer le testicule","points":4}],"dureeMin":16,"corrige":"1. La testostérone exerce un **rétrocontrôle négatif** sur l'hypothalamus et l'hypophyse. Si elle est trop élevée, elle **freine la sécrétion de GnRH, de LH et de FSH** : les testicules sont moins stimulés et la testostérone baisse. Si elle baisse, le frein se relâche, LH et FSH remontent et la testostérone est de nouveau sécrétée. Sa concentration reste ainsi à peu près constante.\n2. Les stéroïdes anabolisants apportent une **grande quantité d'hormone** de type testostérone. L'hypothalamus et l'hypophyse « voient » un taux très élevé : le **rétrocontrôle négatif** freine fortement la GnRH, donc la **LH** et la **FSH**, qui s'effondrent.\n3. La **LH** stimule normalement les **cellules de Leydig** et la **FSH** agit sur les **cellules de Sertoli**, qui soutiennent la **spermatogenèse**. Sans ces deux hormones, les testicules **ne sont plus stimulés** : leurs cellules ne travaillent plus, leur volume **diminue** et la production de **spermatozoïdes chute**, d'où l'infertilité. Le paradoxe s'explique : l'hormone ajoutée agit sur les muscles, mais elle éteint le testicule par le frein qu'elle exerce sur le cerveau.\n4. À l'arrêt, le taux d'hormone de synthèse baisse : le **rétrocontrôle négatif se relâche**. L'hypothalamus peut de nouveau sécréter la GnRH, l'hypophyse la **LH** et la **FSH**, qui remontent et peuvent **relancer** la sécrétion de testostérone et la spermatogenèse."}$exo$::jsonb),
  ('bfa8a56f-b14e-5ad2-8da5-7c9e11bff8e6'::uuid, 1, 'application', $exo${"titre":"Vingt-huit jours de dialogue","consigne":"Réponds à chaque question en quelques phrases, avec le vocabulaire du cours.","enonce":"1. Présente les phases du **cycle ovarien** : jours repères, événements dans l'ovaire, hormone ovarienne dominante.\n2. Explique comment l'**endomètre** évolue au cours du **cycle utérin** sous l'effet des hormones ovariennes. Qu'est-ce qui provoque les menstruations ?\n3. Qu'est-ce qui déclenche l'**ovulation** ?","bareme":[{"critere":"Phase folliculaire (j1-14, follicules, œstrogènes), ovulation (≈ j14), phase lutéale (j15-28, corps jaune, progestérone et œstrogènes)","points":8},{"critere":"Œstrogènes : prolifération ; progestérone : endomètre apte à la nidation ; chute des deux hormones : menstruations","points":7},{"critere":"Pic de LH, déclenché par un rétrocontrôle positif des œstrogènes au-delà d'une valeur seuil","points":5}],"dureeMin":7,"corrige":"1. **Phase folliculaire** (jours 1 à 14) : croissance de follicules (**folliculogenèse**), un seul arrive à maturité ; hormones dominantes : les **œstrogènes**, croissants. **Ovulation** (vers le jour 14) : le follicule mûr **libère l'ovocyte** ; pic d'œstrogènes. **Phase lutéale** (jours 15 à 28) : le follicule vide devient le **corps jaune**, qui sécrète **progestérone** et œstrogènes. Sans fécondation, le corps jaune dégénère vers le jour 28.\n2. Les **œstrogènes** font **proliférer** l'endomètre (épaississement). La **progestérone** le rend **apte à la nidation** (dentelle utérine, glandes sécrétrices). En fin de cycle, la **chute des œstrogènes et de la progestérone** provoque la destruction de l'endomètre : ce sont les **menstruations** (jour 1 du cycle suivant).\n3. L'ovulation est déclenchée par un **pic de LH**. En fin de phase folliculaire, les œstrogènes dépassent une **valeur seuil** : leur rétrocontrôle, négatif le reste du cycle, devient **positif** et provoque ce pic ; l'ovulation survient environ 36 heures plus tard."}$exo$::jsonb),
  ('bfa8a56f-b14e-5ad2-8da5-7c9e11bff8e6'::uuid, 2, 'application', $exo${"titre":"Le carnet de cycle de Clara","consigne":"Exploite le document, puis justifie chaque réponse par le fonctionnement hormonal.","enonce":"**Document – Dosages hormonaux au cours d'un cycle de Clara (sans grossesse)**\n\n| Jours | 1 à 7 | 8 à 12 | 13 | 14 | 15 à 17 | 18 à 24 | 25 à 28 |\n| Œstrogènes | faibles | en forte hausse | maximum | en baisse | modérés | modérés | en chute |\n| LH | basse | basse | pic | pic | basse | basse | basse |\n| Progestérone | très basse | très basse | très basse | faible | en hausse | élevée | en chute |\n\n1. Délimite les phases du cycle ovarien de Clara et justifie à l'aide des hormones.\n2. Explique pourquoi la LH forme un pic au jour 13, alors que les œstrogènes freinent sa sécrétion le reste du cycle.\n3. Le pic de LH commence le jour 13 à 8 h. À quel moment approximatif l'ovulation a-t-elle lieu ?\n4. Quelle structure de l'ovaire produit la progestérone des jours 18 à 24 ? Explique pourquoi Clara a ses règles au début du cycle suivant.","bareme":[{"critere":"Phase folliculaire j1-13/14 (œstrogènes croissants), ovulation vers j14, phase lutéale j15-28 (progestérone élevée)","points":5},{"critere":"Rétrocontrôle négatif habituel, devenu positif quand les œstrogènes dépassent la valeur seuil en fin de phase folliculaire","points":6},{"critere":"Ovulation environ 36 h après : jour 14 vers 20 h","points":4},{"critere":"Corps jaune ; sans fécondation il dégénère, progestérone et œstrogènes chutent, l'endomètre se détruit","points":5}],"dureeMin":12,"corrige":"1. **Phase folliculaire** : des jours 1 à 13 environ, les œstrogènes, faibles puis en forte hausse, témoignent de la croissance des follicules. **Ovulation** : vers le jour 14, juste après le pic de LH et le maximum des œstrogènes. **Phase lutéale** : des jours 15 à 28, la progestérone monte puis reste élevée, sécrétée par le corps jaune.\n2. Pendant la plus grande partie du cycle, les œstrogènes exercent un **rétrocontrôle négatif** sur l'hypothalamus et l'hypophyse. En fin de phase folliculaire (jours 8 à 12), leur concentration monte fortement ; quand elle **dépasse une valeur seuil**, le rétrocontrôle devient **positif** : l'hypophyse libère massivement de la LH, d'où le **pic** du jour 13.\n3. L'ovulation survient **environ 36 heures** après le début du pic de LH : jour 13 à 8 h + 36 h = **jour 14 vers 20 h**.\n4. La progestérone est produite par le **corps jaune**, formé à partir du follicule vide après l'ovulation. Sans fécondation, il **dégénère** vers le jour 28 : la **progestérone et les œstrogènes chutent** (jours 25 à 28). Privé de ces hormones, l'**endomètre se détruit** : ce sont les **menstruations**, qui marquent le jour 1 du cycle suivant."}$exo$::jsonb),
  ('bfa8a56f-b14e-5ad2-8da5-7c9e11bff8e6'::uuid, 3, 'application', $exo${"titre":"Empêcher ou aider une grossesse","consigne":"Explique chaque méthode par la logique hormonale du cycle. Rédige des réponses argumentées.","enonce":"**Situation.** Deux femmes consultent le même jour une gynécologue.\n\n- **Amina**, 22 ans, prend une **pilule combinée** (œstrogène et progestatif de synthèse, un comprimé par jour).\n- **Élise**, 34 ans, commence une **fécondation in vitro** (FIV). Son protocole : (1) un traitement qui met son cycle naturel au repos ; (2) des injections quotidiennes de FSH ; (3) une injection qui imite le pic de LH ; (4) la ponction des ovocytes, fécondés au laboratoire.\n\n1. Explique comment la pilule combinée empêche l'ovulation d'Amina.\n2. Indique un **second effet** du progestatif qui contribue à la contraception.\n3. Justifie chacune des étapes (2) et (3) du protocole d'Élise.\n4. Après la FIV, un embryon s'implante dans l'utérus d'Élise. Explique pourquoi ses règles n'ont alors pas lieu : quelle hormone l'embryon sécrète-t-il, et quel est son effet ?","bareme":[{"critere":"Apport quotidien d'hormones : rétrocontrôle négatif permanent, pas de pic de LH, pas d'ovulation","points":6},{"critere":"Progestatif : glaire cervicale épaissie qui bloque les spermatozoïdes","points":3},{"critere":"FSH : faire mûrir plusieurs follicules ; injection imitant le pic de LH : déclencher l'ovulation au moment choisi pour la ponction","points":6},{"critere":"hCG sécrétée par l'embryon maintient le corps jaune : progestérone élevée, endomètre conservé, pas de menstruations","points":5}],"dureeMin":17,"corrige":"1. Chaque jour, la pilule apporte des hormones de synthèse proches des hormones ovariennes. Elles exercent un **rétrocontrôle négatif permanent** sur l'hypothalamus et l'hypophyse : les œstrogènes ne franchissent jamais le seuil qui rendrait le rétrocontrôle positif, il n'y a **pas de pic de LH**, donc **pas d'ovulation**.\n2. Le progestatif **épaissit la glaire cervicale** : elle devient une barrière qui **bloque le passage des spermatozoïdes** vers l'utérus.\n3. Étape (2) : la **FSH** stimule la **croissance des follicules** ; en dose plus forte que dans un cycle naturel, elle fait **mûrir plusieurs follicules** à la fois, pour recueillir plusieurs ovocytes. Étape (3) : dans un cycle naturel, c'est le **pic de LH** qui déclenche l'ovulation. L'injection qui l'imite **déclenche la maturation finale et l'ovulation au moment choisi**, ce qui permet de programmer la **ponction** des ovocytes avant qu'ils ne soient perdus dans les trompes. L'étape (1) évite qu'un pic de LH naturel ne survienne trop tôt.\n4. L'embryon implanté sécrète l'hormone **hCG**, qui **maintient le corps jaune**. Celui-ci continue de sécréter la **progestérone** (et des œstrogènes), qui reste élevée : l'**endomètre n'est pas détruit** et reste apte à accueillir l'embryon. Les hormones ne chutent pas : **les règles n'ont pas lieu**."}$exo$::jsonb),
  ('1bea2126-b86c-5c04-b80f-457899a4d889'::uuid, 1, 'application', $exo${"titre":"De 46 à 23, puis de 23 + 23 à 46","consigne":"Réponds à chaque question en quelques phrases, avec le vocabulaire du cours.","enonce":"1. Que signifient **diploïde** et **haploïde** ? Donne le nombre de chromosomes d'une cellule somatique et d'un gamète humains.\n2. Compare la **mitose** et la **méiose** : rôle, nombre de divisions, cellules obtenues.\n3. Qu'est-ce qui se sépare au cours de la **méiose I** ? Et au cours de la **méiose II** ?\n4. Comment la **fécondation** rétablit-elle la diploïdie ?","bareme":[{"critere":"Diploïde 2n = 46 (paires de chromosomes), haploïde n = 23 (un chromosome de chaque paire)","points":4},{"critere":"Mitose : multiplier les cellules, une division, 2 cellules diploïdes identiques ; méiose : gamètes, deux divisions, 4 cellules haploïdes différentes","points":6},{"critere":"Méiose I : chromosomes homologues (réductionnelle) ; méiose II : chromatides (équationnelle)","points":6},{"critere":"Réunion de deux noyaux haploïdes : additivité des génomes nucléaires, zygote diploïde","points":4}],"dureeMin":7,"corrige":"1. Une cellule **diploïde** possède ses chromosomes par **paires** : 2n = **46** chromosomes (23 paires) pour une cellule somatique humaine. Une cellule **haploïde** ne possède qu'**un chromosome de chaque paire** : n = **23** pour un gamète.\n2. **Mitose** : sert à **multiplier les cellules** ; **une** division ; donne **2 cellules diploïdes identiques** ; division équationnelle. **Méiose** : sert à **produire les gamètes** ; **deux** divisions successives ; donne **4 cellules haploïdes différentes** ; division réductionnelle puis équationnelle.\n3. En **méiose I** (réductionnelle), les **chromosomes homologues** s'apparient puis se séparent : chaque cellule fille reçoit un chromosome de chaque paire, encore à deux chromatides. En **méiose II** (équationnelle), ce sont les **deux chromatides** de chaque chromosome qui se séparent, comme en mitose.\n4. À la fécondation, un spermatozoïde (n = 23) et un ovocyte (n = 23) réunissent leurs noyaux haploïdes : leurs chromosomes s'associent, c'est l'**additivité des génomes nucléaires**. La cellule-œuf (zygote) possède 23 + 23 = **46 chromosomes** : elle est diploïde."}$exo$::jsonb),
  ('1bea2126-b86c-5c04-b80f-457899a4d889'::uuid, 2, 'application', $exo${"titre":"Compter chromosomes et chromatides","consigne":"Pose chaque raisonnement et donne les nombres demandés en justifiant.","enonce":"**Situation.** Nadia suit une cellule germinale humaine (2n = 46) au cours de la méiose.\n\n1. Au début de la méiose, chaque chromosome est formé de deux chromatides. Combien la cellule contient-elle de **chromosomes** et de **chromatides** ?\n2. Même question pour **une** cellule obtenue à la fin de la méiose I, puis pour **un** gamète obtenu à la fin de la méiose II.\n3. Dans un testicule, 250 cellules germinales achèvent leur méiose. Combien de spermatozoïdes obtient-on ? Dans un ovaire, 250 cellules germinales achèvent leur ovogenèse : combien d'ovocytes obtient-on ? Explique la différence.\n4. Le chien a 78 chromosomes dans ses cellules somatiques. Combien de chromosomes contient un gamète de chien ? Et une cellule-œuf de chien ?","bareme":[{"critere":"Début de méiose : 46 chromosomes, 92 chromatides","points":5},{"critere":"Fin de méiose I : 23 chromosomes à 2 chromatides (46 chromatides) ; gamète : 23 chromosomes à 1 chromatide","points":6},{"critere":"1 000 spermatozoïdes et 250 ovocytes, différence expliquée par la division asymétrique (globules polaires qui dégénèrent)","points":5},{"critere":"Chien : gamète 39 chromosomes, cellule-œuf 78","points":4}],"dureeMin":11,"corrige":"1. La cellule est diploïde : **46 chromosomes**, chacun à deux chromatides, soit 46 × 2 = **92 chromatides**.\n2. **Fin de méiose I** : les homologues se sont séparés ; chaque cellule contient **23 chromosomes**, encore à deux chromatides, soit **46 chromatides**. **Fin de méiose II** : les chromatides se sont séparées ; chaque gamète contient **23 chromosomes à une chromatide** (23 chromatides).\n3. Chaque cellule germinale donne **4 spermatozoïdes** : 250 × 4 = **1 000 spermatozoïdes**. Chaque cellule germinale ne donne qu'**un ovocyte** : **250 ovocytes**. En effet, la division de l'ovogenèse est **asymétrique** : l'ovocyte garde presque tout le cytoplasme, et les autres cellules, les **globules polaires**, dégénèrent.\n4. Un gamète est haploïde : 78 / 2 = **39 chromosomes**. La fécondation réunit deux gamètes : 39 + 39 = **78 chromosomes** dans la cellule-œuf."}$exo$::jsonb),
  ('1bea2126-b86c-5c04-b80f-457899a4d889'::uuid, 3, 'application', $exo${"titre":"Deux anomalies, deux transmissions","consigne":"Analyse les deux situations en t'appuyant sur le déroulement de la méiose et de la fécondation. Rédige des réponses argumentées.","enonce":"**Partie A – Le caryotype de Jules.** Le caryotype de Jules, nouveau-né, montre **47 chromosomes**, dont trois chromosomes 21.\n\n1. Qu'est-ce qu'un caryotype ? Quel nom porte l'anomalie de Jules ?\n2. On sait que l'anomalie vient d'un gamète de sa mère, dont les deux chromosomes 21 ne se sont pas séparés en méiose I. Explique comment on obtient une cellule-œuf à 47 chromosomes, en précisant le nombre de chromosomes du gamète anormal.\n\n**Partie B – Une maladie mitochondriale.** Dans une famille, une maladie est due à une mutation de l'**ADN mitochondrial**.\n\n3. Monsieur R. est atteint, sa femme ne l'est pas. Quel risque ont leurs enfants d'être atteints ? Justifie.\n4. Madame S. est atteinte, son mari ne l'est pas. Même question. Justifie en expliquant ce qui se passe à la fécondation.","bareme":[{"critere":"Caryotype = chromosomes d'une cellule comptés et classés par paires ; trisomie 21","points":4},{"critere":"Non-séparation des chromosomes 21 en méiose I → gamète à 24 chromosomes (deux 21) ; fécondé par un gamète normal (23) → 47 chromosomes","points":6},{"critere":"Père atteint : aucun enfant atteint, les mitochondries du spermatozoïde ne sont pas conservées","points":5},{"critere":"Mère atteinte : tous ses enfants atteints, génome mitochondrial transmis par l'ovocyte seul","points":5}],"dureeMin":17,"corrige":"1. Un **caryotype** est la présentation des chromosomes d'une cellule, **comptés et classés par paires**. Trois chromosomes 21 au lieu de deux : c'est la **trisomie 21**.\n2. Normalement, en méiose I, les deux chromosomes 21 homologues se séparent et chaque cellule fille en reçoit un. Ici, ils **ne se sont pas séparés** : une cellule reçoit **les deux** chromosomes 21. Le gamète obtenu contient donc 22 autres chromosomes + 2 chromosomes 21 = **24 chromosomes**. Fécondé par un spermatozoïde normal (**23 chromosomes**, dont un 21), il donne une cellule-œuf à 24 + 23 = **47 chromosomes**, avec **trois chromosomes 21**. Toutes les cellules de Jules, issues de ce zygote par mitoses, portent cette anomalie.\n3. **Aucun** enfant ne sera atteint. Le génome mitochondrial n'est transmis que par la **mère** : à la fécondation, seul le **noyau** du spermatozoïde s'associe à celui de l'ovocyte ; les **mitochondries du spermatozoïde ne sont pas conservées**.\n4. **Tous** ses enfants, filles comme garçons, recevront la mutation. La cellule-œuf garde le cytoplasme de l'**ovocyte**, donc ses mitochondries et leur ADN : une maladie de l'ADN mitochondrial passe de la mère à **tous ses enfants**, jamais du père."}$exo$::jsonb),
  ('992fd801-ffab-59a8-8141-2b38f2c9016a'::uuid, 1, 'application', $exo${"titre":"Gènes, allèles et brassages","consigne":"Réponds à chaque question en quelques phrases, avec le vocabulaire du cours.","enonce":"1. Définis : **gène**, **allèle**, **génotype**, **phénotype**. Précise combien d'allèles d'un même gène porte une cellule diploïde.\n2. Que signifient **homozygote** et **hétérozygote** ? Chez un hétérozygote A//a, quel allèle s'exprime ? Dans quel cas un phénotype récessif apparaît-il ?\n3. Présente les **deux brassages** génétiques de la méiose : nom, moment, mécanisme.","bareme":[{"critere":"Gène, allèle, génotype, phénotype définis ; deux allèles par gène (un par chromosome homologue)","points":7},{"critere":"Homozygote/hétérozygote ; A dominant s'exprime ; phénotype récessif seulement chez a//a","points":5},{"critere":"Intrachromosomique (prophase I, crossing-over) et interchromosomique (anaphase I, ségrégation aléatoire des homologues)","points":8}],"dureeMin":7,"corrige":"1. Un **gène** est une portion d'ADN qui code une protéine et occupe une place précise sur un chromosome. Un **allèle** est une **version** d'un gène. Le **génotype** est la combinaison des allèles d'un individu ; le **phénotype** est ce qu'on observe, à l'échelle moléculaire, cellulaire ou de l'organisme. Une cellule diploïde porte **deux allèles** de chaque gène, un sur chaque chromosome homologue.\n2. **Homozygote** : deux allèles identiques (A//A ou a//a). **Hétérozygote** : deux allèles différents (A//a). Chez A//a, c'est l'allèle **dominant A** qui s'exprime ; a est **récessif**. Un phénotype récessif n'apparaît que chez l'**homozygote a//a**.\n3. **Brassage intrachromosomique** : en **prophase I**, les homologues appariés échangent des portions de chromatides, c'est le **crossing-over**. **Brassage interchromosomique** : en **anaphase I**, les homologues de chaque paire se séparent au **hasard** (ségrégation aléatoire), indépendamment des autres paires. Les deux créent des gamètes génétiquement différents."}$exo$::jsonb),
  ('992fd801-ffab-59a8-8141-2b38f2c9016a'::uuid, 2, 'application', $exo${"titre":"Le couple Moreau","consigne":"Raisonne à partir de la situation, construis l'échiquier et justifie chaque probabilité.","enonce":"**Situation.** Monsieur et Madame Moreau sont tous deux **en bonne santé**. Leur premier enfant, Hugo, est atteint d'une **maladie héréditaire** due à un gène porté par un autosome (allèles notés M et m).\n\n1. L'allèle responsable de la maladie est-il dominant ou récessif ? Justifie.\n2. Déduis-en les génotypes de Hugo et de ses deux parents.\n3. Construis l'**échiquier de croisement** des parents Moreau.\n4. Quelle est la probabilité que leur prochain enfant soit atteint ? Qu'il soit sain ? Qu'il soit hétérozygote ?","bareme":[{"critere":"Deux parents sains ont un enfant atteint : allèle récessif","points":4},{"critere":"Hugo m//m ; parents M//m (chacun a transmis un allèle m)","points":5},{"critere":"Échiquier juste : gamètes M et m à 50 % chez chaque parent, quatre cases M//M, M//m, M//m, m//m","points":6},{"critere":"Probabilités : atteint 1/4, sain 3/4, hétérozygote 1/2","points":5}],"dureeMin":11,"corrige":"1. Les deux parents sont sains mais ont un enfant atteint : l'allèle de la maladie était présent chez eux **sans s'exprimer**. Il est donc **récessif** (noté m ; l'allèle normal M est dominant).\n2. Hugo exprime un phénotype récessif : il est **m//m**. Il a reçu un allèle m de chacun de ses parents ; comme les parents sont sains, ils portent aussi un allèle M : ils sont **hétérozygotes M//m**.\n3. Chaque parent produit 50 % de gamètes M et 50 % de gamètes m.\n\n| | M | m |\n| **M** | M//M | M//m |\n| **m** | M//m | m//m |\n\n4. Enfant **atteint** (m//m) : 1 case sur 4, soit **1/4**. Enfant **sain** (M//M ou M//m) : **3/4**. Enfant **hétérozygote** (M//m) : 2 cases sur 4, soit **1/2**. Chaque naissance est indépendante : le fait qu'Hugo soit atteint ne change pas ces probabilités."}$exo$::jsonb),
  ('992fd801-ffab-59a8-8141-2b38f2c9016a'::uuid, 3, 'application', $exo${"titre":"L'arbre de la famille Lemoine","consigne":"Analyse l'arbre, justifie chaque déduction, puis rédige une explication de la diversité des enfants.","enonce":"**Document – Arbre généalogique de la famille Lemoine** (maladie héréditaire rare)\n\n- **Génération I** : I-1, homme sain ; I-2, femme saine.\n- **Génération II** (enfants de I-1 et I-2) : II-1, fille **atteinte** ; II-2, fils sain ; II-3, fils **atteint**.\n\n1. L'allèle responsable de la maladie est-il dominant ou récessif ? Justifie.\n2. Le gène est-il porté par un **autosome** ou par le chromosome **X** ? Justifie à l'aide d'une personne précise de l'arbre.\n3. Donne les génotypes de I-1, I-2, II-1 et II-3 (allèles A et a). Pourquoi ne peut-on pas donner avec certitude celui de II-2 ?\n4. II-2 et II-3 sont frères mais ne se ressemblent pas. Explique comment la méiose et la fécondation rendent chaque enfant génétiquement unique : nomme les deux brassages et calcule le nombre de gamètes différents qu'un parent peut produire par le seul brassage interchromosomique.","bareme":[{"critere":"Parents sains (I-1, I-2) avec enfants atteints : allèle récessif","points":4},{"critere":"II-1 fille atteinte de père sain (I-1) : gène non porté par X, donc autosomique","points":5},{"critere":"I-1 et I-2 A//a, II-1 et II-3 a//a ; II-2 A//A ou A//a, phénotype dominant qui ne révèle pas le second allèle","points":5},{"critere":"Crossing-over (prophase I), ségrégation aléatoire (anaphase I), 2²³ ≈ 8 millions de gamètes, fécondation au hasard qui multiplie la diversité","points":6}],"dureeMin":18,"corrige":"1. I-1 et I-2 sont **sains** mais ont deux enfants **atteints** (II-1 et II-3) : l'allèle était présent chez les parents sans s'exprimer. Il est **récessif** (a), l'allèle normal A est dominant.\n2. Si le gène était sur le chromosome X, une fille atteinte (a sur ses deux X) aurait reçu un X porteur de a de son **père**, qui lui transmet obligatoirement son unique X ; ce père serait alors atteint. Or **II-1 est une fille atteinte dont le père I-1 est sain** : le gène **n'est pas sur le chromosome X**, il est porté par un **autosome**.\n3. II-1 et II-3 sont atteints, donc **a//a**. Chacun a reçu un allèle a de chaque parent ; les parents étant sains, ils sont **I-1 : A//a** et **I-2 : A//a**. II-2 est sain : il possède au moins un allèle A, mais son phénotype (dominant) ne dit pas quel est son second allèle ; il peut être **A//A ou A//a**.\n4. Pendant la méiose de chaque parent, deux brassages créent des gamètes différents. Le **brassage intrachromosomique** : en **prophase I**, le **crossing-over** échange des portions de chromatides entre homologues appariés. Le **brassage interchromosomique** : en **anaphase I**, les homologues de chaque paire se répartissent **au hasard**. Avec 23 paires, ce seul brassage permet 2²³ = 8 388 608, soit environ **8 millions** de gamètes différents par parent. Enfin, la **fécondation** réunit **au hasard** un gamète de chaque parent, ce qui multiplie encore les combinaisons (environ 8 millions × 8 millions). Deux frères ne reçoivent donc pratiquement jamais la même combinaison d'allèles (sauf les vrais jumeaux)."}$exo$::jsonb),
  ('cb8a3e6e-8e94-5b73-9ccb-751dfa851a76'::uuid, 1, 'redaction', $exo${"titre":"Du cœur au glucose : ranger les niveaux d'organisation","consigne":"Réponds à chaque question par des phrases complètes, en utilisant le vocabulaire du cours.","enonce":"Voici six éléments du corps humain, donnés dans le désordre :\n\n> mitochondrie · appareil cardio-vasculaire · glucose du sang · cellule musculaire cardiaque · cœur · tissu musculaire cardiaque\n\n1. Range ces six éléments du plus grand au plus petit niveau d'organisation, et nomme le niveau de chacun (appareil, organe, tissu, cellule, ultrastructure, molécule).\n2. Pour chaque niveau, indique la technique qui permet de l'explorer : imagerie médicale, microscopie optique, microscopie électronique ou analyse biochimique.\n3. Donne la définition d'un **tissu** et celle d'un **organe**.","bareme":[{"critere":"Classement juste des six éléments, chacun associé à son niveau","points":8},{"critere":"Technique d'exploration correcte pour chaque niveau","points":7},{"critere":"Définitions exactes du tissu et de l'organe","points":5}],"dureeMin":7,"corrige":"1. Du plus grand au plus petit :\n- **appareil cardio-vasculaire** : appareil (ensemble d'organes qui assurent une même fonction) ;\n- **cœur** : organe ;\n- **tissu musculaire cardiaque** : tissu ;\n- **cellule musculaire cardiaque** : cellule ;\n- **mitochondrie** : ultrastructure (organite) ;\n- **glucose du sang** : molécule.\n2. Techniques :\n- appareil et organe → **imagerie médicale** (radiographie, scanner, IRM, échographie) ;\n- tissu et cellule → **microscopie optique** ;\n- ultrastructure (mitochondrie) → **microscopie électronique** ;\n- molécule (glucose) → **analyse biochimique** (bilan sanguin).\n3. Un **tissu** est un ensemble de cellules semblables et de leur matrice. Un **organe** est une structure formée de plusieurs tissus, qui a une fonction précise."}$exo$::jsonb),
  ('cb8a3e6e-8e94-5b73-9ccb-751dfa851a76'::uuid, 2, 'redaction', $exo${"titre":"Se repérer sur l'imagerie de Nadia","consigne":"Lis la situation, puis réponds aux questions en justifiant avec le vocabulaire du cours.","enonce":"**Situation.** Nadia, 34 ans, passe un scanner. Le radiologue réalise d'abord des coupes **horizontales** qui passent par le thorax, puis une coupe **verticale, d'avant en arrière**, qui passe par le milieu du corps. Plus tard, sur une radiographie vue de face, il repère une petite tache située **à gauche de l'image**.\n\n1. Nomme les deux types de coupes réalisées et indique ce que chacune sépare.\n2. Une coupe horizontale passe par la cavité thoracique : cite quatre organes que le radiologue peut y observer.\n3. La tache est-elle du côté droit ou du côté gauche de Nadia ? Justifie en rappelant la position anatomique.\n4. Quel muscle limite la cavité thoracique vers le bas ? Nomme la cavité située juste en dessous et cite trois organes qu'elle contient.","bareme":[{"critere":"Coupe transversale (haut / bas) et coupe sagittale (droite / gauche) nommées et expliquées","points":6},{"critere":"Quatre organes de la cavité thoracique : cœur, poumons, trachée, œsophage","points":4},{"critere":"Tache du côté droit de Nadia, justifiée par la lecture d'un cliché de face","points":5},{"critere":"Diaphragme nommé, cavité abdominale et trois de ses organes","points":5}],"dureeMin":10,"corrige":"1. Les coupes horizontales sont des coupes **transversales** (ou axiales) : elles séparent le **haut** (supérieur) du **bas** (inférieur). La coupe verticale d'avant en arrière est une coupe **sagittale** : elle sépare la **droite** de la **gauche**.\n2. La cavité thoracique contient le **cœur**, les **poumons**, la **trachée** et l'**œsophage**.\n3. La tache est du **côté droit** de Nadia. Le corps est décrit en position anatomique (debout, face à l'observateur, paumes vers l'avant) : sur un cliché vu de face, le patient est face à nous, donc sa droite apparaît **à gauche de l'image**.\n4. C'est le **diaphragme**, muscle en forme de dôme. En dessous se trouve la **cavité abdominale**, qui contient par exemple l'estomac, le foie, le pancréas, la rate, les intestins et, en arrière, les reins (trois organes suffisent)."}$exo$::jsonb),
  ('cb8a3e6e-8e94-5b73-9ccb-751dfa851a76'::uuid, 3, 'redaction', $exo${"titre":"Quand les poumons faiblissent, tout l'organisme souffre","consigne":"Appuie-toi sur le document et sur le cours. Chaque réponse doit être justifiée.","enonce":"**Document – Le dossier de M. Arnaud, 70 ans**\n\n> M. Arnaud souffre d'une insuffisance respiratoire : ses poumons font passer moins de dioxygène dans le sang. Il se plaint d'être essoufflé, d'avoir les jambes faibles à la marche et d'avoir parfois du mal à se concentrer. Le médecin demande un bilan sanguin, une radiographie du thorax et une biopsie pulmonaire (petit prélèvement de poumon) observée au microscope optique par un service d'**histologie**.\n\n1. Indique dans quelle cavité se trouvent les organes suivants : poumons, cœur, reins, encéphale, vessie, moelle épinière.\n2. À quel niveau d'organisation chaque examen explore-t-il le corps (bilan sanguin, radiographie, biopsie observée au microscope optique) ? Explique le mot « histologie » à l'aide de sa racine.\n3. Explique pourquoi une atteinte des seuls poumons retentit sur les muscles et sur le cerveau de M. Arnaud. Nomme les appareils en jeu et leur rôle.\n4. Les cellules rejettent des déchets : montre que leur élimination fait intervenir deux autres organes, et par quel appareil les déchets y sont conduits.\n5. Quels systèmes coordonnent le fonctionnement de tous ces appareils, et que transmettent-ils ?","bareme":[{"critere":"Cavité juste pour chacun des six organes","points":4},{"critere":"Niveau exploré par chaque examen ; histologie = étude des tissus","points":4},{"critere":"Explication de l'interdépendance : respiratoire → cardio-vasculaire → muscles et cerveau privés d'O₂","points":6},{"critere":"Élimination du CO₂ par les poumons et de l'urée par les reins, transport par l'appareil cardio-vasculaire","points":4},{"critere":"Système nerveux et système hormonal, qui transmettent l'information","points":2}],"dureeMin":16,"corrige":"1. Poumons et cœur : cavité **thoracique**. Reins : cavité **abdominale** (en arrière). Encéphale : cavité **crânienne**. Vessie : cavité **pelvienne**. Moelle épinière : cavité **rachidienne** (canal vertébral).\n2. Le bilan sanguin est une **analyse biochimique** : il explore le niveau **moléculaire**. La radiographie est une imagerie médicale : elle explore l'**organe** (et l'appareil). La biopsie observée au microscope optique explore les **tissus** et les **cellules**. « Histologie » vient de **hist(o)** = tissu : c'est l'étude des tissus.\n3. Aucun appareil ne fonctionne seul. L'**appareil respiratoire** fournit le dioxygène ; l'**appareil cardio-vasculaire** le distribue à toutes les cellules. Si les poumons font passer moins d'O₂ dans le sang, le sang distribué aux **muscles** et au **cerveau** en contient moins : les muscles s'affaiblissent (jambes faibles), le cerveau fonctionne moins bien (difficultés de concentration). Une atteinte d'un seul appareil retentit sur tous les autres.\n4. L'appareil cardio-vasculaire emporte les déchets des cellules : le **CO₂** vers les **poumons**, qui le rejettent, et l'**urée** vers les **reins**. L'élimination dépend donc de trois appareils à la fois.\n5. Le **système nerveux** et le **système hormonal** transmettent l'**information** qui coordonne l'ensemble des appareils."}$exo$::jsonb),
  ('f3a7552d-0035-54cd-9a16-62a8fee18ad4'::uuid, 1, 'redaction', $exo${"titre":"Épithélium ou conjonctif ?","consigne":"Réponds à chaque question en utilisant le vocabulaire du cours.","enonce":"1. Recopie et complète le tableau :\n\n| Le critère | Tissu épithélial | Tissu conjonctif |\n| Disposition des cellules | … | … |\n| Matrice extracellulaire | … | … |\n| Vaisseaux sanguins | … | … |\n| Deux fonctions | … | … |\n\n2. Classe ces tissus dans la bonne famille : épiderme, tissu adipeux, sang, épithélium intestinal, cartilage, os.\n3. Comment un épithélium qui ne contient pas de vaisseaux est-il nourri ?","bareme":[{"critere":"Tableau complet et juste (cellules, matrice, vaisseaux, fonctions)","points":10},{"critere":"Classement juste des six tissus","points":6},{"critere":"Nutrition de l'épithélium par diffusion depuis le conjonctif","points":4}],"dureeMin":7,"corrige":"1. Tableau :\n- Disposition : épithélial = cellules **jointives**, serrées ; conjonctif = cellules **dispersées**.\n- Matrice : épithélial = **presque absente** ; conjonctif = **abondante** (fibres de collagène, d'élastine, substance fondamentale).\n- Vaisseaux : épithélial = **absents** ; conjonctif = **présents**.\n- Fonctions : épithélial = **revêtement** (peau, muqueuses) et **sécrétion** (glandes) ; conjonctif = deux parmi **soutien, nutrition, défense, réserve**.\n2. Tissus **épithéliaux** : épiderme, épithélium intestinal. Tissus **conjonctifs** : tissu adipeux, sang (matrice liquide, le plasma), cartilage, os.\n3. L'épithélium repose sur une **lame basale** ; il est nourri par **diffusion** depuis le tissu conjonctif situé dessous, qui, lui, contient des vaisseaux."}$exo$::jsonb),
  ('f3a7552d-0035-54cd-9a16-62a8fee18ad4'::uuid, 2, 'redaction', $exo${"titre":"Deux cellules au microscope électronique","consigne":"Analyse le document, puis réponds en justifiant chaque réponse par une donnée du document et une connaissance du cours.","enonce":"**Document – Observations au microscope électronique**\n\n| | Cellule A | Cellule B |\n| Forme | Petite, arrondie | Très longue |\n| Noyaux | Un seul | Plusieurs |\n| Réticulum endoplasmique rugueux | Très abondant | Peu abondant |\n| Appareil de Golgi | Très développé, entouré de vésicules | Peu développé |\n| Mitochondries | Présentes | Extrêmement nombreuses |\n\n1. Indique le rôle du réticulum endoplasmique rugueux, de l'appareil de Golgi et de la mitochondrie.\n2. L'une de ces cellules est une cellule pancréatique qui sécrète des protéines, l'autre une fibre musculaire striée. Identifie chacune et justifie.\n3. De quelles molécules la membrane plasmique de ces deux cellules est-elle faite ?","bareme":[{"critere":"Rôles exacts du RER, du Golgi et de la mitochondrie","points":6},{"critere":"Cellule A pancréatique justifiée par le RER et le Golgi abondants","points":5},{"critere":"Cellule B fibre musculaire justifiée par la forme, les noyaux et les mitochondries","points":5},{"critere":"Bicouche de phospholipides, protéines, cholestérol, glucides en surface","points":4}],"dureeMin":11,"corrige":"1. Le **réticulum endoplasmique rugueux** assure la synthèse et le transport des protéines (des ribosomes y sont fixés). L'**appareil de Golgi** assure la maturation, le tri et la sécrétion des protéines. La **mitochondrie** est le siège de la **respiration cellulaire** et produit l'ATP.\n2. La **cellule A** est la **cellule pancréatique** : son RER très abondant et son Golgi très développé entouré de vésicules montrent une forte production et sécrétion de protéines. La **cellule B** est la **fibre musculaire striée** : elle est très longue et possède plusieurs noyaux, comme la fibre musculaire, et ses mitochondries extrêmement nombreuses fournissent l'énergie (ATP) nécessaire à la contraction. La structure de chaque cellule est adaptée à sa fonction.\n3. La membrane plasmique est une **bicouche de phospholipides** dans laquelle sont insérées des **protéines** et du **cholestérol**, avec des **glucides** en surface."}$exo$::jsonb),
  ('f3a7552d-0035-54cd-9a16-62a8fee18ad4'::uuid, 3, 'redaction', $exo${"titre":"Une structure adaptée à chaque fonction","consigne":"Exploite les documents et le cours. Pour chaque réponse, relie une caractéristique de structure à une fonction.","enonce":"**Document 1 – La paroi de l'intestin grêle au microscope**\n\n> On observe une seule couche de cellules hautes et étroites, serrées les unes contre les autres, reposant sur une lame basale. Leur pôle tourné vers la lumière de l'intestin (pôle apical) est hérissé de microvillosités. Sous la lame basale, un tissu aux cellules dispersées contient de nombreux capillaires sanguins.\n\n**Document 2 – La peau au microscope**\n\n> L'épiderme est formé de nombreuses couches de cellules aplaties, sans vaisseaux sanguins.\n\n**Document 3 – Le globule rouge**\n\n> L'hématie est dépourvue de noyau, de forme biconcave, et remplie d'hémoglobine.\n\n1. Nomme précisément l'épithélium du document 1 (nombre de couches et forme des cellules), puis celui du document 2. Justifie.\n2. Explique en quoi l'épithélium intestinal et l'entérocyte sont adaptés à l'absorption des nutriments.\n3. Les nutriments absorbés doivent traverser le tissu situé sous la lame basale avant de rejoindre le sang : nomme ce tissu et explique pourquoi ils ne peuvent pas passer directement de l'épithélium au sang.\n4. Explique pourquoi l'épiderme est adapté à sa fonction.\n5. Relie la structure de l'hématie à sa fonction.","bareme":[{"critere":"Épithélium prismatique simple (doc 1) et pavimenteux stratifié (doc 2), justifiés","points":4},{"critere":"Une seule couche et microvillosités qui augmentent la surface : adaptation à l'absorption","points":5},{"critere":"Tissu conjonctif vascularisé ; épithélium sans vaisseaux","points":4},{"critere":"Épiderme à plusieurs couches résistant aux frottements","points":3},{"critere":"Hématie sans noyau, pleine d'hémoglobine : transport du dioxygène","points":4}],"dureeMin":16,"corrige":"1. Document 1 : **épithélium prismatique simple** — une seule couche (simple) de cellules hautes et étroites (prismatiques), jointives, sur une lame basale. Document 2 : **épithélium pavimenteux stratifié** — plusieurs couches (stratifié) de cellules aplaties (pavimenteuses).\n2. L'épithélium intestinal n'a qu'**une seule couche** de cellules : les nutriments n'ont qu'une cellule à traverser, ce qui **facilite les échanges**. Chaque entérocyte porte des **microvillosités** à son pôle apical, qui augmentent la surface d'échange : l'**absorption** des nutriments est plus efficace.\n3. C'est un **tissu conjonctif** (cellules dispersées, riche en capillaires). Un épithélium ne contient **aucun vaisseau sanguin** : il est nourri par diffusion depuis le conjonctif. Les nutriments doivent donc passer dans le conjonctif pour atteindre les capillaires.\n4. L'épiderme compte **plusieurs couches** de cellules : il **résiste aux frottements**, ce qui convient à un revêtement qui protège le corps de l'extérieur.\n5. L'hématie n'a **pas de noyau** et elle est **pleine d'hémoglobine** : toute la place est occupée par la molécule qui transporte le dioxygène. Sa structure est adaptée à sa fonction, le **transport du dioxygène**."}$exo$::jsonb),
  ('d1fc758f-3cef-5d26-ae3a-350321cc640b'::uuid, 1, 'redaction', $exo${"titre":"La charpente du corps","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Classe ces os dans le squelette **axial** ou le squelette **appendiculaire** : fémur, sternum, clavicule, vertèbre lombaire, côte, scapula, humérus, sacrum.\n2. Combien la colonne vertébrale compte-t-elle de vertèbres cervicales, thoraciques et lombaires ?\n3. Cite quatre rôles du squelette.","bareme":[{"critere":"Classement juste des huit os","points":8},{"critere":"7 cervicales, 12 thoraciques, 5 lombaires","points":6},{"critere":"Quatre rôles du squelette exacts","points":6}],"dureeMin":7,"corrige":"1. Squelette **axial** : sternum, vertèbre lombaire, côte, sacrum. Squelette **appendiculaire** : fémur (membre inférieur), clavicule et scapula (ceinture scapulaire), humérus (membre supérieur).\n2. La colonne vertébrale compte **7 vertèbres cervicales**, **12 thoraciques** et **5 lombaires**, puis le sacrum et le coccyx.\n3. Le squelette (quatre rôles parmi) : **soutient** le corps ; **protège** les organes (crâne, cage thoracique) ; sert de **levier** aux muscles ; **stocke le calcium** ; **produit les cellules sanguines** dans la moelle osseuse rouge."}$exo$::jsonb),
  ('d1fc758f-3cef-5d26-ae3a-350321cc640b'::uuid, 2, 'redaction', $exo${"titre":"Le genou de Léo","consigne":"Lis la situation, puis réponds aux questions en t'appuyant sur le cours.","enonce":"**Situation.** Léo, 17 ans, footballeur, se tord le genou pendant un match. Le médecin craint une atteinte d'un **ligament** ou d'un **ménisque** (petit coussinet fibreux situé dans le genou). Il hésite entre une radiographie et une IRM.\n\n1. Le genou est une articulation mobile. Nomme ses cinq éléments et donne le rôle de chacun.\n2. Quelle différence y a-t-il entre un ligament et un tendon ?\n3. Quel examen le médecin doit-il choisir ? Justifie en comparant le principe et les intérêts des deux techniques.\n4. Le grand-père de Léo souffre de **gonarthrose**. Explique ce mot à l'aide de ses racines.","bareme":[{"critere":"Cinq éléments de l'articulation mobile et leur rôle","points":8},{"critere":"Ligament : os–os ; tendon : muscle–os","points":3},{"critere":"Choix de l'IRM justifié par le principe et l'intérêt pour les tissus mous","points":6},{"critere":"Gonarthrose = arthrose du genou, racines gon(o) et arthr(o)","points":3}],"dureeMin":11,"corrige":"1. Éléments de l'articulation mobile (synoviale) :\n- **cartilage articulaire** : recouvre les extrémités osseuses, amortit et fait glisser ;\n- **capsule articulaire** : manchon fibreux qui enferme l'articulation ;\n- **membrane synoviale** : tapisse la capsule et sécrète le liquide synovial ;\n- **liquide synovial** : lubrifie et nourrit le cartilage ;\n- **ligaments** : relient les os entre eux et stabilisent.\n2. Un **ligament** relie deux **os** entre eux ; un **tendon** relie un **muscle** à un **os**.\n3. Il doit choisir l'**IRM**. La radiographie utilise des **rayons X**, fortement absorbés par l'os, qui apparaît blanc : elle montre bien l'os (fracture, arthrose) mais mal les tissus mous. L'IRM utilise un **champ magnétique** et des **ondes de radiofréquence** qui font émettre un signal aux noyaux d'hydrogène des tissus : elle est excellente pour les **tissus mous**, comme les ligaments et les ménisques, et n'utilise **aucun rayonnement ionisant**.\n4. **Gon(o)** = genou et **arthr(o)** = articulation ; l'arthrose est l'usure du cartilage articulaire. La **gonarthrose** est l'**arthrose du genou**."}$exo$::jsonb),
  ('d1fc758f-3cef-5d26-ae3a-350321cc640b'::uuid, 3, 'redaction', $exo${"titre":"Choisir le bon examen d'imagerie","consigne":"Pour chaque patient, justifie ton choix par le principe, les intérêts et les limites de la technique.","enonce":"**Document – Trois patients aux urgences**\n\n> **Mme Durand**, 45 ans, est tombée sur la main. Le médecin suspecte une fracture simple du poignet et veut une réponse rapide.\n>\n> **M. Petit**, 30 ans, a eu un grave accident de voiture. On suspecte une fracture complexe du bassin, avec plusieurs fragments osseux.\n>\n> **Mme Roux**, 29 ans, enceinte de cinq mois, a une douleur au genou : on suspecte une lésion d'un ligament. Elle ne porte aucun objet métallique ni dispositif implanté.\n\n1. Pour chaque patient, choisis entre radiographie, scanner (scanographie) et IRM, et justifie.\n2. Explique pourquoi l'os apparaît blanc sur une radiographie.\n3. Pourquoi l'IRM ne peut-elle pas être proposée sans précaution à toute personne ? Donne deux exemples.\n4. Explique, à l'aide des racines, les mots : **coxarthrose**, **ostéoporose**.","bareme":[{"critere":"Radiographie pour Mme Durand, justifiée (simple, rapide, peu coûteuse, os visible)","points":4},{"critere":"Scanner pour M. Petit, justifié (coupes, 3D, pas de superposition) avec sa limite de dose","points":4},{"critere":"IRM pour Mme Roux, justifiée (tissus mous, aucun rayonnement ionisant, rayons X évités chez la femme enceinte)","points":5},{"critere":"Absorption des rayons X par l'os ; contre-indications de l'IRM (objets métalliques, certains pacemakers)","points":4},{"critere":"Coxarthrose et ostéoporose expliquées par leurs racines","points":3}],"dureeMin":18,"corrige":"1. **Mme Durand** : **radiographie**. C'est un examen simple, rapide et peu coûteux, adapté aux fractures simples : l'os y apparaît nettement. Sa limite (image plane, rayons ionisants) n'empêche pas de voir une fracture du poignet.\n**M. Petit** : **scanner**. Le tube à rayons X tourne autour du patient et l'ordinateur reconstruit des **coupes** et des images en **3D** : pas de superposition des structures, détail fin, idéal pour une fracture complexe et un traumatisme. Limite : dose de rayons X plus élevée qu'une radiographie, acceptable ici vu la gravité.\n**Mme Roux** : **IRM**. Elle est excellente pour les **tissus mous** comme les ligaments, et n'utilise **aucun rayonnement ionisant** ; or la radiographie (et le scanner, qui utilise aussi les rayons X) est en principe contre-indiquée chez la femme enceinte. Elle ne porte aucun objet métallique : l'IRM est possible.\n2. Les rayons X traversent le corps et sont plus ou moins absorbés. L'os est **très absorbant** : peu de rayons le traversent, il apparaît **blanc**.\n3. L'IRM utilise un **champ magnétique intense** : elle est contre-indiquée avec certains objets métalliques ou dispositifs, par exemple **certains pacemakers** et des **éclats métalliques**. C'est aussi un examen long et bruyant.\n4. **Coxarthrose** : cox(o) = hanche + arthrose (usure du cartilage articulaire) → arthrose de la hanche. **Ostéoporose** : osté(o) = os → fragilisation de l'os."}$exo$::jsonb),
  ('2ed30fa5-823c-5eb9-935a-dbfab4eacdc9'::uuid, 1, 'redaction', $exo${"titre":"Le neurone et le système nerveux","consigne":"Réponds à chaque question par des phrases complètes, avec le vocabulaire du cours.","enonce":"1. Cite les cinq éléments d'un neurone vus en cours et donne le rôle de chacun.\n2. Dans quel sens l'influx nerveux parcourt-il le neurone ?\n3. Quels organes forment le système nerveux central et où sont-ils logés ? Que comprend le système nerveux périphérique ?","bareme":[{"critere":"Cinq éléments du neurone et leur rôle","points":9},{"critere":"Sens de l'influx : dendrites → corps cellulaire → axone → terminaisons","points":4},{"critere":"SNC (encéphale dans le crâne, moelle dans le canal vertébral) et SNP (12 paires crâniennes, 31 rachidiennes, ganglions)","points":7}],"dureeMin":7,"corrige":"1. Le neurone comprend :\n- le **corps cellulaire**, qui contient le noyau ;\n- les **dendrites**, courts prolongements qui reçoivent les messages ;\n- l'**axone**, long prolongement unique qui conduit l'influx vers la terminaison ;\n- la **gaine de myéline**, manchon isolant autour de l'axone, interrompu par les nœuds de Ranvier ;\n- l'**arborisation terminale** et ses boutons synaptiques, qui transmettent le message à la cellule suivante.\n2. L'influx va des **dendrites** vers le **corps cellulaire**, puis le long de l'**axone** jusqu'aux **terminaisons**.\n3. Le **système nerveux central** comprend l'**encéphale** (cerveau, cervelet, tronc cérébral), logé dans le **crâne**, et la **moelle épinière**, logée dans le **canal vertébral**. Le **système nerveux périphérique** comprend les **nerfs crâniens** (12 paires), les **nerfs rachidiens** (31 paires) et les ganglions."}$exo$::jsonb),
  ('2ed30fa5-823c-5eb9-935a-dbfab4eacdc9'::uuid, 2, 'redaction', $exo${"titre":"Enregistrer une fibre nerveuse","consigne":"Exploite le document : décris avec des valeurs, puis interprète avec le cours.","enonce":"**Document – Réponses d'une fibre nerveuse isolée**\n\nAu repos, un appareil mesure entre l'intérieur et l'extérieur de la fibre une valeur de **− 70 mV**. On la stimule avec des intensités croissantes.\n\n| Intensité de la stimulation | Réponse enregistrée |\n| 0,5 V | Aucun potentiel d'action |\n| 1,0 V | Aucun potentiel d'action |\n| 1,5 V | Un potentiel d'action qui monte jusqu'à + 30 mV |\n| 3,0 V | Un potentiel d'action qui monte jusqu'à + 30 mV |\n\nOn applique ensuite des stimulations prolongées : à 2 V, la fibre émet **20 potentiels d'action par seconde** ; à 4 V, elle en émet **50 par seconde**, toujours jusqu'à + 30 mV.\n\n1. Comment s'appelle la valeur de − 70 mV ? Que signifie son signe négatif ?\n2. Entre quelles intensités se situe le seuil de la fibre ? Quelle loi le tableau illustre-t-il ? Énonce-la.\n3. Calcule l'amplitude du potentiel d'action et nomme les phases qui le composent.\n4. Comment la fibre code-t-elle l'intensité de la stimulation ? Justifie avec les données.","bareme":[{"critere":"Potentiel de repos ; intérieur négatif par rapport à l'extérieur","points":4},{"critere":"Seuil entre 1,0 et 1,5 V ; loi du tout ou rien énoncée et reliée aux données","points":6},{"critere":"Amplitude de 100 mV calculée ; dépolarisation, repolarisation, hyperpolarisation","points":5},{"critere":"Codage en fréquence justifié par 20 puis 50 PA par seconde à amplitude constante","points":5}],"dureeMin":12,"corrige":"1. C'est le **potentiel de repos**. Son signe négatif signifie qu'au repos, l'**intérieur** de la fibre est **négatif** par rapport à l'extérieur.\n2. À 1,0 V il n'y a pas de potentiel d'action, à 1,5 V il y en a un : le **seuil** est compris **entre 1,0 V et 1,5 V**. Le tableau illustre la loi du **tout ou rien** : sous le seuil, pas de potentiel d'action ; au-dessus, un potentiel d'action d'**amplitude constante** (+ 30 mV à 1,5 V comme à 3,0 V).\n3. Amplitude = + 30 − (− 70) = **100 mV**. Le potentiel d'action comprend une **dépolarisation** (le potentiel monte jusqu'à devenir positif), une **repolarisation** (il redescend) et une **hyperpolarisation** (il passe brièvement sous le potentiel de repos, puis y revient).\n4. L'intensité est codée par la **fréquence** des potentiels d'action, pas par leur amplitude : à 2 V, 20 PA/s ; à 4 V, 50 PA/s ; mais l'amplitude reste la même (jusqu'à + 30 mV). Plus la stimulation est intense, plus les PA sont nombreux par seconde."}$exo$::jsonb),
  ('2ed30fa5-823c-5eb9-935a-dbfab4eacdc9'::uuid, 3, 'redaction', $exo${"titre":"Fibre isolée ou nerf entier ?","consigne":"Exploite les trois documents. Chaque idée doit s'appuyer sur une donnée chiffrée et une explication du cours.","enonce":"**Document 1 – Une fibre isolée.** Stimulée au-dessus de son seuil, une fibre nerveuse répond toujours par un potentiel d'action de même amplitude, quelle que soit l'intensité.\n\n**Document 2 – Un nerf entier (le nerf sciatique)**\n\n| Intensité de la stimulation | Amplitude de la réponse globale du nerf |\n| 1 V | 0 mV |\n| 2 V | 1,2 mV |\n| 4 V | 3,5 mV |\n| 6 V | 5,0 mV |\n| 8 V | 5,0 mV |\n\n**Document 3 – Deux fibres du nerf.** La fibre A, myélinisée, conduit l'influx à **60 m/s** ; la fibre B, sans myéline, à **1 m/s**. Chacune mesure **0,90 m**.\n\n1. Décris l'évolution de la réponse du nerf (document 2) en citant des valeurs.\n2. Cette évolution semble contredire la loi du tout ou rien (document 1). Explique pourquoi il n'y a pas de contradiction.\n3. Décris l'organisation d'un nerf, de la fibre à l'enveloppe externe.\n4. Calcule le temps mis par l'influx pour parcourir chacune des deux fibres du document 3, en millisecondes. Explique la différence.\n5. Conclus : qu'est-ce qui distingue la réponse d'une fibre de celle d'un nerf ?","bareme":[{"critere":"Description chiffrée : pas de réponse à 1 V, hausse de 1,2 à 5,0 mV, plateau entre 6 et 8 V","points":4},{"critere":"Recrutement de fibres de seuils différents, jusqu'au maximum quand toutes répondent","points":5},{"critere":"Organisation du nerf : fibres, fascicules, endonèvre, périnèvre, épinèvre avec vaisseaux","points":3},{"critere":"Calculs justes (15 ms et 900 ms) et conduction saltatoire de nœud de Ranvier en nœud","points":5},{"critere":"Conclusion claire opposant fibre (tout ou rien) et nerf (réponse graduée)","points":3}],"dureeMin":18,"corrige":"1. À 1 V, le nerf ne répond pas (0 mV). De 2 à 6 V, l'amplitude de la réponse **augmente** : 1,2 mV à 2 V, 3,5 mV à 4 V, 5,0 mV à 6 V. Au-delà, elle ne change plus : 5,0 mV à 8 V, c'est un **maximum**.\n2. Un nerf contient **de nombreuses fibres**, qui ont des **seuils différents**. Chaque fibre obéit bien au tout ou rien. Mais plus la stimulation est intense, plus le nombre de fibres dont le seuil est dépassé augmente : c'est le **recrutement**. La réponse globale, somme des réponses des fibres, augmente donc, jusqu'au maximum atteint quand **toutes** les fibres répondent (ici au plus tard à 6 V).\n3. Un nerf est un faisceau de nombreuses **fibres nerveuses** (axones) regroupées en **fascicules**. Chaque fibre est entourée d'une fine enveloppe conjonctive (**endonèvre**), chaque fascicule d'une gaine (**périnèvre**), et le nerf entier d'une enveloppe externe (**épinèvre**) qui contient ses vaisseaux sanguins.\n4. Temps = distance / vitesse. Fibre A : 0,90 / 60 = **0,015 s = 15 ms**. Fibre B : 0,90 / 1 = **0,90 s = 900 ms**. La fibre A est 60 fois plus rapide car elle est **myélinisée** : l'influx y **saute d'un nœud de Ranvier à l'autre**, la conduction est plus rapide.\n5. Une **fibre** répond par tout ou rien, avec une amplitude constante ; un **nerf** donne une réponse **graduée**, qui augmente avec l'intensité par recrutement de fibres, jusqu'à un maximum."}$exo$::jsonb),
  ('08f314d7-2cd2-5b3b-863b-8732c7abec7c'::uuid, 1, 'redaction', $exo${"titre":"Du muscle au myofilament","consigne":"Réponds à chaque question avec le vocabulaire du cours.","enonce":"1. Range du plus grand au plus petit : myofibrille, muscle, sarcomère, fibre musculaire, faisceau, myofilaments.\n2. Donne trois caractéristiques de la fibre musculaire striée squelettique.\n3. Définis le **sarcomère**, puis indique ce que contiennent la **bande I**, la **bande A** et la **zone H**.","bareme":[{"critere":"Ordre juste : muscle, faisceau, fibre, myofibrille, sarcomère, myofilaments","points":6},{"critere":"Trois caractéristiques de la fibre (géante et très longue, plusieurs noyaux, sarcolemme, myofibrilles)","points":5},{"critere":"Sarcomère défini et contenu exact des bandes I, A et de la zone H","points":9}],"dureeMin":7,"corrige":"1. **Muscle → faisceau → fibre musculaire → myofibrille → sarcomère → myofilaments.**\n2. La fibre musculaire striée squelettique est une **cellule géante, très longue**, qui possède **plusieurs noyaux** ; sa membrane s'appelle le **sarcolemme** ; elle est remplie de **myofibrilles** qui montrent une alternance de bandes claires et sombres (striation). Elle est aussi riche en mitochondries.\n3. Le **sarcomère** est l'**unité contractile** de la myofibrille, délimitée par deux **stries Z**.\n- La **bande I** (claire) ne contient que des filaments d'**actine** ; elle est coupée en son milieu par la strie Z.\n- La **bande A** (sombre) correspond à toute la longueur des filaments de **myosine**, chevauchés par l'actine.\n- La **zone H**, au centre de la bande A, ne contient que de la **myosine**."}$exo$::jsonb),
  ('08f314d7-2cd2-5b3b-863b-8732c7abec7c'::uuid, 2, 'redaction', $exo${"titre":"Mesurer un sarcomère qui se contracte","consigne":"Calcule, puis interprète chaque résultat à l'aide du cours.","enonce":"**Document – Mesures sur des électronographies d'un même sarcomère**\n\n| Longueur (en µm) | Sarcomère relâché | Sarcomère contracté |\n| Sarcomère (de strie Z à strie Z) | 2,4 | 2,0 |\n| Bande A | 1,6 | 1,6 |\n| Bandes I (les deux demi-bandes du sarcomère) | 0,8 | 0,4 |\n| Zone H | 0,5 | 0,1 |\n\n1. Calcule la variation de longueur du sarcomère, de la bande A, des bandes I et de la zone H.\n2. Quelle zone garde la même longueur ? Qu'en déduis-tu sur la longueur des filaments de myosine ?\n3. Explique le mécanisme qui fait raccourcir le sarcomère sans que les myofilaments raccourcissent.\n4. Quels éléments sont nécessaires à ce mécanisme ? Quel organite fournit l'un d'eux ?","bareme":[{"critere":"Variations justes : sarcomère − 0,4 µm, bande A 0, bandes I − 0,4 µm, zone H − 0,4 µm","points":6},{"critere":"Bande A constante, donc myosine de longueur constante","points":4},{"critere":"Glissement : têtes de myosine accrochées à l'actine qui la tirent vers le centre","points":6},{"critere":"ATP et ions calcium ; ATP produit par les mitochondries","points":4}],"dureeMin":12,"corrige":"1. Variations (contracté − relâché) :\n- sarcomère : 2,0 − 2,4 = **− 0,4 µm** ;\n- bande A : 1,6 − 1,6 = **0** ;\n- bandes I : 0,4 − 0,8 = **− 0,4 µm** ;\n- zone H : 0,1 − 0,5 = **− 0,4 µm**.\n2. La **bande A** garde la même longueur. Or elle correspond à toute la longueur des filaments de myosine : les **filaments de myosine ne raccourcissent pas**.\n3. Les **têtes de myosine** s'accrochent à l'**actine** et la tirent vers le centre du sarcomère : les filaments **glissent** les uns sur les autres sans changer de longueur. L'actine s'enfonce entre les filaments de myosine : la zone H (myosine seule) et les bandes I (actine seule) diminuent, et le sarcomère raccourcit d'autant (0,4 µm dans les trois cas).\n4. Le glissement consomme de l'**ATP** et nécessite des **ions calcium Ca²⁺**, libérés dans la fibre quand elle est excitée. L'ATP est produit par les **mitochondries**, très nombreuses dans la fibre musculaire."}$exo$::jsonb),
  ('08f314d7-2cd2-5b3b-863b-8732c7abec7c'::uuid, 3, 'redaction', $exo${"titre":"Deux substances qui dérèglent la jonction neuromusculaire","consigne":"Utilise le document et le cours pour raisonner étape par étape. Justifie chaque prévision.","enonce":"**Document – Deux substances étudiées en laboratoire** (substances fictives)\n\n> La **substance X** empêche l'acétylcholinestérase d'agir.\n>\n> La **substance Y** se fixe sur les récepteurs à acétylcholine de la fibre musculaire à la place de l'acétylcholine, sans déclencher de réponse.\n\n1. Décris, dans l'ordre, les étapes de la transmission du message du motoneurone à la fibre musculaire au niveau de la jonction neuromusculaire.\n2. Prévois l'effet de la substance Y sur le muscle, et justifie.\n3. Prévois l'effet de la substance X sur le muscle, et justifie.\n4. Une fois la fibre excitée, que faut-il pour que les myofilaments glissent ? Pourquoi la fibre musculaire est-elle riche en mitochondries ?\n5. Explique la phrase : « Le message électrique devient chimique dans la fente, puis redevient électrique sur la fibre. »","bareme":[{"critere":"Les cinq étapes de la transmission dans l'ordre (PA, exocytose d'acétylcholine, fixation, PA musculaire, dégradation)","points":6},{"critere":"Substance Y : pas de PA musculaire, pas de contraction (paralysie), justifié","points":4},{"critere":"Substance X : acétylcholine non dégradée, commande qui ne s'arrête pas, contraction prolongée","points":4},{"critere":"ATP et Ca²⁺ ; mitochondries productrices d'ATP","points":3},{"critere":"Passage électrique → chimique → électrique expliqué","points":3}],"dureeMin":18,"corrige":"1. Étapes :\n1) un **potentiel d'action** arrive à la terminaison de l'axone du motoneurone ;\n2) des vésicules libèrent l'**acétylcholine** dans la fente synaptique (**exocytose**) ;\n3) l'acétylcholine se fixe sur des **récepteurs** de la membrane de la fibre musculaire ;\n4) cette fixation déclenche un **potentiel d'action musculaire**, qui provoque la libération du calcium et la **contraction** ;\n5) l'acétylcholine est rapidement dégradée par l'**acétylcholinestérase** : la commande s'arrête.\n2. Avec Y, les récepteurs sont occupés : l'acétylcholine ne peut plus s'y fixer, et Y ne déclenche pas de réponse. Il n'y a donc **pas de potentiel d'action musculaire**, pas de libération de calcium, **pas de contraction** : le muscle est **paralysé**, même si le motoneurone envoie des messages.\n3. Avec X, l'acétylcholinestérase ne dégrade plus l'acétylcholine : elle reste fixée sur les récepteurs. La **commande ne s'arrête plus** : la fibre continue d'être excitée, la contraction est **prolongée** (le muscle ne se relâche pas).\n4. Le glissement nécessite de l'**ATP** et des ions **calcium Ca²⁺**. La fibre est riche en **mitochondries** car elles produisent l'**ATP** consommé par la contraction.\n5. Le potentiel d'action du motoneurone est un message **électrique** ; dans la fente, il est traduit en libération d'une molécule, l'acétylcholine : le message est **chimique** ; sa fixation sur les récepteurs déclenche un potentiel d'action musculaire : le message redevient **électrique**."}$exo$::jsonb),
  ('b313e368-2157-5371-9192-43b3284d19c4'::uuid, 1, 'redaction', $exo${"titre":"Le vocabulaire des atteintes nerveuses","consigne":"Réponds à chaque question par une ou deux phrases.","enonce":"1. Définis : paraplégie, tétraplégie, aphasie, amnésie, paresthésie.\n2. Quelle est la conséquence d'une lésion de la moelle épinière au niveau **cervical** ? au niveau **lombaire** ? Pourquoi la lésion n'agit-elle que **sous** son niveau ?\n3. Quelle est la différence entre une lésion **complète** et une lésion **incomplète** de la moelle ?","bareme":[{"critere":"Cinq définitions exactes","points":8},{"critere":"Tétraplégie (cervical), paraplégie (lombaire), interruption des voies sous la lésion","points":7},{"critere":"Lésion complète : perte totale ; incomplète : perte partielle, récupération possible","points":5}],"dureeMin":7,"corrige":"1. **Paraplégie** : paralysie des deux membres inférieurs. **Tétraplégie** : paralysie des quatre membres. **Aphasie** : trouble du langage. **Amnésie** : perte de mémoire. **Paresthésie** : sensation anormale (fourmillements, engourdissements).\n2. Une lésion **cervicale** provoque une **tétraplégie** (et, si elle est très haute, touche la respiration). Une lésion **lombaire** (ou thoracique) provoque une **paraplégie**. La moelle conduit les ordres moteurs de l'encéphale vers les muscles et les informations sensitives du corps vers l'encéphale : une lésion **interrompt ces voies** pour tout ce qui se trouve **sous** elle, alors que ce qui est au-dessus reste relié à l'encéphale.\n3. Une lésion **complète** entraîne la **perte totale** de la motricité et de la sensibilité sous la lésion. Une lésion **incomplète** entraîne une **perte partielle**, avec une **récupération possible**."}$exo$::jsonb),
  ('b313e368-2157-5371-9192-43b3284d19c4'::uuid, 2, 'redaction', $exo${"titre":"L'accident de moto de Thomas","consigne":"Lis le document, puis réponds en justifiant par des éléments du dossier et du cours.","enonce":"**Document – Dossier de Thomas, 19 ans**\n\n> Thomas a chuté à moto. Les secours l'ont immobilisé sur place avant de le transporter. À l'hôpital, il ne peut plus bouger les jambes et ne sent plus rien sous le nombril : ni le toucher, ni la douleur. Ses bras fonctionnent normalement. Il présente aussi des troubles urinaires. Un scanner montre une fracture d'une vertèbre **thoracique** ; une IRM montre une lésion de la moelle à ce niveau.\n\n1. Nomme le trouble moteur de Thomas et justifie par le niveau de la lésion.\n2. La lésion est-elle complète ou incomplète ? Justifie avec le document.\n3. Qu'apportent respectivement le scanner et l'IRM ? Sont-ce des signes cliniques ou paracliniques ?\n4. Pourquoi les secours ont-ils eu raison d'immobiliser Thomas ? Décris la suite de sa prise en charge et cite deux autres facteurs de risque de ce type de lésion.","bareme":[{"critere":"Paraplégie, justifiée par une lésion thoracique qui épargne les membres supérieurs","points":5},{"critere":"Lésion complète justifiée : ni motricité ni sensibilité sous la lésion","points":4},{"critere":"Scanner : fracture vertébrale ; IRM : moelle et lésion ; signes paracliniques","points":5},{"critere":"Immobilisation du rachis, chirurgie, rééducation ; deux facteurs de risque","points":6}],"dureeMin":11,"corrige":"1. Thomas présente une **paraplégie** : paralysie des deux membres inférieurs. La lésion est au niveau **thoracique**, sous les segments qui commandent les bras : les bras fonctionnent, seules les voies vers les membres inférieurs sont interrompues.\n2. La lésion semble **complète** : sous la lésion, il n'a plus aucune **motricité** (jambes immobiles) ni aucune **sensibilité** (ni toucher ni douleur). Une lésion incomplète laisserait une perte seulement partielle.\n3. Le **scanner** montre les **fractures vertébrales** ; l'**IRM** montre la **moelle** et la **lésion**. Ce sont des **signes paracliniques** (résultats d'examens complémentaires), alors que la paralysie et la perte de sensibilité sont des signes cliniques.\n4. Déplacer une victime suspecte de lésion de la moelle peut aggraver la lésion : il faut **immobiliser le rachis dès le ramassage**. La suite : **chirurgie de stabilisation**, puis **rééducation longue**. Autres facteurs de risque (deux parmi) : chutes, plongeons en eau peu profonde, sports à risque, autres accidents de la route."}$exo$::jsonb),
  ('b313e368-2157-5371-9192-43b3284d19c4'::uuid, 3, 'redaction', $exo${"titre":"L'AVC de Mme Leroy","consigne":"Construis un raisonnement complet à partir du document : signes, mécanisme, traitement, facteurs de risque.","enonce":"**Document – Mme Leroy, 68 ans, droitière**\n\n> Ce matin, pendant le petit-déjeuner, Mme Leroy a soudain laissé tomber sa tasse : son **bras droit** retombait, le **côté droit de son visage** était paralysé et elle **n'arrivait plus à trouver ses mots**. Son mari a appelé le 15. Elle est hypertendue depuis dix ans, fume depuis sa jeunesse et a un diabète.\n>\n> À l'hôpital, une **IRM cérébrale** réalisée en urgence montre qu'une artère de l'**hémisphère gauche** est **bouchée par un caillot**.\n\n1. Relève les signes cliniques et le signe paraclinique. Nomme le trouble du langage.\n2. De quel type d'AVC s'agit-il ? Justifie et indique sa fréquence parmi les AVC.\n3. Explique pourquoi une lésion de l'hémisphère **gauche** provoque des troubles du côté **droit** et un trouble du langage.\n4. Pourquoi le mari a-t-il eu raison d'appeler le 15 immédiatement ? Quels traitements peut-on proposer et à quelle condition ?\n5. Relève les facteurs de risque de Mme Leroy et indique lequel est considéré comme le premier.","bareme":[{"critere":"Signes cliniques (bras, visage, parole) et paraclinique (IRM) distingués ; aphasie nommée","points":4},{"critere":"AVC ischémique justifié par le caillot, environ 80 % des AVC","points":3},{"critere":"Commande croisée : hémiplégie droite ; langage dépendant de l'hémisphère gauche chez la plupart des droitiers","points":6},{"critere":"Urgence : neurones privés d'O₂ qui meurent en minutes ; thrombolyse ou thrombectomie dans les premières heures","points":4},{"critere":"Trois facteurs de risque relevés, hypertension artérielle identifiée comme le premier","points":3}],"dureeMin":18,"corrige":"1. **Signes cliniques** : bras droit qui retombe, paralysie du côté droit du visage, difficulté à trouver ses mots. **Signe paraclinique** : l'IRM cérébrale montrant une artère de l'hémisphère gauche bouchée par un caillot. Le trouble du langage est une **aphasie**.\n2. C'est un **AVC ischémique** (infarctus cérébral) : l'artère est **bouchée** par un caillot, et non rompue. C'est le type le plus fréquent, environ **80 %** des AVC.\n3. Chaque hémisphère commande la **moitié opposée** du corps : une lésion de l'hémisphère gauche provoque une **hémiplégie droite** (bras et visage à droite). Chez la plupart des **droitiers**, comme Mme Leroy, le **langage dépend de l'hémisphère gauche** : son atteinte provoque une **aphasie**.\n4. Un AVC est l'arrêt brutal de la circulation dans une partie de l'encéphale : les **neurones privés de dioxygène meurent en quelques minutes**. Chaque minute compte. On peut **dissoudre le caillot (thrombolyse)** ou **le retirer (thrombectomie)**, mais seulement dans les **toutes premières heures**, après l'imagerie qui a confirmé l'AVC ischémique.\n5. Facteurs de risque : **hypertension artérielle**, **tabac**, **diabète**, et l'**âge**. Le premier facteur de risque de l'AVC est l'**hypertension artérielle**."}$exo$::jsonb),
  ('08d37f26-a2e2-5153-abf2-a5073a2c98dc'::uuid, 1, 'redaction', $exo${"titre":"Aliments et nutriments","consigne":"Réponds à chaque question avec le vocabulaire du cours.","enonce":"1. Quelle différence y a-t-il entre un **aliment** et un **nutriment** ? Donne un exemple de chacun.\n2. Classe en monomère, dimère ou polymère : amidon, glucose, saccharose, protéine, acide aminé, lactose. Lesquels peuvent traverser la paroi intestinale sans digestion ?\n3. Donne les trois rôles des nutriments et, pour chacun, un exemple de nutriment qui le remplit.","bareme":[{"critere":"Distinction aliment / nutriment avec exemples","points":5},{"critere":"Classement juste des six molécules et monomères seuls absorbés","points":8},{"critere":"Rôles énergétique, structural, fonctionnel avec un exemple juste chacun","points":7}],"dureeMin":8,"corrige":"1. Un **aliment** est une denrée consommée (pain, lait, pomme). Un **nutriment** est une molécule directement utilisable par l'organisme, obtenue après digestion ou absorbée telle quelle (glucose, acides aminés, eau, ions).\n2. **Monomères** : glucose, acide aminé. **Dimères** : saccharose, lactose. **Polymères** : amidon, protéine. Seuls les **monomères** (glucose, acide aminé) traversent la paroi intestinale sans digestion — comme l'eau, les ions et les vitamines ; les dimères et les polymères doivent être digérés.\n3. Rôle **énergétique** : glucides et lipides (protides en appoint). Rôle **structural** (construction) : protéines, lipides des membranes, calcium et phosphore des os. Rôle **fonctionnel** (régulation) : vitamines, oligo-éléments (fer, iode, zinc), certaines protéines (enzymes, hormones)."}$exo$::jsonb),
  ('08d37f26-a2e2-5153-abf2-a5073a2c98dc'::uuid, 2, 'redaction', $exo${"titre":"Calculer et interpréter l'IMC","consigne":"Détaille chaque calcul (arrondi au dixième) et interprète le résultat avec le tableau du cours.","enonce":"**Document – Trois personnes**\n\n| | Âge | Taille | Masse |\n| Karim | 32 ans | 1,70 m | 78 kg |\n| Emma | 25 ans | 1,60 m | 45 kg |\n| Tom | 14 ans | 1,65 m | 60 kg |\n\n1. Calcule l'IMC de Karim et interprète-le.\n2. Calcule l'IMC d'Emma et interprète-le.\n3. Peut-on interpréter l'IMC de Tom avec le même tableau ? Justifie.\n4. Karim mange davantage qu'il ne dépense depuis plusieurs années. Explique, avec la notion de bilan énergétique, l'évolution de sa masse. Cite trois postes de dépenses énergétiques.","bareme":[{"critere":"IMC de Karim ≈ 27,0 calculé et classé en surpoids","points":6},{"critere":"IMC d'Emma ≈ 17,6 calculé et classé en maigreur","points":5},{"critere":"Tom : interprétation sur les courbes de corpulence selon l'âge et le sexe","points":4},{"critere":"Bilan énergétique positif et durable → prise de poids ; trois dépenses citées","points":5}],"dureeMin":12,"corrige":"1. IMC = masse / taille². Karim : 1,70 × 1,70 = 2,89 ; 78 / 2,89 ≈ **27,0**. Entre 25 et moins de 30 : **surpoids**.\n2. Emma : 1,60 × 1,60 = 2,56 ; 45 / 2,56 ≈ **17,6**. Moins de 18,5 : **maigreur**.\n3. Non. Tom a 14 ans : chez l'enfant et l'adolescent, l'IMC s'interprète sur des **courbes de corpulence** selon l'**âge** et le **sexe**, pas avec les seuils de l'adulte.\n4. Le **bilan énergétique** compare les **apports** (ce qui est mangé) aux **dépenses**. Chez Karim, les apports dépassent les dépenses depuis longtemps : le bilan est **positif et durable**, ce qui entraîne une **prise de poids**. Dépenses : le **métabolisme de base**, l'**activité physique**, la **thermorégulation**."}$exo$::jsonb),
  ('08d37f26-a2e2-5153-abf2-a5073a2c98dc'::uuid, 3, 'redaction', $exo${"titre":"Des besoins qui varient d'une personne à l'autre","consigne":"Exploite les documents et justifie chaque réponse par une donnée et une connaissance du cours.","enonce":"**Document 1 – Trois personnes suivies par une diététicienne**\n\n> **Léa**, 16 ans, nageuse, s'entraîne dix heures par semaine et grandit encore. **M. Morel**, 75 ans, est sédentaire. **Sophie**, 30 ans, est enceinte.\n\n**Document 2 – Répartition des apports énergétiques de Léa sur une semaine**\n\n| Glucides | Lipides | Protéines |\n| 38 % | 47 % | 15 % |\n\n**Document 3.** Léa boit environ 1 L d'eau par jour. On perd chaque jour au moins 2 L d'eau, qu'il faut remplacer.\n\n1. Distingue besoins **quantitatifs** et besoins **qualitatifs** ; donne deux exemples de besoins qualitatifs.\n2. Explique pourquoi Léa, M. Morel et Sophie n'ont pas les mêmes besoins. Cite les facteurs en jeu pour chacun.\n3. Compare la répartition des apports de Léa aux repères du cours pour un adulte et propose une correction.\n4. Donne quatre rôles de l'eau dans l'organisme et explique pourquoi l'apport en eau de Léa doit être surveillé.\n5. Pourquoi Léa, qui grandit, doit-elle avoir des apports suffisants en protéines ?","bareme":[{"critere":"Besoins quantitatifs (énergie) et qualitatifs (acides aminés et acides gras indispensables, vitamines, minéraux)","points":4},{"critere":"Facteurs de variation justes pour chacun (âge, croissance, activité, grossesse)","points":4},{"critere":"Glucides sous 40–55 %, lipides au-dessus de 35–40 %, protéines dans 10–20 %, correction proposée","points":5},{"critere":"Rôles de l'eau et écart entre 1 L bu et au moins 2 L perdus","points":4},{"critere":"Rôle structural des protéines relié à la croissance","points":3}],"dureeMin":18,"corrige":"1. Les besoins **quantitatifs** portent sur la quantité d'**énergie** ; les besoins **qualitatifs** portent sur des **nutriments précis** : acides aminés **indispensables**, acides gras **indispensables**, **vitamines**, **minéraux** (deux exemples suffisent).\n2. Les besoins varient selon l'**âge**, le **sexe**, l'**activité physique**, la **croissance**, la **grossesse** ou l'allaitement, le climat. **Léa** : adolescente en **croissance** et très **active** (dix heures de natation), elle a des besoins élevés. **M. Morel** : **âgé** et **sédentaire**, ses dépenses sont faibles. **Sophie** : la **grossesse** augmente ses besoins.\n3. Repères pour un adulte : glucides 40 à 55 %, lipides 35 à 40 %, protéines 10 à 20 %. Chez Léa, les **glucides (38 %) sont un peu insuffisants**, les **lipides (47 %) sont en excès**, les **protéines (15 %) sont correctes**. Il faut réduire les aliments gras et augmenter la part des glucides (pain, féculents).\n4. L'eau représente environ 60 % de la masse du corps adulte ; elle est **solvant**, **milieu des réactions**, moyen de **transport**, et participe à la **régulation de la température**. Léa ne boit qu'environ **1 L** par jour alors qu'on en perd **au moins 2 L** : ses boissons ne couvrent qu'environ la moitié de ces pertes, et son activité sportive rend la surveillance encore plus importante.\n5. Les protéines ont un rôle **structural** (construction) : pendant la **croissance**, l'organisme fabrique de nouveaux tissus et a besoin d'acides aminés, dont certains sont **indispensables**."}$exo$::jsonb),
  ('959b38be-a7b5-572a-83d1-df70f9e37c35'::uuid, 1, 'redaction', $exo${"titre":"Deux formes de malnutrition","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Qu'est-ce que la **malnutrition** ? Pourquoi l'obésité et la carence en sont-elles deux formes opposées ?\n2. Distingue une carence **quantitative** et une carence **qualitative**, avec un exemple de chacune.\n3. Définis : cachexie, polyphagie, anorexie.","bareme":[{"critere":"Malnutrition = déséquilibre apports / besoins ; obésité par excès, carence par défaut","points":6},{"critere":"Carences quantitative et qualitative définies avec un exemple juste","points":8},{"critere":"Trois définitions exactes","points":6}],"dureeMin":7,"corrige":"1. La **malnutrition** est tout **déséquilibre entre les apports et les besoins**, pas seulement le manque de nourriture. L'**obésité** est une malnutrition **par excès** (excès de masse grasse) ; la **carence** est une malnutrition **par défaut** (apport insuffisant d'un ou plusieurs nutriments).\n2. Une carence **quantitative** est un **apport global insuffisant** : famine, anorexie mentale, qui mènent à l'amaigrissement jusqu'à la cachexie. Une carence **qualitative** est un apport **suffisant en énergie mais pauvre en un nutriment précis** : carence en fer, en vitamine C (scorbut) ou en vitamine D (rachitisme).\n3. **Cachexie** : amaigrissement extrême avec fonte des muscles. **Polyphagie** : faim excessive, besoin de manger en grande quantité. **Anorexie** : perte ou refus de l'appétit."}$exo$::jsonb),
  ('959b38be-a7b5-572a-83d1-df70f9e37c35'::uuid, 2, 'redaction', $exo${"titre":"Chloé est toujours fatiguée","consigne":"Analyse le dossier et justifie chaque réponse par une donnée du document.","enonce":"**Document – Dossier de Chloé, 17 ans**\n\n> Chloé se plaint d'une grande fatigue depuis plusieurs mois. Elle est essoufflée en montant les escaliers et son entourage la trouve pâle. Elle a des règles abondantes. Elle ne mange ni viande ni poisson, et très rarement des légumineuses.\n\n| Bilan sanguin | Résultat de Chloé | Valeurs de référence du laboratoire |\n| Hémoglobine | 10,2 g/dL | 12 à 16 g/dL |\n| Ferritine | 6 µg/L | 15 à 150 µg/L |\n\n1. Classe les éléments du dossier en signes cliniques et signes paracliniques.\n2. Interprète les deux résultats du bilan sanguin.\n3. Explique le lien entre le manque de fer, l'hémoglobine et les signes de Chloé.\n4. Relève les facteurs de risque de Chloé et propose un traitement, avec un conseil alimentaire justifié.","bareme":[{"critere":"Signes cliniques (fatigue, essoufflement, pâleur) et paracliniques (hémoglobine, ferritine) bien classés","points":4},{"critere":"Hémoglobine basse et ferritine basse (réserves vides) interprétées avec les valeurs","points":5},{"critere":"Fer → hémoglobine → transport de l'O₂ → fatigue, pâleur, essoufflement","points":5},{"critere":"Deux facteurs de risque ; supplémentation, alimentation riche en fer, vitamine C","points":6}],"dureeMin":12,"corrige":"1. **Signes cliniques** : fatigue, essoufflement à l'effort, pâleur. **Signes paracliniques** : hémoglobine et ferritine du bilan sanguin.\n2. L'**hémoglobine** de Chloé (10,2 g/dL) est **basse** : inférieure à 12 g/dL, seuil chez la femme. C'est une **anémie**. La **ferritine** (6 µg/L) est **basse**, sous 15 µg/L : ses **réserves de fer sont vides**. Il s'agit d'une anémie par **carence en fer**.\n3. Le **fer** est indispensable à la fabrication de l'**hémoglobine**, qui **transporte le dioxygène** dans les globules rouges. Sans fer, moins d'hémoglobine, donc moins de dioxygène transporté vers les muscles et les organes : **fatigue**, **essoufflement à l'effort** ; le sang moins riche en hémoglobine donne une **pâleur**.\n4. Facteurs de risque : **règles abondantes**, **alimentation pauvre en fer** (ni viande, ni poisson, peu de légumineuses), et l'adolescence (croissance). Traitement : **supplémentation en fer**, **alimentation riche en fer** (légumineuses, et viande ou poisson si elle le souhaite), recherche et traitement de la cause. Conseil : consommer un **agrume** ou un aliment riche en **vitamine C** au repas, car la vitamine C **favorise l'absorption du fer d'origine végétale**."}$exo$::jsonb),
  ('959b38be-a7b5-572a-83d1-df70f9e37c35'::uuid, 3, 'redaction', $exo${"titre":"La prise en charge de M. Garnier","consigne":"Exploite le document pour construire un raisonnement complet : diagnostic, facteurs de risque, conséquences, traitements.","enonce":"**Document – Dossier de M. Garnier, 45 ans**\n\n> Taille : 1,80 m. Masse : 110 kg. Il travaille assis toute la journée, se déplace en voiture, dort peu, grignote devant les écrans et boit environ 2 L de soda par jour. Son père était obèse.\n>\n> Le médecin a diagnostiqué une **hypertension artérielle** et un **diabète de type 2**. Sa femme se plaint qu'il ronfle et s'arrête de respirer pendant son sommeil. Il a mal aux genoux et avoue avoir honte de son corps.\n\n1. Calcule l'IMC de M. Garnier (arrondi au dixième) et conclus.\n2. Relève ses facteurs de risque et classe-les en comportementaux, biologiques, sociaux et environnementaux.\n3. Relève dans le dossier les conséquences pathologiques de l'obésité et nomme-les.\n4. Propose une prise en charge en justifiant chaque mesure. Pourquoi est-elle pluridisciplinaire ? Cite les professionnels concernés.","bareme":[{"critere":"IMC ≈ 34,0 calculé ; obésité (30 et plus)","points":4},{"critere":"Facteurs de risque relevés et correctement classés","points":5},{"critere":"Conséquences relevées : HTA, diabète de type 2, apnée du sommeil, arthrose du genou, souffrance psychologique","points":5},{"critere":"Prise en charge justifiée (alimentation, activité, accompagnement) et équipe pluridisciplinaire","points":6}],"dureeMin":18,"corrige":"1. 1,80 × 1,80 = 3,24 ; 110 / 3,24 ≈ **34,0**. L'IMC est **supérieur à 30** : M. Garnier est **obèse**.\n2. Facteurs **comportementaux** : sédentarité (travail assis, voiture), grignotage, boissons sucrées (2 L de soda), manque de sommeil. Facteur **biologique** : prédisposition génétique (père obèse). Facteurs **sociaux et environnementaux** : le mode de vie devant les écrans et l'offre alimentaire peuvent être cités ; le dossier ne mentionne ni précarité ni publicité.\n3. Conséquences : **hypertension artérielle**, **diabète de type 2**, **apnée du sommeil** (arrêts de la respiration pendant le sommeil), **arthrose** du genou probable (douleurs aux genoux), **souffrance psychologique** (honte de son corps). Il est aussi exposé aux maladies cardio-vasculaires (athérosclérose).\n4. Prise en charge :\n- **rééquilibrer l'alimentation** sans régime draconien : supprimer le soda, limiter le grignotage et les aliments trop gras et sucrés, pour rendre le bilan énergétique moins positif ;\n- **augmenter l'activité physique** et réduire le temps assis, pour augmenter les dépenses ;\n- **accompagnement psychologique** et **éducation thérapeutique**, pour tenir dans la durée et répondre à la souffrance ;\n- traitements médicamenteux ou **chirurgie bariatrique** seulement dans les obésités sévères, sous conditions strictes.\nLa prise en charge est **longue et pluridisciplinaire** car l'obésité a des causes multiples : **médecin**, **diététicien**, **éducateur sportif**, **psychologue**."}$exo$::jsonb),
  ('734017e7-7d24-5609-836b-fdccc5f842a9'::uuid, 1, 'redaction', $exo${"titre":"L'organisation de l'appareil digestif","consigne":"Réponds à chaque question avec le vocabulaire du cours.","enonce":"1. Donne, dans l'ordre, les organes traversés par les aliments de la bouche à l'anus. Précise les trois parties de l'intestin grêle.\n2. Cite les glandes annexes du tube digestif. Qu'est-ce qui les distingue des organes du tube digestif ?\n3. Nomme les quatre tuniques de la paroi du tube digestif, de l'intérieur vers l'extérieur, et donne le rôle ou la composition de chacune.","bareme":[{"critere":"Ordre juste du tube digestif, avec duodénum, jéjunum, iléon","points":6},{"critere":"Glandes salivaires, foie, pancréas ; non traversées par les aliments","points":6},{"critere":"Muqueuse, sous-muqueuse, musculeuse, séreuse dans l'ordre, avec leur rôle","points":8}],"dureeMin":7,"corrige":"1. **Bouche → pharynx → œsophage → estomac → intestin grêle → gros intestin (côlon, rectum) → anus.** L'intestin grêle comprend le **duodénum**, le **jéjunum** et l'**iléon**.\n2. Les glandes annexes sont les **glandes salivaires**, le **foie** (qui produit la bile, stockée dans la vésicule biliaire) et le **pancréas**. Elles déversent leurs sécrétions dans le tube digestif **sans être traversées par les aliments**.\n3. De l'intérieur vers l'extérieur :\n- **muqueuse** : épithélium au contact des aliments (sécrétion, absorption), sur un conjonctif ;\n- **sous-muqueuse** : conjonctif riche en vaisseaux et en nerfs ;\n- **musculeuse** : muscles lisses qui assurent le brassage et la progression des aliments ;\n- **séreuse** : enveloppe externe (le péritoine)."}$exo$::jsonb),
  ('734017e7-7d24-5609-836b-fdccc5f842a9'::uuid, 2, 'redaction', $exo${"titre":"Le voyage d'une tartine de pain beurré","consigne":"Suis la tartine dans le tube digestif et réponds en utilisant le vocabulaire du cours.","enonce":"**Situation.** Au petit-déjeuner, Malik mange une tartine de pain beurré avec une tranche de jambon. Le pain apporte surtout de l'**amidon**, le beurre des **triglycérides**, le jambon des **protéines**.\n\n1. Cite les phénomènes mécaniques que subit ce repas et explique en quoi ils facilitent la digestion chimique.\n2. Pour chacun des trois nutriments, indique les enzymes qui agissent, leur lieu d'action et les produits obtenus, jusqu'aux produits finaux.\n3. La bile est-elle une enzyme ? Explique son rôle dans la digestion du beurre.\n4. Qu'est-ce qu'une enzyme digestive ? Donne ses trois caractéristiques.","bareme":[{"critere":"Mastication, déglutition, brassage, péristaltisme ; augmentation de la surface offerte aux enzymes","points":4},{"critere":"Amidon : amylases → maltose → maltase → glucose, avec les lieux","points":4},{"critere":"Protéines : pepsine, trypsine, peptidases → acides aminés ; triglycérides : lipase → acides gras + monoglycérides","points":6},{"critere":"Bile non enzymatique, émulsion des graisses ; enzyme = protéine spécifique, T et pH optimaux","points":6}],"dureeMin":12,"corrige":"1. **Mastication** par les dents, **déglutition**, **brassage** par l'estomac et **péristaltisme** (contractions en vague qui font progresser le bol). Ils **fragmentent** les aliments et **augmentent la surface** offerte aux enzymes.\n2. **Amidon** : dans la bouche, l'**amylase salivaire** le transforme en **maltose** ; dans l'intestin grêle, l'**amylase pancréatique** poursuit (amidon → maltose), puis la **maltase** de la bordure des entérocytes donne du **glucose**.\n**Protéines** : dans l'estomac (pH ≈ 2), la **pepsine** les coupe en **peptides** ; dans l'intestin grêle, la **trypsine** (suc pancréatique) donne de petits peptides, puis les **peptidases** de la bordure des entérocytes libèrent les **acides aminés**.\n**Triglycérides** : dans l'intestin grêle, la **lipase** pancréatique les transforme en **acides gras** et **monoglycérides**.\n3. Non, la **bile n'est pas une enzyme**. Produite par le foie, ses sels **émulsionnent** les graisses du beurre en fines gouttelettes, ce qui **augmente la surface d'action de la lipase**.\n4. Une enzyme digestive est une **protéine** qui **hydrolyse** un substrat précis : elle est **spécifique** de son substrat, agit à une **température optimale** (37 °C) et à un **pH optimal**."}$exo$::jsonb),
  ('734017e7-7d24-5609-836b-fdccc5f842a9'::uuid, 3, 'redaction', $exo${"titre":"Des enzymes en tubes à essai","consigne":"Analyse chaque résultat, puis dégage les propriétés des enzymes digestives. Justifie avec les données.","enonce":"**Document – Expériences de digestion in vitro** (durée : 30 minutes)\n\n| Tube | Contenu | Température | pH | Résultat |\n| 1 | Amidon + amylase | 37 °C | 7 | Maltose présent, amidon disparu |\n| 2 | Amidon + amylase | 37 °C | 2 | Amidon intact, pas de maltose |\n| 3 | Protéines + amylase | 37 °C | 7 | Protéines intactes |\n| 4 | Protéines + pepsine | 37 °C | 2 | Peptides présents |\n| 5 | Amidon + amylase | 5 °C | 7 | Très peu de maltose |\n| 6 | Amidon seul | 37 °C | 7 | Amidon intact |\n\n1. À quoi sert le tube 6 ? Compare-le au tube 1 et conclus.\n2. Quelle propriété de l'amylase les tubes 1 et 3 montrent-ils ?\n3. Quelle propriété les tubes 1, 2 et 4 montrent-ils ? Relie le résultat du tube 4 au milieu de l'estomac.\n4. Quelle propriété les tubes 1 et 5 montrent-ils ?\n5. Dans le corps, la mastication et la bile augmentent l'efficacité des enzymes. Explique pourquoi.\n6. Certaines fibres du pain ne sont digérées par aucune de nos enzymes. Que deviennent-elles, et quels autres rôles joue ce qui les transforme ?","bareme":[{"critere":"Tube 6 = témoin : sans enzyme, pas d'hydrolyse ; l'amylase hydrolyse l'amidon en maltose","points":4},{"critere":"Spécificité de substrat (tubes 1 et 3)","points":3},{"critere":"pH optimal : amylase active à pH 7, pas à pH 2 ; pepsine active à pH 2 comme dans l'estomac","points":4},{"critere":"Température optimale (37 °C) déduite des tubes 1 et 5","points":3},{"critere":"Surface augmentée par mastication et émulsion ; fibres fermentées par le microbiote et ses autres rôles","points":6}],"dureeMin":20,"corrige":"1. Le tube 6 est le **témoin** : sans enzyme, l'amidon reste intact. Dans le tube 1, avec l'amylase, l'amidon a disparu et du maltose est apparu : c'est bien l'**amylase qui hydrolyse l'amidon en maltose**.\n2. Tubes 1 et 3 : l'amylase hydrolyse l'amidon mais laisse les protéines intactes. Elle est **spécifique** de son substrat.\n3. Tubes 1 et 2 : l'amylase agit à pH 7 mais pas à pH 2. Tube 4 : la pepsine agit à pH 2. Chaque enzyme a un **pH optimal**. La pepsine agit dans l'**estomac**, dont le pH est d'environ 2 : son pH optimal correspond à son milieu d'action.\n4. Tubes 1 et 5 : à 5 °C, l'amylase ne produit que très peu de maltose, alors qu'à 37 °C l'amidon est entièrement hydrolysé. L'enzyme a une **température optimale**, 37 °C, celle du corps.\n5. La **mastication** fragmente les aliments ; la **bile** émulsionne les graisses en fines gouttelettes. Dans les deux cas, la **surface offerte aux enzymes augmente** : les enzymes agissent plus vite et plus complètement.\n6. Les fibres arrivent dans le côlon, où le **microbiote intestinal** (des milliards de bactéries) les **fermente**. Le microbiote produit aussi certaines **vitamines (K, B)**, participe à la **défense contre les microbes pathogènes** et à la **maturation de l'immunité**."}$exo$::jsonb),
  ('de7f6cd7-d785-5092-8ca2-b810b3237f5f'::uuid, 1, 'redaction', $exo${"titre":"Deux voies pour quitter l'intestin","consigne":"Réponds à chaque question avec le vocabulaire du cours.","enonce":"1. Nomme les trois structures qui augmentent la surface de la muqueuse de l'intestin grêle, de la plus grande à la plus petite, et décris-les. Que contient une villosité ?\n2. Classe ces nutriments selon leur voie d'absorption, sanguine ou lymphatique : glucose, acides aminés, vitamine D, acides gras longs, vitamine C, ions. Justifie par leur nature.\n3. Comment l'eau est-elle absorbée ?","bareme":[{"critere":"Valvules conniventes, villosités, microvillosités décrites ; capillaires et chylifère dans la villosité","points":7},{"critere":"Classement juste des six nutriments, justifié par hydrophile / hydrophobe","points":9},{"critere":"Absorption de l'eau par osmose, en suivant nutriments et ions","points":4}],"dureeMin":8,"corrige":"1. Les **valvules conniventes** sont des replis visibles à l'œil nu ; les **villosités** sont des replis de la muqueuse d'environ 1 mm ; les **microvillosités** sont des replis de la membrane des entérocytes (bordure en brosse), qui portent des enzymes. Chaque villosité contient un réseau de **capillaires sanguins** et un vaisseau lymphatique central, le **chylifère**.\n2. Voie **sanguine** (capillaires puis veine porte vers le foie) : **glucose**, **acides aminés**, **vitamine C**, **ions** — molécules **hydrophiles**, solubles dans le plasma. Voie **lymphatique** (chylifère) : **acides gras longs** (reconstitués en triglycérides et emballés dans des chylomicrons) et **vitamine D** (liposoluble) — molécules **hydrophobes**, qui ne voyagent pas librement dans le sang.\n3. L'eau est absorbée par **osmose** : elle suit les nutriments et les ions absorbés, du milieu le moins concentré vers le plus concentré ; surtout dans l'intestin grêle, le reste dans le côlon."}$exo$::jsonb),
  ('de7f6cd7-d785-5092-8ca2-b810b3237f5f'::uuid, 2, 'redaction', $exo${"titre":"Deux fibroscopies prescrites","consigne":"Lis la situation, puis réponds en utilisant le vocabulaire médical du cours.","enonce":"**Situation.** Le docteur Morin reçoit deux patients.\n\n> **Mme Benali**, 58 ans, a présenté une **hématémèse**. Le médecin soupçonne un **ulcère** de l'estomac.\n>\n> **M. Chevalier**, 62 ans, a des **rectorragies**. Le médecin veut rechercher un **polype** du côlon.\n\n1. Définis hématémèse, rectorragie, ulcère et polype.\n2. Quel examen le médecin prescrit-il à chacun ? Décris son principe et la voie d'introduction.\n3. Cite trois intérêts de ces examens, dont un geste possible pour chacun des deux patients.\n4. Quels sont les risques de ces examens ? Sont-ils fréquents ?","bareme":[{"critere":"Quatre définitions exactes","points":4},{"critere":"Fibroscopie œso-gastro-duodénale par la bouche et coloscopie par l'anus, principe décrit","points":7},{"critere":"Intérêts : voir la muqueuse, biopsie, retirer un polype, arrêter un saignement","points":6},{"critere":"Risques rares : perforation, saignement, infection, anesthésie","points":3}],"dureeMin":11,"corrige":"1. **Hématémèse** : vomissement de sang. **Rectorragie** : saignement par l'anus. **Ulcère** : perte de substance de la muqueuse. **Polype** : excroissance de la muqueuse.\n2. La **fibroscopie** (endoscopie) consiste à introduire dans le tube digestif un **tube souple** muni d'une **caméra** et d'une **source lumineuse**. Mme Benali : **fibroscopie œso-gastro-duodénale**, introduite **par la bouche**, pour voir l'œsophage, l'estomac et le duodénum. M. Chevalier : **coloscopie**, introduite **par l'anus**, pour voir le côlon.\n3. Intérêts : **voir directement la muqueuse** (ulcère, inflammation, polype, tumeur) ; faire des **biopsies** ; parfois **traiter**. Pour Mme Benali, le médecin peut **arrêter le saignement** de l'ulcère ; pour M. Chevalier, il peut **retirer le polype**.\n4. Les risques sont **rares** : perforation, saignement, infection, complications de l'anesthésie."}$exo$::jsonb),
  ('de7f6cd7-d785-5092-8ca2-b810b3237f5f'::uuid, 3, 'redaction', $exo${"titre":"Jules, la maladie cœliaque et les villosités","consigne":"Exploite les documents pour expliquer la maladie, de sa cause à son traitement. Justifie chaque étape.","enonce":"**Document 1 – Dossier de Jules, 8 ans**\n\n> Diarrhée depuis plusieurs mois, ventre ballonné, fatigue. Sur sa courbe de croissance, sa taille et son poids stagnent depuis un an.\n\n**Document 2 – Examens**\n\n> Anticorps spécifiques de la maladie cœliaque : présents. Biopsie du duodénum prélevée par fibroscopie : les villosités ont presque disparu.\n>\n> Hémoglobine : 10,5 g/dL (valeurs de référence du laboratoire pour son âge : 11,5 à 15,5 g/dL).\n\n**Document 3 – Surface de la muqueuse**\n\n> Grâce à ses replis, la surface d'absorption d'un intestin grêle sain est immense. Dans une atrophie villositaire totale, elle est considérablement réduite.\n\n1. Classe les éléments des documents 1 et 2 en signes cliniques et signes paracliniques.\n2. Explique en quoi la structure d'une villosité saine est adaptée à l'absorption.\n3. Explique le mécanisme de la maladie, du gluten jusqu'à la diarrhée et au retard de croissance.\n4. Interprète le taux d'hémoglobine de Jules et explique son origine.\n5. Quel est le traitement ? Justifie-le par le mécanisme, et indique ce qu'on peut en attendre.","bareme":[{"critere":"Signes cliniques et paracliniques bien classés","points":3},{"critere":"Villosité : grande surface, paroi fine, capillaires et chylifère","points":4},{"critere":"Gluten → réaction immunitaire → atrophie → surface réduite → nutriments non absorbés → diarrhée, carences, retard de croissance","points":5},{"critere":"Hémoglobine basse (anémie) par malabsorption du fer","points":3},{"critere":"Régime strict sans gluten à vie, justifié ; repousse des villosités","points":5}],"dureeMin":20,"corrige":"1. **Signes cliniques** : diarrhée chronique, ballonnements, fatigue, stagnation de la taille et du poids (retard de croissance). **Signes paracliniques** : anticorps spécifiques présents, biopsie montrant l'atrophie des villosités, hémoglobine basse.\n2. Une villosité est un repli d'environ 1 mm qui **augmente la surface** d'échange, recouverte d'entérocytes à **microvillosités** (encore plus de surface). Sa paroi est **très fine** (un seul épithélium) et elle contient un riche réseau de **capillaires sanguins** et un **chylifère** : les nutriments passent vite et sont emportés.\n3. Chez des personnes prédisposées, le **gluten** (protéine du blé, de l'orge, du seigle) déclenche une **réaction immunitaire** qui **détruit les villosités** : c'est l'**atrophie villositaire**. Moins de villosités → **surface d'absorption effondrée** (document 3) → les **nutriments ne sont plus absorbés** : ils restent dans l'intestin et provoquent la **diarrhée** ; l'organisme manque de nutriments, d'où **carences**, fatigue et, chez l'enfant, **retard de croissance**.\n4. L'hémoglobine de Jules (10,5 g/dL) est **inférieure** aux valeurs de référence (11,5 g/dL au minimum) : il a une **anémie**. Le **fer** est mal absorbé à cause de la malabsorption ; or il est nécessaire à la fabrication de l'hémoglobine.\n5. Traitement : un **régime strict sans gluten, à vie**. Il supprime la cause de la réaction immunitaire, donc la destruction des villosités s'arrête : **les villosités repoussent**, la surface d'absorption se reconstitue, la diarrhée et les carences disparaissent et la croissance peut reprendre. Le régime doit être suivi à vie, car le gluten déclencherait à nouveau la réaction."}$exo$::jsonb),
  ('21d4364c-64de-57ed-a542-ada4fd8596ae'::uuid, 1, 'redaction', $exo${"titre":"Le trajet du sang dans le cœur","consigne":"Réponds à chaque question avec le vocabulaire du cours.","enonce":"1. Décris le trajet de la circulation **pulmonaire** puis celui de la circulation **systémique**.\n2. Nomme les quatre valves du cœur en précisant leur position. Quel est leur rôle ?\n3. Pourquoi la paroi du ventricule gauche est-elle plus épaisse que celle du ventricule droit ?","bareme":[{"critere":"Trajets pulmonaire et systémique complets et dans l'ordre","points":8},{"critere":"Tricuspide, mitrale, pulmonaire, aortique bien placées ; sens unique","points":7},{"critere":"Ventricule gauche qui propulse le sang dans tout l'organisme","points":5}],"dureeMin":8,"corrige":"1. Circulation **pulmonaire** (petite) : **ventricule droit → artère pulmonaire → poumons → veines pulmonaires → oreillette gauche**. Circulation **systémique** (grande) : **ventricule gauche → aorte → organes → veines caves → oreillette droite**.\n2. Entre oreillettes et ventricules, les valves **auriculo-ventriculaires** : **tricuspide** à droite, **mitrale** à gauche. À la sortie des ventricules, les valves **sigmoïdes** : **pulmonaire** (sortie du ventricule droit) et **aortique** (sortie du ventricule gauche). Elles imposent au sang un **sens unique**.\n3. Le ventricule gauche envoie le sang dans l'aorte, vers **tout l'organisme** : il doit le propulser plus loin et plus fort que le ventricule droit, qui n'envoie le sang qu'aux poumons."}$exo$::jsonb),
  ('21d4364c-64de-57ed-a542-ada4fd8596ae'::uuid, 2, 'redaction', $exo${"titre":"Le cœur d'Inès au repos et à l'effort","consigne":"Détaille chaque calcul avec son unité, puis interprète.","enonce":"**Document – Mesures réalisées par échographie sur Inès, 17 ans**\n\n| | Au repos | Pendant un effort |\n| Volume du ventricule gauche en fin de diastole | 125 mL | 140 mL |\n| Volume du ventricule gauche en fin de systole | 55 mL | 40 mL |\n| Fréquence cardiaque | 72 battements/min | 150 battements/min |\n\n1. Calcule le volume d'éjection systolique (VES) d'Inès au repos et pendant l'effort.\n2. Calcule son débit cardiaque au repos et pendant l'effort, en L/min. Par combien est-il environ multiplié ?\n3. Au repos, calcule la durée d'un cycle cardiaque, arrondie au centième de seconde.\n4. Pendant l'éjection ventriculaire, dans quel état sont les valves auriculo-ventriculaires et les valves sigmoïdes ? Justifie.","bareme":[{"critere":"VES de 70 mL au repos et 100 mL à l'effort, formule écrite","points":5},{"critere":"DC ≈ 5,04 L/min et 15 L/min, multiplié par environ 3","points":6},{"critere":"Durée d'un cycle ≈ 0,83 s","points":4},{"critere":"Valves auriculo-ventriculaires fermées, sigmoïdes ouvertes, justifié","points":5}],"dureeMin":12,"corrige":"1. VES = volume en fin de diastole − volume en fin de systole. Repos : 125 − 55 = **70 mL**. Effort : 140 − 40 = **100 mL**.\n2. DC = fC × VES. Repos : 72 × 70 = 5 040 mL/min = **5,04 L/min**. Effort : 150 × 100 = 15 000 mL/min = **15 L/min**. 15 / 5,04 ≈ 2,98 : le débit est multiplié par **environ 3**, grâce à la hausse de la fréquence et du VES.\n3. Durée d'un cycle = 60 / fC = 60 / 72 ≈ **0,83 s**.\n4. Pendant l'éjection, les ventricules se contractent : les valves **auriculo-ventriculaires sont fermées** (le sang ne revient pas dans les oreillettes) et les valves **sigmoïdes sont ouvertes** (le sang part dans l'aorte et l'artère pulmonaire)."}$exo$::jsonb),
  ('21d4364c-64de-57ed-a542-ada4fd8596ae'::uuid, 3, 'redaction', $exo${"titre":"Un cœur qui bat tout seul","consigne":"Exploite les documents et le cours ; justifie chaque réponse.","enonce":"**Document 1 – Une observation**\n\n> Un cœur prélevé, privé de toute connexion nerveuse et placé dans un liquide nutritif oxygéné, continue de battre régulièrement pendant plusieurs heures.\n\n**Document 2 – Le cycle cardiaque d'un adulte au repos**\n\n> Un cycle dure 0,8 s et comprend trois phases. Le VES mesuré est de 70 mL.\n\n1. Que montre le document 1 ? Où naît l'activité électrique du cœur ?\n2. Décris, dans l'ordre, le trajet de l'excitation dans le tissu nodal et le rôle de chaque élément.\n3. Pourquoi est-il utile que l'influx soit retardé entre les oreillettes et les ventricules ?\n4. Recopie et complète le tableau :\n\n| Phase | Cavités contractées | Valves auriculo-ventriculaires | Valves sigmoïdes |\n| Systole auriculaire | … | … | … |\n| Systole ventriculaire (éjection) | … | … | … |\n| Diastole | … | … | … |\n\n5. À partir du document 2, calcule la fréquence cardiaque puis le débit cardiaque en L/min.","bareme":[{"critere":"Automatisme cardiaque ; activité née dans le tissu nodal","points":3},{"critere":"Nœud sinusal → oreillettes → nœud atrio-ventriculaire → faisceau de His → réseau de Purkinje, avec les rôles","points":5},{"critere":"Retard qui laisse aux ventricules le temps de se remplir","points":3},{"critere":"Tableau des trois phases juste","points":5},{"critere":"fC = 75 battements/min et DC = 5,25 L/min","points":4}],"dureeMin":18,"corrige":"1. Privé de nerfs, le cœur continue de battre : il est **automatique**. Son activité électrique naît dans le cœur lui-même, dans le **tissu nodal**.\n2. **Nœud sinusal** (dans l'oreillette droite) : **pacemaker**, il donne le rythme, environ 70 à 80 par minute au repos → l'excitation parcourt les **oreillettes** → **nœud atrio-ventriculaire** : il retarde légèrement l'influx → **faisceau de His** puis **réseau de Purkinje** : ils distribuent l'excitation à tout le myocarde ventriculaire.\n3. Le retard au nœud atrio-ventriculaire laisse aux oreillettes le temps d'achever le **remplissage des ventricules** avant que ceux-ci se contractent.\n4. Tableau :\n- **Systole auriculaire** : oreillettes contractées ; valves auriculo-ventriculaires **ouvertes** ; sigmoïdes **fermées**.\n- **Systole ventriculaire** : ventricules contractés ; auriculo-ventriculaires **fermées** ; sigmoïdes **ouvertes** pendant l'éjection.\n- **Diastole** : aucune cavité contractée, le cœur se relâche ; auriculo-ventriculaires **ouvertes** (les ventricules se remplissent) ; sigmoïdes **fermées**.\n5. fC = 60 / 0,8 = **75 battements/min**. DC = fC × VES = 75 × 70 = 5 250 mL/min = **5,25 L/min**."}$exo$::jsonb),
  ('a977969e-015e-5879-b7e1-c0db9cd65ff3'::uuid, 1, 'redaction', $exo${"titre":"Artères, veines, capillaires et tension","consigne":"Réponds à chaque question avec le vocabulaire du cours.","enonce":"1. Compare la paroi et la fonction des artères, des veines et des capillaires.\n2. Que représentent les deux valeurs d'une mesure de tension artérielle ?\n3. Interprète ces trois mesures, chacune obtenue au repos à plusieurs reprises : **A** : 12/8 cmHg ; **B** : 16/10 cmHg ; **C** : 8,5/6 cmHg.","bareme":[{"critere":"Comparaison juste des trois vaisseaux (paroi et fonction)","points":9},{"critere":"Systolique (maximale, éjection) et diastolique (minimale)","points":4},{"critere":"A normale, B hypertension, C hypotension, justifiées par les seuils","points":7}],"dureeMin":8,"corrige":"1. **Artère** : trois tuniques (intima, **média épaisse** élastique et musculaire, adventice) ; elle conduit le sang **sous forte pression** depuis le cœur, et son élasticité amortit les à-coups. **Veine** : mêmes tuniques mais **paroi mince**, lumière large, **valvules** anti-reflux ; elle ramène le sang **à basse pression** vers le cœur. **Capillaire** : un seul **endothélium** sur une lame basale ; paroi très fine qui permet les **échanges** entre le sang et les tissus.\n2. La première valeur est la pression **systolique** (maximale, pendant l'éjection) ; la seconde est la pression **diastolique** (minimale).\n3. **A** (12/8 cmHg, soit 120/80 mmHg) : tension **normale**. **B** (16/10 cmHg) : supérieure à 14/9 de façon répétée : **hypertension artérielle**. **C** : systolique de 8,5 cmHg, inférieure à 9 cmHg : **hypotension**."}$exo$::jsonb),
  ('a977969e-015e-5879-b7e1-c0db9cd65ff3'::uuid, 2, 'redaction', $exo${"titre":"Lire un ECG et choisir un examen","consigne":"Détaille tes calculs, puis justifie chaque choix par le principe de la technique.","enonce":"**Document 1 – Deux électrocardiogrammes**\n\n> Sur l'ECG de Paul, deux pics R successifs sont séparés de **0,80 s**. Sur celui de Julie, de **0,50 s**.\n\n**Document 2 – Trois questions du cardiologue**\n\n> a) Le sang circule-t-il vite dans l'artère carotide de M. Faure ? Y a-t-il un rétrécissement ?\n>\n> b) Une artère coronaire de Mme Blanc est-elle bouchée ?\n>\n> c) Une zone du myocarde de M. Simon est-elle mal irriguée ?\n\n1. Que représentent l'onde P, le complexe QRS et l'onde T d'un ECG ?\n2. Calcule la fréquence cardiaque de Paul et celle de Julie.\n3. Pour chaque question du document 2, choisis entre Doppler, angiographie et scintigraphie. Explique le principe de la technique choisie.","bareme":[{"critere":"P : dépolarisation des oreillettes ; QRS : des ventricules ; T : repolarisation des ventricules","points":6},{"critere":"fC de Paul 75 et de Julie 120 battements/min, formule écrite","points":5},{"critere":"Doppler (a), angiographie (b), scintigraphie (c)","points":3},{"critere":"Principe de chaque technique expliqué","points":6}],"dureeMin":12,"corrige":"1. L'**onde P** correspond à la **dépolarisation des oreillettes** ; le **complexe QRS** à la **dépolarisation des ventricules** ; l'**onde T** à la **repolarisation des ventricules**.\n2. fC = 60 / durée d'un cycle (entre deux pics R). Paul : 60 / 0,80 = **75 battements/min**. Julie : 60 / 0,50 = **120 battements/min**.\n3. a) **Doppler** : la fréquence des ultrasons réfléchis par les globules en mouvement change ; on mesure la **vitesse du sang** et on repère un **rétrécissement**.\nb) **Angiographie** (ici coronarographie) : un **produit de contraste iodé** injecté rend les vaisseaux visibles aux **rayons X** ; on voit si l'artère est bouchée.\nc) **Scintigraphie** : un **traceur radioactif** injecté se fixe sur les tissus irrigués et une **gamma-caméra** le détecte ; une zone du myocarde qui fixe peu le traceur est mal irriguée."}$exo$::jsonb),
  ('a977969e-015e-5879-b7e1-c0db9cd65ff3'::uuid, 3, 'redaction', $exo${"titre":"Après l'hémorragie de Marc","consigne":"Exploite le document et construis l'explication complète de la régulation. Chaque idée s'appuie sur une donnée.","enonce":"**Document – Suivi de Marc, 25 ans, blessé dans un accident et qui perd du sang**\n\n| Moment | Pression artérielle | Fréquence cardiaque |\n| Avant l'accident (visite récente) | 12/8 cmHg | 70 battements/min |\n| 10 minutes après la blessure | 10,5/7 cmHg | 110 battements/min |\n| 30 minutes après la blessure | 9,5/6 cmHg | 125 battements/min |\n\nLes infirmiers notent aussi que sa peau est pâle et froide, signe que ses petits vaisseaux se sont resserrés.\n\n1. Décris l'évolution de la pression artérielle et de la fréquence cardiaque de Marc.\n2. Présente les cinq éléments de l'arc réflexe qui régule la pression artérielle, avec leur localisation.\n3. Explique, étape par étape, pourquoi le cœur de Marc s'accélère et ses vaisseaux se resserrent. Quel est le résultat attendu ?\n4. Calcule l'intervalle entre deux pics R de son ECG 30 minutes après la blessure. Nomme l'accélération du cœur et le resserrement des vaisseaux.","bareme":[{"critere":"Description chiffrée : pression qui baisse de 12/8 à 9,5/6, fC qui monte de 70 à 125","points":4},{"critere":"Barorécepteurs (sinus carotidien, crosse de l'aorte), voies afférentes, bulbe rachidien, voies efférentes, effecteurs","points":5},{"critere":"Mécanisme : moins d'étirement, moins de messages, parasympathique diminué, sympathique augmenté, pression qui remonte","points":7},{"critere":"R–R = 0,48 s ; tachycardie et vasoconstriction","points":4}],"dureeMin":18,"corrige":"1. La pression artérielle de Marc **baisse** : 12/8 cmHg avant l'accident, 10,5/7 à 10 minutes, 9,5/6 à 30 minutes. Dans le même temps, sa fréquence cardiaque **augmente** : 70, puis 110, puis 125 battements/min.\n2. Arc réflexe :\n- **récepteurs** : les **barorécepteurs**, sensibles à l'étirement de la paroi, dans le **sinus carotidien** et la **crosse de l'aorte** ;\n- **voies afférentes** (sensitives) : nerfs qui partent des barorécepteurs ;\n- **centre nerveux** : le **bulbe rachidien** (tronc cérébral) ;\n- **voies efférentes** (motrices) : le **nerf parasympathique** (nerf vague), qui ralentit le cœur, et les **nerfs sympathiques**, qui l'accélèrent et contractent les vaisseaux ;\n- **effecteurs** : le **cœur** (nœud sinusal) et les **vaisseaux**.\n3. La perte de sang fait **baisser la pression** → la paroi des artères est **moins étirée** → les barorécepteurs envoient **moins de messages** au bulbe → le bulbe **diminue l'action du parasympathique** et **augmente celle du sympathique** → le cœur **s'accélère** (70 → 125 battements/min) et les vaisseaux **se resserrent** (peau pâle et froide). Résultat attendu : la **pression remonte**.\n4. R–R = 60 / fC = 60 / 125 = **0,48 s**. L'accélération du cœur est une **tachycardie** ; le resserrement des vaisseaux est une **vasoconstriction**."}$exo$::jsonb),
  ('0ce74df7-e927-56b1-9d3d-ffba7a0edbdc'::uuid, 1, 'redaction', $exo${"titre":"Comment se forme une plaque d'athérome","consigne":"Réponds à chaque question avec le vocabulaire du cours.","enonce":"1. Décris, en cinq étapes et dans l'ordre, la formation d'une plaque d'athérome jusqu'à ses complications.\n2. Définis : sténose, ischémie, nécrose, thrombose, embolie.","bareme":[{"critere":"Cinq étapes dans l'ordre : LDL dans l'intima, cellules spumeuses, plaque et chape fibreuse, sténose, rupture et caillot","points":10},{"critere":"Cinq définitions exactes","points":10}],"dureeMin":8,"corrige":"1. Étapes :\n1) le **LDL-cholestérol** en excès pénètre dans l'**intima** d'une artère et s'y oxyde ;\n2) des globules blancs (monocytes devenus macrophages) l'absorbent et se gorgent de lipides : ce sont les **cellules spumeuses**, qui forment une **strie lipidique** ;\n3) des cellules musculaires et des fibres s'accumulent : la lésion devient une **plaque d'athérome**, recouverte d'une **chape fibreuse** ;\n4) la plaque grossit et rétrécit la lumière de l'artère : c'est une **sténose** ;\n5) la plaque peut se **rompre** : un **caillot** se forme et peut boucher l'artère (thrombose) ou se détacher (embolie).\n2. **Sténose** : rétrécissement de la lumière d'un vaisseau. **Ischémie** : apport insuffisant de sang et de dioxygène à un organe. **Nécrose** : mort de cellules ou d'un tissu. **Thrombose** : obstruction d'une artère par un caillot formé sur place. **Embolie** : obstruction d'un vaisseau par un caillot venu d'ailleurs, qui s'est détaché."}$exo$::jsonb),
  ('0ce74df7-e927-56b1-9d3d-ffba7a0edbdc'::uuid, 2, 'redaction', $exo${"titre":"Deux douleurs dans la poitrine","consigne":"Compare les deux dossiers et justifie ton diagnostic par des données.","enonce":"**Document – Deux patients**\n\n> **M. Faure**, 60 ans : douleur en étau dans la poitrine, qui irradie dans le bras gauche, quand il monte les escaliers. Elle disparaît en trois minutes quand il s'arrête. ECG au repos : normal. Troponine : normale.\n>\n> **M. Diallo**, 57 ans : même douleur, mais très intense, survenue au repos et qui dure depuis 45 minutes. La trinitrine ne la soulage pas. ECG : sus-décalage du segment ST. Troponine : élevée.\n\n1. Pose le diagnostic de chaque patient et justifie par trois données au moins.\n2. Explique la différence de mécanisme entre les deux maladies. Nomme les artères concernées.\n3. Pourquoi la troponine est-elle élevée chez M. Diallo seulement ?\n4. Que faut-il faire pour M. Diallo ? Décris un traitement qui rouvre l'artère.","bareme":[{"critere":"Angor pour M. Faure et infarctus pour M. Diallo, justifiés par trois données chacun","points":7},{"critere":"Sténose et ischémie transitoire / occlusion par un caillot et nécrose ; artères coronaires","points":5},{"critere":"Troponine libérée par les cellules nécrosées","points":3},{"critere":"Appel du 15 en urgence ; angioplastie avec stent ou thrombolyse","points":5}],"dureeMin":12,"corrige":"1. **M. Faure : angor** (angine de poitrine) — la douleur survient **à l'effort** (escaliers), **cède au repos** en quelques minutes, l'**ECG au repos est normal** et la **troponine normale**.\n**M. Diallo : infarctus du myocarde** — douleur **intense, prolongée** (45 minutes, plus de 20 minutes), **au repos**, qui **ne cède pas à la trinitrine**, **sus-décalage du segment ST** à l'ECG et **troponine élevée**.\n2. Les deux maladies touchent les **artères coronaires**, qui nourrissent le cœur. Dans l'angor, une **sténose** provoque une **ischémie transitoire**, quand le besoin en O₂ augmente (effort). Dans l'infarctus, un **caillot** provoque une **occlusion complète** : l'ischémie dure, puis les cellules du myocarde meurent : **nécrose**.\n3. La troponine est **libérée par les cellules du myocarde nécrosées**. Chez M. Faure, l'ischémie est transitoire, sans nécrose : la troponine reste normale.\n4. **Appeler le 15** immédiatement : chaque minute compte, car le muscle nécrosé ne se régénère pas. Il faut **rouvrir l'artère** au plus vite : **angioplastie** (un ballonnet écrase la plaque et on pose un **stent**, petit ressort qui maintient l'artère ouverte) ou **thrombolyse** (médicament qui dissout le caillot) ; puis antiagrégants plaquettaires et contrôle des facteurs de risque."}$exo$::jsonb),
  ('0ce74df7-e927-56b1-9d3d-ffba7a0edbdc'::uuid, 3, 'redaction', $exo${"titre":"Le cœur de M. Lambert","consigne":"Exploite les trois documents pour construire un raisonnement physiopathologique complet.","enonce":"**Document 1 – Le profil de M. Lambert, 58 ans**\n\n> Il fume 20 cigarettes par jour depuis 30 ans, a une hypertension artérielle et un excès de LDL-cholestérol. Il travaille assis et ne fait pas de sport. Son père a eu un infarctus à 55 ans.\n\n**Document 2 – Dosage de la troponine après le début d'une douleur thoracique**\n\n| Temps après le début de la douleur | 0 h | 3 h | 6 h |\n| Troponine (µg/L) | 0,01 | 1,2 | 2,5 |\n\nValeur de référence du laboratoire : inférieure à 0,04 µg/L.\n\n**Document 3 – Coronarographie.** Une artère coronaire est complètement bouchée par un caillot formé sur une plaque d'athérome rompue.\n\n1. Classe les facteurs de risque de M. Lambert en modifiables et non modifiables.\n2. Analyse le document 2 : décris, compare à la référence, interprète, conclus.\n3. Explique l'enchaînement qui mène de l'excès de LDL-cholestérol à l'infarctus du document 3.\n4. Quel traitement peut rouvrir l'artère ? Explique son principe.\n5. Propose à M. Lambert quatre mesures de prévention, chacune reliée à l'un de ses facteurs de risque.","bareme":[{"critere":"Modifiables : tabac, HTA, LDL, sédentarité ; non modifiables : âge, sexe masculin, hérédité","points":4},{"critere":"Troponine qui passe de 0,01 à 2,5 µg/L en 6 h, bien au-dessus de 0,04 : nécrose du myocarde","points":4},{"critere":"Chaîne LDL → cellules spumeuses → plaque → rupture → caillot → occlusion → ischémie → nécrose","points":5},{"critere":"Angioplastie avec stent (ou thrombolyse) expliquée","points":3},{"critere":"Quatre mesures de prévention reliées aux facteurs de risque","points":4}],"dureeMin":20,"corrige":"1. **Modifiables** : **tabac**, **hypertension artérielle**, **excès de LDL-cholestérol**, **sédentarité**. **Non modifiables** : **âge** (58 ans), **sexe masculin**, **hérédité** (père victime d'un infarctus).\n2. Au début de la douleur, la troponine est de **0,01 µg/L**, sous la valeur de référence (0,04 µg/L). Elle monte à **1,2 µg/L à 3 h** puis **2,5 µg/L à 6 h**, soit plus de 60 fois la valeur de référence. La troponine est libérée par les **cellules du myocarde nécrosées** : sa hausse montre qu'une partie du muscle cardiaque est en train de mourir. Conclusion : M. Lambert fait un **infarctus du myocarde**.\n3. Le **LDL-cholestérol** en excès pénètre dans l'intima de la coronaire et s'oxyde ; des macrophages l'absorbent et deviennent des **cellules spumeuses** ; la lésion devient une **plaque d'athérome** à chape fibreuse, qui rétrécit l'artère (**sténose**). La plaque se **rompt** : un **caillot** se forme et **bouche complètement** l'artère (document 3). Le myocarde situé en aval est privé de dioxygène (**ischémie** durable), puis ses cellules meurent : **nécrose** = infarctus.\n4. L'**angioplastie** : un ballonnet introduit dans l'artère écrase la plaque, puis on pose un **stent**, petit ressort qui maintient l'artère ouverte. (La **thrombolyse**, médicament qui dissout le caillot, est une autre possibilité.)\n5. Prévention : **arrêter de fumer** (tabac) ; **bouger au moins 30 minutes par jour** (sédentarité) ; **manger équilibré**, avec fruits, légumes, poissons, huiles végétales et moins de graisses saturées (LDL-cholestérol) ; **surveiller sa tension** (hypertension), ainsi que sa glycémie et son cholestérol."}$exo$::jsonb),
  ('80f01940-fb6e-5480-adf0-622d44c0886d'::uuid, 1, 'redaction', $exo${"titre":"Le chemin de l'air","consigne":"Réponds à chaque question avec le vocabulaire du cours.","enonce":"1. Donne, dans l'ordre, les voies que l'air traverse des fosses nasales jusqu'aux alvéoles.\n2. Compare la paroi de la trachée, des bronchioles et des alvéoles, et relie chacune à son rôle.\n3. Quels éléments forment la barrière alvéolo-capillaire ? Pourquoi est-elle idéale pour la diffusion ?","bareme":[{"critere":"Ordre juste : fosses nasales, pharynx, larynx, trachée, bronches, bronchioles, alvéoles","points":5},{"critere":"Parois comparées et reliées à leur rôle (cartilage et cils, muscle lisse, paroi fine)","points":9},{"critere":"Épithélium alvéolaire, lame basale, endothélium ; finesse (≈ 0,5 µm) et grande surface (≈ 100 m²)","points":6}],"dureeMin":8,"corrige":"1. **Fosses nasales → pharynx → larynx → trachée → bronches → bronchioles → alvéoles.**\n2. **Trachée** (et bronches) : anneaux de **cartilage** (en C) qui la maintiennent **ouverte**, épithélium **cilié** avec des cellules à **mucus** : le mucus piège les particules, les cils les remontent vers la gorge. **Bronchioles** : **pas de cartilage** mais du **muscle lisse**, qui règle le passage de l'air (elles se contractent dans l'asthme). **Alvéoles** : paroi **très fine**, entourée de capillaires : **échanges gazeux**.\n3. La barrière comprend l'**épithélium alvéolaire**, une **lame basale** commune et l'**endothélium** du capillaire. Elle est très **fine** (environ 0,5 µm) et très **étendue** (près de 100 m²) : elle est idéale pour la **diffusion** des gaz."}$exo$::jsonb),
  ('80f01940-fb6e-5480-adf0-622d44c0886d'::uuid, 2, 'redaction', $exo${"titre":"Les gaz de part et d'autre de l'alvéole","consigne":"Exploite le document : cite des valeurs, puis explique avec le cours.","enonce":"**Document – Pressions partielles mesurées dans les poumons**\n\n| | Pression partielle d'O₂ | Pression partielle de CO₂ |\n| Air alvéolaire | ≈ 100 mmHg | ≈ 40 mmHg |\n| Sang qui arrive aux poumons | ≈ 40 mmHg | ≈ 46 mmHg |\n\n1. Énonce la règle qui fixe le sens de diffusion d'un gaz, puis déduis-en le sens des échanges d'O₂ et de CO₂ dans les poumons.\n2. Dans les tissus, dans quel sens passent l'O₂ et le CO₂ ? Explique pourquoi.\n3. 100 mL de sang artériel transportent 20 mL de dioxygène. Calcule le volume transporté fixé à l'hémoglobine et le volume dissous, avec les pourcentages du cours.\n4. Écris l'équation de la respiration cellulaire et nomme l'organite où elle se déroule.","bareme":[{"critere":"Diffusion de la pression partielle la plus forte vers la plus faible ; O₂ air → sang, CO₂ sang → air, avec les valeurs","points":6},{"critere":"Tissus : O₂ du sang aux cellules qui le consomment, CO₂ des cellules qui le produisent au sang","points":4},{"critere":"19,6 mL fixés à l'hémoglobine et 0,4 mL dissous","points":5},{"critere":"Équation juste et mitochondrie","points":5}],"dureeMin":12,"corrige":"1. Un gaz diffuse du milieu où sa **pression partielle est la plus forte** vers celui où elle est **la plus faible**. **O₂** : 100 mmHg dans l'air alvéolaire contre 40 mmHg dans le sang → l'O₂ passe **de l'air alvéolaire au sang**. **CO₂** : 46 mmHg dans le sang contre 40 mmHg dans l'air → le CO₂ passe **du sang à l'air alvéolaire**.\n2. Dans les tissus, les cellules **consomment l'O₂** : sa pression partielle y est faible, l'O₂ passe **du sang aux cellules**. Elles **produisent du CO₂** : il passe **des cellules au sang**.\n3. Environ 98 % de l'O₂ est fixé à l'hémoglobine : 20 × 0,98 = **19,6 mL**. Environ 2 % est dissous : 20 × 0,02 = **0,4 mL**.\n4. **C₆H₁₂O₆ + 6 O₂ → 6 CO₂ + 6 H₂O + énergie** (sous forme d'ATP). Elle se déroule dans les **mitochondries**."}$exo$::jsonb),
  ('80f01940-fb6e-5480-adf0-622d44c0886d'::uuid, 3, 'redaction', $exo${"titre":"L'hémoglobine au service du muscle qui travaille","consigne":"Exploite le document, calcule, puis explique avec le cours. Chaque idée s'appuie sur une donnée.","enonce":"**Document – Saturation de l'hémoglobine en O₂** (valeurs simplifiées)\n\n| Lieu | Pression partielle d'O₂ | Conditions | Saturation de l'hémoglobine |\n| Capillaires pulmonaires | 100 mmHg | pH 7,4 ; 37 °C | 98 % |\n| Muscle au repos | 40 mmHg | pH 7,4 ; 37 °C | 75 % |\n| Muscle en activité | 40 mmHg | pH 7,2 ; 39 °C ; CO₂ élevé | 60 % |\n\n1. Décris la structure de l'hémoglobine. Combien de molécules d'O₂ peut-elle transporter ? Pourquoi ?\n2. Calcule, en points de saturation, la part de l'hémoglobine qui libère son O₂ dans le muscle au repos, puis dans le muscle en activité.\n3. Compare les deux lignes du muscle : à même pression partielle d'O₂, qu'est-ce qui change ? Nomme et explique cet effet.\n4. Explique pourquoi un muscle en activité est acide, chaud et riche en CO₂, et en quoi cet effet lui est utile.\n5. Sous quelles formes le CO₂ produit par le muscle est-il transporté dans le sang ?","bareme":[{"critere":"Quatre chaînes (deux α, deux β), quatre hèmes à Fe²⁺ : quatre O₂","points":4},{"critere":"Calculs : 98 − 75 = 23 points au repos, 98 − 60 = 38 points en activité","points":4},{"critere":"Baisse du pH, hausse du CO₂ et de la température : affinité diminuée, courbe vers la droite (effet Bohr)","points":5},{"critere":"Respiration cellulaire intense qui produit CO₂ ; plus d'O₂ libéré là où il est utile","points":4},{"critere":"Hydrogénocarbonate ≈ 70 %, carbaminohémoglobine ≈ 20 %, dissous ≈ 10 %","points":3}],"dureeMin":18,"corrige":"1. L'hémoglobine est une protéine de **quatre chaînes** (deux α, deux β), portant chacune un **hème** avec un atome de **fer Fe²⁺**, sur lequel se fixe une molécule d'O₂. Elle transporte donc jusqu'à **quatre O₂**.\n2. Dans les poumons, l'hémoglobine est saturée à 98 %. Muscle au repos : 98 − 75 = **23 points** de saturation : environ un quart de l'hémoglobine libère son O₂. Muscle en activité : 98 − 60 = **38 points** : l'hémoglobine libère nettement plus d'O₂.\n3. La pression partielle d'O₂ est la même (40 mmHg), mais dans le muscle en activité le **pH baisse** (7,2), la **température monte** (39 °C) et le **CO₂ augmente**. La saturation passe de 75 % à 60 % : l'**affinité de l'hémoglobine pour l'O₂ diminue**, la courbe de saturation se déplace **vers la droite** : c'est l'**effet Bohr**.\n4. Le muscle en activité réalise une **respiration cellulaire** intense dans ses mitochondries : il **produit beaucoup de CO₂** (ce qui rend le milieu plus acide) et de l'énergie, dont une partie en chaleur. Ces conditions font **libérer davantage d'O₂** à l'hémoglobine, **là où il est le plus utile** : l'effet Bohr ajuste l'apport d'O₂ à l'activité.\n5. Le CO₂ est transporté à environ **70 % sous forme d'ions hydrogénocarbonate HCO₃⁻**, environ **20 % fixé à l'hémoglobine** (carbaminohémoglobine) et environ **10 % dissous**."}$exo$::jsonb),
  ('22aad1df-1f4d-53c7-8d43-3f7d86b4a815'::uuid, 1, 'redaction', $exo${"titre":"Lire un spirogramme","consigne":"Détaille tes calculs et réponds avec le vocabulaire du cours.","enonce":"**Document – Spirométrie d'Adrien, 20 ans**\n\n| Volume courant | Volume de réserve inspiratoire | Volume de réserve expiratoire | VEMS |\n| 0,5 L | 2,8 L | 1,2 L | 3,6 L |\n\n1. Définis le volume courant, le volume de réserve inspiratoire, le volume de réserve expiratoire et le VEMS.\n2. Calcule la capacité vitale d'Adrien.\n3. Calcule son rapport de Tiffeneau et interprète-le. Pourquoi le spiromètre simple ne donne-t-il pas le volume résiduel ?","bareme":[{"critere":"Quatre définitions exactes","points":8},{"critere":"CV = 0,5 + 2,8 + 1,2 = 4,5 L","points":5},{"critere":"Tiffeneau = 80 %, normal (au-dessus de 70 %) ; volume résiduel qui reste toujours dans les poumons","points":7}],"dureeMin":8,"corrige":"1. **Volume courant** : air mobilisé à chaque respiration calme. **Volume de réserve inspiratoire** : air inspiré en plus, en forçant. **Volume de réserve expiratoire** : air expiré en plus, en forçant. **VEMS** : volume expiré en une seconde lors d'une expiration forcée.\n2. CV = VC + VRI + VRE = 0,5 + 2,8 + 1,2 = **4,5 L**.\n3. Rapport de Tiffeneau = VEMS / CV = 3,6 / 4,5 = 0,80, soit **80 %**. Il est supérieur à environ 70 % : **pas de trouble ventilatoire obstructif**, la valeur est normale (le VEMS vaut environ 80 % de la CV). Le **volume résiduel** est l'air qui **reste toujours dans les poumons**, même après une expiration forcée : il ne sort jamais, le spiromètre ne peut donc pas le mesurer."}$exo$::jsonb),
  ('22aad1df-1f4d-53c7-8d43-3f7d86b4a815'::uuid, 2, 'redaction', $exo${"titre":"Les sifflements de Lina","consigne":"Calcule (résultats arrondis à l'unité en %), interprète, puis explique avec le cours.","enonce":"**Document – Dossier de Lina, 15 ans**\n\n> Lina se réveille souvent la nuit, gênée pour expirer, avec des sifflements et une toux. Les crises surviennent surtout au printemps, et son père est allergique.\n\n| Spirométrie | Capacité vitale | VEMS |\n| Avant bronchodilatateur | 3,8 L | 2,3 L |\n| 15 min après inhalation d'un bronchodilatateur | 3,8 L | 3,1 L |\n\n1. Calcule le rapport de Tiffeneau avant et après le bronchodilatateur. Interprète chaque résultat.\n2. Ces résultats confirment-ils un asthme ? Justifie par la caractéristique de l'obstruction.\n3. Explique les trois phénomènes qui rétrécissent les bronchioles lors d'une crise.\n4. Distingue le traitement de la crise et le traitement de fond, et propose une mesure de prévention adaptée à Lina.","bareme":[{"critere":"Tiffeneau ≈ 61 % (obstructif) puis ≈ 82 % (normal)","points":6},{"critere":"Obstruction réversible après bronchodilatateur : asthme","points":4},{"critere":"Bronchoconstriction, œdème, hypersécrétion de mucus","points":5},{"critere":"Bronchodilatateur de courte durée (crise), corticoïde inhalé (fond), éviction des allergènes","points":5}],"dureeMin":12,"corrige":"1. Avant : 2,3 / 3,8 ≈ 0,605, soit **≈ 61 %** : inférieur à 70 %, c'est un **trouble ventilatoire obstructif** (l'air a du mal à sortir, les bronches sont rétrécies). Après : 3,1 / 3,8 ≈ 0,816, soit **≈ 82 %** : supérieur à 70 %, la valeur est redevenue **normale**.\n2. Oui : l'obstruction est **réversible** après inhalation d'un bronchodilatateur, ce qui est le signe paraclinique de l'**asthme**. Les signes cliniques concordent : gêne **expiratoire**, **sifflements**, toux, souvent **la nuit**.\n3. Lors d'une crise : 1) la **contraction du muscle lisse** des bronchioles (**bronchoconstriction**) ; 2) l'**œdème** de la muqueuse enflammée ; 3) l'**hypersécrétion de mucus**. Les trois réduisent le diamètre des bronchioles.\n4. La **crise** se traite par un **bronchodilatateur de courte durée, inhalé**, qui relâche le muscle lisse. Le **traitement de fond** est un **corticoïde inhalé**, qui réduit l'inflammation. Prévention : les crises de Lina surviennent au printemps et son père est allergique : on suspecte les **pollens** ; il faut **éviter les allergènes** (et le tabac, y compris passif)."}$exo$::jsonb),
  ('22aad1df-1f4d-53c7-8d43-3f7d86b4a815'::uuid, 3, 'redaction', $exo${"titre":"Asthme ou BPCO ? Le souffle de M. Roche","consigne":"Exploite les documents, compare avec l'asthme et justifie chaque conclusion par une donnée chiffrée.","enonce":"**Document 1 – Dossier de M. Roche, 62 ans**\n\n> Il fume un paquet par jour depuis 40 ans. Il est essoufflé au moindre effort, tousse et crache tous les matins depuis des années.\n\n**Document 2 – Spirométrie** (résultats arrondis à l'unité en %)\n\n| | Capacité vitale | VEMS |\n| Avant bronchodilatateur | 3,5 L | 1,6 L |\n| Après bronchodilatateur | 3,5 L | 1,7 L |\n\n**Document 3 – Dosage.** Une partie de son hémoglobine est fixée au monoxyde de carbone.\n\n1. Calcule le rapport de Tiffeneau avant et après le bronchodilatateur, et interprète.\n2. Montre que M. Roche n'est pas asthmatique mais atteint de BPCO. Que signifie ce sigle ?\n3. Explique l'action des constituants de la fumée sur ses bronches et sur son sang (goudrons, irritants, monoxyde de carbone, nicotine).\n4. À quelles autres maladies le tabac l'expose-t-il ?\n5. M. Roche pense qu'à son âge, arrêter de fumer ne sert plus à rien. Réponds-lui avec deux arguments du cours.","bareme":[{"critere":"Tiffeneau ≈ 46 % puis ≈ 49 % : obstruction sévère qui persiste","points":5},{"critere":"Obstruction non réversible = BPCO, opposée à l'asthme réversible ; sigle expliqué","points":4},{"critere":"Goudrons (cils paralysés, cancérigènes), irritants (inflammation, mucus), CO sur l'hémoglobine, nicotine","points":6},{"critere":"Cancer broncho-pulmonaire et maladies cardio-vasculaires","points":2},{"critere":"Bénéfice à tout âge : CO éliminé en quelques jours, risque d'infarctus qui baisse dès la première année","points":3}],"dureeMin":20,"corrige":"1. Avant : 1,6 / 3,5 ≈ 0,457, soit **≈ 46 %**. Après : 1,7 / 3,5 ≈ 0,486, soit **≈ 49 %**. Les deux valeurs sont bien **inférieures à 70 %** : M. Roche a un **trouble ventilatoire obstructif**, qui persiste après le bronchodilatateur.\n2. Dans l'asthme, l'obstruction est **réversible** après bronchodilatateur (le rapport redevient normal). Ici, il ne gagne que 3 points et reste à 49 % : l'obstruction **n'est pas réversible**. Avec un tabagisme de 40 ans, c'est une **BPCO** : **bronchopneumopathie chronique obstructive**.\n3. Les **goudrons** **paralysent les cils** : le mucus et les particules ne sont plus remontés vers la gorge ; ils sont aussi **cancérigènes**. Les **irritants** **enflamment les bronches** et **augmentent le mucus** (d'où la toux et les crachats du matin). Le **monoxyde de carbone** se fixe sur l'hémoglobine **plus de 200 fois plus fortement** que le dioxygène : le sang **transporte moins d'O₂** (document 3), ce qui aggrave l'essoufflement. La **nicotine** crée la **dépendance**, accélère le cœur et resserre les vaisseaux.\n4. Le tabac l'expose au **cancer broncho-pulmonaire** (et d'autres cancers : gorge, vessie) et aux **maladies cardio-vasculaires** (infarctus, AVC, artériopathie).\n5. Arrêter est **bénéfique à tout âge** : le **CO disparaît du sang en quelques jours** (son sang transportera plus d'O₂) et le **risque d'infarctus baisse nettement dès la première année**."}$exo$::jsonb),
  ('fa02339a-503c-51d6-aef0-7311673a7fa8'::uuid, 1, 'redaction', $exo${"titre":"Décoder le vocabulaire médical","consigne":"Décompose chaque mot en racine, préfixe ou suffixe, puis donne son sens.","enonce":"1. Donne le sens des mots suivants en expliquant leur construction : gastrite, myalgie, cholécystectomie, glycémie, hémiplégie, dyspnée, hypotension, fibroscopie.\n2. Classe ces éléments en **signes cliniques** ou **signes paracliniques** : pâleur, hémoglobine basse au bilan sanguin, dyspnée, anomalie de l'ECG, douleur thoracique, rapport de Tiffeneau à 60 %.","bareme":[{"critere":"Huit mots décomposés et expliqués correctement","points":12},{"critere":"Six éléments bien classés en cliniques / paracliniques","points":8}],"dureeMin":8,"corrige":"1. **Gastrite** : gastr(o) = estomac + -ite = inflammation → inflammation de l'estomac. **Myalgie** : my(o) = muscle + -algie = douleur → douleur musculaire. **Cholécystectomie** : cholécyst(o) = vésicule biliaire + -ectomie = ablation → ablation de la vésicule biliaire. **Glycémie** : glyc = sucre (glucose) + -émie = présence dans le sang → taux de glucose dans le sang. **Hémiplégie** : hémi = moitié + -plégie = paralysie → paralysie d'une moitié du corps. **Dyspnée** : dys- = difficulté + -pnée = respiration → difficulté à respirer. **Hypotension** : hypo- = insuffisance → tension artérielle trop basse. **Fibroscopie** : -scopie = examen visuel → examen de l'intérieur d'un organe avec un tube souple muni d'une caméra.\n2. **Signes cliniques** (examen du patient, ce qu'il ressent et montre) : pâleur, dyspnée, douleur thoracique. **Signes paracliniques** (examens complémentaires) : hémoglobine basse au bilan sanguin, anomalie de l'ECG, rapport de Tiffeneau à 60 % (spirométrie)."}$exo$::jsonb),
  ('fa02339a-503c-51d6-aef0-7311673a7fa8'::uuid, 2, 'redaction', $exo${"titre":"Analyser un document en cinq étapes","consigne":"Applique la méthode d'analyse de document du cours : chaque idée s'appuie sur une donnée chiffrée et une explication.","enonce":"**Document – Évolution de la troponine sanguine chez Mme Guérin, 66 ans, arrivée aux urgences pour une douleur thoracique**\n\n| Temps après l'arrivée (h) | 0 | 2 | 4 | 6 |\n| Troponine (µg/L) | 0,01 | 0,8 | 1,9 | 2,5 |\n\nValeur de référence du laboratoire : inférieure à 0,04 µg/L. La troponine est une protéine libérée dans le sang par les cellules du myocarde qui meurent.\n\n**Question :** le myocarde de Mme Guérin est-il en train de se nécroser ?\n\n1. Présente le document : ce qu'il montre, la grandeur mesurée et son unité.\n2. Décris l'évolution de la troponine en citant des valeurs précises.\n3. Compare les valeurs à la référence.\n4. Interprète ces résultats à l'aide des informations données et conclus en répondant à la question posée.","bareme":[{"critere":"Présentation : titre, grandeur (troponine), unité (µg/L), durée","points":3},{"critere":"Description chiffrée : de 0,01 à 2,5 µg/L en 6 h, hausse continue","points":6},{"critere":"Comparaison : normale à l'arrivée, au-dessus de 0,04 µg/L dès 2 h","points":5},{"critere":"Interprétation (libération par les cellules qui meurent) et conclusion qui répond à la question","points":6}],"dureeMin":12,"corrige":"1. Le document montre l'**évolution de la troponine sanguine** de Mme Guérin pendant les **6 heures** qui suivent son arrivée aux urgences ; la troponine est exprimée en **µg/L**.\n2. À l'arrivée, la troponine est de **0,01 µg/L**. Elle **augmente sans cesse** : **0,8 µg/L à 2 h**, **1,9 µg/L à 4 h**, **2,5 µg/L à 6 h**.\n3. À l'arrivée, la valeur est **normale** (0,01, inférieure à 0,04 µg/L). Dès 2 h, elle **dépasse nettement la référence** (0,8 µg/L, 20 fois la limite) ; à 6 h, elle atteint environ **60 fois** la limite (2,5 / 0,04 ≈ 62).\n4. La troponine est libérée par les cellules du myocarde qui meurent : son augmentation montre que des cellules du muscle cardiaque sont **en train de mourir**, et de plus en plus nombreuses. **Conclusion** : oui, le myocarde de Mme Guérin est en train de se **nécroser**."}$exo$::jsonb),
  ('fa02339a-503c-51d6-aef0-7311673a7fa8'::uuid, 3, 'redaction', $exo${"titre":"Le raisonnement complet : l'anémie de Sarah","consigne":"Organise ta réponse selon les étapes du raisonnement physiopathologique. Chaque étape s'appuie sur le dossier.","enonce":"**Document – Dossier de Sarah, 16 ans**\n\n> Sarah est fatiguée depuis trois mois, pâle, essoufflée en cours d'EPS ; son cœur s'accélère au moindre effort. Elle a des règles abondantes et mange très peu de viande, de poisson et de légumineuses.\n\n| Bilan sanguin | Résultat | Valeurs de référence du laboratoire |\n| Hémoglobine | 10 g/dL | 12 à 16 g/dL |\n| Ferritine | 5 µg/L | 15 à 150 µg/L |\n\n1. **Rappel physiologique** : quel est le rôle de l'hémoglobine et du fer ?\n2. Relève les **signes cliniques** et les **signes paracliniques**, en interprétant les seconds avec les valeurs de référence.\n3. Explique le **mécanisme** qui relie les signes entre eux.\n4. Relève les **facteurs de risque** et propose un **traitement** justifié par le mécanisme.\n5. Propose deux mesures de **prévention** reliées aux facteurs de risque.\n6. Explique la construction du mot **anémie**.","bareme":[{"critere":"Rappel : l'hémoglobine transporte l'O₂, le fer est indispensable à sa fabrication","points":3},{"critere":"Signes cliniques et paracliniques bien classés et interprétés avec des valeurs","points":4},{"critere":"Mécanisme : manque de fer → moins d'hémoglobine → moins d'O₂ transporté → signes","points":5},{"critere":"Facteurs de risque relevés ; traitement justifié (supplémentation, alimentation, cause)","points":4},{"critere":"Prévention reliée aux facteurs de risque ; anémie = an- + -émie","points":4}],"dureeMin":20,"corrige":"1. **Rappel** : l'**hémoglobine**, contenue dans les globules rouges, **transporte le dioxygène** vers les cellules. Le **fer** est **indispensable à sa fabrication**.\n2. **Signes cliniques** : fatigue, pâleur, essoufflement à l'effort, accélération du cœur. **Signes paracliniques** : **hémoglobine basse** (10 g/dL, sous 12 g/dL) : c'est une **anémie** ; **ferritine basse** (5 µg/L, sous 15 µg/L) : les **réserves de fer sont vides**.\n3. **Mécanisme** : apports de fer insuffisants et pertes (règles) → **réserves de fer vides** → **moins d'hémoglobine** fabriquée → le sang **transporte moins de dioxygène** → les muscles en manquent : **fatigue** et **essoufflement** à l'effort ; le cœur **s'accélère** pour compenser ; le sang pauvre en hémoglobine donne la **pâleur**.\n4. **Facteurs de risque** : règles abondantes, alimentation pauvre en fer, adolescence (croissance). **Traitement** : **supplémentation en fer** et **alimentation riche en fer**, qui reconstituent les réserves et permettent de refabriquer l'hémoglobine ; **rechercher et traiter la cause** (règles abondantes).\n5. **Prévention** : manger régulièrement des aliments riches en fer (viande, poisson, légumineuses) ; associer un aliment riche en **vitamine C** (agrume) aux repas, car elle favorise l'absorption du fer végétal ; faire surveiller les règles abondantes.\n6. **Anémie** : préfixe **an-** = absence + suffixe **-émie** = présence dans le sang → littéralement « manque de sang » : ici, un manque d'hémoglobine dans le sang."}$exo$::jsonb)
) AS v (chapter_id, difficulte, style, contenu)
JOIN public.chapters c ON c.id = v.chapter_id
ON CONFLICT (id) DO UPDATE
  SET style      = EXCLUDED.style,
      contenu    = EXCLUDED.contenu,
      difficulte = EXCLUDED.difficulte,
      origine    = 'catalogue';

DO $$
DECLARE
  n INT;
BEGIN
  SELECT count(*) INTO n
